        private static void Log(string line)
        {
            TmpDiag(line);
            try
            {
                File.AppendAllText(Path.Combine(Path.GetTempPath(), "autotest.log"),
                    DateTime.Now.ToString("HH:mm:ss.fff") + " " + line + Environment.NewLine);
            }
            catch { }
            GameLog.Write("autotest: " + line);
            lock (LogLock)
            {
                try
                {
                    var dir = FSO.Common.FSOEnvironment.UserDir;
                    if (string.IsNullOrEmpty(dir)) dir = AppDomain.CurrentDomain.BaseDirectory;
                    Directory.CreateDirectory(dir);
                    File.AppendAllText(
                        Path.Combine(dir, "autotest.log"),
                        DateTime.Now.ToString("HH:mm:ss.fff") + " " + line + Environment.NewLine);
                }
                catch
                {
                }
            }
        }

        private static List<string> EnabledChecks()
        {
            return Config.Checks.Split(',').Select(s => s.Trim().ToLowerInvariant())
                .Where(s => s.Length > 0).ToList();
        }

        private static bool CheckEnabled(string name)
        {
            return EnabledChecks().Contains(name);
        }

        private static void TmpDiag(string message)
        {
            try
            {
                File.AppendAllText(Path.Combine(Path.GetTempPath(), "simitone_diag.log"),
                    DateTime.Now.ToString("HH:mm:ss.fff") + " autotest " + message + Environment.NewLine);
            }
            catch { }
        }

        public static void Begin(string housesCsv, string checksCsv, int timeoutMs, bool exitOnDone)
        {
            Config.Enabled = true;
            TmpDiag("Begin entered houses=" + (housesCsv ?? "null") + " userdir=" + (FSO.Common.FSOEnvironment.UserDir ?? "null"));
            var h = housesCsv?.Trim().Trim('"');
            if (!string.IsNullOrEmpty(h)) Config.HouseCandidates = h;
            var c = checksCsv?.Trim().Trim('"');
            if (!string.IsNullOrEmpty(c)) Config.Checks = c;
            // R246 'ucasflow': BEFORE Content.Init/TS1NeighbourProvider.InitSpecific
            // runs, redirect FSOEnvironment.UserDir into a fresh temp dir so the
            // pristine UserData clone and every CAS write land there (strong
            // isolation; game-data and ~/Documents/Simitone stay untouched).
            AutotestCASFlow.BeginIsolation(c);
            // R247 'uitutorial-lifecycle': same isolation idiom (additive; the
            // reset copy + import write files). Opt-in only — inert unless the
            // checks string names it.
            AutotestTutorialLifecycle247.BeginIsolation(c);
            // SAV-08 'savefault': same isolation idiom (the battery faults and
            // rewrites Neighborhood.iff / house / character copies in the
            // redirected UserDir). Opt-in only — inert unless the checks
            // string names it.
            AutotestSaveFault.BeginIsolation(c);
            // SAV-05 'impexport': same isolation idiom (the battery stages FAMs
            // into the redirected UserDir's UserData/Import and drives the
            // production import poll; game-data is SHA-pinned read-only).
            // Opt-in only — inert unless the checks string names it.
            AutotestImpexport.BeginIsolation(c);
            // SAV-07 'sav07live'/'sav07live2': same isolation idiom but with a
            // DETERMINISTIC isolation dir — run 1 resets it (fresh clone) and
            // run 2 mounts it as-is, so run 2 is a genuine fresh-process reload
            // of run 1's saved state. Opt-in only — inert unless named.
            AutotestSav07.BeginIsolation(c);
            // UI-21 'importui': same isolation idiom (the battery stages a FAM
            // copy into the redirected UserDir's UserData/Import and drives the
            // production import dialog + consumer; game-data is never written).
            // Opt-in only — inert unless the checks string names it.
            AutotestImportUI.BeginIsolation(c);
            // UI-30 'nghbtns': same isolation idiom, but the fresh dir is created
            // INSIDE the launcher's private (in-worktree) userdir — never /tmp —
            // so the neighborhood rematerializes from the pristine template and
            // the credits+bulldoze battery's mutations land in run-local space.
            // Opt-in only — inert unless the checks string names it.
            AutotestUI30.BeginIsolation(c);
            if (timeoutMs > 0) Config.TimeoutMs = timeoutMs;
            Config.ExitOnDone = exitOnDone;

            _houses = Config.HouseCandidates.Split(',').Select(s => s.Trim()).Where(s => s.Length > 0).ToArray();
            if (_houses.Length == 0) _houses = new[] { "auto" };
            _deadline = DateTime.UtcNow.AddMilliseconds(Config.TimeoutMs);
            _state = 0;
            _neighborhoodReadyFrames = 0;
            _neighborhoodSurveyCaptured = false;

            Log("AUTOTEST START houses=[" + string.Join(",", _houses) + "] checks=[" + Config.Checks + "] timeout=" + Config.TimeoutMs + "ms");
            GameThread.EveryUpdate(s => Tick());
            Log("AUTOTEST hook-registered");
        }

        private static void Tick()
        {
            if (_finished) return;
            try { Eng02Diag(); } catch { } // ENG-02 diagnostic; never gate-fatal
            if (DateTime.UtcNow > _deadline && _state > 0)
            {
                Log("AUTOTEST TIMEOUT state=" + _state + " -> FAIL");
                // REL-11: account the failure BEFORE evaluators run — they may Finish()
                // internally, and Finish must never print PASS for a timed-out run.
                _failed++;
                if (CheckEnabled("ghosttrace")) GhostTraceEvaluate("timeout");
                else if (CheckEnabled("deathrel")) DeathRelEvaluate("timeout");
                else if (CheckEnabled("deathtrace")) DeathTraceEvaluate("timeout");
                Finish();
                return;
            }
            try
            {
                switch (_state)
                {
                    case 0: StateWaitNeigh(); break;
                    case 1: StateWaitLot(); break;
                    case 2: StateSample(); break;
                    case 3: StateCarpool(); break;
                    case 4: StateDeathTrace(); break;
                    case 5: StateCameraCapture239(); break;
                    case 6: StatePIP240(); break;
                    case 7: StateCutaway244(); break;
                    case 8: StateCASFlow(); break;
                    case 9: StateTutorialLifecycle247(); break;
                    case 10: StateImpexport(); break;
                    case 11: StateSav07(); break;
                    case 12: StateImportUI(); break;
                    case 13: StateCutaway25(); break;
                    case 14: StateUI30(); break;
                    case 15: StateArchUndo(); break;
                }
            }
            catch (Exception e)
            {
                Log("AUTOTEST tick exception in state " + _state + ": " + e);
                _failed++;
                Finish();
            }
        }

        private static void StateWaitNeigh()
        {
            if (_screen == null)
                _screen = GameFacade.Screens?.CurrentUIScreen as TS1GameScreen;
            if (_screen == null || _screen.InLot) { _neighborhoodReadyFrames = 0; return; }
            // R246 'ucasflow' opt-in (additive): the real-flow CAS audit takes
            // over the run here — it drives the PRODUCTION MoveIn button into
            // GameController.EnterCAS() instead of the house-load pipeline, so
            // it must intercept before TryNextHouse. Only reachable when the
            // configured Checks string contains it (CheckEnabled reads
            // Config.Checks, which -autotest-opts replaces; the default string
            // never lists it, so the default suite is untouched). Both the
            // ucasflow and uicasflow spellings are accepted (run logs and the
            // verdict line use the canonical ucasflow check name).
            if (CheckEnabled("ucasflow") || CheckEnabled("uicasflow") || CheckEnabled("recordfmt"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST uicasflow neighborhood-screen ready; entering CAS flow");
                _casflow = new AutotestCASFlow(CasFlowLog);
                _state = 8;
                return;
            }
            // R247 'uitutorial-lifecycle' opt-in (additive): takes over the run
            // here exactly like ucasflow — the battery drives the production
            // options panel, import poll and lot loads itself. Only reachable
            // when the configured Checks string contains it (the default string
            // never lists it, so the default suite is untouched).
            if (CheckEnabled("uitutorial-lifecycle"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST uitutorial-lifecycle neighborhood-screen ready; entering lifecycle battery");
                _lifecycle247 = new AutotestTutorialLifecycle247(Log);
                _state = 9;
                return;
            }
            // SAV-05 'impexport' opt-in (additive): takes over at the neighborhood
            // screen like the lifecycle battery — the fixture drives the production
            // import poll itself. Only reachable when the configured Checks string
            // contains it (the default string never lists it).
            if (CheckEnabled("impexport"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST impexport neighborhood-screen ready; entering import battery");
                _impexport = new AutotestImpexport(Log);
                _state = 10;
                return;
            }
            // SAV-07 'sav07live'/'sav07live2' opt-in (additive): the live
            // export→import→save→fresh-load round-trip the impexport battery
            // excluded. Run 1 resets the deterministic isolation dir and does
            // export+import+save; run 2 remounts it in a fresh process.
            if (CheckEnabled("sav07live") || CheckEnabled("sav07live2"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST sav07 neighborhood-screen ready; entering round-trip probe (run2="
                    + CheckEnabled("sav07live2") + ")");
                _sav07 = new AutotestSav07(Log, CheckEnabled("sav07live2"));
                _state = 11;
                return;
            }
            // UI-21 'importui' opt-in (additive): takes over at the neighborhood
            // screen like the other batteries — the fixture drives the REAL
            // Import button, dialog and confirmed import itself. Only reachable
            // when the configured Checks string names it.
            if (CheckEnabled("importui"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST importui neighborhood-screen ready; entering import-UI battery");
                _importui = new AutotestImportUI(Log);
                _state = 12;
                return;
            }
            // UI-30 'nghbtns' opt-in (additive): takes over at the neighborhood
            // screen — the credits timeline/entry/exit law + the armed bulldoze
            // branch matrix through the REAL buttons and the NBR-02/NBR-03
            // backends. Only reachable when the configured Checks string names
            // it (the default string never lists it).
            if (CheckEnabled("nghbtns"))
            {
                if (++_neighborhoodReadyFrames < 60) return;
                Log("AUTOTEST nghbtns neighborhood-screen ready; entering credits+bulldoze battery");
                _ui30 = new AutotestUI30(Log);
                _state = 14;
                return;
            }
            // Only the visual survey needs a settled neighborhood frame. Do
            // not add a one-second delay to every unrelated parity run.
            if (!CheckEnabled("uisurvey"))
            {
                _state = 1;
                TryNextHouse();
                return;
            }
            // CurrentUIScreen flips before the outgoing load overlay finishes
            // its last frames. Let the real neighborhood composition settle so
            // the visual artifact contains the 800x600 map above LargeBack.
            if (++_neighborhoodReadyFrames < 60) return;
            Log("AUTOTEST neighborhood-screen ready; attempting houses");
            try
            {
                var tree = new System.Collections.Generic.List<string> { "== neighborhood overview ==" };
                SurveyDump("neighborhood", tree);
                _neighborhoodSurveyCaptured = true;
            }
            catch (Exception se)
            {
                // Attribute the missing visual evidence to uisurvey later,
                // without aborting every remaining lot/runtime check here.
                Log("AUTOTEST uisurvey neighborhood EXC " + se.GetType().Name + " " + se.Message);
            }
            _state = 1;
            TryNextHouse();
        }

        private static bool _autoResolved;

        private static void TryNextHouse()
        {
            if (!_autoResolved && _houses.Length == 1 && _houses[0].ToLowerInvariant() == "auto")
            {
                _autoResolved = true;
                try
                {
                    var neigh = Content.Get().Neighborhood;
                    var found = new List<string>();
                    for (int h = 0; h < 59; h++)
                    {
                        var fam = neigh.GetFamilyForHouse((short)h);
                        if (fam != null && fam.FamilyGUIDs != null && fam.FamilyGUIDs.Length > 0)
                            found.Add(h.ToString());
                    }
                    Log("AUTOTEST auto-detect houses-with-families=[" + string.Join(",", found) + "]");
                    if (found.Count > 0) _houses = found.ToArray();
                    else _houses = new[] { "autofail" };
                }
                catch (Exception e)
                {
                    Log("AUTOTEST auto-detect exception: " + e.Message);
                }
            }
            if (_houseIdx >= _houses.Length)
            {
                Log("AUTOTEST all candidate houses tried; none loaded an in-lot VM with avatars");
                _failed++;
                Finish();
                return;
            }
            short houseId;
            if (!short.TryParse(_houses[_houseIdx], out houseId))
            {
                _houseIdx++;
                TryNextHouse();
                return;
            }
            _screen = GameFacade.Screens?.CurrentUIScreen as TS1GameScreen;
            _loadPath = Content.Get().Neighborhood.GetHousePath(houseId);
            Log("AUTOTEST LOT-TRY house=" + houseId + " path='" + _loadPath + "'");
            _houseDeadline = DateTime.UtcNow.AddSeconds(70);
            // PlayHouse is a public choke point that bypasses UI selection; safe on game thread.
            GameThread.NextUpdate(x =>
            {
                try
                {
                    _screen.PlayHouse(houseId, null);
                    Log("AUTOTEST LOT-ACTION house=" + houseId + " inlot=" + _screen.InLot + " vm=" + (_screen.vm != null));
                }
                catch (Exception e)
                {
                    Log("AUTOTEST LOT-ACTION exception house=" + houseId + ": " + e.GetType().Name + " " + e.Message);
                    Log("AUTOTEST LOT-ACTION stack: " + e.StackTrace);
                }
            });
        }

        private static void StateWaitLot()
        {
            if (_screen == null) return;
            if (_screen.InLot && _screen.vm != null)
            {
                _vm = _screen.vm;
                _avatars = _vm.Entities.Where(e => e is VMAvatar).Cast<VMAvatar>().ToList();
                Log("AUTOTEST LOT-READY house=" + _houses[Math.Min(_houseIdx, _houses.Length - 1)] +
                    " entities=" + _vm.Entities.Count + " avatars=" + _avatars.Count +
                    " loadErrors=" + _vm.LoadErrors.Count +
                    " speed=" + _vm.SpeedMultiplier + " minute=" + _vm.Context.Clock.Minutes);
                // R157: an unpause orphans any shown-but-unanswered blocking dialog. The engine's
                // latch (GlobalBlockingDialog) is released by the player's click (VMNetDialogResponseCmd)
                // or, since r157, by the dialog's own timeout — but a latch we orphan here must be
                // dropped NOW or every later TS1 blocking dialog queues forever (the r156 carpool hang:
                // HelpSystemMagic's load dialog + this unpause = leaked latch = 'process' 4125 frozen).
                if (_vm.SpeedMultiplier <= 0)
                {
                    var staleDlg = _vm.GlobalBlockingDialog;
                    _vm.SpeedMultiplier = 1;
                    _vm.GlobalBlockingDialog = null;
                    Log("AUTOTEST unpaused vm (was paused; stale-dialog-latch " + (staleDlg == null ? "none" : "obj" + staleDlg.ObjectID) + " released)");
                }

                if (CheckEnabled("load"))
                {
                    if (_vm.LoadErrors.Count == 0) Pass("load");
                    else
                    {
                        Fail("load");
                        foreach (var err in _vm.LoadErrors.Take(5)) Log("AUTOTEST load-error: " + err);
                    }
                }

                if (CheckEnabled("lot"))
                {
                    if (_avatars.Count > 0) Pass("lot");
                    else
                    {
                        Log("AUTOTEST lot: house " + _houses[Math.Min(_houseIdx, _houses.Length - 1)] + " loaded with 0 avatars; trying next");
                        _houseIdx++;
                        _state = 1;
                        TryNextHouse();
                        return;
                    }
                }

                if (CheckEnabled("savedthreads")) CheckSavedThreads();

                if (CheckEnabled("savefault")) CheckSaveFault();

                if (CheckEnabled("simvis")) CheckSimVisibility();

                if (CheckEnabled("censorpixel")) CheckCensorPixel();

                // UI-22 'archundo' opt-in (additive): the build-mode
                // architecture undo/redo battery — see AutotestArchUndo.cs.
                // Takes over in-lot exactly like the other focused batteries;
                // only reachable when the configured checks string names it.
                if (CheckEnabled("archundo"))
                {
                    // UI-22 discriminator: 'archundo-probe' in the checks string
                    // runs the identical scenario with the undo/redo SENDS
                    // disabled (ambient-lottery control).
                    _archundo = new AutotestArchUndo(Log, _screen, CheckEnabled("archundo-probe"));
                    _state = 15;
                    return;
                }

                // EXP-06 V1 'ss-mount' opt-in (additive): Superstar pack mount
                // census — see RunSSMount. Only reachable when the checks
                // string names it; the default suite is untouched.
                if (CheckEnabled("ss-mount")) RunSSMount();

                // EXP-06 V2 leg 1 'ss-plugin' opt-in (additive): the Go Studio
                // phone-plugin observation leg — see RunSSPlugin.
                if (CheckEnabled("ss-plugin")) RunSSPlugin();

                if (CheckEnabled("corpus")) RunCorpus();

                if (CheckEnabled("unl-mount")) RunUnleashedMount();

                if (CheckEnabled("uicapture"))
                {
                    try
                    {
                        AutotestCamera239.BeginCaptureCheck(_screen);
                        _cameraCaptureFrames239=0;
                        _state=5;
                        return;
                    }
                    catch (Exception ex)
                    {
                        Log("AUTOTEST uicapture begin EXC "+ex);
                        AutotestCamera239.CancelCaptureCheck();
                        Fail("uicapture");
                    }
                }
                ContinueAfterCorpus239();
            }
            else if (DateTime.UtcNow > _houseDeadline)
            {
                Log("AUTOTEST LOT-TIMEOUT house=" + _houses[Math.Min(_houseIdx, _houses.Length - 1)] + " inlot=" + _screen.InLot);
                _houseIdx++;
                _state = 1;
                TryNextHouse();
            }
        }

