        // Raw room score the engine actually uses in the mood sum (VMTS1MotiveDecay.Tick
        // adds context.GetRoomScore() unclamped; only the stored Room motive is clamped to
        // 0..100-ish by SetMotiveData). To reproduce the engine's mood we must use the raw
        // score, not the clamped motive. Motives are not atomically readable across a decay
        // tick, so comparisons allow a small tolerance for tick-boundary races.
        private static int SnapshotRoom(VMAvatar a)
        {
            try { return _vm.Context.GetRoomScore(_vm.Context.GetRoomAt(a.Position)); }
            catch { return a.GetMotiveData(VMMotive.Room); }
        }

        // Original game-save Room value (MotiveData[VMMotive.Room]) BEFORE the engine's
        // VMTS1MotiveDecay tick overwrites it with a fresh architecture room score.
        private static short GetMotiveData_room(int i)
        {
            if (i < 0 || i >= _avatars.Count) return 0;
            try { return _avatars[i].GetMotiveData(VMMotive.Room); }
            catch { return 0; }
        }

        private static short[] SnapshotAvatar(VMAvatar a)
        {
            var row = new short[DecayMotives.Length + 3];
            for (int i = 0; i < DecayMotives.Length; i++) row[i] = a.GetMotiveData(DecayMotives[i]);
            row[DecayMotives.Length] = (short)Math.Max(-100, Math.Min(100, SnapshotRoom(a)));
            row[DecayMotives.Length + 1] = a.GetMotiveData(VMMotive.Mood);
            // R251: the table-split selector (person+1536) surfaces as the age field.
            try { row[DecayMotives.Length + 2] = a.GetPersonData(VMPersonDataVariable.PersonsAge); }
            catch { row[DecayMotives.Length + 2] = 0; }
            return row;
        }

        // R251 mood law (corrective repoint of the OLD equal-weight /8 approximation).
        // Row layout (SnapshotAvatar): [0..6] = 7 decay motives in DecayMotives order
        // (Hunger, Comfort, Hygiene, Bladder, Energy, Fun, Social), [7] = raw room score
        // (clamped -100..100), [8] = stored mood, [9] = age. Returns the SAME weighted
        // average short the engine's VMTS1MotiveDecay.Tick stores, so the pin asserts the
        // correctly-decoded law, NOT the old /8.
        private static short ComputeMoodLaw(short[] row)
        {
            if (row.Length < DecayMotives.Length + 3) return 0;
            // DecayMotives order -> weight-curve index (curve order is Hunger, Energy,
            // Comfort, Fun, Hygiene, Social, Bladder):
            //   Hunger->0, Comfort->2, Hygiene->4, Bladder->6, Energy->1, Fun->3, Social->5
            var map = new[] { 0, 2, 4, 6, 1, 3, 5 };
            var global = Content.Get().WorldObjectGlobals;
            if (global == null) return 0;
            var age = row[DecayMotives.Length + 2];
            var child = (age > 0 && age < 0x12); // person[1536] in [1,17] -> child table
            var curves = child ? global.HappyWeightChild : global.HappyWeight;

            double num = 0, den = 0;
            for (int i = 0; i < DecayMotives.Length; i++)
            {
                var m = (double)row[i];
                double w = 1.0;
                if (curves != null && map[i] < curves.Length)
                    w = curves[map[i]].GetPoint((float)m);
                num += w * m;
                den += w;
            }
            var room = (double)row[DecayMotives.Length];
            num += MoodRoomWeight * room;
            den += MoodRoomWeight;
            if (den <= 0) return 0;
            return (short)(num / den);
        }

        private static bool MoodMatches(short[] row)
        {
            if (row.Length < DecayMotives.Length + 3) return false;
            var computed = ComputeMoodLaw(row);
            return Math.Abs(row[DecayMotives.Length + 1] - computed) <= 3; // tick-boundary tolerance
        }

        // ============================================================================
        // (R251) 'moodlaw' — OPT-IN. Drives a known motive state (re-pinned every frame
        // so the decay tick has no net effect) and asserts (a) the stored mood equals the
        // curve-weighted target (aggregation law), and (b) a step change to the motives
        // produces the new target on the next recompute (NO smoothing — the mood follows
        // the motives immediately, not by a lerp). This distinguishes the decoded
        // pure-recompute law from the old state-dependent/smoothing hypothesis. It is NOT
        // in the default Config.Checks string (it is additive like freewillwin).
        //
        // State A (DecayMotives order: Hunger,Comfort,Hygiene,Bladder,Energy,Fun,Social)
        //   = {30,60,80,20,70,40,90}; State B = {10,60,80,90,70,40,20}. The step change
        //   moves Hunger 30->10 and Bladder 20->90 (and Fun 40->20) so the weighted
        //   average moves by more than a point (the curves weight low motives heavily).
        private static readonly short[] MoodLawStateA = { 30, 60, 80, 20, 70, 40, 90 };
        private static readonly short[] MoodLawStateB = { 10, 60, 80, 90, 70, 40, 20 };

        private static void SetMoodLawPinned(VMAvatar a, short[] state)
        {
            for (int i = 0; i < DecayMotives.Length && i < state.Length; i++)
                a.SetMotiveData(DecayMotives[i], state[i]);
        }

        private static void CheckMoodLawTick(int minute)
        {
            if (_moodLawDone) return;
            if (_avatars == null || _avatars.Count == 0) { Fail("moodlaw"); _moodLawDone = true; return; }
            var a = _avatars[0];
            try
            {
                if (_moodLawPhase == 0)
                {
                    SetMoodLawPinned(a, MoodLawStateA);
                    _moodLawSetMinute = minute;
                    _moodLawPhase = 1;
                    return;
                }
                if (_moodLawPhase == 1)
                {
                    SetMoodLawPinned(a, MoodLawStateA); // keep state A (counter decay)
                    if (minute - _moodLawSetMinute < 2) return; // wait for a recompute boundary
                    var row = SnapshotAvatar(a);
                    var target = ComputeMoodLaw(row);
                    var stored = row[DecayMotives.Length + 1];
                    Log("AUTOTEST moodlaw phaseA av0 storedMood=" + stored + " lawTarget=" + target +
                        " needs=" + string.Join(",", row.Take(DecayMotives.Length)) + " room=" + row[DecayMotives.Length]);
                    if (Math.Abs(stored - target) > 3)
                    {
                        Log("AUTOTEST moodlaw phaseA MISMATCH (aggregation law) stored=" + stored + " target=" + target);
                        Fail("moodlaw"); _moodLawDone = true; return;
                    }
                    _moodLawMoodA = stored;
                    SetMoodLawPinned(a, MoodLawStateB); // step change
                    _moodLawSetMinute = minute;
                    _moodLawPhase = 2;
                    return;
                }
                if (_moodLawPhase == 2)
                {
                    SetMoodLawPinned(a, MoodLawStateB);
                    if (minute - _moodLawSetMinute < 2) return; // wait for a recompute boundary
                    var row = SnapshotAvatar(a);
                    var target = ComputeMoodLaw(row);
                    var stored = row[DecayMotives.Length + 1];
                    Log("AUTOTEST moodlaw phaseB av0 storedMood=" + stored + " lawTarget=" + target +
                        " phaseAMood=" + _moodLawMoodA +
                        " needs=" + string.Join(",", row.Take(DecayMotives.Length)) + " room=" + row[DecayMotives.Length]);
                    if (Math.Abs(stored - target) > 3)
                    {
                        Log("AUTOTEST moodlaw phaseB MISMATCH (no-smoothing/aggregation) stored=" + stored + " target=" + target);
                        Fail("moodlaw"); _moodLawDone = true; return;
                    }
                    if (Math.Abs(stored - _moodLawMoodA) <= 1)
                    {
                        Log("AUTOTEST moodlaw phaseB FAIL: mood did NOT move on the step change (smoothing?) storedB=" + stored + " moodA=" + _moodLawMoodA);
                        Fail("moodlaw"); _moodLawDone = true; return;
                    }
                    Log("AUTOTEST moodlaw PASS: moodA=" + _moodLawMoodA + " -> moodB=" + stored + " follows step change exactly");
                    Pass("moodlaw"); _moodLawDone = true;
                    return;
                }
            }
            catch (Exception me) { Log("AUTOTEST moodlaw EXC " + me.GetType().Name + " " + me.Message); Fail("moodlaw"); _moodLawDone = true; }
        }

        // ROUND-147 'zoomlive': the far-zoom terrain black-out probe driven by
        // the GAME'S OWN frame loop. The synchronous survey battery (states Z*)
        // forces states within one frame; the user's bug happens across frames
        // (UILotControl's TargetZoom tween, BackbufferScale 2x->1x, static
        // rebakes at intermediate states). This probe sets LotControl.TargetZoom
        // like the mouse wheel does and censuses the LIVE PPX backbuffer (the
        // exact texture the screen displays) every 10 frames.
        private static int _zoomLivePhase = 0;
        private static int _zoomLiveFrame = 0;

        private static void ZoomLiveTick()
        {
            try
            {
                var scr = _screen;
                var lc = scr?.LotControl;
                var world = lc?.World;
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (world == null || gd == null || lc == null) { _zoomLivePhase = 0; return; }
                _zoomLiveFrame++;
                var f = _zoomLiveFrame;
                if (f % 10 == 0)
                {
                    var ch = world.Architecture.Blueprint.Changes;
                    var bb = FSO.Common.Utils.PPXDepthEngine.GetBackbuffer();
                    int dark = -1, green = -1, tot = 0;
                    if (bb != null && !bb.IsDisposed)
                    {
                        var snap = new Color[bb.Width * bb.Height];
                        bb.GetData(snap);
                        dark = 0; green = 0;
                        for (int i = 0; i < snap.Length; i += 53)
                        {
                            tot++;
                            var c = snap[i];
                            if (c.R + c.G + c.B < 30) dark++;
                            if (c.G > 40 && c.G > c.R + 15 && c.G > c.B + 15) green++;
                        }
                        if (System.Array.IndexOf(new int[] { 10, 70, 120, 130, 190, 250, 260, 290, 320 }, f) >= 0)
                        {
                            using (var tex = new Texture2D(gd, bb.Width, bb.Height))
                            {
                                tex.SetData(snap);
                                var zpath = System.IO.Path.Combine(FSO.Common.FSOEnvironment.UserDir, "uisurvey-zoomlive-" + f + ".png");
                                using (var zfs = System.IO.File.Create(zpath)) tex.SaveAsPng(zfs, tex.Width, tex.Height);
                            }
                        }
                    }
                    Log("AUTOTEST zoomlive f=" + f + " phase=" + _zoomLivePhase
                        + " zoom=" + world.State.Zoom + " pz=" + world.State.PreciseZoom.ToString("0.###")
                        + " target=" + lc.TargetZoom.ToString("0.###") + " bbs=" + world.BackbufferScale.ToString("0.###")
                        + " immediate=" + ch.DrawImmediate + " ssDirty=" + ch.StaticSurfaceDirty
                        + " dark=" + dark + "/" + tot + " green=" + green + "/" + tot);
                }
                if (_zoomLivePhase == 1 && f >= 30)
                {
                    lc.TargetZoom = 0.25f;
                    _zoomLivePhase = 2;
                    Log("AUTOTEST zoomlive >>> target far (TargetZoom=0.25)");
                }
                else if (_zoomLivePhase == 2 && f >= 130)
                {
                    lc.TargetZoom = 0.5f;
                    _zoomLivePhase = 3;
                    Log("AUTOTEST zoomlive >>> target medium (TargetZoom=0.5)");
                }
                else if (_zoomLivePhase == 3 && f >= 190)
                {
                    _zoomLivePhase = 4;
                    Log("AUTOTEST zoomlive >>> scroll phase (front-left corner, 0.4 tiles/frame)");
                }
                else if (_zoomLivePhase == 4)
                {
                    // scroll toward the screen's bottom-left (lot front corner)
                    world.State.CenterTile += new Vector2(-0.4f, 0.4f);
                    if (f >= 260)
                    {
                        _zoomLivePhase = 5;
                        Log("AUTOTEST zoomlive >>> scroll stop (does the wedge heal = 'pops back in'?)");
                    }
                }
                else if (_zoomLivePhase == 5 && f >= 320)
                {
                    _zoomLivePhase = 0;
                    Log("AUTOTEST zoomlive END");
                }
            }
            catch (Exception e) { Log("AUTOTEST zoomlive EXC " + e.GetType().Name + " " + e.Message); _zoomLivePhase = 0; }
        }

        private static void StateSample()
        {
            if (_zoomLivePhase > 0) { ZoomLiveTick(); return; }
            if (_vm == null) { Finish(); return; }
            _absTick++; // EXP-02: monotonic watch clock — HPNext resets _hpFrame per leg
            if (_flPushed && !_flDone) FallinTick(); // EXP-02: the fall-in-love watch survives leg transitions
            if (_plPushed) ProposeTick(); // EXP-02: phase-2 propose watch + run-55 postmortem + run-63 neg arm (post-postmortem)
            if (CheckEnabled("ss-book") && !_ssBookDone) { SSBookTick(); return; }
            if (CheckEnabled("socexec") && !_socExecDone) { SocExecTick(); return; }
            if (CheckEnabled("saveresume") && !_srDone) { SaveResumeTick(); return; }
            // (SIM-03 tranches 2-5) focused lifecycle probes; same short-circuit pattern.
            if (CheckEnabled("svccycle") && !_sim3Done) { SvcCycleTick(); return; }
            if (CheckEnabled("billtxn") && !_sim3Done) { BillTxnTick(); return; }
            if (CheckEnabled("marrytrace") && !_sim3Done) { MarryTraceTick(); return; }
            if (CheckEnabled("birthtrace") && !_sim3Done) { BirthTraceTick(); return; }
            if (CheckEnabled("familymerge") && !_sim3Done) { FamilyMergeTick(); return; }
            // R139: loud lot-unload detector. When the carpool takes the
            // last family sim at the ~8:00 window the game returns to the
            // neighborhood; the stale _vm's clock freezes and the carseek
            // soak would otherwise wait silently until the 30-min timeout
            // (r139p1: ticks stopped at 7:29, no SUMMARY, ~10-min exit
            // stall). Fail the soak honestly and let the summary print.
            if (_screen != null && !_screen.InLot
                && !(CheckEnabled("cc02e2e") && _cc02e2eArmed && !_cc02e2eDone)
                && !(CheckEnabled("llinteract") && _ll2State == 1 && _ll2ReloadPending))
            {
                Log("AUTOTEST SAMPLE-ABORT lot unloaded mid-soak (carpool/sim exit) at minute="
                    + _vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")
                    + "; carseek unverifiable this run");
                if (CheckEnabled("carseek")) Fail("carseek");
                if (CheckEnabled("carreturn")) Fail("carreturn");
                if (CheckEnabled("schoolreturn")) Fail("schoolreturn");
                if (CheckEnabled("schoolmiss")) Fail("schoolmiss");
                Finish();
                return;
            }
            if (_vm.SpeedMultiplier <= 0)
            {
                // R157: unpause + orphan the stale dialog latch (see the LOT-READY site).
                var staleDlg2 = _vm.GlobalBlockingDialog;
                _vm.SpeedMultiplier = 1;
                _vm.GlobalBlockingDialog = null;
                Log("AUTOTEST forced speed 1 (stale-dialog-latch " + (staleDlg2 == null ? "none" : "obj" + staleDlg2.ObjectID) + " released)");
            }
            // (CC-02 e2e) per-frame drive of the custom-content chain; the battery
            // stays open until the chain verdicts (tail gate below).
            if (CheckEnabled("cc02e2e") && !_cc02e2eDone)
            {
                if (!_cc02e2eArmed)
                {
                    if (_vm == null || _avatars == null || _avatars.Count == 0) return; // lot not ready yet
                    _cc02e2eArmed = true;
                    var scr = _screen;
                    AutotestCC02E2E.Begin(() => _vm, () => _avatars,
                        () => { scr.Save(); return true; },
                        () => scr.PlayHouse(5, null), Log);
                    Log("AUTOTEST cc02e2e: Begin (chain armed post-battery, freeplay world)");
                }
                if (AutotestCC02E2E.SampleTick())
                {
                    _cc02e2eDone = true;
                    if (AutotestCC02E2E.AllPassed) Pass("cc02e2e");
                    else Fail("cc02e2e");
                }
            }
            // (EXP-01 llinteract v3) per-frame drive of the genie wish-chain legs;
            // the soak stays open until the chain verdicts (explicit SUMMARY count).
            if (CheckEnabled("llinteract") && _ll2State != 2)
            {
                CheckLLInteract();
            }
            // (EXP-01 llfire) per-frame drive of the fire/rocket census legs; the
            // run stays open until the four legs verdict.
            if (CheckEnabled("llfire") && _ll3State != 2)
            {
                CheckLLFire();
            }
            // AUD-12 (opt-in "aud12live"): the capture rail drives the audible
            // acceptance legs; the run stays open until the matrix verdicts.
            if (CheckEnabled("aud12live") && _a12State != 2)
            {
                CheckAUD12Live();
            }
            // CC-05 (opt-in "cc05live"): the MissingGlobal orphan constructed live —
            // construction-time lazy, so the battery never builds it; the check
            // drives the construction once on the first soak frame.
            if (CheckEnabled("cc05live") && !_cc05Done) CheckCC05Live();
            // CC-04 (opt-in "cc04live"): the removal/replacement/reinstall legs —
            // one phase per process run, sequenced by the external driver via
            // /tmp/cc04/phase.txt; the fixed private userdir carries the save.
            if (CheckEnabled("cc04live") && !_cc04Done) CheckCC04Live();
            // EXP-02 (opt-in "hpparty"): the House Party lifecycle spine —
            // Throw Party via the phone, guests arrive, party state, end.
            if (CheckEnabled("hpparty") && _hpState != 2)
            {
                CheckHP();
            }
            // EXP-04 (opt-in "vacation"): the vacation booking leg — phone/plugin
            // row resolve, queue-path dialog answers, occupied-lot/token verdict.
            // run-72 decode: per-frame tick here (the RunCorpus one-shot battery
            // Finishes right after LOT-READY — the settle-guard silently ate the
            // single call and the run ended "no check verdicted").
            if (CheckEnabled("vacation") && _vacState != 2)
            {
                VacTick();
            }
            // EXP-05 (opt-in "unl-pets"): pet spawn/persistence leg — pen-animal
            // Person OBJD family attached through the real APIs, native spawn,
            // motive soak, save + reload persistence (V2 of exp05-scope-20260921.md).
            if (CheckEnabled("unl-pets") && _unlState != 99)
            {
                UnlPetsTick();
            }
            // EXP-05 V3 (opt-in "unl-pets2"): despawn forensics — catch who removes
            // the VerifyFamily-spawned pets (F-PETS-DESPAWN, unl-run2 receipt).
            if (CheckEnabled("unl-pets2") && _unl2State != 99)
            {
                UnlPets2Tick();
            }
            // EXP-05 V6 (opt-in "unl-travel"): Old Town round trip per TRV-02.
            if (CheckEnabled("unl-travel") && _unltrState != 99)
            {
                UnlTravelTick();
            }
            // EXP-05 V4 (opt-in "unl-show"): Pet Show controller loop.
            if (CheckEnabled("unl-show") && _unlsState != 99)
            {
                UnlShowTick();
            }
            // EXP-05 V5 (opt-in "unl-mice"): Unleashed mice controller cycles.
            if (CheckEnabled("unl-mice") && _unlmState != 99)
            {
                UnlMiceTick();
            }
            else if (CheckEnabled("unl-mice"))
            {
                // run-7: verdict recorded — tear the ITRACE sink down so later
                // states (or the battery) don't drown in controller trace lines.
                if (FSO.SimAntics.Engine.VMThread.AutotestTraceSink != null)
                {
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = null;
                    FSO.SimAntics.Engine.VMThread.AutotestTraceShowTrees = false;
                    FSO.SimAntics.Engine.VMThread.AutotestUnbudgetedEnts.Clear();
                }
            }
            var minute = _vm.Context.Clock.Minutes;
            if (_motiveStartMinute < 0) _motiveStartMinute = minute;

            // (R249) 'freewillwin' battery: arm on the first soak frame (pins + seam
            // subscription), tick per frame, and emit its verdict once the window ends
            // (it evaluates before elapsed >= 6, inside the soak window).
            if (CheckEnabled("freewillwin"))
            {
                if (!_freewillwinArmed)
                {
                    _freewillwinArmed = true;
                    AutotestFreeWillWin249.Begin(_vm, _avatars, _loadPath, Log);
                }
                else if (!_freewillwinVerdicted && AutotestFreeWillWin249.SampleTick())
                {
                    _freewillwinVerdicted = true;
                    if (AutotestFreeWillWin249.AllPassed) Pass("freewillwin");
                    else Fail("freewillwin");
                }
            }

            var snap = new List<short[]>();
            foreach (var a in _avatars) snap.Add(SnapshotAvatar(a));

            // Load-phase handoff: the first moments carry the ORIGINAL game-save Mood until
            // Simitone's first VMTS1MotiveDecay tick recomputes it, so exclude pre-decay
            // samples from the formula check (record them separately as honest evidence).
            if (minute - _motiveStartMinute >= 2)
                _samples.Add(snap.ToArray());
            else if (minute != _lastLoggedMinute)
            {
                _lastLoggedMinute = minute;
                // (R224) one-shot room-internals dump: the port's per-room area /
                // RoomImpact sums / computed score vs the ORIGINAL's stored motive[13]
                // (86.333 Goth, 50.222 House07) — the inputs for the room-law fit.
                if (!_roomLawDumped)
                {
                    _roomLawDumped = true;
                    try
                    {
                        var ri = _vm.Context.RoomInfo;
                        for (ushort r = 0; r < ri.Length; r++)
                        {
                            var info = ri[r];
                            if (info.Room.Area == 0) continue;
                            var baseRoom = info.Room.LightBaseRoom;
                            var bInfo = ri[baseRoom];
                            int sumImpact = 0, entCount = 0, supportArea = 0;
                            foreach (var sr in bInfo.Room.SupportRooms)
                            {
                                var s = ri[sr];
                                supportArea += s.Room.Area;
                                foreach (var e in s.Entities)
                                {
                                    try
                                    {
                                        var imp = e.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.RoomImpact);
                                        if (imp != 0) { sumImpact += imp; entCount++; }
                                    }
                                    catch { }
                                }
                            }
                            Log("AUTOTEST roomlaw room=" + r + " base=" + baseRoom +
                                " outside=" + bInfo.Room.IsOutside + " pool=" + bInfo.Room.IsPool +
                                " area=" + bInfo.Room.Area + " supportArea=" + supportArea +
                                " supportCount=" + (bInfo.Room.SupportRooms != null ? bInfo.Room.SupportRooms.Count : 0) +
                                " impactEntities=" + entCount + " sumImpact=" + sumImpact +
                                " score=" + (bInfo.Light != null ? bInfo.Light.RoomScore : 0) +
                                " entitiesInBase=" + (bInfo.Entities != null ? bInfo.Entities.Count : 0));
                        }
                    }
                    catch (Exception rl) { Log("AUTOTEST roomlaw EXC " + rl.GetType().Name + " " + rl.Message); }
                    // (R226) the tile-collector port (r134's CollectTileStats semantics):
                    // per room — the tile count with the original's wall weighting
                    // (tile with wall segments: +1; open tile: +2), wall-tile count,
                    // and the wall STYLE histogram (the window/door classifier input —
                    // the original's codes {1,7,8,9} window-ish / {3,5,6,15,23} door-ish).
                    try
                    {
                        var arch = _vm.Context.Architecture;
                        var roomMaps = arch.Rooms;
                        var wallLevels = arch.Walls;
                        for (int lv = 0; lv < roomMaps.Length && lv < wallLevels.Length; lv++)
                        {
                            var rm = roomMaps[lv];
                            var wl = wallLevels[lv];
                            if (rm?.Map == null || wl == null) continue;
                            var tile56 = new System.Collections.Generic.Dictionary<uint, int>();
                            var wallTiles = new System.Collections.Generic.Dictionary<uint, int>();
                            var styles = new System.Collections.Generic.Dictionary<uint, string>();
                            for (int idx = 0; idx < rm.Map.Length; idx++)
                            {
                                var room = rm.Map[idx];
                                if (room == 0) continue;
                                var segs = wl[idx].Segments;
                                int cur56, curW;
                                tile56.TryGetValue(room, out cur56);
                                wallTiles.TryGetValue(room, out curW);
                                if (segs != 0)
                                {
                                    tile56[room] = cur56 + 1;
                                    wallTiles[room] = curW + 1;
                                    var st = wl[idx].TopLeftStyle + "/" + wl[idx].TopRightStyle + "/" + wl[idx].TopLeftPattern + "/" + wl[idx].TopRightPattern;
                                    styles[room] = styles.TryGetValue(room, out var prev) ? prev + " " + st : st;
                                }
                                else tile56[room] = cur56 + 2;
                            }
                            foreach (var kv in tile56)
                            {
                                Log("AUTOTEST roomlaw-tiles level=" + (lv + 1) + " room=" + kv.Key +
                                    " tile56=" + kv.Value + " wallTiles=" + (wallTiles.TryGetValue(kv.Key, out var wq) ? wq : 0) +
                                    " styles=[" + (styles.TryGetValue(kv.Key, out var sq) ? sq : "") + "]");
                            }
                            // (R231) the SHADOW closed-form law (R228) per inside room, with the
                            // light-aggregate bridge candidates and the window/door style-code
                            // hypotheses — the fixtures (86.333/50.222) arbitrate the mappings.
                            try
                            {
                                foreach (var kv in tile56)
                                {
                                    int engineRoom;
                                    try { engineRoom = (int)(kv.Key & 0xFFFF); } catch { continue; }
                                    if (engineRoom <= 0 || engineRoom >= _vm.Context.RoomInfo.Length) continue;
                                    var bInfo = _vm.Context.RoomInfo[engineRoom].Room.LightBaseRoom;
                                    var rInfo = _vm.Context.RoomInfo[bInfo];
                                    if (rInfo.Room.IsOutside) continue;
                                    var light = rInfo.Light;
                                    int half = kv.Value / 2;
                                    double wallTerm = Math.Min(half, 60) - 30;
                                    double f8 = Math.Max(10, Math.Min(45, half));
                                    // window/door candidates from the style histogram
                                    int winStyle = 0, doorStyle = 0, winPat = 0, doorPat = 0;
                                    if (styles.TryGetValue(kv.Key, out var sq2))
                                    {
                                        foreach (var tok in sq2.Split(' '))
                                        {
                                            var parts = tok.Split('/');
                                            if (parts.Length < 4) continue;
                                            if (ushort.Parse(parts[0]) == 1 || ushort.Parse(parts[0]) == 7 || ushort.Parse(parts[0]) == 8 || ushort.Parse(parts[0]) == 9) winStyle++;
                                            if (ushort.Parse(parts[1]) == 1 || ushort.Parse(parts[1]) == 7 || ushort.Parse(parts[1]) == 8 || ushort.Parse(parts[1]) == 9) winStyle++;
                                            foreach (var d in new[] { 3, 5, 6, 15, 23 })
                                            {
                                                if (ushort.Parse(parts[0]) == d) doorStyle++;
                                                if (ushort.Parse(parts[1]) == d) doorStyle++;
                                                if (ushort.Parse(parts[2]) == d) winPat++;
                                                if (ushort.Parse(parts[3]) == d) doorPat++;
                                            }
                                        }
                                    }
                                    int r60 = 2 * winStyle;
                                    int r84 = rInfo.Entities != null ? rInfo.Entities.Count : 0;
                                    double amb = light != null ? light.AmbientLight : 0;
                                    double olt = light != null ? light.OutsideLight : 0;
                                    // hypotheses for room[80]-inside: H1 ambient, H2 outside light, H3 entity count
                                    foreach (var hyp in new[] { 'A', 'B', 'C' })
                                    {
                                        double r80 = hyp == 'A' ? amb : hyp == 'B' ? olt : r84;
                                        if (r80 == 0) continue;
                                        double t1 = ((double)r60 / r80) * 40 - 40;
                                        double t2 = (r84 * 10.0) / f8;
                                        double t3 = winPat != 0 && doorPat != 0 ? ((double)winPat / doorPat) * 40 - 40 : 0;
                                        // obj term unknown (room108) — print both with obj=0 and solve hint
                                        double shadow = wallTerm + t1 + t2 + t3;
                                        Log("AUTOTEST roomlaw-shadow room=" + engineRoom + " hyp" + hyp +
                                            " half=" + half + " wall=" + wallTerm + " t1=" + t1.ToString("F2") +
                                            " t2=" + t2.ToString("F2") + " t3=" + t3.ToString("F2") +
                                            " shadowNoObj=" + shadow.ToString("F2") +
                                            " amb=" + amb + " olt=" + olt + " ents=" + r84 +
                                            " r60=" + r60 + " winPat=" + winPat + " doorPat=" + doorPat);
                                    }
                                }
                            }
                            catch (Exception sh) { Log("AUTOTEST roomlaw-shadow EXC " + sh.GetType().Name + " " + sh.Message); }
                        }
                    }
                    catch (Exception rl3) { Log("AUTOTEST roomlaw-tiles EXC " + rl3.GetType().Name + " " + rl3.Message); }
                    try
                    {
                        for (int a2 = 0; a2 < _avatars.Count; a2++)
                        {
                            var av = _avatars[a2];
                            var rm = _vm.Context.GetRoomAt(av.Position);
                            Log("AUTOTEST roomlaw avatar" + a2 + " obj=" + av.ObjectID +
                                " pos=" + av.Position.x + "," + av.Position.y + "," + av.Position.Level +
                                " roomAt=" + rm +
                                " score=" + _vm.Context.GetRoomScore(rm));
                        }
                    }
                    catch (Exception rl2) { Log("AUTOTEST roomlaw avatar EXC " + rl2.GetType().Name); }
                    // (R235) the roomlaw PIN: the decoded original ComputeRoom law with the
                    // disclosed room108=2.05 must reproduce the ORIGINAL save's stored room
                    // score for the unambiguous fixture — House07 Bob & Betty (engine room 3,
                    // stored motive[13] = 50.222; the original stores the score as a short ->
                    // 50). The Goth fixture is unattributable (they load outside — r234).
                    if (CheckEnabled("roomlaw"))
                    {
                        var pass = false;
                        try
                        {
                            var house = _houses[Math.Min(_houseIdx, _houses.Length - 1)];
                            if (house == "7" && _avatars.Count >= 2)
                            {
                                // the exact-fixture pin (R235): the decoded original law with
                                // room108=2.05 must reproduce the original save's 50.222,
                                // which the original's own float->short storage truncates to 50.
                                var rm = _vm.Context.GetRoomAt(_avatars[0].Position);
                                var sc = _vm.Context.GetRoomScore(rm);
                                Log("AUTOTEST roomlaw pin house7 avatar0 room=" + rm + " score=" + sc + " (stored original 50.222 -> 50)");
                                pass = sc == 50;
                            }
                            else if (house == "5")
                            {
                                // the default-gate fixture: the Goths' stored 86.333 is
                                // DISCLOSED (outside-at-load, r234) — pin the LAW'S LIVENESS
                                // instead: under the old port formula no inside room could
                                // exceed ~26 (sumImpact/areaScale <= 10); the decoded law's
                                // furnished rooms (the 100-clamped living rooms) prove it runs.
                                var maxInside = -999;
                                for (ushort r = 1; r < _vm.Context.RoomInfo.Length; r++)
                                {
                                    try
                                    {
                                        var bi = _vm.Context.RoomInfo[_vm.Context.RoomInfo[r].Room.LightBaseRoom];
                                        if (bi.Room.IsOutside) continue;
                                        var sc = bi.Light != null ? bi.Light.RoomScore : (short)0;
                                        if (sc > maxInside) maxInside = sc;
                                    }
                                    catch { }
                                }
                                Log("AUTOTEST roomlaw pin house5 maxInsideScore=" + maxInside + " (the old formula caps ~26; the decoded law's furnished rooms clamp at 100)");
                                pass = maxInside > 26;
                            }
                            else Log("AUTOTEST roomlaw pin: not a fixture house (house=" + house + ")");
                        }
                        catch (Exception pe) { Log("AUTOTEST roomlaw pin EXC " + pe.GetType().Name); }
                        if (pass) Pass("roomlaw"); else Fail("roomlaw");
                    }
                }
                for (int i = 0; i < snap.Count; i++)
                {
                    var row = snap[i];
                    int s7 = 0;
                    for (int k = 0; k < DecayMotives.Length; k++) s7 += row[k];
                    int rawRoom = row[DecayMotives.Length];
                    int storedMood = row[DecayMotives.Length + 1];
                    Log("AUTOTEST mood load-phase av" + i +
                        " storedMood=" + storedMood +
                        " needs=" + string.Join(",", row.Take(DecayMotives.Length)) +
                        " roomScore=" + rawRoom +
                        " rowRoom=" + GetMotiveData_room(i) +
                        " s7=" + s7 +
                        " hypNoRoom=" + (short)(s7 / 7) +
                        " hypEngine=" + (short)((s7 + rawRoom) / 8) +
                        " hypLaw=" + ComputeMoodLaw(row) +
                        " (original-save values; engine recomputes after first decay tick)");
                }
            }

            var moodAllOk = true;
            for (int i = 0; i < snap.Count; i++)
            {
                if (!MoodMatches(snap[i]))
                {
                    moodAllOk = false;
                    Log("AUTOTEST mood: MISMATCH av" + i + " storedMood=" + snap[i][DecayMotives.Length + 1] +
                        " computed=" + ComputeMoodLaw(snap[i]));
                }
            }
            // Throttle per-minute-change logs (per-frame would spam ~60 lines/second).
            if (minute != _lastLoggedMinute)
            {
                _lastLoggedMinute = minute;
                Log("AUTOTEST motive sample minute=" + minute + " avatars=" + snap.Count +
                    " moodAllOk=" + moodAllOk + " elapsed=" + (minute - _motiveStartMinute) +
                    " speed=" + _vm.SpeedMultiplier + " (" + minute + ":" + _vm.Context.Clock.Hours + " h)");
            }

            // brainlive: sample the live VM for IFF-factual execution of the original brain.
            ProbeBrainLive();

            // (R251) 'moodlaw' opt-in: drive a known motive state (re-pinned every frame)
            // and verify the decoded curve-weighted mood law — aggregation AND no-smoothing
            // (a step change reaches the new target on the next recompute). Additive; not in
            // the default Checks string. Starts after the load phase (>= 2 game-min).
            if (CheckEnabled("moodlaw") && minute - _motiveStartMinute >= 2) CheckMoodLawTick(minute);

            // (Round 77) NATURAL DEATH-REACH: late in the soak, collapse avatar0's decaying
            // motives so the engine's OWN periodic person-main loop (proven running) naturally
            // routes into the ORIGINAL motive-failure / death-decision chain in live frames -
            // IFF-factual reach evidence, NOT a serve-proof (no RunInMyStack). Engine recomputes
            // stored Mood each decay tick to the R251 curve-weighted law, so the mood gate stays consistent.
            // R149 RACE FIX: the collapse used to fire at elapsed>=6 — INSIDE the mood
            // gate's 10-minute window — and when the death chain executed before the
            // gate's final sample it zeroed av0's stored Mood (legitimately: the sim is
            // dying), flipping the mood gate on harness timing alone (R148 passed by
            // ~4s, R149 failed — same minute-37 collapse both runs). The collapse now
            // waits until the mood gate has completed (no-op when mood isn't enabled).
            if (CheckEnabled("deathchain") && !DeathCollapseDone && minute - _motiveStartMinute >= 6
                && (!CheckEnabled("mood") || MoodGateDone))
            {
                DeathCollapseDone = true;
                try
                {
                    if (_avatars != null && _avatars.Count > 0)
                    {
                        var aC = _avatars[0];
                        for (var i = 0; i < DecayMotives.Length; i++)
                            aC.SetMotiveData(DecayMotives[i], 3);
                        // align stored Mood with the R251 weighted law after the collapse so the mood gate holds
                        try {
                            var newMood = ComputeMoodLaw(SnapshotAvatar(aC));
                            aC.SetMotiveData(VMMotive.Mood, (short)System.Math.Max(-100, System.Math.Min(100, (int)newMood)));
                        } catch (Exception mda) { Log("AUTOTEST death-reach mood-align EXC " + mda.GetType().Name); }
                        Log("AUTOTEST death-reach: motives collapsed to 3 on av0 obj=" + aC.ObjectID +
                            " at minute=" + minute + " (natural death-decision reach probe)");
                    }
                }
                catch (Exception dce2) { Log("AUTOTEST death-reach collapse EXC " + dce2.GetType().Name); }
            }

            // (Round 219) DEATHTRACE entry: collapse avatar0's Hunger to the -100 floor (the
            // 8299 gate is < -98 — the R77 +3 collapse never crossed it), then hand the soak
            // to the dedicated death-state sampler. Only Hunger: a single-variable starvation
            // trace keeps the energy/bladder handlers out of the timeline.
            if ((CheckEnabled("deathtrace") || CheckEnabled("ghosttrace") || CheckEnabled("deathrel")) && !_deathTraceStarted && minute - _motiveStartMinute >= 2)
            {
                _deathTraceStarted = true;
                try
                {
                    if (_avatars != null && _avatars.Count > 0)
                    {
                        var dC = _avatars[0];
                        _deathTraceAvatarId = dC.ObjectID;
                        dC.SetMotiveData(VMMotive.Hunger, -100);
                        _deathTraceCollapseMinute = _vm.Context.Clock.Hours * 60 + _vm.Context.Clock.Minutes;
                        _deathTraceCollapseReal = DateTime.UtcNow;
                        StartDeathTraceObservation();
                        var age0 = -1; try { age0 = dC.GetPersonData(VMPersonDataVariable.PersonsAge); } catch { }
                        var type0 = -1; try { type0 = dC.GetPersonData((VMPersonDataVariable)32); } catch { }
                        Log("AUTOTEST deathtrace: avatar0 obj=" + dC.ObjectID + " age=" + age0 +
                            " type32=" + type0 + " hunger collapsed to -100 at " +
                            (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")) +
                            " (the 8299 gate is Hunger < -98; expected: failure handler -> ~200-tick idle -> Global 393 kill)");
                    }
                    else
                    {
                        Log("AUTOTEST deathtrace: NO avatars — cannot collapse");
                    }
                }
                catch (Exception dte) { Log("AUTOTEST deathtrace collapse EXC " + dte.GetType().Name + " " + dte.Message); }
                _state = 4;
                return;
            }

            // keep sampling until 10 sim-minutes elapsed past baseline (observed sim-clock rate
            // on this build is ~1 sim-min/real-sec..; 10 sim-min is enough for measurable decay)
            if (minute - _motiveStartMinute < 10) return;

            // EXP-05: the default 10-sim-min endpoint (Finish below) is shorter than an
            // EXP show/mice cycle (judge spawn + competition + award runs into sim-hours).
            // While a focused EXP check is still active, hold the soak open — the check's
            // own timeout owns the verdict; SIMTONE_TIMEOUT_MS stays the backstop. The
            // one-shot mood/motive accounting below runs after the check verdicts (99).
            if ((CheckEnabled("unl-show") && _unlsState != 99)
                || (CheckEnabled("unl-mice") && _unlmState != 99))
            {
                var heldTag = (CheckEnabled("unl-mice") && _unlmState != 99) ? "unl-mice" : "unl-show";
                var heldState = heldTag == "unl-mice" ? _unlmState : _unlsState;
                if (!_unlsSoakHeld)
                {
                    _unlsSoakHeld = true;
