            if (CheckEnabled("mood")) { if (AllMoodOk()) Pass("mood"); else Fail("mood"); }
            MoodGateDone = true;   // R149: release the death-reach collapse (it must not race this window)

            bool motiveOk = true;
            _samples.Add(SnapshotAll());
            for (int a = 0; a < _avatars.Count && a < _samples[0].Length; a++)
            {
                var first = _samples[0][a];
                var lastAcc = SnapshotAll()[a];
                var deltas = DecayMotives.Select((m, i) => (int)lastAcc[i] - first[i]).ToArray();
                var increased = new List<string>();
                for (int i = 0; i < deltas.Length; i++)
                    if (deltas[i] > 25) increased.Add(DecayMotives[i].ToString() + "+" + deltas[i]);
                Log("AUTOTEST MOTIVE av" + a + " deltas=[" + string.Join(",", deltas) + "] over " + (minute - _motiveStartMinute) + " sim-min");
                if (increased.Count > 0) Log("AUTOTEST MOTIVE av" + a + " phantom-increases=" + string.Join(" ", increased));
                if (increased.Count > 2) motiveOk = false;
            }
