        private static void StopCareerBudgetObservation()
        {
            if (_careerBudgetObserver == null) return;
            FSO.SimAntics.Primitives.VMTS1Budget.BudgetMutated -= _careerBudgetObserver;
            _careerBudgetObserver = null;
        }

        private static void StartCareerBudgetObservation()
        {
            StopCareerBudgetObservation();
            _careerPayBaseEvents = 0;
            _careerPayBaseAmount = 0;
            _careerPayBonusEvents = 0;
            _careerPayBonusAmount = 0;
            _careerMountedPayTuning = -1;
            _careerBudgetEvents.Clear();
            _careerBudgetObserver = (frame, before, after) =>
            {
                try
                {
                    var iff = frame?.ScopeResource?.MainIff?.Filename ?? "?";
                    var routine = frame?.Routine?.Chunk?.ChunkID ?? 0;
                    var ip = frame?.InstructionPointer ?? 0;
                    var delta = after - before;
                    var entry = iff + ":" + routine + ":" + ip + "=" + delta + " (" + before + "->" + after + ")";
                    _careerBudgetEvents.Add(entry);
                    // (Round 222) chancetrace card effect: a budget mutation authored inside
                    // the chance cascade trees themselves (4124/4133/4134 — the card outcome
                    // transfers, e.g. Science02's +5000 at 4124 ins56). Counted BEFORE the
                    // 4103 pay filter below (run 4 placed it after the early return and the
                    // counter stayed 0 while the event itself logged fine).
                    if (iff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                        && (routine == 4124 || routine == 4133 || routine == 4134))
                    {
                        _chanceEffectBudgetEvents++;
                        _chanceTimeline.Add("card-budget " + entry + " at " + ChanceClock());
                        Log("AUTOTEST chancetrace card-budget " + entry);
                    }
                    if (!iff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase) || routine != 4103) return;
                    if (ip == 9)
                    {
                        _careerPayBaseEvents++;
                        _careerPayBaseAmount += delta;
                    }
                    else if (ip == 51)
                    {
                        _careerPayBonusEvents++;
                        _careerPayBonusAmount += delta;
                        _careerMountedPayTuning = FSO.SimAntics.Engine.Utils.VMMemory.GetTuningVariable(frame.Callee, 132, frame);
                    }
                    Log("AUTOTEST carreturn budget-event " + entry + " tuning132=" + _careerMountedPayTuning);
                }
                catch (Exception be)
                {
                    Log("AUTOTEST carreturn budget-event EXC " + be.GetType().Name + " " + be.Message);
                }
            };
            FSO.SimAntics.Primitives.VMTS1Budget.BudgetMutated += _careerBudgetObserver;
        }

        private static void StopCareerCreateObservation()
        {
