        private static void StartCareerCreateObservation()
        {
            StopCareerCreateObservation();
            _careerOutboundCarCreateEvents = 0;
            _careerReturnCarCreateEvents = 0;
            _careerCarCreateEvents.Clear();
            _schoolBusCreateEvents = 0;
            _schoolBusExactCreateEvents = 0;
            _schoolOutboundCreateEvents = 0;
            _schoolReturnCreateEvents = 0;
            _schoolBusCreateMinutes.Clear();
            _schoolBusCreateBaseIds.Clear();
            _schoolBusCreateEventLog.Clear();
            _careerCreateObserver = (frame, group, guid) =>
            {
                try
                {
                    var createdIff = group?.BaseObject?.Object?.Resource?.MainIff?.Filename ?? "?";
                    var ownerIff = frame?.ScopeResource?.MainIff?.Filename ?? "?";
                    var routine = frame?.Routine?.Chunk?.ChunkID ?? 0;
                    var ip = frame?.InstructionPointer ?? 0;
                    if (guid == SchoolBusGuid && createdIff.Equals("SchoolBus.iff", StringComparison.OrdinalIgnoreCase))
                    {
                        _schoolBusCreateEvents++;
                        var parentRoutine = 0;
                        var parentIp = -1;
                        var parentIff = "?";
                        try
                        {
                            var stack = frame?.Thread?.Stack;
                            var frameIndex = stack?.LastIndexOf(frame) ?? -1;
                            var parent = frameIndex > 0 ? stack[frameIndex - 1] : null;
                            parentRoutine = parent?.Routine?.Chunk?.ChunkID ?? 0;
                            parentIp = parent?.InstructionPointer ?? -1;
                            parentIff = parent?.ScopeResource?.MainIff?.Filename ?? "?";
                        }
                        catch { }
                        var clockMinute = (_vm?.Context?.Clock?.Hours ?? -1) * 60
                            + (_vm?.Context?.Clock?.Minutes ?? 0);
                        var baseId = group?.BaseObject?.ObjectID ?? (short)0;
                        var exact = ownerIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && routine == 4119 && ip == 4;
                        if (exact) _schoolBusExactCreateEvents++;
                        var outboundParent = parentIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && parentRoutine == 4115 && parentIp == 10;
                        var returnParent = parentIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                            && parentRoutine == 4116 && parentIp == 27;
                        var outbound = exact && outboundParent && _schoolStartHour >= 0
                            && clockMinute / 60 == _schoolStartHour - 1;
                        var returning = exact && returnParent && _schoolEndHour >= 0
                            && clockMinute / 60 == _schoolEndHour;
                        if (outbound) _schoolOutboundCreateEvents++;
                        if (returning) _schoolReturnCreateEvents++;
                        _schoolBusCreateMinutes.Add(clockMinute);
                        _schoolBusCreateBaseIds.Add(baseId);
                        var schoolEntry = ownerIff + ":" + routine + ":" + ip + " parent="
                            + parentIff + ":" + parentRoutine + ":" + parentIp
                            + " created " + createdIff + " guid=0x" + guid.ToString("X8")
                            + " base=" + baseId + " clock=" + (clockMinute / 60) + ":"
                            + (clockMinute % 60).ToString("00") + " exact=" + exact
                            + " caller=" + (frame?.Caller?.ObjectID ?? 0)
                            + " callee=" + (frame?.Callee?.ObjectID ?? 0)
                            + " stack=" + (frame?.StackObjectID ?? 0)
                            + " leg=" + (outbound ? "outbound" : returning ? "return" : "unattributed");
                        _schoolBusCreateEventLog.Add(schoolEntry);
                        Log("AUTOTEST schoolreturn create-event " + schoolEntry);
                        return;
                    }
                    if (!CheckEnabled("carreturn")) return;
                    if (guid != 0x4B71ECDA || !createdIff.Equals("CarJunk.iff", StringComparison.OrdinalIgnoreCase)
                        || !ownerIff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)) return;
                    var entry = ownerIff + ":" + routine + ":" + ip + " created " + createdIff
                        + " guid=0x" + guid.ToString("X8") + " base=" + (group?.BaseObject?.ObjectID ?? 0);
                    _careerCarCreateEvents.Add(entry);
                    if (routine == 4106 && ip == 20) _careerOutboundCarCreateEvents++;
                    if (routine == 4121 && ip == 19)
                    {
                        _careerReturnCarCreateEvents++;
                        _careerReturnCarSeen = true;
                    }
                    Log("AUTOTEST carreturn create-event " + entry);
                }
                catch (Exception ce)
                {
                    Log("AUTOTEST carreturn create-event EXC " + ce.GetType().Name + " " + ce.Message);
                }
            };
            FSO.SimAntics.Engine.Primitives.VMCreateObjectInstance.ObjectCreated += _careerCreateObserver;
        }

        // (Round 219) deathtrace observation: a separate create-observer for the death
        // artifacts. The killer is Global 393 'kill person for good' — its ins8 creates the
        // tombstone/urn (5A6FA529) and ins26 the reaper NPC (4B15D4B0). Any create whose
        // frame routine IS 393 is a death artifact regardless of GUID (evidence-grade).
        private static void StartDeathTraceObservation()
        {
            StopDeathTraceObservation();
            _deathTraceCreates.Clear();
            _deathCreateObserver = (frame, group, guid) =>
            {
                try
                {
                    var routine = frame?.Routine?.Chunk?.ChunkID ?? 0;
                    if (routine != 393 && guid != DeathTombstoneGuid && guid != DeathReaperGuid) return;
                    var ownerIff = frame?.ScopeResource?.MainIff?.Filename ?? "?";
                    var createdIff = group?.BaseObject?.Object?.Resource?.MainIff?.Filename ?? "?";
                    var ip = frame?.InstructionPointer ?? 0;
                    var entry = ownerIff + ":" + routine + ":" + ip + " created " + createdIff +
                        " guid=0x" + guid.ToString("X8") + " base=" + (group?.BaseObject?.ObjectID ?? 0) +
                        " caller=" + (frame?.Caller?.ObjectID ?? 0) + " stack=" + (frame?.StackObjectID ?? 0);
                    _deathTraceCreates.Add(entry);
                    if (guid == DeathTombstoneGuid && group?.BaseObject != null)
                        _ghostUrn = group.BaseObject; // (R220) the ghost night-watch subject
                    Log("AUTOTEST deathtrace create-event " + entry);
                }
                catch (Exception de) { Log("AUTOTEST deathtrace create-event EXC " + de.GetType().Name); }
            };
            FSO.SimAntics.Engine.Primitives.VMCreateObjectInstance.ObjectCreated += _deathCreateObserver;
        }

        // (R219/R220) one thread's stack walk: records first-seen canon death ids (always)
        // and, during the ghost phase, ghost ids — urn-side ids only when the frame's
        // MainIff IS UrnStone.iff (4100 collides with CarPortal 4100 'process').
        private static void WalkDeathWatchStack(FSO.SimAntics.Engine.VMThread th, short ownerId)
        {
            if (th == null || th.Stack == null) return;
            for (int f = 0; f < th.Stack.Count; f++)
            {
                var fr = th.Stack[f];
                if (fr == null) continue;
                var id = (ushort)((fr.Routine?.Chunk?.ChunkID) ?? 0);
                if (id == 0) continue;
                string mainIff = null;
                var wantGhost = _ghostPhaseStarted
                    && (Array.IndexOf(GhostPersonWatchIds, id) >= 0 || Array.IndexOf(GhostUrnWatchIds, id) >= 0)
                    && !_ghostIds.Contains(id);
                if (wantGhost)
                {
                    try { mainIff = fr.ScopeResource?.MainIff?.Filename; } catch { }
                    var isPerson = Array.IndexOf(GhostPersonWatchIds, id) >= 0;
                    if (isPerson || (mainIff != null && mainIff.ToLowerInvariant().IndexOf("urnstone") >= 0))
                    {
                        if (id == 4100 && !_ghostForcePushed) _ghostNaturalSpawn = true;
                        _ghostIds.Add(id);
                        var gline = "ghosttrace id-first-seen " + id + " '" +
                            (GhostIdNames.TryGetValue(id, out var gn) ? gn : "?") + "' iff=" + (mainIff ?? "?") +
                            " at " + (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"));
                        _deathTraceTimeline.Add(gline);
                        Log("AUTOTEST deathtrace " + gline);
                    }
                }
                if (!DeathTraceWatchIds.Contains(id) || _deathTraceIds.Contains(id)) continue;
                _deathTraceIds.Add(id);
                string chain = "";
                try
                {
                    var parts = new List<string>();
                    for (int g = 0; g < th.Stack.Count; g++)
                    {
                        var fr2 = th.Stack[g];
                        parts.Add(((fr2?.Routine?.Chunk?.ChunkID) ?? 0) + ":" + (fr2?.InstructionPointer ?? 0));
                    }
                    chain = " stack=[" + string.Join(",", parts) + "]";
                }
                catch { }
                if (id == 393 && _deathTraceStackAtKill == null) _deathTraceStackAtKill = chain;
                var line = "deathtrace id-first-seen " + id + " '" +
                    (DeathTraceIdNames.TryGetValue(id, out var nm) ? nm : "?") + "' on obj=" + ownerId + " at " +
                    (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")) + chain;
                _deathTraceTimeline.Add(line);
                Log("AUTOTEST " + line);
            }
        }

        private static void StopDeathTraceObservation()
        {
            if (_deathCreateObserver == null) return;
            FSO.SimAntics.Engine.Primitives.VMCreateObjectInstance.ObjectCreated -= _deathCreateObserver;
            _deathCreateObserver = null;
        }

        // (Round 219) the death soak state. Dense per-frame sampling of the collapsed
        // avatar's thread stack for the canon death ids, per-minute state polls (the dead
        // flag PersonData[68], the failure code [71], the type switch [32], the motive
        // reset), and a post-death window for the ghost loop. Self-evaluates well before
        // the wrapper timeout; every getter defensive — the probe must not disturb the run.
        private static void StateDeathTrace()
        {
            if (_vm == null || _deathTraceDone) { Finish(); return; }
            try
            {
                // (R219) THE DEATH NOTICE IS A BLOCKING MODAL: the reaper sequence raises a
                // TS1 dialog (the run-3/run-5 evidence — the VM clock froze at 7:00 with the
                // game loop still turning; run 1 only completed because the player clicked
                // it away). The probe acts as the player: name the latch owner, release it,
                // restore speed. Re-releases every 10s if the tree raises it again.
                try
                {
                    var dlg = _vm.GlobalBlockingDialog;
                    if (dlg != null && (dlg.ObjectID != _deathDlgLastObj
                        || DateTime.UtcNow - _deathDlgLastRelease > TimeSpan.FromSeconds(10)))
                    {
                        _deathDlgLastObj = dlg.ObjectID;
                        _deathDlgLastRelease = DateTime.UtcNow;
                        string dIff = null; try { dIff = dlg.Object?.Resource?.MainIff?.Filename; } catch { }
                        var line = "deathtrace blocking-dialog released obj=" + dlg.ObjectID +
                            " iff=" + (dIff ?? "?") + " at " + (_vm.Context.Clock.Hours + ":" +
                            _vm.Context.Clock.Minutes.ToString("00"));
                        _deathTraceTimeline.Add(line);
                        Log("AUTOTEST " + line);
                        _vm.GlobalBlockingDialog = null;
                        if (_vm.SpeedMultiplier <= 0) _vm.SpeedMultiplier = 1;
                    }
                }
                catch { }
                int nowMin = -1;
                try { nowMin = _vm.Context.Clock.Hours * 60 + _vm.Context.Clock.Minutes; } catch { }
                var a0 = (_avatars != null && _avatars.Count > 0) ? _avatars[0] : null;

                // dense stack walk: any avatar thread, any frame carrying a canon death id
                try
                {
                    if (_ghostPhaseStarted)
                    {
                        // the ghost person materializes as a NEW avatar after 4100 runs —
                        // refresh the walk list so its 8641 loop is sampled too
                        var fresh = _vm.Entities.Where(e => e is VMAvatar).Cast<VMAvatar>().ToList();
                        foreach (var av2 in fresh)
                            if (!_avatars.Contains(av2))
                            {
                                _avatars.Add(av2);
                                Log("AUTOTEST ghosttrace: new avatar joined obj=" + av2.ObjectID + " (the ghost person?)");
                            }
                    }
                    foreach (var av in _avatars) { if (av == null) continue; WalkDeathWatchStack(av.Thread, av.ObjectID); }
                    if (_ghostPhaseStarted && _ghostUrn != null) WalkDeathWatchStack(_ghostUrn.Thread, _ghostUrn.ObjectID);
                }
                catch { }

                // per-minute state poll on the collapsed avatar
                if (nowMin != _deathTraceLastPollMin && nowMin >= 0)
                {
                    _deathTraceLastPollMin = nowMin;
                    if (a0 != null)
                    {
                        try
                        {
                            var pd68 = a0.GetPersonData((VMPersonDataVariable)68);
                            var pd71 = a0.GetPersonData((VMPersonDataVariable)71);
                            var pd32 = a0.GetPersonData((VMPersonDataVariable)32);
                            var hunger = a0.GetMotiveData(VMMotive.Hunger);
                            var dead = false; try { dead = a0.Dead; } catch { }
                            if (pd68 == 1 && !_deathFlagSeen)
                            {
                                _deathFlagSeen = true;
                                var line = "deathtrace DEAD-FLAG PersonData[68]=1 on obj=" + a0.ObjectID +
                                    " type32=" + pd32 + " hunger=" + hunger + " at " +
                                    (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"));
                                _deathTraceTimeline.Add(line);
                                Log("AUTOTEST " + line);
                            }
                            if (dead && !_deathDeadFlagSeen)
                            {
                                _deathDeadFlagSeen = true;
                                _deathTraceTimeline.Add("deathtrace entity.Dead=true obj=" + a0.ObjectID);
                                Log("AUTOTEST deathtrace entity.Dead=true obj=" + a0.ObjectID);
                            }
                            Log("AUTOTEST deathtrace minute=" + (_vm.Context.Clock.Hours + ":" +
                                _vm.Context.Clock.Minutes.ToString("00")) + " obj=" + a0.ObjectID +
                                " pd68=" + pd68 + " pd71=" + pd71 + " pd32=" + pd32 +
                                " hunger=" + hunger + " dead=" + dead +
                                " ids=[" + string.Join(",", _deathTraceIds.OrderBy(x => x)) + "]");
                        }
                        catch (Exception pe)
                        {
                            if (!_deathEntityGone)
                            {
                                _deathEntityGone = true;
                                _deathTraceTimeline.Add("deathtrace avatar poll EXC " + pe.GetType().Name +
                                    " (entity likely removed by the kill path)");
                                Log("AUTOTEST deathtrace avatar poll EXC " + pe.GetType().Name + " " + pe.Message);
                            }
                        }
                    }
                }

                // finish conditions: death confirmed + a post-death window for the ghost loop,
                // or the probe's own budget (no death observed -> honest FAIL with timeline)
                var realElapsed = (DateTime.UtcNow - _deathTraceCollapseReal).TotalMinutes;
                var simElapsed = (_deathTraceCollapseMinute >= 0 && nowMin >= 0)
                    ? (nowMin - _deathTraceCollapseMinute + 1440) % 1440 : 0;
                var deadNow = _deathFlagSeen || _deathDeadFlagSeen || _deathEntityGone;
                if (deadNow && !_deathTracePostWindow) { _deathTracePostWindow = true; _deathTraceDeathSimMinute = nowMin; }
                if (deadNow)
                {
                    var since = (nowMin - _deathTraceDeathSimMinute + 1440) % 1440;
                    if (CheckEnabled("deathrel"))
                    {
                        DeathRelTick(nowMin, since, realElapsed);
                        return;
                    }
                    if (CheckEnabled("ghosttrace"))
                    {
                        GhostTraceTick(nowMin, since, realElapsed);
                        return;
                    }
                    if (since >= 10 || realElapsed > 25) { DeathTraceEvaluate("dead"); return; }
                }
                else if (realElapsed > 20 || simElapsed > 240)
                {
                    DeathTraceEvaluate("budget");
                    return;
                }
            }
            catch (Exception dse)
            {
                Log("AUTOTEST deathtrace EXC " + dse.GetType().Name + " " + dse.Message);
                DeathTraceEvaluate("exception");
            }
        }

        private static int _deathTraceLastPollMin = -1;
        private static bool _deathTracePostWindow;
        private static int _deathTraceDeathSimMinute = -1;
        private static short _deathDlgLastObj;
        private static DateTime _deathDlgLastRelease;

        // (SIM-06) 'deathrel' battery state: death -> ghost night -> REAL user save
        // (TS1GameScreen.Save: vm marshal -> FSOV -> SaveHouse + SaveNeighbourhood(true))
        // -> lot reload (PlayHouse) -> assert the death/ghost/aftermath state on the
        // reloaded lot. The night phase reuses R220's urn law verbatim (21:55 arm,
        // natural 22:00 gate, disclosed 4109 Force-Ghost fallback).
        private static int _deathRelPhase;
        private static bool _deathRelDone;
        private static DateTime _deathRelPhaseStart = DateTime.UtcNow;
        private static VM _deathRelOldVm;
        private static short _deathRelHouseId = -1;
        private static bool _deathRelClockArmed, _deathRelGhostSpawned, _deathRelForceUsed;
        private static bool _deathRelTombstonePre, _deathRelTombstonePost, _deathRelGhostAvatarPost;
        private static bool _deathRelDeadPreserved, _deathRelControlIntact;
        private static bool _deathRelControlCaptured;
        private static short _deathRelDeadNeighborId = -1;
        private static short _deathRelControlNeighborId = -1;
        private static uint _deathRelDeadGuid, _deathRelControlGuid;
        private static int _deathRelDeadPd68Pre = int.MinValue, _deathRelDeadPd87Pre = int.MinValue, _deathRelDeadPd32Pre = int.MinValue;
        private static int _deathRelStore68Pre = int.MinValue, _deathRelStore68Post = int.MinValue;
        private static bool _deathRelLateNight;
        private static int _deathRelSpawnNightMin = -1, _deathRelForceNightMin = -1;
        private static string _deathRelReloadException;
        private static bool _deathRelRetriedFromTemplate;

        // (Round 219) PASS law (never weaker than observed, never invented): the failure
        // HANDLER ran (8198/8197/8199/8309 — these only execute past the < -98 gate), the
        // KILL ran (Global 393 frame seen OR a death-artifact create event), and the dead
        // state landed (PersonData[68]==1 / entity.Dead / entity removed). The ghost loop
        // (8641), the reaper/tombstone split and the type-32 value are logged evidence —
        // they close the trace but are timing-dependent, not pass conditions.
        private static void DeathTraceEvaluate(string why)
        {
            DeathTraceVerdict(why);
            Finish();
        }

        // the deathtrace verdict without finishing the run — the ghosttrace phase keeps
        // state 4 alive after death and issues this first, then its own verdict.
        private static void DeathTraceVerdict(string why)
        {
            if (_deathTraceDone) return;
            _deathTraceDone = true;
            StopDeathTraceObservation();
            try
            {
                var handlerSeen = _deathTraceIds.Contains(8198) || _deathTraceIds.Contains(8197)
                    || _deathTraceIds.Contains(8199) || _deathTraceIds.Contains(8309);
                var killSeen = _deathTraceIds.Contains(393) || _deathTraceIds.Contains(316)
                    || _deathTraceCreates.Count > 0;
                var deadConfirmed = _deathFlagSeen || _deathDeadFlagSeen || _deathEntityGone;
                var ghostSeen = _deathTraceIds.Contains(8641) || _deathTraceIds.Contains(8306);
                var realMin = Math.Round((DateTime.UtcNow - _deathTraceCollapseReal).TotalMinutes, 1);
                Log("AUTOTEST deathtrace summary why=" + why +
                    " handlerSeen=" + handlerSeen + " killSeen=" + killSeen +
                    " deadConfirmed=" + deadConfirmed + " ghostSeen=" + ghostSeen +
                    " realMin=" + realMin +
                    " ids=[" + string.Join(",", _deathTraceIds.OrderBy(x => x)) + "]" +
                    " creates=[" + string.Join(" | ", _deathTraceCreates) + "]" +
                    " killStack=" + (_deathTraceStackAtKill ?? "none") +
                    " timeline=[" + string.Join(" | ", _deathTraceTimeline) + "]" +
                    " (original PersonGlobals/Global natural-death path; R77's +3 collapse never crossed the -98 gate)");
                var live = handlerSeen && killSeen && deadConfirmed;
                if (live) Pass("deathtrace"); else Fail("deathtrace");
            }
            catch (Exception ee)
            {
                Log("AUTOTEST deathtrace evaluate EXC " + ee.GetType().Name + " " + ee.Message);
                Fail("deathtrace");
            }
        }

        // (Round 220) the ghost night-watch phase. After the death settle, set the clock to
        // 21:55 — the urn's OWN night gate (main ins5 Global[0]>=22, read live from
        // Context.Clock.Hours) then crosses naturally — and watch the 1-in-8 night roll.
        // Deterministic fallback after night+45 with no spawn: push the urn's own
        // 'Force Ghost' TTAB interaction (the engine's debug tree, disclosed).
        private static void GhostTraceTick(int nowMin, int sinceDeath, double realElapsed)
        {
            try
            {
                if (_screen != null && !_screen.InLot)
                {
                    Log("AUTOTEST ghosttrace: LOT UNLOADED mid-watch (commuting adults take the last living family sim)");
                    GhostTraceEvaluate("lot-unloaded");
                    return;
                }
                if (!_ghostPhaseStarted)
                {
                    if (sinceDeath < 5) return;
                    _ghostPhaseStarted = true;
                    try
                    {
                        _vm.Context.Clock.Hours = 21;
                        _vm.Context.Clock.Minutes = 55;
                        _vm.Context.Clock.MinuteFractions = 0;
                    }
                    catch (Exception je) { Log("AUTOTEST ghosttrace clock-set EXC " + je.GetType().Name); }
                    Log("AUTOTEST ghosttrace: night approach armed — clock set to 21:55 (the urn's own gate crosses NATURALLY at 22:00); urn=" +
                        (_ghostUrn == null ? "NOT FOUND (no tombstone create observed)" : ("obj" + _ghostUrn.ObjectID)) +
                        "; law: per ~30-sim-min night pass 4096 'main' rolls rnd(0..BCON4097[3]=8), on 0 -> 4100 'generate ghost'");
                    return;
                }
                // minutes since 22:00 (wrap-aware); <0 means we are in the day tail before the gate
                int nightMin = (nowMin >= 22 * 60) ? nowMin - 22 * 60
                    : (nowMin < 6 * 60 ? nowMin + 1440 - 22 * 60 : -1);
                if (nightMin < 0)
                {
                    if (realElapsed > 25) GhostTraceEvaluate("clock-miss");
                    return;
                }
                if (!_ghostForcePushed && !_ghostIds.Contains(4100) && nightMin >= 45) PushUrnForceGhost();
                if (nightMin >= 240 || realElapsed > 25) GhostTraceEvaluate(nightMin >= 240 ? "night-complete" : "budget");
            }
            catch (Exception ge)
            {
                Log("AUTOTEST ghosttrace EXC " + ge.GetType().Name + " " + ge.Message);
                GhostTraceEvaluate("exception");
            }
        }

        private static void PushUrnForceGhost()
        {
            _ghostForcePushed = true;
            try
            {
                if (_ghostUrn == null) { Log("AUTOTEST ghosttrace: force-push skipped (no urn entity)"); return; }
                var iff = _ghostUrn.Object.Resource.MainIff;
                var ttabs = iff.List<FSO.Files.Formats.IFF.Chunks.TTAB>();
                int idx = -1;
                foreach (var tt in ttabs)
                {
                    if (tt?.Interactions == null) continue;
                    for (int i = 0; i < tt.Interactions.Length; i++)
                        if (tt.Interactions[i].ActionFunction == 4109) { idx = i; break; }
                    if (idx >= 0) break;
                }
                if (idx < 0) { Log("AUTOTEST ghosttrace: force-push skipped (no TTAB entry with action 4109)"); return; }
                var action = _ghostUrn.GetAction(idx, _ghostUrn, _vm.Context, false);
                if (action == null) { Log("AUTOTEST ghosttrace: force-push GetAction null"); return; }
                action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                _ghostUrn.Thread.EnqueueAction(action);
                Log("AUTOTEST ghosttrace: FORCE-GHOST fallback pushed (urn TTAB idx " + idx +
                    " -> 4109 'Force Ghost', the engine's own debug tree — DISCLOSED: the natural 1-in-8 night roll did not fire by night+45)");
            }
            catch (Exception pe) { Log("AUTOTEST ghosttrace force-push EXC " + pe.GetType().Name + " " + pe.Message); }
        }

        // (Round 220) PASS law: the ghost SPAWNED — 4100 'generate ghost' ran (naturally or
        // via the disclosed Force-Ghost fallback) OR any ghost-behaviour frame executed
        // (the person-side 8641 loop family or the urn-side Ghost Walk/Scare). Natural
        // spawn vs fallback is logged, never conflated.
        private static void GhostTraceEvaluate(string why)
        {
            if (_ghostTraceDone) return;
            DeathTraceVerdict(why + "/ghost");
            _ghostTraceDone = true;
            try
            {
                var ghostLoopSeen = _ghostIds.Contains(8641) || _ghostIds.Contains(8638)
                    || _ghostIds.Contains(8640) || _ghostIds.Contains(8642);
                var ghostSpawned = _ghostIds.Contains(4100) || ghostLoopSeen
                    || _ghostIds.Contains(4103) || _ghostIds.Contains(4111);
                Log("AUTOTEST ghosttrace summary why=" + why +
                    " ghostSpawned=" + ghostSpawned + " naturalSpawn=" + _ghostNaturalSpawn +
                    " forcePushed=" + _ghostForcePushed + " ghostLoopSeen=" + ghostLoopSeen +
                    " ghostIds=[" + string.Join(",", _ghostIds.OrderBy(x => x)) + "]" +
                    " timeline=[" + string.Join(" | ", _deathTraceTimeline.Where(l => l.StartsWith("ghosttrace"))) + "]" +
                    " (urn night law: 22:00-01:59, 1-in-8 per ~30-sim-min pass, cap 3)");
                if (ghostSpawned) Pass("ghosttrace"); else Fail("ghosttrace");
            }
            catch (Exception ee)
            {
                Log("AUTOTEST ghosttrace evaluate EXC " + ee.GetType().Name + " " + ee.Message);
                Fail("ghosttrace");
            }
            Finish();
        }

        // (SIM-06) the deathrel phase machine. Dispatched from StateDeathTrace's dead
        // branch instead of the deathtrace/ghosttrace evaluators; reuses their evidence
        // fields (_deathFlagSeen/_deathDeadFlagSeen/_deathEntityGone/_deathTraceCreates/
        // _ghostUrn/_ghostIds) plus R220's urn night law for the ghost-spawn leg.
        private static void DeathRelTick(int nowMin, int sinceDeath, double realElapsed)
        {
            try
            {
                // run-1 defect: _ghostIds stayed empty because WalkDeathWatchStack only
                // samples ghost ids once _ghostPhaseStarted is set (GhostTraceTick's flag).
                // Arm it at battery entry so the whole deathrel window is sampled.
                if (!_ghostPhaseStarted)
                {
                    _ghostPhaseStarted = true;
                    _ghostIds.Clear();
                }
                if (_screen != null && !_screen.InLot && _deathRelPhase < 3)
                {
                    // like ghosttrace: the lot can unload under the battery (e.g. the
                    // commute takes the last living sim). Honest end, no reload leg.
                    DeathRelEvaluate("lot-unloaded");
                    return;
                }
                switch (_deathRelPhase)
                {
                    case 0: DeathRelAftermath(nowMin, sinceDeath); break;
                    case 1: DeathRelNightWatch(nowMin, realElapsed); break;
                    case 2: DeathRelSave(); break;
                    case 3: DeathRelReloadDispatch(); break;
                    case 4: DeathRelWaitReload(); break;
                    case 5: DeathRelAssert(); break;
                }
            }
            catch (Exception dre)
            {
                Log("AUTOTEST deathrel EXC phase=" + _deathRelPhase + " " + dre.GetType().Name + " " + dre.Message);
                DeathRelEvaluate("exception");
            }
        }

        // p0: settle window after the death landed — capture the dead sim's identity
        // (NeighbourId/GUID + person-data words 68/87/32), a living control sim, the
        // tombstone, and the STORE-side death record baseline (what a family re-activation
        // would resurrect from), then hand to the night watch.
        private static void DeathRelAftermath(int nowMin, int sinceDeath)
        {
            var neigh = Content.Get().Neighborhood;
            if (_deathRelDeadNeighborId < 0)
            {
                var a0 = (_avatars != null && _avatars.Count > 0) ? _avatars[0] : null;
                if (a0 != null)
                {
                    try { _deathRelDeadNeighborId = a0.GetPersonData(VMPersonDataVariable.NeighborId); } catch { }
                    try { _deathRelDeadGuid = a0.Object?.OBJ?.GUID ?? 0; } catch { }
                    try { _deathRelDeadPd68Pre = a0.GetPersonData((VMPersonDataVariable)68); } catch { }
                    try { _deathRelDeadPd87Pre = a0.GetPersonData((VMPersonDataVariable)87); } catch { }
                    try { _deathRelDeadPd32Pre = a0.GetPersonData((VMPersonDataVariable)32); } catch { }
                }
                foreach (var a in _avatars ?? new List<VMAvatar>())
                {
                    if (a == null || ReferenceEquals(a, a0)) continue;
                    try
                    {
                        _deathRelControlNeighborId = a.GetPersonData(VMPersonDataVariable.NeighborId);
                        _deathRelControlGuid = a.Object?.OBJ?.GUID ?? 0;
                        _deathRelControlCaptured = _deathRelControlNeighborId > 0;
                        if (_deathRelControlCaptured) break;
                    }
                    catch { }
                }
                try
                {
                    var rec = neigh.GetNeighborByID(_deathRelDeadNeighborId);
                    _deathRelStore68Pre = (rec != null && rec.PersonData != null && rec.PersonData.Length > 68)
                        ? rec.PersonData[68] : int.MinValue;
                }
                catch { }
                _deathRelTombstonePre = _ghostUrn != null;
                Log("AUTOTEST deathrel captured dead nid=" + _deathRelDeadNeighborId + " guid=0x" + _deathRelDeadGuid.ToString("X8")
                    + " pd68=" + _deathRelDeadPd68Pre + " pd87=" + _deathRelDeadPd87Pre + " pd32=" + _deathRelDeadPd32Pre
                    + " store68=" + (_deathRelStore68Pre == int.MinValue ? "n/a" : _deathRelStore68Pre.ToString())
                    + " tombstone=" + _deathRelTombstonePre
                    + " control nid=" + _deathRelControlNeighborId + " guid=0x" + _deathRelControlGuid.ToString("X8"));
            }
            if (sinceDeath < 5) return; // settle window, mirrors ghosttrace
            _deathRelPhase = 1;
            _deathRelPhaseStart = DateTime.UtcNow;
        }

        // p1: R220's urn night law. Run-1 defect fix: the reaper sequence races the clock
        // (6:40 -> ~23:00), so the phase can START deep inside the night — thresholds keyed
        // to "minutes since 22:00" then fire their exit on the first tick. Now: if already
        // night at arm, give the natural roll a short 8-night-min window before the
        // disclosed 4109 Force-Ghost fallback; exits are phase-relative, not night-absolute.
        private static void DeathRelNightWatch(int nowMin, double realElapsed)
        {
            int nightMin = (nowMin >= 22 * 60) ? nowMin - 22 * 60
                : (nowMin < 6 * 60 ? nowMin + 1440 - 22 * 60 : -1);
            if (!_deathRelClockArmed)
            {
                _deathRelClockArmed = true;
                _deathRelLateNight = nightMin >= 0;
                if (!_deathRelLateNight)
                {
                    try
                    {
                        _vm.Context.Clock.Hours = 21;
                        _vm.Context.Clock.Minutes = 55;
                        _vm.Context.Clock.MinuteFractions = 0;
                    }
                    catch (Exception je) { Log("AUTOTEST deathrel clock-set EXC " + je.GetType().Name); }
                }
                Log("AUTOTEST deathrel: night phase armed at " + (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"))
                    + " (lateNight=" + _deathRelLateNight + (_deathRelLateNight ? ", already past the 22:00 urn gate" : " — clock set to 21:55") + "); urn=" +
                    (_ghostUrn == null ? "NOT FOUND" : "obj" + _ghostUrn.ObjectID));
                return;
            }
            var ghostLoopSeen = _ghostIds.Contains(8641) || _ghostIds.Contains(8638)
                || _ghostIds.Contains(8640) || _ghostIds.Contains(8642);
            if (!_deathRelGhostSpawned && (_ghostIds.Contains(4100) || ghostLoopSeen
                || _ghostIds.Contains(4103) || _ghostIds.Contains(4111)))
            {
                _deathRelGhostSpawned = true;
                _deathRelSpawnNightMin = nightMin;
                var gh = _vm.Entities.OfType<VMAvatar>().FirstOrDefault(a =>
                {
                    try { return a.GetPersonData(VMPersonDataVariable.NeighborId) == _deathRelDeadNeighborId; }
                    catch { return false; }
                });
                Log("AUTOTEST deathrel: GHOST SPAWNED (4100/ghost-loop ids seen; natural=" + _ghostNaturalSpawn
                    + ") ghostAvatar=" + (gh == null ? "not-yet-bound" : "obj" + gh.ObjectID));
            }
            if (nightMin < 0)
            {
                if ((DateTime.UtcNow - _deathRelPhaseStart).TotalMinutes > 6) { DeathRelEvaluate("clock-miss"); }
                return;
            }
            if (_deathRelGhostSpawned && _deathRelSpawnNightMin >= 0 && nightMin >= _deathRelSpawnNightMin + 5)
            {
                // give any ghost-side walk/scare a short live window, then freeze the
                // state into a REAL user save while the ghost is in the lot
                _deathRelPhase = 2;
                _deathRelPhaseStart = DateTime.UtcNow;
                return;
            }
            var naturalWindow = _deathRelLateNight ? 8 : 45;
            if (!_deathRelGhostSpawned && !_ghostForcePushed && _ghostUrn != null && nightMin >= naturalWindow)
            {
                _deathRelForceUsed = true;
                _deathRelForceNightMin = nightMin;
                PushUrnForceGhost();
            }
            if (!_deathRelGhostSpawned && _ghostForcePushed && _deathRelForceNightMin >= 0
                && nightMin >= _deathRelForceNightMin + 150)
            {
                // run-2 defect: 15 night-min starved the 4109 debug tree (its own idles
                // precede the 4100 spawn); R220's law allowed the fallback up to night+240.
                DeathRelEvaluate("no-ghost");
                return;
            }
            if ((DateTime.UtcNow - _deathRelPhaseStart).TotalMinutes > 10)
            {
                DeathRelEvaluate(_deathRelGhostSpawned ? "night-complete" : "no-ghost");
            }
        }

        // p2: the REAL user save path — TS1GameScreen.Save() serializes the whole VM
        // marshal into the house file's FSOV chunk and calls SaveNeighbourhood(true).
        private static void DeathRelSave()
        {
            _deathRelPhase = 3;
            _deathRelPhaseStart = DateTime.UtcNow;
            GameThread.NextUpdate(x =>
            {
                try
                {
                    _screen.Save();
                    Log("AUTOTEST deathrel: user save path executed (TS1GameScreen.Save -> FSOV + SaveHouse + SaveNeighbourhood(true))");
                }
                catch (Exception se)
                {
                    Log("AUTOTEST deathrel save EXC " + se.GetType().Name + " " + se.Message);
                }
            });
        }

        // p3: boot the SAME house back through the harness's own public choke point.
        private static void DeathRelReloadDispatch()
        {
            if ((DateTime.UtcNow - _deathRelPhaseStart).TotalSeconds < 5) return; // let the save land first
            _deathRelOldVm = _vm;
            try { short.TryParse(_houses[Math.Min(_houseIdx, _houses.Length - 1)], out _deathRelHouseId); } catch { }
            if (_deathRelHouseId <= 0) { DeathRelEvaluate("no-house-id"); return; }
            _deathRelPhase = 4;
            _deathRelPhaseStart = DateTime.UtcNow;
            GameThread.NextUpdate(x =>
            {
                try
                {
                    _screen.PlayHouse(_deathRelHouseId, null);
                    Log("AUTOTEST deathrel: PlayHouse(" + _deathRelHouseId + ") dispatched (reload from the just-saved file)");
                }
                catch (Exception pe)
                {
                    _deathRelReloadException = pe.GetType().Name + ": " + pe.Message;
                    var st = (pe.StackTrace ?? "").Split('\n');
                    Log("AUTOTEST deathrel PlayHouse EXC " + _deathRelReloadException
                        + " stack=[" + string.Join(" | ", st.Take(6)).Trim() + "]");
                }
            });
        }

        // p4: wait for the re-mounted lot and re-bind like StateWaitLot (new VM instance
        // proves the old one was torn down), then assert. Run-3 defect fix: a reload that
        // threw (EndOfStreamException inside the port's own save->load path) still flips
        // InLot with an EMPTY vm — require a non-empty entity list, and if the reloaded
        // lot is broken, move the saved user house file aside and retry from the template
        // so the assert separates "save file unloadable" from "restored but state lost".
        private static void DeathRelWaitReload()
        {
            if (_screen.InLot && _screen.vm != null && !ReferenceEquals(_screen.vm, _deathRelOldVm)
                && _screen.vm.Entities.Count > 0)
            {
                _vm = _screen.vm;
                _avatars = _vm.Entities.Where(e => e is VMAvatar).Cast<VMAvatar>().ToList();
                if (_vm.SpeedMultiplier <= 0)
                {
                    _vm.SpeedMultiplier = 1;
                    _vm.GlobalBlockingDialog = null;
                }
                Log("AUTOTEST deathrel: LOT-RELOADED house=" + _deathRelHouseId + " entities=" + _vm.Entities.Count
                    + " avatars=" + _avatars.Count + " loadErrors=" + _vm.LoadErrors.Count
                    + " fromTemplate=" + _deathRelRetriedFromTemplate
                    + " reloadException=" + (_deathRelReloadException ?? "none"));
                _deathRelPhase = 5;
                _deathRelPhaseStart = DateTime.UtcNow;
                return;
            }
            var waited = (DateTime.UtcNow - _deathRelPhaseStart).TotalSeconds;
            if (!_deathRelRetriedFromTemplate && waited > 25)
            {
                // the just-saved user house file did not produce a live lot (run 3: the
                // restore path threw EndOfStreamException and left an empty vm). Move it
                // aside and boot from the template instead: the assert then measures the
                // RESURRECTION law (family re-activation from a death-blind store).
                _deathRelRetriedFromTemplate = true;
                try
                {
                    var userHouse = Content.Get().Neighborhood.GetHousePath(_deathRelHouseId);
                    if (File.Exists(userHouse))
                    {
                        var len = new FileInfo(userHouse).Length; // stat BEFORE the move (run-4 defect: FileInfo.Length re-stats post-move and threw)
                        var aside = userHouse + ".deathrel-unloadable";
                        File.Move(userHouse, aside, true);
                        Log("AUTOTEST deathrel: reload produced no live lot (waited " + Math.Round(waited) + "s"
                            + ", exception=" + (_deathRelReloadException ?? "none") + "); moved the saved user file aside: "
                            + Path.GetFileName(userHouse) + " len=" + len + " -> template retry");
                    }
                    _deathRelOldVm = _vm;
                    _deathRelPhaseStart = DateTime.UtcNow;
                    // GetHousePath is unconditional on the user path (run-5 finding: with
                    // the user file moved aside, PlayHouse has nothing to read). The
                    // template is ContentManager.TS1BasePath/<neigh dir>/Houses/<name>;
                    // the autotest boots the shipped UserData neighborhood.
                    try
                    {
                        var template = Path.Combine(Content.Get().TS1BasePath,
                            "UserData", "Houses", Path.GetFileName(userHouse));
                        if (!File.Exists(userHouse) && File.Exists(template))
                        {
                            File.Copy(template, userHouse, true);
                            Log("AUTOTEST deathrel: template house restored for the retry (len=" + new FileInfo(template).Length + ")");
                        }
                    }
                    catch (Exception te) { Log("AUTOTEST deathrel template-copy EXC " + te.GetType().Name + " " + te.Message); }
                    GameThread.NextUpdate(x =>
                    {
                        try { _screen.PlayHouse(_deathRelHouseId, null); }
                        catch (Exception pe2)
                        {
                            _deathRelReloadException += " | template-retry: " + pe2.GetType().Name + ": " + pe2.Message;
                            Log("AUTOTEST deathrel template-retry EXC " + pe2.GetType().Name + " " + pe2.Message);
                        }
                    });
                    return;
                }
                catch (Exception re) { Log("AUTOTEST deathrel remediation EXC " + re.GetType().Name + " " + re.Message); }
            }
            if (waited > 90)
            {
                DeathRelEvaluate("reload-timeout inlot=" + (_screen?.InLot ?? false));
            }
        }

        // p5: the preservation assert on the reloaded lot. Preservation law (acceptance:
        // "preserve death and ghost-wander behavior through save/reload"): the death is
        // still EFFECTIVE iff the dead sim is present with the dead flag (68=1), OR the
        // ghost avatar carries it forward, OR (entity removed at death, the R219 norm)
        // the tombstone survived AND the store record now carries the death for the
        // night respawn. Anything else = the reload resurrects the sim (fix card).
        private static void DeathRelAssert()
        {
            var tombstone = _vm.Entities.FirstOrDefault(e =>
            {
                try { return (e?.Object?.OBJ?.GUID ?? 0) == DeathTombstoneGuid; }
                catch { return false; }
            });
            _deathRelTombstonePost = tombstone != null;
            VMAvatar dead = null, control = null;
            foreach (var a in _vm.Entities.OfType<VMAvatar>())
            {
                short nid = -1;
                try { nid = a.GetPersonData(VMPersonDataVariable.NeighborId); } catch { }
                if (nid == _deathRelDeadNeighborId && _deathRelDeadNeighborId > 0) dead = a;
                else if (nid == _deathRelControlNeighborId && _deathRelControlNeighborId > 0) control = a;
            }
            int pd68 = int.MinValue, pd87 = int.MinValue, pd32 = int.MinValue;
            if (dead != null)
            {
                try { pd68 = dead.GetPersonData((VMPersonDataVariable)68); } catch { }
                try { pd87 = dead.GetPersonData((VMPersonDataVariable)87); } catch { }
                try { pd32 = dead.GetPersonData((VMPersonDataVariable)32); } catch { }
            }
            // read the store BEFORE computing the verdict — run-2 measured a stale
            // _deathRelStore68Post (0) here and mis-rejected a correct store record.
            try
            {
                var rec = Content.Get().Neighborhood.GetNeighborByID(_deathRelDeadNeighborId);
                _deathRelStore68Post = (rec != null && rec.PersonData != null && rec.PersonData.Length > 68)
                    ? rec.PersonData[68] : int.MinValue;
            }
            catch { }
            _deathRelGhostAvatarPost = _ghostIds.Contains(4100) && dead != null; // the 4100-bound ghost avatar restored with the dead identity
            _deathRelDeadPreserved = (dead != null && pd68 == 1) || _deathRelGhostAvatarPost
                || (_deathRelTombstonePost && dead == null && _deathRelStore68Post == 1);
            if (control != null)
            {
                bool cDead = false, cFlag = false;
                try { cDead = control.Dead; } catch { }
                try { cFlag = control.GetPersonData((VMPersonDataVariable)68) == 1; } catch { }
                _deathRelControlIntact = !cDead && !cFlag;
            }
            Log("AUTOTEST deathrel assert: tombstone=" + _deathRelTombstonePost
                + " deadEntity=" + (dead != null ? "obj" + dead.ObjectID + " pd68=" + pd68 + " pd87=" + pd87 + " pd32=" + pd32 : "ABSENT")
                + " controlIntact=" + _deathRelControlIntact
                + " store68=" + (_deathRelStore68Post == int.MinValue ? "n/a" : _deathRelStore68Post.ToString())
                + " (pre-save store68=" + (_deathRelStore68Pre == int.MinValue ? "n/a" : _deathRelStore68Pre.ToString()) + ")");
            DeathRelEvaluate("asserted");
        }

        private static void DeathRelEvaluate(string why)
        {
            if (_deathRelDone) return;
            _deathRelDone = true;
            StopDeathTraceObservation();
            try
            {
                var deathConfirmed = _deathFlagSeen || _deathDeadFlagSeen || _deathEntityGone;
                var killed = _deathTraceIds.Contains(393) || _deathTraceIds.Contains(316) || _deathTraceCreates.Count > 0;
                var reloaded = _deathRelPhase >= 5;
                Log("AUTOTEST deathrel RESULT why=" + why
                    + " deathConfirmed=" + deathConfirmed + " killed=" + killed
                    + " ghostSpawned=" + _deathRelGhostSpawned + " naturalSpawn=" + _ghostNaturalSpawn + " forceUsed=" + _deathRelForceUsed
                    + " tombstonePre=" + _deathRelTombstonePre
                    + " tombstonePost=" + (reloaded ? _deathRelTombstonePost.ToString() : "n/a")
                    + " deadPreserved=" + (reloaded ? _deathRelDeadPreserved.ToString() : "n/a")
                    + " controlIntact=" + (reloaded ? (_deathRelControlCaptured ? _deathRelControlIntact.ToString() : "no-control") : "n/a")
                    + " reloaded=" + reloaded + " templateFallback=" + _deathRelRetriedFromTemplate
                    + " reloadException=" + (_deathRelReloadException ?? "none")
                    + " store68 pre/post=" + (_deathRelStore68Pre == int.MinValue ? "n/a" : _deathRelStore68Pre.ToString())
                    + "/" + (_deathRelStore68Post == int.MinValue ? "n/a" : _deathRelStore68Post.ToString())
                    + " ghostIds=[" + string.Join(",", _ghostIds.OrderBy(x => x)) + "]"
                    + " creates=[" + string.Join(" | ", _deathTraceCreates) + "]");
                var ok = deathConfirmed && killed && _deathRelGhostSpawned && reloaded
                    && !_deathRelRetriedFromTemplate
                    && _deathRelTombstonePost && _deathRelDeadPreserved
                    && (!_deathRelControlCaptured || _deathRelControlIntact);
                if (ok)
                {
                    Pass("deathrel");
                    Log("AUTOTEST deathrel verdict: death, ghost night-spawn and aftermath state survived a REAL user save + lot reload");
                }
                else
                {
                    Fail("deathrel");
                    if (_deathRelRetriedFromTemplate)
                        Log("AUTOTEST deathrel fix-card: the user save (TS1GameScreen.Save) produced a house file the port itself cannot reload"
                            + " (reload exception: " + (_deathRelReloadException ?? "empty lot") + ")"
                            + " — the FSOV lot round-trip is broken; the template retry then resurrects the dead sim (store68="
                            + (_deathRelStore68Post == int.MinValue ? "n/a" : _deathRelStore68Post.ToString()) + "), so death does not survive any reload");
                    else if (deathConfirmed && killed && reloaded && !_deathRelDeadPreserved)
                        Log("AUTOTEST deathrel fix-card: the reloaded lot lost the death state (dead entity absent/alive again, tombstone="
                            + _deathRelTombstonePost + ", store68=" + (_deathRelStore68Post == int.MinValue ? "n/a" : _deathRelStore68Post.ToString())
                            + ") — the port does not carry the dead flag across the save/reload cycle; native preserves it");
                }
            }
            catch (Exception re)
            {
                Log("AUTOTEST deathrel evaluate EXC " + re.GetType().Name + " " + re.Message);
                Fail("deathrel");
            }
            Finish();
        }

        private static void CarpoolDiscovery()
        {
            try
            {
                if (_carpoolDiscoveryDone) return;
                _carpoolDiscoveryDone = true;
                var now = _vm.Context.Clock.Hours * 60 + _vm.Context.Clock.Minutes;
                int earliest = -1;
                int latestEnd = -1;
                string plan = "";
                var jobs = Content.Get().Jobs;
                _careerExpectedPay = 0;
                _schoolReturnFixtureValid = false;
                _schoolChildAvatarId = 0;
                _schoolChildInitialGrade = -1;
                _schoolChildFinalGrade = -1;
                _schoolStartHour = -1;
                _schoolEndHour = -1;
                _schoolReturnEndElapsed = -1;
                _schoolTargetElapsed = -1;
                _schoolBusSeenBaseIds.Clear();
                _schoolBusFrameIds.Clear();
                _schoolCarGlobalFrameIds.Clear();
                _schoolAtSchoolFrameSites.Clear();
                _schoolSendFrameIps.Clear();
                _schoolSendActiveEntities.Clear();
                _schoolSendLastSites.Clear();
                _schoolSendActionStarts = 0;
                _schoolSendPrimaryRouteSeen = false;
                _schoolSendFallbackRouteSeen = false;
                _schoolSendFalseExitSeen = false;
                _schoolSendHiddenLatchSeen = false;
                _schoolChildHiddenLatchSeen = false;
                _schoolFixturePendingBusSeen = false;
                _schoolFixtureCancelEvents = 0;
                _schoolFixtureAbortEvents = 0;
                _schoolFixtureBlockerUid = 0;
                _schoolFixtureBlockerCancelElapsed = -1;
                _schoolBusGroupMax = 0;
                _schoolOutboundBusSeen = false;
                _schoolBusDisappearedBetweenLegs = false;
                _schoolReturnBusSeen = false;
                _schoolReturnBusDisappeared = false;
                _schoolChildSchoolStateSeen = false;
                _schoolChildHomeStateSeen = false;
                _schoolAtSchoolFrameSeen = false;
                _schoolAtSchoolFrameActive = false;
                _schoolFinalLogicalHome = false;
                _schoolBusLastGroups = null;
                _schoolChildLastState = null;
                _missChildOowSeen = false;
                _missChildFinalAway = -1;
                _missBusCancelSeen = false;
                _missBusCancelUid = 0;
                _missGradeSettledElapsed = -1;
                try { _careerBudgetBase = _vm.TS1State?.CurrentFamily?.Budget ?? 0; } catch { _careerBudgetBase = 0; }
                // (Round 222) CHANCETRACE fixture: the same House-5 worker (obj21, Science
                // level 0), re-based by the probe to job level 5 so the day's 4103 'get paid'
                // takes the Chance Card fork with a KNOWN card. Static decode (r222 law doc):
                // 4134 'Chance Cards 3' dispatches expansion careers 17-21 and cascades base
                // careers to 4124 'Chance Cards 2' (careers 1-10) -> 4133 (12-16); career 9
                // (Science) at level 5 lands on the Science02 card (4124 ins53 level==5 ->
                // dialog ins55 STR#301 msg 21 = entry [20] 'Your latest invention is a huge
                // success!' -> budget +5000 at ins56, PD[12]/PD[11] skill bumps, PD[24]=1).
                // The fork gate is 4103 ins38-43: level != 0, then Local[6] = min of two
                // rnd(0..99) rolls; MyPD[63] > Local[6] -> 4104 'test promotion', else F54 ->
                // CALL 4134 directly. The probe collapses PD[63] to -50 one hour before the
                // level-5 CARR end (past the morning warn/fire pass, before the return/pay),
                // making ins43 deterministically false.
                _chanceFixtureValid = false;
                if (CheckEnabled("chancetrace") && !CheckEnabled("carreturn") && jobs != null)
                {
                    var employed = _avatars.Where(x =>
                    {
                        try { return x.GetPersonData(VMPersonDataVariable.JobType) > 0; }
                        catch { return false; }
                    }).ToList();
                    if (employed.Count == 1)
                    {
                        var worker = employed[0];
                        var jtype = worker.GetPersonData(VMPersonDataVariable.JobType);
                        var jlevel = worker.GetPersonData(VMPersonDataVariable.JobPromotionLevel);
                        var level5 = jobs.GetJobLevel(jtype, 5);
                        _chanceFixtureValid = worker.ObjectID == 21 && jtype == 9 && jlevel == 0
                            && level5 != null && level5.StartTime > 0 && level5.EndTime > level5.StartTime;
                        if (_chanceFixtureValid)
                        {
                            _chanceWorkerAvatarId = worker.ObjectID;
                            _chancePerfAtMinute = (level5.EndTime - 1) * 60;
                            try
                            {
                                worker.SetPersonData(VMPersonDataVariable.JobPromotionLevel, 5);
                                // (R222 run-2 discovery) THE PROBABILITY GATE: 4134's entry is
                                // ins90 (PD[24]==0) -> ins121 Temp[0]=rnd(0..99) -> ins122
                                // 'Temp[0] < Tuning[135]' = BCON 4097 key 7 = 12 (a 12% card
                                // chance per pay — run 2 rolled it honestly and missed). The
                                // probe mounts the worker's TuningReplacement for (4097, 7) at
                                // 100 so the card fires deterministically (VMMemory checks the
                                // replacement BEFORE the BCON — the mounted-tuning precedent of
                                // R163's tuning[132]).
                                var carPortalFx = Content.Get().TS1Global.Get("CarPortal.iff") as IffFile;
                                var tuningFx = carPortalFx?.Get<BCON>(4097);
                                var cardOdds = (tuningFx?.Constants != null && tuningFx.Constants.Length > 7)
                                    ? tuningFx.Constants[7] : -1;
                                try
                                {
                                    if (worker.TuningReplacement == null)
                                        worker.TuningReplacement = new FSO.SimAntics.Entities.VMEntityTuning(worker, _vm);
                                    worker.TuningReplacement.AppendTable(
                                        new Dictionary<int, Dictionary<int, short>> {
                                            { 4097, new Dictionary<int, short> { { 7, 100 } } } });
                                    // R222 run-3: the odds override did not change the outcome —
                                    // either the roll frame's Callee is the PORTAL (the routine's
                                    // code owner) rather than the worker, or the failing gate is
                                    // ins90 (PD[24]) before the roll. The portal copy of the
                                    // override mounts where _carPortal is cached (below), and the
                                    // worker-stack tracer (routine:ip history) names the exact
                                    // failing node.
                                }
                                catch (Exception tex)
                                {
                                    Log("AUTOTEST chancetrace tuning-override EXC " + tex.GetType().Name + " " + tex.Message);
                                }
                                Log("AUTOTEST chancetrace fixture obj=21 Science level 0->5 (probe state-set, the R219 hunger-collapse precedent)" +
                                    " level5CARR start=" + level5.StartTime + " end=" + level5.EndTime + " salary=" + level5.Salary +
                                    " perf-collapse-at=" + (_chancePerfAtMinute / 60) + ":00" +
                                    " card-odds BCON4097[7]=" + cardOdds + " probe-override=100 (rnd(0..99) < 100 always -> the card fires)" +
                                    " expected-card: 4134:90/121/122 -> 4134:2-6 (career not 17..21) -> 4124 via 4134:120 -> 4124:10 (career 9)" +
                                    " -> 4124:53 (level==5) -> dialog 4124:55 STR#301[20] -> 4124:56 budget +5000");
                            }
                            catch (Exception cfx)
                            {
                                _chanceFixtureValid = false;
                                Log("AUTOTEST chancetrace fixture level-set EXC " + cfx.GetType().Name + " " + cfx.Message);
                            }
                        }
                        else
                        {
                            Log("AUTOTEST chancetrace fixture INVALID obj=" + worker.ObjectID +
                                " jtype=" + jtype + " jlevel=" + jlevel +
                                " level5=" + (level5 == null ? "null" : (level5.StartTime + "-" + level5.EndTime)));
                        }
                    }
                    else Log("AUTOTEST chancetrace fixture INVALID employed=" + employed.Count);
                }
                foreach (var a in _avatars)
                {
                    int jtype = 0, jlevel = 0, jperf = 0;
                    try { jtype = a.GetPersonData(VMPersonDataVariable.JobType); } catch { }
                    try { jlevel = a.GetPersonData(VMPersonDataVariable.JobPromotionLevel); } catch { }
                    try { jperf = a.GetPersonData(VMPersonDataVariable.JobPerformance); } catch { }
                    _careerJobBase[a.ObjectID] = new int[] { jperf, jlevel };
                    int st = -1;
                    int et = -1;
                    int salary = 0;
                    string track = "";
                    if (jobs != null && jtype > 0)
                    {
                        try
                        {
                            // R157: the tree's JobData[12] read uses the sim's OWN promotion
                            // level (4100 ins10: Temp[1] = StkObjPD[57]; ins48: JobData[12]) —
                            // r156 read level 0 here, which happens to match this fixture but
                            // is not the tree's law.
                            var lvl = jobs.GetJobLevel((short)jtype, jlevel);
                            st = (lvl?.StartTime) ?? -1;
                            et = (lvl?.EndTime) ?? -1;
                            salary = (lvl?.Salary) ?? 0;
                            track = (lvl?.JobName ?? "").Trim();
                        }
                        catch { }
                    }
                    if (st >= 0 && st * 60 < now)
                    {
                        st += 24; // start already past today -> roll to tomorrow
                        if (et >= 0) et += 24;
                    }
                    if (st >= 0 && et >= 0 && et <= st) et += 24; // overnight shift
                    if (st >= 0 && (earliest < 0 || st * 60 < earliest)) earliest = st * 60;
                    if (et >= 0 && (latestEnd < 0 || et * 60 > latestEnd)) latestEnd = et * 60;
                    if (st >= 0) _careerExpectedPay += salary;
                    plan += (plan.Length == 0 ? "" : " | ") + "obj=" + a.ObjectID + " jtype=" + jtype +
                        " jlevel=" + jlevel + " jperf=" + jperf + " start=" + (st < 0 ? "-" : st.ToString()) +
                        " end=" + (et < 0 ? "-" : et.ToString()) + " salary=" + salary + " track=" + track;
                }
                // The long carreturn check is deliberately fixture-specific. House 5 has
                // exactly one employed resident: obj21, Science level 0 (155, 9:00-15:00).
                // On the successful-promotion branch, CarPortal 4103 first increments PD57,
                // reloads Local[0] from the NEW JobData[1], then pays Local[8] = Local[0] *
                // tuning[132] at ins51 followed by Local[0] at ins9. For House 5 this is the
                // level-1 Science salary 230 with original BCON 4097 key 4 == 2: 460 + 230.
                // Observe those exact primitive calls; the final household delta can also contain
                // unrelated purchases/expenses during the long natural shift.
                _careerReturnFixtureValid = false;
                _careerPromotedSalaryExpected = 0;
                _careerPayTuningExpected = 0;
                _careerPromotionBonusExpected = 0;
                if ((CheckEnabled("carreturn") || CheckEnabled("carskip")) && jobs != null)
                {
                    var employed = _avatars.Where(x =>
                    {
                        try { return x.GetPersonData(VMPersonDataVariable.JobType) > 0; }
                        catch { return false; }
                    }).ToList();
                    if (employed.Count == 1)
                    {
                        var worker = employed[0];
                        var jtype = worker.GetPersonData(VMPersonDataVariable.JobType);
                        var jlevel = worker.GetPersonData(VMPersonDataVariable.JobPromotionLevel);
                        var level = jobs.GetJobLevel(jtype, jlevel);
                        var next = jobs.GetJobLevel(jtype, jlevel + 1);
                        var carPortal = Content.Get().TS1Global.Get("CarPortal.iff") as IffFile;
                        var payTuning = carPortal?.Get<BCON>(4097);
                        var bonusMultiplier = (payTuning?.Constants != null && payTuning.Constants.Length > 4)
                            ? payTuning.Constants[4] : 0;
                        _careerReturnFixtureValid = worker.ObjectID == 21 && jtype == 9 && jlevel == 0
                            && level != null && level.Salary == 155 && level.StartTime == 9 && level.EndTime == 15
                            && next != null && next.Salary == 230 && bonusMultiplier == 2;
                        if (_careerReturnFixtureValid)
                        {
                            _careerReturnAvatarId = worker.ObjectID;
                            _careerReturnExpectedLevel = jlevel + 1;
                            _careerPromotedSalaryExpected = next.Salary;
                            _careerPayTuningExpected = bonusMultiplier;
                            _careerPromotionBonusExpected = _careerPromotedSalaryExpected * bonusMultiplier;
                            _careerExpectedPay = _careerPromotedSalaryExpected + _careerPromotionBonusExpected;
                        }
                    }
                }
                if (CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss"))
                {
                    try
                    {
                        var children = _avatars.Where(x =>
                        {
                            try { return x.GetPersonData(VMPersonDataVariable.PersonsAge) < 18; }
                            catch { return false; }
                        }).ToList();
                        var child = children.Count == 1 ? children[0] : null;
                        if (child != null)
                        {
                            _schoolChildAvatarId = child.ObjectID;
                            _schoolChildInitialGrade = child.GetPersonData(VMPersonDataVariable.JobPromotionLevel);
                        }
                        var carPortal = Content.Get().TS1Global.Get("CarPortal.iff") as IffFile;
                        var schoolTuning = carPortal?.Get<BCON>(4097);
                        if (schoolTuning?.Constants != null && schoolTuning.Constants.Length > 3)
                        {
                            _schoolStartHour = schoolTuning.Constants[2];
                            _schoolEndHour = schoolTuning.Constants[3];
                        }
                        var schoolBus = Content.Get().WorldObjects.Get(SchoolBusGuid);
                        var schoolGuidMounted = schoolBus?.OBJ != null && schoolBus.OBJ.IsMaster
                            && schoolBus.OBJ.GUID == SchoolBusGuid
                            && schoolBus.Resource?.MainIff?.Filename?.Equals(
                                "SchoolBus.iff", StringComparison.OrdinalIgnoreCase) == true;
                        var nid = child?.GetPersonData(VMPersonDataVariable.NeighborId) ?? (short)-1;
                        var personType = child?.GetPersonData(VMPersonDataVariable.PersonType) ?? (short)-1;
                        var age = child?.GetPersonData(VMPersonDataVariable.PersonsAge) ?? (short)-1;
                        var job = child?.GetPersonData(VMPersonDataVariable.JobType) ?? (short)0;
                        var childGuid = child?.Object?.OBJ?.GUID ?? 0;
                        var house5 = _houses[Math.Min(_houseIdx, _houses.Length - 1)] == "5"
                            && Path.GetFileName(_loadPath).Equals("House05.iff", StringComparison.OrdinalIgnoreCase);
                        _schoolReturnFixtureValid = house5 && children.Count == 1 && child != null
                            && child.ObjectID == 16 && childGuid == SchoolChildGuid
                            && nid == SchoolChildNeighborId && personType == 0 && age == 9 && job == -1
                            && _schoolChildInitialGrade == 4 && _schoolStartHour == 9
                            && _schoolEndHour == 15 && schoolGuidMounted;
                        Log("AUTOTEST schoolreturn fixture house5=" + house5 + " children=" + children.Count
                            + " path=" + Path.GetFileName(_loadPath)
                            + " obj=" + (child?.ObjectID ?? 0) + " guid=0x" + childGuid.ToString("X8")
                            + " nid=" + nid + " personType=" + personType + " age=" + age
                            + " job=" + job + " grade=" + _schoolChildInitialGrade
                            + " school=" + _schoolStartHour + "-" + _schoolEndHour
                            + " busGuidMounted=" + schoolGuidMounted
                            + " valid=" + _schoolReturnFixtureValid);
                    }
                    catch (Exception sfe)
                    {
                        Log("AUTOTEST schoolreturn fixture EXC " + sfe.GetType().Name + " " + sfe.Message);
                    }
                }
                var iffCounts = new Dictionary<string, int>();
                foreach (var e in _vm.Entities)
                {
                    string iff = null;
                    try { iff = e?.Object?.Resource?.MainIff?.Filename; } catch { }
                    if (string.IsNullOrEmpty(iff)) continue;
                    if (iffCounts.ContainsKey(iff)) iffCounts[iff]++; else iffCounts[iff] = 1;
                }
                var carIffs = iffCounts.Where(kv => kv.Key.IndexOf("car", StringComparison.OrdinalIgnoreCase) >= 0)
                    .Select(kv => kv.Key + "x" + kv.Value).ToList();
                Log("AUTOTEST carseek discovery avatars=" + _avatars.Count + " plan=[" + plan + "]");
                Log("AUTOTEST carseek discovery distinct-mounted-IFFs=" + iffCounts.Count +
                    " car-ifffs=[" + string.Join(",", carIffs) + "]");
                if (CheckEnabled("carreturn") || CheckEnabled("chancetrace") || CheckEnabled("schoolmiss")) StartCareerBudgetObservation();
                if (CheckEnabled("carreturn") || CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss")) StartCareerCreateObservation();
                foreach (var kv in iffCounts.OrderByDescending(k => k.Value).Take(30))
                    Log("AUTOTEST carseek discovery iff=" + kv.Key + " entities=" + kv.Value);
                // IFF-factual id->label map of every car-named mounted IFF (anchors any observed
                // frame ids to ORIGINAL BHAV labels - never from memory).
                var carIffObjects = new Dictionary<string, IffFile>();
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var ifff = e?.Object?.Resource?.MainIff;
                        if (ifff?.Filename != null && ifff.Filename.IndexOf("car", StringComparison.OrdinalIgnoreCase) >= 0)
                            if (!carIffObjects.ContainsKey(ifff.Filename)) carIffObjects[ifff.Filename] = ifff;
                    }
                    catch { }
                }
                foreach (var kv in carIffObjects)
                {
                    try
                    {
                        var labels = new List<string>();
                        var bl = kv.Value.List<BHAV>();
                        if (bl != null)
                            foreach (var b in bl)
                                labels.Add(b.ChunkID + ":" + (b.ChunkLabel ?? "").Trim());
                        Log("AUTOTEST carseek IFF-label-map " + kv.Key + " bhavs=[" + string.Join(",", labels) + "]");
                        if (kv.Key.IndexOf("car", StringComparison.OrdinalIgnoreCase) >= 0 && bl != null)
                        {
                            // R155 fix 2: CarPortal.iff has NO chunk 280 (verified by direct
                            // parse) — the live 'idle'(280) frames are global.iff's routine
                            // executed on the portal's frame SCOPE. Label-anchor only the three
                            // real chunks; 280 stays required as a portal-scope id in the pass law.
                            bool m4096 = false, m4100 = false, m4125 = false;
                            foreach (var b in bl)
                            {
                                var lbl = (b.ChunkLabel ?? "").Trim();
                                if (b.ChunkID == 4100 && lbl.Equals("process", StringComparison.OrdinalIgnoreCase)) { _carIff4100Process = true; m4100 = true; }
                                if (b.ChunkID == 4096 && lbl.Equals("main", StringComparison.OrdinalIgnoreCase)) m4096 = true;
                                if (b.ChunkID == 4125 && lbl.Equals("process warnings car pools", StringComparison.OrdinalIgnoreCase)) m4125 = true;
                            }
                            if (m4096 && m4100 && m4125) _carLabelsAnchored = true;
                        }
                    }
                    catch (Exception le)
                    {
                        Log("AUTOTEST carseek IFF-label-map EXC " + kv.Key + " " + le.GetType().Name);
                    }
                }
                // R155 diagnostics for the OPEN commute-tail residual: CarPortal 'process' (4100)
                // dispatches 'Create Car' (4106) only when its guard chain (per-portal Attrs 0/2/3/7/8,
                // Global[0]/[1], avatar JobType 56 / PersonType 32 / word 69, JobData[12] start hour)
                // lines up. Log the inputs once at discovery so a future soak can see which one fails.
                try
                {
                    var portal = _vm.Entities.FirstOrDefault(e =>
                    {
                        try { return e?.Object?.Resource?.MainIff?.Filename?.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase) == true; }
                        catch { return false; }
                    });
                    _carPortal = portal;
                    // (R222 run-3) the chance-odds override's portal copy: VMMemory resolves
                    // Tuning reads through frame.Callee — for the Chance Card roll frame that
                    // may be the routine's code owner (this portal) rather than the worker.
                    // Mounted on both candidates so the roll is deterministic either way.
                    if (CheckEnabled("chancetrace") && portal != null)
                    {
                        try
                        {
                            if (portal.TuningReplacement == null)
                                portal.TuningReplacement = new FSO.SimAntics.Entities.VMEntityTuning(portal, _vm);
                            portal.TuningReplacement.AppendTable(
                                new Dictionary<int, Dictionary<int, short>> {
                                    { 4097, new Dictionary<int, short> { { 7, 100 } } } });
                            Log("AUTOTEST chancetrace tuning-override mounted on portal obj=" + portal.ObjectID);
                        }
                        catch (Exception ptex) { Log("AUTOTEST chancetrace portal-override EXC " + ptex.GetType().Name + " " + ptex.Message); }
                    }
                    if (portal != null)
                    {
                        var attrs = new List<string>();
                        for (short a = 0; a <= 8; a++)
                        {
                            try { attrs.Add(a + "=" + portal.GetAttribute(a)); } catch { attrs.Add(a + "=err"); }
                        }
                        Log("AUTOTEST carseek portal-attrs [" + string.Join(",", attrs) + "]");
                    }
                    foreach (var a in _avatars)
                    {
                        int jt = 0, pt = 0, w69 = 0, w69b = 0, ov34 = 0;
                        try { jt = a.GetPersonData(VMPersonDataVariable.JobType); } catch { }
                        try { pt = a.GetPersonData(VMPersonDataVariable.PersonType); } catch { }
                        try { w69 = a.GetPersonData((VMPersonDataVariable)69); } catch { }
                        try { w69b = a.GetPersonData((VMPersonDataVariable)68); } catch { }
                        try { ov34 = a.GetValue((VMStackObjectVariable)34); } catch { }
                        Log("AUTOTEST carseek commute-inputs obj=" + a.ObjectID + " JobType=" + jt +
                            " PersonType=" + pt + " w68=" + w69b + " w69=" + w69 + " objVar34=" + ov34);
                    }
                }
                catch (Exception pde) { Log("AUTOTEST carseek commute-inputs EXC " + pde.GetType().Name); }
                // R157 dialog-latch probe at discovery (see the hourly probe in StateCarpool).
                try
                {
                    var gbd0 = _vm.GlobalBlockingDialog;
                    string gbd0Iff = null;
                    if (gbd0 != null) { try { gbd0Iff = gbd0.Object?.Resource?.MainIff?.Filename; } catch { } }
                    Log("AUTOTEST carseek dialog-state@discovery gbd=" + (gbd0 == null ? "null" : (gbd0.ObjectID + "/" + (gbd0Iff ?? "?"))) +
                        " speed=" + _vm.SpeedMultiplier + " lastSpeed=" + _vm.LastSpeedMultiplier);
                }
                catch { }
                var scheduleStart = earliest;
                if ((CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss")) && _schoolStartHour >= 0)
                {
                    var schoolStartMinute = _schoolStartHour * 60;
                    if (scheduleStart < 0 || schoolStartMinute < scheduleStart)
                        scheduleStart = schoolStartMinute;
                }
                if (scheduleStart < 0)
                {
                    Log("AUTOTEST carseek: no avatar has a CARR StartTime job or mounted school schedule; blind 30-min diagnostic soak");
                    _carpoolTargetMin = now + 30;
                }
                else
                {
                    // R156 WINDOW FIX (law corrected R157): CarPortal 'process' (4100) fires
                    // 'Create Car' (4106) when Global[0] == Attr[0]-1 — ONE hour before the
                    // bookmarked work start (live chain ins34 -> ins20 (Local[3]-=1) -> ins17;
                    // the r155/r156 "-2" reading followed ins12-14, DEAD CODE — both pointers
                    // equal (T34/F34), the -2 compare is 4125's warning staging). The bookmark
                    // (ins48-54) writes Attr[0] = JobData[12] in the SAME hourly run that
                    // matches hour == JobData[12]-1. The gate fixture loads at 8:00 with a
                    // 9:00 job: the 8:00 spawn window is ALWAYS missed and no carpool can
                    // ever fire. Harness action (equivalent to the player setting the clock —
                    // no engine change): rewind the VM clock before the spawn window so the
                    // soak observes it naturally. Margin -125 min still covers BOTH windows
                    // (start-2 warnings and start-1 car).
                    int windowStart = scheduleStart - 125; // (start-2h) - 5min scheduler margin
                    if (windowStart < 0) windowStart += 24 * 60;
                    if (now > windowStart && _vm.Context.Clock != null)
                    {
                        int delta = now - windowStart;
                        _vm.Context.Clock.Hours = windowStart / 60;
                        _vm.Context.Clock.Minutes = windowStart % 60;
                        _vm.Context.Clock.MinuteFractions = 0;
                        _vm.Context.Clock.Ticks -= (long)delta * _vm.Context.Clock.TicksPerMinute;
                        Log("AUTOTEST carseek clock-rewind (harness): " + (now / 60) + ":" + (now % 60).ToString("00")
                            + " -> " + (windowStart / 60) + ":" + (windowStart % 60).ToString("00")
                            + " (Create Car window = StartTime-2h; fixture loads past it)");
                        now = windowStart;
                    }
                    var longEnd = -1;
                    if ((CheckEnabled("carreturn") || CheckEnabled("chancetrace")) && latestEnd >= 0) longEnd = latestEnd;
                    if ((CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss")) && _schoolEndHour >= 0)
                    {
                        var schoolEndMinute = _schoolEndHour * 60;
                        if (longEnd < 0 || schoolEndMinute > longEnd) longEnd = schoolEndMinute;
                    }
                    _carpoolTargetMin = longEnd >= 0
                        ? (longEnd + 75) % (24 * 60) // display clock; elapsed targets below survive midnight
                        : scheduleStart + 75; // +75 min gives the morning commute a full hour+ to dispatch
                    _careerElapsedMinutes = 0;
                    _careerElapsedClockMin = now;
                    if ((CheckEnabled("carreturn") || CheckEnabled("chancetrace")) && latestEnd >= 0)
                    {
                        var endClock = ((latestEnd % (24 * 60)) + (24 * 60)) % (24 * 60);
                        _careerReturnEndElapsed = (endClock - now + (24 * 60)) % (24 * 60);
                        _careerTargetElapsed = _careerReturnEndElapsed + 75;
                    }
                    // (SIM-04) carskip: soak 2 extra full workday cycles (+2h margin) so the
                    // missed-work warn/fire ladder (4126) can walk its countdown naturally.
                    if (CheckEnabled("carskip")) _careerTargetElapsed += 2 * 24 * 60 + 120;
                    // (SIM-02) simjrn: give the journey battery a comfortable window
                    if (CheckEnabled("simjrn")) _careerTargetElapsed += 12 * 60;
                    if ((CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss")) && _schoolEndHour >= 0)
                    {
                        var schoolEndClock = _schoolEndHour * 60;
                        _schoolReturnEndElapsed = (schoolEndClock - now + (24 * 60)) % (24 * 60);
                        // The outbound fixture takes almost two sim-hours from creation
                        // through visible-group removal. Give the return leg the same
                        // lifecycle ceiling; the state loop can finish earlier once the
                        // bus is gone and the original child is stably home.
                        _schoolTargetElapsed = _schoolReturnEndElapsed + 135;
                    }
                    var waitTarget = -1;
                    if (CheckEnabled("carreturn") || CheckEnabled("chancetrace")) waitTarget = _careerTargetElapsed;
                    if ((CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss")) && _schoolTargetElapsed > waitTarget)
                        waitTarget = _schoolTargetElapsed;
                    Log("AUTOTEST carseek: earliest CARR StartTime=" + earliest
                        + " schoolStart=" + _schoolStartHour + " scheduleStart=" + scheduleStart
                        + " target=" + _carpoolTargetMin +
                        " returnEnd=" + latestEnd + " expectedPay=" + _careerExpectedPay +
                        " promotedSalary=" + _careerPromotedSalaryExpected +
                        " promotionBonus=" + _careerPromotionBonusExpected +
                        " tuning132=" + _careerPayTuningExpected + " fixture=" + _careerReturnFixtureValid +
                        " schoolEnd=" + _schoolEndHour + " schoolFixture=" + _schoolReturnFixtureValid +
                        " budgetBase=" + _careerBudgetBase + " targetElapsed=" + _careerTargetElapsed +
                        " schoolTargetElapsed=" + _schoolTargetElapsed +
                        " (wait " + (waitTarget >= 0 ? waitTarget : (_carpoolTargetMin - now)) +
                        " sim-min)");
                }
                _carpoolLastMin = -1;
            }
            catch (Exception cde) { Log("AUTOTEST carseek discovery EXC " + cde.GetType().Name + " " + cde.Message); }
        }

        // (SIM-04) carskip: per-soak-tick probe for the missed-work warn/fire ladder.
        // Deletes every spawned CarJunk car (the worker cannot board -> the workday is
        // missed naturally), watches the worker's job/level/countdown words and the
        // portal ladder routines (4125/4126/4127), and detects the ladder's warning
        // object (4126 ins11/18 createObjectInstance GUID 0xF7870464) and the fire
        // transition (JobType PD[56] -> 0). All sampling is read-only except the car
        // deletions, which model a player removing the carpool car.
        private static void CareerSkipTick()
        {
            try
            {
                if (_vm == null) return;

                // (e) morning state-set (R222 probe-state-set precedent): walk the ladder
                // deterministically. 4126 computes Local[1] = Global[1] - PD[69] per workday
                // pass (10:00 for this fixture) with branches at Local[1]==2 (warning object)
                // and ==1 (final warning trees). Day 1 = natural miss (car deleted); each
                // later morning sets PD[69] = Global[1] - (2 | 1) to enter those branches;
                // day 4+ is left natural to observe the countdown/fire.
                if (_vm.Context.Clock.Hours == 8 && _vm.Context.Clock.Minutes < 8)
                {
                    int g1now = 0;
                    try { g1now = _vm.GetGlobalValue(1); } catch { }
                    if (_skipStateSetDay != g1now)
                    {
                        _skipStateSetDay = g1now;
                        _skipStateDayIndex++;
                        var sw = _avatars.FirstOrDefault(x => x.ObjectID == _careerReturnAvatarId)
                                 ?? _avatars.FirstOrDefault();
                        if (sw != null && _skipStateDayIndex >= 2)
                        {
                            try
                            {
                                int target = _skipStateDayIndex == 2 ? g1now - 2 : (_skipStateDayIndex == 3 ? g1now - 1 : -999);
                                int before = sw.GetPersonData((VMPersonDataVariable)69);
                                if (target != -999 && before != target)
                                {
                                    sw.SetPersonData((VMPersonDataVariable)69, (short)target);
                                    Log("AUTOTEST carskip state-set PD[69] " + before + " -> " + target +
                                        " (Local[1] = Global[1](" + g1now + ") - PD[69] = " + (g1now - target) +
                                        " -> " + (g1now - target == 2 ? "WARNING" : "FINAL WARNING") + " branch at the 10:00 pass)");
                                }
                            }
                            catch (Exception sse2) { Log("AUTOTEST carskip state-set EXC " + sse2.Message); }
                        }
                    }
                }

                // (a) stack scan: ladder routines live on any thread this tick
                bool saw4126 = false, saw4127 = false;
                List<VMEntity> entities;
                try { entities = _vm.Entities.ToList(); }
                catch { return; }
                foreach (var e in entities)
                {
                    var stack = e?.Thread?.Stack;
                    if (stack == null) continue;
                    foreach (var fr in stack)
                    {
                        var id = fr?.Routine?.Chunk?.ChunkID ?? 0;
                        if (id == 4126) saw4126 = true;
                        if (id == 4127) saw4127 = true;
                    }
                }
                if (saw4126 && !_skip4126Seen)
                {
                    _skip4126Seen = true;
                    Log("AUTOTEST carskip B7: 4126 'warn/fire people who miss work' ON STACK (first live sighting; r157 never observed it)");
                }
                if (saw4127) _skip4127Seen = true;

                // (b) warning-object detection (4126 ins11/18 GUID 0xF7870464)
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var g = e?.Object?.GUID ?? 0;
                        if ((uint)(g & 0xFFFFFFFF) == 0xF7870464u || ((g >> 32) & 0xFFFFFFFF) == 0xF7870464u)
                        {
                            if (!_skipWarnObjSeen)
                            {
                                _skipWarnObjSeen = true;
                                Log("AUTOTEST carskip B7/B8: ladder warning object 0xF7870464 spawned (obj" + e.ObjectID + ")");
                            }
                        }
                    }
                    catch { }
                }

                // (c) delete spawned CarJunk cars -> the worker cannot board
                foreach (var e in entities)
                {
                    try
                    {
                        if (e == null || e.Dead || _skipDeletedBaseIds.Contains(e.ObjectID)) continue;
                        var iff = e?.Object?.Resource?.MainIff?.Filename;
                        if (iff != null && iff.Equals("CarJunk.iff", StringComparison.OrdinalIgnoreCase))
                        {
                            _skipDeletedBaseIds.Add(e.ObjectID);
                            _skipCarsDeleted++;
                            Log("AUTOTEST carskip: deleting carpool car obj" + e.ObjectID + " at " +
                                _vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00") +
                                " (worker misses the ride; workday counts as missed)");
                            _vm.RemoveEntity(e);
                        }
                    }
                    catch { }
                }

                // (d) worker state watch (obj21 fixture: job 9 Science; PD words 56/57/63/69/24)
                var w = _avatars.FirstOrDefault(x => x.ObjectID == _careerReturnAvatarId)
                        ?? _avatars.FirstOrDefault();
                if (w != null)
                {
                    int p56 = 0, p57 = 0, p63 = 0, p69 = 0, p24 = 0;
                    try { p56 = w.GetPersonData(VMPersonDataVariable.JobType); } catch { }
                    try { p57 = w.GetPersonData(VMPersonDataVariable.JobPromotionLevel); } catch { }
                    try { p63 = w.GetPersonData(VMPersonDataVariable.JobPerformance); } catch { }
                    try { p69 = w.GetPersonData((VMPersonDataVariable)69); } catch { }
                    try { p24 = w.GetPersonData((VMPersonDataVariable)24); } catch { }
                    int g0 = 0, g1 = 0;
                    try { g0 = _vm.GetGlobalValue(0); } catch { }
                    try { g1 = _vm.GetGlobalValue(1); } catch { }
                    bool fireNow = _skipLastPd56 > 0 && p56 == 0;
                    if (p69 != _skipLastPd69 || p56 != _skipLastPd56 || g1 != _skipLastGlobal1)
                    {
                        var line = "pd69=" + p69 + " pd56=" + p56 + " pd57=" + p57 + " pd24=" + p24
                            + " g0=" + g0 + " g1=" + g1 + " at " + _vm.Context.Clock.Hours + ":" +
                            _vm.Context.Clock.Minutes.ToString("00");
                        if (_skipPdLog.Count == 0 || _skipPdLog[_skipPdLog.Count - 1] != line)
                        {
                            _skipPdLog.Add(line);
                            Log("AUTOTEST carskip watch " + line);
                        }
                        _skipLastPd69 = p69; _skipLastPd56 = p56; _skipLastGlobal1 = g1;
                    }
                    if (fireNow && !_skipFireSeen)
                    {
                        _skipFireSeen = true;
                        Log("AUTOTEST carskip B9: FIRED — JobType PD[56] " + _skipLastPd56 + " -> 0 (job cleared by the missed-work ladder)");
                    }
                }
            }
            catch (Exception ske) { Log("AUTOTEST carskip tick EXC " + ske.GetType().Name + " " + ske.Message); }
        }

        // (SIM-15) deterministic single-shift protocol. At the day-1 08:00 morning:
        // - career5day: hold the worker's boarding-critical motives maxed through the
        //   hour so the 4128 mood-miss cannot recur (carreturn's pins then hold).
        // - career5level: additionally state-set PD[57]=5 (Science level 5) and
        //   PD[63]=-50 (collapsed performance) — SIM-04's passing chancetrace shape —
        //   so the SAME shift's pay window (4103:54) cascades the Science02 chance
        //   card. One shift, no day-2 dependency; wall time inside the detached-
        //   process survival window.
        private static void CareerProtocolTick()
        {
            try
            {
                if (_vm == null) return;
                if (_vm.Context.Clock.Hours != 8) return;
                var w = _avatars.FirstOrDefault(x => x.ObjectID == _careerReturnAvatarId)
                         ?? _avatars.FirstOrDefault();
                if (w == null) return;

                if (CheckEnabled("career5day"))
                {
                    try
                    {
                        w.SetMotiveData(VMMotive.Energy, 100);
                        w.SetMotiveData(VMMotive.Hunger, 100);
                        w.SetMotiveData(VMMotive.Fun, 100);
                        w.SetMotiveData(VMMotive.Social, 100);
                        w.SetMotiveData(VMMotive.Comfort, 100);
                    }
                    catch (Exception m5) { Log("AUTOTEST career5day motive set EXC " + m5.Message); }
                }

                int g1now = 0;
                try { g1now = _vm.GetGlobalValue(1); } catch { }
                if (_c5StateSetDay == g1now) return;
                _c5StateSetDay = g1now;

                if (CheckEnabled("career5level") && !_c5LevelSet)
                {
                    try
                    {
                        int lvlBefore = w.GetPersonData(VMPersonDataVariable.JobPromotionLevel);
                        w.SetPersonData(VMPersonDataVariable.JobPromotionLevel, 5);
                        w.SetPersonData(VMPersonDataVariable.JobPerformance, -50);
                        _c5LevelSet = true; _c5CollapseSet = true;
                        Log("AUTOTEST career5level state-set PD[57] " + lvlBefore + " -> 5 (Science level 5), PD[63] -> -50 (collapsed performance)");
                    }
                    catch (Exception c5) { Log("AUTOTEST career5level state-set EXC " + c5.GetType().Name + " " + c5.Message); }
                }
            }
            catch (Exception c5e) { Log("AUTOTEST career5 protocol tick EXC " + c5e.GetType().Name + " " + c5e.Message); }
        }

        private static void StateCarpool()
        {
            if (_vm == null) { Finish(); return; }
            // (Round 222) CHANCETRACE player move — MUST run before the generic R157 unpause
            // below or it would orphan the card dialog before the probe can answer it. When the
            // blocking dialog's owner thread is sitting in the Chance Card cascade (a CarPortal
            // frame with id 4124/4133/4134 on its stack), the probe answers it as the player
            // through the exact VMNetDialogResponseCmd TS1 law: Responded=true, ResponseCode=0
            // (first choice -> the dialog primitive exits GOTO_TRUE into the card's effect
            // branch), restore LastSpeedMultiplier, clear GlobalBlockingDialog. The primitive's
            // own completion path then releases BlockingState and signals the UI closed.
            if (CheckEnabled("chancetrace")) ChanceTraceRespondDialog();
            // R157: with the dialog-latch fixed, the portal's warning dialogs (4125 ins11/15)
            // now actually SHOW and pause the VM — the soak is the player: unpause + orphan
            // the latch so the dialog's own 60-sim-sec timeout (engine r157) resumes the tree.
            if (_vm.SpeedMultiplier <= 0)
            {
                var staleDlg3 = _vm.GlobalBlockingDialog;
                _vm.SpeedMultiplier = 1;
                _vm.GlobalBlockingDialog = null;
                Log("AUTOTEST carseek unpause (stale-dialog-latch " + (staleDlg3 == null ? "none" : "obj" + staleDlg3.ObjectID) + " released)");
            }
            try
            {
                int now = _vm.Context.Clock.Hours * 60 + _vm.Context.Clock.Minutes;
                if (_careerElapsedClockMin < 0) _careerElapsedClockMin = now;
                if (now != _careerElapsedClockMin)
                {
                    var advance = now - _careerElapsedClockMin;
                    if (advance < 0) advance += 24 * 60;
                    _careerElapsedMinutes += advance;
                    _careerElapsedClockMin = now;
                }
                var afterCareerEnd = (CheckEnabled("carreturn") || CheckEnabled("chancetrace")) && _careerReturnEndElapsed >= 0
                    && _careerElapsedMinutes >= _careerReturnEndElapsed;

                // (Round 222) CHANCETRACE fork determinism: collapse the worker's job
                // performance (PD[63]) to -50 one hour before the level-5 CARR end. The
                // 4103 promotion fork (ins38-43) reads MyPD[63] > min(rnd(0..99), rnd(0..99));
                // -50 can never exceed a roll >= 0, so ins43 is deterministically false and
                // the F54 edge calls 4134 'Chance Cards 3' directly (no 4104 attempt). Timed
                // past the morning warn/fire pass (4125/4126 stage at the start hour) and
                // before the return/pay window; performance regen inside one sim-hour cannot
                // cross 0 from -50.
                if (CheckEnabled("chancetrace") && _chanceFixtureValid && !_chancePerfCollapsed
                    && _chancePerfAtMinute >= 0 && now >= _chancePerfAtMinute)
                {
                    _chancePerfCollapsed = true;
                    try
                    {
                        var cw = _avatars.FirstOrDefault(x => x.ObjectID == _chanceWorkerAvatarId);
                        if (cw != null)
                        {
                            var perfBefore = cw.GetPersonData(VMPersonDataVariable.JobPerformance);
                            cw.SetPersonData(VMPersonDataVariable.JobPerformance, -50);
                            _chancePerfSetMinute = now;
                            Log("AUTOTEST chancetrace perf-collapse PD[63] " + perfBefore + " -> -50 at " +
                                (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")) +
                                " (4103 ins43 MyPD[63] > min(rnd,rnd) now deterministically false -> ins54 CALL 4134)");
                        }
                    }
                    catch (Exception pce) { Log("AUTOTEST chancetrace perf-collapse EXC " + pce.GetType().Name + " " + pce.Message); }
                }

                // (a) car-named entities present right now (IFF-factual: entity Object resource IFF
                // filename carrying 'car' - e.g. CarPortal.iff / Carpool.iff if mounted on the lot).
                int carEnt = 0;
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var iff = e?.Object?.Resource?.MainIff?.Filename;
                        if (iff != null && iff.IndexOf("car", StringComparison.OrdinalIgnoreCase) >= 0) carEnt++;
                    }
                    catch { }
                }
                int portalEnt = 0;
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var iff = e?.Object?.Resource?.MainIff?.Filename;
                        if (iff != null && iff.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)) portalEnt++;
                    }
                    catch { }
                }
                if (portalEnt > _portalEntityMax) _portalEntityMax = portalEnt;
                if (carEnt > _carEntityMax) _carEntityMax = carEnt;
                // R158 METRIC FIX: spawnedCars counts DISTINCT MULTITILE GROUPS, not lot
                // entities — the r157 "18 cars" was this probe counting the 18 PARTS of ONE
                // car (CarJunk.iff = master + 18 slave OBJDs; spawn-detail: every part
                // g<base>x18, a 3x6 curb footprint). The port spawns ONE carpool car —
                // the original's law. [CarCreate] (engine mirror) confirmed a single
                // createObjectInstance (portal 4106:20) made it.
                int spawnedCars = 0;
                var seenCarBases = new HashSet<VMEntity>();
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var iff = e?.Object?.Resource?.MainIff?.Filename;
                        if (iff == null || iff.IndexOf("car", StringComparison.OrdinalIgnoreCase) < 0) continue;
                        if (iff.IndexOf("CarPortal", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                        if (iff.IndexOf("PaperCarrier", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                        VMEntity baseObject;
                        try { baseObject = e.MultitileGroup?.BaseObject ?? e; } catch { baseObject = e; }
                        if (seenCarBases.Add(baseObject)) spawnedCars++;
                    }
                    catch { }
                }
                foreach (var baseObject in seenCarBases)
                {
                    _careerSeenCarGroups.Add(baseObject);
                }
                if (spawnedCars > _spawnedCarMax)
                {
                    _spawnedCarMax = spawnedCars;
                    // R158: attribute the spawn COUNT — 18 entities appeared for ONE
                    // [CarCreate] (portal 4106:20). Break each car entity down by multitile
                    // group (base id, group size, position) so the count law is exact.
                    try
                    {
                        var detail = new List<string>();
                        foreach (var e in _vm.Entities)
                        {
                            try
                            {
                                var iff = e?.Object?.Resource?.MainIff?.Filename;
                                if (iff == null || iff.IndexOf("car", StringComparison.OrdinalIgnoreCase) < 0) continue;
                                if (iff.IndexOf("CarPortal", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                                if (iff.IndexOf("PaperCarrier", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                                var mg = e.MultitileGroup;
                                int gsz = 0, baseId = -1;
                                try { gsz = mg?.Objects?.Count ?? 0; baseId = mg?.BaseObject?.ObjectID ?? -1; } catch { }
                                var pos = e.Position;
                                detail.Add(e.ObjectID + "(g" + baseId + "x" + gsz + "@" + pos.TileX + "," + pos.TileY + ")");
                            }
                            catch { }
                        }
                        Log("AUTOTEST carseek spawn-detail n=" + spawnedCars + " [" + string.Join(",", detail) + "]");
                    }
                    catch (Exception sde) { Log("AUTOTEST carseek spawn-detail EXC " + sde.GetType().Name); }
                }
                if (carEnt != _carPrevEnt)
                {
                    _carPrevEnt = carEnt;
                    var present = new List<string>();
                    foreach (var e in _vm.Entities)
                    {
                        try
                        {
                            var iff = e?.Object?.Resource?.MainIff?.Filename;
                            if (iff != null && iff.IndexOf("car", StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                uint g = 0;
                                try { g = e.MasterDefinition?.GUID ?? 0; } catch { }
                                present.Add(iff + "#id" + e.ObjectID + (g == 0 ? "" : ("#guid" + g)));
                            }
                        }
                        catch { }
                    }
                    Log("AUTOTEST carseek car-entity-change carEnt=" + carEnt +
                        " present=[" + string.Join(",", present) + "]");
                }

                // R165: SchoolBus.iff has no "car" substring, so every older career census
                // skipped it. Creation starts out of world and the controller may outlive the
                // visible car, so track existing and actually in-world groups separately.
                if (CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss"))
                {
                    // Fixture-only determinism: SchoolBus 4103 naturally queues its
                    // UserDriven Go-to-School action (private 4098 / interaction 0). If a
                    // cancellable autonomous interaction is still active ahead of that
                    // exact authored action, request normal cancellation first. Only if
                    // the same blocker survives three sim-minutes do we abort that current
                    // interaction once. Never clear/rebuild the queue or cancel/reset the
                    // bus action; normal games never enter this -autotest-only branch.
                    if (_schoolReturnFixtureValid && _schoolOutboundCreateEvents == 1
                        && _schoolReturnCreateEvents == 0 && !_schoolBusDisappearedBetweenLegs
                        && !_schoolChildSchoolStateSeen)
                    {
                        try
                        {
                            var child = _vm.Entities.OfType<VMAvatar>()
                                .FirstOrDefault(x => x.ObjectID == _schoolChildAvatarId && !x.Dead
                                    && x.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                                    && x.GetPersonData(VMPersonDataVariable.TS1AtWorkSchool) == 0);
                            var thread = child?.Thread;
                            var queue = thread?.Queue;
                            if (queue != null)
                            {
                                var pendingBus = queue.Select((action, index) => new { action, index })
                                    .FirstOrDefault(x => x.index > thread.ActiveQueueBlock
                                        && x.action?.ActionRoutine?.ID == 4098
                                        && x.action.InteractionNumber == 0
                                        && x.action.CodeOwner?.Resource?.MainIff?.Filename?.Equals(
                                            "SchoolBus.iff", StringComparison.OrdinalIgnoreCase) == true
                                        && x.action.Callee?.MasterDefinition?.GUID == SchoolBusGuid);
                                if (pendingBus != null)
                                {
                                    _schoolFixturePendingBusSeen = true;
                                    var activeIndex = thread.ActiveQueueBlock;
                                    var active = activeIndex >= 0 && activeIndex < queue.Count
                                        ? queue[activeIndex] : null;
                                    var activeIsBus = active?.ActionRoutine?.ID == 4098
                                        && active.InteractionNumber == 0
                                        && active.CodeOwner?.Resource?.MainIff?.Filename?.Equals(
                                            "SchoolBus.iff", StringComparison.OrdinalIgnoreCase) == true
                                        && active.Callee?.MasterDefinition?.GUID == SchoolBusGuid;
                                    var activeCanCancel = active != null && !activeIsBus
                                        && active.Mode == FSO.SimAntics.Engine.VMQueueMode.Normal
                                        && !active.Flags.HasFlag(TTABFlags.MustRun);
                                    if (CheckEnabled("schoolmiss"))
                                    {
                                        // (SIM-05) schoolmiss inverts the success fixture: the
                                        // authored bus action loses its queue spot once (ordinary
                                        // queue-skip API), the blocker keeps the slot, and the
                                        // child never boards — the real missed-school law runs.
                                        if (pendingBus.action.UID != _missBusCancelUid)
                                        {
                                            _missBusCancelUid = pendingBus.action.UID;
                                            _missBusCancelSeen = true;
                                            // v2 (run1 finding): the authored bus action queues as
                                            // mode=Idle with MustRun-family flags, so CancelAction's
                                            // Normal-only queue-skip never removed it and the child
                                            // boarded anyway. Direct removal is the deterministic
                                            // fixture-only instrument (disclosed; normal play untouched).
                                            thread.Queue.Remove(pendingBus.action);
                                            Log("AUTOTEST schoolmiss bus-action queue-remove uid="
                                                + pendingBus.action.UID
                                                + " mode=" + pendingBus.action.Mode
                                                + " flags=" + pendingBus.action.Flags
                                                + " clock=" + (_vm.Context.Clock.Hours + ":"
                                                    + _vm.Context.Clock.Minutes.ToString("00")));
                                        }
                                    }
                                    else if (activeCanCancel && active.UID != _schoolFixtureBlockerUid)
                                    {
                                        var blocker = (active.CodeOwner?.Resource?.MainIff?.Filename ?? "?")
                                            + ":" + (active.ActionRoutine?.ID ?? 0)
                                            + " priority=" + active.Priority + " mode=" + active.Mode;
                                        _schoolFixtureBlockerUid = active.UID;
                                        _schoolFixtureBlockerCancelElapsed = _careerElapsedMinutes;
                                        _schoolFixtureCancelEvents++;
                                        thread.CancelAction(active.UID);
                                        Log("AUTOTEST schoolreturn fixture-unblock cancel="
                                            + _schoolFixtureCancelEvents + " blocker=" + blocker
                                            + " pending=SchoolBus.iff:4098 queue=" + queue.Count
                                            + " clock=" + (_vm.Context.Clock.Hours + ":"
                                                + _vm.Context.Clock.Minutes.ToString("00")));
                                    }
                                    else if (activeCanCancel && active.UID == _schoolFixtureBlockerUid
                                        && _schoolFixtureBlockerCancelElapsed >= 0
                                        && _careerElapsedMinutes - _schoolFixtureBlockerCancelElapsed >= 3
                                        && _schoolFixtureAbortEvents == 0)
                                    {
                                        thread.AbortCurrentInteraction();
                                        _schoolFixtureAbortEvents++;
                                        var busPreserved = queue.Contains(pendingBus.action);
                                        if (!busPreserved) _schoolReturnFixtureValid = false;
                                        Log("AUTOTEST schoolreturn fixture-unblock abort="
                                            + _schoolFixtureAbortEvents + " blockerUid=" + active.UID
                                            + " busPreserved=" + busPreserved + " queue=" + queue.Count
                                            + " clock=" + (_vm.Context.Clock.Hours + ":"
                                                + _vm.Context.Clock.Minutes.ToString("00")));
                                    }
                                }
                            }
                        }
                        catch (Exception sue)
                        {
                            Log("AUTOTEST schoolreturn fixture-unblock EXC "
                                + sue.GetType().Name + " " + sue.Message);
                        }
                    }

                    var schoolBusExistingBases = new HashSet<VMEntity>();
                    var schoolBusInWorldBases = new HashSet<VMEntity>();
                    foreach (var e in _vm.Entities)
                    {
                        try
                        {
                            var iff = e?.Object?.Resource?.MainIff?.Filename;
                            if (!"SchoolBus.iff".Equals(iff, StringComparison.OrdinalIgnoreCase)) continue;
                            VMEntity baseObject;
                            try { baseObject = e.MultitileGroup?.BaseObject ?? e; } catch { baseObject = e; }
                            schoolBusExistingBases.Add(baseObject);
                            _schoolBusSeenBaseIds.Add(baseObject.ObjectID);
                            var objects = baseObject.MultitileGroup?.Objects;
                            var inWorld = objects == null
                                ? !baseObject.Dead && baseObject.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                                : objects.Any(x => x != null && !x.Dead
                                    && x.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD);
                            if (inWorld) schoolBusInWorldBases.Add(baseObject);
                        }
                        catch { }
                    }
                    if (schoolBusInWorldBases.Count > _schoolBusGroupMax)
                        _schoolBusGroupMax = schoolBusInWorldBases.Count;
                    if (_schoolOutboundCreateEvents > 0 && _schoolReturnCreateEvents == 0
                        && schoolBusInWorldBases.Count > 0) _schoolOutboundBusSeen = true;
                    if (_schoolOutboundBusSeen && _schoolReturnCreateEvents == 0
                        && schoolBusInWorldBases.Count == 0) _schoolBusDisappearedBetweenLegs = true;
                    if (_schoolReturnCreateEvents > 0 && schoolBusInWorldBases.Count > 0)
                        _schoolReturnBusSeen = true;
                    if (_schoolReturnBusSeen && schoolBusInWorldBases.Count == 0)
                        _schoolReturnBusDisappeared = true;
                    var schoolExistingGroups = string.Join(",",
                        schoolBusExistingBases.Select(x => x.ObjectID).OrderBy(x => x));
                    var schoolGroups = string.Join(",",
                        schoolBusInWorldBases.Select(x => x.ObjectID).OrderBy(x => x));
                    if (_schoolBusLastGroups != schoolGroups)
                    {
                        _schoolBusLastGroups = schoolGroups;
                        Log("AUTOTEST schoolreturn bus-groups clock=" +
                            (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"))
                            + " existing=[" + schoolExistingGroups + "] inWorld=[" + schoolGroups
                            + "] max=" + _schoolBusGroupMax
                            + " outboundSeen=" + _schoolOutboundBusSeen
                            + " betweenGone=" + _schoolBusDisappearedBetweenLegs
                            + " returnSeen=" + _schoolReturnBusSeen
                            + " returnGone=" + _schoolReturnBusDisappeared);
                    }

                    // A SchoolBus routine can run on the bus thread or a pushed avatar
                    // interaction. Record every distinct instruction/caller/callee/stack
                    // site, but do not miscount a VMRoutingFrame copied from its parent as
                    // a second BHAV action (the first diagnostic run exposed that trap).
                    var atSchoolFrameActive = false;
                    var sendFrameEntities = new HashSet<short>();
                    foreach (var e in _vm.Entities)
                    {
                        try
                        {
                            var stack = e?.Thread?.Stack;
                            if (stack == null) continue;
                            foreach (var fr in stack)
                            {
                                if (fr == null) continue;
                                var owner = fr.ScopeResource?.MainIff?.Filename ?? "";
                                var id = (ushort)(fr.Routine?.Chunk?.ChunkID ?? 0);
                                if (fr is FSO.SimAntics.Engine.VMRoutingFrame) continue;
                                if (owner.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                                    && id == 4116)
                                {
                                    atSchoolFrameActive = true;
                                    _schoolAtSchoolFrameSeen = true;
                                    var atSchoolSite = "entity=" + e.ObjectID + " ip=" + fr.InstructionPointer
                                        + " caller=" + (fr.Caller?.ObjectID ?? 0)
                                        + "/nid" + ((fr.Caller as VMAvatar)?.GetPersonData(
                                            VMPersonDataVariable.NeighborId) ?? (short)-1)
                                        + " callee=" + (fr.Callee?.ObjectID ?? 0)
                                        + "/nid" + ((fr.Callee as VMAvatar)?.GetPersonData(
                                            VMPersonDataVariable.NeighborId) ?? (short)-1)
                                        + " stack=" + fr.StackObjectID
                                        + "/nid" + ((fr.StackObject as VMAvatar)?.GetPersonData(
                                            VMPersonDataVariable.NeighborId) ?? (short)-1);
                                    if (_schoolAtSchoolFrameSites.Add(atSchoolSite))
                                        Log("AUTOTEST schoolreturn at-school-site " + atSchoolSite);
                                }
                                if (!owner.Equals("SchoolBus.iff", StringComparison.OrdinalIgnoreCase)) continue;
                                if (id == 4121)
                                {
                                    sendFrameEntities.Add(e.ObjectID);
                                    _schoolSendFrameIps.Add(fr.InstructionPointer);
                                    if (!_schoolSendActiveEntities.Contains(e.ObjectID))
                                        _schoolSendActionStarts++;
                                    if (fr.InstructionPointer == 5) _schoolSendPrimaryRouteSeen = true;
                                    if (fr.InstructionPointer == 20) _schoolSendFallbackRouteSeen = true;
                                    if (fr.InstructionPointer == 23) _schoolSendFalseExitSeen = true;
                                    if (fr.InstructionPointer == 6) _schoolSendHiddenLatchSeen = true;
                                    var sendSite = "ip=" + fr.InstructionPointer
                                        + " caller=" + (fr.Caller?.ObjectID ?? 0)
                                        + " callee=" + (fr.Callee?.ObjectID ?? 0)
                                        + " stack=" + fr.StackObjectID
                                        + " hidden=" + (fr.Caller?.GetValue(VMStackObjectVariable.Hidden) ?? (short)-1)
                                        + " oow=" + (fr.Caller?.Position
                                            == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD);
                                    string lastSendSite;
                                    if (!_schoolSendLastSites.TryGetValue(e.ObjectID, out lastSendSite)
                                        || lastSendSite != sendSite)
                                    {
                                        _schoolSendLastSites[e.ObjectID] = sendSite;
                                        Log("AUTOTEST schoolreturn send-site entity=" + e.ObjectID
                                            + " start=" + _schoolSendActionStarts + " " + sendSite);
                                    }
                                }
                                var sg = fr.ScopeResource?.SemiGlobal?.Iff?.Filename ?? "";
                                var first = sg.Equals("CarGlobals.iff", StringComparison.OrdinalIgnoreCase)
                                    && id >= 8192
                                    ? _schoolCarGlobalFrameIds.Add(id)
                                    : _schoolBusFrameIds.Add(id);
                                if (first)
                                {
                                    var label = "";
                                    try { label = ((fr.Routine?.Chunk) as BHAV)?.ChunkLabel?.Trim() ?? ""; }
                                    catch { }
                                    Log("AUTOTEST schoolreturn first-frame id=" + id + " label=" + label
                                        + " owner=" + owner + " sg=" + sg + " entity=" + e.ObjectID);
                                }
                            }
                        }
                        catch { }
                    }
                    _schoolSendActiveEntities.Clear();
                    foreach (var entityId in sendFrameEntities)
                        _schoolSendActiveEntities.Add(entityId);
                    foreach (var entityId in _schoolSendLastSites.Keys
                        .Where(x => !sendFrameEntities.Contains(x)).ToList())
                        _schoolSendLastSites.Remove(entityId);
                    _schoolAtSchoolFrameActive = atSchoolFrameActive;

                    // Follow logical identity by NeighborId 32 and require the original as
                    // the sole survivor at home. Ordinary school has no clone; this census
                    // makes an unexpected duplicate unable to satisfy the gate.
                    var logicalChildren = new List<VMAvatar>();
                    foreach (var avatar in _vm.Entities.OfType<VMAvatar>())
                    {
                        try
                        {
                            if (avatar.GetPersonData(VMPersonDataVariable.NeighborId) == SchoolChildNeighborId)
                                logicalChildren.Add(avatar);
                        }
                        catch { }
                    }
                    try
                    {
                        var liveLogicalChildren = logicalChildren.Where(x => !x.Dead).ToList();
                        var original = liveLogicalChildren.FirstOrDefault(x => x.ObjectID == _schoolChildAvatarId);
                        var awayNow = liveLogicalChildren.Any(x =>
                            x.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                            && x.GetValue(VMStackObjectVariable.Hidden) == 1
                            && x.GetPersonData(VMPersonDataVariable.TS1AtWorkSchool) == 1);
                        if (CheckEnabled("schoolmiss") && liveLogicalChildren.Any(x =>
                            x.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                            || x.GetValue(VMStackObjectVariable.Hidden) == 1))
                            _missChildOowSeen = true;
                        if (_schoolOutboundCreateEvents > 0 && awayNow)
                        {
                            _schoolChildSchoolStateSeen = true;
                            _schoolChildHiddenLatchSeen = true;
                        }
                        _schoolFinalLogicalHome = _schoolReturnCreateEvents > 0
                            && _schoolChildSchoolStateSeen && !_schoolAtSchoolFrameActive
                            && original != null
                            && original.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                            && original.GetValue(VMStackObjectVariable.Hidden) == 0
                            && original.GetPersonData(VMPersonDataVariable.TS1AtWorkSchool) == 0
                            && liveLogicalChildren.All(x => x.ObjectID == _schoolChildAvatarId);
                        if (_schoolFinalLogicalHome) _schoolChildHomeStateSeen = true;
                        if (original != null)
                        {
                            _schoolChildFinalGrade = original.GetPersonData(
                                VMPersonDataVariable.JobPromotionLevel);
                            if (CheckEnabled("schoolmiss"))
                            {
                                _missChildFinalAway = original.GetPersonData(
                                    VMPersonDataVariable.TS1AtWorkSchool);
                                if (_schoolBusDisappearedBetweenLegs
                                    && _missGradeSettledElapsed < 0
                                    && _schoolChildFinalGrade == _schoolChildInitialGrade + 3)
                                    _missGradeSettledElapsed = _careerElapsedMinutes;
                            }
                        }

                        var childStates = logicalChildren.OrderBy(x => x.ObjectID).Select(x =>
                        {
                            var stack = x.Thread?.Stack == null ? "" : string.Join("/", x.Thread.Stack.Where(fr =>
                            {
                                try {
                                    var owner = fr.ScopeResource?.MainIff?.Filename ?? "";
                                    var id = fr.Routine?.Chunk?.ChunkID ?? 0;
                                    return (owner.Equals("CarPortal.iff", StringComparison.OrdinalIgnoreCase)
                                            && (id == 4116 || id == 4117))
                                        || owner.Equals("SchoolBus.iff", StringComparison.OrdinalIgnoreCase);
                                }
                                catch { return false; }
                            }).Select(fr => (fr.ScopeResource?.MainIff?.Filename ?? "?") + ":"
                                + (fr.Routine?.Chunk?.ChunkID ?? 0) + ":" + fr.InstructionPointer));
                            return "id=" + x.ObjectID + " guid=0x" + (x.Object?.OBJ?.GUID ?? 0).ToString("X8")
                                + " pd32=" + x.GetPersonData(VMPersonDataVariable.PersonType)
                                + " oow=" + (x.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                                + " hidden=" + x.GetValue(VMStackObjectVariable.Hidden)
                                + " atSchool=" + x.GetPersonData(VMPersonDataVariable.TS1AtWorkSchool)
                                + " grade=" + x.GetPersonData(VMPersonDataVariable.JobPromotionLevel)
                                + " container=" + (x.Container?.ObjectID ?? 0) + " dead=" + x.Dead
                                + " stack=[" + stack + "]";
                        });
                        var childState = string.Join(" | ", childStates);
                        if (_schoolChildLastState != childState)
                        {
                            _schoolChildLastState = childState;
                            Log("AUTOTEST schoolreturn child-state clock=" +
                                (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"))
                                + " logical=[" + childState + "] awayNow=" + awayNow
                                + " schoolSeen=" + _schoolChildSchoolStateSeen
                                + " atSchoolFrameActive=" + _schoolAtSchoolFrameActive
                                + " finalHome=" + _schoolFinalLogicalHome
                                + " homeSeen=" + _schoolChildHomeStateSeen);
                        }
                    }
                    catch (Exception sce)
                    {
                        Log("AUTOTEST schoolreturn child-state EXC " + sce.GetType().Name + " " + sce.Message);
                    }
                }

                // (b) IFF-factual car-owned frames in any live thread stack. A frame is car-owned
                // when its code scope (object IFF, else semi-global IFF) filename carries 'car'
                // (CarPortal.iff owns 'process'/'send to work'/'At Work'/'At School'/'start motives
                // delta' - IFF-pinned by the career check). Identity = routine id + owning file.
                foreach (var e in _vm.Entities)
                {
                    try
                    {
                        var th = e?.Thread;
                        if (th == null || th.Stack == null) continue;
                        for (int f = 0; f < th.Stack.Count; f++)
                        {
                            var fr = th.Stack[f];
                            if (fr == null) continue;
                            string owner = null, sg = null;
                            try { owner = fr.ScopeResource?.MainIff?.Filename; } catch { }
                            try { sg = fr.ScopeResource?.SemiGlobal?.Iff?.Filename; } catch { }
                            var code = owner ?? sg ?? "";
                            if (code.IndexOf("car", StringComparison.OrdinalIgnoreCase) < 0) continue;
                            _careerFrameCount++;
                            var id = (ushort)((fr.Routine?.Chunk?.ChunkID) ?? 0);
                            if (id != 0)
                            {
                                var ownFile = owner ?? sg ?? "";
                                if (!_careerFrameOwner.ContainsKey(id)) _careerFrameOwner[id] = ownFile;
                                else if (_careerFrameOwner[id] != ownFile)
                                    _careerFrameOwner[id] = _careerFrameOwner[id] + "|" + ownFile;
                                if (afterCareerEnd && ownFile.IndexOf("CarPortal.iff", StringComparison.OrdinalIgnoreCase) >= 0)
                                    _careerPostEndFrameIds.Add(id);
                            }
                            if (id != 0 && _careerFrameIds.Add(id))
                            {
                                string lbl = "";
                                try
                                {
                                    var bh = fr.Routine?.Chunk as BHAV;
                                    if (bh != null) lbl = (bh.ChunkLabel ?? "").Trim();
                                }
                                catch { }
                                Log("AUTOTEST carseek first-seen id=" + id + " label=" + lbl +
                                    " owner=" + (owner ?? "") + " sg=" + (sg ?? ""));
                            }
                        }
                    }
                    catch { }
                }

                // (b2) R157 PORTAL STACK TRACER: log every CHANGE of the portal's live stack
                // signature (routine:ip per frame + top StackObject). If 'process' (4100)
                // dies mid-run (suppressed exception -> reset), the stack collapses back to
                // [4096:...] and the transition is captured; if it blocks inside 4125, the
                // signature freezes there. This is the instrument that names the failing node.
                try
                {
                    var pt = _carPortal?.Thread;
                    if (pt != null && pt.Stack != null && pt.Stack.Count > 0)
                    {
                        var sb2 = new System.Text.StringBuilder();
                        short topObj = 0;
                        foreach (var pf in pt.Stack)
                        {
                            if (pf == null) { sb2.Append("[null]"); continue; }
                            sb2.Append('[').Append((pf.Routine?.Chunk?.ChunkID) ?? 0)
                               .Append(':').Append(pf.InstructionPointer).Append(']');
                            topObj = pf.StackObjectID;
                        }
                        var sig = sb2.ToString() + " stkObj=" + topObj + " bs=" + (_carPortal.Thread.BlockingState == null ? "-" : _carPortal.Thread.BlockingState.GetType().Name);
                        if (sig != _portalStackLast)
                        {
                            _portalStackLast = sig;
                            Log("AUTOTEST carseek portal-stack " + sig);
                        }
                    }
                }
                catch (Exception pst) { Log("AUTOTEST carseek portal-stack EXC " + pst.GetType().Name); }

                // (R222) CHANCETRACE WORKER-STACK TRACER — the same instrument the portal got
                // in R157, pointed at the WORKER's thread: 'get paid' (4103) and the whole
                // Chance Card cascade (4134/4124/4133) execute there, and the portal tracer
                // cannot see them. Logs every change of the worker's live stack signature
                // (routine:ip per frame + blocking state) — the instrument that names the
                // exact instruction the fork took (ins43 vs ins54, 4134:90 vs 4134:122, the
                // card dialog site 4124:55).
                if (CheckEnabled("chancetrace"))
                {
                    try
                    {
                        var wt = _chanceWorkerEntity != null ? _chanceWorkerEntity.Thread : null;
                        if (wt == null && _chanceWorkerAvatarId != 0)
                        {
                            try { _chanceWorkerEntity = _vm.Entities.FirstOrDefault(e => e != null && e.ObjectID == _chanceWorkerAvatarId); } catch { }
                            wt = _chanceWorkerEntity?.Thread;
                        }
                        if (wt != null && wt.Stack != null && wt.Stack.Count > 0)
                        {
                            var sbw = new System.Text.StringBuilder();
                            var chanceOnStack = false;
                            foreach (var wf in wt.Stack)
                            {
                                if (wf == null) { sbw.Append("[null]"); continue; }
                                var wid = (ushort)((wf.Routine?.Chunk?.ChunkID) ?? 0);
                                string wOwner = null;
                                try { wOwner = wf.ScopeResource?.MainIff?.Filename; } catch { }
                                sbw.Append('[').Append(wid).Append(':').Append(wf.InstructionPointer)
                                   .Append(wOwner != null && wOwner.ToLowerInvariant().IndexOf("carportal") >= 0 ? "*" : "").Append(']');
                                // (R222 run 5) routine ids are PER-IFF — the r155 paper-carrier
                                // lesson: User00009.iff/PersonGlobals frames also carry 4124 and
                                // collided with the detector. Only CarPortal-owned frames count.
                                if ((wid == 4124 || wid == 4133 || wid == 4134)
                                    && wOwner != null && wOwner.ToLowerInvariant().IndexOf("carportal") >= 0) chanceOnStack = true;
                            }
                            var wsig = sbw.ToString() + " bs=" + (wt.BlockingState == null ? "-" : wt.BlockingState.GetType().Name)
                                + " at " + (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00"));
                            if (wsig != _chanceWorkerStackLast)
                            {
                                _chanceWorkerStackLast = wsig;
                                Log("AUTOTEST chancetrace worker-stack " + wsig);
                                _chanceTimeline.Add("worker-stack " + wsig);
                            }
                            if (chanceOnStack && !_chanceCascadeFrameSeen)
                            {
                                _chanceCascadeFrameSeen = true;
                                Log("AUTOTEST chancetrace cascade-frame-first-seen " + wsig);
                            }
                        }
                    }
                    catch (Exception wst) { Log("AUTOTEST chancetrace worker-stack EXC " + wst.GetType().Name + " " + wst.Message); }
                }

                // (b3) R157 NULL-ROUTINE DETECTOR: a frame whose Routine/Instructions is
                // null/empty NREs at VMStackFrame.GetCurrentInstruction — the suppressed
                // "[SimAnticsExc] ... VMStackFrame.cs:line 131" seen 143x in the r156 soak.
                // Report each affected entity once (owner IFF + stack depth) to attribute it.
                try
                {
                    foreach (var e2 in _vm.Entities)
                    {
                        try
                        {
                            var th2 = e2?.Thread;
                            if (th2 == null || th2.Stack == null) continue;
                            for (int f2 = 0; f2 < th2.Stack.Count; f2++)
                            {
                                var fr2 = th2.Stack[f2];
                                if (fr2 == null) continue;
                                if ((fr2.Routine == null || fr2.Routine.Instructions == null || fr2.Routine.Instructions.Length == 0)
                                    && _badRoutineReported.Add(e2.ObjectID))
                                {
                                    string iff2 = null;
                                    try { iff2 = e2?.Object?.Resource?.MainIff?.Filename; } catch { }
                                    Log("AUTOTEST carseek bad-routine-frame obj=" + e2.ObjectID + " iff=" + (iff2 ?? "?") +
                                        " depth=" + f2 + " of " + th2.Stack.Count);
                                }
                            }
                        }
                        catch { }
                    }
                }
                catch { }

                // (c) job perf/level drift vs the discovery snapshot (IFF 'start motives delta'/promote)
                foreach (var a in _avatars)
                {
                    try
                    {
                        int jperf = 0, jlevel = 0;
                        try { jperf = a.GetPersonData(VMPersonDataVariable.JobPerformance); } catch { }
                        try { jlevel = a.GetPersonData(VMPersonDataVariable.JobPromotionLevel); } catch { }
                        int[] baseV;
                        if (_careerJobBase.TryGetValue(a.ObjectID, out baseV))
                        {
                            if (baseV != null && (baseV[0] != jperf || baseV[1] != jlevel)) _careerJobChanged = true;
                            if (baseV != null && jlevel > baseV[1]) _careerPromoted = true;
                        }
                    }
                    catch { }
                }

                var minute = now;
                if (minute != _carpoolLastMin)
                {
                    _carpoolLastMin = minute;
                    // R156: per-minute portal guard inputs — names the failing 'process' condition
                    // live (Attr 0 = bookmarked start hour, 2/3 = stage flags, 6 = timer, 7 = day
                    // bookmark, 8 = family-min level). Logged on the 5 minutes around each hour
                    // (the 'main' top-of-hour gate window) to keep noise down.
                    string attrInfo = "";
                    if (_carPortal != null && _vm.Context.Clock.Minutes < 6)
                    {
                        try
                        {
                            var av = new List<string>();
                            for (short a2 = 0; a2 <= 8; a2++)
                            {
                                var v2 = _carPortal.GetAttribute(a2);
                                av.Add(a2 + "=" + v2);
                                if (a2 == 0 && v2 > _portalAttr0Max) _portalAttr0Max = v2; // the ins54 bookmark
                            }
                            attrInfo = " attrs[" + string.Join(",", av) + "]";
                        }
                        catch { }
                    }
                    Log("AUTOTEST carseek minute=" + (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")) +
                        " carEnt=" + carEnt + " maxCarEnt=" + _carEntityMax + " portalEnt=" + portalEnt +
                        " careerFrames=" + _careerFrameCount + " distinct=" + _careerFrameIds.Count +
                        " jobPerfLvlChanged=" + _careerJobChanged + attrInfo);
                    if (CheckEnabled("carskip")) CareerSkipTick();
                    if (CheckEnabled("career5day") || CheckEnabled("career5level")) CareerProtocolTick();
                    if (CheckEnabled("simjrn")) AutotestSimJourney.Tick(_vm, _avatars?.FirstOrDefault(), Log);

                    // R157 GATE-REPLICA (once per hour, minute 0): evaluates the tree's OWN
                    // data path per avatar — JobData[12] read at the sim's level (w56/w57) via
                    // the same provider VMMemory's JobData scope uses. If the tree RAN, the
                    // bookmark (ins48-54) would fire exactly on the hour marked BOOKMARK-NOW.
                    // start=-999 means the provider itself threw (level out of range).
                    if (_vm.Context.Clock.Minutes == 0)
                    {
                        try
                        {
                            // R157 dialog-latch probe: 4125 ins15 is a BLOCKING dialog (Flags=0x08,
                            // Continue=1 NOT set). A thread frozen there for hours while the clock
                            // runs can only be the primitive's first branch — TS1
                            // GlobalBlockingDialog != null -> CONTINUE_NEXT_TICK forever. Name the
                            // latch owner (id + IFF), the speed, and the portal's BlockingState.
                            var gbd = _vm.GlobalBlockingDialog;
                            string gbdIff = null;
                            if (gbd != null) { try { gbdIff = gbd.Object?.Resource?.MainIff?.Filename; } catch { } }
                            string portalBs = "-", portalBsW = "-";
                            try
                            {
                                var bs = _carPortal?.Thread?.BlockingState;
                                if (bs != null)
                                {
                                    portalBs = bs.GetType().Name;
                                    var wt = bs.GetType().GetField("WaitTime");
                                    if (wt != null) portalBsW = "" + wt.GetValue(bs);
                                }
                            }
                            catch { }
                            Log("AUTOTEST carseek dialog-state gbd=" + (gbd == null ? "null" : (gbd.ObjectID + "/" + (gbdIff ?? "?"))) +
                                " speed=" + _vm.SpeedMultiplier + " portalBS=" + portalBs + " wait=" + portalBsW);
                        }
                        catch (Exception dse) { Log("AUTOTEST carseek dialog-state EXC " + dse.GetType().Name); }
                        try
                        {
                            var rep = new List<string>();
                            var jobsR = Content.Get().Jobs;
                            foreach (var a3 in _avatars)
                            {
                                int w56 = 0, w57 = 0, w69 = 0;
                                try { w56 = a3.GetPersonData(VMPersonDataVariable.JobType); } catch { }
                                try { w57 = a3.GetPersonData(VMPersonDataVariable.JobPromotionLevel); } catch { }
                                try { w69 = a3.GetPersonData((VMPersonDataVariable)69); } catch { }
                                int startH = -1;
                                if (w56 > 0)
                                {
                                    try { startH = jobsR.GetJobData((ushort)w56, w57, 12); }
                                    catch { startH = -999; }
                                }
                                bool bookmarkNow = startH > 0 && ((startH - 1 + 24) % 24) == _vm.Context.Clock.Hours;
                                rep.Add("obj=" + a3.ObjectID + " w56=" + w56 + " w57=" + w57 + " w69=" + w69 +
                                    " start=" + startH + (bookmarkNow ? " BOOKMARK-NOW" : ""));
                            }
                            Log("AUTOTEST carseek gate-replica hour=" + _vm.Context.Clock.Hours + " [" + string.Join(" | ", rep) + "]");
                        }
                        catch (Exception gre) { Log("AUTOTEST carseek gate-replica EXC " + gre.GetType().Name); }
                    }
                }

                bool careerTargetReached;
                if (CheckEnabled("carreturn") || CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss") || CheckEnabled("chancetrace") || CheckEnabled("carskip") || CheckEnabled("simjrn"))
                {
                    var carTargetReached = !(CheckEnabled("carreturn") || CheckEnabled("chancetrace") || CheckEnabled("carskip") || CheckEnabled("simjrn"))
                        || (_careerTargetElapsed >= 0
                            && _careerElapsedMinutes >= _careerTargetElapsed);
                    var schoolLifecycleComplete = _schoolReturnEndElapsed >= 0
                        && _careerElapsedMinutes >= _schoolReturnEndElapsed + 15
                        && _schoolReturnBusDisappeared && _schoolChildHomeStateSeen;
                    var schoolCeilingReached = _schoolTargetElapsed >= 0
                        && _careerElapsedMinutes >= _schoolTargetElapsed;
                    var schoolTargetReached = !(CheckEnabled("schoolreturn") || CheckEnabled("schoolmiss"))
                        || !_schoolReturnFixtureValid
                        || (CheckEnabled("schoolmiss")
                            ? (_missGradeSettledElapsed >= 0
                                && _careerElapsedMinutes >= _missGradeSettledElapsed + 30)
                                || schoolCeilingReached
                            : schoolLifecycleComplete || schoolCeilingReached);
                    careerTargetReached = carTargetReached && schoolTargetReached;
                }
                else careerTargetReached = now >= _carpoolTargetMin;
                if (!careerTargetReached) return;
                var portalIds = _careerFrameOwner.Where(kv => kv.Value != null && kv.Value.IndexOf("CarPortal.iff", StringComparison.OrdinalIgnoreCase) >= 0).Select(kv => kv.Key).OrderBy(x => x).ToList();
                var paperIds = _careerFrameOwner.Where(kv => kv.Value != null && kv.Value.IndexOf("PaperCarrier", StringComparison.OrdinalIgnoreCase) >= 0).Select(kv => kv.Key).OrderBy(x => x).ToList();
                int budgetNow = 0;
                try { budgetNow = _vm.TS1State?.CurrentFamily?.Budget ?? 0; } catch { }
                int budgetDelta = budgetNow - _careerBudgetBase;
                var payTransactionsExact = _careerPayBaseEvents == 1 && _careerPayBonusEvents == 1
                    && _careerPayBaseAmount == _careerPromotedSalaryExpected
                    && _careerPayBonusAmount == _careerPromotionBonusExpected
                    && _careerMountedPayTuning == _careerPayTuningExpected;
                var attributedPay = _careerPayBaseAmount + _careerPayBonusAmount;
                var unrelatedBudgetDelta = budgetDelta - attributedPay;
                var returnWorker = _avatars.FirstOrDefault(x => x.ObjectID == _careerReturnAvatarId);
                var promotionExact = _careerReturnFixtureValid && returnWorker != null
                    && returnWorker.GetPersonData(VMPersonDataVariable.JobPromotionLevel) == _careerReturnExpectedLevel;
                var workerState = "missing";
                if (returnWorker != null)
                {
                    try
                    {
                        var stack = returnWorker.Thread?.Stack == null ? "" : string.Join("", returnWorker.Thread.Stack.Select(fr =>
                            "[" + ((fr?.Routine?.Chunk?.ChunkID) ?? 0) + ":" + (fr?.InstructionPointer ?? -1) + "]"));
                        workerState = "pos=" + returnWorker.Position + " container=" + (returnWorker.Container?.ObjectID ?? 0)
                            + " blocking=" + (returnWorker.Thread?.BlockingState?.GetType().Name ?? "-") + " stack=" + stack;
                    }
                    catch (Exception wse) { workerState = "EXC " + wse.GetType().Name; }
                }
                Log("AUTOTEST carseek RESULT minute=" + now +
                    " car-entity-max=" + _carEntityMax + " portal-entity-max=" + _portalEntityMax +
                    " career-frames=" + _careerFrameCount + " ids=[" + string.Join(",", _careerFrameIds.OrderBy(x => x)) + "]" +
                    " portal-owned=[" + string.Join(",", portalIds) + "]" +
                    " paper-owned=[" + string.Join(",", paperIds) + "]" +
                    " jobPerfLvlChanged=" + _careerJobChanged +
                    " iff4100process=" + _carIff4100Process + " labels4=" + _carLabelsAnchored +
                    " spawnedCars=" + _spawnedCarMax + " attr0Max=" + _portalAttr0Max +
                    " returnCar=" + _careerReturnCarSeen + " createEvents=" + _careerOutboundCarCreateEvents
                    + "/" + _careerReturnCarCreateEvents + " promoted=" + _careerPromoted +
                    " promotionExact=" + promotionExact +
                    " elapsed=" + _careerElapsedMinutes + " postEndIds=[" + string.Join(",", _careerPostEndFrameIds.OrderBy(x => x)) + "]" +
                    " currentCarGroups=[" + string.Join(",", seenCarBases.Select(x => x.ObjectID).OrderBy(x => x)) + "] worker={" + workerState + "}" +
                    " budget=" + _careerBudgetBase + "->" + budgetNow + " delta=" + budgetDelta +
                    " attributedPay=" + attributedPay + " expectedPay=" + _careerExpectedPay +
                    " unrelatedDelta=" + unrelatedBudgetDelta +
                    " payEvents=[" + string.Join(",", _careerBudgetEvents) + "]" +
                    " createEvents=[" + string.Join(",", _careerCarCreateEvents) + "]");
                // R157 PASS law (strictly stronger than R155's — extend, never weaken): the R155
                // portal-scoped law (4096+280+4100+4125 live, three-label anchor, portal presence)
                // AND the COMMUTE TAIL now LIVE — the dialog-latch fix (engine r157: queued-dialog
                // state + shared timeout + latch release on completion) let 'process' complete for
                // the first time: portal-owned 4105 'send to work' + 4102 'At Work' executed, the
                // bookmark landed (portal Attr[0] > 0 at a top-of-hour sample — 9 for this
                // fixture's 9:00 Science job), and ONE spawned carpool car (a multitile group,
                // R158 metric) appeared at 8:00 = start-1, the corrected ins34->20->17 law.
                bool portalLive = portalIds.Contains(4096) && portalIds.Contains(280)
                    && portalIds.Contains(4100) && portalIds.Contains(4125)
                    && _carIff4100Process && _carLabelsAnchored && _portalEntityMax >= 1;
                bool commuteLive = portalIds.Contains(4105) && portalIds.Contains(4102)
                    && _portalAttr0Max > 0 && _spawnedCarMax >= 1; // R158: >=1 GROUP (r157's >=5 counted multitile PARTS of the single car — erratum)
                if (CheckEnabled("carseek"))
                {
                    if (portalLive && commuteLive) { Pass("carseek"); }
                    else { Fail("carseek"); }
                }
                if (CheckEnabled("carreturn"))
                {
                    // Strong end-to-end effects from the naturally scheduled IFF trees:
                    // one post-EndTime car group, the two exact CARR-authored transfers credited
                    // once each, and the level-0 fixture promoted by the original 4104 gate.
                    // The aggregate family delta is diagnostic only: unrelated expenses may occur
                    // while the natural six-hour shift is being soaked.
                    bool returnLive = _careerReturnFixtureValid && portalLive && commuteLive
                        && _careerReturnCarSeen && _careerOutboundCarCreateEvents == 1
                        && _careerReturnCarCreateEvents == 1
                        && _careerExpectedPay > 0
                        && payTransactionsExact && promotionExact;
                    Log("AUTOTEST carreturn effects returnCar=" + _careerReturnCarSeen +
                        " exactCreateEvents=" + (_careerOutboundCarCreateEvents == 1 && _careerReturnCarCreateEvents == 1) +
                        " outbound=" + _careerOutboundCarCreateEvents + " return=" + _careerReturnCarCreateEvents +
                        " sampledGetPaid4103=" + _careerPostEndFrameIds.Contains(4103) +
                        " budgetCallbacksProve4103=" + (_careerPayBaseEvents > 0 && _careerPayBonusEvents > 0) +
                        " exactPayTransactions=" + payTransactionsExact +
                        " base=" + _careerPayBaseEvents + "x" + _careerPayBaseAmount +
                        " bonus=" + _careerPayBonusEvents + "x" + _careerPayBonusAmount +
                        " mountedTuning132=" + _careerMountedPayTuning +
                        " promoted=" + promotionExact +
                        " fixture=" + _careerReturnFixtureValid +
                        " (natural CarPortal.iff At Work/Get paid/Test promotion path)");
                    if (returnLive) Pass("carreturn"); else Fail("carreturn");
                }
                if (CheckEnabled("simjrn"))
                {
                    // SIM-02: live object-use journey battery (use/interrupt/route-fail)
                    var ok = AutotestSimJourney.Verdict(Log);
                    if (ok) Pass("simjrn"); else Fail("simjrn");
                }
                if (CheckEnabled("carskip"))
                {
                    // SIM-04 missed-work ladder law: B7 = warning (4126 live and/or the
                    // 0xF7870464 warning object); B8 = a second ladder stage; B9 = the
                    // fire transition (worker JobType cleared). The bare minimum for an
                    // honest pass is B7+ (the ladder walking at all); full pass = fire.
                    Log("AUTOTEST carskip RESULT warnObj=" + _skipWarnObjSeen +
                        " r4126=" + _skip4126Seen + " r4127=" + _skip4127Seen +
                        " fire=" + _skipFireSeen + " carsDeleted=" + _skipCarsDeleted +
                        " pdWatch=[" + string.Join(" | ", _skipPdLog.Take(12)) + "]");
                    if (_skipWarnObjSeen && _skipFireSeen) { Pass("carskip"); Log("AUTOTEST carskip verdict: full ladder observed (warning + fire)"); }
                    else if (_skipWarnObjSeen || (_skip4126Seen && _skipCarsDeleted > 0)) { Pass("carskip"); Log("AUTOTEST carskip verdict: PARTIAL — ladder entered (warning evidence) but no fire transition observed; disclose soak length"); }
                    else { Fail("carskip"); Log("AUTOTEST carskip verdict: ladder never triggered (no 4126/warning evidence) — disclose"); }
                }
                if (CheckEnabled("career5day"))
                {
                    // SIM-15 protocol verdict (motives arm): motives were held and the
                    // worker attended all shifts — no missed-work ladder sighting.
                    var c5ok = !_skip4126Seen;
                    Log("AUTOTEST career5day RESULT motivesHeld=true ladderWalked=" + _skip4126Seen);
                    if (c5ok) { Pass("career5day"); Log("AUTOTEST career5day verdict: no missed-work walk under held motives"); }
                    else Fail("career5day");
                }
                if (CheckEnabled("career5level"))
                {
                    // SIM-15 protocol verdict (level arm): state-set walked the worker to
                    // level 5 with collapsed performance and the chance cascade fired.
                    var c5ok = _c5LevelSet && _c5CollapseSet && _chanceCascadeFrameSeen;
                    Log("AUTOTEST career5level RESULT levelSet=" + _c5LevelSet + " collapseSet=" + _c5CollapseSet +
                        " cascadeSeen=" + _chanceCascadeFrameSeen);
                    if (c5ok) { Pass("career5level"); Log("AUTOTEST career5level verdict: level-5 collapse reached and the chance cascade fired"); }
                    else Fail("career5level");
                }
                if (CheckEnabled("schoolreturn") && !CheckEnabled("schoolmiss"))
                {
                    var exactCreates = _schoolBusCreateEvents == 2
                        && _schoolBusExactCreateEvents == 2
                        && _schoolOutboundCreateEvents == 1
                        && _schoolReturnCreateEvents == 1;
                    var gradeLaw = _schoolChildFinalGrade >= _schoolChildInitialGrade - 1
                        && _schoolChildFinalGrade <= _schoolChildInitialGrade + 1;
                    var schoolLive = _schoolReturnFixtureValid && exactCreates
                        && _schoolBusGroupMax == 1
                        && _schoolOutboundBusSeen && _schoolBusDisappearedBetweenLegs
                        && _schoolReturnBusSeen && _schoolReturnBusDisappeared
                        && _schoolBusFrameIds.Contains(4096) && _schoolBusFrameIds.Contains(4121)
                        && _schoolCarGlobalFrameIds.Contains(8205)
                        && _schoolAtSchoolFrameSeen
                        && _schoolChildHiddenLatchSeen && _schoolChildSchoolStateSeen
                        && _schoolChildHomeStateSeen && _schoolFinalLogicalHome
                        && gradeLaw;
                    Log("AUTOTEST schoolreturn effects fixture=" + _schoolReturnFixtureValid
                        + " creates=" + _schoolBusCreateEvents + " exact=" + _schoolBusExactCreateEvents
                        + " legs=" + _schoolOutboundCreateEvents + "/" + _schoolReturnCreateEvents
                        + " createMinutes=[" + string.Join(",", _schoolBusCreateMinutes) + "]"
                        + " createBases=[" + string.Join(",", _schoolBusCreateBaseIds) + "]"
                        + " seenBases=[" + string.Join(",", _schoolBusSeenBaseIds.OrderBy(x => x)) + "]"
                        + " groupMax=" + _schoolBusGroupMax
                        + " outboundBusSeen=" + _schoolOutboundBusSeen
                        + " betweenGone=" + _schoolBusDisappearedBetweenLegs
                        + " returnBusSeen=" + _schoolReturnBusSeen
                        + " returnGone=" + _schoolReturnBusDisappeared
                        + " childSchool=" + _schoolChildSchoolStateSeen
                        + " childHome=" + _schoolChildHomeStateSeen
                        + " atSchoolFrame=" + _schoolAtSchoolFrameSeen
                        + "/active=" + _schoolAtSchoolFrameActive
                        + " finalHome=" + _schoolFinalLogicalHome
                        + " grade=" + _schoolChildInitialGrade + "->" + _schoolChildFinalGrade
                        + "/law=" + gradeLaw
                        + " schoolFrames=[" + string.Join(",", _schoolBusFrameIds.OrderBy(x => x)) + "]"
                        + " carGlobalFrames=[" + string.Join(",", _schoolCarGlobalFrameIds.OrderBy(x => x)) + "]"
                        + " atSchoolSites=" + _schoolAtSchoolFrameSites.Count
                        + " sendStarts=" + _schoolSendActionStarts
                        + " sendIps=[" + string.Join(",", _schoolSendFrameIps.OrderBy(x => x)) + "]"
                        + " sendPath=" + _schoolSendPrimaryRouteSeen + "/"
                        + _schoolSendFallbackRouteSeen + "/false" + _schoolSendFalseExitSeen
                        + "/hidden" + _schoolSendHiddenLatchSeen
                        + " hiddenState=" + _schoolChildHiddenLatchSeen
                        + " fixtureQueue=" + _schoolFixturePendingBusSeen
                        + "/cancel" + _schoolFixtureCancelEvents
                        + "/abort" + _schoolFixtureAbortEvents
                        + " events=[" + string.Join(" | ", _schoolBusCreateEventLog) + "]"
                        + " (original SchoolBus day; fixture-only queue unblock if needed)");
                    if (schoolLive) Pass("schoolreturn"); else Fail("schoolreturn");
                }
                if (CheckEnabled("schoolmiss"))
                {
                    var missNoReturn = _schoolOutboundCreateEvents == 1
                        && _schoolReturnCreateEvents == 0
                        && _schoolBusExactCreateEvents == 1;
                    var missHomeAllDay = _missBusCancelSeen
                        && _schoolOutboundBusSeen && _schoolBusDisappearedBetweenLegs
                        && !_missChildOowSeen
                        && _missChildFinalAway == 0;
                    var missGradeLaw = _schoolChildFinalGrade == _schoolChildInitialGrade + 3;
                    var missNoPortalPay = !_careerBudgetEvents.Any(e =>
                        e.StartsWith("CarPortal.iff:", StringComparison.OrdinalIgnoreCase));
                    Log("AUTOTEST schoolmiss RESULT fixture=" + _schoolReturnFixtureValid
                        + " outboundCreates=" + _schoolOutboundCreateEvents
                        + " returnCreates=" + _schoolReturnCreateEvents
                        + " exactCreates=" + _schoolBusExactCreateEvents
                        + " busCancel=" + _missBusCancelSeen
                        + " outboundSeen=" + _schoolOutboundBusSeen
                        + " busGone=" + _schoolBusDisappearedBetweenLegs
                        + " childOowSeen=" + _missChildOowSeen
                        + " grade=" + _schoolChildInitialGrade + "->" + _schoolChildFinalGrade
                        + "/law=" + missGradeLaw
                        + " finalAway=" + _missChildFinalAway
                        + " portalBudgetEvents=" + _careerBudgetEvents.Count(x =>
                            x.StartsWith("CarPortal.iff:", StringComparison.OrdinalIgnoreCase))
                        + " (missed-school law: CarPortal 4117 'lower all kids grades' ins4 PD[57]+=3; no pay path on the school branch)");
                    if (_schoolReturnFixtureValid && missNoReturn && missHomeAllDay
                        && missGradeLaw && missNoPortalPay)
                    {
                        Pass("schoolmiss");
                        Log("AUTOTEST schoolmiss verdict: missed-school branch observed exactly (grade +3, child stayed home visible, away flag 0, no return bus, no portal pay)");
                    }
                    else Fail("schoolmiss");
                }
                if (CheckEnabled("chancetrace"))
                {
                    // (Round 222) PASS law: the fixture held, the pay window ran (a CarPortal
                    // 4103 'get paid' frame sampled post-end, or the CARR budget transfers),
                    // the chance cascade executed LIVE (a portal-owned 4124/4133/4134 frame),
                    // the probe answered the card's blocking dialog (chance-owner verified on
                    // the latch thread's stack), and a card effect landed afterwards (a budget
                    // event or a worker PD change past the response). Never weaker than
                    // observed; every clause is engine-produced evidence, never invented.
                    var chanceIdsSeen = _careerFrameIds.Where(id => id == 4124 || id == 4133 || id == 4134).ToList();
                    var cascadeSeen = chanceIdsSeen.Count > 0 || _chanceCascadeFrameSeen;
                    var payWindowRan = _careerPostEndFrameIds.Contains(4103)
                        || (_careerPayBaseEvents > 0 && _careerPayBonusEvents > 0);
                    var cw = _avatars.FirstOrDefault(x => x.ObjectID == _chanceWorkerAvatarId);
                    var cwState = "missing";
                    if (cw != null)
                    {
                        try
                        {
                            var pd11 = cw.GetPersonData((VMPersonDataVariable)11);
                            var pd12 = cw.GetPersonData((VMPersonDataVariable)12);
                            var pd24 = cw.GetPersonData((VMPersonDataVariable)24);
                            if (_chanceDialogResponded && _chancePd24AtResponse != short.MinValue
                                && (pd24 != _chancePd24AtResponse || pd11 != _chancePd11AtResponse
                                    || pd12 != _chancePd12AtResponse))
                                _chanceEffectPdSeen = true;
                            cwState = "w56=" + cw.GetPersonData(VMPersonDataVariable.JobType)
                                + " w57=" + cw.GetPersonData(VMPersonDataVariable.JobPromotionLevel)
                                + " w63=" + cw.GetPersonData(VMPersonDataVariable.JobPerformance)
                                + " pd24=" + pd24 + " (" + _chancePd24AtResponse + " at response)"
                                + " pd11=" + pd11 + " (" + _chancePd11AtResponse + ")"
                                + " pd12=" + pd12 + " (" + _chancePd12AtResponse + ")";
                        }
                        catch (Exception cws) { cwState = "EXC " + cws.GetType().Name; }
                    }
                    var effectsAfter = _chanceEffectBudgetEvents > 0 || _chanceEffectPdSeen;
                    var chanceLive = _chanceFixtureValid && payWindowRan
                        && cascadeSeen && _chanceDialogResponded && effectsAfter;
                    Log("AUTOTEST chancetrace summary fixture=" + _chanceFixtureValid +
                        " perfCollapsed=" + _chancePerfCollapsed + " perfMinute=" + _chancePerfSetMinute +
                        " payWindowRan=" + payWindowRan +
                        " chanceIds=[" + string.Join(",", chanceIdsSeen) + "] cascadeFrameSeen=" + _chanceCascadeFrameSeen +
                        " postEndIds=[" + string.Join(",", _careerPostEndFrameIds.OrderBy(x => x)) + "]" +
                        " dialogResponded=" + _chanceDialogResponded +
                        " dialogRespondStack=" + (_chanceDialogRespondStack ?? "none") +
                        " effectBudgetEvents=" + _chanceEffectBudgetEvents +
                        " effectPdSeen=" + _chanceEffectPdSeen +
                        " worker={" + cwState + "}" +
                        " payEvents=[" + string.Join(",", _careerBudgetEvents) + "]" +
                        " timeline=[" + string.Join(" | ", _chanceTimeline) + "]" +
                        " (CarPortal 4103:54 -> 4134/4124/4133 cascade, Science level-5 Science02 card; R222)");
                    if (chanceLive) Pass("chancetrace"); else Fail("chancetrace");
                }
                Finish();
            }
            catch (Exception cse)
            {
                Log("AUTOTEST carseek EXC " + cse.GetType().Name + " " + cse.Message);
                if (CheckEnabled("carseek")) Fail("carseek");
                if (CheckEnabled("carreturn")) Fail("carreturn");
                if (CheckEnabled("schoolreturn")) Fail("schoolreturn");
                if (CheckEnabled("schoolmiss")) Fail("schoolmiss");
                if (CheckEnabled("chancetrace")) Fail("chancetrace");
                Finish();
            }
        }

        // (Round 222) CHANCETRACE statics — the career Chance Card trace. Static law
        // (decoded from the staged CarPortal.iff, r222 law doc): 4103 'get paid' ins54
        // CALLs 4134 'Chance Cards 3' (expansion careers 17-21, else cascades) ->
        // 4124 'Chance Cards 2' (careers 1-10) -> 4133 'Chance Cards' (12-16); the
        // per-career/level card body raises a BLOCKING STR#301 dialog (title $Me,
        // icon 'job $Local:9'), then applies budget/PD/sound effects and sets the
        // PD[24] shown-latch. The fork into the card is 4103 ins38-43 (level != 0,
        // MyPD[63] > min of two rnd(0..99) -> promotion instead).
        private static bool _chanceFixtureValid;
