        private static string ChanceClock()
        {
            try { return (_vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")); }
            catch { return "?"; }
        }

        // The chancetrace player move: answer the chance card's blocking dialog. Runs at
        // the very top of StateCarpool, BEFORE the generic R157 unpause (which would
        // orphan the latch unanswered). Only fires when the latch owner's stack carries
        // one of the chance tree ids — every other blocking dialog keeps its existing
        // handling. Applies the exact VMNetDialogResponseCmd TS1 law.
        private static void ChanceTraceRespondDialog()
        {
            try
            {
                var dlg = _vm.GlobalBlockingDialog;
                if (dlg == null) return;
                var th = dlg.Thread;
                if (th == null || th.Stack == null) return;
                string chain = "";
                var chanceOwned = false;
                for (int f = 0; f < th.Stack.Count; f++)
                {
                    var fr = th.Stack[f];
                    if (fr == null) continue;
                    var id = (ushort)((fr.Routine?.Chunk?.ChunkID) ?? 0);
                    string fOwner = null;
                    try { fOwner = fr.ScopeResource?.MainIff?.Filename; } catch { }
                    chain += id + ":" + (fr.InstructionPointer) + ",";
                    // (R222 run 5) ids are per-IFF — only CarPortal-owned cascade frames
                    // identify the card dialog (User00009.iff also has a 4124).
                    if ((id == 4124 || id == 4133 || id == 4134)
                        && fOwner != null && fOwner.ToLowerInvariant().IndexOf("carportal") >= 0) chanceOwned = true;
                }
                if (!chanceOwned) return;
                var bs = th.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                if (bs == null || bs.Responded) return;
                bs.Responded = true;
                bs.ResponseCode = 0; // the first choice
                bs.ResponseText = "0";
                if (_vm.LastSpeedMultiplier > 0)
                {
                    _vm.SpeedMultiplier = _vm.LastSpeedMultiplier;
                    _vm.LastSpeedMultiplier = 0;
                }
                else if (_vm.SpeedMultiplier < 0) _vm.SpeedMultiplier = 1;
                _vm.GlobalBlockingDialog = null;
                if (!_chanceDialogResponded)
                {
                    _chanceDialogResponded = true;
                    _chanceDialogRespondStack = chain;
                    var cw = _avatars.FirstOrDefault(x => x.ObjectID == _chanceWorkerAvatarId);
                    if (cw != null)
                    {
                        _chancePd11AtResponse = cw.GetPersonData((VMPersonDataVariable)11);
                        _chancePd12AtResponse = cw.GetPersonData((VMPersonDataVariable)12);
                        _chancePd24AtResponse = cw.GetPersonData((VMPersonDataVariable)24);
                    }
                    var line = "chance-card dialog ANSWERED (ResponseCode=0) owner=obj" + dlg.ObjectID +
                        " stack=[" + chain + "] at " + ChanceClock();
                    _chanceTimeline.Add(line);
                    Log("AUTOTEST " + line);
                }
            }
            catch (Exception cre)
            {
                Log("AUTOTEST chancetrace respond EXC " + cre.GetType().Name + " " + cre.Message);
            }
        }

        private static short[][] SnapshotAll()
        {
