        // brainlive probe: scan every live avatar's active thread stack for frames owned by the
        // ORIGINAL PersonGlobals.iff brain (frame CodeOwner resource main iff filename contains
        // 'personglobals'). IFF-factual owner mapping: avatars resolve their 8xxx semi-global code
        // to PersonGlobals (mirrors VMEntity.SemiGlobal / callgraph check). Pure read of public
        // VM state - no engine change, no timing impact.
        private static bool BrainDiagDone;

        // brainlive probe: scan every live avatar's active thread stack for frames that execute code
        // OWNED by the ORIGINAL PersonGlobals.iff brain. IFF-factual identity: a frame's code
        // scope is fr.ScopeResource.SemiGlobal (the module that resolved its routine) — VMMemory
        // names it via SemiGlobal.Iff.Filename. PersonGlobals-owned frames have that filename ==
        // 'PersonGlobals.iff'. Pure read of public VM state - no engine change.
        private static void ProbeBrainLive()
        {
            if (_vm == null) return;
            try
            {
                for (int i = 0; i < _avatars.Count; i++)
                {
                    var th = _avatars[i].Thread;
                    if (th == null || th.Stack == null) continue;
                    if (!BrainDiagDone)
                    {
                        // first-sample diagnostic: WHAT is actually on the live avatar stacks
                        Log("AUTOTEST brainlive diag av" + i + " threads=" + th.Stack.Count);
                        for (int f = 0; f < th.Stack.Count; f++)
                        {
                            var fr0 = th.Stack[f];
                            if (fr0 == null) continue;
                            string sgName = null, rName = null;
                            try { sgName = fr0.ScopeResource?.SemiGlobal?.Iff?.Filename; } catch { }
                            try { rName = fr0.Routine?.Rti?.Name; } catch { }
                            Log("AUTOTEST brainlive diag   frame" + f + " routineID=" + (fr0.Routine?.Chunk?.ChunkID) +
                                (fr0.Routine?.Chunk != null ? (" label=" + (fr0.Routine.Chunk as FSO.Files.Formats.IFF.Chunks.BHAV)?.ChunkLabel) : "") +
                                " rti=" + rName + " semiGlobal=" + sgName);
                        }
                    }
                    for (int f = 0; f < th.Stack.Count; f++)
                    {
                        var fr = th.Stack[f];
                        if (fr == null) continue;
                        try
                        {
                            var sgName = fr.ScopeResource?.SemiGlobal?.Iff?.Filename;
                            if (sgName == null || sgName.IndexOf("ersonglobals", StringComparison.OrdinalIgnoreCase) < 0) continue;
                            BrainPgSeen = true;
                            BrainPgRoutineCount++;
                            var id = (ushort)((fr.Routine?.Chunk?.ChunkID) ?? 0);
                            if (id != 0) BrainPgRoutinesSeen.Add(id);
                        }
                        catch { }
                    }
                }
                BrainDiagDone = true;
            }
            catch (Exception) { }
        }

