        // (SIM-03) socexec state: one real social driven end-to-end (push -> enqueue ->
        // route -> run -> completion) with an NBRS relationship diff on both directions.
        // Opt-in; never in the default Checks string. Accept/refuse are both legal content
        // outcomes — the probe proves the execution path and the rel write, not the sign.
        private static bool _socExecDone;
        private static bool _socExecPushed;
        private static bool _socEnqueuedSeen;
        private static bool _socStartSeen;
