        // 99,20}; engine VMAvatar.TS1 Init mirrors it IFF-literally (resolved: NOT blanket-100).
        private static void CheckMotiveInit()
        {
            try
            {
                int ok = 0;
                var notes = new List<string>();
                IffFile pg = Content.Get().TS1Global.Get("PersonGlobals.iff") as IffFile;
                var a0 = (_avatars == null || _avatars.Count == 0) ? null : _avatars[0];
                if (pg == null && a0?.Object?.Resource?.SemiGlobal?.Iff != null) pg = a0.Object.Resource.SemiGlobal.Iff;
                if (pg == null) { Log("AUTOTEST motiveinit: PersonGlobals.iff NOT mounted"); Fail("motiveinit"); return; }
                bool imOk = false;
                var im = pg.List<BHAV>().FirstOrDefault(x => (x.ChunkLabel ?? "").Trim().ToLowerInvariant() == "init motives");
                var idxSet = new HashSet<int>();
                if (im != null && im.Instructions != null)
                    foreach (var ins in im.Instructions)
                    {
                        if (ins.Opcode == 8 && ins.Operand != null && ins.Operand.Length >= 4)
                        {
                            var o = ins.Operand;
                            int idx = o[0] | (o[1] << 8); int sc = o[2] | (o[3] << 8);
                            if (sc == 14) idxSet.Add(idx); // 14 = MyMotives
                        }
                        if (ins.Opcode == 2 && ins.Operand != null && ins.Operand.Length >= 8)
                        {
                            var o = ins.Operand;
                            int lhs = o[0] | (o[1] << 8); int rhs = o[2] | (o[3] << 8); int ls = o[6]; int rs = o[7];
                            if (ls == 14) idxSet.Add(lhs & 0x7FFF);
                            if (rs == 14) idxSet.Add(rhs & 0x7FFF);
                        }
                    }
                if (idxSet.Count == 0) { Log("AUTOTEST motiveinit: 'init motives' op8/op2 motive-set empty (IFF missing?)"); Fail("motiveinit"); return; }
                bool setOk = idxSet.SetEquals(new int[] { 5, 6, 7, 8, 9, 14, 15 });
                if (!setOk) notes.Add("init-motives-dd-set-drift"); else { imOk = true; ok++; }
                // BCON 8195 (IFF-literal canon: base keys 0..6, amount keys 8..14)
                var bc = pg.List<BCON>().FirstOrDefault(x => x.ChunkID == 8195);
                if (bc != null && bc.Constants != null && bc.Constants.Length >= 15)
                {
                    int[] baseR = new int[] { 50, 1, 1, 1, 50, 1, 15 };
                    int[] amtR = new int[] { 99, 99, 99, 99, 50, 99, 20 };
                    bool bOk = true, aOk = true;
                    for (int i = 0; i < 7; i++) { if (bc.Constants[i] != baseR[i]) bOk = false; if (bc.Constants[8 + i] != amtR[i]) aOk = false; }
                    if (bOk && aOk) ok++; else notes.Add("bcon8195-constant-drift");
                }
