        // R166: cXObject::TryGenericSimCall mode 12 rotates the stack object's tile through
        // CTilePt::BuildRotationLookup's fixed 64x64 table, then writes -(x+y) to Temp0.
        // The table is independent of current lot dimensions. The owned corpus has 47 call
        // instances across taxi/carpool/school/vacation/studio/NPC vehicle routines.
        private static void CheckGenericCall12()
        {
            try
            {
                var points = new (short X, short Y, short[] Expected)[]
                {
                    (11, 23, new short[] { -34, -51, -92, -75 }),
                    (0, 0, new short[] { 0, -63, -126, -63 }),
                    (63, 63, new short[] { -126, -63, 0, -63 }),
                    (0, 63, new short[] { -63, 0, -63, -126 }),
                    (63, 0, new short[] { -63, -126, -63, 0 }),
                };
                bool math = true;
                var values = new List<string>();
                foreach (var point in points)
                {
                    for (int rotation = 0; rotation < 4; rotation++)
                    {
                        var got = FSO.SimAntics.Primitives.VMGenericTS1Call.GetDistanceToCamera(
                            point.X, point.Y, (FSO.LotView.WorldRotation)rotation);
                        math &= got == point.Expected[rotation];
                        values.Add(point.X + "," + point.Y + "/r" + rotation + "=" + got);
                    }
                }

                bool live = false;
                string liveInfo = "unavailable";
                var caller = (_avatars == null) ? null : _avatars.FirstOrDefault(a => a.Thread != null);
                var target = _vm?.Entities?.FirstOrDefault(
                    entity => entity != null
                        && entity.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD);
                if (caller != null && target != null)
                {
                    var thread = caller.Thread;
                    var previousTemp0 = thread.TempRegisters[0];
                    try
                    {
                        var frame = new FSO.SimAntics.Engine.VMStackFrame
                        {
                            Thread = thread,
                            Caller = caller,
                            Callee = caller,
                            StackObject = target,
                        };
                        var rotation = _vm.Context.World?.State.Rotation
                            ?? FSO.LotView.WorldRotation.TopLeft;
                        var expected = FSO.SimAntics.Primitives.VMGenericTS1Call.GetDistanceToCamera(
                            target.Position.TileX, target.Position.TileY, rotation);
                        var exit = new FSO.SimAntics.Primitives.VMGenericTS1Call().Execute(
                            frame,
                            new FSO.SimAntics.Primitives.VMGenericTS1CallOperand
                            {
                                Call = VMGenericTS1CallMode.GetDistanceToCameraInTemp0,
                            });
                        live = exit == FSO.SimAntics.Engine.VMPrimitiveExitCode.GOTO_TRUE
                            && thread.TempRegisters[0] == expected;
                        liveInfo = "obj=" + target.ObjectID
                            + " tile=" + target.Position.TileX + "," + target.Position.TileY
                            + " rotation=" + rotation + " expected=" + expected
                            + " got=" + thread.TempRegisters[0] + " exit=" + exit;
                    }
                    finally
                    {
                        thread.TempRegisters[0] = previousTemp0;
                    }
                }
                Log("AUTOTEST genericcall12 math=" + math + " live=" + live
                    + " liveInfo=[" + liveInfo + "] values=[" + string.Join(" ", values) + "]");
                if (math && live) { Pass("genericcall12"); return; }
                Fail("genericcall12");
            }
            catch (Exception error)
            {
                Log("AUTOTEST genericcall12 EXC " + error.GetType().Name + " " + error.Message);
                Fail("genericcall12");
            }
        }

        // R167: cXObject::TryGenericSimCall mode 13 resolves Stack Object ID, then
        // ObjectModule::CleanupPeople invokes cXPerson::Cleanup(target) on every
        // person except target. TS1 OBJM Interaction.TargetID/Icon map to the VM's
        // Callee/IconOwner fields. The packaged check pins both original callers
        // and invokes the production handler against an isolated queue fixture.
        private static void CheckGenericCall13()
        {
            try
            {
                var phone = Content.Get()?.TS1Global?.Get("PhoneGlobals.iff") as IffFile;
                var importLot = phone?.Get<BHAV>(8252);
                var main = phone?.Get<BHAV>(8284);
                var selfOperand = new byte[] { 0, 0, 11, 0, 0, 5, 10, 3 };
                bool EntrySetsSelf(BHAV bhav)
                {
                    var entry = bhav?.Instructions?.FirstOrDefault();
                    return entry != null && entry.Opcode == 2
                        && entry.Operand != null && entry.Operand.SequenceEqual(selfOperand);
                }
                bool Mode13At(BHAV bhav, int index, byte truePointer, byte falsePointer)
                {
                    if (bhav?.Instructions == null || index < 0 || index >= bhav.Instructions.Length)
                        return false;
                    var instruction = bhav.Instructions[index];
                    return instruction.Opcode == 1
                        && instruction.TruePointer == truePointer
                        && instruction.FalsePointer == falsePointer
                        && instruction.Operand != null
                        && instruction.Operand.Length == 8
                        && instruction.Operand[0] == 13
                        && instruction.Operand.Skip(1).All(value => value == 0);
                }
                bool iffAnchor = importLot?.Instructions?.Length == 2
                    && EntrySetsSelf(importLot) && Mode13At(importLot, 1, 254, 253)
                    && main?.Instructions?.Length == 13
                    && EntrySetsSelf(main) && main.Instructions[0].TruePointer == 6
                    && Mode13At(main, 1, 5, 253)
                    && main.Instructions[12].Opcode == 8197
                    && main.Instructions[12].TruePointer == 1
                    && main.Instructions[12].FalsePointer == 1;

                var syntheticVM = (VM)System.Runtime.CompilerServices.RuntimeHelpers
                    .GetUninitializedObject(typeof(VM));
                syntheticVM.TS1 = true;
                syntheticVM.Entities = new List<VMEntity>();
                var syntheticContext = (VMContext)System.Runtime.CompilerServices.RuntimeHelpers
                    .GetUninitializedObject(typeof(VMContext));
                syntheticContext.VM = syntheticVM;
                syntheticContext.ObjectQueries = new VMObjectQueries(syntheticContext);
                var contextProperty = typeof(VM).GetProperty(
                    nameof(VM.Context),
                    System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic);
                contextProperty.SetValue(syntheticVM, syntheticContext);

                VMGameObject NewObject()
                {
                    var result = (VMGameObject)System.Runtime.CompilerServices.RuntimeHelpers
                        .GetUninitializedObject(typeof(VMGameObject));
                    result.ObjectData = new short[80];
                    result.EntryPoints = new OBJfFunctionEntry[33];
                    return result;
                }

                var actor = (VMAvatar)System.Runtime.CompilerServices.RuntimeHelpers
                    .GetUninitializedObject(typeof(VMAvatar));
                actor.ObjectData = new short[80];
                actor.EntryPoints = new OBJfFunctionEntry[33];
                var personDataField = typeof(VMAvatar).GetField(
                    "PersonData",
                    System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic);
                personDataField.SetValue(actor, new short[101]);
                actor.Thread = new FSO.SimAntics.Engine.VMThread(
                    syntheticContext, actor, 4);
                syntheticContext.ObjectQueries.Avatars.Add(actor);
                syntheticVM.Entities.Add(actor);

                var target = NewObject();
                var decoy = NewObject();
                actor.Thread.Queue.Add(new FSO.SimAntics.Engine.VMQueuedAction
                {
                    UID = 1,
                    Callee = target,
                    StackObject = decoy,
                    IconOwner = decoy,
                    Mode = FSO.SimAntics.Engine.VMQueueMode.Normal,
                });
                actor.Thread.Queue.Add(new FSO.SimAntics.Engine.VMQueuedAction
                {
                    UID = 2,
                    Callee = decoy,
                    StackObject = decoy,
                    IconOwner = target,
                    Mode = FSO.SimAntics.Engine.VMQueueMode.Normal,
                });
                actor.Thread.Queue.Add(new FSO.SimAntics.Engine.VMQueuedAction
                {
                    UID = 3,
                    Callee = decoy,
                    StackObject = decoy,
                    Mode = FSO.SimAntics.Engine.VMQueueMode.Normal,
                });

                var dispatchThread = new FSO.SimAntics.Engine.VMThread(
                    syntheticContext, null, 1);
                dispatchThread.TempRegisters[0] = 12345;
                var exit = new FSO.SimAntics.Primitives.VMGenericTS1Call().Execute(
                    new FSO.SimAntics.Engine.VMStackFrame
                    {
                        Thread = dispatchThread,
                        StackObject = target,
                    },
                    new FSO.SimAntics.Primitives.VMGenericTS1CallOperand
                    {
                        Call = VMGenericTS1CallMode.AbortInteractions,
                    });
                var remaining = actor.Thread.Queue.Select(action => action.UID).ToArray();
                bool dispatch = exit == FSO.SimAntics.Engine.VMPrimitiveExitCode.GOTO_TRUE
                    && dispatchThread.TempRegisters[0] == 12345
                    && remaining.SequenceEqual(new ushort[] { 3 });

                Log("AUTOTEST genericcall13 iff=" + iffAnchor
                    + " dispatch=" + dispatch
                    + " remaining=[" + string.Join(",", remaining) + "]"
                    + " temp0=" + dispatchThread.TempRegisters[0]
                    + " exit=" + exit);
                if (iffAnchor && dispatch) { Pass("genericcall13"); return; }
                Fail("genericcall13");
            }
            catch (Exception error)
            {
                Log("AUTOTEST genericcall13 EXC " + error.GetType().Name + " " + error.Message);
                Fail("genericcall13");
            }
        }

        // R168: cXObject::TryGenericSimCall mode 14 loads signed Temp0 from the
        // receiver, calls cSimulator::SetGlobal(31, Temp0), then takes the common
        // true return. The full owned-data census has 18 calls in 13 IFFs; each
        // caller initializes Temp0 and ignores the false branch. This packaged
        // check pins representative parameter/literal callers and dispatches the
        // production primitive over the signed 16-bit boundary while restoring
        // all live VM state in a finally block.
        private static void CheckGenericCall14()
        {
            short[] savedGlobals = null;
            short[] savedTemps = null;
            FSO.SimAntics.Engine.VMThread thread = null;
            try
            {
                bool InstructionAt(BHAV bhav, int index, ushort opcode,
                    byte truePointer, byte falsePointer, byte[] operand)
                {
                    if (bhav?.Instructions == null || index < 0
                        || index >= bhav.Instructions.Length) return false;
                    var instruction = bhav.Instructions[index];
                    return instruction.Opcode == opcode
                        && instruction.TruePointer == truePointer
                        && instruction.FalsePointer == falsePointer
                        && instruction.Operand != null
                        && instruction.Operand.SequenceEqual(operand);
                }

                var ts1 = Content.Get()?.TS1Global;
                var stereos = ts1?.Get("Stereos.iff") as IffFile;
                var piano = ts1?.Get("piano.iff") as IffFile;
                var stereoSwitch = stereos?.Get<BHAV>(4118);
                var pianoNpc = piano?.Get<BHAV>(4117);
                var mode14 = new byte[] { 14, 0, 0, 0, 0, 0, 0, 0 };
                var temp0FromParam0 = new byte[] { 0, 0, 0, 0, 0, 5, 8, 9 };
                var temp0FromLiteral2 = new byte[] { 0, 0, 2, 0, 0, 5, 8, 7 };
                bool iffAnchor = stereoSwitch?.Instructions?.Length == 11
                    && InstructionAt(stereoSwitch, 1, 2, 8, 253, temp0FromParam0)
                    && InstructionAt(stereoSwitch, 8, 1, 7, 253, mode14)
                    && pianoNpc?.Instructions?.Length == 29
                    && InstructionAt(pianoNpc, 24, 2, 25, 253, temp0FromLiteral2)
                    && InstructionAt(pianoNpc, 25, 1, 27, 253, mode14);

                thread = (_avatars == null)
                    ? null
                    : _avatars.FirstOrDefault(avatar => avatar?.Thread != null)?.Thread;
                if (_vm?.GlobalState == null || _vm.GlobalState.Length <= 31 || thread == null)
                {
                    Log("AUTOTEST genericcall14 live VM fixture unavailable");
                    Fail("genericcall14");
                    return;
                }

                var registration = VMContext.Primitives[1];
                bool registered = registration != null
                    && registration.Opcode == 1
                    && registration.Name == "generic_sims_call"
                    && registration.OperandModel
                        == typeof(FSO.SimAntics.Primitives.VMGenericTS1CallOperand)
                    && registration.GetHandler()
                        is FSO.SimAntics.Primitives.VMGenericTS1Call;
                var operand = new FSO.SimAntics.Primitives.VMGenericTS1CallOperand();
                operand.Read(mode14);
                bool decoded = operand.Call
                    == VMGenericTS1CallMode.HouseRadioStationEqualsTemp0
                    && (byte)operand.Call == 14;

                savedGlobals = (short[])_vm.GlobalState.Clone();
                savedTemps = (short[])thread.TempRegisters.Clone();
                var values = new short[]
                {
                    short.MinValue, -32767, -1, 0, 1, 2, 30, short.MaxValue,
                };
                var decoy = _vm.Entities?.FirstOrDefault(entity => entity != null);
                var handler = registration?.GetHandler();
                bool dispatch = registered && decoded && decoy?.ObjectID != 0;
                var results = new List<string>();
                for (int caseIndex = 0; caseIndex < values.Length; caseIndex++)
                {
                    var globalsBefore = (short[])_vm.GlobalState.Clone();
                    var tempsBefore = (short[])thread.TempRegisters.Clone();
                    var value = values[caseIndex];
                    thread.TempRegisters[0] = value;
                    thread.TempRegisters[1] = -12345;
                    var exit = handler.Execute(
                        new FSO.SimAntics.Engine.VMStackFrame
                        {
                            Thread = thread,
                            StackObject = ((caseIndex & 1) == 0) ? null : decoy,
                        },
                        operand);
                    bool otherGlobalsUnchanged = Enumerable.Range(0, _vm.GlobalState.Length)
                        .All(index => index == 31
                            || _vm.GlobalState[index] == globalsBefore[index]);
                    bool otherTempsUnchanged = Enumerable.Range(2, thread.TempRegisters.Length - 2)
                        .All(index => thread.TempRegisters[index] == tempsBefore[index]);
                    bool caseOk = exit == FSO.SimAntics.Engine.VMPrimitiveExitCode.GOTO_TRUE
                        && _vm.GlobalState[31] == value
                        && thread.TempRegisters[0] == value
                        && thread.TempRegisters[1] == -12345
                        && otherGlobalsUnchanged
                        && otherTempsUnchanged;
                    dispatch &= caseOk;
                    results.Add(value + "->" + _vm.GlobalState[31]
                        + "/" + exit + "/" + caseOk);
                }

                Log("AUTOTEST genericcall14 iff=" + iffAnchor
                    + " registered=" + registered
                    + " decoded=" + decoded
                    + " dispatch=" + dispatch
                    + " values=[" + string.Join(" ", results) + "]"
                    + " (global31 assignment; Stack Object ignored)");
                if (iffAnchor && dispatch) { Pass("genericcall14"); return; }
                Fail("genericcall14");
            }
            catch (Exception error)
            {
                Log("AUTOTEST genericcall14 EXC " + error.GetType().Name + " " + error.Message);
                Fail("genericcall14");
            }
            finally
            {
                if (savedGlobals != null && _vm?.GlobalState != null)
                    Array.Copy(savedGlobals, _vm.GlobalState,
                        Math.Min(savedGlobals.Length, _vm.GlobalState.Length));
                if (savedTemps != null && thread?.TempRegisters != null)
                    Array.Copy(savedTemps, thread.TempRegisters,
                        Math.Min(savedTemps.Length, thread.TempRegisters.Length));
            }
        }


        // CALLGRAPH IFF-LITERAL (Round 44): the ORIGINAL object scripting surface stays IFF-literal -
        // aggregate opcode histogram over the 20 fixture objects (engine-independent raw census r44:
        // 747 BHAVs / 7767 instructions; op2=4035, op44=475, op23=433, op32=157, op31=152, op8=88,
        // op48=81, op29=77, op13=21). The engine-mounted equivalents MUST match IFF-literally; ANY
