                                case 2: op2++; break; case 44: op44++; break; case 23: op23++; break;
                                case 32: op32++; break; case 31: op31++; break; case 8: op8++; break;
                                case 48: op48++; break; case 29: op29++; break; case 13: op13++; break;
                            }
                        }
                    }
                }
                bool ok = mounted == 20 && tot == 7767 && op2 == 4035 && op44 == 475 && op23 == 433 && op32 == 157
                    && op31 == 152 && op8 == 88 && op48 == 81 && op29 == 77 && op13 == 21;
                Log("AUTOTEST callgraph object-surface histogram: mounted=" + mounted + "/20 total=" + tot + " op2=" + op2 + " op44=" + op44 + " op23=" + op23 + " op32=" + op32 + " op31=" + op31 + " op8=" + op8 + " op48=" + op48 + " op29=" + op29 + " op13=" + op13 + " ok=" + ok);
                if (ok) { Pass("callgraph"); return; }
                Log("AUTOTEST callgraph: object scripting surface must stay IFF-literal (Round 44)");
                Fail("callgraph");
            }
            catch (Exception cge) { Log("AUTOTEST callgraph EXC " + cge.GetType().Name + " " + cge.Message); Fail("callgraph"); }
        }

