                var files = new string[] { "Easel.iff", "ChessTable.iff", "Beds.iff", "Fridges.iff", "Stoves.iff", "TVs.iff", "ShowerC.iff", "TubC.iff", "TubM.iff", "Toilets.iff", "Mirrors.iff", "ExerciseMachine.iff", "BBQ.iff", "Bookcases.iff", "Computers.iff", "Stereos.iff", "Bars.iff", "HotTub.iff", "Recliners.iff", "ChairsLR1Tile.iff" };
                // raw r45 canon (engine-independent; sum(id*count)=338605)
                var canon = new Dictionary<int, long> {
                    { 259, 4L }, { 260, 35L }, { 261, 2L }, { 265, 29L }, { 271, 23L },
                    { 272, 44L }, { 273, 65L }, { 277, 15L }, { 278, 2L }, { 279, 3L },
                    { 280, 75L }, { 281, 149L }, { 282, 11L }, { 283, 2L }, { 284, 2L },
                    { 285, 8L }, { 286, 15L }, { 287, 4L }, { 288, 4L }, { 290, 21L },
                    { 291, 2L }, { 292, 1L }, { 293, 4L }, { 294, 2L }, { 295, 7L },
                    { 297, 5L }, { 300, 2L }, { 302, 5L }, { 303, 1L }, { 304, 1L },
                    { 306, 1L }, { 307, 1L }, { 308, 4L }, { 309, 4L }, { 310, 3L },
                    { 319, 12L }, { 320, 14L }, { 321, 57L }, { 332, 4L }, { 333, 1L },
                    { 334, 5L }, { 336, 1L }, { 339, 4L }, { 340, 7L }, { 347, 11L },
                    { 348, 7L }, { 349, 7L }, { 350, 9L }, { 351, 5L }, { 355, 4L },
                    { 357, 54L }, { 358, 2L }, { 359, 1L }, { 362, 3L }, { 363, 38L },
                    { 365, 73L }, { 370, 8L }, { 374, 3L }, { 377, 1L }, { 379, 6L },
                    { 382, 13L }, { 386, 10L }, { 387, 1L }, { 388, 2L }, { 389, 7L },
                    { 392, 1L }, { 393, 3L }, { 394, 5L }, { 395, 1L }, { 398, 2L },
                    { 399, 9L }, { 400, 3L }, { 401, 4L }, { 402, 4L }, { 403, 6L },
                    { 405, 6L }, { 406, 5L }, { 407, 7L }, { 408, 3L }, { 409, 4L },
                    { 410, 4L }, { 411, 1L }, { 412, 2L }, { 413, 1L }, { 415, 5L },
                    { 417, 10L }, { 424, 14L }, { 427, 1L }, { 446, 4L }, { 464, 3L },
                    { 467, 4L }, { 468, 1L }, { 469, 5L }, { 479, 3L }, { 485, 2L },
                    { 488, 2L }, { 489, 1L }, { 492, 1L }
                };
                var hist = new Dictionary<int, long>();
