                    foreach (var b in gIff.List<BHAV>())
                    {
                        gIds.Add(b.ChunkID);
                        var lbl = (b.ChunkLabel ?? "").Trim();
                        if (lbl.Length > 0) { gNamed.Add(b.ChunkID); nameMap[b.ChunkID] = lbl; }
                    }
                long resolved = 0, unresolved = 0, unnamed = 0;
                foreach (var k in hist.Keys)
