                var top = hist.OrderByDescending(k => k.Value).Take(3).Select(k => np(k.Key) + "(" + k.Key + ")x" + k.Value).ToArray();
                bool ok = exact && mounted == 20 && tot == 1053 && hist.Count == 98 && resolved == 98
                    && unnamed == 0 && unresolved == 0 && checksum == 338605;
