                    " distinct=" + hist.Count + " resolved=" + resolved + " named=" + resolved + " unresolved=" +
                    unresolved + " checksum=" + checksum + " top=[" + string.Join(",", top) + "] ok=" + ok);
                if (ok) { Pass("globalcalls"); return; }
                Log("AUTOTEST globalcalls: global-dispatch surface must stay IFF-literal (Round 45: 1053/98/98/98, checksum 338605)");
                Fail("globalcalls");
            }
            catch (Exception gce) { Log("AUTOTEST globalcalls EXC " + gce.GetType().Name + " " + gce.Message); Fail("globalcalls"); }
        }

        // CATALOG IFF-LITERAL (Round 46): the ORIGINAL buy-mode catalog surface stays IFF-literal.
        // The engine's served buy catalog (TS1ObjectProvider / WorldCatalog) is IFF-built from the
        // ORIGINAL OBJD tables (Price = obj.Price, Category = log2(FunctionFlags) or BuildModeType+7,
        // passesCatalogCheck predicate). Engine-independent raw canon (tools/iff_objd_canon.py +
        // iff_objd_raw.py over game-data/The Sims): 1114 catalog-eligible GUIDs, checksum
        // 3356090364479856, plus per-fixture OBJD constants. IFF-literally: EVERY served item's
        // price/category must equal the raw OBJD canon, none dropped, none phantom, and the mounted
        // original fixture OBJDs must match - any drift (hardcoded price, edited/regenerated OBJD,
        // added/removed entry) FAILS. Honest scope: pins the DATA surface (price/category/eligibility)
        // served to buy-mode UI; live buy-mode UI purchase flows still need play.
        private static void CheckCatalog()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST catalog: no TS1Global (original-object mounts unavailable)"); Fail("catalog"); return; }

                // Part A - IFF-literal fixture OBJD recompute. OBJD.RawData is the raw u16 field array
                // the ORIGINAL IFF carries: Price@16, FunctionFlags@38, BuildModeType@67, Disabled@14,
                // MasterID@8, SubIndex@9 (int16), NumGraphics@2. IFF-literally must equal the canon.
                int fixtureOk = 0; var notes = new List<string>();
                foreach (var kv in AutotestCatalogCanon.FixtureEligible)
                {
                    var iff = ts1.Get(kv.Key) as IffFile;
                    if (iff == null) { notes.Add(kv.Key + "-not-mounted"); continue; }
                    var mine = new List<uint>();
                    long sum = 0; long rawSum = 0;
                    var bhavs = new Dictionary<uint, int[]>();
                    foreach (var obj in iff.List<OBJD>())
                    {
                        if (obj.RawData == null || obj.RawData.Length <= 67) continue;
                        var price = obj.RawData[16];
                        var ff = obj.RawData[38];
                        var bmt = obj.RawData[67];
                        var dis = obj.RawData[14];
                        var mid = obj.RawData[8];
                        short si = (short)obj.RawData[9];
                        var ng = obj.RawData[2];
                        if ((ff > 0 || bmt > 0) && dis == 0 && (mid != 0 || ng > 0) && (mid == 0 || si == -1))
                        {
                            mine.Add(obj.GUID);
                            sum += (long)obj.GUID * price;
                            // Round 49 - IFF-literal FULL-RAW + BEHAVIORAL-ENTRY surface: the engine-exposed
                            // OBJD.RawData field array (IFF read) and the VM's behavioural entry ids
                            // (BHAV_MainID@3, AnimationTableID@11, BHAV_Init@40, BHAV_Place@41, BHAV_UserPickup@42,
                            // BHAV_Load@44, BHAV_UserPlace@45) must equal the IFF-literal canon.
                            var lim = Math.Min(obj.RawData.Length, 104);
                            for (int i = 0; i < lim; i++) rawSum += (long)obj.RawData[i] * (i + 1);
                            bhavs[obj.GUID] = new int[] { obj.RawData[3], obj.RawData[11], obj.RawData[40], obj.RawData[41], obj.RawData[42], obj.RawData[44], obj.RawData[45] };
                        }
                    }
                    mine.Sort();
                    var canonGuids = AutotestCatalogCanon.FixtureGuids[kv.Key];
                    bool same = mine.Count == kv.Value && mine.Count == canonGuids.Length;
                    if (same)
                        for (int i = 0; i < mine.Count; i++)
                            if (mine[i] != canonGuids[i]) { same = false; break; }
                    if (!same) { notes.Add(kv.Key + "-guids-drift"); continue; }
                    if (AutotestCatalogCanon.FixtureChecksum[kv.Key] != sum) { notes.Add(kv.Key + "-price-drift"); continue; }
                    if (AutotestCatalogCanon.FixtureRawChecksum[kv.Key] != rawSum) { notes.Add(kv.Key + "-raw-drift"); continue; }
                    bool bhavOk = bhavs.Count == AutotestCatalogCanon.FixtureBHAVs[kv.Key].Count;
                    if (bhavOk)
                        foreach (var bg in bhavs)
                        {
                            int[] canonB;
                            if (!AutotestCatalogCanon.FixtureBHAVs[kv.Key].TryGetValue(bg.Key, out canonB)) { bhavOk = false; break; }
                            var v = bg.Value; bool eq = v.Length == canonB.Length;
                            if (eq) for (int x = 0; x < v.Length; x++) if (v[x] != canonB[x]) { eq = false; break; }
                            if (!eq) { bhavOk = false; break; }
                        }
                    if (!bhavOk) { notes.Add(kv.Key + "-bhav-drift"); continue; }
                    fixtureOk++;
                }

                // Part B - whole-corpus serve pin: EVERY served catalog entry must equal the IFF-literal
                // raw OBJD canon (price + category): none phantom, none dropped, none hardcoded.
                var served = Content.Get().WorldCatalog.All();
                int servMatch = 0; var srvNotes = new List<string>();
                foreach (var it in served)
                {
                    int[] canon;
                    if (!AutotestCatalogCanon.CatalogCanon.TryGetValue(it.GUID, out canon)) { srvNotes.Add("phantom 0x" + it.GUID.ToString("x8")); continue; }
                    if (canon[0] != (int)it.Price || canon[1] != (int)it.Category) { srvNotes.Add("price-cat 0x" + it.GUID.ToString("x8") + " served=" + ((int)it.Price) + "/" + ((int)it.Category) + " canon=" + canon[0] + "/" + canon[1]); continue; }
                    servMatch++;
                }
                int servMissing = 0;
                foreach (var kv in AutotestCatalogCanon.CatalogCanon)
                    if (!Content.Get().WorldCatalog.GetItemByGUID(kv.Key).HasValue) servMissing++;
                bool partB = servMatch == served.Count && served.Count == AutotestCatalogCanon.Eligible && servMissing == 0;

                // Part C (Round 47) - IFF-literal SORT-BYTE surface pin: every served catalog item's
                // RoomSort/Subsort/DowntownSort/VacationSort/CommunitySort/StudiotownSort/MagictownSort must
                // equal the raw OBJD canon (RoomFlags@37, FunctionSubsort@92, DTSubsort@93, VacationSubsort@95,
                // CommunitySubsort@97, STSubsort@101, MTSubsort@102). IFF-literal: the v138 corpus carries
                // 106 fields and the engineered OBJD.Read parses them all (Round 47 fix), so canon == served ==
                // raw IFF bytes for every sort byte - nothing is frozen at 0. Closes R46's flagged 'RoomFlags
                // raw-available but not asserted'. Any drift (hardcoded sort, edited/regenerated OBJD) FAILS.
                int sortMatch = 0; var sortNotes = new List<string>();
                foreach (var it in served)
                {
                    int[] s;
                    if (!AutotestCatalogCanon.CatalogSorts.TryGetValue(it.GUID, out s)) { sortNotes.Add("sort-phantom 0x" + it.GUID.ToString("x8")); continue; }
                    if (s[0] != (int)it.RoomSort || s[1] != (int)it.Subsort || s[2] != (int)it.DowntownSort ||
                        s[3] != (int)it.VacationSort || s[4] != (int)it.CommunitySort ||
                        s[5] != (int)it.StudiotownSort || s[6] != (int)it.MagictownSort)
                    {
                        sortNotes.Add("sort-drift 0x" + it.GUID.ToString("x8") + " served=" + (int)it.RoomSort + "/" + (int)it.Subsort + "/" + (int)it.DowntownSort + "/" + (int)it.VacationSort + "/" + (int)it.CommunitySort + "/" + (int)it.StudiotownSort + "/" + (int)it.MagictownSort + " canon=" + s[0] + "/" + s[1] + "/" + s[2] + "/" + s[3] + "/" + s[4] + "/" + s[5] + "/" + s[6]);
                        continue;
                    }
                    sortMatch++;
                }
                int sortMissing = 0;
                foreach (var kv in AutotestCatalogCanon.CatalogSorts)
                    if (!Content.Get().WorldCatalog.GetItemByGUID(kv.Key).HasValue) sortMissing++;
                bool partC = sortMatch == served.Count && served.Count == AutotestCatalogCanon.Eligible && sortMissing == 0;

                // Part D (Round 48) - IFF-literal NAMES surface pin: every served item's Name must equal the raw
                // OBJD chunk LABEL (IObjectCatalogItem.Name = obj.ChunkLabel; chunkLabel = ASCII.GetString(64
                // label bytes).TrimEnd(0) - IFF-authored UI text via tso.files IffFile.cs/IoBuffer.cs).
                // IFF-literal canon tools/iff_objd_names.py (1114 labels, all ASCII, no high bytes). Any
                // client-invented/renamed label or mount loss FAILS the round-46/47/48 catalog pin.
                int nameMatch = 0; var nameNotes = new List<string>();
                foreach (var it in served)
                {
                    string canonN;
                    if (!AutotestCatalogCanon.CatalogNames.TryGetValue(it.GUID, out canonN)) { nameNotes.Add("name-phantom 0x" + it.GUID.ToString("x8")); continue; }
                    if (it.Name != canonN) { nameNotes.Add("name-drift 0x" + it.GUID.ToString("x8") + " served=" + it.Name + " canon=" + canonN); continue; }
                    nameMatch++;
                }
                int nameMissing = 0;
                foreach (var kv in AutotestCatalogCanon.CatalogNames)
                    if (!Content.Get().WorldCatalog.GetItemByGUID(kv.Key).HasValue) nameMissing++;
                bool partD = nameMatch == served.Count && served.Count == AutotestCatalogCanon.Eligible && nameMissing == 0;

                // Part E (Round 50/51) - whole-serving-corpus OBJD-SURFACE IFF-literal pin. Every served
                // item's mounted OBJD must equal the raw OBJD IFF canon (tools/iff_objd_corpus_bhavs.py,
                // 1114 entries) on BOTH: (a) the VM behavioural entry ids (BHAV_MainID@3, AnimationTableID@11,
                // BHAV_Init@40, BHAV_Place@41, BHAV_UserPickup@42, BHAV_Load@44, BHAV_UserPlace@45) and
                // (b, Round 51) the FULL engine-exposed OBJD.RawData field-array checksum (v138=104 fields,
                // v136=78 - IFF-literal mirror of the Round-47 fixed read). Engine index ObjdByGUID is pure
                // IFF data (TS1ObjectProvider.Init). None phantom, none dropped, none hardcoded - any engine
                // script-id invention, OBJD reinterpretation, or mount of a re-patched OBJD FAILS.
                int bhavC = 0; var bhavNotesE = new List<string>();
                foreach (var it in served)
                {
                    int[] canonB;
                    if (!AutotestCatalogCanon.CatalogBHAVs.TryGetValue(it.GUID, out canonB)) { bhavNotesE.Add("bhav-phantom 0x" + it.GUID.ToString("x8")); continue; }
                    OBJD obj;
                    if (!TS1ObjectProvider.ObjdByGUID.TryGetValue(it.GUID, out obj) || obj.RawData == null || obj.RawData.Length <= 45) { bhavNotesE.Add("bhav-no-objd 0x" + it.GUID.ToString("x8")); continue; }
                    bool eqB = obj.RawData[3] == canonB[0] && obj.RawData[11] == canonB[1] && obj.RawData[40] == canonB[2] &&
                        obj.RawData[41] == canonB[3] && obj.RawData[42] == canonB[4] && obj.RawData[44] == canonB[5] && obj.RawData[45] == canonB[6];
                    if (!eqB) { bhavNotesE.Add("bhav-drift 0x" + it.GUID.ToString("x8") + " served=" + obj.RawData[3] + "/" + obj.RawData[11] + "/" + obj.RawData[40] + "/" + obj.RawData[41] + "/" + obj.RawData[42] + "/" + obj.RawData[44] + "/" + obj.RawData[45] + " canon=" + canonB[0] + "/" + canonB[1] + "/" + canonB[2] + "/" + canonB[3] + "/" + canonB[4] + "/" + canonB[5] + "/" + canonB[6]); continue; }
                    // Round 51 - IFF-literal FULL engine-exposed OBJD.RawData surface: the entire field
                    // array (v138=104 fields via the Round-47 fixed read; v136=78) must equal the raw IFF
                    // checksum. Any engine OBJD reinterpretation or mount of a re-patched OBJD FAILS.
                    long rawSumR = 0;
                    var limR = Math.Min(obj.RawData.Length, 104);
                    for (int i = 0; i < limR; i++) rawSumR += (long)obj.RawData[i] * (i + 1);
                    long canonRaw;
                    if (!AutotestCatalogCanon.CatalogRawChecksum.TryGetValue(it.GUID, out canonRaw)) { bhavNotesE.Add("raw-no-canon 0x" + it.GUID.ToString("x8")); continue; }
                    if (canonRaw != rawSumR) { bhavNotesE.Add("raw-drift 0x" + it.GUID.ToString("x8") + " served=" + rawSumR + " canon=" + canonRaw); continue; }
                    bhavC++;
                }
                bool partE = bhavC == served.Count;

                // Part G (Round 52) - served-catalog DEFAULTS IFF-literal. The ORIGINAL buy catalog greys
                // no item and carries no tags; IFF-literally OBJD exposes no disable-level (DisableLevel==0)
                // and no tags (null). CatalogName (unset by the provider) must be null or equal the IFF label
                // (Name) - never an invented alternative. Guards engine invention across the FINAL unpinned
                // served IObjectCatalogItem fields (GUID/Category/Price/Name/sorts/behavior/raw all pinned).
                int defC = 0; var defNotes = new List<string>();
                foreach (var it in served)
                {
                    if (it.DisableLevel != 0) { defNotes.Add("dis 0x" + it.GUID.ToString("x8") + "=" + it.DisableLevel); continue; }
                    if (it.Tags != null) { defNotes.Add("tags 0x" + it.GUID.ToString("x8") + "=" + it.Tags); continue; }
                    if (it.CatalogName != null && it.CatalogName != it.Name) { defNotes.Add("catname 0x" + it.GUID.ToString("x8") + "=" + it.CatalogName + " vs " + it.Name); continue; }
                    defC++;
                }
                bool partG = defC == served.Count;

                // Part H (Round 53) - IFF-literal buy-catalog ENUMERATION-ORDER pin. The served order must equal
                // the IFF-literal canon: category-major asc (IObjectCatalog.All() = ItemsByCategory[0..29]
                // flattened; Category = IFF OBJD log2(FunctionFlags) or BuildModeType+7) then the ORIGINAL IFF
                // FAR-member encounter order (first IFF mount wins for duplicate members; cross-file IFF
                // path-sorted; tools/iff_objd_catalog_order.py). IFF-literally the buy-mode list order the
                // player sees is IFF-driven; any engine reordering / invented order FAILS.
                int orderBad = 0; var orderNotes = new List<string>();
                for (int oi = 0; oi < served.Count; oi++)
                {
                    if (oi >= AutotestCatalogCanon.CatalogOrderArray.Length) { orderBad++; continue; }
                    if (served[oi].GUID != AutotestCatalogCanon.CatalogOrderArray[oi])
                    { if (orderBad < 6) orderNotes.Add("order@" + oi + " served=" + served[oi].GUID.ToString("x8") + " iff=" + AutotestCatalogCanon.CatalogOrderArray[oi].ToString("x8")); orderBad++; }
                }
                bool partH = orderBad == 0 && served.Count == AutotestCatalogCanon.CatalogOrderArray.Length;

                Log("AUTOTEST catalog IFF-literal: fixture-verified=" + fixtureOk + "/20 notes=" + string.Join(",", notes)
                    + " served=" + served.Count + " eligible=" + AutotestCatalogCanon.Eligible + " served-match=" + servMatch
                    + " served-missing=" + servMissing + " partB=" + partB + " sort-match=" + sortMatch + " sort-missing=" + sortMissing
                    + " partC=" + partC + " sortNotes=" + string.Join(",", sortNotes.Take(6))
                    + " name-match=" + nameMatch + " name-missing=" + nameMissing + " partD=" + partD + " nameNotes=" + string.Join(",", nameNotes.Take(6))
                    + " bhav-match=" + bhavC + " partE=" + partE + " bhavNotes=" + string.Join(",", bhavNotesE.Take(6))
                    + " def-count=" + defC + " partG=" + partG + " defNotes=" + string.Join(",", defNotes.Take(6))
                    + " order-match=" + (served.Count - orderBad) + " partH=" + partH + " orderNotes=" + string.Join(",", orderNotes)
                    + " srvNotes=" + string.Join(",", srvNotes.Take(4)));
                if (fixtureOk == 20 && partB && partC && partD && partE && partG && partH) { Pass("catalog"); return; }
                Log("AUTOTEST catalog: original buy-catalog surface must stay IFF-literal (Round 46/47/50: 1114 eligible, checksum 3356090364479856, sort canon 1114, name canon 1114, behavior canon 1114)");
                Fail("catalog");
            }
            catch (Exception cte) { Log("AUTOTEST catalog EXC " + cte.GetType().Name + " " + cte.Message); Fail("catalog"); }
        }

        // NAMES runtime check: report each avatar's display-name resolution so the
