        private static void CheckNames()
        {
            try
            {
                if (_avatars.Count == 0) { Log("AUTOTEST names: no avatars on this lot (INFO)"); Pass("names"); return; }
                foreach (var a in _avatars)
                {
                    var nid = a.GetPersonData(FSO.SimAntics.Model.VMPersonDataVariable.NeighborId);
                    var gender = a.GetPersonData(FSO.SimAntics.Model.VMPersonDataVariable.Gender);
                    var mtName = a.MultitileGroup?.Name ?? "";
                    var name = a.Name ?? "";
                    var toStr = a.ToString();
                    Log("AUTOTEST names obj=" + a.ObjectID + " nid=" + nid + " gender=" + gender +
                        " name=" + (name ?? "<null>") + " multiname=" + (mtName ?? "") +
                        " tostring=" + (toStr ?? "<null>") + " pet=" + a.IsPet);
                }
                Pass("names");
            }
            catch (Exception ne) { Log("AUTOTEST names EXC " + ne.GetType().Name + " " + ne.Message); Fail("names"); }
        }

