        // Registered-chunk inventory check (Round 65): the engine IFF parser must expose EXACTLY
        // the IFF-literal chunk inventory - per raw 4-char type instance counts across the
        // last-wins corpus (tools/iff_chunks_census.py).
        private static void CheckChunks()
        {
            try
            {
                var inv = FSO.Content.TS1.TS1ObjectProvider.MtChunkInv;
                var canon = AutotestCatalogCanon.ChunkTypeCensus;
                bool ok = inv != null && canon != null;
                if (ok)
                {
                    ok = inv.Count == canon.Length;
                    for (int i = 0; ok && i < canon.Length; i++)
                    {
                        var tok = canon[i]; var eq = tok.IndexOf("=");
                        var ct = tok.Substring(0, eq); var want = int.Parse(tok.Substring(eq + 1));
                        int got = 0; if (!inv.TryGetValue(ct, out got)) { Log("chunks TOKMISS " + i + " " + tok + " ct=" + ct); ok = false; break; }
                        if (got != want) { Log("chunks TOKDIF " + i + " " + tok + " ct=" + ct + " want=" + want + " got=" + got); ok = false; break; }
                    }
                }
                Log("AUTOTEST chunks IFF-literal inventory types=" + (inv == null ? 0 : inv.Count) + "/" + (canon == null ? 0 : canon.Length) + " eng=" + string.Join(",", (inv == null ? new Dictionary<string, int>() : inv).OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value)) + " canon=" + string.Join(",", (canon ?? new string[0])));
                Log("chunks FAILEDCOUNT " + (FSO.Content.Content.FailedContentFiles == null ? -1 : FSO.Content.Content.FailedContentFiles.Count)); foreach (var fc in (FSO.Content.Content.FailedContentFiles ?? new System.Collections.Generic.List<FSO.Content.TS1.TS1BCFProvider.FailedFileInfo>())) if (fc != null && fc.Filename != null) Log("chunks FAILEDFILE " + fc.Filename + " : " + fc.ErrorType + " " + fc.ErrorMessage);
                if (ok) { Pass("chunks"); return; }
                Log("AUTOTEST chunks: IFF chunk inventory must match exactly (tools/iff_chunks_census.py)");
                Fail("chunks");
            }
            catch (Exception se) { Log("AUTOTEST chunks EXC " + se.GetType().Name + " " + se.Message); Fail("chunks"); }
        }
        // BHAV operand-byte census check (Round 64): the engine IFF parser must expose EXACTLY
        // the IFF-literal operand bytes - 256-bucket histogram over all 8-byte operands
        // (tools/iff_bhav_operands.py) - IFF-literally the operand surface the VM reads.
        private static void CheckOperand()
        {
            try
            {
