                var canon = AutotestCatalogCanon.BhavOperandByteCensus;
                bool ok = h != null && canon != null && h.Length == canon.Length;
                if (ok)
                    for (int i = 0; i < canon.Length; i++) if (h[i] != canon[i]) { ok = false; break; }
                int tot = 0; if (h != null) foreach (var x in h) tot += x;
                Log("AUTOTEST operand IFF-literal bytes=" + tot + " (256-bucket)");
                if (ok) { Pass("operand"); return; }
                Log("AUTOTEST operand: IFF operand bytes must match exactly (tools/iff_bhav_operands.py)");
                Fail("operand");
            }
