        }
        // Per-opcode operand-byte matrix check (Round 66): the engine IFF parser must expose
        // EXACTLY the IFF-literal per-opcode operand-byte matrix - for each opcode, the
        // 256-bucket histogram over the 8 operand bytes (tools/iff_operand_byopcode.py).
        // IFF-literally which operand bytes ride with which opcodes on the VM input surface;
        // strictly stronger than the Round-64 marginal (an intra-opcode operand-byte swap
        // leaves the marginal identical but drifts the per-opcode matrix).
        private static void CheckOperandByOpcode()
        {
            try
            {
                var h = FSO.Content.TS1.TS1ObjectProvider.MtOperandByOpcode;
                var canon = AutotestCatalogCanon.BhavOperandByOpcode;
                bool ok = h != null && canon != null;
                var eng = new Dictionary<int, int>();
                long tot = 0;
                if (ok)
                    foreach (var kv in h)
                    {
                        if (kv.Value == null) { ok = false; continue; }
                        for (int i = 0; i < 256; i++)
                        {
                            if (kv.Value[i] == 0) continue;
                            int key = (kv.Key << 8) | i;
                            int c = kv.Value[i];
                            tot += c;
                            int ev;
                            if (eng.TryGetValue(key, out ev)) { if (ev != c) ok = false; }
                            else eng[key] = c;
                        }
                    }
                if (ok && eng.Count != canon.Count) ok = false;
                if (ok)
                    foreach (var kv in canon)
                    {
                        int ev;
                        if (!eng.TryGetValue(kv.Key, out ev) || ev != kv.Value) { ok = false; break; }
                    }
                Log("AUTOTEST opmx IFF-literal opcodes=" + (h == null ? 0 : h.Count) + " pairs=" + eng.Count + " bytes=" + tot);
                if (ok && tot == 3108024) { Pass("opmx"); return; }
                if (!ok) Log("AUTOTEST opmx: per-opcode operand matrix must match canon (tools/iff_operand_byopcode.py)");
                Fail("opmx");
            }
            catch (Exception se) { Log("AUTOTEST opmx EXC " + se.GetType().Name + " " + se.Message); Fail("opmx"); }
        }
