                int tB = FSO.Content.TS1.TS1ObjectProvider.MtTTAsBlocks, tC = FSO.Content.TS1.TS1ObjectProvider.MtTTAsChunks;
                bool ok = sB == AutotestCatalogCanon.StrSharpBlockCensus && sC == AutotestCatalogCanon.StrSharpChunkCensus
                    && tB == AutotestCatalogCanon.TTAsBlockCensus && tC == AutotestCatalogCanon.TTAsChunkCensus;
