        // ROUND-87 'uicur' IFF-LITERAL pin + rendered-control gate: the ORIGINAL UIGraphics.far .cur
        // cursors (51) must mount in the engine TS1Global mount table 1:1 (raw FAR stored name + byte
        // length + sha256, byte-verbatim; IFF-literalism as loadscreen/uichrome/uitoolbar - Sims1 FAR1
        // does not compress, so DataLength == payload length). Rendered-control gate: the IFF-first
        // live mount must have loaded the ORIGINAL LivePerson.cur member bytes into the runtime
        // CursorManager (LastMountedLivePersonLen == IFF canon). Canon from
        // tools/iff-dump/make_r87_canon.py -> tools/iff-dump/r87/.
        private static void CheckUICursor()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uicur: no TS1Global"); Fail("uicur"); return; }
                var entries = ts1.GetFarEntries(".cur");
                bool ok = true; string info = "";
                using (var sha = System.Security.Cryptography.SHA256.Create())
                {
                    foreach (var canon in AutotestCatalogCanon.R87CursorCanon)
                    {
                        FSO.Content.Framework.Far1ProviderEntry<object> e = null;
                        foreach (var en in entries)
                        {
                            if (en != null && en.FarEntry != null && en.FarEntry.Filename == canon.Name) { e = en; break; }
                        }
                        bool present = e != null;
                        bool len = present && e.FarEntry.DataLength == canon.Bytes;
                        bool raw = false;
                        if (present)
                        {
                            try
                            {
                                var b = e.Archive.GetEntry(e.FarEntry);
                                raw = b != null && b.Length == canon.Bytes && ByteHash256(b, sha) == canon.Sha256;
                            }
                            catch { }
                        }
                        if (!(present && len && raw))
                        {
                            ok = false;
                            info += canon.Name + ":p=" + present + " l=" + len + " r=" + raw + " ";
                        }
                    }
                }
                long livePerson = -1;
                foreach (var canon in AutotestCatalogCanon.R87CursorCanon)
                    if (canon.Name == "Shared\\cursors\\LivePerson.cur") { livePerson = canon.Bytes; break; }
                bool mounted = FSO.Common.Rendering.Framework.CursorManager.LastMountedLivePersonLen == livePerson;
                Log("AUTOTEST uicur IFF-literal cursor mount: ok=" + ok + " livePersonMounted=" + mounted + " mountedLen=" + FSO.Common.Rendering.Framework.CursorManager.LastMountedLivePersonLen + " " + info.Trim());
                if (ok && mounted) { Pass("uicur"); return; }
                Log("AUTOTEST uicur: original .cur cursors must mount 1:1 (name+bytes+sha256) AND the original LivePerson cursor must be IFF-first live (mountedLen=" + FSO.Common.Rendering.Framework.CursorManager.LastMountedLivePersonLen + " expected " + livePerson + ")");
                Fail("uicur");
            }
            catch (Exception se) { Log("AUTOTEST uicur EXC " + se.GetType().Name + " " + se.Message); Fail("uicur"); }
        }

        // ROUND-87 'uiglyph' IFF-LITERAL pin: the ORIGINAL UIGraphics.far .ffn glyph-tables (45) must
        // mount in the engine TS1Global mount table 1:1 (raw FAR stored name + byte length + sha256,
        // byte-verbatim). These are the ORIGINAL glyph-table bytes; IFF-literalism as the other
        // UI members. Canon from tools/iff-dump/make_r87_canon.py -> tools/iff-dump/r87/.
        private static void CheckUIGlyph()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uiglyph: no TS1Global"); Fail("uiglyph"); return; }
                var entries = ts1.GetFarEntries(".ffn");
                bool ok = true; string info = "";
                byte[] ffnCanon = null;   // R96: capture on FIRST read (FAR streams
                                          // do not always survive a second GetEntry)
                byte[] ffnCaption = null; // R97: the caption font, same first-read rule
                byte[] ffnBold = null;    // R98: the bold money font, same first-read rule
                byte[] ffnSmall = null;   // R99: the small toolbar-readout font, same rule
                byte[] ffnDialog = null;  // R100: the dialog font (cheat responses), same rule
                byte[] ffnTitle = null;   // R106: the title font (option captions), same rule
                using (var sha = System.Security.Cryptography.SHA256.Create())
                {
                    foreach (var canon in AutotestCatalogCanon.R87GlyphCanon)
                    {
                        FSO.Content.Framework.Far1ProviderEntry<object> e = null;
                        foreach (var en in entries)
                        {
                            if (en != null && en.FarEntry != null && en.FarEntry.Filename == canon.Name) { e = en; break; }
                        }
                        bool present = e != null;
                        bool len = present && e.FarEntry.DataLength == canon.Bytes;
                        bool raw = false;
                        if (present)
                        {
                            try
                            {
                                var b = e.Archive.GetEntry(e.FarEntry);
                                raw = b != null && b.Length == canon.Bytes && ByteHash256(b, sha) == canon.Sha256;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.DefaultFontPath)
                                    ffnCanon = b;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.CaptionFontPath)
                                    ffnCaption = b;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.BoldFontPath)
                                    ffnBold = b;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.SmallFontPath)
                                    ffnSmall = b;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.DialogFontPath)
                                    ffnDialog = b;
                                if (raw && canon.Name == Simitone.Client.UI.Controls.OriginalGlyphFont.TitleFontPath)
                                    ffnTitle = b;
                            }
                            catch { }
                        }
                        if (!(present && len && raw))
                        {
                            ok = false;
                            info += canon.Name + ":p=" + present + " l=" + len + " r=" + raw + " ";
                        }
                    }
                }
                // R96: the pinned tables must PARSE and RENDER — the FNTF decode
                // (header / 11-byte char records / 4-bit grayscale shape atlas) is
                // verified against the original files, evidence in
                // tools/iff-dump/r96/. Pins on the DEFAULT font
                // (Fonts\variablesans_14.ffn, byte-pinned above): 224 glyphs,
                // atlas exactly 256x224, the exact char records for 'A'/'e' (from
                // the canon bytes), Measure("The Sims") == 88 (the summed
                // advances w+tail0; space=5), and a HEADLESS RENDER of "The Sims"
                // with real ink and >= 8 antialias alpha levels (4-bit depth).
                bool render = true; string rinfo = "";
                try
                {
                    {
                    var gd = FSO.Client.GameFacade.GraphicsDevice;
                    byte[] ffn = ffnCanon;   // byte-verified against the R87 canon above
                    if (ffn == null || gd == null) { render = false; rinfo = "ffn-or-gd-missing "; }
                    else
                    {
                        var font = Simitone.Client.UI.Controls.OriginalGlyphFont.FromFFN(ffn, gd);
                        if (font.NumChars != 224) { render = false; rinfo += "nch=" + font.NumChars + "!=224 "; }
                        if (font.AtlasW != 256 || font.AtlasH != 224) { render = false; rinfo += "atlas=" + font.AtlasW + "x" + font.AtlasH + "!=256x224 "; }
                        if (font.Atlas == null) { render = false; rinfo += "no-atlas "; }
                        Simitone.Client.UI.Controls.OriginalGlyphFont.Glyph gA, gE;
                        font.ByChar.TryGetValue('A', out gA);
                        font.ByChar.TryGetValue('e', out gE);
                        if (gA.W != 12 || gA.H != 15 || gA.U != 54 || gA.V != 37 || gA.T0 != 2 || gA.T2 != 2)
                        { render = false; rinfo += "A-record!=engine "; }
                        if (gE.W != 11 || gE.H != 11 || gE.U != 242 || gE.V != 9 || gE.T2 != 6)
                        { render = false; rinfo += "e-record!=engine "; }
                        int mw = font.Measure("The Sims");
                        if (mw != 88) { render = false; rinfo += "measure=" + mw + "!=88 "; }
                        using (var rt = new RenderTarget2D(gd, 400, 64))
                        {
                            gd.SetRenderTarget(rt);
                            gd.Clear(Color.Transparent);
                            var sb = new SpriteBatch(gd);
                            sb.Begin();
                            font.Draw(sb, "The Sims", new Vector2(4, 4), Color.White);
                            sb.End();
                            gd.SetRenderTarget(null);
                            var px = new Color[400 * 64];
                            rt.GetData(px);
                            int ink = 0;
                            var levels = new System.Collections.Generic.HashSet<byte>();
                            foreach (var c in px) { if (c.A > 0) { ink++; levels.Add(c.A); } }
                            if (ink < 200) { render = false; rinfo += "ink=" + ink + "<200 "; }
                            if (levels.Count < 8) { render = false; rinfo += "aa-levels=" + levels.Count + "<8 "; }
                        }
