        private static string ByteHash256(byte[] b, System.Security.Cryptography.SHA256 sha)
        {
            var h = sha.ComputeHash(b);
            var sb = new System.Text.StringBuilder(h.Length * 2);
            foreach (var x in h) sb.Append(x.ToString("x2"));
            return sb.ToString();
        }

        // ROUND-88 shared IFF-LITERAL pinner: raw FAR stored name + stored DataLength + byte-verbatim
        // sha256 + BMP (offset 18/22) / TGA (offset 12/14) header dims. Sims1 FAR1 does not compress,
        // so DataLength == payload length; every claim verifies to raw IFF canon bytes.
        private static bool PinR88(IEnumerable<FSO.Content.Framework.Far1ProviderEntry<object>> entries,
            AutotestCatalogCanon.R88ResourceCanon canon, System.Security.Cryptography.SHA256 sha, out string info)
        {
            info = "";
            FSO.Content.Framework.Far1ProviderEntry<object> e = null;
            foreach (var en in entries)
            {
                if (en != null && en.FarEntry != null && en.FarEntry.Filename == canon.Name) { e = en; break; }
            }
            bool present = e != null;
            bool len = present && e.FarEntry.DataLength == canon.Bytes;
            bool raw = false; int w = -1; int h = -1;
            if (present)
            {
                try
                {
                    var b = e.Archive.GetEntry(e.FarEntry);
                    raw = b != null && b.Length == canon.Bytes && ByteHash256(b, sha) == canon.Sha256;
                    if (raw && b.Length >= 26 && b[0] == (byte)'B' && b[1] == (byte)'M')
                    {
                        w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                        h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        if (h < 0) h = -h;
                    }
                    else if (raw && b.Length >= 18) // TGA header: width @12, height @14 (LE u16)
                    {
                        w = b[12] | (b[13] << 8);
                        h = b[14] | (b[15] << 8);
                    }
                }
                catch { }
            }
            bool ok = present && len && raw && w == canon.W && h == canon.H;
            if (!ok) info = canon.Name + ":p=" + present + " l=" + len + " r=" + raw + " " + w + "x" + h + " ";
            return ok;
        }

        private static bool PinR88All(IEnumerable<FSO.Content.Framework.Far1ProviderEntry<object>> entries,
            AutotestCatalogCanon.R88ResourceCanon[] canons, out string info)
        {
            bool ok = true; info = "";
            using (var sha = System.Security.Cryptography.SHA256.Create())
            {
                foreach (var canon in canons)
                {
                    string why;
                    if (!PinR88(entries, canon, sha, out why)) { ok = false; info += why; }
                }
            }
            return ok;
        }

        // ROUND-88 'uiboot' IFF-LITERAL pin + live boot-screen gate: the ORIGINAL kSimsLogo boot/logo
        // screen (Res_Other.RT id 9003 -> Other\setup.bmp + 17 language variants, each 800x600x24 with
        // the plumbob + wordmark art baked in) must pin 1:1, AND the boot loading screen must IFF-mount
        // the original screen live with the Simitone logo/diagonal stripes/elastic bar hidden and an
        // engine-drawn original-style progress bar active (the original templates declare NO bar or
        // logo-control asset - the original bar is engine-drawn, and so is this one).
        // ROUND-118 STRENGTHENED: the Simitone loader chrome is DELETED outright and the boot art is
        // mounted DIRECTLY from UIGraphics.far in the LoadingScreen ctor (frame one - no pre-mount
        // window). The direct read's extracted bytes must be sha256-IDENTICAL to the R88 canon entry
        // for Other\setup.bmp, proving the first-frame art is the byte-verbatim original member.
        private static void CheckUIBoot()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uiboot: no TS1Global"); Fail("uiboot"); return; }
                var entries = ts1.GetFarEntries(".bmp");
                string info;
                bool ok = PinR88All(entries, AutotestCatalogCanon.R88BootCanon, out info);
                bool mounted = LoadingScreen.BootLogoMounted;
                bool dims = LoadingScreen.BootLogoDims == "800x600";
                bool chromeHidden = LoadingScreen.SimitoneChromeHidden;
                bool bar = LoadingScreen.OriginalBarActive && LoadingScreen.OriginalBarLastFill >= 0f;
                // R118: the ctor-time direct FAR read must have produced the canon member
                // byte-verbatim (length + sha256 == the R88 pin for Other\setup.bmp).
                var setupCanon = System.Linq.Enumerable.FirstOrDefault(
                    AutotestCatalogCanon.R88BootCanon, c => c.Name == "Other\\setup.bmp");
                bool direct = LoadingScreen.BootDirectMounted
                    && setupCanon != null
                    && LoadingScreen.BootDirectLen == setupCanon.Bytes
                    && LoadingScreen.BootDirectSha == setupCanon.Sha256;
                Log("AUTOTEST uiboot IFF-literal kSimsLogo boot screen: ok=" + ok
                    + " mounted=" + mounted + " dims=" + LoadingScreen.BootLogoDims
                    + " simitoneChromeHidden=" + chromeHidden
                    + " engineBar=" + LoadingScreen.OriginalBarActive + " barFill=" + LoadingScreen.OriginalBarLastFill
                    + " directFrameOne=" + direct + " (len=" + LoadingScreen.BootDirectLen + " sha=" + LoadingScreen.BootDirectSha + ")"
                    + " " + info.Trim());
                if (ok && mounted && dims && chromeHidden && bar && direct) { Pass("uiboot"); return; }
                Log("AUTOTEST uiboot: original kSimsLogo (Other\\setup.bmp, 18 locales) must pin 1:1 AND IFF-mount live as the boot screen FROM FRAME ONE (direct FAR read sha256 == canon; Simitone chrome deleted, engine-drawn bar active)");
                Fail("uiboot");
            }
            catch (Exception se) { Log("AUTOTEST uiboot EXC " + se.GetType().Name + " " + se.Message); Fail("uiboot"); }
        }

