                    && popupProbe.TextBlock != null
                    && popupProbe.TextBlock.Font == Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(10, FSO.Client.GameFacade.GraphicsDevice)
                    && popupProbe.TextBlock.Position.X == 25 && popupProbe.TextBlock.Position.Y == 25
