                bool motiveTwinned = false, motiveTextCanon = false;
                bool motiveGeometry = false, motivePaintLaw = false, motiveDeltaLaw = false;
                bool motivePopupLaw = false;
                bool traitTwinned = false, traitTextCanon = false;
                bool personalityGeometry = false, personalityArt = false;
                bool humanCorpusLaw = false, petCorpusLaw = false;
                bool zodiacLaw = false, stateRestored = false;
