                            && (int)motivePanel.Size.X == Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel.NATIVE_HOST_W
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.GAUGE_W == 100
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.GAUGE_H == 20
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.BAR_X == 20
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.BAR_Y == 12
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.BAR_W == 60
                            && Simitone.Client.UI.Controls.UIOriginalMotiveGauge.BAR_H == 5;
                        motiveTextCanon = motiveTwinned;
                        for (int i = 0; i < 8 && motiveGeometry; i++)
