                        bool tabTipsLaw = modeTipsCanon
                            && Enumerable.Range(0, 7).All(i =>
                                main.PeopleChrome.Tabs[i].Tooltip == R188ModeTips[i]);

                        // cWinPeople::TSPaint maps the current mood directly;
                        // it does not compare queued samples. Pin both native
                        // round-away stages, interior bands, and saturation.
                        var moodTrend = new[] { -100f, -75f, -25f, -0.5f, 0f, 25f, 75f, 100f }
                            .Select(Simitone.Client.UI.Panels.UIOriginalPeopleChrome
                                .NativeMoodTrendForProbe).ToArray();
                        bool moodBandLaw = moodTrend.SequenceEqual(
                            new[] { -5, -4, -1, 0, 0, 2, 5, 5 });

                        // People category plaques are ordinary SetImage(_,4,1)
                        // cTSWinBtns too. Exercise their custom draw selector
                        // through the real UIButton entered/down state so the
                        // hover and pressed cells cannot silently collapse to
                        // the static selected/unselected pair.
                        bool tabStateLaw = false;
                        var tabProbe = new Simitone.Client.UI.Panels.UIOriginalTabButton(
                            "cpanel\\Buttons\\Mood.bmp", 32, 39);
                        try
                        {
                            var dispatch = typeof(FSO.Client.UI.Controls.UIButton).GetMethod("OnMouseEvent",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            tabStateLaw = dispatch != null && tabProbe.CurrentNativeFrameForProbe == 0;
                            dispatch?.Invoke(tabProbe, new object[] {
                                FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, null });
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 2;
                            dispatch?.Invoke(tabProbe, new object[] {
                                FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, null });
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 1;
                            dispatch?.Invoke(tabProbe, new object[] {
                                FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut, null });
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 1;
                            dispatch?.Invoke(tabProbe, new object[] {
                                FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, null });
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 0;
                            tabProbe.SelectedState = 1;
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 1;
                            dispatch?.Invoke(tabProbe, new object[] {
                                FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, null });
                            tabStateLaw = tabStateLaw && tabProbe.CurrentNativeFrameForProbe == 1;
                        }
                        finally { tabProbe.Removed(); }

                        // Route all seven standard panels in native tab order
                        // and pin both the concrete surface and its exact
                        // cWinPeople content-host width.
                        var panelTypes = new[]
                        {
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIRelationshipSubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIHouseSubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIPersonalitySubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel),
                            typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel),
                        };
                        var wideHost = gameScreen.ScreenWidth == 1024 ? 504 : 280;
                        var hostWidths = new[] { 280, wideHost, wideHost, wideHost, 280, wideHost, wideHost };
                        bool panelMatrix = true;
                        bool liveRefresh = true;
                        for (int i = 0; i < nativeOrder.Length; i++)
                        {
                            main.Switcher_OnCategorySelect(nativeOrder[i]);
                            panelMatrix = panelMatrix && main.SubPanel != null
                                && main.SubPanel.GetType() == panelTypes[i]
                                && (int)main.SubPanel.Size.X == hostWidths[i]
                                && (int)main.SubPanel.Size.Y == 100;
                            if (main.SubPanel != null)
                            {
                                main.SubPanel.Invalidated = false;
                                main.SubPanel.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                                liveRefresh = liveRefresh && main.SubPanel.Invalidated;
                            }
                            else liveRefresh = false;
                        }

                        // Exercise the exact direct-tab path that used to leave
                        // ActiveCategory stale at Mood.
                        main.PeopleChrome.SelectTab(5);
                        bool interestRoute = main.Switcher.ActiveCategory == 6
                            && main.PeopleChrome.ActiveTab == 5
                            && main.SubPanel is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel;
                        main.PeopleChrome.SelectTab(6);
                        bool giftRoute = main.Switcher.ActiveCategory == 7
                            && main.PeopleChrome.ActiveTab == 6
                            && main.SubPanel is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel;

                        // Legacy inventory is absent from cWinPeople. A direct
                        // stale id must not become the state restored later.
                        main.Switcher_OnCategorySelect(4);
                        bool inventoryRejected = main.Switcher.ActiveCategory == 7
                            && main.SubPanel == null && main.PeopleChrome.ActiveTab == -1
                            && main.PeopleChrome.Tabs.All(t => t.SelectedState == 0);

                        // The port dictionary deliberately encodes the native
                        // LotZoning words as 0=residential / 1=community. Prove
                        // that the semantic bridge rejects House on a community
                        // lot without corrupting the last accepted category.
                        short activeHouse = gameScreen.vm.GetGlobalValue(10);
                        var zones = FSO.Content.Content.Get().Neighborhood.ZoningDictionary;
                        short savedZone;
                        bool hadZone = zones.TryGetValue(activeHouse, out savedZone);
                        bool houseZoningRejected;
                        try
                        {
                            zones[activeHouse] = 1;
                            main.Switcher_OnCategorySelect(5);
                            houseZoningRejected = main.Switcher.ActiveCategory == 7
                                && main.SubPanel == null && main.PeopleChrome.ActiveTab == -1
                                && main.PeopleChrome.Tabs.All(t => t.SelectedState == 0);
                        }
                        finally
                        {
                            if (hadZone) zones[activeHouse] = savedZone;
                            else zones.Remove(activeHouse);
                        }

                        main.Switcher_OnCategorySelect(3);
                        savedMyUID = gameScreen.vm.MyUID;
                        myUIDCaptured = true;
                        gameScreen.vm.MyUID = 0;
                        main.PeopleChrome.SelectTab(2);
                        bool noPersonRejected = main.Switcher.ActiveCategory == 3
                            && main.SubPanel == null && main.PeopleChrome.ActiveTab == -1
                            && main.PeopleChrome.Tabs.All(t => t.SelectedState == 0);

                        gameScreen.vm.MyUID = savedMyUID;
                        myUIDCaptured = false;
                        main.Switcher_OnCategorySelect(0);
                        desktopPeopleRouting = census && houseZoningLaw && tabTipsLaw
                            && moodBandLaw && tabStateLaw
                            && interestRoute && giftRoute && panelMatrix && liveRefresh
                            && inventoryRejected && houseZoningRejected && noPersonRejected;
                        routingInfo = " order=" + string.Join(",", servedOrder)
                            + " matrix=" + panelMatrix
                            + " liveRefresh=" + liveRefresh
                            + " houseZoningLaw=" + houseZoningLaw
                            + " houseZoningRejected=" + houseZoningRejected
                            + " tabTips=" + tabTipsLaw
                            + " moodBand=" + moodBandLaw
                            + " tabState=" + tabStateLaw
                            + " interest=" + interestRoute + " gift=" + giftRoute
                            + " inventoryRejected=" + inventoryRejected
                            + " noPersonRejected=" + noPersonRejected;
                    }
                }
                catch (Exception re)
                {
                    desktopPeopleRouting = false;
                    routingInfo = " EXC " + re.GetType().Name + " " + re.Message;
                }
                finally
                {
                    if (myUIDCaptured && gameScreen?.vm != null)
                        gameScreen.vm.MyUID = savedMyUID;
                }
                // R199: the same-mode desktop click law. CPState::SetMode
                // @0x210790 opens with `if (this->mode == requested && !force)
                // return` and every cWinViewControl::TSOnCommand mode-button
                // case passes force 0, so clicking the ALREADY-ACTIVE desktop
                // mode button is a no-op — it must never mount the mobile
                // family strip (UISwitchAvatarPanel / pswitch_bg) over the
                // native panel, in the steady state NOR in the port's
                // hidden-at-lot-entry state (the click still reveals the
                // panel there; the original composes it permanently).
                bool desktopSameModeLaw = gameScreen == null || !gameScreen.Desktop;
                string sameModeInfo = "";
                try
                {
                    var fe = gameScreen?.Frontend;
                    var main = fe?.MainPanel;
                    if (fe != null && main != null && gameScreen.Desktop)
                    {
                        var click = typeof(Simitone.Client.UI.Panels.UISimitoneFrontend).GetMethod("LiveButtonClicked",
                            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                        main.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                        var savedActive = main.PanelActive;
                        int SelectorsMounted()
                        {
                            return main.GetChildren()
                                .OfType<Simitone.Client.UI.Panels.UISwitchAvatarPanel>().Count();
                        }
                        // steady state: panel up, click the active mode
                        main.PanelActive = true;
                        bool steadyConsumed = (bool)click.Invoke(fe, new object[]
                            { Simitone.Client.UI.Panels.UIMainPanelMode.LIVE });
                        bool steadyNoop = click != null && !steadyConsumed
                            && main.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.LIVE
                            && !main.ShowingSelect && main.SwitchAvatar == null && SelectorsMounted() == 0;
                        // the reported repro: fresh lot entry leaves the panel inactive
                        main.PanelActive = false;
                        bool revealConsumed = (bool)click.Invoke(fe, new object[]
                            { Simitone.Client.UI.Panels.UIMainPanelMode.LIVE });
                        bool revealNoSelector = !revealConsumed && main.PanelActive
                            && !main.ShowingSelect && main.SwitchAvatar == null && SelectorsMounted() == 0;
                        // cross-mode clicks keep switching (still no selector)
                        bool buyConsumed = (bool)click.Invoke(fe, new object[]
                            { Simitone.Client.UI.Panels.UIMainPanelMode.BUY });
                        bool crossMode = !buyConsumed
                            && main.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.BUY && SelectorsMounted() == 0;
                        bool liveConsumed = (bool)click.Invoke(fe, new object[]
                            { Simitone.Client.UI.Panels.UIMainPanelMode.LIVE });
                        bool backLive = !liveConsumed
                            && main.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.LIVE;
                        desktopSameModeLaw = steadyNoop && revealNoSelector && crossMode && backLive;
                        sameModeInfo = " steady=" + steadyNoop + " reveal=" + revealNoSelector
                            + " cross=" + crossMode + " back=" + backLive;
                        main.PanelActive = savedActive;
                        main.Switcher_OnCategorySelect(0);
                    }
                }
                catch (Exception sme) { desktopSameModeLaw = false; sameModeInfo = " EXC " + sme.GetType().Name; }
                Log("AUTOTEST uilive IFF-literal Live.iff Motives+Personality + subpanel twins: motiveCanon=" + motiveCanon
                    + " (" + l1 + "/" + n1 + ") traitCanon=" + traitCanon + " (" + l2 + "/" + n2 + ")"
                    + " petTables=" + petTablesCanon + " (" + pmLabel + "/" + pmN + "," + ptLabel + "/" + ptN + ")"
                    + " modeTips=" + modeTipsCanon + " (" + modeTipsLabel + "/" + modeTipsN + ")"
                    + " zodiacStrings=" + zodiacStringsCanon + " (" + designLabel + "/" + designN
                    + "," + signLabel + "/" + signN + ")"
                    + " motiveTwinned=" + motiveTwinned + " motiveTextCanon=" + motiveTextCanon
                    + " traitTwinned=" + traitTwinned + " traitTextCanon=" + traitTextCanon
                    + nativeInfo + " stateRestored=" + stateRestored
                    + " desktopAtomic=" + desktopAtomic + atomicInfo
                    + " peopleRouting=" + desktopPeopleRouting + routingInfo
                    + " sameMode=" + desktopSameModeLaw + sameModeInfo);
                if (motiveCanon && traitCanon && motiveTwinned && motiveTextCanon
                    && traitTwinned && traitTextCanon && petTablesCanon && modeTipsCanon && zodiacStringsCanon
                    && motiveGeometry && motivePaintLaw && motiveDeltaLaw && motivePopupLaw
                    && personalityGeometry && personalityArt
                    && humanCorpusLaw && petCorpusLaw && zodiacLaw && stateRestored
                    && desktopAtomic && desktopPeopleRouting && desktopSameModeLaw) { Pass("uilive"); return; }
                Log("AUTOTEST uilive: desktop Needs/Personality must retain native title/font/color/geometry, 60x5 half-up motive paint, mouse-down shared motive popup, PersBkg+HouseSubBars crops, human/pet corpora, adult-only zodiac visibility, and the same-mode click no-op (no mobile family strip) without leaking probe state");
                Fail("uilive");
            }
            catch (Exception se) { Log("AUTOTEST uilive EXC " + se.GetType().Name + " " + se.Message); Fail("uilive"); }
        }

        // ROUND-115 'uijob' IFF-LITERAL pin + live job-subpanel twin gate: the job subpanel's
