        // Your Pet') and the original-glyph money FLOATERS (both UI modes' DisplayChange).
        private const string R115JobLabelsSha = "3908a498315efe29380a685c613a75fe747b1d53a088b3d8133993f46c0a7a28";
        private const string R115JobPopupSha = "2639aca61ecbbc33ff7e7d4af04e5534165c23d439b9fc54e34ae7c49dd9c7a8";
