                            && (int)twin.Size.Y == Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel.SKILL_LABEL_H);
                    bool jobCaptionGeometry = panel.JobTwin != null && panel.JobTwin.Font != null
                        && (int)panel.JobTwin.X == Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel.JOB_CAPTION_X
                        && (int)panel.JobTwin.Y == Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel.JOB_CAPTION_Y
                        && (int)panel.JobTwin.Size.X == Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel.JOB_CAPTION_W
