        // R181: UIElement.Visible is not enforced by UIContainer before a
        // child's virtual Draw call. Every custom painter must therefore stop
        // before emitting pixels. These production probes cover the renderer
        // families that previously leaked stale mood bars, queue/catalog art,
        // inventory cells, relationship portraits and dialog captions through
        // hidden panels. Visible output is also required so a vacuous zero-pixel
        // control cannot satisfy the gate.
        private static void CheckUIVisibilityContract()
        {
            try
            {
                var gradeButton = new Simitone.Client.UI.Controls.UIBigButton(false)
                {
                    Caption = "OK"
                };
                var gradient = new Simitone.Client.UI.Controls.UIVertGrad
                {
                    GSize = new Vector2(40, 20),
                    Position = new Vector2(100, 100)
                };
                var valueBarTexture = Content.Get().CustomUI.Get("motive_bg.png")
                    .Get(GameFacade.GraphicsDevice);
                var valueBar = new Simitone.Client.UI.Controls.UIValueBar(valueBarTexture)
                {
                    Width = 60,
                    Value = 0.5f,
                    Position = new Vector2(100, 100)
                };
                var moodGauge = new Simitone.Client.UI.Controls.UIOriginalLiveGauge
                {
                    MoodValue = 100,
                    DisplayMood = 100
                };
                var queueIcon = new Simitone.Client.UI.Controls.UIInteraction(false);
                var inventoryCell = new Simitone.Client.UI.Panels.LiveSubpanels.UIInventoryDisplay(
                    new FSO.Files.Formats.IFF.Chunks.InventoryItem { GUID = 0, Count = 1 });
                var relationshipCell = new Simitone.Client.UI.Panels.LiveSubpanels.UIRelationshipDisplay(
                    0, 0, _vm);
                var catalogCell = new Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem(
                    new Simitone.Client.UI.Panels.LiveSubpanels.UICatalogElement
                    {
                        Item = new FSO.Content.Interfaces.ObjectCatalogItem
                        {
                            GUID = 0,
                            Price = 1,
                            Name = "visibility probe"
                        }
                    }, null);
                var familiesPanel = new Simitone.Client.UI.Panels.CAS.UIFamiliesCASPanel
                {
                    // The production panel starts fully transitioned out. Put it
                    // at its normal visible endpoint so its custom background
                    // paint is a meaningful positive half of this probe.
                    TitleI = 1f
                };

                var probes = new Dictionary<string, FSO.Client.UI.Framework.UIElement>
                {
                    { "bigButton", gradeButton },
                    { "gradient", gradient },
                    { "valueBar", valueBar },
                    { "moodGauge", moodGauge },
                    { "queueIcon", queueIcon },
                    { "inventoryCell", inventoryCell },
                    { "relationshipCell", relationshipCell },
                    { "catalogCell", catalogCell },
                    { "familiesPanel", familiesPanel },
                };
                var results = new List<string>();
                bool contract = true;
                foreach (var pair in probes)
                {
                    pair.Value.Visible = true;
                    CalculateElementMatrixChain(pair.Value);
                    int visiblePixels = RenderElementAlphaPixels(pair.Value);
                    pair.Value.Visible = false;
                    int hiddenPixels = RenderElementAlphaPixels(pair.Value);
                    pair.Value.Visible = true;
                    bool probe = visiblePixels > 0 && hiddenPixels == 0;
                    contract &= probe;
                    results.Add(pair.Key + "=" + visiblePixels + "/" + hiddenPixels + "/" + probe);
                }

                // UIMainPanel is not safe to construct in isolation: its
                // constructor reparents the lot's shared Query/Pickup panels.
                // Exercise the live production instance instead, preserving
                // every field we temporarily change. Nulling only the public
                // backdrop reference selects Draw's authored fallback paint
                // branch; the image remains mounted as a child. Without the
                // early Visible guard that branch emits pixels before
                // UIContainer.Draw gets a chance to reject the hidden panel.
                var mainPanel = (GameFacade.Screens?.CurrentUIScreen as
                    Simitone.Client.UI.Screens.TS1GameScreen)?.Frontend?.MainPanel;
                if (mainPanel == null)
                {
                    contract = false;
                    results.Add("mainPanel=null/false");
                }
                else
                {
                    var savedVisible = mainPanel.Visible;
                    var savedWidth = mainPanel.CurWidth;
                    var savedBack = mainPanel.OriginalPanelBack;
                    try
                    {
                        mainPanel.OriginalPanelBack = null;
                        mainPanel.CurWidth = Math.Max(263f, savedWidth);
                        mainPanel.Visible = true;
                        CalculateElementMatrixChain(mainPanel);
                        int visiblePixels = RenderElementAlphaPixels(mainPanel);
                        mainPanel.Visible = false;
                        int hiddenPixels = RenderElementAlphaPixels(mainPanel);
                        bool probe = visiblePixels > 0 && hiddenPixels == 0;
                        contract &= probe;
                        results.Add("mainPanel=" + visiblePixels + "/" + hiddenPixels + "/" + probe);
                    }
                    finally
                    {
                        mainPanel.OriginalPanelBack = savedBack;
                        mainPanel.CurWidth = savedWidth;
                        mainPanel.Visible = savedVisible;
                    }
                }

                Log("AUTOTEST uivis custom Draw Visible contract: "
                    + string.Join(" ", results));
                if (contract) { Pass("uivis"); return; }
                Log("AUTOTEST uivis: every production custom painter must emit visible pixels and zero pixels when Visible=false");
                Fail("uivis");
            }
            catch (Exception error)
            {
                Log("AUTOTEST uivis EXC " + error.GetType().Name + " " + error.Message);
                Fail("uivis");
            }
        }

