                    + " sortsMounted=" + sortsMounted + " hostGeometry=" + hostGeometry
                    + " capacityLaw=" + capacityLaw + " filterLaw=" + filterLaw + " markerLaw=" + markerLaw
                    + " relTruthLaw=" + relTruthLaw
                    + " orderLaw=" + orderLaw + " scoreLaw=" + scoreLaw
                    + " cardGeometry=" + cardGeometry + " cardTooltips=" + cardTooltips
                    + " popupLaw=" + popupLaw
                    + " identityLaw=" + identityLaw + " rightClickLaw=" + rightClickLaw + " paging=" + paging);
                if (popupStringsCanon && tipsCanon && art && sortsMounted && hostGeometry
                    && capacityLaw && filterLaw && orderLaw && markerLaw && scoreLaw
                    && cardGeometry && cardTooltips && popupLaw && identityLaw && rightClickLaw && paging) { Pass("uirel"); return; }
                Log("AUTOTEST uirel: native relationship host/filter/card/score/marker/pager/popup/input law must remain exact");
                Fail("uirel");
            }
            catch (Exception se) { Log("AUTOTEST uirel EXC " + se.GetType().Name + " " + se.Message); Fail("uirel"); }
        }

        // ROUND-160 'uinav': the neighborhood NAVBAR on the R143-decoded engine law.
        // (1) STR# 151 'NghbBtnTips' pins chunk sha256 + the English block (14
        //     entries, ids 0..13) verbatim; the destination screens' own tooltip
        //     tables 169/170/173/174 pin entry 0 'Return to Neighborhood View'.
        // (2) Every strip art member pins name+dims in the TS1Global mount
        //     (14 toolbar sheets + 2 banners + Current + CreditBtnEn + the four
        //     Return sheets + the per-screen Import/Bulldoze pair + LargeBack).
        // (3) LIVE: the rewritten UINeighbourhoodSwitcher must mount the law —
        //     home strip = all 14 engine slots at the BSS anchors with engine
        //     cell sizes and disk tooltips + banner + Current indicator + title;
        //     the Downtown strip swaps banner/import/bulldoze art for its own
        //     and adds Return at (200,0); moveIn mode hides MoveIn + destinations.
        //     The STRIPS are constructed headlessly (Panel=null; clicks are never
        //     fired — PopMode no-ops).
        private static void CheckUINav()
        {
            try
            {
                // (1) string canon
                int tId, tN; string tLbl;
                var tips = LoadUITextEnglish(151, out tId, out tN, out tLbl);
                var tipsSha = _r159UITextSha;
                var english151 = new string[]
                {
                    "Select or Create Family", "Evict or Bulldoze", "Quit", "View Web Pages",
                    "Switch To Previous Neighborhood", "Switch To Next Neighborhood", "Import Family",
                    "Switch to Downtown View", "Credits", "Switch to Vacation Island View",
                    "Evict or Rezone", "Switch to Studio Town View", "Switch to Magic Town View", ""
                };
                bool tipsCanon = tLbl == "NghbBtnTips" && tN == 280
                    && tipsSha == "4ff9445991562586f25cdff60072a2712dd4e48c0b51f54d0f5734030f69daf9";
                for (int i = 0; i < 14 && tipsCanon; i++)
                    if (tips.Count <= i || tips[i] != english151[i]) tipsCanon = false;
                bool returnTips = true;
                var destTables = new Dictionary<int, string> { { 169, "169" }, { 170, "170" }, { 173, "173" }, { 174, "174" } };
                foreach (var kv in destTables)
                {
                    int dId, dN; string dLbl;
                    var d = LoadUITextEnglish(kv.Key, out dId, out dN, out dLbl);
                    if (d.Count < 1 || d[0] != "Return to Neighborhood View") returnTips = false;
                }

                // (2) art canon (name + dims in the live TS1Global mount)
                bool art = R159ArtDims("NghUI\\MoveIn.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Bulldoze.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Exit.bmp", 212, 52)
                    && R159ArtDims("NghUI\\InetBtn.bmp", 156, 52)
                    && R159ArtDims("NghUI\\Previous.bmp", 104, 52)
                    && R159ArtDims("NghUI\\Next.bmp", 104, 52)
                    && R159ArtDims("NghUI\\Import.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Downtown.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Vacation.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Rezone.bmp", 212, 52)
                    && R159ArtDims("NghUI\\Studiotown.bmp", 212, 52)
                    && R159ArtDims("NghUI\\MagicLand.bmp", 212, 52)
                    && R159ArtDims("NghUI\\TheSimsLogo.bmp", 70, 52)
                    && R159ArtDims("NghUI\\banner_neighborhood.bmp", 800, 52)
                    && R159ArtDims("NghUI\\banner_downtown.bmp", 800, 52)
                    && R159ArtDims("NghUI\\Current.bmp", 23, 30)
                    && R159ArtDims("Nbhd\\CreditBtnEn.bmp", 232, 58)
                    && R159ArtDims("NghUI\\Return.bmp", 212, 52)
                    && R159ArtDims("Downtown\\Return.bmp", 212, 52)
                    && R159ArtDims("Studiotown\\Return.bmp", 212, 52)
                    && R159ArtDims("Magicland\\Return.bmp", 212, 52)
                    && R159ArtDims("Downtown\\Import.bmp", 212, 52)
                    && R159ArtDims("Downtown\\Bulldoze.bmp", 212, 52)
                    && R159ArtDims("Downtown\\LargeBack.bmp", 1024, 768);

                // R170: exercise the production neighborhood-surround resolver,
                // not merely UIOriginal's independent case-insensitive art probe.
                // The FAR member is lowercase `largeback.bmp`; a case-sensitive
                // TS1Provider.Get left the 1024x768 screen's gray clear color visible.
                var surroundProbe = new Simitone.Client.UI.Screens.UISimitoneBg(false);
                surroundProbe.ResolveNeighborhoodSurround();
                bool surround = surroundProbe.SurroundMounted && surroundProbe.Bg != null
                    && surroundProbe.Bg.Width == 1024 && surroundProbe.Bg.Height == 768;
                // Integration pin: the TS1GameScreen that carried us from the
                // neighborhood into this lot must itself own the resolved
                // surround. A standalone resolver probe cannot catch removal
                // of the constructor call that mounts the production screen.
                bool mountedSurround = _screen?.Bg != null && _screen.Bg.SurroundMounted
                    && _screen.Bg.Bg != null && _screen.Bg.Bg.Width == 1024 && _screen.Bg.Bg.Height == 768;
                if (mountedSurround)
                {
                    var expectedCenter = new Vector2(_screen.ScreenWidth, _screen.ScreenHeight) / 2f;
                    mountedSurround = _screen.GetChildren().Contains(_screen.Bg)
                        && Vector2.Distance(_screen.Bg.Position, expectedCenter) < 0.01f;
                }

                // (3) law integrity — the static table IS the r143 constants
                var law = Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.EngineLaw;
                bool lawOk = law.Length == 14;
                var lawExpect = new Tuple<string, int, int, int, int, int>[]
                {
                    Tuple.Create("NghUI\\MoveIn.bmp", 200, 0, 4, 0, 0),
                    Tuple.Create("NghUI\\Bulldoze.bmp", 300, 0, 4, 1, 1),
                    Tuple.Create("NghUI\\Exit.bmp", 600, 0, 4, 2, 2),
                    Tuple.Create("NghUI\\InetBtn.bmp", 762, 0, 4, 3, 3),
                    Tuple.Create("Nbhd\\CreditBtnEn.bmp", 41, 543, 4, 8, 4),
                    Tuple.Create("NghUI\\Previous.bmp", 106, 0, 4, 4, 5),
                    Tuple.Create("NghUI\\Next.bmp", 141, 0, 4, 5, 6),
                    Tuple.Create("NghUI\\Import.bmp", 250, 0, 4, 6, 7),
                    Tuple.Create("NghUI\\Downtown.bmp", 400, 0, 4, 7, 8),
                    Tuple.Create("NghUI\\TheSimsLogo.bmp", 5, 0, 1, -1, 9),
                    Tuple.Create("NghUI\\Vacation.bmp", 450, 0, 4, 9, 10),
                    Tuple.Create("NghUI\\Rezone.bmp", 350, 0, 4, 10, 11),
                    Tuple.Create("NghUI\\Studiotown.bmp", 500, 0, 4, 11, 12),
                    Tuple.Create("NghUI\\MagicLand.bmp", 550, 0, 4, 12, 13),
                };
                for (int i = 0; i < 14 && lawOk; i++)
                {
                    var e = lawExpect[i]; var s = law[i];
                    if (s.Member != e.Item1 || s.X != e.Item2 || s.Y != e.Item3 || s.Cols != e.Item4 || s.Tip != e.Item5 || s.Idx != e.Item6) lawOk = false;
                }
                var smallOffset = Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.OriginalArtboardOffset(640, 480);
                var largeOffset = Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.OriginalArtboardOffset(1024, 768);
                var smallCenter = Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.OriginalArtboardCenter(640, 480);
                var largeCenter = Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.OriginalArtboardCenter(1024, 768);
                lawOk = lawOk
                    && smallOffset == Vector2.Zero
                    && largeOffset == new Vector2(112, 84)
                    && smallCenter == new Vector2(400, 300)
                    && largeCenter == new Vector2(512, 384);

                // cWinLotBtn::ImageBlt always clips against the 800x600 map rect.
                // Pin full, edge-cropped, scaled, and fully-outside cases without
                // constructing GPU textures.
                var clipFull = Simitone.Client.UI.Panels.UINeighborhoodHouseButton.ClipSourceToArtboard(
                    new Vector2(10, 20), 100, 80, 1f);
                var clipLeft = Simitone.Client.UI.Panels.UINeighborhoodHouseButton.ClipSourceToArtboard(
                    new Vector2(-10, 20), 100, 80, 1f);
                var clipScaled = Simitone.Client.UI.Panels.UINeighborhoodHouseButton.ClipSourceToArtboard(
                    new Vector2(790, 590), 40, 30, 2f);
                var clipOutside = Simitone.Client.UI.Panels.UINeighborhoodHouseButton.ClipSourceToArtboard(
                    new Vector2(801, 100), 40, 30, 1f);
                bool lotClip = clipFull == new Rectangle(0, 0, 100, 80)
                    && clipLeft == new Rectangle(10, 0, 90, 80)
                    && clipScaled == new Rectangle(0, 0, 20, 20)
                    && clipOutside == Rectangle.Empty;

                // (3b) LIVE strips — home (mode 4), downtown (mode 2), moveIn lock.
                Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.StripsMounted = 0;
                Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.ButtonsMounted = 0;
                var nav = new Simitone.Client.UI.Panels.UINeighbourhoodSwitcher(null, 4, false);

                var navOffset = Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.OriginalArtboardOffset(
                    FSO.Client.GlobalSettings.Default.GraphicsWidth,
                    FSO.Client.GlobalSettings.Default.GraphicsHeight);
                bool touchNav = FSO.Common.FSOEnvironment.SoftwareKeyboard;
                var shifted = touchNav ? Vector2.Zero : navOffset;
                bool layoutOk = touchNav
                    ? (int)nav.BannerPositionForProbe.X == 0 && (int)nav.BannerPositionForProbe.Y == 0
                    : (int)nav.X == 0 && (int)nav.Y == 0 && nav.ScaleX == 1 && nav.ScaleY == 1
                        && (int)nav.BannerPositionForProbe.X == (int)shifted.X
                        && (int)nav.BannerPositionForProbe.Y == (int)shifted.Y
                        && (int)nav.CurrentPositionForProbe.X == 124 + (int)shifted.X
                        && (int)nav.CurrentPositionForProbe.Y == 3 + (int)shifted.Y;

                bool homeStrip = nav.LastBannerMember == "NghUI\\banner_neighborhood.bmp"
                    && nav.Buttons.Count == 14
                    && nav.LastMembers.Contains("NghUI\\Current.bmp")
                    && nav.CurrentNumberTextForProbe == "1"
                    && nav.CurrentNumberDrawsLastForProbe
                    && nav.LastTitleText == null   // kMarquee 5016 is a dead slot
                    && layoutOk;
                var numberFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(12, GameFacade.GraphicsDevice);
                if (numberFont == null) homeStrip = false;
                else
                {
                    homeStrip = homeStrip
                        && numberFont.RuntimeTopOffset == 4;
                    var expectedNumber = new Vector2(
                        124 + 23 / 2 - 1 - numberFont.Measure("1") / 2 + shifted.X,
                        3 + 30 / 2 - 1 - numberFont.LineHeight / 2
                            + shifted.Y);
                    homeStrip = homeStrip && nav.CurrentNumberPositionForProbe == expectedNumber;
                }
                // every home button sits at its law anchor with the engine cell size + disk tooltip
                var cell = new Dictionary<string, Tuple<int, int>> {
                    { "NghUI\\MoveIn.bmp", Tuple.Create(53, 52) }, { "NghUI\\Bulldoze.bmp", Tuple.Create(53, 52) },
                    { "NghUI\\Exit.bmp", Tuple.Create(53, 52) }, { "NghUI\\InetBtn.bmp", Tuple.Create(39, 52) },
                    { "Nbhd\\CreditBtnEn.bmp", Tuple.Create(58, 58) }, { "NghUI\\Previous.bmp", Tuple.Create(26, 52) },
                    { "NghUI\\Next.bmp", Tuple.Create(26, 52) }, { "NghUI\\Import.bmp", Tuple.Create(53, 52) },
                    { "NghUI\\Downtown.bmp", Tuple.Create(53, 52) }, { "NghUI\\TheSimsLogo.bmp", Tuple.Create(70, 52) },
                    { "NghUI\\Vacation.bmp", Tuple.Create(53, 52) }, { "NghUI\\Rezone.bmp", Tuple.Create(53, 52) },
                    { "NghUI\\Studiotown.bmp", Tuple.Create(53, 52) }, { "NghUI\\MagicLand.bmp", Tuple.Create(53, 52) }
                };
                int lawHits = 0;
                foreach (var s in law)
                {
                    var b = nav.Buttons.FirstOrDefault(x => x.Member == s.Member);
                    if (b == null) continue;
                    Tuple<int, int> c; cell.TryGetValue(s.Member, out c);
                    if (c == null) continue;
                    bool tipOk = (s.Tip < 0)
                        ? string.IsNullOrEmpty(b.Tooltip)   // the logo: STR# 151[13] is the empty tooltip
                        : b.Tooltip == GameFacade.Strings.GetString("151", s.Tip.ToString());
                    int expectX = s.X + (int)shifted.X;
                    int expectY = s.Y + (int)shifted.Y;
                    if ((int)b.X == expectX && (int)b.Y == expectY && b.CellWidth == c.Item1 && b.CellHeight == c.Item2
                        && b.OriginalMounted && tipOk)
                        lawHits++;
                }
                homeStrip = homeStrip && lawHits == 14;

                nav.SetMode(2, false);
                bool dtStrip = nav.LastBannerMember == "NghUI\\banner_downtown.bmp"
                    && nav.Buttons.Count == 9   // 14 - 5 home-only - current-mode Downtown, + Return
                    && nav.LastMembers.Contains("Downtown\\Return.bmp")
                    && nav.LastMembers.Contains("Downtown\\Import.bmp")
                    && nav.LastMembers.Contains("Downtown\\Bulldoze.bmp")
                    && !nav.LastMembers.Contains("NghUI\\Downtown.bmp")
                    && !nav.LastMembers.Contains("NghUI\\MoveIn.bmp")
                    && !nav.LastMembers.Contains("Nbhd\\CreditBtnEn.bmp")
                    && !nav.LastMembers.Contains("NghUI\\Rezone.bmp")
                    && (int)nav.BannerPositionForProbe.X == (int)shifted.X
                    && (int)nav.BannerPositionForProbe.Y == (int)shifted.Y;
                var ret = nav.Buttons.FirstOrDefault(x => x.Member == "Downtown\\Return.bmp");
                bool returnBtn = ret != null && (int)ret.X == 200 + (int)shifted.X
                    && (int)ret.Y == (int)shifted.Y && ret.CellWidth == 53
                    && ret.Tooltip == GameFacade.Strings.GetString("169", "0");

                nav.SetMode(4, true);
                bool moveInLock = !nav.LastMembers.Contains("NghUI\\MoveIn.bmp")
                    && !nav.LastMembers.Contains("NghUI\\Downtown.bmp")
                    && !nav.LastMembers.Contains("NghUI\\Vacation.bmp")
                    && !nav.LastMembers.Contains("NghUI\\Studiotown.bmp")
                    && !nav.LastMembers.Contains("NghUI\\MagicLand.bmp")
                    && nav.LastMembers.Contains("NghUI\\Exit.bmp");   // Quit stays reachable

                Log("AUTOTEST uinav: tipsCanon=" + tipsCanon + " returnTips=" + returnTips + " art=" + art
                    + " surround=" + surround + "/mounted=" + mountedSurround
                    + " lawOk=" + lawOk + " layoutOk=" + layoutOk + " off=" + (int)shifted.X + "," + (int)shifted.Y
                    + " lotClip=" + lotClip
                    + " homeStrip=" + homeStrip + " dtStrip=" + dtStrip
                    + " returnBtn=" + returnBtn + " moveInLock=" + moveInLock
                    + " strips=" + Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.StripsMounted
                    + " buttons=" + Simitone.Client.UI.Panels.UINeighbourhoodSwitcher.ButtonsMounted);
                if (tipsCanon && returnTips && art && surround && mountedSurround && lawOk && lotClip && homeStrip && dtStrip && returnBtn && moveInLock) { Pass("uinav"); return; }
                Log("AUTOTEST uinav: the navbar and production surround must mount the recovered engine law (centered banner children + clipped lots + no synthetic title + destination Return)");
                Fail("uinav");
            }
            catch (Exception se) { Log("AUTOTEST uinav EXC " + se.GetType().Name + " " + se.Message); Fail("uinav"); }
        }

        // ROUND-161 'uibudget': the BUDGET window on the cWinBudgetDlg decode
        // (evidence r161/). (1) STR# 146 'budgetstrs' pins chunk sha256 + the
        // English block: the two '(x;y)' LAYOUT anchors + the 15 row labels
        // with their interleaved tooltips + the OK/title/header strings.
        // (2) Art pins name+dims: kBudgetBkg 800x600 + kBudgetOK 868x52.
        // (3) LIVE: the dialog constructed through its real ctor on the
        // autotest's live game screen — 15 rows mounted at the anchor law
        // ((40,100) + i*20), uniform max-width columns measured, the '%s'
        // totals formatted from the REAL family data (Account Total ==
        // "§<ActiveFamily.Budget>", Net Worth == Budget+ValueInArch), the OK
        // button 217x52 centered on the board, tooltips == disk.
        private static void CheckUIBudget()
        {
            try
            {
                int tId, tN; string tLbl;
                var strs = LoadUITextEnglish(146, out tId, out tN, out tLbl);
                var sha = _r159UITextSha;
                bool canon = tLbl == "budgetstrs" && tN == 648
                    && sha == "48abf0be8228434ac7818e03ead7e7499249627f89a49e1bc31188a9cf54ab61";
                // [0]/[1] anchors, [2] OK, [3] title, [4]/[5] headers, label+tooltip pairs
                string[] pin = new string[]
                {
                    "(40;25)", "(40;100)", "OK", "Budget", "3 Days", "Today",
                    "Income:", "Money received", "Job", "Combined salary of all household members",
                    "Miscellaneous", "Job bonuses and windfalls", "Expenses:", "Money spent",
                    "Bills Paid:", "Total of bills paid", "Food:", "Amount paid for meals and snacks",
                    "Repair/Cleaning/Gardening:", "Amount paid to service people", "New Purchases",
                    "Any items purchased", "Household Items", "Amount paid for household items",
                    "Architecture/Landscaping", "Amount paid for construction and landscaping",
                    "Miscellaneous Expenses", "Fines paid and other financial losses", "Cash Flow",
                    "The sum of income and expenses", "Household Account Total: %s",
                    "Current funds available", "Days Since Move-In: %s",
                    "Sim days family has lived here", "Household Net Worth: %s",
                    "Value of house and belongings"
                };
                for (int i = 0; i < pin.Length && canon; i++)
                    if (strs.Count <= i || strs[i] != pin[i]) canon = false;

                bool art = R159ArtDims("cpanel\\backgrounds\\budgetback.bmp", 800, 600)
                    && R159ArtDims("cpanel\\buttons\\budgetok.bmp", 868, 52);

                var game = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                bool live = false, totalsOk = false, colsOk = false, okBtnOk = false, tipsOk = false;
                if (game != null)
                {
                    var before = Simitone.Client.UI.Panels.UIOriginalBudgetDialog.DialogsMounted;
                    var dlg = new Simitone.Client.UI.Panels.UIOriginalBudgetDialog(game);
                    // Independently recovered original 20-row table (R238).
                    int[] ys = {25,55,74,97,116,135,154,177,196,215,234,253,270,287,306,325,348,371,390,409};
                    int[] indents = {0,0,0,1,1,0,0,1,1,1,1,2,2,1,0,0,0,0,0,0};
                    live = UI.Panels.UIOriginalBudgetDialog.DialogsMounted == before + 1
                        && dlg.RowLabels.Count == 20 && dlg.BoardH == 528 && dlg.ScaleX == 1 && dlg.ScaleY == 1;
                    for (int i = 0; i < 20 && live; i++)
                    {
                        live &= dlg.RowLabels[i].Y == ys[i];
                        if (i > 0 && i < 17) live &= dlg.RowLabels[i].X == 70 + indents[i]*12;
                    }
                    colsOk = UI.Panels.UIOriginalBudgetDialog.LastLabelW == 188
                        && UI.Panels.UIOriginalBudgetDialog.LastCurW >= 39
                        && UI.Panels.UIOriginalBudgetDialog.LastDay3W >= 43
                        && dlg.RowToday.All(t => t.X == 288)
                        && dlg.Row3Day.All(t => t.X == 357 + UI.Panels.UIOriginalBudgetDialog.LastCurW - 39)
                        && !dlg.RowToday.Any(t => t.Y == 74 || t.Y == 154 || t.Y == 234);
                    var fam = game.ActiveFamily;
                    totalsOk = fam != null
                        && dlg.RowLabels[17].Text == "Household Account Total: §" + fam.Budget
                        && dlg.RowLabels[18].Text.StartsWith("Household Net Worth:")
                        && dlg.RowLabels[19].Text.StartsWith("Days Since Move-In:");
                    var ok = dlg.OkButton;
                    okBtnOk = ok != null && ok.OriginalMounted && ok.CellWidth == 217 && ok.CellHeight == 52
                        && ok.X == (dlg.BoardW - 217)/2 && ok.Y == 452
                        && dlg.OkCaption.Text == GameFacade.Strings.GetString("146", "2")
                        && dlg.OkCaption.Font.LineHeight == 38 && dlg.OkCaption.Y >= ok.Y;
                    tipsOk = dlg.RowLabels[3].Tooltip == GameFacade.Strings.GetString("146", "9")
                        && dlg.RowLabels[7].Tooltip == GameFacade.Strings.GetString("146", "15")
                        && dlg.RowLabels[18].Tooltip == GameFacade.Strings.GetString("146", "35");
                }
                Log("AUTOTEST uibudget: canon=" + canon + " art=" + art + " live=" + live
                    + " colsOk=" + colsOk + " totalsOk=" + totalsOk + " okBtnOk=" + okBtnOk + " tipsOk=" + tipsOk
                    + " labelW=" + Simitone.Client.UI.Panels.UIOriginalBudgetDialog.LastLabelW);
                if (canon && art && live && colsOk && totalsOk && okBtnOk && tipsOk) { Pass("uibudget"); return; }
                Log("AUTOTEST uibudget: the budget window must mount the cWinBudgetDlg law (146 sha-verbatim + anchors + max-width columns + formatted totals + centered OK)");
                Fail("uibudget");
            }
            catch (Exception se) { Log("AUTOTEST uibudget EXC " + se.GetType().Name + " " + se.Message); Fail("uibudget"); }
        }

        // ROUND-194 'uiballoon': the speech-balloon chrome + event icons on
        // the decoded law (evidence r194/). (1) Art pins: SpeechMedium 16x16
        // (9000), SpeechLarge 32x32 (9001), TragedyMask 133x103 (9005).
        // (2) The gzi 9005 dialog path resolves through the resource-id map
        // (the R177 icon law; 40 shipped sites). (3) LIVE: the balloon
        // builder through its real ctor (nine-slice law, content sizing) and
        // the money floater rides the balloon chrome.
        private static void CheckUISpeechBalloon()
        {
            try
            {
                bool art = R159ArtDims("Other\\SpeechMedium.bmp", 16, 16)
                    && R159ArtDims("Other\\SpeechLarge.bmp", 32, 32)
                    && R159ArtDims("Other\\TragedyMask.BMP", 133, 103);

                var res9005 = Simitone.Client.UI.Model.UIOriginal.ResourceNameForIDForProbe(9005);
                bool tragedy = string.Equals(res9005, "Other\\TragedyMask.bmp",
                    StringComparison.OrdinalIgnoreCase);

                var font = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadDefault(GameFacade.GraphicsDevice);
                var b = new Simitone.Client.UI.Controls.UIOriginalSpeechBalloon("+§120", font, false);
                var bL = new Simitone.Client.UI.Controls.UIOriginalSpeechBalloon("test", font, true);
                var w = font.Measure("+§120");
                b.SizeToContent(w, 13);
                bool law = Simitone.Client.UI.Controls.UIOriginalSpeechBalloon.CornerFor[0] == 4
                    && Simitone.Client.UI.Controls.UIOriginalSpeechBalloon.CornerFor[1] == 8
                    && b.ContentWidth == w + 12 && b.ContentHeight == 13 + 8
                    && !b.Large && bL.Large;

                var game = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                bool live = false;
                if (game != null)
                {
                    var ucp = game.Frontend?.DesktopUCP;
                    var before = ucp != null ? ucp.FloatersBallooned : -1;
                    if (ucp != null)
                    {
                        ucp.DisplayChange(120);
                        live = ucp.FloatersBallooned == before + 1
                            && Simitone.Client.UI.Controls.UIOriginalSpeechBalloon.BalloonsMounted >= 1;
                    }
                }

                bool ok = art && tragedy && law && live;
                Log("AUTOTEST uiballoon art=" + art + " tragedy=" + tragedy + " law=" + law + " live=" + live);
                if (ok) Pass("uiballoon"); else Fail("uiballoon");
            }
