        // four sheets are cTSPieMenu items (InsertString into the pie at
        // cDDDSimsView+0x13c), rendered only inside the pie popup — the panel
        // buttons' own law is an animated step (DoSpeedTransitionSound), no
        // flyout. The small zoom/rotate buttons themselves remain.
        private static void CheckUISmallMounts()
        {
            try
            {
                bool art = R159ArtDims("cpanel\\Backgrounds\\TallSubPanel.TGA", 600, 150)
                    && R159ArtDims("cpanel\\ViewMenuZoomIn.bmp", 378, 84)
                    && R159ArtDims("cpanel\\ViewMenuZoomOut.bmp", 378, 84)
                    && R159ArtDims("cpanel\\ViewMenuRotateLeft.bmp", 420, 42)
                    && R159ArtDims("cpanel\\ViewMenuRotateRight.bmp", 420, 42)
                    && R159ArtDims("cpanel\\ViewMenuBackground.bmp", 17, 17);

                var game = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                bool tall = false, labels = false;
                if (game != null)
                {
                    var mp = game.Frontend?.MainPanel;
                    var doubleByteLanguages = new HashSet<byte> { 15, 17, 18, 19, 20 };
                    bool languageLaw = Enumerable.Range(0, 256).All(code =>
                        Simitone.Client.UI.Panels.UIMainPanel.UsesTallSubpanel((byte)code)
                        == doubleByteLanguages.Contains((byte)code));
                    bool requiresTall = doubleByteLanguages.Contains((byte)STR.DefaultLangCode);
                    tall = languageLaw && mp != null && mp.OriginalPanelBack != null
                        && mp.OriginalPanelBack.Size == new Vector2(804, 100)
                        && (requiresTall
                            ? mp.TallSubpanel != null && mp.TallSubpanel.Texture.Width == 600
                                && mp.TallSubpanel.Texture.Height == 150
                                && mp.TallSubpanel.Visible == (mp.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.LIVE)
                            : mp.TallSubpanel == null);


                    // R217: no ViewMenu cells anywhere in the desktop UCP
                    // subtree, and the four small buttons remain mounted.
                    var ucp = game.Frontend?.DesktopUCP;
                    if (ucp != null)
                    {
                        int viewMenuCells = 0;
                        CountViewMenuCells(ucp, ref viewMenuCells);
                        labels = viewMenuCells == 0
                            && ucp.ZoomInButton != null && ucp.ZoomOutButton != null
                            && ucp.RotateCWButton != null && ucp.RotateCCWButton != null;
                    }
                }

                // Desktop fit preserves the native minimum canvas after the
                // window manager clamps a requested high-DPI physical window.
                var fitCases = new[] {
                    (1600,1022,2f,1022f/600), (1600,1200,2f,2f),
                    (1024,768,1f,1f), (640,480,2f,.8f), (1920,1080,1.25f,1.25f)
                };
                bool dpiFit = fitCases.All(c => Math.Abs(SimitoneGame.FitDesktopDpiScale(c.Item3,c.Item1,c.Item2)-c.Item4)<.00001f);
                if (!FSOEnvironment.SoftwareKeyboard)
                    dpiFit &= GlobalSettings.Default.GraphicsWidth >= 800 && GlobalSettings.Default.GraphicsHeight >= 600
                        && game != null && Math.Abs(game.ScaleX-FSOEnvironment.DPIScaleFactor)<.00001f
                        && Math.Abs(game.ScaleY-FSOEnvironment.DPIScaleFactor)<.00001f;
                string configFixture = Path.Combine(Path.GetTempPath(),"simitone-r238-config-"+Guid.NewGuid().ToString("N")+".ini");
                bool configRoundTrip;
                try
                {
                    var settings = new GlobalSettings(configFixture) { GraphicsWidth=800, GraphicsHeight=600, DPIScaleFactor=2 };
                    settings.SetRuntimeViewport(939,600);
                    settings.FXVolume=7;
                    settings.Save();
                    var loaded = new GlobalSettings(configFixture);
                    configRoundTrip = settings.GraphicsWidth==939 && settings.GraphicsHeight==600
                        && loaded.GraphicsWidth==800 && loaded.GraphicsHeight==600 && loaded.DPIScaleFactor==2
                        && loaded.FXVolume==7;
                    settings.GraphicsWidth=1280; settings.GraphicsHeight=720;
                    settings.Save(); loaded=new GlobalSettings(configFixture);
                    configRoundTrip &= settings.GraphicsWidth==1280 && settings.GraphicsHeight==720
                        && loaded.GraphicsWidth==1280 && loaded.GraphicsHeight==720;
                }
                finally { if (File.Exists(configFixture)) File.Delete(configFixture); }
                bool ok = art && tall && labels && dpiFit && configRoundTrip;
                Log("AUTOTEST uismall art=" + art + " tall=" + tall + " flyoutRetired=" + labels
                    +" desktop-fit="+dpiFit+" configured-resolution-roundtrip="+configRoundTrip);
                if (ok) Pass("uismall"); else Fail("uismall");
            }
            catch (Exception ce) { Log("AUTOTEST uismall EXC " + ce.GetType().Name + " " + ce.Message); Fail("uismall"); }
