                    && R159ArtDims("Shared\\Sys\\dropdown.bmp", 16, 16)
                    && R159ArtDims("Shared\\Sys\\ListBack.BMP", 136, 22)
                    && R159ArtDims("Shared\\Sys\\CloseBox.bmp", 48, 11)
                    && R159ArtDims("Shared\\Sys\\MinimizeBox.bmp", 48, 11)
                    && R159ArtDims("cpanel\\Backgrounds\\PopupInfoTiles.bmp", 36, 36);

                // the decoded cell laws, as arithmetic
                bool math = 168 / 6 == 28            // WinChk: 6 cells of 28x28
                    && 260 / 4 == 65                 // WinBtn: 4 states of 65x33
                    && 48 / 4 == 12                  // CloseBox/MinimizeBox: 4 cells of 12x11
                    && 204 / 12 == 17 && 12 * 17 == 204   // WinScrol: 12 cells of 17x20 (6+6 groups)
                    && 36 / 3 == 12;                 // PopupInfoTiles: 3x3 cells of 12

                // the live consumers this round corrected onto the family
                bool wired = Simitone.Client.UI.Panels.UIOriginalPhoneBookDialog.FrameMember == "cpanel\\Backgrounds\\PopupInfoTiles.bmp"
                    && Simitone.Client.UI.Panels.UIOriginalPhoneBookDialog.FrameCell == 12
                    && Simitone.Client.UI.Panels.UIOriginalHelpDialog.FrameMember == "cpanel\\Backgrounds\\PopupInfoTiles.bmp"
                    && Simitone.Client.UI.Panels.UIOriginalHelpDialog.FrameCell == 12;

                bool tiledCoverage = true;
                var device = GameFacade.GraphicsDevice;
                var priorTargets = device.GetRenderTargets(); var priorViewport = device.Viewport;
                try
                {
                    foreach (float density in new[] { 1f, 1.25f, 1.7033333f, 2f })
                    using (var target = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(device,256,256))
                    {
                        var element = new FSO.Client.UI.Framework.UIContainer {
                            Position = new Vector2(7,9), ScaleX = density, ScaleY = density
                        };
                        device.SetRenderTarget(target); device.Clear(Color.Transparent);
