        // HARDCODED in the port; the originals are UIText.iff 128 'PickFamilyStrs' (400
        // entries; [6] 'Delete Family?', [7] the %s delete confirmation, [8] 'SELECT A
        // FAMILY'), 129 'DesignFamilyStrs' (270; [12] 'Enter Last Name:') and 130
        // 'DesignCharStrs' (504; [17]-[21] Neat/Outgoing/Active/Playful/Nice, [24] 'BIO',
        // [26] 'Enter First Name:'). The three panels construct unconditionally at screen
        // setup (texture loads need only a graphics device - available headless).
        private const string R116PickFamilySha = "dce5d06dda063180895de85efc2325021c774a6fe0285ee7a3204c49cdd781f0";
        private const string R116DesignFamilySha = "b0cb46b704d065935fbd101543b76e1ede383c716c759496aabd60cf5177a9d6";
        private const string R116DesignCharSha = "66b9ee45eb561390262c4256c6a2a65802cad834653567e663c014225bc84b93";
        // R117: UIText.iff STR# 138 'VCtlTips' FULL-CHUNK sha256 (chunkSize 28762 = 76-byte
        // header + body; 432 raw entries / 24 English, format -3; FreeSo-regenerated trailer
        // 0xA3 x count - STR.cs:355 quirk. Body-only sha256 = 40a5193b28709c689ea8dded20ac
        // 00cec93da9291de284481d5644b6751937e2).
        private const string R117VCtlTipsSha = "d3dc987e72222692218cec96a497b53541581f7a2bf40cfbceca13fdbc95ee7a";

        private static void CheckUICAS()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uicas: no UIText.iff"); Fail("uicas"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                // r116p1 honest FAIL: lbl/n were shared out-vars, overwritten by each
                // successive walk - canon128/129 compared against CHUNK 130's label/count.
                // Capture per-chunk locals immediately after each walk.
                var raw128 = FindStrChunkByID(d, 128, out id, out n, out lbl, out body);
                var l128 = lbl; // count captured AFTER ParseLang1 (the walk leaves totalEntries -1)
                var s128 = ByteHash256(raw128, sha);
                var e128 = ParseLang1(body, out n);
                var n128 = n;
                var raw129 = FindStrChunkByID(d, 129, out id, out n, out lbl, out body);
                var l129 = lbl;
                var s129 = ByteHash256(raw129, sha);
                var e129 = ParseLang1(body, out n);
                var n129 = n;
                var raw130 = FindStrChunkByID(d, 130, out id, out n, out lbl, out body);
                var l130 = lbl;
                var s130 = ByteHash256(raw130, sha);
                var e130 = ParseLang1(body, out n);
                var n130 = n;
                bool canon128 = raw128 != null && l128 == "PickFamilyStrs" && n128 == 400 && s128 == R116PickFamilySha
                    && e128.Count > 8 && e128[6] == "Delete Family?"
                    && e128[7] == "Are you sure you want to delete the \"%s\" family?"
                    && e128[8] == "SELECT A FAMILY";
                bool canon129 = raw129 != null && l129 == "DesignFamilyStrs" && n129 == 270 && s129 == R116DesignFamilySha
                    && e129.Count > 12 && e129[12] == "Enter Last Name:";
                string[] traits = new string[] { "Neat", "Outgoing", "Active", "Playful", "Nice" };
                bool canon130 = raw130 != null && l130 == "DesignCharStrs" && n130 == 504 && s130 == R116DesignCharSha
                    && e130.Count > 26 && e130[24] == "BIO" && e130[26] == "Enter First Name:";
                for (int i = 0; i < 5; i++) if (e130.Count <= 17 + i || e130[17 + i] != traits[i]) canon130 = false;
                // LIVE: construct the panels through their own ctors + one Update tick each.
                var sim = new Simitone.Client.UI.Panels.CAS.UISimCASPanel();
                sim.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                bool simTwinned = Simitone.Client.UI.Panels.CAS.UISimCASPanel.CASTwinsMounted > 0
                    && sim.FirstNameTwin != null && sim.TraitTwins != null && sim.TraitTwins.Length == 5 && sim.BioTwin != null;
                bool simText = simTwinned
                    && sim.FirstNameTwin.Text == e130[26] && sim.BioTwin.Text == e130[24]
                    && sim.TraitTwins[0].Text == e130[17] && sim.TraitTwins[4].Text == e130[21];
                var fams = new Simitone.Client.UI.Panels.CAS.UIFamiliesCASPanel();
                fams.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                bool famsTwinned = Simitone.Client.UI.Panels.CAS.UIFamiliesCASPanel.FamiliesTitleTwinned > 0
                    && fams.TitleTwin != null && fams.TitleTwin.Text == e128[8];
                var fam = new Simitone.Client.UI.Panels.CAS.UIFamilyCASPanel(new System.Collections.Generic.List<FSO.SimAntics.VMAvatar>());
                fam.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                bool famTwinned = Simitone.Client.UI.Panels.CAS.UIFamilyCASPanel.LastNameTwinned > 0
                    && fam.LastNameTwin != null && fam.LastNameTwin.Text == e129[12];
                // delete-dialog wiring incl. the %s substitution
                bool dialogWired = GameFacade.Strings.GetString("128", "6") == "Delete Family?"
                    && GameFacade.Strings.GetString("128", "7", new string[] { "Goth" }).Contains("\"Goth\"");
                Log("AUTOTEST uicas IFF-literal PickFamily+DesignFamily+DesignChar + CAS twins: c128=" + canon128
                    + " c129=" + canon129 + " c130=" + canon130
                    + " simTwinned=" + simTwinned + " simText=" + simText
                    + " famsTwinned=" + famsTwinned + " famTwinned=" + famTwinned + " dialogWired=" + dialogWired);
                if (canon128 && canon129 && canon130 && simTwinned && simText && famsTwinned && famTwinned && dialogWired) { Pass("uicas"); return; }
                Log("AUTOTEST uicas: UIText.iff STR# 128/129/130 must pin sha256-verbatim AND the CAS panels must mount twins carrying the disk canon, with the delete-dialog %s wired");
                Fail("uicas");
            }
            catch (Exception se) { Log("AUTOTEST uicas EXC " + se.GetType().Name + " " + se.Message); Fail("uicas"); }
        }

        // ROUND-117 'uidtips' IFF-LITERAL pin + CONSTRUCTED-panel gate: the ORIGINAL UCP
        // tooltips (UIText.iff STR# 138 'VCtlTips', 432 entries / 24 English, format -3)
        // pin byte-verbatim (label + English count + sha256 + ALL 24 entries - including
        // the double-space zoom hints 'Zoom In  +'/'Zoom Out  -' and the keyboard suffixes
        // the port paraphrases dropped), AND the UIDesktopUCP constructor must assign all
        // 19 tooltips (15 buttons + 4 speed buttons) from that table: live/buy/build/
        // options 10-13, floors up=1/down=0 (story names, our direction pairing - canon
        // carries no arrows), roof 2, walls 7/8/9, zoom 5/6, rotate CW=4/CCW=3, speeds
        // 16/17/18/15. The EYEDROPPER tooltip stays port-authored (no original - zero
        // corpus hits, disclosed in-source). The FSO.UI-side UILayer.DrawTooltip
        // dispatches through the R119 OriginalVectorFont family; R172 pins its recovered
        // cDefaultTTWindow size/insets/baseline in production renders. Mapped-unused
        // residuals in 138: 'Funds' 14, camera
        // 19, friend count 20, AM/PM 21/22 (clock), 'Help' 23.
        private static void CheckUITooltips()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uidtips: no UIText.iff"); Fail("uidtips"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw138 = FindStrChunkByID(d, 138, out id, out n, out lbl, out body);
                var l138 = lbl; // count captured AFTER ParseLang1 (the walk leaves totalEntries -1)
                var s138 = ByteHash256(raw138, sha);
                var e138 = ParseLang1(body, out n);
                var n138 = n;
                string[] canon138 = new string[] {
                    "First Story", "Second Story", "Roof", "Rotate Left", "Rotate Right",
                    "Zoom In  +", "Zoom Out  -", "Walls Up", "Walls Cutaway", "Walls Down",
                    "Live Mode - F1", "Buy Mode - F2", "Build Mode - F3", "Options Mode - F5",
                    "Funds", "Pause - P", "Normal Speed - 1", "High Speed - 2", "Ultra Speed - 3",
                    "Camera Mode - F4", "Family Friend Count", "AM", "PM", "Help" };
                // n138 = the RAW declared count (432 = 24 English x languages), the same
                // raw-total pin uicas uses (400 for 128); e138 = the lang-1 subset (24).
                bool canon = raw138 != null && l138 == "VCtlTips" && n138 == 432 && s138 == R117VCtlTipsSha
                    && e138.Count == 24;
                for (int i = 0; i < 24; i++) if (e138.Count <= i || e138[i] != canon138[i]) canon = false;
                // CONSTRUCT the real UCP through its own ctor (tooltips are ctor-assigned; the
                // ctor is safe against the live game screen - uijob's money-panel precedent).
                // R142 ENGINE LAW: pause + speeds LIVE ON THE UCP PLATE (kPause 85,135
                // + kSpeed1/2/3 105/120/141,135 — layout-init 0x2b8230); the toolbar
                // cluster is mobile-only. Tooltips [15..18] asserted on the plate buttons.
                // R172 also renders the production tooltip path into a transparent target:
                // cDefaultTTWindow uses VariableSans 07, a textWidth+6 x charHeight+2
                // body, and the x=3/y=1 raster origin. Our raw FFN needs the cache's
                // recovered 2px top-bearing normalization, putting the Plant Tool ink
                // at the exact original in-box baseline.
                var gameScreen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var ucp = new Simitone.Client.UI.Panels.Desktop.UIDesktopUCP(gameScreen);
                bool speedWired =
                    ucp.PauseButton != null && ucp.PauseButton.Tooltip == e138[15]
                    && ucp.SpeedButtons != null && ucp.SpeedButtons.Length == 3
                    && ucp.SpeedButtons[0] != null && ucp.SpeedButtons[0].Tooltip == e138[16]
                    && ucp.SpeedButtons[1] != null && ucp.SpeedButtons[1].Tooltip == e138[17]
                    && ucp.SpeedButtons[2] != null && ucp.SpeedButtons[2].Tooltip == e138[18];
                bool wired =
                    ucp.LiveButton != null && ucp.BuyButton != null && ucp.BuildButton != null
                    && ucp.OptionsButton != null && ucp.FloorUpButton != null && ucp.FloorDownButton != null
                    && ucp.RoofButton != null && ucp.WallsUpButton != null && ucp.WallsCutButton != null
                    && ucp.WallsDownButton != null && ucp.ZoomInButton != null && ucp.ZoomOutButton != null
                    && ucp.RotateCWButton != null && ucp.RotateCCWButton != null
                    && ucp.LiveButton.Tooltip == e138[10] && ucp.BuyButton.Tooltip == e138[11]
                    && ucp.BuildButton.Tooltip == e138[12] && ucp.OptionsButton.Tooltip == e138[13]
                    && ucp.FloorUpButton.Tooltip == e138[1] && ucp.FloorDownButton.Tooltip == e138[0]
                    && ucp.RoofButton.Tooltip == e138[2]
                    && ucp.WallsUpButton.Tooltip == e138[7] && ucp.WallsCutButton.Tooltip == e138[8]
                    && ucp.WallsDownButton.Tooltip == e138[9]
                    && ucp.ZoomInButton.Tooltip == e138[5] && ucp.ZoomOutButton.Tooltip == e138[6]
                    && ucp.RotateCWButton.Tooltip == e138[4] && ucp.RotateCCWButton.Tooltip == e138[3]
                    && speedWired;
                bool renderer = false;
                string rendererInfo = "";
                var layer = GameFacade.Screens;
                var gd = GameFacade.GraphicsDevice;
                if (layer == null || gd == null) rendererInfo = "no-layer-or-device";
                else
                {
                    var previousTargets = gd.GetRenderTargets();
                    var previousViewport = gd.Viewport;
                    var previousTooltip = layer.Tooltip;
                    var previousDpi = FSOEnvironment.DPIScaleFactor;
                    try
                    {
                        // Isolate the decoded 1x tooltip law from a user's saved
                        // UI zoom. This call has no screen-tree side effects.
                        FSOEnvironment.DPIScaleFactor = 1f;
                        layer.Tooltip = "Plant Tool";
                        using (var rt = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(gd, 128, 64))
                        using (var sb = new Microsoft.Xna.Framework.Graphics.SpriteBatch(gd))
                        {
                            gd.SetRenderTarget(rt);
                            gd.Clear(Color.Transparent);
                            sb.Begin();
                            layer.DrawTooltip(sb, new Vector2(32, 32), 1f, new Color(31, 124, 31));
                            sb.End();

                            if (previousTargets.Length == 0) gd.SetRenderTarget(null);
                            else gd.SetRenderTargets(previousTargets);
                            gd.Viewport = previousViewport;

                            var px = new Color[128 * 64];
                            rt.GetData(px);
                            var tooltipPath = System.IO.Path.Combine(
                                FSO.Common.FSOEnvironment.UserDir, "uisurvey-tooltip.png");
                            using (var fs = System.IO.File.Create(tooltipPath))
                                rt.SaveAsPng(fs, rt.Width, rt.Height);
                            int minX = 128, minY = 64, maxX = -1, maxY = -1;
                            int inkMinX = 128, inkMinY = 64, inkMaxX = -1, inkMaxY = -1;
                            for (int y = 0; y < 64; y++)
                            for (int x = 0; x < 128; x++)
                            {
                                var c = px[y * 128 + x];
                                if (c.A != 0)
                                {
                                    minX = Math.Min(minX, x); minY = Math.Min(minY, y);
                                    maxX = Math.Max(maxX, x); maxY = Math.Max(maxY, y);
                                }
                                // Exclude the four green border lines. Every
                                // non-white interior pixel belongs to FFN ink,
                                // including its antialias fringe.
                                if (x > 32 && x < 95 && y > 17 && y < 32
                                    && (c.R != 255 || c.G != 255 || c.B != 255))
                                {
                                    inkMinX = Math.Min(inkMinX, x); inkMinY = Math.Min(inkMinY, y);
                                    inkMaxX = Math.Max(inkMaxX, x); inkMaxY = Math.Max(inkMaxY, y);
                                }
                            }
                            bool singleRenderer = minX == 32 && minY == 17 && maxX == 95 && maxY == 32
                                && inkMinX == 35 && inkMinY == 21 && inkMaxX == 90 && inkMaxY == 28
                                && Simitone.Client.UI.Controls.OriginalVectorFont.LastTablePx == 7;
                            rendererInfo = "box=" + minX + "," + minY + ".." + maxX + "," + maxY
                                + " ink=" + inkMinX + "," + inkMinY + ".." + inkMaxX + "," + inkMaxY
                                + " font=" + Simitone.Client.UI.Controls.OriginalVectorFont.LastTablePx
                                + " artifact=" + tooltipPath;

                            // Pin the same law across two lines. This catches a
                            // line-pitch or second-line baseline regression that
                            // the one-line user's capture cannot expose.
                            layer.Tooltip = "Plant Tool\nPlant Tool";
                            gd.SetRenderTarget(rt);
                            gd.Clear(Color.Transparent);
                            sb.Begin();
                            layer.DrawTooltip(sb, new Vector2(32, 48), 1f, new Color(31, 124, 31));
                            sb.End();

                            if (previousTargets.Length == 0) gd.SetRenderTarget(null);
                            else gd.SetRenderTargets(previousTargets);
                            gd.Viewport = previousViewport;

                            var multiPx = new Color[128 * 64];
                            rt.GetData(multiPx);
                            var multiPath = System.IO.Path.Combine(
                                FSO.Common.FSOEnvironment.UserDir, "uisurvey-tooltip-multiline.png");
                            using (var fs = System.IO.File.Create(multiPath))
                                rt.SaveAsPng(fs, rt.Width, rt.Height);
                            int mMinX = 128, mMinY = 64, mMaxX = -1, mMaxY = -1;
                            int b1MinX = 128, b1MinY = 64, b1MaxX = -1, b1MaxY = -1;
                            int b2MinX = 128, b2MinY = 64, b2MaxX = -1, b2MaxY = -1;
                            bool gapInk = false;
                            for (int y = 0; y < 64; y++)
                            for (int x = 0; x < 128; x++)
                            {
                                var c = multiPx[y * 128 + x];
                                if (c.A != 0)
                                {
                                    mMinX = Math.Min(mMinX, x); mMinY = Math.Min(mMinY, y);
                                    mMaxX = Math.Max(mMaxX, x); mMaxY = Math.Max(mMaxY, y);
                                }
                                if (x > 32 && x < 95 && y > 20 && y < 48
                                    && (c.R != 255 || c.G != 255 || c.B != 255))
                                {
                                    if (y <= 31)
                                    {
                                        b1MinX = Math.Min(b1MinX, x); b1MinY = Math.Min(b1MinY, y);
                                        b1MaxX = Math.Max(b1MaxX, x); b1MaxY = Math.Max(b1MaxY, y);
                                    }
                                    else if (y >= 37)
                                    {
                                        b2MinX = Math.Min(b2MinX, x); b2MinY = Math.Min(b2MinY, y);
                                        b2MaxX = Math.Max(b2MaxX, x); b2MaxY = Math.Max(b2MaxY, y);
                                    }
                                    else gapInk = true;
                                }
                            }
                            bool multilineRenderer = mMinX == 32 && mMinY == 20
                                && mMaxX == 95 && mMaxY == 48
                                && b1MinX == 35 && b1MinY == 24 && b1MaxX == 90 && b1MaxY == 31
                                && b2MinX == 35 && b2MinY == 37 && b2MaxX == 90 && b2MaxY == 44
                                && !gapInk;
                            renderer = singleRenderer && multilineRenderer;
                            rendererInfo += " multiBox=" + mMinX + "," + mMinY + ".." + mMaxX + "," + mMaxY
                                + " bands=" + b1MinX + "," + b1MinY + ".." + b1MaxX + "," + b1MaxY
                                + "/" + b2MinX + "," + b2MinY + ".." + b2MaxX + "," + b2MaxY
                                + " gapInk=" + gapInk + " multiArtifact=" + multiPath;
                        }
                        // High DPI must scale the native 07 face, not replace it
                        // with a different 14pt bitmap font. Render the real path.
                        layer.Tooltip = "Plant Tool";
                        foreach (float dpi in new[] { 2f, 1.7f })
                        using (var rt = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(gd,256,128))
                        using (var sb = new Microsoft.Xna.Framework.Graphics.SpriteBatch(gd))
                        {
                            FSOEnvironment.DPIScaleFactor = dpi;
                            gd.SetRenderTarget(rt); gd.Clear(Color.Transparent);
                            sb.Begin(); layer.DrawTooltip(sb,new Vector2(32,64),1f,Color.Black); sb.End();
                            gd.SetRenderTarget(null); gd.Viewport = previousViewport;
                            var pixels = new Color[256*128]; rt.GetData(pixels);
                            bool scaled = UI.Controls.OriginalVectorFont.LastTablePx == 7
                                && Math.Abs(UI.Controls.OriginalVectorFont.LastGlyphScale-dpi)<.00001f
                                && pixels.Any(c => c.A>0);
                            if (dpi == 2f)
                            {
                                var occupied = Enumerable.Range(0,pixels.Length).Where(i => pixels[i].A>0).ToArray();
                                scaled &= occupied.Min(i => i%256)==32 && occupied.Max(i => i%256)==158
                                    && occupied.Min(i => i/256)==34 && occupied.Max(i => i/256)==64;
                                var scaledTooltipPath = Path.Combine(FSOEnvironment.UserDir,"uisurvey-tooltip-2x.png");
                                using (var fs = File.Create(scaledTooltipPath)) rt.SaveAsPng(fs,rt.Width,rt.Height);
                            }
                            renderer &= scaled;
                            rendererInfo += " native07-at-"+dpi+"x="+scaled;
                        }
                    }
                    catch (Exception re) { rendererInfo = "EXC " + re.GetType().Name + " " + re.Message; }
                    finally
                    {
                        layer.Tooltip = previousTooltip;
                        FSOEnvironment.DPIScaleFactor = previousDpi;
                        try
                        {
                            if (previousTargets.Length == 0) gd.SetRenderTarget(null);
                            else gd.SetRenderTargets(previousTargets);
                            gd.Viewport = previousViewport;
                        }
                        catch { }
                    }
                }
                // R141: the eyedropper BUTTON is gone entirely (port-authored chrome, zero
                // corpus hits; the field no longer exists — compile-level absence); the
                // E-key tool itself stays invisible. No runtime assertion needed.
                Log("AUTOTEST uidtips IFF-literal VCtlTips + UCP tooltips: canon=" + canon
                    + " (" + l138 + "/" + n138 + ") wired=" + wired + " speedWired=" + speedWired
                    + " renderer=" + renderer + "(" + rendererInfo + ")"
                    + " live='" + (ucp.LiveButton != null ? ucp.LiveButton.Tooltip : "null")
                    + "' zoomIn='" + (ucp.ZoomInButton != null ? ucp.ZoomInButton.Tooltip : "null") + "'");
                if (canon && wired && renderer) { Pass("uidtips"); return; }
                Log("AUTOTEST uidtips: STR# 138 must pin sha256-verbatim, every UCP tooltip must read the disk canon, and DrawTooltip must render the decoded 07pt/inset/baseline law");
                Fail("uidtips");
            }
            catch (Exception se) { Log("AUTOTEST uidtips EXC " + se.GetType().Name + " " + se.Message); Fail("uidtips"); }
        }

        // ROUND-119 'uivfont' engine-default-renderer gate: the ORIGINAL variablesans .ffn
        // family (tables 07-20, each table byte-pinned by 'uiglyph') must BE the engine-wide
        // default text renderer — GameFacade.VectorFont is the family root, TextStyle size
        // selection routes to the nearest native table with Scale EXACTLY 1.0 on ladder sizes,
        // MeasureString reproduces the r119 canon widths byte-verbatim (computed from the same
        // R87 canon extraction by tools/iff-dump/r119/make_r119_vfont_canon.py), and the draw
        // path renders headlessly through the same virtual override every engine consumer
        // (labels/buttons/dialogs/lists/text-edits/tooltips/headlines) dispatches to.
        private static void CheckUIVFont()
        {
            try
            {
                var root = FSO.Client.GameFacade.VectorFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                if (root == null)
                {
                    Log("AUTOTEST uivfont: VectorFont is not the original-glyph family (got "
                        + (FSO.Client.GameFacade.VectorFont != null ? FSO.Client.GameFacade.VectorFont.GetType().Name : "null") + ")");
                    Fail("uivfont"); return;
                }
                var info = ""; var ok = true;
                var OV = typeof(Simitone.Client.UI.Controls.OriginalVectorFont);

                // ladder selection: requested px -> expected native table (ties to smaller;
                // 7-20 ladder incl. 16 (R140 restore), _48 excluded by design — 16-glyph wordmark font, no digits)
                int[][] ladder = {
                    new[]{5,7}, new[]{7,7}, new[]{8,8}, new[]{9,9}, new[]{10,10}, new[]{11,11},
                    new[]{12,12}, new[]{13,12}, new[]{14,14}, new[]{15,14}, new[]{16,16},
                    new[]{17,16}, new[]{18,18}, new[]{19,18}, new[]{20,20},
                    new[]{25,20}, new[]{34,20}, new[]{37,20}, new[]{60,20} };
                foreach (var pair in ladder)
                {
                    var picked = root.SelectForSize(pair[0]) as Simitone.Client.UI.Controls.OriginalVectorFont;
                    if (picked == null || picked.TablePx != pair[1])
                    { ok = false; info += " size" + pair[0] + "=>" + (picked != null ? picked.TablePx.ToString() : "null") + "(want" + pair[1] + ");"; }
                }

                // TextStyle routing: the Size setter must re-select VFont (framework hook) and
                // land on Scale == 1.0 exactly, with MeasureString == the native canon width.
                var st = new FSO.Client.UI.Framework.TextStyle { Font = FSO.Client.GameFacade.MainFont, VFont = FSO.Client.GameFacade.VectorFont };
                st.Size = 10;
                var st10 = st.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                bool routed = st10 != null && st10.TablePx == 10;
                bool scale1 = System.Math.Abs(st.Scale - 1f) < 0.0001f;
                int mLot = (int)System.Math.Round(st.MeasureString("Lot 20").X);
                if (!(routed && scale1 && mLot == 43))
                { ok = false; info += " style10 routed=" + routed + " scale=" + st.Scale.ToString("0.####") + " mLot20=" + mLot + "(want43);"; }

                // per-table canon: 'The Sims' width across the whole ladder (r119-vfont-canon.txt)
                int[] wantSims = { 50, 54, 58, 61, 70, 71, 88, 91, 103, 115 }; // R140: _16 restored (91)
                for (int i = 0; i < Simitone.Client.UI.Controls.OriginalVectorFont.LadderPx.Length; i++)
                {
                    var px = Simitone.Client.UI.Controls.OriginalVectorFont.LadderPx[i];
                    var tab = root.SelectForSize(px) as Simitone.Client.UI.Controls.OriginalVectorFont;
                    int w = (int)System.Math.Round(tab.MeasureString("The Sims").X);
                    if (w != wantSims[i])
                    { ok = false; info += " t" + px + " Sims=" + w + "(want" + wantSims[i] + ");"; }
                }

                // engine defaults (UILayer styles) must carry the family
                bool defRouted =
                    FSO.Client.UI.Framework.TextStyle.DefaultLabel.VFont != null && OV.IsAssignableFrom(FSO.Client.UI.Framework.TextStyle.DefaultLabel.VFont.GetType()) &&
                    FSO.Client.UI.Framework.TextStyle.DefaultButton.VFont != null && OV.IsAssignableFrom(FSO.Client.UI.Framework.TextStyle.DefaultButton.VFont.GetType()) &&
                    FSO.Client.UI.Framework.TextStyle.DefaultTitle.VFont != null && OV.IsAssignableFrom(FSO.Client.UI.Framework.TextStyle.DefaultTitle.VFont.GetType());
                if (!defRouted) { ok = false; info += " defaultsNotRouted;"; }

                // headless draws through the engine override: root delegation converts to the
                // _12 reference units (0.72 * 11.5/12 = 0.690), table draws render natively.
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                int draws0 = Simitone.Client.UI.Controls.OriginalVectorFont.DrawCallsRendered;
                int glyphs0 = Simitone.Client.UI.Controls.OriginalVectorFont.GlyphsDrawn;
                root.Draw(gd, "The Sims", new Vector2(2, 2), Color.White, new Vector2(0.72f), null);
                bool rootDelegated = Simitone.Client.UI.Controls.OriginalVectorFont.LastTablePx == 12
                    && System.Math.Abs(Simitone.Client.UI.Controls.OriginalVectorFont.LastGlyphScale - 0.690f) < 0.001f;
                st10.Draw(gd, "Lot 20", new Vector2(2, 2), Color.White, Vector2.One, null);
                bool tableDrew = Simitone.Client.UI.Controls.OriginalVectorFont.LastTablePx == 10
                    && System.Math.Abs(Simitone.Client.UI.Controls.OriginalVectorFont.LastGlyphScale - 1f) < 0.001f;
                bool drew = Simitone.Client.UI.Controls.OriginalVectorFont.DrawCallsRendered >= draws0 + 2
                    && Simitone.Client.UI.Controls.OriginalVectorFont.GlyphsDrawn > glyphs0
                    && Simitone.Client.UI.Controls.OriginalVectorFont.TablesMounted >= 2;
                if (!(rootDelegated && tableDrew && drew))
                { ok = false; info += " rootDelegated=" + rootDelegated + " tableDrew=" + tableDrew + " drew=" + drew + ";"; }

                Log("AUTOTEST uivfont original .ffn default renderer: ok=" + ok
                    + " tablesMounted=" + Simitone.Client.UI.Controls.OriginalVectorFont.TablesMounted
                    + "/10 draws=" + Simitone.Client.UI.Controls.OriginalVectorFont.DrawCallsRendered
                    + " glyphs=" + Simitone.Client.UI.Controls.OriginalVectorFont.GlyphsDrawn
                    + " lastTable=" + Simitone.Client.UI.Controls.OriginalVectorFont.LastTablePx
                    + "@" + Simitone.Client.UI.Controls.OriginalVectorFont.LastGlyphScale.ToString("0.###")
                    + (info.Length > 0 ? " " + info.Trim() : ""));
                if (ok) { Pass("uivfont"); return; }
                Log("AUTOTEST uivfont: VectorFont must be the original variablesans family (07-20), ladder+canon widths+headless draws exact");
                Fail("uivfont");
            }
            catch (Exception se) { Log("AUTOTEST uivfont EXC " + se.GetType().Name + " " + se.Message); Fail("uivfont"); }
        }

        // ROUND-120 'uimpanel' bottom-bar composition gate (user-reported: "bottom-right
        // overlap and repetition"): in DESKTOP mode the MainPanel and the DesktopUCP share
        // one bottom bar — the panel must start at/right of the UCP's right edge (the old
        // fixed X=179 put the open panel 136px INSIDE the UCP, covering the speed pills,
        // time plaque and options button — reproduced headlessly in the R120 uidump with
        // the lot loading in buy mode), BOTH surfaces must sit fully inside the screen
        // (the clipped-UCP class from the live 5:4 window), and the logical screen size
        // must agree with the allocated backbuffer (ScreenWidth x DPI == viewport — the
        // resize-path drift class where settings were left in physical units).
        private static void CheckUIMPanel()
        {
            try
            {
                var screen = FSO.Client.GameFacade.Screens?.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var fe = screen?.Frontend;
                if (fe == null || fe.MainPanel == null || fe.DesktopUCP == null)
                { Log("AUTOTEST uimpanel: no frontend/panels (screen=" + (screen != null ? "TS1GameScreen" : "null") + ")"); Fail("uimpanel"); return; }
                var ucp = fe.DesktopUCP; var mp = fe.MainPanel;
                var info = ""; var ok = true;

                float ucpRight = ucp.X + ucp.Size.X;
                bool noOverlap = mp.X >= ucpRight - 0.5f;
                if (!noOverlap) { ok = false; info += " panelX=" + (int)mp.X + " < ucpRight=" + (int)ucpRight + ";"; }

                bool ucpOnScreen = ucp.X >= -0.5f && ucp.Y >= -0.5f &&
                    ucp.X + ucp.Size.X <= screen.ScreenWidth + 0.5f && ucp.Y + ucp.Size.Y <= screen.ScreenHeight + 0.5f;
                if (!ucpOnScreen) { ok = false; info += " ucpOffScreen x=" + (int)ucp.X + ".." + (int)(ucp.X + ucp.Size.X) + " y=" + (int)ucp.Y + ".." + (int)(ucp.Y + ucp.Size.Y) + ";"; }

                // R142: bar height corrected 128 -> 100 (PanelBack.bmp's own height;
                // the desktop bar now sits flush at the bottom, Y = SH-100 exactly).
                bool mpOnScreen = mp.Y >= -0.5f && mp.Y + 100 <= screen.ScreenHeight + 0.5f && mp.X >= -0.5f;
                if (!mpOnScreen) { ok = false; info += " panelOffScreen y=" + (int)mp.Y + ";"; }

                var vp = FSO.Client.GameFacade.GraphicsDevice.Viewport;
                var dpi = FSO.Common.FSOEnvironment.DPIScaleFactor;
                bool bufferAgrees =
                    System.Math.Abs(screen.ScreenWidth * dpi - vp.Width) <= 1f &&
                    System.Math.Abs(screen.ScreenHeight * dpi - vp.Height) <= 1f;
                if (!bufferAgrees)
                { ok = false; info += " bufferDrift screen=" + screen.ScreenWidth + "x" + screen.ScreenHeight + " dpi=" + dpi + " viewport=" + vp.Width + "x" + vp.Height + ";"; }

                Log("AUTOTEST uimpanel desktop bottom-bar composition: ok=" + ok
                    + " ucp=" + (int)ucp.X + "," + (int)ucp.Y + " " + (int)ucp.Size.X + "x" + (int)ucp.Size.Y
                    + " panel=" + (int)mp.X + "," + (int)mp.Y + " ucpRight=" + (int)ucpRight
                    + " screen=" + screen.ScreenWidth + "x" + screen.ScreenHeight
                    + " viewport=" + vp.Width + "x" + vp.Height + " dpi=" + dpi
                    + (info.Length > 0 ? " " + info.Trim() : ""));
                if (ok) { Pass("uimpanel"); return; }
                Log("AUTOTEST uimpanel: MainPanel must sit right of the DesktopUCP, both fully on-screen, and screen size x DPI must equal the backbuffer viewport");
                Fail("uimpanel");
            }
            catch (Exception se) { Log("AUTOTEST uimpanel EXC " + se.GetType().Name + " " + se.Message); Fail("uimpanel"); }
        }

