        // ROUND-207 'uicheat' (Tier B 'cheat bars'): the engine cheat bar —
        // cSimsApp::FinishSlowInit 0x24d6f4 creates a cTSWinTextEdit2 with
        // SetArea(20,20,220,41), SetCapacity(255), SetTextColor(WHITE),
        // SetColors(RGB(0x40,0x5D,0x5F),...) from the InitSimsColors palette,
        // font table index 10; cTSMainWindowW95::TSOnKeyDown 0x4d5b48 accepts
        // BOTH ctrl+shift+'c' AND ctrl+shift+'b' chords.
        private static void CheckUICheatBar()
        {
            try
            {
                var box = new Simitone.Client.UI.Panels.UICheatTextbox(_vm);
                // The inner textbox carries the real size (UIElement's
                // container Size setter is a no-op); the (20,20) anchor is
                // the MOUNT's law on the real frontend's box.
                var fe = gameScreen_Frontend();
                var mounted = fe == null ? null : fe.CheatTextbox;
                bool geometry = box.TextBoxForProbe != null
                    && (int)box.TextBoxForProbe.Width == 200 && (int)box.TextBoxForProbe.Height == 21
                    && mounted != null && (int)mounted.X == 20 && (int)mounted.Y == 20
                    && mounted.TextBoxForProbe != null
                    && (int)mounted.TextBoxForProbe.Width == 200 && (int)mounted.TextBoxForProbe.Height == 21;
                // sample the mounted background texture center pixel
                bool bgExact = false; string bgInfo = "n/a";
                try
                {
                    var tex = box.BackgroundTextureForProbe;
                    if (tex != null)
                    {
                        var px = new Microsoft.Xna.Framework.Color[tex.Width * tex.Height];
                        tex.GetData(px);
                        var c = px[px.Length / 2];
                        bgInfo = c.R + "," + c.G + "," + c.B;
                        bgExact = c.R == 0x40 && c.G == 0x5D && c.B == 0x5F && c.A == 255;
                    }
                }
                catch (Exception tex) { bgInfo = "EXC " + tex.GetType().Name; }
                bool textLaw = box.TextBoxForProbe != null
                    && box.TextBoxForProbe.MaxChars == 255
                    && box.TextBoxForProbe.MaxLines == 1
                    && box.TextBoxForProbe.TextStyle != null
                    && box.TextBoxForProbe.TextStyle.Color == new Microsoft.Xna.Framework.Color(255, 255, 255);
                // chord law through the real Update with manufactured states
                bool chordC = false, chordB = false, chordX = false;
                try
                {
                    // One FRESH box per chord: the manufactured InputManager's
                    // focus events throw past the flip and can corrupt the
                    // next Update, so each probe box gets exactly one update.
                    Func<Microsoft.Xna.Framework.Input.Keys, Simitone.Client.UI.Panels.UICheatTextbox> makeChordState = key =>
                    {
                        var b = new Simitone.Client.UI.Panels.UICheatTextbox(_vm);
                        var u = new FSO.Common.Rendering.Framework.Model.UpdateState
                        { InputManager = new FSO.Common.Rendering.Framework.IO.InputManager() };
                        u.KeyboardState = new Microsoft.Xna.Framework.Input.KeyboardState(
                            Microsoft.Xna.Framework.Input.Keys.LeftControl, Microsoft.Xna.Framework.Input.Keys.LeftShift, key);
                        u.NewKeys = new System.Collections.Generic.List<Microsoft.Xna.Framework.Input.Keys> { key };
                        try { b.Update(u); } catch { }
                        return b;
                    };
                    // A fresh box's container starts Visible=true (the
                    // frontend hides it post-ctor) — one chord update must
                    // FLIP it off; an inert key leaves it on.
                    chordC = !makeChordState(Microsoft.Xna.Framework.Input.Keys.C).Visible;
                    chordB = !makeChordState(Microsoft.Xna.Framework.Input.Keys.B).Visible;
                    chordX = makeChordState(Microsoft.Xna.Framework.Input.Keys.X).Visible;
                }
                catch (Exception chord) { Log("AUTOTEST uicheat chord EXC " + chord.GetType().Name); }
                Log("AUTOTEST uicheat cheat bar: geometry=" + geometry + " bg=" + bgExact
                    + "(" + bgInfo + ") textLaw=" + textLaw
                    + " chordC=" + chordC + " chordB=" + chordB + " chordXinert=" + chordX
                    + " mounted=" + (mounted == null ? "null" : ((int)mounted.X + "," + (int)mounted.Y + " inner="
                        + (mounted.TextBoxForProbe == null ? "null" : (int)mounted.TextBoxForProbe.Width + "x" + (int)mounted.TextBoxForProbe.Height))));
                if (geometry && bgExact && textLaw && chordC && chordB && chordX) { Pass("uicheat"); return; }
                Log("AUTOTEST uicheat: the cheat bar must carry the engine law (20,20 200x21 opaque 64,93,95 white text 255 chars, ctrl+shift+C and +B toggles)");
                Fail("uicheat");
            }
            catch (Exception e) { Log("AUTOTEST uicheat EXC " + e.GetType().Name + " " + e.Message); Fail("uicheat"); }
        }

        // ROUND-206 'uipanelentry' (the R199 residual closed): the original
        // composes the control panel PERMANENTLY at lot entry — cSimsApp::
        // RebuildControlPanel 0x24de40 (new(0x108) cWinCPanel ctor 0x270d40
        // into app+0x84, SetRect from the app window bounds) +
        // CPState::EnteringHouse 0x211c80 -> SetMode immediately. The panel
        // exists from the FIRST frame; the port's hidden-until-first-click
        // reveal is retired on desktop (ComposeAtLotEntry = Open()'s
        // untweened end state; the BUY global-32 entry keeps its tweened
        // Open, which the original's mode-entry also animates differently).
        private static void CheckUIPanelEntry()
        {
            try
            {
                var gameScreen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                // LIVE law: the real frontend's panel must be composed right
                // now (entry composed it and nothing closed it since).
                var mp = (gameScreen == null || gameScreen.Frontend == null) ? null : gameScreen.Frontend.MainPanel;
                // Exact width is pinned deterministically by the ctor probe
                // below; the live panel's width is re-derived every Update
                // (UIMainPanel "if (PanelActive) CurWidth = ScreenWidth - X"),
                // so a same-frame X shift by an earlier check can lag one
                // frame here — pin the COMPOSED range (closed = 0).
                bool liveComposed = gameScreen != null && gameScreen.Desktop && mp != null
                    && mp.PanelActive && mp.Visible && mp.CurWidth > 700;
                // CONSTRUCTION law: a fresh desktop frontend composes its
                // panel in the ctor (LIVE branch — the corpus loads in live
                // mode with global 32 clear).
                bool freshComposed = false;
                try
                {
                    var fe = new Simitone.Client.UI.Panels.UISimitoneFrontend(gameScreen);
                    freshComposed = fe.MainPanel != null && fe.MainPanel.PanelActive
                        && fe.MainPanel.Visible
                        && (int)fe.MainPanel.CurWidth == (int)(gameScreen.ScreenWidth - fe.MainPanel.X);
                }
                catch (Exception fe) { Log("AUTOTEST uipanelentry fresh-ctor EXC " + fe.GetType().Name + " " + fe.Message); }
                Log("AUTOTEST uipanelentry lot-entry panel compose: liveComposed=" + liveComposed
                    + " (active=" + (mp != null && mp.PanelActive) + " width=" + (mp != null ? (int)mp.CurWidth : -1)
                    + " target=" + (mp != null ? (int)(gameScreen.ScreenWidth - mp.X) : -1) + ")"
                    + " freshComposed=" + freshComposed);
                if (liveComposed && freshComposed) { Pass("uipanelentry"); return; }
                Log("AUTOTEST uipanelentry: the desktop control panel must be composed at lot entry (PanelActive+Visible+full width, untweened), both live and at frontend construction");
                Fail("uipanelentry");
            }
            catch (Exception e) { Log("AUTOTEST uipanelentry EXC " + e.GetType().Name + " " + e.Message); Fail("uipanelentry"); }
        }

        // Independent reimplementation of the R205 friend-count walk (gate-side
        // double implementation of the engine law; the production code lives in
        // UIDesktopUCP.ComputeFamilyFriendCount).
        private static int IndependentFamilyFriendCount(Simitone.Client.UI.Screens.TS1GameScreen game)
        {
            try
            {
                var provider = FSO.Content.Content.Get().Neighborhood;
                var family = game == null ? null : game.ActiveFamily;
                if (provider == null || family == null || family.FamilyGUIDs == null) return 0;
                var members = new System.Collections.Generic.List<short>();
                foreach (var guid in family.FamilyGUIDs)
                {
                    var id = provider.GetNeighborIDForGUID(guid);
                    if (id.HasValue) members.Add(id.Value);
                }
                var friends = new System.Collections.Generic.HashSet<short>();
                foreach (var m in members)
                {
                    var mem = provider.GetNeighborByID(m);
                    if (mem == null || mem.Relationships == null) continue;
                    foreach (var other in provider.Neighbors.Entries)
                    {
                        if (other == null || other.NeighbourID == m || other.Relationships == null) continue;
                        if (members.Contains(other.NeighbourID)) continue;
                        var fwd = new System.Collections.Generic.List<short>();
                        var rev = new System.Collections.Generic.List<short>();
                        if (!mem.Relationships.TryGetValue(other.NeighbourID, out fwd)) continue;
                        if (!other.Relationships.TryGetValue(mem.NeighbourID, out rev)) continue;
                        if (fwd.Count == 0 || rev.Count == 0 || fwd[0] < 50 || rev[0] < 50) continue;
                        friends.Add(other.NeighbourID);
                    }
                }
                return friends.Count;
            }
            catch { return -1; }
        }

        // EXP-01 audit probe (opt-in "llplace"): the surface-object placement law.

        // Session-2 found the Genie Lamp is a SURFACE object: CreateObjectInstance

        // with the Default flag set cannot place it on a bare floor tile (every

        // adjacent-tile attempt came back null/out-of-world). Buy-mode places

        // surface objects with VMPlaceRequestFlags.UserPlacement (=AcceptSlots),

        // which is why they snap into a table/counter slot. This probe pins that law

        // without a serialized game run: create a base dining table beside a live

        // avatar, create the lamp, PlaceInSlot the lamp into the table's slot 0,

        // and assert the lamp is contained, not out-of-world, and still interactable.

        private static void CheckLLPlace()

        {

            try

            {

                var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>()

                    .Where(a => a.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD).ToList();

                if (avatars == null || avatars.Count == 0) { Log("AUTOTEST llplace: no in-world avatar"); Fail("llplace"); return; }

                var av = avatars[0];



                const uint LampGuid = 0xE1B42ACD;          // Genie Lantern (ExpansionPack/ExpansionPack.far)

                const uint TableGuid = 0x921FDA07;         // Dining Table - Moderate (GameData/Objects/Objects.far, base game)



                var lampDef = Content.Get().WorldObjects.Get(LampGuid);

                if (lampDef == null) { Log("AUTOTEST llplace: Genie Lamp OBJD not mounted"); Fail("llplace"); return; }

                var tableDef = Content.Get().WorldObjects.Get(TableGuid);

                if (tableDef == null) { Log("AUTOTEST llplace: dining table OBJD not mounted"); Fail("llplace"); return; }



                // Find a free floor tile adjacent to the avatar (sub-tile units: 16 = one tile).

                var basePos = av.Position;

                VMMultitileGroup tableGrp = null;

                foreach (var cand in new[]

                {

                    new { dx = (short)16, dy = (short)0 }, new { dx = (short)(-16), dy = (short)0 },

                    new { dx = (short)0, dy = (short)16 }, new { dx = (short)0, dy = (short)(-16) },

                    new { dx = (short)16, dy = (short)16 }, new { dx = (short)(-16), dy = (short)(-16) },

                })

                {

                    var pos = basePos; pos.TileX += cand.dx; pos.TileY += cand.dy;

                    try

                    {

                        tableGrp = _vm.Context.CreateObjectInstance(TableGuid, pos, FSO.LotView.Model.Direction.NORTH);

                        if (tableGrp != null && tableGrp.BaseObject?.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD) break;

                        tableGrp = null;

                    }

                    catch (Exception ce) { Log("AUTOTEST llplace table dx=" + cand.dx + " dy=" + cand.dy + " EXC " + ce.GetType().Name + " " + ce.Message); }

                }

                if (tableGrp?.BaseObject == null) { Log("AUTOTEST llplace: dining table placement failed (no free adjacent tile)"); Fail("llplace"); return; }

                var table = tableGrp.BaseObject;

                Log("AUTOTEST llplace tableSpawned obj=" + table.ObjectID + " at " + table.Position + " slots=" + table.TotalSlots());



                // Create the lamp (surface object), then place it into the table's slot 0.

                var lampGrp = _vm.Context.CreateObjectInstance(LampGuid, FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH);

                var lamp = lampGrp?.BaseObject;

                if (lamp == null) { Log("AUTOTEST llplace: lamp create returned null"); Fail("llplace"); return; }



                var placed = table.PlaceInSlot(lamp, 0, true, _vm.Context);

                Log("AUTOTEST llplace placeInSlot=" + placed + " lampContained=" + (lamp.Container == table)

                    + " lampSlot=" + lamp.ContainerSlot + " lampPos=" + lamp.Position

                    + " lampOOW=" + (lamp.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD));



                // Interactable after placement: the lamp pie menu must be enumerable from the avatar.

                var menu = lamp.GetPieMenu(_vm, av, true, true);

                var names = menu == null ? "<null>" : string.Join(" | ", menu.Select(m => m.Name));

                Log("AUTOTEST llplace menu=" + names);



                var ok = placed && lamp.Container == table

                    && lamp.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD

                    && menu != null && menu.Count > 0;

                // cleanup both probe artifacts

                try { lamp.Delete(false, _vm.Context); } catch { }

                try { tableGrp.Delete(_vm.Context); } catch { }

                if (ok) Pass("llplace"); else Fail("llplace");

            }

            catch (Exception le)

            {

                Log("AUTOTEST llplace EXC " + le.GetType().Name + " " + le.Message + " AT " + (le.StackTrace ?? "").Replace("\n", " | "));

                Fail("llplace");

            }

        }

