        // CC-03 audit probe (opt-in "cc03anim"): animation resolution and

        // playback safety. (1) the TS1 provider resolves a known base animation

        // and rejects a missing name; (2) an avatar carrying a state whose

        // animation no longer resolves (custom anim removed after save) ticks

        // without crashing — the state is marked ended instead.

        private static void CheckCC03Anim()

        {

            try

            {

                var provider = Content.Get().AvatarAnimations;

                var known = provider?.Get("a2o-rarm-carry-loop.anim");

                var missing = provider?.Get("cc03_does_not_exist.anim");

                Log("AUTOTEST cc03anim providerKnown=" + (known != null) + " providerMissing=" + (missing == null));



                var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>().ToList();

                if (avatars == null || avatars.Count == 0) { Log("AUTOTEST cc03anim: no avatar on lot"); Fail("cc03anim"); return; }



                var marshal = new FSO.SimAntics.Marshals.VMAnimationStateMarshal { Anim = "cc03_missing_anim", EventQueue = new short[0] };

                var badState = new FSO.SimAntics.Model.VMAnimationState(marshal);

                var badAnimNull = badState.Anim == null;

                var ticked = false;

                var survived = true;

                // drive the real avatar tick across on-lot avatars until one

                // reaches the animation section (a paused thread skips it)

                foreach (var cand in avatars)

                {

                    cand.Animations.Add(badState);

                    var carryBefore = cand.CarryAnimationState;

                    var carryMarshal2 = new FSO.SimAntics.Marshals.VMAnimationStateMarshal { Anim = "cc03_missing_carry", EventQueue = new short[0] };

                    cand.CarryAnimationState = new FSO.SimAntics.Model.VMAnimationState(carryMarshal2);

                    try { cand.Tick(); ticked = true; }

                    catch (Exception ex2) { survived = false; Log("AUTOTEST cc03anim tickEXC on av" + cand.ObjectID + ": " + ex2.GetType().Name); }

                    if (badState.EndReached)

                    {

                        if (carryBefore != null) cand.CarryAnimationState = carryBefore;

                        else cand.CarryAnimationState = null;

                        break;

                    }

                    cand.Animations.Remove(badState);

                    cand.CarryAnimationState = carryBefore;

                }

                var badEnded = badState.EndReached;

                Log("AUTOTEST cc03anim tickSurvived=" + survived + " badAnimNull=" + badAnimNull

                    + " badEnded=" + badEnded);



                var ok = known != null && missing == null && survived && badAnimNull && badEnded && ticked;

                if (ok) Pass("cc03anim"); else Fail("cc03anim");

            }

            catch (Exception ae)

            {

                Log("AUTOTEST cc03anim EXC " + ae.GetType().Name + " " + ae.Message);

                Fail("cc03anim");

            }

        }



