        private static void CheckHP()
        {
            try
            {
                switch (_hpState)
                {
                    case 0: HPInit(); break;
                    case 1: HPDrive(); break;
                    case 2: return;
                    case 4: HPRepeat(); break;
                }
            }
            catch (Exception le)
            {
                Log("AUTOTEST hpparty EXC state=" + _hpState + " leg=" + _hpLeg + " " + le.GetType().Name + " " + le.Message);
                Fail("hpparty");
                _hpState = 2;
            }
        }

