                            else if (_hpFrame % 900 == (_hdDepartFrame % 900))
                            {
                                // increment 16 — the LOT-TRANSITION dump: the
                                // transit car's 'Home Main' progression (does the
                                // vehicle system advance or park forever?), the
                                // entity census, and the host's persistent absence
                                var car = _vm.Entities.FirstOrDefault(e =>
                                    (e?.Object?.Resource?.MainIff?.Filename ?? "").Equals("carpublictransit.iff", StringComparison.OrdinalIgnoreCase));
                                var carStk = car?.Thread?.Stack;
                                var cst = carStk == null ? "-" : string.Join(",", carStk.Select(f => (f.Routine?.Chunk?.ChunkID ?? 0) + "@" + ((int)f.InstructionPointer)));
                                Log("AUTOTEST hddowntown RETURN-obs f=" + (_hpFrame - _hdDepartFrame)
                                    + " hostOow=" + (_hpHost?.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                                    + " hostDead=" + (_hpHost?.Dead ?? true)
                                    + " lotAvatars=" + _vm.Context.ObjectQueries.Avatars.Count(a => a.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                                    + " entities=" + _vm.Entities.Count
                                    + " car=" + (car == null ? "gone" : ("obj" + car.ObjectID + " act='" + (car.Thread?.ActiveAction?.Name ?? "-") + "' stk=[" + cst + "]")));
                            }
                        }
                        if ((_hdSawCab || _hdRode) && (_hdRode ? (_hdHostReturned || (_hdDepartFrame >= 0 && _hpFrame > _hdDepartFrame + 7200)) : true))
                        {
                            Log("AUTOTEST hddowntown PASS-RIDE-THROUGH (cabDlg=" + _hdSawDlg + " cabEntity=" + _hdSawCab
                                + " queue=" + _hdSawQueue + " departed=" + _hdRode + " returned=" + _hdHostReturned + ") at " + Sim3Clock());
                            Log("AUTOTEST hpparty verdict legs P/G/S/E/D1/D2/C1/C2 + CAST=" + (castOkHd ? "ok" : "pinned") + " + HD=ok(ride-through) + COMPANION=" + (_hdSawComp ? "ok" : (_hdCompPushed ? "pinned" : "n/a")) + " + DATE=" + (_hdJoinPushed ? "pushed" : "n/a") + " + GUEST-RUN=" + (_hdGuestRan ? "ok" : "pinned") + " + GUEST-DEPART=" + (_hdGuestDeparted ? "ok" : "pinned") + " + RETURN=" + (_hdHostReturned ? "ok" : (_hdDepartFrame >= 0 ? "pinned" : "n/a")));
                            ArmRepeat();
                        }
                        else if (_hdSawDlg && _hdDlgFrame >= 0 && _hdDepartFrame < 0 && _hpFrame > _hdDlgFrame + 10800)
                        { // increment 6: window 7200->10800 (run-7: the host held the cab queue 2h without entity; the create is OOW — the guid-exact scan now catches it)
                            Log("AUTOTEST hddowntown PASS-QUEUE (cab dialog fired; host queue=" + _hdSawQueue
                                + " but no cab entity/departure in the phase-2 window — the post-queue chain (4098 entity / travel transition) is the next decode; trail above)");
                            Log("AUTOTEST hpparty verdict legs P/G/S/E/D1/D2/C1/C2 + CAST=" + (castOkHd ? "ok" : "pinned")
                                + " + HD=ok(" + (_hdSawQueue ? "queue" : "dialog") + ",ride-through-pinned) + COMPANION=" + (_hdSawComp ? "ok" : (_hdCompPushed ? "pinned" : "n/a")) + " + DATE=" + (_hdJoinPushed ? "pushed" : "n/a") + " + GUEST-RUN=" + (_hdGuestRan ? "ok" : "pinned") + " + GUEST-DEPART=" + (_hdGuestDeparted ? "ok" : "pinned"));
                            ArmRepeat();
                        }
                        else if (!_hdSawDlg && _hpFrame > 14400)
                        {
                            Log("AUTOTEST hddowntown PINNED (no cab dialog/entity in the window — the picker-response path is the named next decode; observation trail above)");
                            Log("AUTOTEST hpparty verdict legs P/G/S/E/D1/D2/C1/C2 + CAST=" + (castOkHd ? "ok" : "pinned") + " + HD=pinned");
                            ArmRepeat();
                        }
                    }
                    break;
                case 3: // E: END — the run4 law: the party ends naturally
                    // (attr0 2 -> 0, guests leave). PASS on the observed reset;
                    // honest FAIL if the party never ends within a generous window.
                {
                    var c3 = _vm.Entities.FirstOrDefault(e => e.Object?.OBJ != null && e.Object.OBJ.GUID == HP_PARTY_CTRL);
                    int ea0 = c3?.GetAttribute(0) ?? -99;
                    if (_hpFrame == 30) Log("AUTOTEST hpparty E: end window (attr0=" + ea0 + " guests=" + guestsNow + ")");
                    if (ea0 == 0 && _hpFrame > 30)
                    {
                        Log("AUTOTEST hpparty E PASS (party ended: attr0=" + ea0 + " guests=" + guestsNow + ") at " + Sim3Clock());
                        HPNext(); // continue into the D1/D2 dance tranche
                    }
                    else if (_hpFrame > 36000)
                    {
                        Log("AUTOTEST hpparty E FAIL (attr0=" + ea0 + " never reset)");
                        Fail("hpparty"); _hpState = 2;
                    }
                    break;
                }
            }
        }

        private static VMEntity HPPlaceBeside(uint guid)
        {
            var basePos = _hpHost.Position;
            for (int ring = 1; ring <= 3; ring++)
            {
                var candidates = new[]
                {
                    new { dx = (short)ring, dy = (short)0 }, new { dx = (short)-ring, dy = (short)0 },
                    new { dx = (short)0, dy = (short)ring }, new { dx = (short)0, dy = (short)-ring },
                    new { dx = (short)ring, dy = (short)ring }, new { dx = (short)-ring, dy = (short)-ring },
                };
                foreach (var cand in candidates)
                {
                    var pos = basePos;
                    pos.TileX += cand.dx;   // TILE units (the setter does x = v<<4)
                    pos.TileY += cand.dy;
                    try
                    {
                        var grp = _vm.Context.CreateObjectInstance(guid, pos, FSO.LotView.Model.Direction.NORTH);
                        if (grp?.BaseObject != null && grp.BaseObject.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                            return grp.BaseObject;
                    }
                    catch { }
                }
            }
            return null;
        }

        private static FSO.LotView.Model.LotTilePos HPBuffetBuyPos(int idx)
        {
            // host-derived buy candidates: yard-class offsets in TILES from the
            // host (subtile = host + offset*16); far enough for the 3-tile
            // BuffetTable footprint, multiple directions to escape interior
            // positions
            var offs = new[] {
                new { dx = 4, dy = 0 }, new { dx = 0, dy = 4 }, new { dx = 4, dy = 4 },
                new { dx = -4, dy = 0 }, new { dx = 0, dy = -4 }, new { dx = 6, dy = 0 } };
            var o = offs[idx % offs.Length];
            var hp = _hpHost.Position;
            return new FSO.LotView.Model.LotTilePos((short)(hp.x + o.dx * 16), (short)(hp.y + o.dy * 16), hp.Level);
        }

        private static void HPNext()
        {
            _hpLeg++;
            _hpFrame = 0;
        }

        private static void CheckLLInteract()
        {
            try
            {
                switch (_ll2State)
                {
                    case 0: LL2Init(); break;
                    case 1: LL2Drive(); break;
                    case 2: return; // verdict recorded
                }
            }
            catch (Exception le)
            {
                Log("AUTOTEST llinteract EXC state=" + _ll2State + " leg=" + _ll2Leg + " frame=" + _ll2Frame + " "
                    + le.GetType().Name + " " + le.Message + " AT " + (le.StackTrace ?? "").Replace("\n", " | "));
                Fail("llinteract");
                _ll2State = 2;
            }
        }

        private static void LL2Init()
        {
            // v4 prescription step 1: never place or push inside the boot-dialog
            // latch window, and let the lot settle first — v3 pushed Clean 1 ms
            // after lampSpawned and the rub tree parked inside the latch.
            if (_vm?.GlobalBlockingDialog != null) return;
            if (++_ll2Settle < 90) return;

            var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>()
                .Where(a => a.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD).ToList();
            if (avatars == null || avatars.Count == 0) { Log("AUTOTEST llinteract: no in-world avatar"); Fail("llinteract"); _ll2State = 2; return; }
            // prefer an adult: the 9:00 school flow (run-4 pin) pulls child avatars
            // out of the legs with an unstoppable 'At School' queue entry.
            _ll2Av = avatars.FirstOrDefault(a => a.GetPersonData(VMPersonDataVariable.PersonsAge) >= 18) ?? avatars[0];
            Log("AUTOTEST llinteract avatar obj=" + _ll2Av.ObjectID + " age=" + _ll2Av.GetPersonData(VMPersonDataVariable.PersonsAge));

            foreach (var kv in FSO.Content.TS1.TS1ObjectProvider.ObjdByGUID)
            {
                var label = (kv.Value.ChunkLabel ?? "").ToLowerInvariant();
                if (label == "genie lamp") { _ll2LampGuid = kv.Key; break; }
            }
            if (_ll2LampGuid == 0) { Log("AUTOTEST llinteract: Genie Lamp OBJD not found in catalog"); Fail("llinteract"); _ll2State = 2; return; }

            _ll2Fam = _vm.TS1State?.CurrentFamily;
            var scr = _screen;
            _ll2Save = () => { scr.Save(); return true; };
            _ll2Reload = () => scr.PlayHouse(5, null);

            // place the lamp into a dining table's slot 0 beside the avatar (v2 law:
            // the lamp is a SURFACE object — bare-floor placement is rejected; the
            // LotTilePos sub-tile unit is 16).
            VMEntity table = null;
            for (int ring = 1; ring <= 2 && table == null; ring++)
            {
                var candidates = new[]
                {
                    new { dx = (short)(16*ring), dy = (short)0 },
                    new { dx = (short)(-16*ring), dy = (short)0 },
                    new { dx = (short)0, dy = (short)(16*ring) },
                    new { dx = (short)0, dy = (short)(-16*ring) },
                    new { dx = (short)(16*ring), dy = (short)(16*ring) },
                    new { dx = (short)(-16*ring), dy = (short)(-16*ring) },
                };
                foreach (var cand in candidates)
                {
                    var pos = _ll2Av.Position;
                    pos.TileX += cand.dx;
                    pos.TileY += cand.dy;
                    try
                    {
                        var grp = _vm.Context.CreateObjectInstance(0x921FDA07, pos, FSO.LotView.Model.Direction.NORTH);
                        if (grp != null && grp.BaseObject?.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD) { table = grp.BaseObject; break; }
                    }
                    catch (Exception ce) { Log("AUTOTEST llinteract table ring=" + ring + " EXC " + ce.GetType().Name + " " + ce.Message); }
                }
            }
            if (table == null) { Log("AUTOTEST llinteract: table placement failed"); Fail("llinteract"); _ll2State = 2; return; }
            var lampGrp = _vm.Context.CreateObjectInstance(_ll2LampGuid, FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH);
            _ll2Lamp = lampGrp?.BaseObject;
            if (_ll2Lamp == null) { Log("AUTOTEST llinteract: lamp create returned null"); Fail("llinteract"); _ll2State = 2; return; }
            var placedOk = table.PlaceInSlot(_ll2Lamp, 0, true, _vm.Context);
            if (!placedOk || _ll2Lamp.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
            { Log("AUTOTEST llinteract: lamp slot placement failed placed=" + placedOk); Fail("llinteract"); _ll2State = 2; return; }
            Log("AUTOTEST llinteract lampSpawned guid=0x" + _ll2LampGuid.ToString("X") + " obj=" + _ll2Lamp.ObjectID + " at " + _ll2Lamp.Position);

            // resolve the wish-chain rows from the lamp's own IFF (TTAs 129 labels
            // line up with TTAB 129 row indices). The Force rows are the
            // deterministic dialog paths: 'Force Good/Money Love' (row 10) sets
            // attr[2]=4 + attr[4]=0, 'Force Bad/Earth Air' (row 2) sets attr[2]=3 +
            // attr[4]=1. Plain Clean is a 60% bad coin ('Select Good/Bad' #4147).
            var lampIff = _ll2Lamp.Object?.Resource?.Iff;
            var ttas = lampIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAs>(129);
            var ttab = lampIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAB>(129);
            if (ttas == null || ttab == null) { Log("AUTOTEST llinteract: lamp TTAs/TTAB 129 not found"); Fail("llinteract"); _ll2State = 2; return; }
            for (int i = 0; i < ttas.Length && i < ttab.Interactions.Length; i++)
            {
                var lbl = (ttas.GetString(i) ?? "").Trim();
                if (_ll2RowForceGood < 0 && lbl == "Force Good/Money Love") _ll2RowForceGood = i;
                if (_ll2RowBadAir < 0 && lbl == "Force Bad/Earth Air") _ll2RowBadAir = i;
            }
            if (_ll2RowForceGood < 0 || _ll2RowBadAir < 0)
            { Log("AUTOTEST llinteract: wish rows not resolved (forceGood=" + _ll2RowForceGood + " badAir=" + _ll2RowBadAir + ")"); Fail("llinteract"); _ll2State = 2; return; }

            _ll2SawGenie = false;
            for (int i = 0; i < _ll2LegOk.Length; i++) _ll2LegOk[i] = false;
            // diagnostic: the wish-code map — 'offer option' writes attr[3] =
            // Chosen[attr[2]-pair index]; the dispatcher switches on attr[3].
            var chosen = lampIff.Get<FSO.Files.Formats.IFF.Chunks.BCON>(4100);
            if (chosen != null)
                Log("AUTOTEST llinteract Chosen BCON 4100 = [" + string.Join(",", chosen.Constants) + "]");
            var opts = lampIff.Get<FSO.Files.Formats.IFF.Chunks.BCON>(4099);
            if (opts != null)
                Log("AUTOTEST llinteract Options BCON 4099 = [" + string.Join(",", opts.Constants) + "]");
            StartLeg(0);
            _ll2State = 1;
        }

        private static bool LL2PushRow(int row, int param0, string what)
        {
            var action = _ll2Lamp.GetAction(row, _ll2Av, _vm.Context, false, new short[] { (short)param0, 0, 0, 0 });
            if (action == null) { Log("AUTOTEST llinteract: GetAction null for " + what + " row=" + row); return false; }
            action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
            // v4 (run-1 root cause): the Force rows are DEBUG rows whose TTAB check
            // tree (#4161, 'my.attr[0] > my.attr[0]') is always false. The port
            // evaluates that check when the action reaches the queue front
            // (CheckTS1Action runs the check routine REGARDLESS of
            // FSOSkipPermissions) and VMThread.AttemptPush then silently drops the
            // queued action (RemoveAt) — the tree never runs (the SIM-19 drop
            // mechanism). Native debug interactions skip the check entirely
            // ('do not bother running check'); the harness push replicates that
            // debug-enabled law by clearing the check routine.
            action.CheckRoutine = null;
            _ll2Av.Thread.EnqueueAction(action);
            _ll2ActionUID = action.UID;
            Log("AUTOTEST llinteract pushed " + what + " row=" + row + " uid=" + action.UID);
            return true;
        }

        private static void StartLeg(int leg)
        {
            _ll2Leg = leg;
            _ll2Frame = 0;
            _ll2GenieClearFrame = 0;
            _ll2SawChain = false;
            _ll2LastQueueClear = false;
            _ll2LegDialogs = _ll2Dialogs;
            _ll2EntitiesLegStart = _vm.Entities.Count;
            _ll2GoodLegStart = LL2CountGuids(LL2GoodSummonGuids);
            _ll2RoachLegStart = LL2CountGuids(new[] { 0x4415A98Eu });
            // v4: the push is deferred to LL2Drive (settle + slot-0 genie clear +
            // guard defeat first). Wish responses follow the engine YesNo law:
            // 0 = yes/TRUE ('Money'), 1 = no/FALSE ('Air').
            switch (leg)
            {
                case 0: _ll2WishChoice = 0; _ll2PendingPush = true; break;
                case 1: _ll2WishChoice = 0; _ll2PendingPush = true; break;
                case 2: _ll2WishChoice = 1; _ll2PendingPush = true; break;
                case 3: _ll2WishChoice = 0; _ll2PendingPush = false; _ll2SaveDone = false; Log("AUTOTEST llinteract leg D: saving lot"); break;
            }
        }

        private static void LL2Drive()
        {
            _ll2Frame++;

            // content-level chain-progress signal: the Force row tree stamps
            // attr[2] with the pair selector (4 = Money/Love, 3 = Earth/Air) and
            // the chain tail resets it to 0 — used for completion below (the
            // avatar's queue is NOT usable: ambient pushes like the 9:00 'At
            // School' flow refill it forever — run-4 leg-1 pin).
            if (_ll2Leg < 3 && _ll2Lamp != null)
            {
                var pair = (_ll2Leg == 2) ? 3 : 4;
                if (_ll2Lamp.GetAttribute(2) == pair) _ll2SawChain = true;
            }

            var genie = _vm.Context.ObjectQueries.Avatars.Any(a => a.Object?.OBJ?.GUID == 505322445u);
            if (genie && !_ll2SawGenie)
            {
                _ll2SawGenie = true;
                Log("AUTOTEST llinteract genie NPC 505322445 appeared leg=" + _ll2Leg + " frame=" + _ll2Frame);
            }

            // auto-respond the leg's dialog chain (R222 law), extended for the
            // r157 queue law (run-2 pin): a TS1 dialog parks QUEUED as the
            // interacting thread's BlockingState (HasDisplayed=false) while any
            // other entity holds GlobalBlockingDialog — it never reaches the
            // global slot, and after 1800 ticks it TIMES OUT taking the default
            // ResponseCode 0 (= the yes branch). Respond the displayed global
            // dialog first, then the avatar thread's queued dialog directly.
            var responded = false;
            var dlgEnt = _vm.GlobalBlockingDialog;
            if (dlgEnt != null)
            {
                var bs = dlgEnt.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                if (bs != null && !bs.Responded)
                {
                    bs.Responded = true;
                    bs.ResponseCode = (byte)_ll2WishChoice;
                    bs.ResponseText = _ll2WishChoice.ToString();
                    _ll2Dialogs++;
                    responded = true;
                    Log("AUTOTEST llinteract dialog#" + _ll2Dialogs + " responded-global (choice " + _ll2WishChoice + ") leg=" + _ll2Leg + " frame=" + _ll2Frame);
                    _vm.GlobalBlockingDialog = null;
                    if (_vm.LastSpeedMultiplier > 0) { _vm.SpeedMultiplier = _vm.LastSpeedMultiplier; _vm.LastSpeedMultiplier = 0; }
                    else if (_vm.SpeedMultiplier < 0) _vm.SpeedMultiplier = 1;
                }
            }
            if (!responded && _ll2Leg < 3 && !_ll2PendingPush)
            {
                var qbs = _ll2Av?.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                if (qbs != null && !qbs.Responded)
                {
                    qbs.Responded = true;
                    qbs.ResponseCode = (byte)_ll2WishChoice;
                    qbs.ResponseText = _ll2WishChoice.ToString();
                    _ll2Dialogs++;
                    Log("AUTOTEST llinteract dialog#" + _ll2Dialogs + " responded-queued (choice " + _ll2WishChoice
                        + " type=" + qbs.Type + " wait=" + qbs.WaitTime
                        + ") leg=" + _ll2Leg + " frame=" + _ll2Frame
                        + " hasDisplayed=" + qbs.HasDisplayed
                        + " latchObj=" + (_vm.GlobalBlockingDialog?.ObjectID ?? -1));
                }
            }

            // v4 deferred push: settle, clear the autonomous slot-0 genie puppet,
            // then defeat the once-per-day guard and push. A live non-ghost genie
            // in the lamp's slot 0 parks the rub tree at [21]/[22] (initiation
            // decode); the ghost 0xC772A09E is the same puppet's first form.
            if (_ll2PendingPush)
            {
                if (_vm.GlobalBlockingDialog != null) return; // never queue world edits under a latch
                var puppet = _vm.Entities.FirstOrDefault(e => e.Object?.OBJ != null
                    && (e.Object.OBJ.GUID == 505322445u || e.Object.OBJ.GUID == 0xC772A09Eu));
                if (puppet != null)
                {
                    if (_ll2GenieClearFrame == 0)
                    {
                        _ll2GenieClearFrame = _ll2Frame;
                        Log("AUTOTEST llinteract clearing slot-0 genie puppet guid=0x" + puppet.Object.OBJ.GUID.ToString("X")
                            + " obj=" + puppet.ObjectID + " leg=" + _ll2Leg + " frame=" + _ll2Frame);
                        try { puppet.Delete(false, _vm.Context); }
                        catch (Exception de) { Log("AUTOTEST llinteract genie clear EXC " + de.GetType().Name + " " + de.Message); }
                    }
                    else if (_ll2Frame - _ll2GenieClearFrame > 600)
                    {
                        FinishLeg(false, "genie puppet would not clear");
                    }
                    return;
                }
                if (_ll2Frame < 30) return;                    // in-leg settle before pushing
                if (_ll2Av?.Thread?.Queue?.Count > 0) return;  // avatar queue drained first
                if (_ll2Frame > 3600) { FinishLeg(false, "pre-push wait exceeded (queue/lantern busy)"); return; }
                // prescription step 2: test #4098 refuses the rub while
                // lamp.attr[5] == global[1] (once-per-day guard).
                _ll2Lamp.SetAttribute(5, (short)(_vm.GetGlobalValue(1) - 1));
                var row = (_ll2Leg == 2) ? _ll2RowBadAir : _ll2RowForceGood;
                if (!LL2PushRow(row, 0, (_ll2Leg == 2) ? "Force Bad/Earth Air" : "Force Good/Money Love"))
                    FinishLeg(false, "push failed");
                else
                {
                    _ll2PendingPush = false;
                    _ll2Frame = 0; // the leg's stall budget measures from the push,
                                   // not from StartLeg (run-3 leg-2 pin: a long
                                   // pre-push wait consumed the 7200 window)
                    // diagnostic: lamp attribute ground truth right after the push
                    // (attr[2] is written by the Force row tree before its rub gosub;
                    // attr[5] is re-stamped by 'actual rub' [47] after routing).
                    Log("AUTOTEST llinteract postPush leg=" + _ll2Leg
                        + " lampAttr0=" + _ll2Lamp.GetAttribute(0) + " attr2=" + _ll2Lamp.GetAttribute(2)
                        + " attr3=" + _ll2Lamp.GetAttribute(3) + " attr5=" + _ll2Lamp.GetAttribute(5)
                        + " global1=" + _vm.GetGlobalValue(1)
                        + " avQueue=" + (_ll2Av?.Thread?.Queue?.Count ?? -1));
                }
                return;
            }

            // leg D second half: after PlayHouse the runner re-captures its own _vm;
            // wait for the reloaded world to expose the lamp again.
            if (_ll2ReloadPending)
            {
                if (_vm == null) return;
                var lamp = _vm.Entities.FirstOrDefault(e => e.Object != null && e.Object.OBJ != null && e.Object.OBJ.GUID == _ll2LampGuid);
                if (lamp == null)
                {
                    if (_ll2Frame > 2400) FinishLeg(false, "lamp not present after reload");
                    return;
                }
                _ll2Lamp = lamp;
                _ll2ReloadPending = false;
                Log("AUTOTEST llinteract persistence: lamp present after reload obj=" + lamp.ObjectID);
                FinishLeg(true, "lamp survived save->reload");
                return;
            }

            // leg D first half: save, then reload
            if (_ll2Leg == 3)
            {
                if (!_ll2SaveDone)
                {
                    if (_ll2Save())
                    {
                        _ll2SaveDone = true;
                        Log("AUTOTEST llinteract leg D: lot saved, reloading");
                        _ll2Reload();
                        _ll2ReloadPending = true;
                    }
                    else if (_ll2Frame > 300) FinishLeg(false, "save callback kept failing");
                    return;
                }
            }

            var queueClear = _ll2Av?.Thread?.Queue?.Count == 0
                && (_ll2Av.Thread.ActiveAction == null || _ll2Av.Thread.ActiveAction.UID != _ll2ActionUID);

            if (_ll2Frame == 300 || _ll2Frame == 900 || _ll2Frame == 1800 || _ll2Frame == 2700
                || _ll2Frame == 3600 || _ll2Frame == 4500 || _ll2Frame == 5400 || _ll2Frame == 6300)
            {
                Log("AUTOTEST llinteract leg=" + _ll2Leg + " frame=" + _ll2Frame + " queueClear=" + queueClear
                    + " dialogs=" + _ll2Dialogs + " geniePresent=" + genie
                    + " entitiesNow=" + _vm.Entities.Count + " (legStart " + _ll2EntitiesLegStart + ")"
                    + " budget=" + (_ll2Fam?.Budget ?? -1));
                // diagnostic: rub-tree progress ground truth (attr[2] row selector,
                // attr[3] wish code, attr[5] day stamp, attr[0] main state)
                Log("AUTOTEST llinteract attrs leg=" + _ll2Leg + " frame=" + _ll2Frame
                    + " attr0=" + _ll2Lamp.GetAttribute(0) + " attr2=" + _ll2Lamp.GetAttribute(2)
                    + " attr3=" + _ll2Lamp.GetAttribute(3) + " attr5=" + _ll2Lamp.GetAttribute(5)
                    + " latchObj=" + (_vm.GlobalBlockingDialog?.ObjectID ?? -1));
                LL2LogStack("av", _ll2Av?.Thread?.Stack);
                LL2LogStack("lamp", _ll2Lamp?.Thread?.Stack);
            }

            // diagnostic: first frame the queue drains after a push — dump tree state
            if (_ll2Leg < 3 && queueClear && !_ll2LastQueueClear && _ll2Dialogs == _ll2LegDialogs)
            {
                Log("AUTOTEST llinteract queueDrainedNoDialog leg=" + _ll2Leg + " frame=" + _ll2Frame
                    + " attr0=" + _ll2Lamp.GetAttribute(0) + " attr2=" + _ll2Lamp.GetAttribute(2)
                    + " attr3=" + _ll2Lamp.GetAttribute(3) + " attr5=" + _ll2Lamp.GetAttribute(5)
                    + " active=" + (_ll2Av?.Thread?.ActiveAction?.UID ?? -1));
                LL2LogStack("drain-av", _ll2Av?.Thread?.Stack);
            }
            _ll2LastQueueClear = queueClear;

            // legs A-C: the decoded chain is exactly TWO blocking dialogs (the
            // wish yes/no + the outcome announcement); completion needs both plus
            // a drained queue. A missing dialog stalls to an honest FAIL.
            var legDialogs = _ll2Dialogs - _ll2LegDialogs;
            // completion = content signals: both dialogs responded, the row tree
            // stamped its pair selector (sawChain) and the chain tail has ADVANCED
            // the selector off the pair value (run-5 pin: the tail ROTATES attr[2]
            // — after the Earth/Air pair it becomes 4, never 0), and the pushed
            // interaction is no longer the avatar's active action.
            if (_ll2Leg < 3 && legDialogs >= 2 && _ll2SawChain
                && _ll2Lamp.GetAttribute(2) != ((_ll2Leg == 2) ? 3 : 4)
                && !genie
                && (_ll2Av?.Thread?.ActiveAction?.UID ?? -1) != _ll2ActionUID)
                EvaluateLeg();
            else if (_ll2Frame >= 7200)
            {
                LL2DumpStallState("leg window expired");
                FinishLeg(false, "leg stalled (queueClear=" + queueClear + " dialogs=" + legDialogs + ")");
            }
        }

        private static int LL2CountGuids(uint[] guids)
        {
            return _vm.Entities.Count(e => e.Object?.OBJ != null && guids.Contains(e.Object.OBJ.GUID));
        }

        private static void LL2LogStack(string tag, System.Collections.Generic.List<VMStackFrame> stack)
        {
            if (stack == null || stack.Count == 0) { Log("AUTOTEST llinteract stack " + tag + ": <empty>"); return; }
            var parts = new System.Collections.Generic.List<string>();
            foreach (var fr in stack)
                parts.Add("#" + (fr.Routine?.ID ?? 0) + "@" + fr.InstructionPointer);
            Log("AUTOTEST llinteract stack " + tag + ": " + string.Join(" <- ", parts));
        }

        private static void LL2DumpStallState(string why)
        {
            try
            {
                Log("AUTOTEST llinteract STALL-DUMP (" + why + ") leg=" + _ll2Leg + " frame=" + _ll2Frame
                    + " attr0=" + _ll2Lamp.GetAttribute(0) + " attr2=" + _ll2Lamp.GetAttribute(2)
                    + " attr3=" + _ll2Lamp.GetAttribute(3) + " attr5=" + _ll2Lamp.GetAttribute(5)
                    + " latchObj=" + (_vm.GlobalBlockingDialog?.ObjectID ?? -1)
                    + " speed=" + _vm.SpeedMultiplier
                    + " goodDelta=" + (LL2CountGuids(LL2GoodSummonGuids) - _ll2GoodLegStart)
                    + " roachDelta=" + (LL2CountGuids(new[] { 0x4415A98Eu }) - _ll2RoachLegStart));
                LL2LogStack("stall-av", _ll2Av?.Thread?.Stack);
                var bs = _ll2Av?.Thread?.BlockingState;
                Log("AUTOTEST llinteract stall-av BlockingState=" + (bs == null ? "<null>" : bs.GetType().Name)
                    + (bs is FSO.SimAntics.Primitives.VMDialogResult qd
                        ? " dialogType=" + qd.Type + " responded=" + qd.Responded + " hasDisplayed=" + qd.HasDisplayed + " wait=" + qd.WaitTime
                        : ""));
                var aa = _ll2Av?.Thread?.ActiveAction;
                Log("AUTOTEST llinteract stall-av ActiveAction=" + (aa == null ? "<null>" : "uid=" + aa.UID + " '" + aa.Name + "'")
                    + " queue=[" + string.Join(",", (_ll2Av?.Thread?.Queue ?? new System.Collections.Generic.List<VMQueuedAction>()).Select(q => q.UID + "'" + q.Name + "'")) + "]");
                LL2LogStack("stall-lamp", _ll2Lamp?.Thread?.Stack);
            }
            catch (Exception se) { Log("AUTOTEST llinteract STALL-DUMP EXC " + se.GetType().Name + " " + se.Message); }
        }

        private static void EvaluateLeg()
        {
            var goodDelta = LL2CountGuids(LL2GoodSummonGuids) - _ll2GoodLegStart;
            var roachDelta = LL2CountGuids(new[] { 0x4415A98Eu }) - _ll2RoachLegStart;
            var entitiesDelta = _vm.Entities.Count - _ll2EntitiesLegStart;
            var legDialogs = _ll2Dialogs - _ll2LegDialogs;
            switch (_ll2Leg)
            {
                case 0: // A: Force Good/Money Love → yes → wish dialog + 'POT OF GOLD'
                        // → 'good money' #4133 random summon (GUID-scoped delta)
                    FinishLeg(legDialogs == 2 && goodDelta > 0,
                        "dialogs=" + legDialogs + " goodSummonDelta=" + goodDelta + " entitiesDelta=" + entitiesDelta);
                    break;
                case 1: // B: repeat use — the full chain again on the live slot
                    FinishLeg(legDialogs == 2 && goodDelta > 0,
                        "dialogs=" + legDialogs + " goodSummonDelta=" + goodDelta + " entitiesDelta=" + entitiesDelta);
                    break;
                case 2: // C: Force Bad/Earth Air → no ('Air') → announcement →
                        // exactly Tuning[12]=9 roach controllers 0x4415A98E
                    FinishLeg(legDialogs == 2 && roachDelta == 9,
                        "dialogs=" + legDialogs + " roachDelta=" + roachDelta + " (expected 9) entitiesDelta=" + entitiesDelta);
                    break;
            }
        }

        private static void FinishLeg(bool ok, string detail)
        {
            _ll2LegOk[_ll2Leg] = ok;
            Log("AUTOTEST llinteract leg " + _ll2Leg + (ok ? " PASS " : " FAIL ") + detail);
            _ll2Leg++;
            if (_ll2Leg <= 3) StartLeg(_ll2Leg);
            else LL2Verdict();
        }

        private static void LL2Verdict()
        {
            Log("AUTOTEST llinteract verdict legs A/B/C/D = "
                + string.Join("/", _ll2LegOk.Select(x => x ? "ok" : "FAIL")));
            try { if (!_ll2ReloadPending && _ll2Lamp != null && _vm != null) _ll2Lamp.Delete(false, _vm.Context); } catch { }
            if (_ll2LegOk.All(x => x)) Pass("llinteract");
            else Fail("llinteract");
            _ll2State = 2;
        }

        // EXP-01 llfire (opt-in "llfire"): the FIRE + ROCKET census rows,
        // content-derived from fire-loop-decode-20260916.md and
        // rocket-loop-decode-20260916.md. The rocket is the deterministic entry:
        // Launch (TTAB 129 row 'Launch', user path always passes) spawns the
        // Down/Explosion twin 0xDE9C3FEA while the standing rocket 0x405046FF
        // stays; its explosion phase attempts a burn EVERY cycle while the
        // launcher is INSIDE (outdoors ~3% rolls), and 'burn something' #4107
        // drops a bare Fire even with no flammable candidate indoors. Legs:
        //   R  launch -> twin seen -> Fire 0x24C95F99 entities on the lot (+ a
        //      Burns-flagged host gaining VMEntityFlags.Burning when present).
        //   P  ecosystem while burning: a room sim carries a queued 'Fire!'
        //      panic interaction AND BuildBuyEnabled == false (generic TS1 call
        //      10, set by Fire set-up #4100 each cycle).
        //   A  burn-out: room-burn attr[0] > Tuning[135]=75 -> destroy #4105
        //      leaves Ash 0x63416BA1. Household extinguish autonomy is cancelled
        //      for this leg (disclosed guard) so the burn can outrun the sims;
        //      the NPC firefighter can still win the race -> honest FAIL.
        //   E  extinguish chain: fresh ignition (second rocket), push the Fire's
        //      own Extinguish row on the adult -> flame attr[2] drains, fires
        //      reach 0, Burning hosts clear, BuildBuyEnabled returns true
        //      (generic 11 on the douse path).
        // Verdict: explicit llfire PASS only when every leg's assertions hold.

        private static int _ll3State;      // 0 init, 1 drive, 2 done
        private static int _ll3Leg;        // 0=R 1=P 2=A 3=E
        private static int _ll3Frame;
        private static int _ll3Settle;
        private static VMAvatar _ll3Av;
        private static VMEntity _ll3Rocket;
        private static int _ll3RowLaunch = -1;
        private static int _ll3RowExtinguish = -1;
        private static bool[] _ll3LegOk = new bool[4];
        private static bool _ll3SawTwin, _ll3SawFire, _ll3SawBurning, _ll3SawPanic,
            _ll3SawBuildLock, _ll3SawUnlock, _ll3Ash;
        private static bool _ll3Guard;     // cancel extinguish autonomy (leg A)
        private static int _ll3GuardCancels;
        private static uint _ll3ActionUID;
        private static bool _ll3PendingPush;
        private static bool _ll3LaunchedThisLeg;
        private static int _ll3LaunchTries;      // run-8: outdoor landings are native variance — bounded disclosed retries
        private static bool _ll3EDrainSeen;      // run-8: extinguish completion = drain + unlock (not total drain)
        private static int _ll3EMaxFires;        // run-10: any decrease from peak = a douse (spread can outpace the sim)
        private static int _ll3FiresLegStart;
        private static VMEntity _ll3Anchor; // enclosed Burns-flagged furniture (launch anchor)
        private static readonly System.Collections.Generic.List<VMEntity> _ll3Anchors =
            new System.Collections.Generic.List<VMEntity>(); // all enclosed Burns candidates (run-5 law: one anchor's rings can all be blocked)
        private static int _ll3TwinDiagTick;   // run-3 diagnostics: twin telemetry
        private static int _ll3TwinLastData0 = -1;
        private static FSO.LotView.Model.LotTilePos _ll3TwinLastPos;

        // run-1..4 law: the burn gate keys on the launcher's room — an outdoor
        // launch only gets ~3% rolls and NO fallback fire. ROOM IDS: 1 = the
        // OUTSIDE room (RoomData[1].IsOutside; the map inits to 1); enclosed
        // rooms are 2+. GetRoomAt returns 0 only for out-of-bounds tiles, so
        // the enclosed test is room >= 2. Runs 1-4 all launched OUTDOORS (the
        // run-4 telemetry: countdown base 0 = the outside branch, storedRoom 0
        // = room id 1) and the no-ignition outcome was native-correct.
        private static bool LL3Enclosed(FSO.LotView.Model.LotTilePos pos)
        {
            return _vm.Context.GetRoomAt(pos) >= 2;
        }

        private static bool LL3Burns(VMEntity e)
        {
            // same read as VMBurn.cs: FlagField2 & VMEntityFlags2.Burns
            return (((FSO.SimAntics.VMEntityFlags2)e.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.FlagField2))
                & FSO.SimAntics.VMEntityFlags2.Burns) > 0;
        }

        private static int LL3CountGuid(uint guid)
        {
            return _vm.Entities.Count(e => e.Object?.OBJ != null && e.Object.OBJ.GUID == guid);
        }

        private static VMEntity LL3FirstGuid(uint guid)
        {
            return _vm.Entities.FirstOrDefault(e => e.Object?.OBJ != null && e.Object.OBJ.GUID == guid);
        }

        private static int LL3FireCount() { return LL3CountGuid(0x24C95F99u); }

        private static bool LL3AnyBurningHost()
        {
            // a Burns-flagged object currently carrying the Burning flag (data[8] bit 9)
            return _vm.Entities.Any(e => e.Object?.OBJ != null
                && e.Object.OBJ.GUID != 0x24C95F99u
                && e.GetFlag(FSO.SimAntics.VMEntityFlags.Burning));
        }

        private static bool LL3PanicQueued()
        {
            foreach (var av in _vm.Context.ObjectQueries.Avatars)
            {
                var q = av.Thread?.Queue;
                if (q != null)
                {
                    foreach (var item in q)
                        if ((item.Name ?? "").IndexOf("Fire", System.StringComparison.OrdinalIgnoreCase) >= 0) return true;
                }
                var act = av.Thread?.ActiveAction;
                if (act != null && (act.Name ?? "").IndexOf("Fire", System.StringComparison.OrdinalIgnoreCase) >= 0) return true;
            }
            return false;
        }

        private static void LL3AutonomyGuard()
        {
            // leg A guard: cancel every avatar's 'Extinguish' actions (household
            // autonomy + any on-lot NPC) so the burn-out can win the race.
            // Disclosed diagnostic, leg-scoped.
            foreach (var av in _vm.Context.ObjectQueries.Avatars)
            {
                var th = av.Thread;
                if (th == null) continue;
                for (int i = th.Queue.Count - 1; i >= 0; i--)
                {
                    if ((th.Queue[i].Name ?? "").IndexOf("Extinguish", System.StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        var uid = th.Queue[i].UID;
                        th.Queue.RemoveAt(i);
                        _ll3GuardCancels++;
                        Log("AUTOTEST llfire autonomy-guard: cancelled 'Extinguish' uid=" + uid
                            + " on obj=" + av.ObjectID + " leg=" + _ll3Leg + " frame=" + _ll3Frame + " (disclosed)");
                    }
                }
                var act = th.ActiveAction;
                if (act != null && (act.Name ?? "").IndexOf("Extinguish", System.StringComparison.OrdinalIgnoreCase) >= 0
                    && act.UID != _ll3ActionUID)
                {
                    // leave the active one to the tree's own exit — cancelling the
                    // ACTIVE action mid-tree is not supported from outside; log it.
                    Log("AUTOTEST llfire autonomy-guard: active 'Extinguish' uid=" + act.UID
                        + " on obj=" + av.ObjectID + " still running (cannot cancel active; disclosed)");
                }
            }
        }

        private static void CheckLLFire()
        {
            try
            {
                switch (_ll3State)
                {
                    case 0: LL3Init(); break;
                    case 1: LL3Drive(); break;
                    case 2: return; // verdict recorded
                }
            }
            catch (Exception le)
            {
                Log("AUTOTEST llfire EXC state=" + _ll3State + " leg=" + _ll3Leg + " frame=" + _ll3Frame + " "
                    + le.GetType().Name + " " + le.Message + " AT " + (le.StackTrace ?? "").Replace("\n", " | "));
                Fail("llfire");
                _ll3State = 2;
            }
        }

        private static bool LL3PlaceRocket()
        {
            // run-1 law: launch from an ENCLOSED tile beside flammable furniture.
            // Ring around the anchor (enclosed Burns-flagged object) when present,
            // else the avatar. Every candidate tile must itself be enclosed.
            var anchorList = _ll3Anchors.Count > 0 ? _ll3Anchors : new System.Collections.Generic.List<VMEntity> { _ll3Av };
            foreach (var anchorEnt in anchorList)
            for (int ring = 1; ring <= 3; ring++)
            {
                var basePos = anchorEnt.Position;
                // run-6 law: LotTilePos.TileX/TileY are TILE units (the setter does
                // x = value << 4) — the earlier 16*ring offsets were 16-48 TILES out
                // (every launch landed outdoors; runs 5-6's enclosed filter then
                // rejected every candidate). Ring offsets are ±ring TILES.
                var candidates = new[]
                {
                    new { dx = (short)(ring), dy = (short)0 },
                    new { dx = (short)(-ring), dy = (short)0 },
                    new { dx = (short)0, dy = (short)(ring) },
                    new { dx = (short)0, dy = (short)(-ring) },
                    new { dx = (short)(ring), dy = (short)(ring) },
                    new { dx = (short)(-ring), dy = (short)(-ring) },
                };
                foreach (var cand in candidates)
                {
                    var pos = basePos;
                    pos.TileX += cand.dx;
                    pos.TileY += cand.dy;
                    if (!LL3Enclosed(pos)) continue;
                    try
                    {
                        var grp = _vm.Context.CreateObjectInstance(0x405046FFu, pos, FSO.LotView.Model.Direction.NORTH);
                        if (grp != null && grp.BaseObject != null && grp.BaseObject.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD)
                        {
                            _ll3Rocket = grp.BaseObject;
                            return true;
                        }
                    }
                    catch (Exception ce) { Log("AUTOTEST llfire rocket ring=" + ring + " EXC " + ce.GetType().Name + " " + ce.Message); }
                }
            }
            return false;
        }

        private static bool LL3PushLaunch()
        {
            var action = _ll3Rocket.GetAction(_ll3RowLaunch, _ll3Av, _vm.Context, false, new short[] { 0, 0, 0, 0 });
            if (action == null) { Log("AUTOTEST llfire: GetAction null for Launch row=" + _ll3RowLaunch); return false; }
            action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
            action.CheckRoutine = null; // same harness law as llinteract v4: CheckTS1Action
                                        // runs the TTAB check at queue front regardless of
                                        // FSOSkipPermissions; the user path (param0=0) passes
                                        // the autonomy test natively, but the debug-row
                                        // drop mechanism is defeated uniformly here.
            _ll3Av.Thread.EnqueueAction(action);
            _ll3ActionUID = action.UID;
            Log("AUTOTEST llfire pushed Launch row=" + _ll3RowLaunch + " uid=" + action.UID + " rocket=" + _ll3Rocket.ObjectID);
            return true;
        }

        private static bool LL3PushExtinguish(VMEntity fire)
        {
            var action = fire.GetAction(_ll3RowExtinguish, _ll3Av, _vm.Context, false, new short[] { 0, 0, 0, 0 });
            if (action == null) { Log("AUTOTEST llfire: GetAction null for Extinguish row=" + _ll3RowExtinguish); return false; }
            action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
            action.CheckRoutine = null;
            _ll3Av.Thread.EnqueueAction(action);
            _ll3ActionUID = action.UID;
            Log("AUTOTEST llfire pushed Extinguish row=" + _ll3RowExtinguish + " uid=" + action.UID + " fire=" + fire.ObjectID
                + " flame attr2=" + fire.GetAttribute(2));
            return true;
        }

        private static void LL3Init()
        {
            // same latch discipline as llinteract v4: no placement/push inside the
            // boot-dialog latch window; let the lot settle first.
            if (_vm?.GlobalBlockingDialog != null) return;
            if (++_ll3Settle < 90) return;

            var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>()
                .Where(a => a.Position != FSO.LotView.Model.LotTilePos.OUT_OF_WORLD).ToList();
            if (avatars == null || avatars.Count == 0) { Log("AUTOTEST llfire: no in-world avatar"); Fail("llfire"); _ll3State = 2; return; }
            _ll3Av = avatars.FirstOrDefault(a => a.GetPersonData(VMPersonDataVariable.PersonsAge) >= 18) ?? avatars[0];
            Log("AUTOTEST llfire avatar obj=" + _ll3Av.ObjectID + " age=" + _ll3Av.GetPersonData(VMPersonDataVariable.PersonsAge)
                + " at " + _ll3Av.Position + " room=" + _vm.Context.GetRoomAt(_ll3Av.Position) + (LL3Enclosed(_ll3Av.Position) ? " (enclosed)" : " (OUTSIDE)"));

            // anchor: the first ENCLOSED Burns-flagged object (indoor furniture) —
            // the launch happens beside it, so the crash cone is full of
            // flammables and the launcher's room is enclosed.
            foreach (var e in _vm.Entities)
            {
                if (e.Object?.OBJ == null || e is VMAvatar) continue;
                if (e.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD) continue;
                var g = e.Object.OBJ.GUID;
                if (g == 0x24C95F99u || g == 0x405046FFu || g == 0xDE9C3FEAu) continue;
                if (!LL3Burns(e)) continue;
                if (_vm.Context.GetRoomAt(e.Position) < 2) continue; // 1 = outside room
                _ll3Anchors.Add(e);
            }
            _ll3Anchor = _ll3Anchors.Count > 0 ? _ll3Anchors[0] : null;
            Log(_ll3Anchors.Count > 0
                ? "AUTOTEST llfire anchors=" + _ll3Anchors.Count + " first obj=" + _ll3Anchors[0].ObjectID
                    + " guid=0x" + _ll3Anchors[0].Object.OBJ.GUID.ToString("X")
                    + " '" + (_ll3Anchors[0].Object.OBJ.ChunkLabel ?? "?") + "' at " + _ll3Anchors[0].Position
                    + " room=" + _vm.Context.GetRoomAt(_ll3Anchors[0].Position)
                : "AUTOTEST llfire: no enclosed Burns-flagged anchor found (fallback: avatar ring)");

            if (!LL3PlaceRocket() || _ll3Rocket == null)
            { Log("AUTOTEST llfire: rocket placement failed"); Fail("llfire"); _ll3State = 2; return; }

            // resolve the Launch row from the rocket's own IFF (TTAs 129 labels
            // line up with TTAB 129 row indices)
            var rokIff = _ll3Rocket.Object?.Resource?.Iff;
            var rokas = rokIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAs>(129);
            var roktab = rokIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAB>(129);
            if (rokas == null || roktab == null) { Log("AUTOTEST llfire: rocket TTAs/TTAB 129 not found"); Fail("llfire"); _ll3State = 2; return; }
            for (int i = 0; i < rokas.Length && i < roktab.Interactions.Length; i++)
                if (_ll3RowLaunch < 0 && (rokas.GetString(i) ?? "").Trim() == "Launch") _ll3RowLaunch = i;
            if (_ll3RowLaunch < 0)
            { Log("AUTOTEST llfire: Launch row not resolved"); Fail("llfire"); _ll3State = 2; return; }
            Log("AUTOTEST llfire rocketSpawned obj=" + _ll3Rocket.ObjectID + " at " + _ll3Rocket.Position
                + " LaunchRow=" + _ll3RowLaunch + " prePushFires=" + LL3FireCount());

            _ll3Leg = 0; _ll3Frame = 0; _ll3PendingPush = true;
            for (int i = 0; i < _ll3LegOk.Length; i++) _ll3LegOk[i] = false;
            _ll3State = 1;
        }

        private static void LL3StartLeg(int leg)
        {
            _ll3Leg = leg;
            _ll3Frame = 0;
            _ll3PendingPush = false;
            _ll3LaunchedThisLeg = false;
            _ll3LaunchTries = 0;
            _ll3EDrainSeen = false;
            _ll3EMaxFires = 0;
            switch (leg)
            {
                case 0: _ll3PendingPush = true; break; // R: launch after settle
                case 1: break;                          // P: observe panic + build lock
                case 2: _ll3Guard = true; _ll3GuardCancels = 0; break; // A: burn-out under guard
                case 3: _ll3Guard = false; _ll3PendingPush = true; break; // E: fresh ignition + extinguish
            }
            Log("AUTOTEST llfire leg " + leg + " start fires=" + LL3FireCount()
                + " buildBuy=" + (_vm.Context.Architecture.BuildBuyEnabled));
        }

        private static void LL3Drive()
        {
            _ll3Frame++;

            // content signals, sampled every frame
            if (!_ll3SawTwin && LL3CountGuid(0xDE9C3FEAu) > 0)
            {
                _ll3SawTwin = true;
                Log("AUTOTEST llfire twin 0xDE9C3FEA appeared leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3SawFire && LL3FireCount() > 0)
            {
                _ll3SawFire = true;
                Log("AUTOTEST llfire first Fire entity leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3SawBurning && LL3AnyBurningHost())
            {
                _ll3SawBurning = true;
                Log("AUTOTEST llfire Burning host appeared leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3SawPanic && LL3PanicQueued())
            {
                _ll3SawPanic = true;
                Log("AUTOTEST llfire panic queued leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3SawBuildLock && !_vm.Context.Architecture.BuildBuyEnabled)
            {
                _ll3SawBuildLock = true;
                Log("AUTOTEST llfire BuildBuyEnabled=false (generic 10) leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3SawUnlock && _ll3SawBuildLock && _vm.Context.Architecture.BuildBuyEnabled)
            {
                _ll3SawUnlock = true;
                Log("AUTOTEST llfire BuildBuyEnabled back true (generic 11) leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }
            if (!_ll3Ash && LL3CountGuid(0x63416BA1u) > 0)
            {
                _ll3Ash = true;
                Log("AUTOTEST llfire Ash 0x63416BA1 appeared leg=" + _ll3Leg + " frame=" + _ll3Frame);
            }

            if (_ll3Guard) LL3AutonomyGuard();

            // run-3 diagnostics: while a twin is alive, dump its countdown (data[0],
            // explosion phase at 12..20), its resolved position (OOW = placement
            // failed), the launcher's room (rocket data[11]) and the burn-candidate
            // cone population near the twin.
            var twinEnt = LL3FirstGuid(0xDE9C3FEAu);
            if (twinEnt != null && (_ll3Leg == 0 || _ll3Leg == 3))
            {
                if (++_ll3TwinDiagTick % 30 == 0 || twinEnt.Position != _ll3TwinLastPos)
                {
                    var d0 = twinEnt.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.Graphic);
                    _ll3TwinLastData0 = d0;
                    _ll3TwinLastPos = twinEnt.Position;
                    int launcherId = _ll3Rocket?.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.ObjectId) ?? -1;
                    var launcher = _vm.GetObjectById((short)launcherId);
                    int candNear = 0;
                    foreach (var e2 in _vm.Entities)
                    {
                        if (e2.Object?.OBJ == null || e2 is VMAvatar) continue;
                        if (e2.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD
                            || twinEnt.Position == FSO.LotView.Model.LotTilePos.OUT_OF_WORLD) continue;
                        var dx = e2.Position.TileX - twinEnt.Position.TileX;
                        var dy = e2.Position.TileY - twinEnt.Position.TileY;
                        if (dx * dx + dy * dy > (16 * 5) * (16 * 5)) continue;
                        if (LL3Burns(e2)) candNear++;
                    }
                    Log("AUTOTEST llfire twinDiag leg=" + _ll3Leg + " frame=" + _ll3Frame
                        + " data0=" + d0 + " pos=" + twinEnt.Position
                        + " room=" + _vm.Context.GetRoomAt(twinEnt.Position)
                        + " storedRoom=" + twinEnt.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.Room)
                        + " twinData11=" + twinEnt.GetValue(FSO.SimAntics.Model.VMStackObjectVariable.ObjectId)
                        + " twinId=" + twinEnt.ObjectID
                        + " launcher=" + launcherId + (launcher != null ? (" room=" + _vm.Context.GetRoomAt(launcher.Position)
                            + " pos=" + launcher.Position) : " <missing>")
                        + " burnCandNear=" + candNear);
                }
            }

            // heartbeat
            if (_ll3Frame == 300 || _ll3Frame == 900 || _ll3Frame == 1800 || _ll3Frame == 2700
                || _ll3Frame == 3600 || _ll3Frame == 4500 || _ll3Frame == 5400 || _ll3Frame == 6300)
            {
                Log("AUTOTEST llfire leg=" + _ll3Leg + " frame=" + _ll3Frame + " fires=" + LL3FireCount()
                    + " twin=" + LL3CountGuid(0xDE9C3FEAu) + " ash=" + LL3CountGuid(0x63416BA1u)
                    + " burningHost=" + LL3AnyBurningHost() + " panic=" + LL3PanicQueued()
                    + " buildBuy=" + _vm.Context.Architecture.BuildBuyEnabled
                    + " guardCancels=" + _ll3GuardCancels
                    + " avQueue=" + (_ll3Av?.Thread?.Queue?.Count ?? -1));
            }

            // defensive: answer any blocking dialog with the first choice (R222 law)
            var dlgEnt = _vm.GlobalBlockingDialog;
            if (dlgEnt != null)
            {
                var bs = _ll3Av?.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                var gbs = dlgEnt.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult
                    ?? bs;
                if (gbs != null && !gbs.Responded)
                {
                    gbs.Responded = true;
                    gbs.ResponseCode = 0;
                    gbs.ResponseText = "0";
                    _vm.GlobalBlockingDialog = null;
                    if (_vm.LastSpeedMultiplier > 0) { _vm.SpeedMultiplier = _vm.LastSpeedMultiplier; _vm.LastSpeedMultiplier = 0; }
                    else if (_vm.SpeedMultiplier < 0) _vm.SpeedMultiplier = 1;
                    Log("AUTOTEST llfire dialog auto-responded leg=" + _ll3Leg + " frame=" + _ll3Frame + " (defensive)");
                }
            }

            // deferred pushes: settle, then launch / extinguish
            if (_ll3PendingPush)
            {
                if (_vm.GlobalBlockingDialog != null) return;
                if (_ll3Frame < 30) return;
                if (_ll3Leg == 0)
                {
                    // run-14 law: the avatar's queue can carry an ambient entry at
                    // settle (autonomy) — the queue is not a usable gate (the
                    // llinteract run-4 law); push after the settle window directly.
                    if (_ll3Frame > 3600) { LL3FinishLeg(false, "pre-push wait exceeded"); return; }
                    if (!LL3PushLaunch()) { LL3FinishLeg(false, "push failed"); return; }
                    _ll3PendingPush = false;
                    _ll3Frame = 0; // stall budget measures from the push
                }
                else if (_ll3Leg == 3)
                {
                    // run-12 law: with leg A's leftover fires STILL burning, the
                    // extinguish chain is exercisable directly (run 11 passed amid
                    // a 20-fire inferno: douse-from-peak + unlock) — no re-ignition
                    // needed. Re-ignite ONLY when nothing burns (fires can outpace
                    // the drain-wait; burning tiles also block placement).
                    if (!_ll3LaunchedThisLeg && LL3FireCount() == 0)
                    {
                        if (!LL3PlaceRocket())
                        { LL3FinishLeg(false, "re-ignition rocket placement failed"); return; }
                    }
                    if (!_ll3LaunchedThisLeg) // not launched yet this leg
                    {
                        // run-13 law: a burning lot keeps the sim's queue forever
                        // full (panic 'Fire!' re-propagation 4115@26) — the same
                        // trap llinteract run-4 pinned; push WITHOUT a queue wait.
                        if (_ll3Frame > 3600) { LL3FinishLeg(false, "re-launch wait exceeded"); return; }
                        if (!LL3PushLaunch()) { LL3FinishLeg(false, "re-launch push failed"); return; }
                        _ll3LaunchedThisLeg = true;
                        _ll3Frame = 0;
                        return;
                    }
                    if (LL3FireCount() == 0)
                    {
                        if (_ll3Frame > 7200) { LL3FinishLeg(false, "re-ignition did not produce a fire"); return; }
                        return; // wait for ignition
                    }
                    // resolve the Extinguish row from a live fire's own IFF
                    var fire = LL3FirstGuid(0x24C95F99u);
                    var firIff = fire.Object?.Resource?.Iff;
                    var fias = firIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAs>(129);
                    var fitab = firIff?.Get<FSO.Files.Formats.IFF.Chunks.TTAB>(129);
                    if (_ll3RowExtinguish < 0)
                    {
                        if (fias == null || fitab == null) { LL3FinishLeg(false, "fire TTAs/TTAB 129 not found"); return; }
                        for (int i = 0; i < fias.Length && i < fitab.Interactions.Length; i++)
                            if (_ll3RowExtinguish < 0 && (fias.GetString(i) ?? "").Trim() == "Extinguish") _ll3RowExtinguish = i;
                        if (_ll3RowExtinguish < 0) { LL3FinishLeg(false, "Extinguish row not resolved"); return; }
                    }
                    if (!LL3PushExtinguish(fire)) { LL3FinishLeg(false, "extinguish push failed"); return; } // run-13: no queue wait (panic fills it)
                    _ll3PendingPush = false;
                    _ll3FiresLegStart = LL3FireCount();
                    _ll3Frame = 0;
                }
                return;
            }

            // leg completion laws (content signals; a missing signal stalls to an
            // honest FAIL at the budget)
            switch (_ll3Leg)
            {
                case 0: // R: twin + ignition. The Burning host is OR by law: the
                    // no-candidate indoor path drops a BARE fire (#4107 fallback),
                    // so a missing Burning host is logged, not failed.
                    // The twin's landing is content-chosen (#4106): an outdoor
                    // landing is NATIVE variance (3% rolls, no fallback fire) and a
                    // twin can park alive — a no-fire stall retries the launch
                    // (<= 2, disclosed) instead of failing.
                    if (_ll3SawTwin && _ll3SawFire)
                        LL3FinishLeg(true,
                            "twin=" + _ll3SawTwin + " fires=" + LL3FireCount() + " burningHost=" + _ll3SawBurning
                            + " tries=" + (_ll3LaunchTries + 1));
                    else if (_ll3SawTwin && LL3FireCount() == 0 && _ll3Frame >= 3000 && _ll3LaunchTries < 2)
                    {
                        _ll3LaunchTries++;
                        Log("AUTOTEST llfire leg=0 no ignition (twinAlive=" + (LL3CountGuid(0xDE9C3FEAu) > 0)
                            + ") — disclosed retry #" + _ll3LaunchTries);
                        _ll3SawTwin = false;
                        _ll3PendingPush = true;
                        _ll3Frame = 0;
                    }
                    else if (_ll3Frame >= 7200) LL3FinishLeg(false, "ignition stalled (twin=" + _ll3SawTwin + " fires=" + LL3FireCount()
                        + " tries=" + (_ll3LaunchTries + 1) + ")");
                    break;
                case 1: // P: panic + build lock
                    if (_ll3SawPanic && _ll3SawBuildLock)
                        LL3FinishLeg(true, "panic=" + _ll3SawPanic + " buildLock=" + _ll3SawBuildLock + " fires=" + LL3FireCount());
                    else if (_ll3Frame >= 3600)
                        LL3FinishLeg(false, "ecosystem stalled (panic=" + _ll3SawPanic + " buildLock=" + _ll3SawBuildLock + ")");
                    break;
                case 2: // A: burn-out -> Ash
                    if (_ll3Ash)
                        LL3FinishLeg(true, "ash=1 guardCancels=" + _ll3GuardCancels + " fires=" + LL3FireCount());
                    else if (_ll3Frame >= 7200)
                        LL3FinishLeg(false, "burn-out stalled (ash=0 fires=" + LL3FireCount() + " guardCancels=" + _ll3GuardCancels + ")");
                    break;
                case 3: // E: extinguish chain. run-8 law: spread (1-in-8 per
                    // eligible tick once room-burn > 45) can outpace one sim —
                    // completion is the CHAIN semantics: the fire count drained
                    // below its push-time level AND the douse path unlocked
                    // build mode (generic 11), not a total drain.
                    var fires = LL3FireCount();
                    if (fires > _ll3EMaxFires) _ll3EMaxFires = fires;
                    if (_ll3EMaxFires > 0 && fires < _ll3EMaxFires) _ll3EDrainSeen = true;
                    if (_ll3EDrainSeen && _ll3SawUnlock)
                        LL3FinishLeg(true, "chainDrained fires=" + fires + " firesStart=" + _ll3FiresLegStart
                            + " unlock=" + _ll3SawUnlock);
                    else if (_ll3Frame >= 7200)
                        LL3FinishLeg(false, "extinguish stalled (fires=" + fires + " firesStart=" + _ll3FiresLegStart
                            + " drainSeen=" + _ll3EDrainSeen + " unlock=" + _ll3SawUnlock + ")");
                    break;
            }
        }

        private static void LL3FinishLeg(bool ok, string detail)
        {
            _ll3LegOk[_ll3Leg] = ok;
            Log("AUTOTEST llfire leg " + _ll3Leg + (ok ? " PASS " : " FAIL ") + detail);
            _ll3Leg++;
            if (_ll3Leg <= 3) LL3StartLeg(_ll3Leg);
            else LL3Verdict();
        }

        private static void LL3Verdict()
        {
            Log("AUTOTEST llfire verdict legs R/P/A/E = "
                + string.Join("/", _ll3LegOk.Select(x => x ? "ok" : "FAIL")));
            if (_ll3LegOk.All(x => x)) Pass("llfire");
            else Fail("llfire");
            _ll3State = 2;
        }

        private static void CheckObjectTooltips()
        {
            try
            {
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uitt: no UIText.iff"); Fail("uitt"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw159 = FindStrChunkByID(d, 159, out id, out n, out lbl, out body);
                var s159 = ByteHash256(raw159, sha);
                var e159 = ParseLang1(body, out n);
                bool canon = raw159 != null && lbl == "ObjectTTs" && n == 180 && s159 == R125Str159Sha
                    && e159.Count == 9;
                string canonInfo = "";
                for (int i = 0; i < 9 && canon; i++)
                    if (e159[i] != R125Str159[i]) { canon = false; canonInfo = "e159[" + i + "]"; }
                if (canon && canonInfo == "") canonInfo = "159/9";

                // R198: the cDefaultTTWindow color law (r198/r198-tooltip-law.md)
                // — the normal slot is the default pen 0 (BLACK: Init 0x3b9828
                // stores 0), the error slot is the (0xFF,0,0) palette lookup
                // (0x3b9844-0x3b9860), whose only SetColor consumer is the
                // unaffordable catalog product (ProductButton 0x20b8d4). The
                // 9-entry STR# 159 count above is the proof that the retired
                // TSO ids 16/21/22/24/27 were out of range.
                bool colorLaw =
                    Simitone.Client.UI.Panels.UILotControl.TooltipDefaultColor == new Color(0, 0, 0)
                    && Simitone.Client.UI.Panels.UILotControl.TooltipErrorColor == new Color(255, 0, 0);

                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var lc = screen?.LotControl;
                if (lc == null) liveInfo = "no-lotcontrol;";
                else
                {
                    var vm = lc.vm;
                    var viewer = vm.GetAvatarByPersist(vm.MyUID);
                    var anchors = new Dictionary<string, int>()
                    {
                        { "Persian Plush Pet Bed", 6 },
                        { "Critter Condo", 4 },
                        { "Scratcheriffic Scratching Post", 5 },
                    };
                    bool anchorsOK = viewer != null;
                    bool nameOK = false;
                    string diag = "";
                    if (viewer == null) liveInfo += "no-viewer;";
                    foreach (var kv in anchors)
                    {
                        try
                        {
                            uint guid = 0;
                            for (sbyte cat = 0; cat < 8 && guid == 0; cat++)
                            {
                                var items = Content.Get().WorldCatalog.GetItemsByCategory(cat);
                                if (items == null) continue;
                                foreach (var it in items)
                                {
                                    var wo = Content.Get().WorldObjects.Get(it.GUID);
                                    if (wo == null) continue;
                                    var ctss = wo.Resource.Get<FSO.Files.Formats.IFF.Chunks.CTSS>(wo.OBJ.CatalogStringsID);
                                    if (ctss != null && ctss.GetString(0) == kv.Key) { guid = it.GUID; break; }
                                }
                            }
                            if (guid == 0) { diag += kv.Key + ":noguid; "; anchorsOK = false; continue; }
                            var grp = vm.Context.CreateObjectInstance(guid,
                                FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                            var leader = grp.GetInteractionGroupLeader(grp.Objects[0]);
                            var reason = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader, viewer);
                            bool ok = reason == e159[kv.Value];
                            if (!ok) diag += kv.Key + "->'" + reason + "'(want " + kv.Value + "); ";
                            anchorsOK = anchorsOK && ok;
                            if (kv.Key == "Scratcheriffic Scratching Post")
                            {
                                var name = Simitone.Client.UI.Panels.UILotControl.ObjectHoverName(leader);
                                nameOK = name == kv.Key;
                                if (!nameOK) diag += "name='" + name + "'; ";
                            }
                            grp.Delete(vm.Context);
                        }
                        catch (Exception ae) { diag += kv.Key + "EXC(" + ae.GetType().Name + "); "; anchorsOK = false; }
                    }
                    // R129 engine-derived live checks (disclosed class): the
                    // ladder's human-viewer outcomes the corpus can anchor
                    // without synthesizing a pet viewer — an adults-only table
                    // (every live entry NoChild, no AllowCats/AllowDogs
                    // anywhere) -> [1] rung 1, and a plain table (live entries
                    // but no rung aggregate) -> [0], the engine's terminal
                    // default for human viewers ([8] is pet-only).
                    uint adultsGUID = 0, plainGUID = 0;
                    for (sbyte cat = 0; cat < 8 && (adultsGUID == 0 || plainGUID == 0); cat++)
                    {
                        var items = Content.Get().WorldCatalog.GetItemsByCategory(cat);
                        if (items == null) continue;
                        foreach (var it in items)
                        {
                            var wo = Content.Get().WorldObjects.Get(it.GUID);
                            if (wo == null) continue;
                            var ttab = wo.Resource.Get<FSO.Files.Formats.IFF.Chunks.TTAB>(wo.OBJ.TreeTableID);
                            if (ttab == null || ttab.Interactions.Length == 0) continue;
                            bool any2 = false, allNoChild = true, allNoAdult = true, anyCats2 = false, anyDogs2 = false;
                            foreach (var e2 in ttab.Interactions)
                            {
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.Debug) > 0) continue;
                                any2 = true;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1NoChild) == 0) allNoChild = false;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1NoAdult) == 0) allNoAdult = false;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1AllowCats) > 0) anyCats2 = true;
                                if ((e2.Flags & FSO.Files.Formats.IFF.Chunks.TTABFlags.TS1AllowDogs) > 0) anyDogs2 = true;
                            }
                            if (!any2) continue;
                            bool adultsOnly = allNoChild && !anyCats2 && !anyDogs2;
                            bool petsFamily = allNoChild && allNoAdult; // Pets/Dogs/CatsOnly base
                            if (adultsOnly) { if (adultsGUID == 0) adultsGUID = it.GUID; }
                            else if (!petsFamily) { if (plainGUID == 0) plainGUID = it.GUID; }
                            if (adultsGUID != 0 && plainGUID != 0) break;
                        }
                    }
                    var r129checks = new List<KeyValuePair<uint, int>>();
                    if (adultsGUID != 0) r129checks.Add(new KeyValuePair<uint, int>(adultsGUID, 1));
                    if (plainGUID != 0) r129checks.Add(new KeyValuePair<uint, int>(plainGUID, 0));
                    if (r129checks.Count == 0) liveInfo += "r129-nocorpus;";
                    foreach (var kv2 in r129checks)
                    {
                        try
                        {
                            var grp2 = vm.Context.CreateObjectInstance(kv2.Key,
                                FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                            var leader2 = grp2.GetInteractionGroupLeader(grp2.Objects[0]);
                            var reason2 = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader2, viewer);
                            bool ok2 = reason2 == e159[kv2.Value];
                            if (!ok2) diag += "r129:" + kv2.Key.ToString("X") + "->'" + reason2 + "'(want " + kv2.Value + "); ";
                            anchorsOK = anchorsOK && ok2;
                            grp2.Delete(vm.Context);
                        }
                        catch (Exception ae2) { diag += "r129EXC(" + ae2.GetType().Name + "); "; anchorsOK = false; }
                    }
                    bool selfOK = false;
                    if (viewer != null)
                    {
                        var selfReason = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, viewer, viewer);
                        // R129: [3] is the PET self-hover (engine modes 29/42)
                        // and [8] is pet-only — a HUMAN hovering itself can
                        // produce neither. The ladder output on the sim's own
                        // table is corpus data; pin the impossibilities.
                        selfOK = selfReason != e159[3] && selfReason != e159[8];
                        if (!selfOK) diag += "self->'" + selfReason + "'; ";
                    }
                    // R198: a disabled object routes through the same R129
                    // ladder (the five TSO branches' STR# 159 ids never existed
                    // in the 9-entry table). Probe on a live anchor: the routed
                    // text equals the ladder output and the counter advances.
                    bool disabledOK = false;
                    {
                        var probeGuid = plainGUID != 0 ? plainGUID : adultsGUID;
                        if (probeGuid == 0) liveInfo += "r198-nocorpus;";
                        else
                        {
                            try
                            {
                                var grp3 = vm.Context.CreateObjectInstance(probeGuid,
                                    FSO.LotView.Model.LotTilePos.OUT_OF_WORLD, FSO.LotView.Model.Direction.NORTH, false);
                                var leader3 = grp3.GetInteractionGroupLeader(grp3.Objects[0]);
                                int beforeDisabled = Simitone.Client.UI.Panels.UILotControl.DisabledRouted;
                                var routed = Simitone.Client.UI.Panels.UILotControl.DisabledObjectTooltipText(vm, leader3, viewer);
                                var direct = Simitone.Client.UI.Panels.UILotControl.ObjectTooltipReason(vm, leader3, viewer);
                                disabledOK = routed == direct
                                    && Simitone.Client.UI.Panels.UILotControl.DisabledRouted == beforeDisabled + 1;
                                if (!disabledOK) diag += "r198:disabled->'" + routed + "'vs'" + direct + "'; ";
                                grp3.Delete(vm.Context);
                            }
                            catch (Exception ae3) { diag += "r198EXC(" + ae3.GetType().Name + "); "; }
                        }
                    }
                    live = anchorsOK && selfOK && nameOK && disabledOK;
                    if (!live) liveInfo += "anchors(" + diag + ");";
                }

                Log("AUTOTEST uitt original object hover tooltips: canon=" + canon + " (" + canonInfo + ")"
                    + " live=" + live + " colorLaw=" + colorLaw
                    + " strLoads=" + Simitone.Client.UI.Panels.UILotControl.CanonStringsLoaded
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && live && colorLaw) { Pass("uitt"); return; }
                Log("AUTOTEST uitt: STR# 159 must pin verbatim (9 entries — the TSO ids were out of range), the live classifier must produce the canon reasons for the corpus anchor objects (pets/dogs/cats), the active character, the CTSS name, and the disabled-object ladder routing; the tooltip color law must pin (black default pen, (255,0,0) error slot)");
                Fail("uitt");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uitt EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uitt");
            }
        }

        // ROUND-126 'uibuild': the BUILD-mode catalog subcategory row in the
        // ORIGINAL composition. (1) UIText.iff STR# 139 'BldTips' pins
        // byte-verbatim (full-chunk sha + all 16 English entries; script-
        // generated pins); (2) the 11 mounted tool plaques (res_cpanel.RT
        // kToolBtn 64..77 -> cpanel\Buttons\toolBtn*.bmp) pin name+len+dims+sha
        // and mount at canon dims — SINGLE-frame full images (toolBtnTerrain is
        // 156x39 = 4x39; Frame() would mis-crop it — see ResolveSubSortArt);
        // (3) LIVE through the REAL UIBuyBrowsePanel Build entry flow (ctor ->
        // InitCategory -> the subcategory button loop): all 3 port build
        // categories build their rows with tooltips == STR# 139 verbatim and
        // the pinned plaque dims per slot. [11..13] Hand/Undo/Redo have no port
        // surface (disclosed); [14]/[15] paging strings pair with the R122
        // arrows; the port's 3-category grouping is kept (original evidence
        // suggests a flat paged tool list — disclosed residual, canon md).
        private static void CheckBuildCatalog()
        {
            try
            {
                // ---- string canon ----
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) { Log("AUTOTEST uibuild: no UIText.iff"); Fail("uibuild"); return; }
                var d = System.IO.File.ReadAllBytes(path);
                var sha = System.Security.Cryptography.SHA256.Create();
                int id; int n; string lbl; byte[] body;
                var raw139 = FindStrChunkByID(d, 139, out id, out n, out lbl, out body);
                var s139 = ByteHash256(raw139, sha);
                var e139 = ParseLang1(body, out n);
                bool canon = raw139 != null && lbl == "BldTips" && n == 288 && s139 == R126BldTipsSha
                    && e139.Count == 16;
                string canonInfo = "";
                for (int i = 0; i < 16 && canon; i++)
                    if (e139.Count <= i || e139[i] != R126BldTips[i]) { canon = false; canonInfo = "e139[" + i + "]"; }
                if (!canon && canonInfo == "") canonInfo = "structure";

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                bool art = false; string artInfo = "";
                System.Collections.Generic.Dictionary<string, string[]> pinByLow = null;
                if (ts1 == null) artInfo = "no-ts1;";
                else
                {
                    var entries = ts1.GetFarEntries(".bmp");
                    pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                    foreach (var pin in R126BuildArt) pinByLow[pin[0]] = pin;
                    var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                    art = true;
                    foreach (var en in entries)
                    {
                        if (en == null || en.FarEntry == null) continue;
                        string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                        string[] pin;
                        if (!pinByLow.TryGetValue(low, out pin)) continue;
                        bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                        byte[] b = null; int w = -1, h = -1;
                        try
                        {
                            b = en.Archive.GetEntry(en.FarEntry);
                            if (b != null && b.Length >= 26)
                            {
                                w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                                h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                            }
                        }
                        catch { }
                        bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                            && ByteHash256(b, sha) == pin[4];
                        if (!okPin) { art = false; artInfo += low + ";"; }
                        unseen.Remove(low);
                    }
                    if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }
                }

                // R171 ProductButton state-sheet law. These exact crops are
                // the difference between one legible authored icon and the
                // four crushed repeats visible in the terrain/water captures.
                var terrain0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(144, 33, 4, 0);
                var terrain2 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(144, 33, 4, 2);
                var level0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(156, 33, 4, 0);
                var water0 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(180, 45, 4, 0);
                var wall1 = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(74, 37, 2, 1);
                bool stateLaw = terrain0 == new Rectangle(0, 0, 36, 33)
                    && terrain2 == new Rectangle(72, 0, 36, 33)
                    && level0 == new Rectangle(0, 0, 39, 33)
                    && water0 == new Rectangle(0, 0, 45, 45)
                    && wall1 == new Rectangle(37, 0, 37, 37);
                if (!stateLaw) artInfo += "state-crops=" + terrain0 + "/" + terrain2 + "/" + level0 + "/" + water0 + "/" + wall1 + ";";

                // ---- live band (R145: the FLAT 12-tool row on the cWinArch law;
                // the 2-level group/subsort rows were the mobile composition) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var mp3 = screen?.Frontend?.MainPanel;
                if (screen == null) liveInfo = "no-screen;";
                else if (mp3 == null || mp3.ArchChrome == null) liveInfo = "no-arch;";
                else
                {
                    live = true;
                    try
                    {
                        // R170: mode replacement is atomic in cWinCPanel::SetPanel.
                        // Exercise LIVE -> BUILD -> BUY -> BUILD through the real
                        // flow: the retiring UISubpanel must become non-drawable
                        // immediately (its delayed Kill cleanup still runs),
                        // and exactly one desktop chrome may own the band.
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                        mp3.Switcher_OnCategorySelect(0);
                        var retiringLive = mp3.SubPanel;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        bool atomicLiveBuild = retiringLive == null || !retiringLive.Visible;
                        bool buildOnly = mp3.ArchChrome.Visible && !mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUY);
                        var incomingBuy = mp3.SubPanel;
                        bool incomingBuyImmediate = incomingBuy != null && incomingBuy.Visible && incomingBuy.Opacity >= 0.999f;
                        // Simulate the midpoint writes of this panel's active
                        // tweens in their real insertion order. Merely setting
                        // Opacity=1 once would be undone by UISubpanel's queued
                        // constructor fade on the next update.
                        bool incomingBuyMidpoint = false;
                        var incomingTweenWrites = 0;
                        try
                        {
                            var tween = GameFacade.Screens.Tween;
                            var activeField = typeof(FSO.Client.UI.Framework.UITween).GetField("m_ActiveTweens",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            var objectField = typeof(FSO.Client.UI.Framework.UITweenInstance).GetField("m_Object",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            var active = activeField?.GetValue(tween) as System.Collections.IEnumerable;
                            if (activeField != null && objectField != null && active != null)
                                foreach (var raw in active.Cast<object>().ToList())
                                {
                                    var inst = raw as FSO.Client.UI.Framework.UITweenInstance;
                                    if (inst != null && object.ReferenceEquals(objectField?.GetValue(inst), incomingBuy))
                                    {
                                        inst.RenderPercent(0.5f);
                                        incomingTweenWrites++;
                                    }
                                }
                            // Constructor fade + the later constant-opacity
                            // hold must both be present and exercised.
                            incomingBuyMidpoint = incomingTweenWrites >= 2
                                && incomingBuy != null && incomingBuy.Opacity >= 0.999f;
                        }
                        catch { incomingBuyMidpoint = false; }
                        bool buyOnly = !mp3.ArchChrome.Visible && mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;

                        // R171 correction: desktop category replacement is
                        // atomic too. The original child-window switch never
                        // cross-fades two full panels; doing so was the visible
                        // duplicate Mood/Needs/Job composition in the user's
                        // live captures. The outgoing BUY panel must be hidden
                        // immediately and the incoming panel must be fully
                        // drawable from its first frame.
                        mp3.Switcher_OnCategorySelect(1);
                        bool atomicSameMode = mp3.SubPanel != null && !object.ReferenceEquals(mp3.SubPanel, incomingBuy)
                            && (incomingBuy == null || !incomingBuy.Visible)
                            && mp3.SubPanel.Visible && mp3.SubPanel.Opacity >= 0.999f;
                        var retiringBuy = mp3.SubPanel;
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        bool atomicBuyBuild = retiringBuy == null || !retiringBuy.Visible;
                        // Render the two manual-paint overrides while hidden.
                        // Both must emit exactly zero pixels; Visible booleans
                        // alone passed with the original stale-bar bug.
                        var oldPeopleVisible = mp3.PeopleChrome.Visible;
                        var oldArchVisible = mp3.ArchChrome.Visible;
                        var visiblePeoplePixels = -1;
                        var visibleArchPixels = -1;
                        var hiddenPeoplePixels = -1;
                        var hiddenArchPixels = -1;
                        try
                        {
                            mp3.PeopleChrome.Visible = true;
                            visiblePeoplePixels = RenderElementAlphaPixels(mp3.PeopleChrome);
                            mp3.ArchChrome.Visible = true;
                            visibleArchPixels = RenderElementAlphaPixels(mp3.ArchChrome);
                            mp3.PeopleChrome.Visible = false;
                            hiddenPeoplePixels = RenderElementAlphaPixels(mp3.PeopleChrome);
                            mp3.ArchChrome.Visible = false;
                            hiddenArchPixels = RenderElementAlphaPixels(mp3.ArchChrome);
                        }
                        finally
                        {
                            mp3.PeopleChrome.Visible = oldPeopleVisible;
                            mp3.ArchChrome.Visible = oldArchVisible;
                        }
                        bool hiddenDrawSilent = visiblePeoplePixels > 0 && visibleArchPixels > 0
                            && hiddenPeoplePixels == 0 && hiddenArchPixels == 0;
                        var visibleRetiringPanels = mp3.GetChildren()
                            .OfType<Simitone.Client.UI.Panels.LiveSubpanels.UISubpanel>()
                            .Count(panel => panel.Visible && !object.ReferenceEquals(panel, mp3.SubPanel));
                        bool noRetiringPanels = visibleRetiringPanels == 0;

                        bool modeComposition = atomicLiveBuild && atomicBuyBuild && buildOnly && buyOnly
                            && incomingBuyImmediate && incomingBuyMidpoint && atomicSameMode && hiddenDrawSilent && noRetiringPanels
                            && mp3.ArchChrome.Visible && !mp3.BuyChrome.Visible && !mp3.PeopleChrome.Visible;
                        if (!modeComposition)
                            liveInfo += "modecomp(liveRet=" + atomicLiveBuild + ",buyRet=" + atomicBuyBuild
                                + ",build=" + buildOnly + ",buy=" + buyOnly
                                + ",incoming=" + incomingBuyImmediate + "/" + incomingBuyMidpoint + " writes=" + incomingTweenWrites
                                + ",sameAtomic=" + atomicSameMode + ",drawPx=" + visiblePeoplePixels + "/" + visibleArchPixels
                                + "->" + hiddenPeoplePixels + "/" + hiddenArchPixels
                                + ",retiringVisible=" + visibleRetiringPanels + ");";
                        live = live && modeComposition;

                        // 12 tool buttons at the STATIC anchor table, 4-state
                        // cells (sheet/4), tooltips STR# 139 [0..11] in engine
                        // res-id order; undo (11,21) / redo (11,53) 30x24.
                        var ac = mp3.ArchChrome;
                        var ax = Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolAnchorX;
                        var ay = Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolAnchorY;
                        // Res_CPanel.RT + the cWinArch SetArea calls: every
                        // four-state sheet retains its authored cell size.
                        // Exact WxH pins catch both crushed strips and subtle
                        // one-pixel hit-area drift.
                        var toolW = new[] { 39, 25, 31, 32, 32, 29, 35, 43, 27, 29, 39, 30 };
                        var toolH = new[] { 39, 38, 40, 40, 38, 35, 39, 28, 41, 39, 33, 35 };
                        string diag = "";
                        for (int i = 0; i < 12 && live; i++)
                        {
                            var t = ac.Tools[i];
                            bool slot = t.Tooltip == e139[i]
                                && (int)t.Position.X == ax[i] && (int)t.Position.Y == ay[i]
                                && t.CellWidth == toolW[i]
                                && (int)t.Size.X == toolW[i] && (int)t.Size.Y == toolH[i]
                                && t.CellWidth * 4 == (Simitone.Client.UI.Model.UIOriginal.EnsureResolved(
                                    Simitone.Client.UI.Panels.UIOriginalArchChrome.ToolArt[i])?.Get(GameFacade.GraphicsDevice))?.Width;
                            if (!slot) diag = "t" + i + ":tip=" + t.Tooltip + "/e" + i + "=" + e139[i]
                                + " pos=" + (int)t.Position.X + "," + (int)t.Position.Y + "/" + ax[i] + "," + ay[i]
                                + " size=" + (int)t.Size.X + "x" + (int)t.Size.Y
                                + "/" + toolW[i] + "x" + toolH[i] + " cell=" + t.CellWidth;
                            live = live && slot;
                        }
                        if (ac.UndoBtn.CellWidth != 30 || (int)ac.UndoBtn.Position.X != 11 || (int)ac.UndoBtn.Position.Y != 21
                            || ac.UndoBtn.Tooltip != e139[12] || ac.RedoBtn.Tooltip != e139[13])
                        { live = false; diag += "chrome;"; }
                        if (diag.Length > 0) liveInfo += "tools(" + diag + ");";

                        // the TOOL CLICK path: Wall tool -> the browse band grid
                        // with that tool's own catalog category (wall styles)
                        mp3.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                        mp3.SelectBuildTool(2);   // Wall (engine tool order)
                        var bpc = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        bool grid = bpc != null && bpc.BandMode && bpc.BandCells.Count > 0
                            && (int)bpc.BandCells[0].Position.X == 338 && (int)bpc.BandCells[0].Position.Y == 5
                            && bpc.BandPageNext.Visible;
                        if (!grid) liveInfo += "grid(cells=" + (bpc != null ? bpc.BandCells.Count.ToString() : "?") + ");";
                        live = live && grid;

                        var wallCell = bpc?.BandCells.FirstOrDefault(cell =>
                            cell.Element?.Special?.Res is FSO.Client.UI.Controls.Catalog.UICatalogWallResProvider);
                        bool wallCellLaw = wallCell != null && wallCell.Icon != null
                            && wallCell.PairedProductIcon && wallCell.ProductIconStates == 2
                            && Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.ProductIconSource(
                                wallCell.Icon.Width, wallCell.Icon.Height, wallCell.PairedProductIcon, false)
                                == new Rectangle(0, 0, 37, 37);
                        if (!wallCellLaw) liveInfo += "wallState=" + (wallCell?.Icon != null
                            ? wallCell.Icon.Width + "x" + wallCell.Icon.Height + "/s" + wallCell.ProductIconStates
                            : "null") + ";";
                        live = live && wallCellLaw;

                        // Terrain tool -> four-state terrain members. The first
                        // authored state must be 36/39px wide, not the whole
                        // 144/156px strip squeezed into a 45px catalog cell.
                        mp3.SelectBuildTool(0);
                        var terrainPanel = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        var terrainCell = terrainPanel?.BandCells.FirstOrDefault(cell =>
                            cell.Element?.Special?.Res is Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalTerrainResProvider);
                        var terrainSource = terrainCell?.Icon != null
                            ? Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(
                                terrainCell.Icon.Width, terrainCell.Icon.Height, terrainCell.ProductIconStates, 0)
                            : Rectangle.Empty;
                        bool terrainCellLaw = terrainCell != null && terrainCell.NaturalIcon
                            && terrainCell.ProductIconStates == 4
                            && (terrainSource.Width == 36 || terrainSource.Width == 39)
                            && terrainSource.Height >= 32 && terrainSource.Height <= 34;
                        if (!terrainCellLaw) liveInfo += "terrainState=" + (terrainCell?.Icon != null
                            ? terrainCell.Icon.Width + "x" + terrainCell.Icon.Height + "/src" + terrainSource
                            : "null") + ";";
                        live = live && terrainCellLaw;

                        // Pool/pond sentinel floor ids retain their painter but
                        // display the original four-state 180x45 sheets and
                        // 145x103 popup art rather than isometric floor SPR2s.
                        mp3.SelectBuildTool(1);
                        var waterPanel = mp3.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                        var waterCells = waterPanel?.BandCells.Where(cell =>
                            cell.Element?.Special?.Res is Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider).ToList();
                        var sentinelIds = waterCells == null
                            ? new System.Collections.Generic.HashSet<ulong>()
                            : new System.Collections.Generic.HashSet<ulong>(waterCells.Select(cell => cell.Element.Special.ResID));
                        bool waterCellLaw = waterCells != null && waterCells.Count == 2
                            && sentinelIds.SetEquals(new ulong[] {
                                Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider.PoolID,
                                Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalPoolWaterResProvider.WaterID })
                            && waterCells.All(cell => cell.NaturalIcon && cell.ProductIconStates == 4
                                && cell.Icon != null && cell.Icon.Width == 180 && cell.Icon.Height == 45
                                && Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.IconStateSource(
                                    cell.Icon.Width, cell.Icon.Height, cell.ProductIconStates, 0)
                                    == new Rectangle(0, 0, 45, 45)
                                && cell.Element.Special.Res.GetThumb(cell.Element.Special.ResID)?.Width == 145
                                && cell.Element.Special.Res.GetThumb(cell.Element.Special.ResID)?.Height == 103);
                        if (!waterCellLaw) liveInfo += "poolWater=" + (waterCells != null
                            ? waterCells.Count + "/ids=" + string.Join(",", sentinelIds)
                            : "null") + ";";
                        live = live && waterCellLaw;

                        // roof tool -> the engine roof panel (pattern row hidden)
                        mp3.SelectBuildTool(10);
                        var roofPanel = mp3.ArchChrome.RoofPanel;
                        var currentWidth = screen.ScreenWidth;
                        var perPage = Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(currentWidth);
                        bool roofStaticLaw =
                            Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(800) == 8
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternsPerPageForScreenWidth(1024) == 16
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(800) == 253
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(1024) == 433
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(0, 800) == new Vector2(70, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(3, 800) == new Vector2(205, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(4, 800) == new Vector2(70, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(7, 800) == new Vector2(205, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(0, 1024) == new Vector2(70, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(7, 1024) == new Vector2(385, 1)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(8, 1024) == new Vector2(70, 46)
                            && Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(15, 1024) == new Vector2(385, 46);
                        bool roofPositions = roofPanel.Patterns
                            .Select((pattern, i) => new { pattern, i })
                            .All(x => x.pattern.Visible == (x.i < perPage)
                                && (!x.pattern.Visible || x.pattern.Position ==
                                    Simitone.Client.UI.Panels.UIOriginalRoofPanel.PatternPositionForSlot(x.i, currentWidth)));
                        int roofStyle = (int)roofPanel.Game.vm.Context.Architecture.RoofStyle;
                        bool roofSelection = roofPanel.Patterns
                            .Select((pattern, i) => new { pattern, i })
                            .All(x => x.pattern.Selected == (x.i == roofStyle));
                        bool roof = roofPanel.Visible
                            && roofPanel.PitchBtns[0].CellWidth == 26   // 104x23/4 steep
                            && (int)roofPanel.PitchBtns[2].Position.Y == 50
                            && (int)roofPanel.PageNext.X ==
                                Simitone.Client.UI.Panels.UIOriginalRoofPanel.NextPageXForScreenWidth(currentWidth)
                            && roofStaticLaw && roofPositions && roofSelection
                            && mp3.SubPanel == null;
                        if (!roof) liveInfo += "roof(w=" + currentWidth + ",per=" + perPage
                            + ",next=" + (int)roofPanel.PageNext.X + ",static=" + roofStaticLaw
                            + ",positions=" + roofPositions + ",selection=" + roofSelection + ");";
                        live = live && roof;
                    }
                    catch (Exception be) { live = false; liveInfo += "EXC(" + be.GetType().Name + ");"; }
                }

                Log("AUTOTEST uibuild original build catalog: canon=" + canon + " (BldTips/16 " + canonInfo + ")"
                    + " art=" + art + " (" + R126BuildArt.Length + " pins) stateLaw=" + stateLaw + " live=" + live
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (canon && art && stateLaw && live) { Pass("uibuild"); return; }
                Log("AUTOTEST uibuild: STR# 139 must pin verbatim, all 11 tool plaques must mount byte-identical, and the live BUILD rows must carry the canon captions and plaque dims");
                Fail("uibuild");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uibuild EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uibuild");
            }
        }


