                    catch (Exception le) { liveInfo += "EXC(" + le.GetType().Name + " " + le.Message + ");"; }
                }

                Log("AUTOTEST uiinterest interest/gift panels: canon=" + canon + " art=" + art + " (" + R145InterestArt.Length + " pins) live=" + live
                    + (canonInfo.Length > 0 ? " canonFails=" + canonInfo : "")
                    + (artInfo.Length > 0 ? " artFails=" + artInfo : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo : ""));
                if (canon && art && live) { Pass("uiinterest"); return; }
                Log("AUTOTEST uiinterest: Live.iff STR# 140/141/142 + the 24 interest/gift art members must pin verbatim, and the band panels must mount on the engine law (grid/fill/paging/filters)");
                Fail("uiinterest");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uiinterest EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : ""));
                Fail("uiinterest");
            }
        }

        // ROUND-127 'uibldt': the BUILD-mode terrain tool ITEM cells in the
        // ORIGINAL composition. (1) The 8 mounted members (4 kBldSbTl* cell
        // plaques + 4 kBldPopup* thumbs, res_cpanel.RT verbatim) pin
        // name+len+dims+sha in the live FAR mount — they replace the TSO-only
        // UIFileIDs provider, whose IDs cannot resolve on TS1 data (the cells
        // rendered blank 1x1) and which mounted a wrong-asset placeholder for
        // Grass; (2) LIVE through the REAL InitCategory(18, build:true) flow:
        // FOUR tools in RT popup order (Up 3600, Down 3601, Level 3602, Hot
        // Date Grass 3607) — the port's combined raise/lower tool is split
        // back into the original Up/Down pair (UITerrainRaiser
        // parameters[0]==1 = lower mode) — each with the canon provider,
        // icon dims == the pinned plaque dims, and thumb dims 145x103.
        // Names stay port-authored (r127 scan: UIText.iff carries NO
        // tool-name strings; the plaques are pictorial — disclosed).
        private static void CheckBuildTools()
        {
            try
            {
                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uibldt: no TS1Global"); Fail("uibldt"); return; }
                var sha = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R127TerrainArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- live terrain tool set (InitCategory(18, true) -> AddTerrainTools) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var bp = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(
                            screen, 1, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Build, false);
                        bp.InitCategory(18, true);
                        var cats = bp.FullCategory;
                        bool ok = cats.Count == 4;
                        string diag = "count=" + cats.Count;
                        // order: Raise(0, plain) / Lower(3, lower-mode param) / Flatten(1) / Grass(2)
                        var expectControls = new Type[] {
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainRaiser),
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainRaiser),
                            typeof(FSO.Client.UI.Panels.LotControls.UITerrainFlatten),
                            typeof(FSO.Client.UI.Panels.LotControls.UIGrassPaint) };
                        var expectResID = new int[] { 0, 3, 1, 2 };
                        var expectIconW = new int[] { 144, 144, 156, 144 };
                        var expectIconH = new int[] { 33, 34, 33, 32 };
                        for (int i = 0; i < 4 && ok; i++)
                        {
                            var el = cats[i];
                            var sp = el.Special;
                            var prov = sp?.Res as Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalTerrainResProvider;
                            if (sp == null || prov == null) { ok = false; diag = "i" + i + ":no-canon-provider"; break; }
                            var icon = prov.GetIcon((ulong)expectResID[i]);
                            var thumb = prov.GetThumb((ulong)expectResID[i]);
                            bool lowerParam = (i == 1);
                            bool paramOK = lowerParam
                                ? (sp.Parameters != null && sp.Parameters.Count == 1 && sp.Parameters[0] == 1)
                                : (sp.Parameters == null || sp.Parameters.Count == 0);
                            bool slot = sp.Control == expectControls[i]
                                && (int)sp.ResID == expectResID[i]
                                && paramOK
                                && icon != null && icon.Width == expectIconW[i] && icon.Height == expectIconH[i]
                                && thumb != null && thumb.Width == 145 && thumb.Height == 103;
                            if (!slot) diag = "i" + i + ":ctl=" + (sp.Control != null ? sp.Control.Name : "?")
                                + " resID=" + sp.ResID + " param=" + (sp.Parameters != null ? sp.Parameters.Count.ToString() : "null")
                                + " icon=" + (icon != null ? icon.Width + "x" + icon.Height : "null")
                                + " thumb=" + (thumb != null ? thumb.Width + "x" + thumb.Height : "null");
                            ok = ok && slot;
                        }
                        if (!ok) liveInfo += "tools(" + diag + ");";
                        live = ok;
                        bp.Kill();
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                // R216: the TS1 floor bounds law, both layers — the TOOL clips
                // (cNewFloorTool::TileIsFloorable @0x17a6f0's rim rejection,
                // ported as ClipFloorRectToFloorable and applied in
                // UIFloorPainter before the command exists) while the
                // PRIMITIVE stays unrestricted (the terrain restore writes
                // full-lot strips through FloorPatternRect). The probe drives
                // the real preview path (SimulateCommands against VisFloors).
                bool floorRim = false;
                try
                {
                    var gsc = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                    var arch = gsc != null && gsc.vm != null ? gsc.vm.Context.Architecture : null;
                    if (arch != null && arch.Width > 4 && arch.Height > 4)
                    {
                        string rimDiag;
                        floorRim = FloorRimLawProbe(arch, out rimDiag);
                        if (!floorRim) liveInfo += "floorRim(" + rimDiag + ");";
                    }
                }
                catch (Exception fe) { liveInfo += "floorRimEXC(" + fe.GetType().Name + ");"; }

                Log("AUTOTEST uibldt original terrain tools: art=" + art + " (" + R127TerrainArt.Length + " pins) live=" + live
                    + " floorRim=" + floorRim
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (art && live && floorRim) { Pass("uibldt"); return; }
                Log("AUTOTEST uibldt: all 8 terrain tool members must mount byte-identical, the live terrain category must be the 4 original tools (raise/lower split) on canon plaque+popup art, and the floor tool must clip the 1-tile unfloorable rim while the primitive stays unrestricted");
                Fail("uibldt");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uibldt EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uibldt");
            }
        }

        // R216: the floor rim law on the LIVE lot architecture, BOTH layers.
        // (a) TOOL layer — ClipFloorRectToFloorable (the port of
        // cNewFloorTool::TileIsFloorable @0x17a6f0's rim rejection, applied in
        // UIFloorPainter BEFORE the command exists) must clip a whole-lot drag
        // to exactly the 1-tile inset. (b) PRIMITIVE layer — FloorPatternRect
        // itself is UNRESTRICTED in TS1 (the engine checks in the tool; the
        // terrain restore writes full-lot strips through the primitive), so an
        // UNclipped whole-lot rect must paint the rim too. SimulateCommands
        // writes VisFloors only; restored by re-simulating an empty list.
        private static bool FloorRimLawProbe(FSO.SimAntics.VMArchitecture arch, out string diag)
        {
            diag = "";
            var w = arch.Width; var h = arch.Height;
            var probe = arch.GetFloor(0, 0, 1).Pattern;
            // RunCommands drops floor commands whose pattern has no catalog
            // entry — the sentinel must be a REAL floor style id.
            ushort sentinel = 0;
            try
            {
                foreach (var kv in FSO.Content.Content.Get().WorldFloors.Entries)
                    if (kv.Value != null && kv.Key != probe) { sentinel = (ushort)kv.Key; break; }
            }
            catch { }
            if (sentinel == 0) { diag = "noFloorStyle"; return false; }

            // (a) the tool clip: whole-lot drag (0,0)..(w-1,h-1) -> the inset.
            var whole = new Microsoft.Xna.Framework.Rectangle(0, 0, w - 1, h - 1);
            var clipped = FSO.SimAntics.Utils.VMArchitectureTools.ClipFloorRectToFloorable(arch, whole);
            bool clipLaw = clipped != null
                && clipped.Value.X == 1 && clipped.Value.Y == 1
                && clipped.Value.Width == w - 3 && clipped.Value.Height == h - 3;
            if (!clipLaw) diag += "clip=" + (clipped == null ? "null" : clipped.Value.ToString()) + ";";

            // (b) the primitive: an UNCLIPPED whole-lot rect paints the rim.
            arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>
            {
                new FSO.SimAntics.Model.VMArchitectureCommand
                {
                    Type = FSO.SimAntics.Model.VMArchitectureCommandType.FLOOR_RECT,
                    level = 1, pattern = sentinel, style = 0,
                    x = 0, y = 0, x2 = w - 1, y2 = h - 1
                }
            }, true);
            bool primitiveFree;
            try
            {
                primitiveFree = arch.VisFloors[0][arch.GetOffset(0, 0)].Pattern == sentinel
                    && arch.VisFloors[0][arch.GetOffset(w - 1, h - 1)].Pattern == sentinel;
                if (!primitiveFree) diag += "primRimStale;";
            }
            finally
            {
                arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>(), true);
            }

            // (c) the TOOL-clipped rect through the same preview path: the rim
            // stays untouched, the interior takes the pattern.
            bool clippedPaint = false;
            if (clipped != null)
            {
                arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>
                {
                    new FSO.SimAntics.Model.VMArchitectureCommand
                    {
                        Type = FSO.SimAntics.Model.VMArchitectureCommandType.FLOOR_RECT,
                        level = 1, pattern = sentinel, style = 0,
                        x = clipped.Value.X, y = clipped.Value.Y,
                        x2 = clipped.Value.Width, y2 = clipped.Value.Height
                    }
                }, true);
                try
                {
                    ushort rim00 = arch.VisFloors[0][arch.GetOffset(0, 0)].Pattern;            // corner of the outer ring
                    ushort rimEdge = arch.VisFloors[0][arch.GetOffset(w - 1, h - 1)].Pattern;
                    ushort interior = arch.VisFloors[0][arch.GetOffset(1, 1)].Pattern;         // first floorable tile
                    clippedPaint = rim00 != sentinel && rimEdge != sentinel && interior == sentinel;
                    if (!clippedPaint) diag += w + "x" + h + " sent=" + sentinel.ToString("X")
                        + " rim00=" + rim00.ToString("X") + " rimEdge=" + rimEdge.ToString("X")
                        + " i11=" + interior.ToString("X") + ";";
                }
                finally
                {
                    arch.SimulateCommands(new System.Collections.Generic.List<FSO.SimAntics.Model.VMArchitectureCommand>(), true);
                }
            }
            return clipLaw && primitiveFree && clippedPaint;
        }

        // ROUND-130 'uiroof': the ORIGINAL build-mode roof panel. (1) STR# 147
        // 'roofpanelstrs' pins byte-verbatim (label, full-chunk sha incl. the
        // 76-byte header, all 18 English entries — the 4 pitch names
        // [5]/[3]/[1]/[12], the layout directives, pager captions, page
        // titles and the two lore texts; script-generated pins); (2) the 7
        // roof art members pin name+len+dims+sha through the live FAR mount
        // (kRoofPatternTemplate 180x45 4-frame sheet, the 4 kBldSbTlRoof*
        // plaques, both kBldPopup* thumbs); (3) LIVE through the REAL
        // InitCategory(17, true) flow: exactly 4 + WorldRoofs.Count items —
        // the pitch sub-tools lead in the engine panel's display order
        // (Steep, Medium, Shallow, Flat) on UIRoofPitcher with RT ids
        // 3902/3901/3900/3904, natural-size plaques 104x23/104x17/104x16/
        // 100x16, the shared 133x103 popup thumb, STR# 147 names, and the
        // engine-mapped FSO pitches (0.99/0.66/0.495/0.0 — the engine's
        // exact slope ratios 1 : 4/3 : 2 with medium anchored at the port
        // default, disclosed); the pattern swatches follow on UIRoofer with
        // 32x32 icons and 145x103 popups, composed inside the roof's own
        // 45x45 RoofPatternTemplate frames.
        // ROUND-131 'uigauge' — the ORIGINAL live-tab MOOD GAUGE (engine id
        // kLiveModeGauge 4911, cWinPeople::Init 0x28eee0 + TSPaint decode):
        // the gate pins STR# 154 'MiscStrings' (ratings family + full-chunk
        // sha), the 9 live/pager/level art members byte-verbatim, and the LIVE
        // gauge control — art mounted at engine dims, the caption pinned to
        // [15] 'Mood Rating', the engine fill mapping verified through the
        // eased value: height = min(|mood|,100)/4 px (25 px = full 27x25 bar
        // art height), polarity green >= 0 / red < 0 (kGreenbars/kRedBars).
        // ROUND-132 'uirate': the People-panel RATINGS family. (1) The 9 art pins
        // (pie strips + subpanel sheets + Off backdrops) must match UIGraphics.far
        // byte-verbatim. (2) The decoded engine fill law — clamp [0,100] then
        // 4*(value/10) px, integer division (cWinSubpanelHouse::TSPaint
        // 0x2a0458-0x2a06a0) — must hold as pure math. (3) The original House tab
        // (new port surface: kHouseBtn 4502) mounts with the STR#154 [12]/[13]
        // captions on 40x16 HouseSubBars art. (4) The Job tab's original Job
        // Rating bar ([14] caption, 40x11 JobSubBars art) tracks JobPerformance.
        // (5) The follow-Sim crosshair toggle mounts on the motive subpanel with
        // the pinned 45x45 kTrackingTarget art and null-safe ScrollAnchor toggling.
        // Residuals (disclosed): the HouseStats score COMPUTATION (0x8bba8-0x8c174
        // getters) is undecoded — the House Rating bar mounts at 0 and Friend
        // Rating uses FamilyFriends clamped to [0,100] as a port-side proxy.
        // ROUND-133 'uihouse': the House tab on the original's own terms.
        // (1) Live.iff STR# 133/135/138 disk-pin byte-verbatim (full-chunk shas +
        // entries — the corpus that CORRECTS the R132 'House Rating' reading).
        // (2) The DECODED lot-size ladder as pure math. (3) LIVE: the subpanel's
        // captions equal the disk canon (header, five score labels, the four
        // formatted value lines with real computed numbers) and the lot word is
        // 138[ladder(lot width)]; the square-feet figure cross-checks against an
        // independent recount of the enclosed room areas. Score bar VALUES stay 0
        // — the engine's score constants are TOC-relocated (disclosed residual).
        private static void CheckHouse()
        {
            try
            {
                // ---- STR# 133/135/138 canon from Live.iff ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/Live.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-live;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var raw133 = FindStrChunkByID(d, 133, out id, out n, out lbl, out body);
                    string lbl133 = lbl;
                    var e133 = (raw133 != null) ? ParseLang1(body, out n) : null;
                    var raw135 = FindStrChunkByID(d, 135, out id, out n, out lbl, out body);
                    string lbl135 = lbl;
                    var e135 = (raw135 != null) ? ParseLang1(body, out n) : null;
                    var raw138 = FindStrChunkByID(d, 138, out id, out n, out lbl, out body);
                    string lbl138 = lbl;
                    var e138 = (raw138 != null) ? ParseLang1(body, out n) : null;
                    strOK = raw133 != null && raw135 != null && raw138 != null
                        && lbl133 == "HouseSubpanelLabels" && lbl135 == "HouseSubpanelPopupText"
                        && lbl138 == "HouseSubpanelSize"
                        && e133 != null && e135 != null && e138 != null
                        && e133.Count == 10 && e135.Count == 18 && e138.Count == 3;
                    if (strOK)
                    {
                        if (ByteHash256(raw133, sha) != R133H133Sha
                            || ByteHash256(raw135, sha) != R133H135Sha
                            || ByteHash256(raw138, sha) != R133H138Sha) { strOK = false; strInfo = "sha;"; }
                    }
                    else if (strInfo == "") strInfo = "chunks;";
                    for (int i = 0; i < 10 && strOK; i++)
                        if (e133[i] != R133H133[i]) { strOK = false; strInfo = "e133[" + i + "];"; }
                    for (int i = 0; i < 9 && strOK; i++)
                        if (e135[i * 2] != R133H135Titles[i]) { strOK = false; strInfo = "e135[" + (i * 2) + "];"; }
                    for (int i = 0; i < 3 && strOK; i++)
                        if (e138[i] != R133H138[i]) { strOK = false; strInfo = "e138[" + i + "];"; }
                }

                // ---- the decoded lot-size ladder (pure math) ----
                var cls = Simitone.Client.UI.Model.OriginalHouseStats.ComputeLotSize;
                bool math = cls(0) == 0 && cls(39) == 0 && cls(40) == 1 && cls(49) == 1
                    && cls(50) == 2 && cls(63) == 2;

                // R186: House::GetSizeScore's exact PiecewiseFn, loaded from
                // Global.iff STR# 505 'HouseScoreCurves'. Pin every knot, the
                // native zero-member guard, interpolation/truncation, and both
                // endpoint clamps. Inputs are square feet / family members.
                var size = Simitone.Client.UI.Model.OriginalHouseStats.ComputeSizeScore;
                bool sizeLaw = size(900, 0) == 0
                    && size(-1, 1) == 0
                    && size(0, 1) == 0
                    && size(150, 1) == 25
                    && size(300, 1) == 50
                    && size(600, 1) == 75
                    && size(1200, 1) == 100
                    && size(2400, 1) == 100
                    && size(449, 1) == 62
                    && size(900, 2) == 62;
                math = math && sizeLaw;

                // R186 follow-up: ObjectModule+0xa4 / +0xa0 through the
                // second STR# 505 curve. A zero movable-value denominator
                // substitutes x=100 (therefore clamps to score 0). Pin every
                // knot, every interpolation segment, and both clamps.
                var furnishings = Simitone.Client.UI.Model.OriginalHouseStats.ComputeFurnishingsScore;
                bool furnishingsLaw = furnishings(0, 0) == 0
                    && furnishings(100, -1) == 100
                    && furnishings(100, 0) == 100
                    && furnishings(100, 50) == 80
                    && furnishings(100, 100) == 60
                    && furnishings(100, 150) == 47
                    && furnishings(100, 200) == 35
                    && furnishings(100, 250) == 27
                    && furnishings(100, 300) == 20
                    && furnishings(100, 350) == 15
                    && furnishings(100, 400) == 10
                    && furnishings(100, 450) == 5
                    && furnishings(100, 500) == 0
                    && furnishings(100, 10000) == 0
                    // Native rounds each integer to float before fdivs; a
                    // double-first quotient incorrectly returns 20 here.
                    && furnishings(16000274, 48000822) == 19;
                // cFixedWorld::ComputeArchValue keeps one full-price wall
                // structure accumulator, then halves the TOTAL once.  The
                // distinction is visible with the owned Build.iff's odd-price
                // styles: two 45-value segments yield 45, not 22 + 22.
                var combineArch = FSO.SimAntics.Utils.VMArchitectureStats.CombineArchitectureValue;
                bool architectureValueLaw = combineArch(100, 0) == 100
                    && combineArch(100, 45) == 122
                    && combineArch(100, 90) == 145
                    && combineArch(100, -45) == 78;
                math = math && furnishingsLaw && architectureValueLaw;

                // R186 follow-up: the exact outside Room score and Yard getter.
                // Negative impacts are doubled, nonnegative objects contribute
                // one each, and the accumulated room operand is multiplied by
                // native single-precision 0.33, clamped, then truncated.
                var outdoor = Simitone.Client.UI.Model.OriginalHouseStats.ComputeOutdoorRoomScore;
                var yard = Simitone.Client.UI.Model.OriginalHouseStats.ComputeYardScore;
                bool yardLaw = outdoor(0, 0) == 0f
                    && outdoor(10, 0) == 10f
                    && outdoor(10, -3) == 4f
                    && yard(-100f) == 0
                    && yard(0f) == 0
                    && yard(3f) == 0
                    && yard(4f) == 1
                    && yard(100f) == 33
                    && yard(304f) == 100
                    && yard(10000f) == 100;
                math = math && yardLaw;

                // ---- R136: the route-history Layout law (pure math over
                // synthetic feeds) — (int)(100.0*clamp(1f-2f*flagged/
                // max(1,total),0,1)); the engine seed N0 is BSS-proven
                // unrecoverable, the total normalization is disclosed ----
                Simitone.Client.UI.Model.OriginalRouteHistory.Clear();
                bool lawFresh = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;            // fresh house -> 100
                Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples = 10; Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 0;
                bool lawSmooth = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;           // all-smooth movement
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 2;
                bool lawMix = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 60;               // 100*(1-2*2/10)
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 5;
                bool lawHalf = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 0;               // 2*flagged==total
                Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 8;
                bool lawClamp = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 0;              // clamped at 0
                Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples = 0; Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples = 0;
                bool lawGuard = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100;            // max(total,1) guard
                Simitone.Client.UI.Model.OriginalRouteHistory.Clear();
                bool lawReset = Simitone.Client.UI.Model.OriginalRouteHistory.LayoutScore == 100 && Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples == 0;
                math = math && lawFresh && lawSmooth && lawMix && lawHalf
                    && lawClamp && lawGuard && lawReset;

                // ---- live subpanel ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var hs = new Simitone.Client.UI.Panels.LiveSubpanels.UIHouseSubpanel(screen);
                        hs.RecomputeStats();
                        bool ok = true; string diag = "";
                        if (hs.Header == null || hs.Header.Caption != R133H133[0]
                            || hs.SqFtLine == null || hs.BedLine == null || hs.BathLine == null || hs.LotLine == null)
                        { ok = false; diag += "labels;"; }
                        else
                        {
                            int[] scoreLabelY = { 7, 25, 43, 61, 79 };
                            for (int i = 0; i < 5; i++)
                            {
                                var scoreButton = hs.ScoreButtons[i];
                                int captionWidth = scoreButton?.Label?.Font?.Measure(R133H133[1 + i]) ?? -1;
                                if (hs.ScoreLabels[i] == null || hs.ScoreLabels[i].Caption != R133H133[1 + i]
                                    || hs.ScoreBars[i] == null || hs.ScoreBars[i].BarsTex == null
                                    || hs.ScoreBars[i].BarsTex.Width != 40 || hs.ScoreBars[i].BarsTex.Height != 16
                                    // R185: only the measured caption is a hit
                                    // window; all five share the x=154 right edge.
                                    || scoreButton == null || captionWidth <= 0
                                    || !HasTooltipHook(scoreButton)
                                    || scoreButton.Tooltip != R133H135Titles[i]
                                    || (int)scoreButton.Size.X != captionWidth
                                    || (int)scoreButton.X != 154 - captionWidth
                                    || (int)scoreButton.Y != scoreLabelY[i])
                                { ok = false; diag += "score" + i + ";"; }
                            }
                            for (int i = 0; i < 4; i++)
                            {
                                var factButton = hs.FactButtons[i];
                                if (factButton == null || !HasTooltipHook(factButton)
                                    || factButton.Tooltip != R133H135Titles[5 + i])
                                { ok = false; diag += "fact-tip" + i + ";"; }
                            }
                            bool houseColors = Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.NormalColor
                                    == new Microsoft.Xna.Framework.Color(0xC3, 0xCD, 0xCD, 0xFF)
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.SelectedColor
                                    == new Microsoft.Xna.Framework.Color(0x00, 0xFF, 0xFF, 0xFF)
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.HoverColor
                                    == Microsoft.Xna.Framework.Color.White
                                && Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalHouseTextButton.DisabledColor
                                    == new Microsoft.Xna.Framework.Color(0x40, 0x5D, 0x5F, 0xFF);
                            if (!houseColors) { ok = false; diag += "button-colors;"; }

                            // All nine native House items retarget one live
                            // popup. A second item must not allocate another
                            // chrome window or retain the first item's text.
                            hs.SelectItem(0);
                            var housePopup = hs.CurrentPopup;
                            hs.SelectItem(1);
                            if (housePopup == null || !object.ReferenceEquals(housePopup, hs.CurrentPopup)
                                || hs.PopupItem != 1 || hs.SelectedItem != 1
                                || hs.CurrentPopup.Title != R133H135Titles[1]
                                || hs.CurrentPopup.Body != Simitone.Client.UI.Model.OriginalLiveStrings.Entry(135, 3)
                                // Init @0x2a1390-0x2a13bc supplies no bitmap
                                // or selector arguments: House is full-width
                                // text, not an empty 168px picture pane.
                                || hs.CurrentPopup.UsesArtPane || hs.CurrentPopup.SplitArtPanes
                                || hs.CurrentPopup.Art != null || hs.CurrentPopup.Art2 != null
                                || hs.CurrentPopup.ObjectGuids.Any(x => x != 0)
                                || (int)hs.CurrentPopup.TitleText.X != 15
                                || (int)hs.CurrentPopup.TitleText.Size.X != 530
                                || (int)hs.CurrentPopup.BodyParagraph.X != 15
                                || hs.CurrentPopup.BodyParagraph.MaxWidth != 530
                                || (int)(hs.CurrentPopup.X + hs.CurrentPopup.Size.X) != (int)hs.Size.X
                                || (int)(hs.CurrentPopup.Y + hs.CurrentPopup.Size.Y) != 0)
                            { ok = false; diag += "shared-popup;"; }
                            // the four value lines: real computed numbers in the canon formats
                            var st = hs.Stats;
                            string wantSqft = R133H133[6].Replace("%d", st.SquareFeet.ToString());
                            string wantBed = R133H133[7].Replace("%d", st.Bedrooms.ToString());
                            string wantBath = R133H133[8].Replace("%d", st.Bathrooms.ToString());
                            string wantLot = R133H133[9].Replace("%s", R133H138[st.LotSizeIndex]);
                            if (hs.SqFtLine.Caption != wantSqft) { ok = false; diag += "sqft='" + hs.SqFtLine.Caption + "';"; }
                            if (hs.BedLine.Caption != wantBed) { ok = false; diag += "bed;"; }
                            if (hs.BathLine.Caption != wantBath) { ok = false; diag += "bath;"; }
                            if (hs.LotLine.Caption != wantLot) { ok = false; diag += "lot='" + hs.LotLine.Caption + "';"; }
                            // cross-check against an independent compute + the room map
                            var again = Simitone.Client.UI.Model.OriginalHouseStats.Compute(screen.vm);
                            if (again.SquareFeet != st.SquareFeet || again.Bedrooms != st.Bedrooms
                                || again.Bathrooms != st.Bathrooms || again.LotSizeIndex != st.LotSizeIndex)
                            { ok = false; diag += "recompute;"; }
                            // R134: the FillInObjectStats aggregates — the value split
                            // (indoor+outdoor = total of priced objects, counted the
                            // same deduped way) and the upkeep condition invariant
                            // (working + broken == the deduped object count).
                            if (st.WorkingObjects + st.BrokenObjects != st.ObjectCount)
                            { ok = false; diag += "upkeep=" + st.WorkingObjects + "+" + st.BrokenObjects
                                + "!=" + st.ObjectCount + ";"; }
                            if (st.FurnishingsValue < 0 || st.YardValue < 0)
                            { ok = false; diag += "values;"; }
                            if (again.FurnishingsValue != st.FurnishingsValue || again.YardValue != st.YardValue
                                || again.BrokenObjects != st.BrokenObjects || again.HasPool != st.HasPool
                                || again.FurnishingsObjectValue != st.FurnishingsObjectValue
                                || again.FurnishingsFixedValue != st.FurnishingsFixedValue
                                || again.YardGoodObjects != st.YardGoodObjects
                                || again.YardNegativeImpact != st.YardNegativeImpact
                                || again.YardRoomScore != st.YardRoomScore)
                            { ok = false; diag += "agg-recompute;"; }
                            // R135: the Upkeep bar is LIVE on the decoded law
                            // (int(100*clamp(dividend/2^31,0,1)), r=0 normalization
                            // disclosed) — must equal the independent compute and be
                            // full when nothing is broken.
                            if (hs.ScoreBars[3].Value != st.UpkeepScore)
                            { ok = false; diag += "upkeep-bar=" + hs.ScoreBars[3].Value + "/" + st.UpkeepScore + ";"; }
                            if (st.BrokenObjects == 0 && st.ObjectCount > 0 && st.UpkeepScore != 100)
                            { ok = false; diag += "upkeep-full;"; }
                            // R186: the first bar is no longer a placeholder;
                            // it must use the independently pinned native size
                            // curve over the persistent active-family count.
                            int expSize = size(st.SquareFeet, st.FamilyMemberCount);
                            if (hs.ScoreBars[0].Value != expSize || st.SizeScore != expSize)
                            { ok = false; diag += "size-bar=" + hs.ScoreBars[0].Value + "/" + expSize + ";"; }
                            // R186: furnishings uses the exact SIMI value split:
                            // movable objects in the denominator and fixed
                            // build-mode objects + architecture in the numerator.
                            var valueSplit = FSO.SimAntics.Utils.VMArchitectureStats.GetObjectValue(screen.vm);
                            int expFixed = valueSplit.Item2
                                + FSO.SimAntics.Utils.VMArchitectureStats.GetArchValue(screen.vm.Context.Architecture);
                            int expFurnishings = furnishings(valueSplit.Item1, expFixed);
                            if (st.FurnishingsObjectValue != valueSplit.Item1
                                || st.FurnishingsFixedValue != expFixed)
                            { ok = false; diag += "furn-inputs=" + st.FurnishingsObjectValue + "/"
                                + st.FurnishingsFixedValue + "!=" + valueSplit.Item1 + "/" + expFixed + ";"; }
                            if (hs.ScoreBars[1].Value != expFurnishings || st.FurnishingsScore != expFurnishings)
                            { ok = false; diag += "furn-bar=" + hs.ScoreBars[1].Value + "/" + expFurnishings + ";"; }
                            // R186 follow-up: Yard is also no longer a
                            // placeholder. Cross-check the live bar against the
                            // independently pinned getter and raw room operand.
                            int expYard = yard(st.YardRoomScore);
                            if (hs.ScoreBars[2].Value != expYard || st.YardScore != expYard)
                            { ok = false; diag += "yard-bar=" + hs.ScoreBars[2].Value + "/" + expYard + ";"; }
                            if (st.YardGoodObjects < 0 || st.YardNegativeImpact > 0)
                            { ok = false; diag += "yard-inputs=" + st.YardGoodObjects + "/" + st.YardNegativeImpact + ";"; }
                            // R136: the Layout bar is LIVE on the route-history
                            // law — must equal the independent recompute of the
                            // decoded formula from the raw counters and stay in
                            // the engine's [0,100] range.
                            Simitone.Client.UI.Model.OriginalRouteHistory.Sample(screen.vm);
                            hs.RecomputeStats();
                            int expTot = System.Math.Max(1, Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples);
                            float expRatio = 1f - (2f * Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples) / expTot;
                            if (expRatio < 0f) expRatio = 0f;
                            if (expRatio > 1f) expRatio = 1f;
                            int expLayout = (int)(100.0 * expRatio);
                            if (hs.ScoreBars[4].Value != hs.Stats.LayoutScore)
                            { ok = false; diag += "layout-bar=" + hs.ScoreBars[4].Value + "/" + hs.Stats.LayoutScore + ";"; }
                            if (hs.Stats.LayoutScore != expLayout)
                            { ok = false; diag += "layout-law=" + hs.Stats.LayoutScore + "/" + expLayout + ";"; }
                            if (hs.Stats.LayoutScore < 0 || hs.Stats.LayoutScore > 100)
                            { ok = false; diag += "layout-range=" + hs.Stats.LayoutScore + ";"; }
                            // R137 re-pins for the corrected flag channel
                            // (flag = holds-a-route, decoded cXPerson::Simulate
                            // 0x10bff0): flagged can never exceed total, and a
                            // second Sample in the same frame (no VM clock
                            // advance = no Simulate) must add nothing.
                            if (Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples
                                > Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples)
                            { ok = false; diag += "layout-flag-subset;"; }
                            int t0 = Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples;
                            int f0 = Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples;
                            Simitone.Client.UI.Model.OriginalRouteHistory.Sample(screen.vm);
                            if (Simitone.Client.UI.Model.OriginalRouteHistory.TotalSamples != t0
                                || Simitone.Client.UI.Model.OriginalRouteHistory.FlaggedSamples != f0)
                            { ok = false; diag += "layout-pause-gate;"; }
                            var arch = screen.vm != null && screen.vm.Context != null ? screen.vm.Context.Architecture : null;
                            if (arch == null || arch.RoomData == null || arch.RoomData.Count == 0)
                            { ok = false; diag += "no-roommap;"; }
                            else if (st.LotSizeIndex != cls(arch.Width))
                            { ok = false; diag += "ladder;"; }
                        }
                        hs.Kill();
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uihouse original house tab: str=" + strOK + " math=" + math + " live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && math && live) { Pass("uihouse"); return; }
                Log("AUTOTEST uihouse: STR# 133/135/138, the decoded lot ladder, and the live-computed stat lines must all match the original");
                Fail("uihouse");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uihouse EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uihouse");
            }
        }

        // ROUND-137 'uivalue': the LIVE house value. (1) The value-display
        // corpus pins byte-verbatim: UIText.iff STR# 146 'budgetstrs' (the
        // budget window's [30] 'Household Account Total: %s', [34]
        // 'Household Net Worth: %s' + [35] tooltip), STR# 134 'NghRollover'
        // ([0] the neighborhood net-worth rollover) and STR# 131
        // 'EvictModeStrs' ([3] the evict payout wording) — full-chunk shas
        // + entries (generated pins). (2) LIVE: the ORIGINAL recomputes the
        // architecture value whenever the house changes
        // (cFixedWorld::ComputeArchValue 0x15ea70 — wallpaper full,
        // flooring + wall structure HALF value, roof tiles at the
        // [TOC-28568] = 100 file constant); the port's GetArchValue now
        // implements that law and TS1GameScreen refreshes FAMI.ValueInArch
        // on WallsChanged + periodically + at save. The gate asserts the
        // family value equals an independent fresh recompute, is positive
        // on a built lot, and the SIMI snapshot mirrors it.
        private static void CheckValue()
        {
            try
            {
                // ---- the value-display corpus from UIText.iff ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-uitext;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var rawB = FindStrChunkByID(d, 146, out id, out n, out lbl, out body);
                    string lblB = lbl;
                    var eB = (rawB != null) ? ParseLang1(body, out n) : null;
                    var rawN = FindStrChunkByID(d, 134, out id, out n, out lbl, out body);
                    string lblN = lbl;
                    var eN = (rawN != null) ? ParseLang1(body, out n) : null;
                    var rawE = FindStrChunkByID(d, 131, out id, out n, out lbl, out body);
                    string lblE = lbl;
                    var eE = (rawE != null) ? ParseLang1(body, out n) : null;
                    strOK = rawB != null && rawN != null && rawE != null
                        && lblB == R137BLabel && lblN == R137NLabel && lblE == R137ELabel
                        && eB != null && eN != null && eE != null
                        && eB.Count >= 36 && eN.Count >= 1 && eE.Count >= 4;
                    if (strOK)
                    {
                        if (ByteHash256(rawB, sha) != R137BSha
                            || ByteHash256(rawN, sha) != R137NSha
                            || ByteHash256(rawE, sha) != R137ESha) { strOK = false; strInfo = "sha;"; }
                    }
                    else if (strInfo == "") strInfo = "chunks;";
                    if (strOK)
                    {
                        if (eB[30] != R137B30 || eB[34] != R137B34 || eB[35] != R137B35)
                        { strOK = false; strInfo = "eB;"; }
                        if (eN[0] != R137N0) { strOK = false; strInfo = "eN;"; }
                        if (eE[3] != R137E3) { strOK = false; strInfo = "eE;"; }
                    }
                }

                // ---- live: the family's architecture value is CURRENT ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        bool ok = true; string diag = "";
                        screen.RefreshArchValue();
                        var family = screen.ActiveFamily;
                        if (family == null) { ok = false; diag += "no-family;"; }
                        else
                        {
                            var objVal = FSO.SimAntics.Utils.VMArchitectureStats.GetObjectValue(screen.vm);
                            int expect = FSO.SimAntics.Utils.VMArchitectureStats.GetArchValue(screen.vm.Context.Architecture)
                                + objVal.Item2;
                            if (family.ValueInArch != expect)
                            { ok = false; diag += "value=" + family.ValueInArch + "/" + expect + ";"; }
                            if (family.ValueInArch <= 0)
                            { ok = false; diag += "positive=" + family.ValueInArch + ";"; }
                            var simi = screen.vm.TS1State != null ? screen.vm.TS1State.SimulationInfo : null;
                            if (simi != null && simi.ArchitectureValue != family.ValueInArch)
                            { ok = false; diag += "simi=" + simi.ArchitectureValue + "/" + family.ValueInArch + ";"; }
                        }
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uivalue live house value: str=" + strOK + " live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && live) { Pass("uivalue"); return; }
                Log("AUTOTEST uivalue: the value-display corpus must pin byte-verbatim and FAMI.ValueInArch must equal the live recompute of the decoded engine law");
                Fail("uivalue");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uivalue EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uivalue");
            }
        }

        // ROUND-138 'uitext' — the RENDERED PIXELS of the original .ffn text
        // path (user-reported garbled/unreadable text across the board; every
        // prior gate pinned the corpus ON DISK but never the pixels). Root
        // cause: OriginalGlyphFont.FromFFN uploaded the atlas white-RGB/
        // straight-alpha while ALL draw paths blend with BlendState.AlphaBlend
        // (One, InverseSourceAlpha — MonoGame's premultiplied convention), so
        // any pixel with alpha >= 1/15 saturated to full ink: every glyph
        // collapsed to a solid block (evidence: tools/iff-dump/r138/
        // r138-textdiag-BEFORE.log — alpha art shows clean AA'd glyphs, rgb
        // art solid rectangles; fixed by premultiplying the atlas, AFTER log
        // shows rgb art == alpha art). This check pins the law PIXEL-WISE on
        // three surfaces: (1) direct OriginalGlyphFont.Draw, (2) the full
        // UILabel -> DrawLocalString -> OriginalVectorFont UI path, (3) ink
        // composited over an opaque background (intermediate blend shades
        // must exist — the collapse turns them into saturated ink).
        // Residuals (disclosed): _12_bs/_11_s carry flags=11 (regular tables
        // flags=9) and their nibble ink ceiling is 13 (vs 15) — the engine's
        // exact scaling of those tables is undecoded, the port keeps the
        // data-literal nib*17; chars > 0xFF have no glyph (the tables are
        // byte-keyed, STR# text arrives byte-coded so all canon strings
        // render; true-Unicode literals silently drop).
        private static void CheckText()
        {
            try
            {
                var gd = GameFacade.GraphicsDevice;
                bool ok = true; string diag = "";
                if (gd == null) { diag += "no-gd;"; ok = false; }
                else
                {
                    // ---- table mount through the live FAR provider ----
                    var font = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                        "Fonts\\variablesans_14.ffn", gd);
                    if (font == null || font.Atlas == null) { diag += "mount;"; ok = false; }
                    else
                    {
                        if (font.NumChars != 224 || font.AtlasW != 256 || font.AtlasH != 224)
                        { diag += "table=" + font.NumChars + "/" + font.AtlasW + "x" + font.AtlasH + ";"; ok = false; }
                        int missing = 0;
                        for (int c = 32; c <= 255; c++)
                            if (!font.ByChar.ContainsKey((char)c)) missing++;
                        if (missing != 0) { diag += "missing=" + missing + ";"; ok = false; }
                    }

                    if (ok)
                    {
                        // ---- (1) direct draw: premultiply law + collapse detector ----
                        var st1 = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "Handgloves 0123",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        ok &= AssertTextLaw(st1, "direct", ref diag);

                        // ---- (2) the full UI label path ----
                        var st2 = RenderTextProbe(gd,
                            (batch) =>
                            {
                                var label = new FSO.Client.UI.Controls.UILabel();
                                label.Caption = "The quick brown fox 0123";
                                label.CaptionStyle = FSO.Client.UI.Framework.TextStyle.DefaultLabel.Clone();
                                label.CaptionStyle.Size = 12;
                                label.CaptionStyle.Color = Microsoft.Xna.Framework.Color.White;
                                label.Draw(batch);
                            },
                            Microsoft.Xna.Framework.Color.Transparent);
                        ok &= AssertTextLaw(st2, "uilabel", ref diag);

                        // ---- (3) compositing over an opaque background ----
                        // AA edge pixels must land BETWEEN bg and tint; the
                        // collapse saturates them to (near-)full ink.
                        var bg = new Microsoft.Xna.Framework.Color(40, 40, 60);
                        var tint = new Microsoft.Xna.Framework.Color(255, 249, 157);
                        var st3 = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "Handgloves",
                                new Microsoft.Xna.Framework.Vector2(4, 8), tint),
                            bg);
                        if (st3.Ink < 100) { diag += "bg-ink=" + st3.Ink + ";"; ok = false; }
                        if (st3.Between < 100)
                        { diag += "bg-between=" + st3.Between + ";"; ok = false; }
                        Log("AUTOTEST uitext bg-composite: between=" + st3.Between
                            + " saturated=" + st3.Saturated + " solid=" + st3.Solid);

                        // ---- R139 (4): the BOLD ink ceiling — the decoded
                        // engine law. cTSFont::RebuildColorTable 0x4b31d0 +
                        // the global blend LUT ([TOC-28288], BSS-proven
                        // runtime-built, shared with Spr2Decoder/AlphaBlend)
                        // take NO per-font input: the nibble is used AS-IS as
                        // a blend level. The _12_bs/_11_s tables (flags=11)
                        // simply carry no nibble above 13, so their max ink
                        // is 13*17 = 221/255 — the port's nib*17 exactly.
                        var bold = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                            "Fonts\\variablesans_12_bs.ffn", gd);
                        if (bold == null || bold.Atlas == null)
                        { diag += "bold-mount;"; ok = false; }
                        else
                        {
                            var stb = RenderTextProbe(gd,
                                (batch) => bold.Draw(batch, "Handgloves",
                                    new Microsoft.Xna.Framework.Vector2(4, 8),
                                    Microsoft.Xna.Framework.Color.White),
                                Microsoft.Xna.Framework.Color.Transparent);
                            if (stb.MaxAlpha < 219 || stb.MaxAlpha > 223)
                            { diag += "bold-ceiling=" + stb.MaxAlpha + "!=221;"; ok = false; }
                            Log("AUTOTEST uitext bold-ceiling: maxAlpha=" + stb.MaxAlpha
                                + " (13*17=221, nibble-as-is law)");
                        }

                        // ---- R139 (5): the CP1252 boundary conversion.
                        // The engine's char table is 256 slots indexed by
                        // (c & 0xFF) (TSCharWidth 0x4acff0) — a Unicode curly
                        // quote is the TEXT the original encoded as byte
                        // 0x93, so the boundary maps it back and the two
                        // strings render identically.
                        if (Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('\u201C') != (char)0x93
                            || Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('\u2019') != (char)0x92
                            || Simitone.Client.UI.Controls.OriginalGlyphFont.MapChar('A') != 'A')
                        { diag += "cp1252-map;"; ok = false; }
                        if (font.Measure("\u201CQ\u201D \u2019t\u2019 \u2026")
                            != font.Measure("\x93Q\x94 \x92t\x92 \x85"))
                        { diag += "cp1252-measure;"; ok = false; }
                        var stU = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "\u201CHand\u201D",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        var stB = RenderTextProbe(gd,
                            (batch) => font.Draw(batch, "\x93Hand\x94",
                                new Microsoft.Xna.Framework.Vector2(4, 8),
                                Microsoft.Xna.Framework.Color.White),
                            Microsoft.Xna.Framework.Color.Transparent);
                        if (stU.Ink < 50 || stB.Ink < 50 || Math.Abs(stU.Ink - stB.Ink) > Math.Max(3, stB.Ink / 20)
                            || Math.Abs(stU.BBoxW - stB.BBoxW) > 2)
                        { diag += "cp1252-render=" + stU.Ink + "/" + stB.Ink
                            + " bbox=" + stU.BBoxW + "/" + stB.BBoxW + ";"; ok = false; }
                        Log("AUTOTEST uitext cp1252: unicode-ink=" + stU.Ink
                            + " bytes-ink=" + stB.Ink + " bbox " + stU.BBoxW + "/" + stB.BBoxW);

                        // ---- R139 (6): NATIVE scale at every size. The
                        // engine never scales bitmap glyphs (TSDrawChar blits
                        // the records' own pixel extents) — off-ladder px
                        // requests render the snapped table 1:1 (Scale==1).
                        // R140: _16 RESTORED — the R139b "broken table"
                        // verdict was an artifact of the port's 4-byte
                        // atlas stream misalignment (fixed in FromFFN this
                        // round; the engine samples at record+16 and every
                        // table incl. _16 renders clean).
                        var ov = default(Simitone.Client.UI.Controls.OriginalVectorFont);
                        {
                            var style = FSO.Client.UI.Framework.TextStyle.DefaultLabel.Clone();
                            style.Size = 13;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 12 || style.Scale != 1.0f)
                            { diag += "native13=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 6;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 7 || style.Scale != 1.0f)
                            { diag += "native6=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 12;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 12 || style.Scale != 1.0f)
                            { diag += "native12=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 16;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 16 || style.Scale != 1.0f)
                            { diag += "native16=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                            style.Size = 17;
                            ov = style.VFont as Simitone.Client.UI.Controls.OriginalVectorFont;
                            if (ov == null || ov.TablePx != 16 || style.Scale != 1.0f)
                            { diag += "native17=" + (ov != null ? ov.TablePx.ToString() : "null")
                                + "@" + style.Scale + ";"; ok = false; }
                        }
                        // ladder composition pin (R140): the full shipped
                        // ladder incl. 16 — the engine's font factory builds
                        // "VariableSans_%02d" from the request and maps BOTH
                        // 15 and 16 to the 16px table
                        var ladder = Simitone.Client.UI.Controls.OriginalVectorFont.LadderPx;
                        bool ladderOK = ladder.Length == 10;
                        bool has16 = false;
                        foreach (var px in ladder) if (px == 16) has16 = true;
                        if (!has16) ladderOK = false;
                        if (!ladderOK) { diag += "ladder;"; ok = false; }
                        // per-table render probe: every ladder table must
                        // render 'Handgloves' with real ink (logged with the
                        // measured-vs-rendered width agreement)
                        foreach (var px in ladder)
                        {
                            var tf = Simitone.Client.UI.Controls.OriginalGlyphFont.Load(
                                "Fonts\\variablesans_" + px.ToString("00") + ".ffn", gd);
                            if (tf == null || tf.Atlas == null)
                            { diag += "probe" + px + "-mount;"; ok = false; continue; }
                            var stp = RenderTextProbe(gd,
                                (batch) => tf.Draw(batch, "Handgloves",
                                    new Microsoft.Xna.Framework.Vector2(4, 8),
                                    Microsoft.Xna.Framework.Color.White),
                                Microsoft.Xna.Framework.Color.Transparent);
                            int expect = tf.Measure("Handgloves");
                            if (stp.Ink < 100)
                            { diag += "probe" + px + "-ink=" + stp.Ink + ";"; ok = false; }
                            Log("AUTOTEST uitext probe" + px + ": ink=" + stp.Ink
                                + " bboxW=" + stp.BBoxW + " measure=" + expect);
                        }
                    }
                }

                Log("AUTOTEST uitext rendered-pixel law: " + (ok ? "OK" : "FAIL")
                    + (diag.Length > 0 ? " diag=" + diag.Trim() : ""));
                if (ok) { Pass("uitext"); }
                else
                {
                    Log("AUTOTEST uitext: .ffn text must render as premultiplied coverage (rgb==alpha ramps, no saturation collapse) on the direct, UILabel and background-composited surfaces");
                    Fail("uitext");
                }
                // R139b DIAGNOSTIC (non-failing): the neighborhood house-name
                // strings — the source for the lot hover captions and the
                // house-select panel (user-reported garbled tooltip text).
                try
                {
                    var neigh = FSO.Content.Content.Get().Neighborhood;
                    if (neigh == null) Log("AUTOTEST uitext nbr: provider null");
                    else
                    {
                        for (int h = 1; h <= 8; h++)
                        {
                            var nd = neigh.GetHouseNameDesc(h);
                            string nm = nd != null ? (nd.Item1 ?? "") : "<null>";
                            Log("AUTOTEST uitext nbr house=" + h + " name=" + TextDiagEscape(nm));
                        }
                    }
                }
                catch (Exception ne)
                {
                    Log("AUTOTEST uitext nbr EXC " + ne.GetType().Name + ": " + ne.Message);
                }
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uitext EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uitext");
            }
        }

        private static string TextDiagEscape(string s)
        {
            if (s == null) return "<null>";
            var sb = new System.Text.StringBuilder();
            foreach (var ch in s)
            {
                if (ch >= 32 && ch < 127) sb.Append(ch);
                else sb.Append(string.Format("<{0:X4}>", (ushort)ch));
            }
            return sb.ToString();
        }

        private struct TextProbeStats
        {
            public int Ink, Solid, Mid, Saturated, Eq, Between;
            public int BBoxW, BBoxH;
            public int MaxAlpha;
        }

        /// Renders a draw action into an offline target and measures the
        /// premultiply law statistics over the readback.
        private static TextProbeStats RenderTextProbe(
            Microsoft.Xna.Framework.Graphics.GraphicsDevice gd,
            Action<FSO.Client.UI.Framework.UISpriteBatch> draw,
            Microsoft.Xna.Framework.Color bg)
        {
            var W = 320; var H = 48;
            var rt = new Microsoft.Xna.Framework.Graphics.RenderTarget2D(gd, W, H);
            var prev = gd.GetRenderTargets();
            gd.SetRenderTarget(rt);
            gd.Clear(bg);
            using (var sb = new FSO.Client.UI.Framework.UISpriteBatch(gd, 0))
            {
                sb.UIBegin(Microsoft.Xna.Framework.Graphics.BlendState.AlphaBlend,
                    Microsoft.Xna.Framework.Graphics.SpriteSortMode.Deferred);
                draw(sb);
                sb.End();
            }
            gd.SetRenderTarget(null);
            if (prev != null && prev.Length > 0) gd.SetRenderTargets(prev);
            var px = new Microsoft.Xna.Framework.Color[W * H];
            rt.GetData(px);
            rt.Dispose();

            var st = new TextProbeStats();
            int x0 = W, x1 = -1, y0 = H, y1 = -1;
            for (int y = 0; y < H; y++)
                for (int x = 0; x < W; x++)
                {
                    var c = px[y * W + x];
                    var mx = Math.Max(c.R, Math.Max(c.G, c.B));
                    if (c.A > 0 && mx > 20) st.Ink++;
                    if (mx > 20)
                    {
                        if (x < x0) x0 = x; if (x > x1) x1 = x;
                        if (y < y0) y0 = y; if (y > y1) y1 = y;
                    }
                    // background-composited probe: alpha is opaque everywhere,
                    // classify by ink strength instead
                    if (c.A >= 250) st.Solid++;
                    else if (c.A >= 30) st.Mid++;
                    if (mx >= 250) st.Saturated++;
                    if (c.A > st.MaxAlpha) st.MaxAlpha = c.A;
                    if (Math.Abs(mx - c.A) <= 3) st.Eq++;
                    if (mx > 70 && mx < 225) st.Between++;
                }
            if (x1 >= x0) { st.BBoxW = x1 - x0 + 1; st.BBoxH = y1 - y0 + 1; }
            return st;
        }

        private static bool AssertTextLaw(TextProbeStats st, string name, ref string diag)
        {
            bool ok = true;
            // the premultiplied law: essentially every inked pixel has rgb == alpha
            if (st.Ink < 100) { diag += name + "-ink=" + st.Ink + ";"; ok = false; }
            if (st.Ink > 0 && st.Eq < st.Ink * 95 / 100)
            { diag += name + "-premul=" + st.Eq + "/" + st.Ink + ";"; ok = false; }
            // the collapse signature: mid-alpha pixels must NOT saturate rgb
            if (st.Mid > 0 && st.Saturated > st.Solid + st.Mid / 10)
            { diag += name + "-collapse=" + st.Saturated + "/" + st.Solid + "+" + st.Mid + ";"; ok = false; }
            // the AA ramp must survive (this is what makes the text readable)
            if (st.Mid < 100) { diag += name + "-aa=" + st.Mid + ";"; ok = false; }
            if (st.BBoxW < 60 || st.BBoxH < 8 || st.BBoxH > 40)
            { diag += name + "-bbox=" + st.BBoxW + "x" + st.BBoxH + ";"; ok = false; }
            Log("AUTOTEST uitext " + name + ": ink=" + st.Ink + " solid=" + st.Solid
                + " mid=" + st.Mid + " saturated=" + st.Saturated + " eq=" + st.Eq
                + " bbox=" + st.BBoxW + "x" + st.BBoxH);
            return ok;
        }

        private static void CheckRatings()
        {
            try
            {
                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uirate: no TS1Global"); Fail("uirate"); return; }
                var sha2 = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R132RateArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha2) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- the decoded fill law (pure math; integer division) ----
                bool math = Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(0) == 0
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(49) == 16
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(50) == 20
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(100) == 40
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(-5) == 0
                    && Simitone.Client.UI.Controls.UIOriginalRatingBar.ComputeFill(150) == 40;

                // ---- live surfaces ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        bool ok = true; string diag = "";
                        // the engine fill law end-to-end through the control
                        var jb = Simitone.Client.UI.Controls.UIOriginalRatingBar.JobBar();
                        if (jb.BackdropTex == null || jb.BarsTex == null
                            || jb.BackdropTex.Width != 40 || jb.BackdropTex.Height != 11
                            || jb.BarsTex.Width != 40 || jb.BarsTex.Height != 11)
                        { ok = false; diag += "jobbar-art;"; }
                        jb.Value = 73;
                        if (jb.FillWidth != 28) { ok = false; diag += "jobbar-fill=" + jb.FillWidth + ";"; }

                        // R133: the House subpanel's captions moved to the ORIGINAL'S OWN
                        // tables (STR# 133/135/138) — pinned by 'uihouse'. The R132 reading
                        // (STR# 154 [12]/[13] as the House panel's captions) was an
                        // interpretation the corpus corrected; this check no longer
                        // double-asserts it.

                        // the Job tab's original rating bar + caption
                        var job = new Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel(screen);
                        if (job.RatingTitle == null || job.RatingBar == null
                            || job.RatingTitle.Caption != R131Str154Ratings[2]         // 'Job Rating'
                            || job.RatingBar.BarsTex == null || job.RatingBar.BarsTex.Width != 40
                            || job.RatingBar.BarsTex.Height != 11)
                        { ok = false; diag += "job-caption;"; }

                        // R200: the follow-Sim law on its ENGINE surface —
                        // cWinPeople::TrackPerson/StopTracking (0x28bf00 /
                        // 0x288740): the kTrackingTarget crosshair marks the
                        // TRACKED webcam portrait (TSOnCommand +0x224 selects
                        // when different, +0xfcc toggle-tracks; the same-person
                        // branch untracks); selection change or camera-anchor
                        // loss detaches (SetSelectedPerson / EdgeDetectScroller
                        // / the level buttons). The old motive-subpanel
                        // TrackButton pin is retired WITH the desktop mount —
                        // the same 45x45 art is pinned here on its true
                        // surface (mobile keeps its touch button by design).
                        var sp = new Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel(screen);
                        if (screen.Desktop && sp.TrackButton != null)
                        { ok = false; diag += "trackbtn-retired;"; }
                        var mp = screen.Frontend == null ? null : screen.Frontend.MainPanel;
                        var chrome = mp == null ? null : mp.PeopleChrome;
                        if (chrome == null)
                        {
                            if (screen.Desktop) { ok = false; diag += "no-people-chrome;"; }
                        }
                        else
                        {
                            var tt = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackingTarget;
                            if (tt == null || tt.Width != 45 || tt.Height != 45)
                            { ok = false; diag += "tracktarget-art;"; }
                            // drive the production refresh synchronously (the
                            // chrome's own 30-frame cadence must not gate the
                            // law probe) — same public method Update calls.
                            try { chrome.RefreshWebcams(); } catch { }
                            int wi;
                            Simitone.Client.UI.Panels.UIOriginalWebcamButton wb = null;
                            for (wi = 0; wi < 8; wi++)
                                if (chrome.Webcams[wi] != null && chrome.Webcams[wi].Avatar != null)
                                { wb = chrome.Webcams[wi]; break; }
                            if (wb == null || screen.vm == null || screen.LotControl == null)
                            { ok = false; diag += "track-no-avatar;"; }
                            else
                            {
                                var trackAv = wb.Avatar;
                                var savedUID = screen.vm.MyUID;
                                var world = screen.LotControl.World;
                                // clean state, then click 1: select + track
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.StopTracking();
                                int att0 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackAttaches;
                                chrome.SelectWebcam(wi);
                                bool click1 = screen.vm.MyUID == trackAv.PersistID
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv
                                    && wb.CrosshairVisibleForProbe
                                    && sp.IsTracking
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackAttaches == att0 + 1;
                                // click 2 on the SAME portrait: the same-person branch untracks
                                chrome.SelectWebcam(wi);
                                bool click2 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null
                                    && world.State.ScrollAnchor == null
                                    && !wb.CrosshairVisibleForProbe;
                                // click 3: re-track, then a selection change by
                                // another surface detaches (SetSelectedPerson law)
                                chrome.SelectWebcam(wi);
                                bool tracked3 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv;
                                screen.vm.MyUID = savedUID != trackAv.PersistID ? savedUID : 0;
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.SyncTracking(screen);
                                bool selLaw = tracked3
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null;
                                // click 4: re-track, then manual camera input
                                // clears the anchor — the crosshair follows it out
                                chrome.SelectWebcam(wi);
                                tracked3 = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == trackAv;
                                if (world.State != null) world.State.ScrollAnchor = null;
                                Simitone.Client.UI.Panels.UIOriginalPeopleChrome.SyncTracking(screen);
                                bool anchorLaw = tracked3
                                    && Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null
                                    && !wb.CrosshairVisibleForProbe;
                                // TrackPerson(null) is the safe untrack
                                chrome.TrackPerson(null);
                                bool nullLaw = Simitone.Client.UI.Panels.UIOriginalPeopleChrome.TrackedAvatar == null;
                                if (!(click1 && click2 && selLaw && anchorLaw && nullLaw))
                                { ok = false; diag += "tracklaw=" + click1 + "/" + click2 + "/" + selLaw + "/" + anchorLaw + "/" + nullLaw + ";"; }
                                screen.vm.MyUID = savedUID;
                            }
                        }

                        job.Kill(); sp.Kill();
                        if (!ok) liveInfo += diag;
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uirate ratings family: art=" + art + " (" + R132RateArt.Length + " pins) math=" + math + " live=" + live
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (art && math && live) { Pass("uirate"); return; }
                Log("AUTOTEST uirate: the 9 ratings members, the 4*(v/10) fill law, the Job tab bar [14] and the crosshair toggle must all match the original (House tab captions moved to uihouse/STR# 133 in R133)");
                Fail("uirate");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uirate EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uirate");
            }
        }

        private static void CheckLiveGauge()
        {
            try
            {
                // ---- STR# 154 canon ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-uitext;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var raw154 = FindStrChunkByID(d, 154, out id, out n, out lbl, out body);
                    var e154 = ParseLang1(body, out n);
                    strOK = raw154 != null && lbl == "MiscStrings"
                        && ByteHash256(raw154, sha) == R131Str154Sha;
                    for (int i = 0; i < 4 && strOK; i++)
                        if (e154[12 + i] != R131Str154Ratings[i]) { strOK = false; strInfo = "e154[" + (12 + i) + "];"; }
                }

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uigauge: no TS1Global"); Fail("uigauge"); return; }
                var sha2 = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R131LiveArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha2) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- live gauge control (UIMotiveSubpanel hosts the gauge) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var sp = new Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel(screen);
                        var g = sp.Gauge;
                        var gaugeType = typeof(Simitone.Client.UI.Controls.UIOriginalLiveGauge);
                        var backdrop = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("BackdropTex").GetValue(null);
                        var green = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("GreenTex").GetValue(null);
                        var red = (Microsoft.Xna.Framework.Graphics.Texture2D)gaugeType.GetField("RedTex").GetValue(null);
                        bool ok = g != null && sp.GaugeCaption != null
                            && sp.GaugeCaption.Caption == R131Str154Ratings[3] // 'Mood Rating' (STR#154[15])
                            && backdrop != null && backdrop.Width == 108 && backdrop.Height == 100
                            && green != null && green.Width == 27 && green.Height == 25
                            && red != null && red.Width == 27 && red.Height == 25;
                        string diag = "caption=" + (sp.GaugeCaption != null ? sp.GaugeCaption.Caption : "null");
                        if (ok)
                        {
                            g.MoodValue = 100;
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool hi = g.DisplayMood == 100f && g.FillHeight == 25
                                && g.CurrentBarTex == green;
                            g.MoodValue = -60;
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool lo = g.DisplayMood == -60f && g.FillHeight == 15
                                && g.CurrentBarTex == red;
                            g.MoodValue = -400; // engine clamps the rating at 5 -> 25px cap
                            for (int i = 0; i < 60; i++) g.StepEase();
                            bool cap = g.FillHeight == 25;
                            // R135: the EXACT engine rating law, constants recovered
                            // from the binary's const pool (file 0x5a45ec via TOC
                            // resolution): 11*(100+mood)/201 - 5, symmetric round,
                            // clamp [-5,5]. Check points computed by hand from it.
                            var rt = Simitone.Client.UI.Controls.UIOriginalLiveGauge.Rating;
                            bool law = rt(100) == 5 && rt(50) == 3 && rt(1) == 1
                                && rt(0) == 0 && rt(-1) == 0 && rt(-50) == -2
                                && rt(-60) == -3 && rt(-100) == -5 && rt(-400) == -5
                                && rt(400) == 5;
                            ok = hi && lo && cap && law;
                            if (!ok) diag += " hi=" + hi + " lo=" + lo + " cap=" + cap + " law=" + law
                                + " disp=" + g.DisplayMood + " h=" + g.FillHeight;
                        }
                        if (!ok) liveInfo += "gauge(" + diag + ");";
                        live = ok;
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uigauge original live mood gauge: str=" + strOK + " art=" + art + " (" + R131LiveArt.Length + " pins) live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && art && live) { Pass("uigauge"); return; }
                Log("AUTOTEST uigauge: STR# 154, the 9 gauge/pager/level members, and the live mood gauge (engine fill mapping + polarity) must match the original");
                Fail("uigauge");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uigauge EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uigauge");
            }
        }

        private static void CheckRoofTools()
        {
            try
            {
                // ---- STR# 147 canon ----
                bool strOK = false; string strInfo = "";
                var path = System.IO.Path.Combine(FSO.Content.Content.TS1HybridBasePath, "GameData/UIText.iff");
                if (!System.IO.File.Exists(path)) strInfo = "no-uitext;";
                else
                {
                    var d = System.IO.File.ReadAllBytes(path);
                    var sha = System.Security.Cryptography.SHA256.Create();
                    int id; int n; string lbl; byte[] body;
                    var raw147 = FindStrChunkByID(d, 147, out id, out n, out lbl, out body);
                    var e147 = ParseLang1(body, out n);
                    strOK = raw147 != null && lbl == "roofpanelstrs"
                        && ByteHash256(raw147, sha) == R130RoofStr147Sha
                        && e147.Count == 18;
                    string canonInfo = "";
                    for (int i = 0; i < 18 && strOK; i++)
                        if (e147[i] != R130RoofStr147[i]) { strOK = false; canonInfo = "e147[" + i + "]"; }
                    if (strOK && canonInfo == "") canonInfo = "147/18";
                    if (!strOK) strInfo += "str(" + (canonInfo != "" ? canonInfo : "sha/label") + ");";
                }

                // ---- art canon (generated pins; full lowercase path keys) ----
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uiroof: no TS1Global"); Fail("uiroof"); return; }
                var sha2 = System.Security.Cryptography.SHA256.Create();
                var entries = ts1.GetFarEntries(".bmp");
                var pinByLow = new System.Collections.Generic.Dictionary<string, string[]>();
                foreach (var pin in R130RoofArt) pinByLow[pin[0]] = pin;
                var unseen = new System.Collections.Generic.HashSet<string>(pinByLow.Keys);
                bool art = true; string artInfo = "";
                foreach (var en in entries)
                {
                    if (en == null || en.FarEntry == null) continue;
                    string low = en.FarEntry.Filename.Replace('/', '\\').ToLowerInvariant();
                    string[] pin;
                    if (!pinByLow.TryGetValue(low, out pin)) continue;
                    bool one = en.FarEntry.DataLength == int.Parse(pin[1]);
                    byte[] b = null; int w = -1, h = -1;
                    try
                    {
                        b = en.Archive.GetEntry(en.FarEntry);
                        if (b != null && b.Length >= 26)
                        {
                            w = b[18] | (b[19] << 8) | (b[20] << 16) | (b[21] << 24);
                            h = b[22] | (b[23] << 8) | (b[24] << 16) | (b[25] << 24);
                        }
                    }
                    catch { }
                    bool okPin = one && b != null && w == int.Parse(pin[2]) && h == int.Parse(pin[3])
                        && ByteHash256(b, sha2) == pin[4];
                    if (!okPin) { art = false; artInfo += low + ";"; }
                    unseen.Remove(low);
                }
                if (unseen.Count > 0) { art = false; foreach (var k in unseen) artInfo += k + ":missing;"; }

                // ---- live roof panel (InitCategory(17, true) -> AddRoofs) ----
                bool live = false; string liveInfo = "";
                var screen = GameFacade.Screens.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                if (screen == null) liveInfo = "no-screen;";
                else
                {
                    try
                    {
                        var bp = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(
                            screen, 1, Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Build, false);
                        bp.InitCategory(17, true);
                        var cats = bp.FullCategory;
                        int patCount = Content.Get().WorldRoofs.Count;
                        bool ok = cats.Count == 4 + patCount;
                        string diag = "count=" + cats.Count + " patterns=" + patCount;
                        // pitch sub-tools: the engine panel's display order
                        var expectResID = new int[] { 3902, 3901, 3900, 3904 };
                        var expectIconW = new int[] { 104, 104, 104, 100 };
                        var expectIconH = new int[] { 23, 17, 16, 16 };
                        var expectPitch = new float[] { 0.99f, 0.66f, 0.495f, 0f };
                        var expectStr = new int[] { 5, 3, 1, 12 };
                        for (int i = 0; i < 4 && ok; i++)
                        {
                            var el = cats[i];
                            var sp = el.Special;
                            var prov = sp?.Res as Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalRoofPitchResProvider;
                            if (sp == null || prov == null) { ok = false; diag = "i" + i + ":no-canon-provider"; break; }
                            var icon = prov.GetIcon((ulong)expectResID[i]);
                            var thumb = prov.GetThumb((ulong)expectResID[i]);
                            bool pitchOK = System.Math.Abs(
                                Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalRoofPitchResProvider.PitchForRtId(expectResID[i])
                                - expectPitch[i]) < 0.0001f;
                            bool slot = sp.Control == typeof(Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIRoofPitcher)
                                && (int)sp.ResID == expectResID[i]
                                && sp.Parameters != null && sp.Parameters.Count == 1 && sp.Parameters[0] == expectResID[i]
                                && pitchOK
                                && icon != null && icon.Width == expectIconW[i] && icon.Height == expectIconH[i]
                                && thumb != null && thumb.Width == 133 && thumb.Height == 103
                                && el.Item.Name == R130RoofStr147[expectStr[i]];
                            if (!slot) diag = "i" + i + ":ctl=" + (sp.Control != null ? sp.Control.Name : "?")
                                + " resID=" + sp.ResID + " pitchOK=" + pitchOK
                                + " icon=" + (icon != null ? icon.Width + "x" + icon.Height : "null")
                                + " thumb=" + (thumb != null ? thumb.Width + "x" + thumb.Height : "null")
                                + " name='" + el.Item.Name + "'";
                            ok = ok && slot;
                        }
                        // pattern swatches: UIRoofer on the canon provider
                        for (int i = 4; i < cats.Count && ok; i++)
                        {
                            var sp = cats[i].Special;
                            var prov = sp?.Res as Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UIOriginalRoofResProvider;
                            if (sp == null || prov == null) { ok = false; diag = "p" + i + ":no-canon-provider"; break; }
                            var icon = prov.GetIcon(sp.ResID);
                            var thumb = prov.GetThumb(sp.ResID);
                            if (sp.Control != typeof(FSO.Client.UI.Panels.LotControls.UIRoofer)
                                || icon == null || icon.Width != 32 || icon.Height != 32
                                || thumb == null || thumb.Width != 145 || thumb.Height != 103)
                            {
                                ok = false;
                                diag = "p" + i + ":ctl=" + (sp.Control != null ? sp.Control.Name : "?")
                                    + " icon=" + (icon != null ? icon.Width + "x" + icon.Height : "null")
                                    + " thumb=" + (thumb != null ? thumb.Width + "x" + thumb.Height : "null");
                            }
                        }
                        // the roof category's own template frames load at 45x45
                        Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.LoadRoofFrames();
                        var rf = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.RoofFrame;
                        var rs = Simitone.Client.UI.Panels.LiveSubpanels.Catalog.UICatalogItem.RoofFrameSel;
                        if (rf == null || rf.Width != 45 || rf.Height != 45 || rs == null || rs.Width != 45 || rs.Height != 45)
                        {
                            ok = false;
                            diag += " frames=" + (rf != null ? rf.Width + "x" + rf.Height : "null")
                                + "/" + (rs != null ? rs.Width + "x" + rs.Height : "null");
                        }
                        // R131: the engine's PAGED roof panel (cWinRoofPanel SetCurPage;
                        // kCatalogPrevPage 100 / kCatalogNextPage 101 = ScrollLeft/Right
                        // art). Page 0 = 'Roof Pitch' [14] (the 4 sub-tools), page 1 =
                        // 'Roof Patterns' [16] (the swatches); buttons clamp + disable
                        // at the bounds.
                        bool pager = bp.RoofPageTitle != null && bp.RoofPrevBtn != null && bp.RoofNextBtn != null
                            && bp.RoofPage == 0
                            && bp.RoofPitchItems != null && bp.RoofPitchItems.Count == 4
                            && bp.RoofPatternItems != null && bp.RoofPatternItems.Count == patCount
                            && bp.FilterCategory != null && bp.FilterCategory.Count() == 4
                            && bp.RoofPageTitle.Caption == R130RoofStr147[14]
                            && bp.RoofPrevBtn.Disabled && !bp.RoofNextBtn.Disabled;
                        if (!pager)
                        {
                            ok = false;
                            diag += " pager0(title=" + (bp.RoofPageTitle != null ? bp.RoofPageTitle.Caption : "null")
                                + " filt=" + (bp.FilterCategory != null ? bp.FilterCategory.Count().ToString() : "null") + ")";
                        }
                        bp.SetRoofPage(1);
                        bool pager1 = bp.RoofPage == 1
                            && bp.FilterCategory != null && bp.FilterCategory.Count() == patCount
                            && bp.RoofPageTitle.Caption == R130RoofStr147[16]
                            && !bp.RoofPrevBtn.Disabled && bp.RoofNextBtn.Disabled;
                        if (!pager1)
                        {
                            ok = false;
                            diag += " pager1(filt=" + (bp.FilterCategory != null ? bp.FilterCategory.Count().ToString() : "null") + ")";
                        }
                        bp.SetRoofPage(2);  // clamps at 1
                        bp.SetRoofPage(-1); // clamps at 0
                        if (!(bp.RoofPage == 0 && bp.FilterCategory != null && bp.FilterCategory.Count() == 4))
                        {
                            ok = false;
                            diag += " pagerClamp(page=" + bp.RoofPage + ")";
                        }
                        if (!ok) liveInfo += "roof(" + diag + ");";
                        live = ok;
                        bp.Kill();
                    }
                    catch (Exception te) { liveInfo += "EXC(" + te.GetType().Name + ");"; }
                }

                Log("AUTOTEST uiroof original roof panel: str=" + strOK + " art=" + art + " (" + R130RoofArt.Length + " pins) live=" + live
                    + (strInfo.Length > 0 ? " strFails=" + strInfo.Trim() : "")
                    + (artInfo.Length > 0 ? " artFails=" + artInfo.Trim() : "")
                    + (liveInfo.Length > 0 ? " liveFails=" + liveInfo.Trim() : ""));
                if (strOK && art && live) { Pass("uiroof"); return; }
                Log("AUTOTEST uiroof: STR# 147, the 7 roof members, and the live roof category (4 pitch sub-tools + pattern swatches in the RoofPatternTemplate frames) must all match the original");
                Fail("uiroof");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uiroof EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : "")
                    + (trace.Length > 1 ? " / " + trace[1].Trim() : ""));
                Fail("uiroof");
            }
        }

        // ROUND-89 'uinbhd' IFF-LITERAL pin + LIVE-cycling gate: the ORIGINAL neighborhood
        // SCREEN members (Res_Nbhd.RT backdrops + vacation sub-layers + nessie, R89ScreenCanon)
        // must pin 1:1 (name+bytes+sha256+dims), and EVERY original animation family must
        // mount AND cycle through UINeighborhoodAnimationLayer - the same control the live
        // neighborhood screens use. Family expectations mirror the RT canon: TS1.0 frame
        // deltas 3, Downtown water 6 (incl. dscreen05), Vacation water 5 plus the
        // post-lot static port/trees overlays,
        // Unleashed waves 6 + nessie 3, Studiotown car 0-19 (20), Magicland water 6 +
        // balloon 1-16 + fog A/B/C. Cycling proof = AdvancesByFamily increments after
        // StepFrame (frame advance is what the live screen's Update drives).
        private static void CheckUINeighborhood()
        {
            try
            {
                var ts1 = Content.Get()?.TS1Global;
                if (ts1 == null) { Log("AUTOTEST uinbhd: no TS1Global"); Fail("uinbhd"); return; }
                var entries = ts1.GetFarEntries(".bmp");
                string info;
                bool pinned = PinR88All(entries, AutotestCatalogCanon.R89ScreenCanon, out info);

                var expectCount = new Dictionary<string, int[]> {
                    { "0:0", new[] { 3 } }, { "1:0", new[] { 6 } }, { "2:0", new[] { 5 } },
                    // R93: Community keeps ONLY the waves as a family — nessie moved
                    // to the ENGINE cheat layer below.
                    { "3:0", new[] { 6 } },
                    // R92: Magicland keeps ONLY the waves as a family — the balloon
                    // (16) and fog (3) families moved to the ENGINE layers below.
                    { "6:0", new[] { 6 } } };
                var expectFirst = new Dictionary<string, string> {
                    { "0:0", "Nbhd\\DiffN1-N2_8.bmp" }, { "1:0", "Downtown\\dscreen00.bmp" },
                    { "2:0", "VIsland\\visland_waves001.bmp" }, { "3:0", "Community\\NScreen_unleashed_waves001.bmp" } };
                // R90/R95 ENGINE-DERIVED position pins — a separate evidence class from
                // IFF canon: constants recovered from the ORIGINAL PPC engine binary (The Sims
                // Complete) by the anchor scan tools/iff-dump/scan_pef_ppc.py + R92's
                // ppc_decode.py; provenance in tools/iff-dump/r90/RE-ENGINE-CONSTANTS.md.
                // waves (0,62) = cMagiclandSprites::DoWater draw coordinates
                // @0x57c6dc/0x57c6e0. R95: Downtown water (0,0) = the ctor li-0 water
                // position fields this+308/+312 (stores 0x400308/0x400314, TSPaint reads
                // 0x3fedf4/0x3fede8) and Vacation waves (0,0) = the ctor li-0 fields
                // this+316/+320 (stores 0x442cc0/0x442ccc, TSPaint reads
                // 0x4416d4/0x4416b4) — the last two provisional water positions closed.
                // (The R90 nessie (118,519) position pin moved into the R93 cheat-layer
                // constants. UL waves + TS1.0 deltas remain disclosed-unresolved: their
                // sprites are self-drawing SpriteSlots — positions live inside the slot,
                // not in window-class fields.)
                var expectPos = new Dictionary<string, float[]> {
                    { "1:0", new float[] { 0, 0 } },
                    { "2:0", new float[] { 0, 0 } },
                    { "6:0", new float[] { 0, 62 } } };

                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (gd == null) { Log("AUTOTEST uinbhd: no GraphicsDevice for live layer mount"); Fail("uinbhd"); return; }

                // R178: instantiate the real neighborhood panel and pin the exact
                // hotspot keys. LotLocations STR#5 contains a trailing House90 row,
                // but the original Studio constructor creates only 81..89; House90
                // belongs to Magic, whose constructor creates 90..98. This catches
                // the formerly clickable Studio hotspot that entered the wrong town.
                bool lotRanges = true; string rangeInfo = "";
                var rangePanel = new Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel(5);
                var studioHouses = rangePanel.HousePositions.Keys.OrderBy(x => x).ToArray();
                var expectStudioHouses = Enumerable.Range(81, 9).ToArray();
                if (!studioHouses.SequenceEqual(expectStudioHouses))
                { lotRanges = false; rangeInfo += "studio=" + string.Join(",", studioHouses) + ";"; }
                rangePanel.PopulateScreen(7);
                var magicHouses = rangePanel.HousePositions.Keys.OrderBy(x => x).ToArray();
                var expectMagicHouses = Enumerable.Range(90, 9).ToArray();
                if (!magicHouses.SequenceEqual(expectMagicHouses))
                { lotRanges = false; rangeInfo += "magic=" + string.Join(",", magicHouses) + ";"; }

                bool cyc = true; string cinfo = "";
                var cfgs = Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.Neighborhoods;
                // R173: the exact paint-phase split. Vacation TSPaint paints only
                // kVIWater below child lots; PostChildDraw paints kNghVacationPort
                // then kNghVacationTrees above them (0x43e134..0x43e21c).
                // Drive the SAME generic mount routine used by PopulateScreen so
                // this probe asserts actual structural order, not a parallel model.
                // Studiotown's loose DScreen_top_layer.bmp is absent from Res_Nbhd.RT
                // and original Init, so no image layer may mount for it.
                bool layerPhases = true; string phaseInfo = "";
                var phaseTrace = new List<string>();
                Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel.MountImageAndLotLayers(
                    cfgs[2], new int[] { 0 },
                    layer => phaseTrace.Add("under:" + layer.Frames[0]),
                    lot => phaseTrace.Add("lot"),
                    layer => phaseTrace.Add("post:" + layer.Frames[0]));
                string[] expectedPhaseTrace = new string[] {
                    "under:VIsland\\visland_waves001.bmp", "lot",
                    "post:VIsland\\visland_port.bmp", "post:VIsland\\visland_trees.bmp" };
                if (!phaseTrace.SequenceEqual(expectedPhaseTrace))
                { layerPhases = false; phaseInfo += "vac-order=" + string.Join(",", phaseTrace) + ";"; }
                if (cfgs[2].FullImageAnimations.Length != 1
                    || cfgs[2].FullImageAnimations[0].Frames.Length != 5
                    || cfgs[2].PostLotOverlays.Length != 2
                    || cfgs[2].PostLotOverlays[0].Frames.Length != 1
                    || cfgs[2].PostLotOverlays[1].Frames.Length != 1)
                { layerPhases = false; phaseInfo += "vac-split;"; }
                if (cfgs[4].FullImageAnimations.Length != 0
                    || cfgs[4].PostLotOverlays.Length != 0)
                { layerPhases = false; phaseInfo += "studio-loose-overlay;"; }
                foreach (var overlay in cfgs[2].PostLotOverlays)
                {
                    var tex = ((FSO.Content.Model.ITextureRef)ts1.Get(overlay.Frames[0])).Get(gd);
                    if (tex == null || tex.Width <= 0 || tex.Height <= 0)
                    { layerPhases = false; phaseInfo += "unmounted:" + overlay.Frames[0] + ";"; }
                }
                int famOK = 0, famTot = 0;
                for (int m = 0; m < cfgs.Length; m++)
                {
                    var cfg = cfgs[m];
                    int[] layerCounts;
                    if (!expectCount.TryGetValue(m + ":0", out layerCounts)) continue; // mode 5 (old town) has no anims
                    if (cfg.FullImageAnimations.Length != layerCounts.Length)
                    {
                        cyc = false;
                        cinfo += "mode" + (m + 1) + ":layers=" + cfg.FullImageAnimations.Length + "!=canon" + layerCounts.Length + " ";
                        continue;
                    }
                    for (int l = 0; l < cfg.FullImageAnimations.Length; l++)
                    {
                        var anim = cfg.FullImageAnimations[l];
                        famTot++;
                        string key = m + ":" + l;
                        string firstBad = "";
                        string ef;
                        if (expectFirst.TryGetValue(key, out ef) && anim.Frames[0] != ef)
                            firstBad = " first=" + anim.Frames[0] + "!=canon" + ef;
                        float[] ep;
                        if (expectPos.TryGetValue(key, out ep) &&
                            (anim.Position.X != ep[0] || anim.Position.Y != ep[1]))
                            firstBad += " pos=" + anim.Position.X + "," + anim.Position.Y +
                                        "!=engine" + ep[0] + "," + ep[1];
                        int adv0;
                        var layer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(anim, cfg.Pulsate, cfg.FrameDuration);
                        var famKey = Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.FamilyKey(anim);
                        lock (Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.AdvancesByFamily)
                            Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.AdvancesByFamily.TryGetValue(famKey, out adv0);
                        bool mounted = layer.Frames != null && layer.Frames.Length == layerCounts[l];
                        if (mounted)
                            foreach (var f in layer.Frames) if (f == null || f.Width <= 0 || f.Height <= 0) { mounted = false; break; }
                        for (int s = 0; s < layer.FrameTime + 2; s++) layer.StepFrame();
                        int adv;
                        lock (Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.AdvancesByFamily)
                            Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.AdvancesByFamily.TryGetValue(famKey, out adv);
                        bool multi = layerCounts[l] > 1;
                        bool good = mounted && adv > adv0 && (!multi || layer.FrameNum > 0) && firstBad.Length == 0;
                        if (good) famOK++;
                        else
                        {
                            cyc = false;
                            cinfo += "mode" + (m + 1) + "L" + l + "[" + famKey + "]:mounted=" + mounted +
                                     " adv=" + adv0 + "->" + adv + " frameNum=" + layer.FrameNum + firstBad + " ";
                        }
                    }
                }
                // R173: cWinNeighborhoodUL::TSPaint (0x46b130..0x46b230)
                // advances a mod-12 counter when 1000/integerElapsed <= 2*pi
                // (earliest event 160 ms), then selects floor(counter/2) from the
                // six wave buffers. The
                // selected buffer replaces the child-window image; it is never
                // alpha-crossfaded. Pin both the elapsed-time boundary and the
                // two-counter hold, with a non-UL family as the negative control.
                bool ulCadence = true; string ulinfo = "";
                var ulCadenceAnim = cfgs[3].FullImageAnimations[0];
                var ulCadenceLayer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(
                    ulCadenceAnim, cfgs[3].Pulsate, cfgs[3].FrameDuration);
                double ulTick = Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.OldTownCounterIntervalMilliseconds;
                if (!ulCadenceAnim.Discrete || !ulCadenceLayer.Discrete
                    || ulCadenceAnim.FrameRepeat != Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.OldTownFrameRepeat
                    || Math.Abs(ulCadenceAnim.CounterIntervalMilliseconds - ulTick) > 0.000001
                    || Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.OldTownAdvancesPerSecondThreshold != 6.2831855f
                    || ulCadenceLayer.DrawsInterpolatedFrameForProbe || ulCadenceLayer.VisibleFrameForProbe != 0)
                { ulCadence = false; ulinfo += "policy;"; }
                ulCadenceLayer.AdvanceMilliseconds(ulTick - 0.01);
                if (ulCadenceLayer.FrameNum != 0 || ulCadenceLayer.VisibleFrameForProbe != 0)
                { ulCadence = false; ulinfo += "early;"; }
                ulCadenceLayer.AdvanceMilliseconds(0.02);
                if (ulCadenceLayer.FrameNum != 1 || ulCadenceLayer.VisibleFrameForProbe != 0)
                { ulCadence = false; ulinfo += "counter1;"; }
                ulCadenceLayer.AdvanceMilliseconds(ulTick);
                if (ulCadenceLayer.FrameNum != 2 || ulCadenceLayer.VisibleFrameForProbe != 1)
                { ulCadence = false; ulinfo += "counter2;"; }
                for (int s = 0; s < 10; s++) ulCadenceLayer.StepFrame();
                if (ulCadenceLayer.FrameNum != 0 || ulCadenceLayer.VisibleFrameForProbe != 0)
                { ulCadence = false; ulinfo += "mod12;"; }
                var stalledLayer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(
                    ulCadenceAnim, cfgs[3].Pulsate, cfgs[3].FrameDuration);
                stalledLayer.AdvanceMilliseconds(1000);
                if (stalledLayer.FrameNum != 1 || stalledLayer.VisibleFrameForProbe != 0)
                { ulCadence = false; ulinfo += "catchup;"; }
                var genericLayer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(
                    cfgs[1].FullImageAnimations[0], cfgs[1].Pulsate, cfgs[1].FrameDuration);
                if (genericLayer.Discrete || !genericLayer.DrawsInterpolatedFrameForProbe)
                { ulCadence = false; ulinfo += "global-regression;"; }
                // R91 ENGINE-DERIVED car-lane pins — literal re-declaration of the
                // cWinStudiotown::InitCars six-lane table (literal stores 0x475e1c..
                // 0x4760ec; direction split cmpwi r25,3 @0x475f54; bitmap pick
                // Random()%18 @0x475c28/0x476000; full decode in tools/iff-dump/r91/).
                // Pins: the table itself, the %18 bitmap modulus, the 20-frame texture
                // mount, and movement invariants (phase advances along dir; every car
                // stays inside its lane range; 13+11+10+8+7+5 = 54 cars).
                // R101: the old "+3/+4 car hotspot" residual was REFUTED —
                // those are per-car record FIELD offsets (slot/rect pointers
                // in the animation function 0x476150..0x4763E4), not pixels;
                // the engine draw passes no offsets (r6=r7=0 @0x4763b0), so
                // the raw-coordinate CarX pins here are the correct assertions
                // (decode: tools/iff-dump/r101/).
                var expectLanes = new int[6, 6] {
                    { 468, 806, 420, -1, 13, 40 }, { 480, 806, 440, -1, 11, 35 },
                    { 492, 806, 475, -1, 10, 30 }, { 606, 816, 538, 1, 8, 20 },
                    { 606, 816, 574, 1, 7, 12 }, { 606, 816, 610, 1, 5, 10 } };
                bool lanes = true; string linfo = "";
                var carAnim = cfgs[4].CarLanes;
                if (carAnim == null || carAnim.Frames.Length != 20 ||
                    carAnim.Frames[0] != "Studiotown\\Nhood_superstar_car0.bmp")
                { lanes = false; linfo = "carAnim-missing "; }
                int carsTotal = 0;
                for (int L = 0; L < 6 && lanes; L++)
                {
                    var lay = new Simitone.Client.UI.Panels.UINeighborhoodCarLaneLayer(carAnim, L, 15);
                    if (lay.XStart != expectLanes[L, 0] || lay.XEnd != expectLanes[L, 1] || lay.Y != expectLanes[L, 2] ||
                        lay.Dir != expectLanes[L, 3] || lay.Cars != expectLanes[L, 4] || lay.Spacing != expectLanes[L, 5])
                    { lanes = false; linfo += "L" + L + ":table!=engine "; }
                    carsTotal += lay.Cars;
                    if (lay.Frames == null || lay.Frames.Length != 20) { lanes = false; linfo += "L" + L + ":frames!=20 "; }
                    else foreach (var f in lay.Frames)
                        if (f == null || f.Width <= 0 || f.Height <= 0) { lanes = false; linfo += "L" + L + ":badframe "; break; }
                    for (int i = 0; i < lay.CarBitmap.Length; i++)
                        if (lay.CarBitmap[i] < 0 || lay.CarBitmap[i] >= Simitone.Client.UI.Panels.UINeighborhoodCarLaneLayer.BitmapChoiceModulus)
                        { lanes = false; linfo += "L" + L + "car" + i + ":bmp>=18 "; break; }
                    for (int s = 0; s < 400; s++) lay.StepFrame();
                    if (lay.Phase * lay.Dir <= 0) { lanes = false; linfo += "L" + L + ":phase-not-moving "; }
                    for (int i = 0; i < lay.Cars; i++)
                    {
                        float x = lay.CarX(i);
                        if (x < lay.XStart - 0.01f || x > lay.XEnd + 0.01f)
                        { lanes = false; linfo += "L" + L + "car" + i + ":x-out-of-range "; break; }
                    }
                }
                // R92 ENGINE-DERIVED cloud/balloon pins — literal re-declaration of the
                // cMagiclandSprites decode (InitClouds 0x57c890 four seeding loops;
                // AnimateClouds 0x57c1d0 drift/wrap; AnimateBalloon 0x57c330 wind walk;
                // InitBalloons 0x57caf0 literal seed; raw decodes in tools/iff-dump/r92/).
                // Cloud pins: 21 records; per-group Y ladders (60+16j for 0..7, 60+16k
                // for 10..15, 60+10k for 17..20); defaults for records 8/9/16 (x=0,
                // tick=1, frame=-110, drift=0); columns 142/262 + k*(rand%5) spreads
                // and drift rand%5+2 for 17..20; slot/interval moduli; movement
                // invariants (drift>0 clouds wrapped and stay in column range).
                bool cloudsOK = true; string clinfo = "";
                var cloudAnim = cfgs[6].Clouds;
                if (cloudAnim == null || cloudAnim.Frames.Length != 3 ||
                    cloudAnim.Frames[0] != "Magicland\\DScreen_mistA.tga")
                { cloudsOK = false; clinfo = "cloudAnim-missing "; }
                int wrappedCount = 0;
                if (cloudsOK)
                {
                    var cl = new Simitone.Client.UI.Panels.UINeighborhoodCloudLayer(cloudAnim, 15);
                    if (cl.CloudsInfo.Length != 21) { cloudsOK = false; clinfo += "count!=21 "; }
                    if (cl.Frames == null || cl.Frames.Length != 3) { cloudsOK = false; clinfo += "frames!=3 "; }
                    else foreach (var f in cl.Frames)
                        if (f == null || f.Width <= 0 || f.Height <= 0) { cloudsOK = false; clinfo += "badframe "; break; }
                    for (int i = 0; i < 21 && cloudsOK; i++)
                    {
                        var c = cl.CloudsInfo[i];
                        // R258 ENGINE-EXACT record map: loop 2 records 0..5 as
                        // stored (loop 3 overwrites 6..7); loop 3 records 6..11
                        // (k=i-6); loop 4 records 13..16 (k=i-13); defaults at
                        // 12 and 17..20.
                        int expectY = (i <= 5) ? 60 + 16 * i
                            : (i <= 11) ? 60 + 16 * (i - 6)
                            : (i >= 13 && i <= 16) ? 60 + 10 * (i - 13) : 0;
                        if (c.Y != expectY) { cloudsOK = false; clinfo += "c" + i + ":y=" + c.Y + "!=engine" + expectY + " "; }
                        if (c.Tick != 1 || c.Frame != -110) { cloudsOK = false; clinfo += "c" + i + ":defaults "; }
                        if (c.Slot < 0 || c.Slot > 2) { cloudsOK = false; clinfo += "c" + i + ":slot!=0..2 "; }
                        if (c.Interval < 2 || c.Interval > 3) { cloudsOK = false; clinfo += "c" + i + ":interval!=rand%2+2 "; }
                        if (i <= 5)
                        {
                            if (c.WrapX != 462 - 32 * i) { cloudsOK = false; clinfo += "c" + i + ":wrapX!=462-32j "; }
                            if (c.Drift != 2) { cloudsOK = false; clinfo += "c" + i + ":drift!=2 "; }
                            if (c.X < 342 - 32 * i || c.X > 342 - 32 * i + 4 * i) { cloudsOK = false; clinfo += "c" + i + ":x!=342-32j+j*rand%5 "; }
                        }
                        else if (i <= 11)
                        {
                            int k = i - 6;
                            if (c.WrapX != 462 - 48 * k) { cloudsOK = false; clinfo += "c" + i + ":wrapX!=462-48k "; }
                            if (c.Drift != 3) { cloudsOK = false; clinfo += "c" + i + ":drift!=3 "; }
                            if (c.X < 282 - 48 * k || c.X > 282 - 48 * k + 4 * (i + 4)) { cloudsOK = false; clinfo += "c" + i + ":x!=282-48k+c*rand%5 "; }
                        }
                        else if (i == 12 || i >= 17)
                        {
                            if (c.X != 0 || c.Drift != 0) { cloudsOK = false; clinfo += "c" + i + ":not-default "; }
                        }
                        else
                        {
                            int k = i - 13;
                            if (c.X < 142 || c.X > 142 + 4 * k) { cloudsOK = false; clinfo += "c" + i + ":x!=142+k*rand%5 "; }
                            if (c.WrapX < 262 || c.WrapX > 262 + 4 * k) { cloudsOK = false; clinfo += "c" + i + ":wrapX!=262+k*rand%5 "; }
                            if (c.Drift != 2) { cloudsOK = false; clinfo += "c" + i + ":drift!=2 "; }
                        }
                    }
                    for (int s = 0; s < 3000; s++) cl.StepFrame();
                    for (int i = 0; i < 21 && cloudsOK; i++)
                    {
                        var c = cl.CloudsInfo[i];
                        // post-step invariant: X in [0, max possible init/wrap column]
                        // (loop-2 init max = 342 at j=0; wrapX max = 462 at j=0)
                        if (c.X < 0 || c.X > 462) { cloudsOK = false; clinfo += "c" + i + ":x-out-of-range "; }
                        if (c.Slot < 0 || c.Slot > 2) { cloudsOK = false; clinfo += "c" + i + ":slot-rebad "; }
                        if (cl.Wrapped[i]) wrappedCount++;
                    }
                    if (wrappedCount < 12) { cloudsOK = false; clinfo += "wrapped=" + wrappedCount + "<12 "; }
                }
                // Balloon pins: literal init (seed 1, wind 400, anchor 300); the wind
                // walk stays in [1,15] with the %35 reset observed; draw x = anchor +
                // sway with the engine-literal (seed%1440) angle argument; bitmap index
                // = wind within the 16-frame mount.
                bool balloonOK = true; string binfo = "";
                var balAnim = cfgs[6].Balloons;
                if (balAnim == null || balAnim.Frames.Length != 16 ||
                    balAnim.Frames[0] != "Magicland\\Nhood_balloon1.bmp")
                { balloonOK = false; binfo = "balAnim-missing "; }
                if (balloonOK)
                {
                    var bl = new Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer(balAnim, 15);
                    if (bl.Seed != 1 || bl.Wind != 400) { balloonOK = false; binfo += "init!=engine{1,400} "; }
                    if (bl.Frames == null || bl.Frames.Length != 16) { balloonOK = false; binfo += "frames!=16 "; }
                    else foreach (var f in bl.Frames)
                        if (f == null || f.Width <= 0 || f.Height <= 0) { balloonOK = false; binfo += "badframe "; break; }
                    // R104/r258: the sway constants are lfd DOUBLES from the
                    // float block (file 0x5a5348 via TOC sec1+0x3d64 ->
                    // code+0x59c4b8): 0.785 / 180.0 multiply-divide, and the
                    // wind-band pool doubles {1.5,3.0,4.5,5.0,6.0} (the r258
                    // dump's double view of the same bytes).
                    if (Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EnginePiOver4 != 0.785 ||
                        Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineDegrees != 180.0)
                    { balloonOK = false; binfo += "angle-consts!=engine "; }
                    var gates = Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineWindGates;
                    float[] expectGates = new float[] { 1.5f, 3.0f, 4.5f, 5.0f, 6.0f };
                    if (gates == null || gates.Length != 5)
                    { balloonOK = false; binfo += "gates-missing "; }
                    else for (int gi = 0; gi < 5; gi++)
                        if (gates[gi] != expectGates[gi]) { balloonOK = false; binfo += "gate" + gi + "!=" + expectGates[gi] + " "; }
                    bool sawReset2 = false, sawHigh = false;
                    for (int s = 0; s < 2000; s++)
                    {
                        bl.StepFrame();
                        // Wind==400 is the engine's LITERAL init state (InitBalloons
                        // f16), present transiently after the disclosed off-screen
                        // respawn until the next StepWind clamps it — allowed here;
                        // the steady walk must stay in [0,15].
                        if (bl.Wind < 0 || (bl.Wind > 15 && bl.Wind != 400)) { balloonOK = false; binfo += "step" + s + ":wind-out "; break; }
                        // Seed starts 1 and increments per step, so Seed%35==0 at s=34,
                        // 69, ... — the engine's %35 wind reset to 2.
                        if (bl.Wind == 2 && s > 0 && (s + 1) % 35 == 0) sawReset2 = true;
                        if (bl.Wind >= 14) sawHigh = true;
                        // R258 engine-exact sway: the off-screen respawn resets the
                        // seed every 599 steps (DrawY = s+2 >= 600 at s=598, seed
                        // back to 1, no increment that step), so m = (s % 599) + 1
                        // and DrawX = 300 + (int)(m*sin(0.785*m/180)) — asserted
                        // against the law restated HERE (independent of the
                        // layer's EngineSway), plus hard engine-exact anchors.
                        int m = (s % 599) + 1;
                        int expectX = 300 + (int)(m * Math.Sin(0.785 * m / 180.0));
                        if (bl.DrawX != expectX) { balloonOK = false; binfo += "step" + s + ":x=" + bl.DrawX + "!=law" + expectX + " "; break; }
                        if (bl.DrawY < 2 || bl.DrawY > 600) { balloonOK = false; binfo += "step" + s + ":y-out "; break; }
                    }
                    // hard anchors (desk-computed from the r258 law, double math):
                    // m=1 -> 0; m=359 -> 358; m=360 -> 359 (phase exactly 1.57,
                    // sin(1.57)<1); m=599 -> 302; m=1080 -> -1079; m=1439 -> -10.
                    bool anchors = Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(1) == 0
                        && Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(359) == 358
                        && Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(360) == 359
                        && Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(599) == 302
                        && Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(1080) == -1079
                        && Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.EngineSway(1439) == -10;
                    if (!anchors) { balloonOK = false; binfo += "sway-anchors!=law "; }
                    if (!sawReset2) { balloonOK = false; binfo += "no-%35-wind-reset "; }
                    if (!sawHigh) { balloonOK = false; binfo += "wind-never-climbed "; }
                }
                // R93 ENGINE-DERIVED nessie cheat pins — literal walk of the decoded
                // machine (CheatCallback 0x4652c0..0x465445: "nessie" match, once-only
                // flag this+240, spawn li pair 118/519 @0x465310; DoNessie
                // 0x462090..0x46273c: state -1->0 kNess1, 0 sfx ->1 kNess2, ->2 kNess3,
                // swim (-2,+1)/tick until x==60 (29 ticks), ->3 kNess2, ->4 kNess1,
                // ->5 end: flag cleared — the cheat can fire again). Raw decodes in
                // tools/iff-dump/r93/.
                // R107: the UL/TS1.0 water POSITION mechanism decoded — the
                // SpriteSlot machinery (activate 0x47b350..0x47b424, position
                // resolution via the slot record at +396: rect [108]/[112] plus
                // offsets [80]/[84], fed from the SPRITE RESOURCE's own stored
                // origin — r107/r107-*.txt) — so those positions are
                // data-inside-the-sprite, not window-class constants. The port's
                // (0,0) full-screen overlay mount is the engine-visible
                // equivalent; pin that the wave/delta textures ARE full-screen
                // (the mechanism's precondition for origin-covering draws).
                bool fsTextures = true; string fsinfo = "";
                {
                    var ulAnim = cfgs[3].FullImageAnimations[0];
                    var vcAnim = cfgs[0].FullImageAnimations[0];
                    var ulLayer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(ulAnim, false, 15);
                    var vcLayer = new Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer(vcAnim, false, 15);
                    if (ulLayer.Frames == null || ulLayer.Frames.Length != 6 || ulLayer.Frames[0].Width != 800 || ulLayer.Frames[0].Height != 600)
                    { fsTextures = false; fsinfo += "ULwaves:" + (ulLayer.Frames != null && ulLayer.Frames.Length > 0 ? ulLayer.Frames[0].Width + "x" + ulLayer.Frames[0].Height : "null") + " "; }
                    if (vcLayer.Frames == null || vcLayer.Frames.Length != 3 || vcLayer.Frames[0].Width < 600)
                    { fsTextures = false; fsinfo += "TS1deltas:" + (vcLayer.Frames != null && vcLayer.Frames.Length > 0 ? vcLayer.Frames[0].Width + "x" + vcLayer.Frames[0].Height : "null") + " "; }
                }
                bool nessieOK = true; string ninfo = "";
                var nessAnim = cfgs[3].Nessie;
                if (nessAnim == null || nessAnim.Frames.Length != 3 ||
                    nessAnim.Frames[0] != "Community\\ness01.bmp")
                { nessieOK = false; ninfo = "nessAnim-missing "; }
                if (nessieOK)
                {
                    var ne = new Simitone.Client.UI.Panels.UINeighborhoodNessieLayer(nessAnim, 15);
                    if (ne.Active || ne.State != -2) { nessieOK = false; ninfo += "not-dormant "; }
                    if (ne.Frames == null || ne.Frames.Length != 3) { nessieOK = false; ninfo += "frames!=3 "; }
                    else foreach (var f in ne.Frames)
                        if (f == null || f.Width <= 0 || f.Height <= 0) { nessieOK = false; ninfo += "badframe "; break; }
                    // dormant ticks never activate her
                    ne.StepFrame();
                    if (ne.Active) { nessieOK = false; ninfo += "dormant-step-activated "; }
                    // the cheat: first fires at the engine spawn, second is refused
                    if (!ne.CheatNessie()) { nessieOK = false; ninfo += "cheat-refused-first "; }
                    else if (ne.CheatNessie()) { nessieOK = false; ninfo += "cheat-allowed-twice "; }
                    if (ne.X != 118 || ne.Y != 519) { nessieOK = false; ninfo += "spawn!=engine(118,519) "; }
                    // full machine walk: -1 -> 0 (kNess1) -> 1 (kNess2) -> 2 (kNess3)
                    // R108: the sound selection is ENGINE-RECOVERED (TOC-18180 ->
                    // sec1+0x6c6e0 = "%d\0nessie_sfx\0...", +3 skips the prefix):
                    // the engine plays the sound NAMED "nessie_sfx".
                    if (Simitone.Client.UI.Panels.UINeighborhoodNessieLayer.EngineSoundEvent != "nessie_sfx")
                    { nessieOK = false; ninfo += "sound-event!=engine "; }
                    ne.StepFrame();
                    if (ne.State != 0 || ne.FrameIndex != 0) { nessieOK = false; ninfo += "s0 "; }
                    ne.StepFrame();
                    if (ne.State != 1 || ne.FrameIndex != 1) { nessieOK = false; ninfo += "s1 "; }
                    ne.StepFrame();
                    if (ne.State != 2 || ne.FrameIndex != 2) { nessieOK = false; ninfo += "s2 "; }
                    int swam = 0;
                    while (ne.State == 2 && nessieOK && swam < 100) { ne.StepFrame(); swam++; }
                    if (ne.X != 60 || swam != 29 || ne.Y != 548)
                    { nessieOK = false; ninfo += "swim:x=" + ne.X + ",y=" + ne.Y + ",t=" + swam + " "; }
                    // the last swim tick already set state 3 (kNess2 dive frame)
                    if (ne.State != 3 || ne.FrameIndex != 1) { nessieOK = false; ninfo += "s3 "; }
                    ne.StepFrame();
                    if (ne.State != 4 || ne.FrameIndex != 0) { nessieOK = false; ninfo += "s4 "; }
                    ne.StepFrame();
                    if (ne.State != 5 || !ne.Active || ne.FrameIndex != 0) { nessieOK = false; ninfo += "s5 "; }
                    ne.StepFrame();
                    if (ne.Active || ne.State != -2) { nessieOK = false; ninfo += "end-not-cleared "; }
                    // after the end-state the cheat fires again (engine flag cleared)
                    if (!ne.CheatNessie()) { nessieOK = false; ninfo += "cheat-dead-after-end "; }
                }
                long flowAdv = Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.FrameAdvances;
                int flowLayers = Simitone.Client.UI.Panels.UINeighborhoodAnimationLayer.LayersMounted;
                int flowLanes = Simitone.Client.UI.Panels.UINeighborhoodCarLaneLayer.LanesMounted;
                int flowClouds = Simitone.Client.UI.Panels.UINeighborhoodCloudLayer.LayersMounted;
                int flowBalloons = Simitone.Client.UI.Panels.UINeighborhoodBalloonLayer.LayersMounted;
                int flowNessie = Simitone.Client.UI.Panels.UINeighborhoodNessieLayer.LayersMounted;
                Log("AUTOTEST uinbhd IFF-literal neighborhood screens + LIVE cycling + ENGINE-derived positions + ENGINE car lanes + ENGINE clouds/balloon + ENGINE nessie cheat: pinned=" + pinned +
                    " families=" + famOK + "/" + famTot + " cyc=" + cyc + " lotRanges=" + lotRanges + " layerPhases=" + layerPhases + " ulCadence=" + ulCadence +
                    " lanes=" + lanes + " cars=" + carsTotal + "/54 clouds=" + cloudsOK + " wrapped=" + wrappedCount + "/21 balloon=" + balloonOK + " nessie=" + nessieOK + " fsWater=" + fsTextures + " " + fsinfo.Trim() +
                    " flowLanes=" + flowLanes + " flowClouds=" + flowClouds + " flowBalloons=" + flowBalloons + " flowNessie=" + flowNessie +
                    " flowLayers=" + flowLayers + " flowAdvances=" + flowAdv + " " + info.Trim() + " " + rangeInfo.Trim() + " " + cinfo.Trim() + " " + phaseInfo.Trim() + " " + ulinfo.Trim() + " " + linfo.Trim() + " " + clinfo.Trim() + " " + binfo.Trim() + " " + ninfo.Trim());
                if (pinned && cyc && famOK == famTot && lotRanges && layerPhases && ulCadence && lanes && carsTotal == 54 && cloudsOK && balloonOK && nessieOK && fsTextures) { Pass("uinbhd"); return; }
                Log("AUTOTEST uinbhd: neighborhood screens must pin 1:1 AND under-lot/post-lot phases must match the original AND every original animation family must mount+cycle (UL waves discrete at the engine cadence) AND the engine car lanes/clouds/balloon/nessie-cheat must pin+move");
                Fail("uinbhd");
            }
            catch (Exception se) { Log("AUTOTEST uinbhd EXC " + se.GetType().Name + " " + se.Message); Fail("uinbhd"); }
        }


        private static void CheckUIDump()
        {
            // Render the live UI layer (CurrentUIScreen) into a RenderTarget2D through the
            // shared ui.SpriteBatch in a single Immediate pass. This is the headless visual-
            // verification hook for the UI-fidelity gap: evidence, not a pin.
            var ui = FSO.Client.GameFacade.Screens;
            var gd = FSO.Client.GameFacade.GraphicsDevice;
            // IFF-literal backdrop pin below (Round 69), TREE-LEVEL: the original live-
            // toolbar backdrop (UIGraphics.far 0119_PanelBack.bmp, navy #000052 + steel-
            // #6F6F9C glimmer wedge) mounts as the UIMainPanel's lowest child, sized
            // (ScreenWidth,128) and visible. The pixel render of that wedge wobbles in
            // brightness run-to-run (IFF steel R observed 0x5F..0xA7 across r68/r69), so
            // the GATE is the widget tree: OriginalPanelBack present, correctly sized,
            // visible. Pixel steel/navy counts stay as logged evidence only. IFF canvas
            // fidelity is byte-verified in R68 evidence; rendering is proven by the
            // committed r67(0)->r68(2047) steel-band diff.
            var bmp = (ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen)?.Frontend?.MainPanel;
            var pb = bmp?.OriginalPanelBack;
            int backSteel = 0, backNavyTeal = 0, backPX = 0, backPY = 0;
            if (bmp != null) { backPX = (int)bmp.Position.X + 6; backPY = (int)bmp.Position.Y; }
            try
            {
                if (gd == null || ui == null) { Skip("uidump", "no device/ui"); return; }
                int w = gd.Viewport.Width, h = gd.Viewport.Height;
                if (w <= 0 || h <= 0) { w = gd.PresentationParameters.BackBufferWidth; h = gd.PresentationParameters.BackBufferHeight; }
                if (w <= 0 || h <= 0) { Skip("uidump", "zero-size viewport"); return; }
                try
                {
                    // Open the live-mode main panel so the navy palette is actually on screen
                    // (evidence only; bypasses the 0.5s open tween by setting CurWidth directly).
                    var scr = ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                    var mp = scr?.Frontend?.MainPanel;
                    if (mp != null)
                    {
                        mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                        mp.Visible = true;
                        mp.PanelActive = true;
                        mp.CurWidth = Math.Max(500, w - mp.X - 40);
                        mp.Switcher_OnCategorySelect(0);
                        foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                        if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                    }
                    else Log("AUTOTEST uidump openpanel: none (scr=" + (scr != null) + " front=" + (scr?.Frontend != null) + ")");
                }
                catch (Exception pex) { Log("AUTOTEST uidump openpanel EXC " + pex.GetType().Name + " " + pex.Message); }
                using (var rt = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(gd, 1, 0, SurfaceFormat.Color, w, h, DepthFormat.None))
                {
                    gd.SetRenderTarget(rt);
                    gd.Clear(new Color(0x72, 0x72, 0x72, 0xFF));
                    ui.SpriteBatch.UIBegin(BlendState.AlphaBlend, SpriteSortMode.Immediate);
                    try { ui.Draw(ui.SpriteBatch); } finally { ui.SpriteBatch.End(); }
                    gd.SetRenderTarget(null);
                    var path = System.IO.Path.Combine(FSO.Common.FSOEnvironment.UserDir, "uidump-lot.png");
                    using (var fs = System.IO.File.Create(path))
                        rt.SaveAsPng(fs, rt.Width, rt.Height);
                    var pix = new Color[w * h];
                    rt.GetData<Color>(pix);
                    // IFF-literal backdrop pin (Round 69): the UIMainPanel carries the ORIGINAL
                    // live-toolbar backdrop (UIGraphics.far 0119_PanelBack.bmp, navy #000052 +
                    // steel-#6F6F9C glimmer left wedge). If it renders, the panel's top band at
                    // the panel's position contains a heavy IFF steel-glimmer signature that is
                    // ABSENT pre-mount (r67 evidence 0 px, r68 mounted 2047 px in the same band).
                    // Machine-pins the palette so the 'pending-eyes' palette gap no longer needs
                    // human eyes: FAIL means the original backdrop is not on screen.
                    int bX1 = System.Math.Min(w, backPX + 262), bY1 = System.Math.Min(h, backPY + 56);
                    if (bmp != null && bX1 > backPX && bY1 > backPY)
                    {
                        for (int i = backPY; i < bY1; i++)
                        {
                            for (int j = backPX; j < bX1; j++)
                            {
                                var c = pix[i * w + j];
                                int rr = c.R, gg = c.G, bb = c.B;
                                if (rr >= 0x40 && rr <= 0xE0 && bb >= gg && gg >= rr && bb - gg <= 0x30 && gg - rr <= 0x3A && gg >= 0x70 && bb >= 0x90) backSteel++;
                                else if (rr < 0x10 && gg >= 0x28 && gg <= 0x60 && bb >= gg && bb <= gg + 0x22) backNavyTeal++;
                            }
                        }
                    }
                    int minX = -1, minY = -1, maxX = -1, maxY = -1, nonBg = 0;
                    var seen = new System.Collections.Generic.Dictionary<int, int>();
                    for (int i = 0; i < pix.Length; i++)
                    {
                        var c = pix[i];
                        if (c.A > 0 && (c.R + c.G + c.B) > 0)
                        {
                            nonBg++;
                            int x = i % w, y = i / w;
                            if (minX < 0) { minX = maxX = x; minY = maxY = y; }
                            if (x < minX) minX = x; if (x > maxX) maxX = x;
                            if (y < minY) minY = y; if (y > maxY) maxY = y;
                        }
                        int key = (c.R >> 5) << 6 | (c.G >> 5) << 3 | (c.B >> 5);
                        int v; seen.TryGetValue(key, out v); seen[key] = v + 1;
                    }
                    var top = string.Join(",", seen.OrderByDescending(kv => kv.Value).Take(4)
                        .Select(kv => "#" + (((kv.Key >> 6) << 5) | 16).ToString("X2") + ((((kv.Key >> 3) & 7) << 5) | 16).ToString("X2") + (((kv.Key & 7) << 5) | 16).ToString("X2")));
                    Log("AUTOTEST uidump screen=" + (ui.CurrentUIScreen?.GetType().Name ?? "null") + " size=" + w + "x" + h +
                        " nonBg=" + nonBg + " bbox=" + minX + "," + minY + ".." + maxX + "," + maxY + " top=" + top + " -> " + path);
                    // R142 correction (disclosed): the backdrop is PanelBack at its
                    // NATURAL 804x100 clamped to the screen, not the old full-width x128 stretch.
                    int pbW = Math.Min(804, w - 220);
                    bool uiback = pb != null && pb.Visible && (int)pb.Size.Y == 100 &&
                        System.Math.Abs(pb.Size.X - pbW) <= 4;
                    Log("AUTOTEST uiback panel=" + (bmp != null) + " backdrop=" + (pb != null) +
                        " size=" + (pb != null ? (int)pb.Size.X + "x" + (int)pb.Size.Y : "?") + " vis=" + (pb != null ? pb.Visible : false) +
                        " band=" + backPX + "," + backPY + ".." + bX1 + "," + bY1 +
                        " steelIFF=" + backSteel + " navyteal=" + backNavyTeal + " pin=" + (uiback ? "PASS" : "FAIL"));
                    try
                    {
                        var tree = new System.Collections.Generic.List<string>();
                        WalkUITree(ui.CurrentUIScreen, 0, 3, ref tree);
                        foreach (var t in tree.Take(60)) Log("AUTOTEST uidump-tree " + t);
                    }
                    catch (Exception te) { Log("AUTOTEST uidump-tree EXC " + te.GetType().Name + " " + te.Message); }
                }
                // R85 'uichrome' tree gate: the mounted control TEXTURES must carry ORIGINAL-dimension
                // art (IFF-first in UICategorySwitcher/UIMotiveBar; 65x65 modern icon or 30x20 bg would
                // mean the IFF mount fell back). Pins the rendered control tree, not absolute hex.
                var mbTex = bmp?.Switcher?.MainButton?.Texture;
                // R144: kGreenbars now mounts as the people-chrome TREND ARROWS
                // (engine 1.4) — the mobile motive bars that carried it as a fill
                // are desktop-gone; the texture pin itself is unchanged (27x25).
                var barTex = bmp?.PeopleChrome?.GreenBars
                    ?? (bmp?.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel)?.MotiveDisplays?[0]?.GreenTex;
                bool uichromeBtn = mbTex != null && mbTex.Width == 128 && mbTex.Height == 39;
                bool uichromeBar = barTex != null && barTex.Width == 27 && barTex.Height == 25;
                Log("AUTOTEST uichrome tree: btn=" + uichromeBtn + " (" + (mbTex != null ? mbTex.Width + "x" + mbTex.Height : "null") + ") bar=" + uichromeBar + " (" + (barTex != null ? barTex.Width + "x" + barTex.Height : "null") + ")");
                bool uibackOk = bmp != null && pb != null && pb.Visible && (int)pb.Size.Y == 100 &&
                    System.Math.Abs(pb.Size.X - Math.Min(804, w - 220)) <= 4;
                if (!uibackOk) { Log("AUTOTEST uidump FAIL: original IFF backdrop not mounted/live (pb=" + (pb != null) + " vis=" + (pb?.Visible ?? false) + " size=" + (pb != null ? (int)pb.Size.X + "x" + (int)pb.Size.Y : "?") + ")"); Fail("uidump"); }
                else Pass("uidump");
                if (!uichromeBtn || !uichromeBar) { Log("AUTOTEST uichrome FAIL: original chrome not mounted/live (btn=" + (mbTex != null ? mbTex.Width + "x" + mbTex.Height : "null") + " bar=" + (barTex != null ? barTex.Width + "x" + barTex.Height : "null") + ")"); Fail("uichrome"); }
                // R86 'uitoolbar' tree gate (R141 CORRECTION): the live-MODE button art is
                // kPeople people.bmp (200x50 = 4 frames of 50x50 — Res_CPanel.RT proves
                // kPeople 2010 is the mode dial's people button and kHouseBtn 4502 House.bmp
                // is the HOUSE TAB). The R86-era pin (108x30 House.bmp) codified the port's
                // art misuse; the desktop UCP now mounts the true 50x50 people frame. The
                // mobile path (UILiveButton, House.bmp via ResolveOrPng) is also corrected
                // to people art this round; the gate pins the corrected law.
                var frontend = ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var liveTex = frontend?.Frontend?.ModeSwitcher?.LiveButton?.Texture;
                if (liveTex == null && frontend?.Frontend?.DesktopUCP != null) liveTex = frontend.Frontend.DesktopUCP.LiveButton?.Texture;
                // R144: LiveGadget (108x100) is the TAB-COLUMN PLAQUE on the people
                // chrome (engine 1.2) — no longer a gauge backdrop inside bars.
                var gaugeTex = bmp?.PeopleChrome?.LiveGadget?.Texture
                    ?? (bmp?.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel)?.MotiveDisplays?[0]?.GaugeTex;
                bool uitoolbarLive = liveTex != null && liveTex.Width == 200 && liveTex.Height == 50;
                bool uitoolbarGauge = gaugeTex != null && gaugeTex.Width == 108 && gaugeTex.Height == 100;
                Log("AUTOTEST uitoolbar tree: live=" + uitoolbarLive + " (" + (liveTex != null ? liveTex.Width + "x" + liveTex.Height : "null") + ") gauge=" + uitoolbarGauge + " (" + (gaugeTex != null ? gaugeTex.Width + "x" + gaugeTex.Height : "null") + ")");
                if (!uitoolbarLive || !uitoolbarGauge) { Log("AUTOTEST uitoolbar FAIL: original toolbar chrome not mounted/live (live=" + (liveTex != null ? liveTex.Width + "x" + liveTex.Height : "null") + " gauge=" + (gaugeTex != null ? gaugeTex.Width + "x" + gaugeTex.Height : "null") + ")"); Fail("uitoolbar"); }
            }
            catch (Exception ue)
            {
                Log("AUTOTEST uidump EXC " + ue.GetType().Name + " " + ue.Message);
                try { gd?.SetRenderTarget(null); } catch { }
                Fail("uidump");
            }
        }

        // ROUND-141 'uisurvey' — eyes-on evidence harness: stabilize the in-lot HUD in
        // several canonical states and dump the FULL UI layer (all screens) plus an
        // ABSOLUTE-position tree of visible elements. The dumps are the working surface
        // for the UI/UX restoration rounds (duplicate icons, wrong spots, port chrome).
        private static void AbsWalk(FSO.Client.UI.Framework.UIElement el, int depth, int maxDepth, int ax, int ay, ref System.Collections.Generic.List<string> into)
        {
            if (el == null || depth > maxDepth) return;
            try
            {
                // R142: prune invisible/transparent subtrees entirely — children of a
                // hidden parent keep their own Visible=true (touch helpers, cheat box)
                // and polluted the r142 baseline tree with never-drawn elements.
                if (!el.Visible || el.Opacity <= 0.05f) return;
                int x = ax + (int)el.Position.X, y = ay + (int)el.Position.Y;
                {
                    // R142: captions + texture dims make survey trees self-identifying
                    // (the r142 baseline had an anonymous UICatButton/UILabel cluster
                    // on the switcher that took real archaeology to attribute — print
                    // the caption and sheet so the tree names its own elements).
                    var extra = "";
                    var lbl = el as FSO.Client.UI.Controls.UILabel;
                    if (lbl != null && lbl.Caption != null)
                    {
                        var cap = lbl.Caption.Replace("\n", " ");
                        if (cap.Length > 24) cap = cap.Substring(0, 24);
                        extra = " cap=\"" + cap + "\"";
                    }
                    var btnT = el.GetType().GetProperty("Texture")?.GetValue(el) as Microsoft.Xna.Framework.Graphics.Texture2D;
                    if (btnT != null) extra += " tex=" + btnT.Width + "x" + btnT.Height;
                    into.Add(new string(' ', depth * 2) + el.GetType().Name + " ABS=" + x + "," + y + " size=" + (int)el.Size.X + "x" + (int)el.Size.Y + extra);
                }
                var kids = (el as FSO.Client.UI.Framework.UIContainer)?.GetChildren();
                if (kids != null)
                {
                    int cnt = 0;
                    foreach (var k in kids.Take(400))
                    {
                        if (cnt++ >= 200) break;
                        AbsWalk(k, depth + 1, maxDepth, x, y, ref into);
                    }
                }
            }
            catch (Exception we) { into.Add("  " + el.GetType().Name + " EXC " + we.Message); }
        }

        private static void SurveyDump(string tag, System.Collections.Generic.List<string> tree)
        {
            var ui = FSO.Client.GameFacade.Screens;
            var gd = FSO.Client.GameFacade.GraphicsDevice;
            int w = gd.Viewport.Width, h = gd.Viewport.Height;
            if (w <= 0 || h <= 0) { w = gd.PresentationParameters.BackBufferWidth; h = gd.PresentationParameters.BackBufferHeight; }
            using (var rt = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(gd, 1, 0, SurfaceFormat.Color, w, h, DepthFormat.None))
            {
                gd.SetRenderTarget(rt);
                gd.Clear(new Color(0x72, 0x72, 0x72, 0xFF));
                // R144: warm-up pass — the FIRST explicit UI draw after an RT
                // switch paints nothing (cached containers hold backbuffer-era
                // textures); draw once, discard, then the saved pass is real.
                ui.SpriteBatch.UIBegin(BlendState.AlphaBlend, SpriteSortMode.Immediate);
                try
                {
                    var warm = ui.CurrentUIScreen;
                    foreach (var child in (warm as FSO.Client.UI.Framework.UIContainer)?.GetChildren() ?? new System.Collections.Generic.List<FSO.Client.UI.Framework.UIElement>())
                        child.PreDraw(ui.SpriteBatch);
                    warm?.PreDraw(ui.SpriteBatch);
                    warm?.Draw(ui.SpriteBatch);
                }
                catch { }
                ui.SpriteBatch.End();
                // The lot world is a separate 3D graphics layer, not a child of
                // the UI manager. Render its production backbuffer before the
                // HUD; otherwise in-lot survey artifacts have a false gray field.
                var world = (ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen)
                    ?.LotControl?.World;
                if (world != null)
                {
                    try { world.PreDraw(gd); }
                    catch (Exception we) { Log("AUTOTEST uisurvey world-predraw EXC " + we.GetType().Name + " " + we.Message); }
                }
                // The warm-up and world pre-draw churn render targets —
                // re-assert the survey target before the real composition.
                gd.SetRenderTarget(rt);
                gd.Clear(new Color(0x72, 0x72, 0x72, 0xFF));
                if (world != null)
                {
                    try { world.Draw(gd); }
                    catch (Exception we) { Log("AUTOTEST uisurvey world-draw EXC " + we.GetType().Name + " " + we.Message); }
                }
                ui.SpriteBatch.UIBegin(BlendState.AlphaBlend, SpriteSortMode.Immediate);
                try
                {
                    // Draw the complete manager tree exactly once. CurrentUIScreen
                    // is already mounted under UILayer.mainUI; drawing it explicitly
                    // again darkened antialiased text/overlays and made survey images
                    // diverge from the real frame composition.
                    ui.Draw(ui.SpriteBatch);
                } finally { ui.SpriteBatch.End(); }
                gd.SetRenderTarget(null);
                var path = System.IO.Path.Combine(FSO.Common.FSOEnvironment.UserDir, "uisurvey-" + tag + ".png");
                using (var fs = System.IO.File.Create(path))
                    rt.SaveAsPng(fs, rt.Width, rt.Height);
                Log("AUTOTEST uisurvey dump " + tag + " " + w + "x" + h + " -> " + path);
            }
            AbsWalk(ui.CurrentUIScreen, 0, 4, 0, 0, ref tree);
        }

        /// Hide dialogs that predate a visual fixture without answering or
        /// removing them. Close/RemoveDialog would desynchronize UILotControl's
        /// private BlockingDialog from the VM, while VMNetDialogResponseCmd would
        /// mutate GlobalBlockingDialog, the owner thread and simulation speed.
        /// Visibility-only suppression preserves all of that production state.
        private static void SuppressPreexistingDialogsForVisualArtifacts(string fixture)
        {
            var screen = FSO.Client.GameFacade.Screens?.CurrentUIScreen;
            if (screen == null) return;

            var latchBefore = _vm?.GlobalBlockingDialog;
            var speedBefore = _vm?.SpeedMultiplier ?? 0;
            var suppressed = 0;
            foreach (var dialog in screen.GetChildren()
                .OfType<Simitone.Client.UI.Controls.UIMobileDialog>().ToList())
            {
                if (_visualArtifactDialogVisibility.ContainsKey(dialog)) continue;
                _visualArtifactDialogVisibility.Add(dialog, dialog.Visible);
                if (!dialog.Visible) continue;
                dialog.Visible = false;
                suppressed++;
            }

            var vmStatePreserved = _vm == null
                || (object.ReferenceEquals(latchBefore, _vm.GlobalBlockingDialog)
                    && speedBefore == _vm.SpeedMultiplier);
            Log("AUTOTEST visual-fixture " + fixture + " suppressed-preexisting-dialogs="
                + suppressed + " tracked=" + _visualArtifactDialogVisibility.Count
                + " vm-state-preserved=" + vmStatePreserved);
        }

        private static void RestoreVisualArtifactDialogs()
        {
            var restored = 0;
            foreach (var entry in _visualArtifactDialogVisibility.ToList())
            {
                // A legitimate VM update may have removed/replaced the dialog
                // while the harness ran. Never resurrect a detached instance.
                if (entry.Key.Parent == null) continue;
                entry.Key.Visible = entry.Value;
                restored++;
            }
            if (_visualArtifactDialogVisibility.Count > 0)
                Log("AUTOTEST visual-fixture restored-dialogs=" + restored
                    + "/" + _visualArtifactDialogVisibility.Count);
            _visualArtifactDialogVisibility.Clear();
        }

        /// Render one production UI element in isolation and count emitted
        /// alpha pixels. This catches override code that paints after a base
        /// container has returned for Visible=false—the exact stale mood-bar /
        /// build-seam failure that a boolean-only composition probe misses.
        private static int RenderElementAlphaPixels(FSO.Client.UI.Framework.UIElement element)
        {
            if (element == null) return -1;
            var ui = FSO.Client.GameFacade.Screens;
            var gd = FSO.Client.GameFacade.GraphicsDevice;
            if (ui == null || gd == null) return -1;
            var w = Math.Max(1, gd.Viewport.Width);
            var h = Math.Max(1, gd.Viewport.Height);
            var previousTargets = gd.GetRenderTargets();
            var previousViewport = gd.Viewport;
            using (var rt = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(
                gd, 1, 0, SurfaceFormat.Color, w, h, DepthFormat.None))
            {
                var began = false;
                try
                {
                    gd.SetRenderTarget(rt);
                    gd.Clear(Color.Transparent);
                    ui.SpriteBatch.UIBegin(BlendState.AlphaBlend, SpriteSortMode.Immediate);
                    began = true;
                    element.Draw(ui.SpriteBatch);
                    ui.SpriteBatch.End();
                    began = false;
                    gd.SetRenderTarget(null);
                    var pixels = new Color[w * h];
                    rt.GetData(pixels);
                    var count = 0;
                    foreach (var pixel in pixels) if (pixel.A != 0) count++;
                    return count;
                }
                finally
                {
                    if (began) try { ui.SpriteBatch.End(); } catch { }
                    if (previousTargets.Length == 0) gd.SetRenderTarget(null);
                    else gd.SetRenderTargets(previousTargets);
                    gd.Viewport = previousViewport;
                }
            }
        }

        /// Assert that a custom-drawn control actually participates in the
        /// shared quick-tip pipeline. Merely assigning UIElement.Tooltip is
        /// inert unless UIUtils.GiveTooltip installed its update hook.
        private static bool HasTooltipHook(FSO.Client.UI.Framework.UIElement element)
        {
            if (element == null) return false;
            try
            {
                var field = typeof(FSO.Client.UI.Framework.UIElement).GetField("UpdateHooks",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                var hooks = field?.GetValue(element) as System.Collections.IEnumerable;
                if (hooks == null) return false;
                foreach (var hook in hooks)
                {
                    var del = hook as Delegate;
                    if (del?.Target is FSO.Client.Utils.UITooltipHandler) return true;
                }
            }
            catch { }
            return false;
        }

        /// Recalculate an element's complete root-to-leaf matrix chain. Live
        /// gates can mount a child between normal PreDraw passes; recalculating
        /// only that child would copy a stale/identity ancestor transform and
        /// falsely place a bottom-band overlay at negative screen coordinates.
        private static void CalculateElementMatrixChain(FSO.Client.UI.Framework.UIElement element)
        {
            var chain = new Stack<FSO.Client.UI.Framework.UIElement>();
            for (var current = element; current != null; current = current.Parent)
                chain.Push(current);
            while (chain.Count > 0) chain.Pop().CalculateMatrix();
        }

        /// Render one production UI element and sample a single local pixel.
        /// Unlike an alpha-count probe this preserves paint-order evidence: an
        /// opaque frame painted after its payload replaces the sentinel color.
        private static Color RenderElementPixel(FSO.Client.UI.Framework.UIElement element, int x, int y)
        {
            if (element == null) return Color.Transparent;
            var ui = FSO.Client.GameFacade.Screens;
            var gd = FSO.Client.GameFacade.GraphicsDevice;
            if (ui == null || gd == null) return Color.Transparent;
            var w = Math.Max(x + 1, Math.Max(1, gd.Viewport.Width));
            var h = Math.Max(y + 1, Math.Max(1, gd.Viewport.Height));
            var previousTargets = gd.GetRenderTargets();
            var previousViewport = gd.Viewport;
            using (var rt = FSO.Common.Utils.PPXDepthEngine.CreateRenderTarget(
                gd, 1, 0, SurfaceFormat.Color, w, h, DepthFormat.None))
            {
                var began = false;
                try
                {
                    gd.SetRenderTarget(rt);
                    gd.Clear(Color.Transparent);
                    ui.SpriteBatch.UIBegin(BlendState.AlphaBlend, SpriteSortMode.Immediate);
                    began = true;
                    element.Draw(ui.SpriteBatch);
                    ui.SpriteBatch.End();
                    began = false;
                    gd.SetRenderTarget(null);
                    var pixel = new Color[1];
                    rt.GetData(0, new Rectangle(x, y, 1, 1), pixel, 0, 1);
                    return pixel[0];
                }
                finally
                {
                    if (began) try { ui.SpriteBatch.End(); } catch { }
                    if (previousTargets.Length == 0) gd.SetRenderTarget(null);
                    else gd.SetRenderTargets(previousTargets);
                    gd.Viewport = previousViewport;
                }
            }
        }

        // R237 opt-in evidence capture for surfaces absent from the normal
        // survey. Uses production dialogs without invoking their action callbacks.
        private static void CheckUIAudit()
        {
            var game = GameFacade.Screens.CurrentUIScreen as TS1GameScreen;
            var mp = game?.Frontend?.MainPanel;
            if (mp == null) { Fail("uiaudit"); return; }
            var oldMode = mp.Mode;
            var oldVisible = mp.Visible;
            var oldActive = mp.PanelActive;
            var oldWidth = mp.CurWidth;
            var tree = new List<string>();
            try
            {
                SuppressPreexistingDialogsForVisualArtifacts("uiaudit");
                mp.SetMode(UI.Panels.UIMainPanelMode.OPTIONS);
                mp.Visible = true;
                mp.PanelActive = true;
                foreach (var fadeable in mp.GetFadeables())
                    if (fadeable != null) fadeable.Opacity = 1;
                var options = mp.SubPanel as UI.Panels.LiveSubpanels.UIOriginalOptionsPanel;
                if (options == null) throw new InvalidOperationException("Options did not mount");
                foreach (var section in new[] { "graphics", "sound", "play" })
                {
                    options.Invalidated = false;
                    options.ShowScreen(section);
                    if (!options.Invalidated) throw new InvalidOperationException("Options transition failed to invalidate: " + section);
                    // R238: transition itself must invalidate the cache. Compare
                    // immediate rendering with a redundant explicit refresh.
                    SurveyDump("audit-options-" + section + "-before-refresh", tree);
                    options.Invalidate();
                    SurveyDump("audit-options-" + section, tree);
                    // Exercise the production button press/release callback, too.
                    options.ShowMain();
                    int index = section == "graphics" ? 3 : section == "sound" ? 4 : 5;
                    var mouseEvent = typeof(FSO.Client.UI.Controls.UIButton).GetMethod("OnMouseEvent",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                    var button = options.Mains[index].Btn;
                    mouseEvent.Invoke(button, new object[] { FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, null });
                    mouseEvent.Invoke(button, new object[] { FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, null });
                    if (options.ActiveScreen != section || !options.Invalidated)
                        throw new InvalidOperationException("Options click did not transition/repaint: " + section);
                    SurveyDump("audit-options-" + section + "-click", tree);
                }
                mp.SetMode(UI.Panels.UIMainPanelMode.LIVE);
                foreach (var fadeable in mp.GetFadeables())
                    if (fadeable != null) fadeable.Opacity = 1;
                var caller = game.vm.Entities.OfType<VMAvatar>().FirstOrDefault();
                short callerNid = caller?.GetPersonData(VMPersonDataVariable.NeighborId) ?? (short)0;
                var factories = new Dictionary<string, Func<FSO.Client.UI.Framework.UIElement>>
                {
                    { "budget", () => new UI.Panels.UIOriginalBudgetDialog(game) },
                    { "help", () => new UI.Panels.UIOriginalHelpDialog() },
                    { "phonebook", () => new UI.Panels.UIOriginalPhoneBookDialog(callerNid, game.vm) },
                    { "scrapbook", () => new UI.Panels.UIOriginalScrapbookDialog() }
                };
                foreach (var factory in factories)
                {
                    var savedPages = UI.Model.OriginalSnapshotAlbum.Pages;
                    var savedPage = UI.Model.OriginalSnapshotAlbum.CurrentPage;
                    Microsoft.Xna.Framework.Graphics.Texture2D fixturePhoto = null;
                    if (factory.Key == "scrapbook")
                    {
                        fixturePhoto = new Microsoft.Xna.Framework.Graphics.Texture2D(GameFacade.GraphicsDevice,200,150);
                        fixturePhoto.SetData(Enumerable.Repeat(new Color(50,100,150),200*150).ToArray());
                        UI.Model.OriginalSnapshotAlbum.Pages = new List<UI.Model.OriginalSnapshotPage> {
                            new UI.Model.OriginalSnapshotPage { FileName="audit-fixture", Photo=fixturePhoto,
                                Description="A test photo with an editable caption.\nThe second line checks native font spacing and selection." }
                        };
                        UI.Model.OriginalSnapshotAlbum.CurrentPage = 0;
                    }
                    var neighbor = Content.Get().Neighborhood.GetNeighborByID(callerNid);
                    var oldRelationships = neighbor?.Relationships;
                    FSO.Client.UI.Framework.UIElement dialog = null;
                    try
                    {
                        if (factory.Key == "phonebook" && neighbor != null)
                        {
                            var contacts = Content.Get().Neighborhood.Neighbors.Entries.Where(n => n?.PersonData != null
                                && n.PersonData.Length > (int)VMPersonDataVariable.TS1FamilyNumber
                                && n.PersonData[(int)VMPersonDataVariable.TS1FamilyNumber] > 0
                                && n.PersonData[(int)VMPersonDataVariable.TS1FamilyNumber] <= 10
                                && n.PersonData[(int)VMPersonDataVariable.Gender] <= 1);
                            neighbor.Relationships = contacts.ToDictionary(n => (int)n.NeighbourID,n => new List<short>{50,50});
                        }
                        dialog = factory.Value();
                        FSO.Client.UI.Framework.UIScreen.GlobalShowDialog(dialog, true);
                        var bounds = dialog.GetBounds();
                        bool fits = dialog.X + bounds.X >= 0 && dialog.Y + bounds.Y >= 0
                            && dialog.X + bounds.Right <= GlobalSettings.Default.GraphicsWidth
                            && dialog.Y + bounds.Bottom <= GlobalSettings.Default.GraphicsHeight;
                        Log("AUTOTEST uiaudit fit="+factory.Key+":"+fits+" logical="
                            +GlobalSettings.Default.GraphicsWidth+"x"+GlobalSettings.Default.GraphicsHeight
                            +" dpi="+FSOEnvironment.DPIScaleFactor+" position="+dialog.Position+" bounds="+bounds);
                        if (!fits) throw new InvalidOperationException("Native dialog clipped by viewport: " + factory.Key);
                        SurveyDump("audit-" + factory.Key, tree);
                        var phone = dialog as UI.Panels.UIOriginalPhoneBookDialog;
                        if (phone != null)
                        {
                            phone.SelectFamily(0);
                            phone.FamilyList.SetItems(Enumerable.Range(0,47).Select(i => "Audit family " + i));
                            phone.FamilyList.ScrollBy(1000);
                            SurveyDump("audit-phonebook-overflow", tree);
                        }
                        var scrapbook = dialog as UI.Panels.UIOriginalScrapbookDialog;
                        if (scrapbook != null)
                        {
                            scrapbook.Caption.OnFocusChanged(FSO.Common.Rendering.Framework.IO.FocusEvent.FocusIn);
                            scrapbook.Caption.SetSelection(0,12);
                            SurveyDump("audit-scrapbook-editing",tree);
                            scrapbook.Caption.Blur();
                        }
                    }
                    finally
                    {
                        if (dialog != null) FSO.Client.UI.Framework.UIScreen.RemoveDialog(dialog);
                        if (neighbor != null) neighbor.Relationships = oldRelationships;
                        UI.Model.OriginalSnapshotAlbum.Pages = savedPages;
                        UI.Model.OriginalSnapshotAlbum.CurrentPage = savedPage;
                        fixturePhoto?.Dispose();
                    }
                }
                Log("AUTOTEST uiaudit captured=15 visual-review-required=True");
                Pass("uiaudit");
            }
            catch (Exception ex)
            {
                Log("AUTOTEST uiaudit EXC " + ex);
                Fail("uiaudit");
            }
            finally
            {
                mp.SetMode(oldMode);
                mp.Visible = oldVisible;
                mp.PanelActive = oldActive;
                mp.CurWidth = oldWidth;
            }
        }

        private static void CheckUISurvey()
        {
            try
            {
                var ui = FSO.Client.GameFacade.Screens;
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (gd == null || ui == null) { Log("AUTOTEST uisurvey: unavailable (no device/ui)"); Fail("uisurvey"); return; }
                var scr = ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var mp = scr?.Frontend?.MainPanel;
                if (mp == null) { Log("AUTOTEST uisurvey: no in-lot screen (screen=" + (ui.CurrentUIScreen?.GetType().Name ?? "null") + ")"); Fail("uisurvey"); return; }
                SuppressPreexistingDialogsForVisualArtifacts("uisurvey");
                // This survey runs in the same tick that the lot becomes ready,
                // before the desktop placement helper's first Update hides its
                // default-visible touch controls.
                if (scr.LotControl?.ArchTouch != null) scr.LotControl.ArchTouch.Visible = false;
                var tree = new System.Collections.Generic.List<string>();
                var popupSurveyOk = false;
                var querySurveyOk = false;
                var cameraSurveyOk = false;
                var popupSurveyIndex = -1;
                Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel popupSurveyPanel = null;

                // State A: LIVE, panel open, Mood category (the everyday HUD).
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                    mp.Visible = true;
                    mp.PanelActive = true;
                    mp.CurWidth = Math.Max(500, gd.Viewport.Width - mp.X - 40);
                    mp.Switcher_OnCategorySelect(0);
                    var liveSurveyUpdate = new FSO.Common.Rendering.Framework.Model.UpdateState();
                    mp.PeopleChrome?.RefreshWebcams();
                    mp.PeopleChrome?.Update(liveSurveyUpdate);
                    mp.SubPanel?.Update(liveSurveyUpdate);
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey openpanel EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state A: live panel open ==");
                SurveyDump("live", tree);
                var surveyMotive = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel;
                if (surveyMotive != null)
                {
                    surveyMotive.ToggleMotivePopupForProbe(0);
                    tree.Add("== state A1: motive live popup ==");
                    SurveyDump("live-popup", tree);
                    surveyMotive.CloseMotivePopup();
                    surveyMotive.ToggleMotivePopupForProbe(5);
                    tree.Add("== state A1b: text-only Social motive popup ==");
                    SurveyDump("live-social-popup", tree);
                    surveyMotive.CloseMotivePopup();
                }

                // State A2: the compact decoded Job panel. This catches both
                // stale-Mood overlap and the former three-column overflow.
                try
                {
                    mp.Switcher_OnCategorySelect(1);
                    mp.SubPanel?.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey jobpanel EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state A2: live job panel ==");
                SurveyDump("job", tree);
                var surveyJobPopup = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel;
                if (surveyJobPopup != null)
                {
                    surveyJobPopup.ToggleAdultSummaryPopup(0);
                    if (surveyJobPopup.JobFamilyPopup != null)
                    {
                        tree.Add("== state A2b: job live popup ==");
                        SurveyDump("job-popup", tree);
                    }
                    surveyJobPopup.CloseJobFamilyPopup();
                    surveyJobPopup.ToggleAdultSkillPopup(5);
                    if (surveyJobPopup.JobFamilyPopup != null)
                    {
                        tree.Add("== state A2c: two-selector Creativity popup ==");
                        SurveyDump("job-skill-popup", tree);
                    }
                    surveyJobPopup.CloseJobFamilyPopup();
                }

                // State A3: the executable's child Report Card replacement.
                // Temporarily drive the same selected-avatar words used by
                // PersonFinder, then restore them before advancing the survey.
                var surveyAvatar = scr.SelectedAvatar;
                if (surveyAvatar != null)
                {
                    var surveyAge = surveyAvatar.GetPersonData(VMPersonDataVariable.PersonsAge);
                    var surveyGrade = surveyAvatar.GetPersonData(VMPersonDataVariable.JobPromotionLevel);
                    try
                    {
                        surveyAvatar.SetPersonData(VMPersonDataVariable.PersonsAge, (short)9);
                        surveyAvatar.SetPersonData(VMPersonDataVariable.JobPromotionLevel, (short)4);
                        mp.SubPanel?.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                        foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                        if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                        tree.Add("== state A3: child report card ==");
                        SurveyDump("reportcard", tree);
                    }
                    catch (Exception pe) { Log("AUTOTEST uisurvey reportcard EXC " + pe.GetType().Name + " " + pe.Message); }
                    finally
                    {
                        surveyAvatar.SetPersonData(VMPersonDataVariable.PersonsAge, surveyAge);
                        surveyAvatar.SetPersonData(VMPersonDataVariable.JobPromotionLevel, surveyGrade);
                        mp.SubPanel?.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                    }
                }

                // States A3b-A3d: the three expansion-era Job-tab surfaces
                // that cannot be selected by a top-level tab. Drive the same
                // private router targets as production, update their real
                // controls, and restore every person-data word afterwards.
                var surveyJob = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel;
                if (surveyJob != null && surveyAvatar != null)
                {
                    var surveyJobType = typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel);
                    var surveyFlags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                    var setSurveyMode = surveyJobType.GetMethod("SetDesktopMode", surveyFlags);
                    var updateSurveyPet = surveyJobType.GetMethod("UpdatePetSkills", surveyFlags);
                    var updateSurveyFame = surveyJobType.GetMethod("UpdateFame", surveyFlags);
                    var surveyMode = surveyJob.DesktopMode;
                    var surveyFameScore = surveyAvatar.GetPersonData(VMPersonDataVariable.TS1FameScore);
                    var surveyFameLevel = surveyAvatar.GetPersonData(VMPersonDataVariable.TS1FameStarPower);
                    try
                    {
                        setSurveyMode?.Invoke(surveyJob, new object[] {
                            Simitone.Client.UI.Panels.LiveSubpanels.UIDesktopJobMode.DogSkills });
                        updateSurveyPet?.Invoke(surveyJob, new object[] { surveyAvatar, false });
                        tree.Add("== state A3b: dog skills panel ==");
                        SurveyDump("dog-skills", tree);

                        setSurveyMode?.Invoke(surveyJob, new object[] {
                            Simitone.Client.UI.Panels.LiveSubpanels.UIDesktopJobMode.CatSkills });
                        updateSurveyPet?.Invoke(surveyJob, new object[] { surveyAvatar, true });
                        tree.Add("== state A3c: cat skills panel ==");
                        SurveyDump("cat-skills", tree);

                        surveyAvatar.SetPersonData(VMPersonDataVariable.TS1FameScore, (short)7);
                        surveyAvatar.SetPersonData(VMPersonDataVariable.TS1FameStarPower, (short)4);
                        setSurveyMode?.Invoke(surveyJob, new object[] {
                            Simitone.Client.UI.Panels.LiveSubpanels.UIDesktopJobMode.Fame });
                        updateSurveyFame?.Invoke(surveyJob, new object[] { surveyAvatar });
                        tree.Add("== state A3d: fame panel ==");
                        SurveyDump("fame", tree);
                    }
                    catch (Exception pe)
                    {
                        Log("AUTOTEST uisurvey job-family EXC " + pe.GetType().Name + " " + pe.Message);
                    }
                    finally
                    {
                        surveyAvatar.SetPersonData(VMPersonDataVariable.TS1FameScore, surveyFameScore);
                        surveyAvatar.SetPersonData(VMPersonDataVariable.TS1FameStarPower, surveyFameLevel);
                        setSurveyMode?.Invoke(surveyJob, new object[] { surveyMode });
                        surveyJob.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                    }
                }

                // States A4-A8: every remaining standard desktop people tab.
                // These are deliberately exercised through the production tab
                // switcher without pruning stale children: overlap from a bad
                // SetSubpanel transition must remain visible in the artifact.
                var standardPeoplePanels = new[]
                {
                    Tuple.Create(2, "personality", "personality panel"),
                    Tuple.Create(3, "relationship", "relationship panel"),
                    Tuple.Create(5, "house", "house panel"),
                    Tuple.Create(6, "interest", "interest panel"),
                    Tuple.Create(7, "gift", "gift/inventory panel"),
                };
                var standardState = 4;
                foreach (var panelState in standardPeoplePanels)
                {
                    try
                    {
                        mp.Switcher_OnCategorySelect(panelState.Item1);
                        mp.SubPanel?.Update(new FSO.Common.Rendering.Framework.Model.UpdateState());
                        foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                        if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                    }
                    catch (Exception pe)
                    {
                        Log("AUTOTEST uisurvey " + panelState.Item2 + " EXC "
                            + pe.GetType().Name + " " + pe.Message);
                    }
                    tree.Add("== state A" + standardState + ": " + panelState.Item3 + " ==");
                    SurveyDump(panelState.Item2, tree);
                    // Capture the standard panel's production live-popup too.
                    // These frames make clipping, stale-client retargeting and
                    // art-pane mistakes visible instead of testing only the
                    // settled 100px band.
                    var personalitySurvey = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIPersonalitySubpanel;
                    var relationshipSurvey = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIRelationshipSubpanel;
                    var houseSurvey = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIHouseSubpanel;
                    var interestSurvey = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel;
                    var giftSurvey = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel;
                    // The corpus household has no inventory tokens. Mount the
                    // same GUID-0 fallback/count fixture used by uiinterest so
                    // the seventh standard panel gets a populated pixel survey
                    // too; keep the ordinary "gift" capture above as the real
                    // empty-household state.
                    Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftCell giftSurveyFixture = null;
                    if (giftSurvey != null && giftSurvey.Cells.Count == 0)
                    {
                        giftSurveyFixture = new Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftCell(
                            new FSO.Files.Formats.IFF.Chunks.InventoryItem { GUID = 0, Count = 12 });
                        giftSurveyFixture.ItemName = "Gift Fixture";
                        giftSurveyFixture.ItemDescription = "Populated inventory visual fixture.";
                        giftSurveyFixture.Tooltip = giftSurveyFixture.ItemName;
                        int giftContentTop = (giftSurvey.HostTitle?.Font?.LineHeight ?? 10) + 5;
                        giftSurveyFixture.Position = new Vector2(
                            Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel.ContentLeft,
                            giftContentTop + (100 - giftContentTop - 60) / 2);
                        giftSurvey.Add(giftSurveyFixture);
                        giftSurvey.Cells.Add(giftSurveyFixture);
                        tree.Add("== state A" + standardState + "a: populated gift visual fixture ==");
                        SurveyDump("gift-populated", tree);
                    }
                    if (personalitySurvey != null)
                        personalitySurvey.ToggleTraitPopupForProbe(0);
                    else if (relationshipSurvey != null && relationshipSurvey.Cards.Count > 0)
                        relationshipSurvey.SelectRelationship(relationshipSurvey.Cards[0]);
                    else if (houseSurvey != null)
                        houseSurvey.SelectItem(0);
                    else if (interestSurvey != null)
                        interestSurvey.ToggleTopicPopupForProbe(interestSurvey.VisibleTopicSequence[0]);
                    else if (giftSurvey != null && giftSurvey.Cells.Count > 0)
                        giftSurvey.TogglePopup(giftSurvey.Cells[0]);

                    bool standardPopupVisible = personalitySurvey?.CurrentPopup != null
                        || relationshipSurvey?.CurrentPopup != null
                        || houseSurvey?.CurrentPopup != null
                        || interestSurvey?.CurrentPopup != null
                        || giftSurvey?.CurrentPopup != null;
                    if (standardPopupVisible)
                    {
                        tree.Add("== state A" + standardState + "b: " + panelState.Item3 + " live popup ==");
                        SurveyDump(panelState.Item2 + "-popup", tree);
                    }
                    if (giftSurveyFixture != null)
                    {
                        giftSurvey.ClosePopup();
                        giftSurvey.Remove(giftSurveyFixture);
                        giftSurvey.Cells.Remove(giftSurveyFixture);
                    }
                    standardState++;
                }

                // State B: UCP island alone (panel closed) — the bottom-left dial plate.
                try
                {
                    mp.Visible = false;
                    mp.PanelActive = false;
                    mp.CurWidth = 0;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey closepanel EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state B: ucp island ==");
                SurveyDump("ucp", tree);

                // State B2: the recovered Camera mode. This preserves direct
                // visual evidence for the formerly empty cyan bubble above
                // Options and for the complete cWinCamPanel replacement band.
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.CAMERA);
                    mp.Visible = true;
                    mp.PanelActive = true;
                    mp.CurWidth = Math.Max(500, gd.Viewport.Width - mp.X - 40);
                    cameraSurveyOk = mp.CameraChrome != null && mp.CameraChrome.Visible
                        && mp.SubPanel == null && !mp.Switcher.MainButton.Visible;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey camera EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state B2: camera panel ==");
                SurveyDump("camera", tree);

                // R239: retain rendered evidence of the world frame and its
                // disappearance when a child UI surface takes pointer input.
                if (scr.CameraOverlay != null)
                {
                    var overlay = scr.CameraOverlay;
                    var probe = new FSO.Common.Rendering.Framework.Model.UpdateState {
                        WindowFocused=true, Time=new GameTime(),
                        MouseState=new Microsoft.Xna.Framework.Input.MouseState(
                            (int)(400*FSOEnvironment.DPIScaleFactor), (int)(350*FSOEnvironment.DPIScaleFactor),0,
                            Microsoft.Xna.Framework.Input.ButtonState.Released,Microsoft.Xna.Framework.Input.ButtonState.Released,
                            Microsoft.Xna.Framework.Input.ButtonState.Released,Microsoft.Xna.Framework.Input.ButtonState.Released,
                            Microsoft.Xna.Framework.Input.ButtonState.Released)
                    };
                    bool wasActive=overlay.CameraActive, wasOver=overlay.PointerOverWorld;
                    try
                    {
                        overlay.SetCameraActive(true);
                        overlay.Update(probe);
                        overlay.OnMouse(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver,probe);
                        SurveyDump("camera-frame",tree);
                        overlay.OnMouse(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut,probe);
                        SurveyDump("camera-frame-hidden",tree);
                    }
                    finally
                    {
                        overlay.SetCameraActive(wasActive);
                        if (wasActive && wasOver) overlay.OnMouse(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver,probe);
                    }
                }

                // State C: BUY mode with the engine band (R145: SetMode applies
                // the engine entry — room main, Living, default subsort grid).
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUY);
                    mp.Visible = true;
                    mp.PanelActive = true;
                    mp.CurWidth = Math.Max(500, gd.Viewport.Width - mp.X - 40);
                    // R142: UISubpanel.Kill() removes after a 300ms tween — the survey
                    // dumps instantly, so the killed LIVE subpanel would still hang in
                    // the tree (and the opacity-forcing below resurrect it to full).
                    // Detach anything that is not the current subpanel before dumping.
                    var stale = new System.Collections.Generic.List<FSO.Client.UI.Framework.UIElement>();
                    foreach (var c in mp.GetChildren())
                        if (c is Simitone.Client.UI.Panels.LiveSubpanels.UISubpanel && !object.ReferenceEquals(c, mp.SubPanel)) stale.Add(c);
                    foreach (var c in stale) mp.Remove(c);
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey buymode EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state C: buy catalog ==");
                SurveyDump("buy", tree);

                // State C2: exercise the real hover-popup path and preserve a
                // visual artifact for the paired-icon crop, natural-size blit,
                // word wrapping, and measured-height anchor. Choose the
                // visible item with the most wrapped lines so the dump proves
                // the expanding case rather than only the 127px minimum.
                try
                {
                    var buy = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel;
                    var show = typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel).GetMethod(
                        "ShowBandPopup", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                    var best = -1;
                    var bestLines = -1;
                    var bestDescriptionLength = -1;
                    var surveyFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(8, gd);
                    if (buy != null && show != null)
                    {
                        // Measure every source through the production paragraph
                        // font/362px law without opening its popup. This picks
                        // the genuinely tallest wrapped fixture while invoking
                        // the expensive iconic-object compositor only once.
                        for (var i = 0; i < buy.BandCells.Count; i++)
                        {
                            var elem = buy.BandCells[i].Element;
                            string description = null;
                            try
                            {
                                if (elem.Special?.Res != null)
                                    description = elem.Special.Res.GetDescription(elem.Special.ResID);
                                else if (elem.Item.GUID != 0 && elem.Item.GUID != uint.MaxValue)
                                {
                                    var worldObj = FSO.Content.Content.Get().WorldObjects.Get(elem.Item.GUID);
                                    description = worldObj?.Resource?.Get<CTSS>(worldObj.OBJ.CatalogStringsID)?.GetString(1);
                                }
                            }
                            catch { }
                            var length = description?.Length ?? 0;
                            var lines = 0;
                            if (!string.IsNullOrEmpty(description) && surveyFont != null)
                            {
                                var paragraph = new Simitone.Client.UI.Controls.UIOriginalParagraph(surveyFont)
                                {
                                    Text = description,
                                    MaxWidth = Simitone.Client.UI.Panels.UIOriginalCatalogPopup.DESCRIPTION_MAX_WIDTH,
                                    LineHeight = surveyFont.LineHeight
                                };
                                paragraph.WrapIfNeeded();
                                lines = paragraph.GetChildren()
                                    .OfType<Simitone.Client.UI.Controls.UIOriginalText>().Count();
                            }
                            if (lines > bestLines || (lines == bestLines && length > bestDescriptionLength))
                            {
                                best = i;
                                bestLines = lines;
                                bestDescriptionLength = length;
                            }
                        }
                        if (best >= 0)
                        {
                            show.Invoke(buy, new object[] { best, buy.BandCells[best] });
                            bestLines = buy.BandPopup?.DescriptionLineCount ?? 0;
                        }
                        popupSurveyOk = best >= 0 && bestLines > 1 && buy.BandPopup != null
                            && buy.BandPopup.Visible && buy.BandPopup.Size.X == 559 && buy.BandPopup.Size.Y > 127;
                        if (popupSurveyOk)
                        {
                            popupSurveyPanel = buy;
                            popupSurveyIndex = best;
                        }
                        Log("AUTOTEST uisurvey buy-popup cell=" + best + " lines=" + bestLines
                            + " descChars=" + bestDescriptionLength
                            + " size=" + (buy.BandPopup?.Size.ToString() ?? "null") + " ok=" + popupSurveyOk);
                    }
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey buy-popup EXC " + pe.GetType().Name + " " + pe.Message); }
                if (popupSurveyOk)
                {
                    tree.Add("== state C2: buy catalog hover popup ==");
                    SurveyDump("buy-popup", tree);
                }
                else Log("AUTOTEST uisurvey buy-popup FAILED: no visible multi-line production popup; artifact not accepted");

                // State C3/C4: production product click -> complete PopupInfo
                // panel, followed by the world-entry hide. This is the exact
                // pair that formerly appeared low/cropped and then remained as
                // a 45px slice. Keep both visual artifacts: one full card and
                // one clean catalog with no residual strip.
                try
                {
                    if (popupSurveyPanel != null && popupSurveyIndex >= 0)
                    {
                        var click = typeof(Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel).GetMethod(
                            "BandCellClick", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                        click?.Invoke(popupSurveyPanel, new object[] {
                            popupSurveyIndex, popupSurveyPanel.BandCells[popupSurveyIndex] });
                        var qp = scr.LotControl.QueryPanel;
                        bool full = qp != null && qp.Shown && qp.ShowPCT == 1f
                            && Math.Abs(qp.Size.Y - qp.FullHeight) < 0.01f
                            && Math.Abs(qp.Y + 5 + qp.FullHeight) < 0.01f
                            && qp.Visible && qp.Opacity == 1f
                            && (popupSurveyPanel.BandPopup == null || !popupSurveyPanel.BandPopup.Visible);
                        tree.Add("== state C3: selected product full description ==");
                        SurveyDump("buy-query", tree);

                        qp?.SetShown(false);
                        bool hidden = qp != null && !qp.Shown && qp.ShowPCT == 1f
                            && Math.Abs(qp.Size.Y - qp.FullHeight) < 0.01f
                            && !qp.Visible && qp.Opacity == 0f;
                        tree.Add("== state C4: selected product description hidden ==");
                        SurveyDump("buy-query-hidden", tree);
                        querySurveyOk = full && hidden;
                        Log("AUTOTEST uisurvey buy-query full=" + full + " hidden=" + hidden
                            + " size=" + (qp?.Size.ToString() ?? "null")
                            + " fullH=" + (qp?.FullHeight.ToString() ?? "null")
                            + " y=" + (qp?.Y.ToString() ?? "null") + " ok=" + querySurveyOk);
                        popupSurveyPanel.Deselect();
                    }
                }
                catch (Exception qe)
                {
                    Log("AUTOTEST uisurvey buy-query EXC " + qe.GetType().Name + " " + qe.Message);
                    try { popupSurveyPanel?.Deselect(); } catch { }
                }
                if (!querySurveyOk)
                    Log("AUTOTEST uisurvey buy-query FAILED: full/hidden production description artifacts not accepted");

                // State D: BUILD mode — the cWinArch band (12 tools + undo/redo)
                // plus each special row implicated by the user's captures.
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUILD);
                    mp.Visible = true;
                    mp.PanelActive = true;
                    mp.CurWidth = Math.Max(500, gd.Viewport.Width - mp.X - 40);
                    if (mp.ArchChrome != null) mp.ArchChrome.SelectTool(0);   // Terrain four-state row
                    var stale2 = new System.Collections.Generic.List<FSO.Client.UI.Framework.UIElement>();
                    foreach (var c in mp.GetChildren())
                        if (c is Simitone.Client.UI.Panels.LiveSubpanels.UISubpanel && !object.ReferenceEquals(c, mp.SubPanel)) stale2.Add(c);
                    foreach (var c in stale2) mp.Remove(c);
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey buildmode EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state D0: build terrain row ==");
                SurveyDump("build-terrain", tree);

                try
                {
                    if (mp.ArchChrome != null) mp.ArchChrome.SelectTool(1);   // Pool + pond cells
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey watermode EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state D1: build pool/water row ==");
                SurveyDump("build-water", tree);

                try
                {
                    if (mp.ArchChrome != null) mp.ArchChrome.SelectTool(2);   // Wall two-state row
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey wallmode EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state D2: build wall row ==");
                SurveyDump("build", tree);
                SurveyDump("build-wall", tree);

                // State D3: the ROOF tool swaps the pattern row for the engine
                // roof panel (R145 section 7).
                try
                {
                    if (mp.ArchChrome != null) mp.ArchChrome.SelectTool(10);
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey roofmode EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state D3: roof panel ==");
                SurveyDump("roof", tree);

                // State F: the COMMUNITY buy band (R146) — the expansion plaque
                // set on the band chrome (chrome-level: lot-independent art/
                // anchors/tooltips; the current lot stays a home lot).
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.BUY);
                    if (mp.BuyChrome != null)
                    {
                        mp.BuyChrome.SetLotMode(Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Community);
                        mp.BuyChrome.ApplyEngineDefault();
                        var cpanel = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(scr, (sbyte)0,
                            Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Community);
                        mp.SetSubpanel(cpanel);
                        mp.BuyChrome.SubCats = cpanel.CurrentSubCats;
                        mp.BuyChrome.RelayoutSub(cpanel.CurrentSubCats);
                    }
                    var staleF = new System.Collections.Generic.List<FSO.Client.UI.Framework.UIElement>();
                    foreach (var c in mp.GetChildren())
                        if (c is Simitone.Client.UI.Panels.LiveSubpanels.UISubpanel && !object.ReferenceEquals(c, mp.SubPanel)) staleF.Add(c);
                    foreach (var c in staleF) mp.Remove(c);
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey expband EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state F: community buy band ==");
                SurveyDump("expband", tree);

                // State G (R178): Studio Town's unopened MAIN row — the exact
                // reported Food/Shops/Studio/Spa surface. All four category
                // plaques must use their native members in normal frame 0.
                try
                {
                    if (mp.BuyChrome != null)
                    {
                        mp.BuyChrome.SetLotMode(Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Studiotown);
                        mp.BuyChrome.ApplyEngineDefault();
                        var studioPanel = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(scr, (sbyte)0,
                            Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Studiotown);
                        mp.SetSubpanel(studioPanel);
                        mp.BuyChrome.SubCats = studioPanel.CurrentSubCats;
                    }
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey studio-main EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state G: Studio Town buy main row ==");
                SurveyDump("studio-main", tree);

                // State H (R176): Magic Town's unopened MAIN row. This is the
                // exact reported surface: semantic MagiCo/Outdoors art, native
                // tooltip routing, and all plaques in normal frame 0.
                try
                {
                    if (mp.BuyChrome != null)
                    {
                        mp.BuyChrome.SetLotMode(Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Magictown);
                        mp.BuyChrome.ApplyEngineDefault();
                        var magicPanel = new Simitone.Client.UI.Panels.LiveSubpanels.UIBuyBrowsePanel(scr, (sbyte)0,
                            Simitone.Client.UI.Panels.LiveSubpanels.UICatalogMode.Magictown);
                        mp.SetSubpanel(magicPanel);
                        mp.BuyChrome.SubCats = magicPanel.CurrentSubCats;
                    }
                    foreach (var f in mp.GetFadeables()) if (f != null) f.Opacity = 1;
                    if (mp.SubPanel != null) mp.SubPanel.Opacity = 1;
                }
                catch (Exception pe) { Log("AUTOTEST uisurvey magic-main EXC " + pe.GetType().Name + " " + pe.Message); }
                tree.Add("== state H: Magic Town buy main row ==");
                SurveyDump("magic-main", tree);

                // States Z* (R146->R147 CONCLUSION): the far-zoom black-out
                // differential battery ran here for two rounds. Findings, kept
                // for the record in tools/iff-dump/r147/: the live game keeps
                // PreciseZoom=1 and only switches the zoom ENUM; the forced
                // PreciseZoom 0.25/0.5 states this battery measured never occur
                // live, and the "black terrain" they showed was the beyond-lot
                // VOID seen through mismatched synchronous framing, not a
                // terrain render failure. The REAL defect — visible in the
                // user's photos — is the camera roaming past the lot terrain
                // into that void (BoundView never bounded a TS1 lot). Fixed in
                // the engine this round; pinned by the 'uizoomcage' check. The
                // live 'zoomlive' probe below stays as the user-flow evidence.
                var world = scr.LotControl?.World;
                var oldZoom = world != null ? world.State.Zoom : FSO.LotView.WorldZoom.Near;
                var oldPrecise = world != null ? world.State.PreciseZoom : 1f;
                try
                {
                    if (world != null)
                    {
                        var bpZ = world.Architecture.Blueprint;
                        // TerrainComponent.Size is private; the vertex count gives
                        // the mesh: numQuads*4 vertices, numQuads = w*h.
                        int meshTiles = (bpZ.Terrain?.VertexBuffer != null) ? bpZ.Terrain.VertexBuffer.VertexCount / 4 : -1;
                        Log("AUTOTEST uisurvey terrain-extent meshTiles=" + meshTiles
                            + " lot=" + bpZ.Width + "x" + bpZ.Height
                            + " center=" + world.State.CenterTile.X.ToString("0.#") + "," + world.State.CenterTile.Y.ToString("0.#"));
                    }
                }
                catch (Exception te) { Log("AUTOTEST uisurvey terrain-extent EXC " + te.GetType().Name); }
                // diagnostics: did the world render into the PPX backbuffer at all?
                try
                {
                    if (world != null)
                        Log("AUTOTEST uisurvey zoom-diag useBackbuffer=" + world.UseBackbuffer
                            + " visible=" + world.Visible
                            + " zoom=" + world.State.Zoom + " pzoom=" + world.State.PreciseZoom
                            + " bbscale=" + world.BackbufferScale);
                    var bb = FSO.Common.Utils.PPXDepthEngine.GetBackbuffer();
                    if (bb != null)
                    {
                        Log("AUTOTEST uisurvey zoom-diag ppxBB=" + bb.Width + "x" + bb.Height);
                        var bbd = new Color[bb.Width * bb.Height];
                        try { bb.GetData(bbd); int dark = 0; int tot = 0; for (int i = 0; i < bbd.Length; i += 97) { tot++; if (bbd[i].R + bbd[i].G + bbd[i].B < 30) dark++; } Log("AUTOTEST uisurvey zoom-diag ppxBB dark-sampled=" + dark + "/" + tot); }
                        catch (Exception ge) { Log("AUTOTEST uisurvey zoom-diag ppxBB get EXC " + ge.GetType().Name); }
                    }
                    else Log("AUTOTEST uisurvey zoom-diag ppxBB=null");
                }
                catch (Exception de) { Log("AUTOTEST uisurvey zoom-diag EXC " + de.GetType().Name + " " + de.Message); }
                try
                {
                    if (world != null)
                    {
                        world.State.Zoom = oldZoom;
                        world.State.PreciseZoom = oldPrecise;
                        world.BackbufferScale = 1f;
                    }
                }
                catch (Exception ze) { Log("AUTOTEST uisurvey zoomrestore EXC " + ze.GetType().Name + " " + ze.Message); }

                // Restore live mode so later checks/soaks see the canonical state.
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                    mp.Visible = false;
                    mp.PanelActive = false;
                    mp.CurWidth = 0;
                }
                catch { }

                foreach (var t in tree.Take(400)) Log("AUTOTEST uisurvey-tree " + t);
                // R147: hand off to the LIVE zoom probe (runs across the next
                // ~320 real game frames via StateSample ticks: baseline, far
                // tween, medium return, scroll-to-corner — the cage must keep
                // every census healthy).
                _zoomLiveFrame = 0;
                _zoomLivePhase = 1;
                Log("AUTOTEST zoomlive ARM (baseline 30 frames, then far, then medium, then scroll)");
                var completeSurvey = popupSurveyOk && querySurveyOk && cameraSurveyOk
                    && _neighborhoodSurveyCaptured;
                if (!_neighborhoodSurveyCaptured)
                    Log("AUTOTEST uisurvey FAILED: neighborhood artifact was not captured");
                if (completeSurvey) Pass("uisurvey"); else Fail("uisurvey");
            }
            catch (Exception se)
            {
                Log("AUTOTEST uisurvey EXC " + se.GetType().Name + " " + se.Message);
                try { FSO.Client.GameFacade.GraphicsDevice?.SetRenderTarget(null); } catch { }
                Fail("uisurvey");
            }
        }

        // ROUND-147 'uizoomcage' — the camera cage law (see the call-site
        // comment). Slams the camera far off-lot at each zoom in all four
        // diagonal extremes and asserts BoundView (inside world.PreDraw)
        // clamps every one back inside the terrain-covering bounds.
        private static void CheckZoomCage()
        {
            try
            {
                var ui = FSO.Client.GameFacade.Screens;
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                var scr = ui?.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var world = scr?.LotControl?.World;
                if (gd == null || world == null)
                { Skip("uizoomcage", "no in-lot world"); return; }
                var bp = world.Architecture.Blueprint;
                var lotW = (float)bp.Width;
                var oldZoom = world.State.SilentZoom;
                var oldCenter = world.State.CenterTile;
                bool ok = true;
                var info = "";
                foreach (FSO.LotView.WorldZoom z in System.Enum.GetValues(typeof(FSO.LotView.WorldZoom)))
                {
                    world.State.SilentZoom = z;
                    world.State.WorldSpace.Invalidate();
                    var tW = world.State.WorldSpace.TilePxWidthHalf;
                    var tH = world.State.WorldSpace.TilePxHeightHalf;
                    var halfW = world.State.WorldSpace.WorldPxWidth / 2f;
                    var halfH = world.State.WorldSpace.WorldPxHeight / 2f;
                    var uMax = Math.Max(0f, (lotW * tW - halfW) / tW);
                    var vMax = Math.Max(0f, (lotW * tH - halfH) / tH);
                    var far = lotW + 500f;
                    var extremes = new Vector2[]
                    {
                        new Vector2(-500f, -500f), new Vector2(-500f, far),
                        new Vector2(far, -500f), new Vector2(far, far),
                        new Vector2(-5000f, 3000f)
                    };
                    foreach (var e in extremes)
                    {
                        world.State.CenterTile = e;   // fires SCROLL invalidation
                        world.PreDraw(gd);            // BoundView clamps here
                        var c = world.State.CenterTile;
                        var u = c.X - c.Y;
                        var v = c.X + c.Y - lotW;
                        bool inside = u <= uMax + 0.02f && u >= -uMax - 0.02f
                                   && v <= vMax + 0.02f && v >= -vMax - 0.02f;
                        if (!inside)
                        {
                            ok = false;
                            info += " " + z + "(" + (int)e.X + "," + (int)e.Y + ")=>u=" + u.ToString("0.#") + "/" + uMax.ToString("0.#")
                                 + " v=" + v.ToString("0.#") + "/" + vMax.ToString("0.#") + ";";
                        }
                    }
                    Log("AUTOTEST uizoomcage " + z + " tileHalf=" + tW + "/" + tH
                        + " cage |u|<=" + uMax.ToString("0.#") + " |v|<=" + vMax.ToString("0.#") + " lot=" + lotW);
                }
                world.State.SilentZoom = oldZoom;
                world.State.WorldSpace.Invalidate();
                world.State.CenterTile = oldCenter;
                world.PreDraw(gd);
                if (ok) { Pass("uizoomcage"); return; }
                Log("AUTOTEST uizoomcage: BoundView must cage the camera inside the terrain bounds at every zoom — off-lot positions leaked:" + info);
                Fail("uizoomcage");
            }
            catch (Exception se)
            {
                var trace = (se.StackTrace ?? "").Split('\n');
                Log("AUTOTEST uizoomcage EXC " + se.GetType().Name + " " + se.Message
                    + (trace.Length > 0 ? " AT " + trace[0].Trim() : ""));
                Fail("uizoomcage");
            }
        }

        // ROUND-141 'uicp' — the desktop control panel on the ORIGINAL engine art.
        // Canon: UIGraphics.far Res_CPanel.RT id->file map (kUniversalBkgTGA 2037 =
        // UniversalBack.tga 220x183; mode buttons kPeople/kObjects/kArch/kCamera/kOptions;
        // camera kZoomIn/kZoomOut/kRotLeft/kRotRight; walls kNoCut/kDynaCut/kNoWall/
        /// kLevelRoof; floors kLevel1/kLevel2; speeds kPause/kSpeed1-3; patches
        // kLiveModePatch..kOptionsModePatch 4803-4806 plus kCameraModePatch 2035).
        // The engine builders are cWinViewControl::Init and cWinCamPanel::Init —
        // cWinViewControl::Init (0x2b5f30) — decodes + id map under tools/iff-dump/r141/.
        // Pins: plate dims/position, per-mode patch switching, every button's original
        // frame dimensions, the ONE speed cluster (toolbar right end — the UCP pills and
        /// the static strip are BOTH gone), the removed port chrome (no hide button, no
        /// search box, no friend/eyedropper buttons), and the motive bars ON-SCREEN.
        private static void CheckUCP()
        {
            try
            {
                var ui = FSO.Client.GameFacade.Screens;
                var scr = ui.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var fe = scr?.Frontend;
                var ucp = fe?.DesktopUCP;
                var mp = fe?.MainPanel;
                if (ucp == null || mp == null)
                { Log("AUTOTEST uicp: no desktop frontend (ucp=" + (ucp != null) + " mp=" + (mp != null) + ")"); Fail("uicp"); return; }
                bool ok = true;
                var info = "";

                // 1. the ORIGINAL plate: 220x183, flush bottom-left, and NOT the old
                //    292x281 d_live_bg.png chrome.
                var bg = ucp.Background;
                if (bg == null || bg.Texture == null || bg.Texture.Width != 220 || bg.Texture.Height != 183)
                { ok = false; info += " plate=" + (bg?.Texture != null ? bg.Texture.Width + "x" + bg.Texture.Height : "null") + "!=220x183;"; }
                if ((int)ucp.Position.X != 0 || (int)ucp.Position.Y != ui.CurrentUIScreen.ScreenHeight - 183 || (int)ucp.Size.X != 220 || (int)ucp.Size.Y != 183)
                { ok = false; info += " ucpPos=" + (int)ucp.Position.X + "," + (int)ucp.Position.Y + " size=" + (int)ucp.Size.X + "x" + (int)ucp.Size.Y + ";"; }

                // 2. Per-mode patches: canon dims, right/bottom-aligned on the
                //    220x183 plate, and exactly one visible per mode. Anchoring at
                //    (0,0) produced the stray Live-patch arc beside the family UI.
                var patches = new object[][] {
                    new object[]{ ucp.LivePatch, "213", "153", "7",   "30", "LIVE" },
                    new object[]{ ucp.BuyPatch, "156", "148", "64",  "35", "BUY" },
                    new object[]{ ucp.BuildPatch, "107", "132", "113", "51", "BUILD" },
                    new object[]{ ucp.OptionsPatch, "37", "100", "183", "83", "OPTIONS" },
                    new object[]{ ucp.CameraPatch, "55", "100", "165", "83", "CAMERA" } };
                var modes = new[] { Simitone.Client.UI.Panels.UIMainPanelMode.LIVE, Simitone.Client.UI.Panels.UIMainPanelMode.BUY,
                    Simitone.Client.UI.Panels.UIMainPanelMode.BUILD, Simitone.Client.UI.Panels.UIMainPanelMode.OPTIONS,
                    Simitone.Client.UI.Panels.UIMainPanelMode.CAMERA };
                for (int m = 0; m < patches.Length; m++)
                {
                    var p = patches[m][0] as FSO.Client.UI.Controls.UIImage;
                    if (p == null || p.Texture == null || p.Texture.Width.ToString() != (string)patches[m][1] || p.Texture.Height.ToString() != (string)patches[m][2])
                    { ok = false; info += " patch" + patches[m][5] + "=" + (p?.Texture != null ? p.Texture.Width + "x" + p.Texture.Height : "null") + ";"; continue; }
                    if (((int)p.X).ToString() != (string)patches[m][3] || ((int)p.Y).ToString() != (string)patches[m][4])
                    { ok = false; info += " patch" + patches[m][5] + "Pos=" + (int)p.X + "," + (int)p.Y + "!=" + patches[m][3] + "," + patches[m][4] + ";"; }
                    ucp.SetMode(modes[m]);
                    for (int q = 0; q < patches.Length; q++)
                    {
                        var pq = patches[q][0] as FSO.Client.UI.Controls.UIImage;
                        bool want = (q == m);
                        if (pq.Visible != want) { ok = false; info += " patch" + patches[q][5] + "vis=" + pq.Visible + " want " + want + ";"; }
                    }
                }
                ucp.SetMode(mp.Mode);   // restore

                // 3. mode/camera/wall/floor button art = original frame dimensions
                var uiButtons = new object[][] {
                    new object[]{ ucp.LiveButton, "200", "50", "live/people.bmp" },
                    new object[]{ ucp.BuyButton, "180", "47", "buy/objects.bmp" },
                    new object[]{ ucp.BuildButton, "156", "39", "build/arch.bmp" },
                    new object[]{ ucp.OptionsButton, "92", "23", "options/options.bmp" },
                    new object[]{ ucp.CameraButton, "116", "29", "camera/camera.bmp" } };
                foreach (object[] d in uiButtons)
                {
                    var btn = d[0] as FSO.Client.UI.Controls.UIButton;
                    var tex = btn?.Texture;
                    if (tex == null || tex.Width.ToString() != (string)d[1] || tex.Height.ToString() != (string)d[2])
                    { ok = false; info += " " + d[3] + "=" + (tex != null ? tex.Width + "x" + tex.Height : "null") + ";"; }
                }
                var stButtons = new object[][] {
                    new object[]{ ucp.ZoomInButton, "108", "27", "27", "27", "zoomin" }, new object[]{ ucp.ZoomOutButton, "108", "27", "27", "27", "zoomout" },
                    new object[]{ ucp.RotateCWButton, "108", "27", "27", "27", "rotright" }, new object[]{ ucp.RotateCCWButton, "108", "27", "27", "27", "rotleft" },
                    new object[]{ ucp.RoofButton, "88", "19", "22", "19", "LevRoof" }, new object[]{ ucp.WallsUpButton, "84", "21", "21", "21", "nocut" },
                    new object[]{ ucp.WallsCutButton, "84", "21", "21", "21", "dynacut" }, new object[]{ ucp.WallsDownButton, "88", "15", "22", "15", "nowall" },
                    new object[]{ ucp.FloorUpButton, "88", "15", "22", "15", "Lev2" }, new object[]{ ucp.FloorDownButton, "84", "11", "21", "11", "Lev1" } };
                foreach (object[] d in stButtons)
                {
                    var btn = d[0] as Simitone.Client.UI.Panels.UIOriginalNavbarButton;
                    var tex = btn?.Texture;
                    if (tex == null || tex.Width.ToString() != (string)d[1] || tex.Height.ToString() != (string)d[2]
                        || btn.Cols != 4 || btn.Rows != 1 || btn.CellWidth.ToString() != (string)d[3] || btn.CellHeight.ToString() != (string)d[4])
                    { ok = false; info += " " + d[5] + "=" + (tex != null ? tex.Width + "x" + tex.Height : "null")
                        + " cell=" + (btn != null ? btn.CellWidth + "x" + btn.CellHeight : "null") + ";"; }
                }

                // 4. speed cluster ON THE PLATE (R142 ENGINE LAW — layout-init
                //    0x2b8230 anchors): kPause (85,135), a 4x2 grid of the 60x30
                //    sheet; kSpeed1/2/3 at (105/120/141,135), full 4x1 sheets whose
                //    cells are 11/20/32x15. Preserving full sheets is required for
                //    hover/pressed/disabled state art. The
                //    toolbar carries NO speed cluster on desktop (mp fields null).
                if (mp.PauseButton != null || mp.SpeedButtons != null)
                { ok = false; info += " toolbar-speed-cluster-present;"; }
                if (ucp.PauseButton == null || ucp.PauseButton.Texture == null || ucp.PauseButton.Texture.Width != 60 || ucp.PauseButton.Texture.Height != 30
                    || ucp.PauseButton.Cols != 4 || ucp.PauseButton.Rows != 2 || ucp.PauseButton.CellWidth != 15 || ucp.PauseButton.CellHeight != 15)
                { ok = false; info += " pause=" + (ucp.PauseButton?.Texture != null ? ucp.PauseButton.Texture.Width + "x" + ucp.PauseButton.Texture.Height : "null") + " cell=" + (ucp.PauseButton != null ? ucp.PauseButton.CellWidth + "x" + ucp.PauseButton.CellHeight : "null") + ";"; }
                if ((int)ucp.PauseButton.X != 85 || (int)ucp.PauseButton.Y != 135)
                { ok = false; info += " pausePos=" + (int)ucp.PauseButton.X + "," + (int)ucp.PauseButton.Y + "!=85,135;"; }
                int[] sw = { 11, 20, 32 };
                int[] sheetW = { 44, 80, 128 };
                int[] spx = { 105, 120, 141 };
                if (ucp.SpeedButtons == null || ucp.SpeedButtons.Length != 3)
                { ok = false; info += " speedBtns=" + (ucp.SpeedButtons != null ? ucp.SpeedButtons.Length.ToString() : "null") + ";"; }
                else for (int i = 0; i < 3; i++)
                    {
                        var t = ucp.SpeedButtons[i].Texture;
                        if (t == null || t.Width != sheetW[i] || t.Height != 15
                            || ucp.SpeedButtons[i].Cols != 4 || ucp.SpeedButtons[i].Rows != 1
                            || ucp.SpeedButtons[i].CellWidth != sw[i] || ucp.SpeedButtons[i].CellHeight != 15)
                        { ok = false; info += " speed" + (i + 1) + "=" + (t != null ? t.Width + "x" + t.Height : "null")
                            + " cell=" + ucp.SpeedButtons[i].CellWidth + "x" + ucp.SpeedButtons[i].CellHeight + ";"; }
                        if ((int)ucp.SpeedButtons[i].X != spx[i] || (int)ucp.SpeedButtons[i].Y != 135)
                        { ok = false; info += " speed" + (i + 1) + "Pos=" + (int)ucp.SpeedButtons[i].X + "," + (int)ucp.SpeedButtons[i].Y + "!=" + spx[i] + ",135;"; }
                    }

                // 4b. R142 ENGINE-EXACT UCP anchors (the full 0x2b8230 table the port
                //     now mounts): mode cascade, camera diamond, wall row at y77..110.
                var anchorBtns = new object[] {
                    new object[]{ ucp.LiveButton,      "10",  "6",   "live" },
                    new object[]{ ucp.BuyButton,       "69",  "20",  "buy" },
                    new object[]{ ucp.BuildButton,     "117", "45",  "build" },
                    new object[]{ ucp.CameraButton,    "175", "95",  "camera" },
                    new object[]{ ucp.OptionsButton,   "193", "125", "options" },
                    new object[]{ ucp.ZoomInButton,    "26",  "105", "zoomin" },
                    new object[]{ ucp.ZoomOutButton,   "26",  "149", "zoomout" },
                    new object[]{ ucp.RotateCCWButton, "9",   "127", "rotccw" },
                    new object[]{ ucp.RotateCWButton,  "43",  "127", "rotcw" },
                    new object[]{ ucp.FloorUpButton,   "5",   "92",  "lev2" },
                    new object[]{ ucp.FloorDownButton, "5",   "77",  "lev1" },
                    new object[]{ ucp.RoofButton,      "32",  "78",  "levroof" },
                    new object[]{ ucp.WallsUpButton,   "56",  "80",  "nocut" },
                    new object[]{ ucp.WallsCutButton,  "80",  "85",  "dynacut" },
                    new object[]{ ucp.WallsDownButton, "103", "95",  "nowall" } };
                foreach (object[] ab in anchorBtns)
                {
                    var b = ab[0] as FSO.Client.UI.Framework.UIElement;
                    if (b == null || ((int)b.Position.X).ToString() != (string)ab[1] || ((int)b.Position.Y).ToString() != (string)ab[2])
                    { ok = false; info += " @" + ab[3] + "=" + (b != null ? (int)b.Position.X + "," + (int)b.Position.Y : "null") + "!=" + ab[1] + "," + ab[2] + ";"; }
                }

                // TS1 exposes Lev1/Lev2 as the story-state display; it does not
                // draw the fabricated ordinal label that appeared over the plus.
                if (ucp.FloorLabel != null || ucp.FloorLabelShadow != null || ucp.FloorOriginal != null)
                { ok = false; info += " floor-ordinal-present;"; }
                bool storyLaw = !Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(true, false, false, true)
                    && !Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(true, false, true, false)
                    && Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(true, false, true, true)
                    && Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(true, true, false, false)
                    && !Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(false, true, true, true);
                if (!storyLaw) { ok = false; info += " lev2-enable-law;"; }

                // R254/UI-18 live derivation pin: the gate's story-2 inputs come from
                // the loaded lot's ARCHITECTURE (native cFixedWorld+0x80/+0x81 —
                // story-2 wall/floor content and story-2 support, recomputed on every
                // edit; the retired camera-visit latch could never arm on a two-story
                // lot entered at story 1, leaving Lev2 and PageUp dead in live mode).
                // FloorUpButton.Disabled must equal the law against the real world.
                var archLev2 = scr.vm != null ? scr.vm.Context.Architecture : null;
                bool lev2Story2 = Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.HasSecondStoryContent(archLev2);
                bool lev2Sup = Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.AnySupported(archLev2);
                bool lev2Expected = Simitone.Client.UI.Panels.Desktop.UIDesktopUCP.SecondStoryAvailableForState(
                    scr.InLot, lev2Story2, mp.Mode == Simitone.Client.UI.Panels.UIMainPanelMode.BUILD, lev2Sup);
                if (ucp.FloorUpButton.Disabled != !lev2Expected)
                { ok = false; info += " lev2-live-derivation(disabled=" + ucp.FloorUpButton.Disabled + ",story2=" + lev2Story2 + ",sup=" + lev2Sup + ");"; }
                else
                { Log("AUTOTEST uicp lev2-live: story2Content=" + lev2Story2 + " supported=" + lev2Sup + " lev2Enabled=" + lev2Expected); }

                // 5. removed port chrome on desktop: no hide button, no catalog search box
                if (mp.HideButton != null) { ok = false; info += " hideButton-present;"; }
                int searchBoxes = 0;
                foreach (var c in mp.GetChildren()) if (c is FSO.Client.UI.Controls.UITextBox) searchBoxes++;
                if (searchBoxes > 0) { ok = false; info += " searchBox-present;"; }

                // 5b. The cyan bubble above Options is the missing Camera mode,
                // not spacing around the correctly anchored Options button. Pin
                // the complete cWinCamPanel band: eight 4-state controls, STR# 140
                // tooltips, two 2x89 separators, and Medium/Medium CPState defaults.
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.CAMERA);
                    var cam = mp.CameraChrome;
                    if (cam == null || !cam.Visible || mp.SubPanel != null
                        || mp.PeopleChrome?.Visible == true || mp.ArchChrome?.Visible == true
                        || mp.BuyChrome?.Visible == true || mp.Switcher.MainButton.Visible)
                    { ok = false; info += " cameraModeComposition;"; }
                    else
                    {
                        var cameraButtons = new object[][] {
                            new object[]{ cam.CamFrameSmall, "128", "27", "82",  "70", "1" },
                            new object[]{ cam.CamFrameMed,   "128", "29", "82",  "36", "3" },
                            new object[]{ cam.CamFrameLarge, "128", "28", "82",  "4",  "5" },
                            new object[]{ cam.CamFrameCust,  "240", "58", "11",  "11", "7" },
                            new object[]{ cam.CamViewAlbum,  "244", "35", "226", "35", "9" },
                            new object[]{ cam.CamQualLow,    "128", "28", "154", "70", "11" },
                            new object[]{ cam.CamQualMed,    "128", "29", "154", "36", "13" },
                            new object[]{ cam.CamQualHigh,   "128", "28", "154", "4",  "15" } };
                        foreach (var d in cameraButtons)
                        {
                            var b = d[0] as Simitone.Client.UI.Panels.UIOriginalSheetButton;
                            if (b == null || b.Texture == null
                                || b.Texture.Width.ToString() != (string)d[1]
                                || b.Texture.Height.ToString() != (string)d[2]
                                || ((int)b.X).ToString() != (string)d[3]
                                || ((int)b.Y).ToString() != (string)d[4]
                                || b.CellWidth != b.Texture.Width / 4
                                || b.Tooltip != GameFacade.Strings.GetString("140", (string)d[5]))
                            { ok = false; info += " cameraBtn@" + d[3] + "," + d[4] + ";"; }
                        }
                        if (cam.ToothpickLeft == null || cam.ToothpickLeft.Width != 2 || cam.ToothpickLeft.Height != 89
                            || cam.ToothpickRight == null || cam.ToothpickRight.Width != 2 || cam.ToothpickRight.Height != 89)
                        { ok = false; info += " cameraToothpicks;"; }
                        if (cam.SnapshotSize != 1 || cam.SnapshotQuality != 1
                            || cam.CamFrameMed.State != 1 || cam.CamQualMed.State != 1)
                        { ok = false; info += " cameraDefaults;"; }
                        cam.SelectSnapshotSize(2);
                        cam.SelectSnapshotQuality(0);
                        if (cam.SnapshotSize != 2 || cam.SnapshotQuality != 0
                            || cam.CamFrameLarge.State != 1 || cam.CamFrameMed.State != 0
                            || cam.CamQualLow.State != 1 || cam.CamQualMed.State != 0)
                        { ok = false; info += " cameraSelection;"; }
                        cam.SelectSnapshotSize(1);
                        cam.SelectSnapshotQuality(1);
                    }
                }
                catch (Exception cex) { ok = false; info += " cameraEXC " + cex.GetType().Name + ";"; }

                // 6. R144 ENGINE LAW (r144/toolbar-law.md): the live toolbar is the
                //    cWinPeople composition — motive host (300,0) panel-local with 8
                //    gauges 100x20 in a 2-COLUMN x 4-ROW grid (flow (0,21), x-pitch
                //    100, row pitch 19), the people chrome (8 webcams (9,5) 45-pitch
                //    4x2, LiveGadget plaque (193,0), 7 tabs at engine anchors), and
                //    the plate readouts (money right-anchored (178,158) font[10];
                //    clock digits centered in (95,118,151,125) font[8]).
                try
                {
                    mp.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                    mp.Switcher_OnCategorySelect(0);
                    var sub = mp.SubPanel as Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel;
                    if (sub == null || sub.GaugeGrid == null || sub.GaugeGrid.Length != 8)
                    { ok = false; info += " motiveSubpanel;"; }
                    else
                    {
                        // host law: subpanel itself at MainPanel-local (300,0); gauges
                        // HOST-local (0/100, 21+19r), 100x20
                        if ((int)sub.Position.X != 300 || (int)sub.Position.Y != 0)
                        { ok = false; info += " host@" + (int)sub.Position.X + "," + (int)sub.Position.Y + "!=300,0;"; }
                        for (int i = 0; i < 8; i++)
                        {
                            var g = sub.GaugeGrid[i];
                            int gx = (int)(mp.X + sub.Position.X + g.Position.X);
                            int gy = (int)(mp.Y + g.Position.Y);
                            int wantX = (i % 2) * 100, wantY = 21 + (i / 2) * 19;
                            if ((int)g.Position.X != wantX || (int)g.Position.Y != wantY || (int)g.Size.X != 100 || (int)g.Size.Y != 20)
                            { ok = false; info += " gauge" + i + "@" + (int)g.Position.X + "," + (int)g.Position.Y + "!=" + wantX + "," + wantY + ";"; break; }
                            if (gx < 0 || gx + 100 > ui.CurrentUIScreen.ScreenWidth + 2 || gy + 20 > ui.CurrentUIScreen.ScreenHeight + 2)
                            { ok = false; info += " gauge" + i + "Off=" + gx + "," + gy + ";"; break; }
                        }
                        // fill law: clamp(round(raw*60/200), 0, 60) of the 100px gauge
                        var probe = sub.GaugeGrid[0];
                        probe.RawValue = -100; // raw 0 -> 0 px
                        var fillEmpty = probe.FillWidthForProbe();
                        probe.RawValue = 0;    // raw 100 -> 30 px
                        var fillMid = probe.FillWidthForProbe();
                        probe.RawValue = 100;  // raw 200 -> 60 px (cap)
                        var fillCap = probe.FillWidthForProbe();
                        if (fillEmpty != 0 || fillMid != 30 || fillCap != 60)
                        { ok = false; info += " fillLaw=" + fillEmpty + "/" + fillMid + "/" + fillCap + "!=0/30/60;"; }
                    }
                    var chrome = mp.PeopleChrome;
                    if (chrome == null || chrome.Webcams == null || chrome.Webcams.Length != 8 || chrome.Tabs == null || chrome.Tabs.Length != 7)
                    { ok = false; info += " peopleChrome;"; }
                    else
                    {
                        for (int i = 0; i < 8; i++)
                        {
                            var w = chrome.Webcams[i];
                            if ((int)w.Position.X != 9 + (i % 4) * 45 || (int)w.Position.Y != 5 + (i / 4) * 45)
                            { ok = false; info += " webcam" + i + "@" + (int)w.Position.X + "," + (int)w.Position.Y + ";"; break; }
                        }
                        int[][] tabAnchors = { new[] {202,31}, new[] {269,4}, new[] {269,35}, new[] {269,66}, new[] {237,35}, new[] {237,4}, new[] {237,66} };
                        for (int i = 0; i < 7; i++)
                        {
                            var t = chrome.Tabs[i];
                            if ((int)t.Position.X != tabAnchors[i][0] || (int)t.Position.Y != tabAnchors[i][1])
                            { ok = false; info += " tab" + i + "@" + (int)t.Position.X + "," + (int)t.Position.Y + "!=" + tabAnchors[i][0] + "," + tabAnchors[i][1] + ";"; break; }
                            var nativeTip = Simitone.Client.UI.Model.OriginalLiveStrings.Entry(134, i) ?? "";
                            if (t.Tooltip != nativeTip)
                            { ok = false; info += " tab" + i + "Tip=" + (t.Tooltip ?? "null") + "!=" + nativeTip + ";"; break; }
                        }
                        if (chrome.LiveGadget == null || (int)chrome.LiveGadget.Position.X != 193 || (int)chrome.LiveGadget.Position.Y != 0
                            || chrome.LiveGadget.Texture.Width != 108 || chrome.LiveGadget.Texture.Height != 100)
                        { ok = false; info += " liveGadget;"; }
                    }
                    if (ucp.MoneyOriginal == null || ucp.MoneyOriginal.Font == null)
                    { ok = false; info += " plateMoney;"; }
                    else if ((int)ucp.MoneyOriginal.X + ucp.MoneyOriginal.Font.Measure(ucp.MoneyOriginal.Text) > 178 || (int)ucp.MoneyOriginal.Y != 158)
                    { ok = false; info += " plateMoneyAnchor=" + (int)ucp.MoneyOriginal.X + "," + (int)ucp.MoneyOriginal.Y + ";"; }
                    if (ucp.ClockDigits == null || ucp.ClockDigits.Font == null)
                    { ok = false; info += " plateClock;"; }
                    else
                    {
                        int cx = (int)ucp.ClockDigits.X + ucp.ClockDigits.Font.Measure(ucp.ClockDigits.Text) / 2;
                        if (cx < 95 || cx > 151 || (int)ucp.ClockDigits.Y != 118)
                        { ok = false; info += " plateClockAnchor=" + cx + "," + (int)ucp.ClockDigits.Y + ";"; }
                    }
                    if (mp.TimeOriginal != null || mp.MoneyOriginal != null)
                    { ok = false; info += " toolbarReadouts-present;"; }
                }
                catch (Exception mex) { ok = false; info += " motiveEXC " + mex.GetType().Name + ";"; }

                Log("AUTOTEST uicp original-plate+patches+buttons+speed-cluster" + (ok ? ": OK " : ": FAIL ") + info);
                if (ok) Pass("uicp"); else Fail("uicp");
            }
            catch (Exception ce) { Log("AUTOTEST uicp EXC " + ce.GetType().Name + " " + ce.Message); Fail("uicp"); }
        }

        // ROUND-142 'uidlgchrome' — the ORIGINAL system dialog + pie-menu canon on the
        // live build: the SMCtrlMgrRes chrome (decoded r142/dialog-chrome-law.md) must
        // resolve from UIGraphics.far AND the UIMobileAlert family must be running it —
        // GenDlg nine-slice frame, RGB(0,0,82) fill, font[11]/#C3CDCD text,
        // WinBtn 260x33 system buttons, the
        // PositionButtons law (spacing=(w-32-n*maxW)/(n+1) min 16, first at 16+spacing,
        // bottom 32px inset), auto-size min width 200. cWinPictureDialog is pinned
        // separately: PopupInfoTiles tiled 12px thirds; (21,21) content; 120px
        // native object image; font slots 14/12 at 27/23px and RGB(195,205,205);
        // adaptive 2:1 sizing and independent min-100 buttons. Pie canon: PieButt.bmp 17x17 +
        // ViewMenuBackground.bmp 17x17 resolve; the slice-count band law is pinned
        // exactly (0->1, 1-2->+2, 3-4->+4, >=5->+8).
        private sealed class DialogProbeResource : GameIffResource
        {
            private readonly IffFile Iff;
            public DialogProbeResource(IffFile iff) { Iff = iff; }
            public override IffFile MainIff { get { return Iff; } }
            public override T Get<T>(ushort id) { return Iff == null ? default(T) : Iff.Get<T>(id); }
            public override List<T> List<T>() { return Iff == null ? new List<T>() : Iff.List<T>(); }
        }

        private static IffFile FindMountedTS1Iff(string filename)
        {
            var ts1 = Content.Get()?.TS1Global;
            var direct = ts1?.Get(filename) as IffFile;
            if (direct != null) return direct;
            var entries = ts1?.GetFarEntries(".iff");
            if (entries == null) return null;
            var entry = entries.FirstOrDefault(x => x?.FarEntry?.Filename != null
                && string.Equals(Path.GetFileName(x.FarEntry.Filename), filename,
                    StringComparison.OrdinalIgnoreCase));
            return entry?.Get() as IffFile;
        }

        private static Simitone.Client.UI.Panels.UIMobileAlert NewDialogIconProbeAlert()
        {
            return new Simitone.Client.UI.Panels.UIMobileAlert(
                new FSO.Client.UI.Controls.UIAlertOptions
                {
                    Title = "ObjectDialog icon route",
                    Message = "Production selector-mode routing probe.",
                    Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                        new FSO.Client.UI.Controls.UIAlertButton(
                            FSO.Client.UI.Controls.UIAlertButtonType.OK, null)
                    }
                }, true);
        }

        private static void CheckOriginalDialogSelectorParsing(ref bool ok, ref string info)
        {
            var avatar = _vm?.Context?.ObjectQueries?.Avatars?
                .OfType<VMAvatar>().FirstOrDefault();
            var liveFrame = avatar?.Thread?.Stack?
                .LastOrDefault(x => x?.CodeOwner != null && x.Routine != null);
            if (avatar == null || liveFrame == null)
            {
                ok = false;
                info += " selectorParserNoFrame;";
                return;
            }

            var source = new STR();
            source.LanguageSets[0].Strings = new[]
            {
                new STRItem { LanguageCode = 1, Value = "$Neighbor" },
                new STRItem { LanguageCode = 1, Value = "$Object" },
                new STRItem { LanguageCode = 1, Value = "$Neighbor" },
                new STRItem { LanguageCode = 1, Value = "$Object" },
                new STRItem { LanguageCode = 1, Value = "$Me" }
            };
            var frame = new VMStackFrame
            {
                Thread = liveFrame.Thread,
                Routine = liveFrame.Routine,
                InstructionPointer = liveFrame.InstructionPointer,
                Caller = avatar,
                Callee = avatar,
                CodeOwner = liveFrame.CodeOwner,
                Locals = liveFrame.Locals ?? new short[0],
                Args = liveFrame.Args ?? new short[0],
                StackObject = avatar
            };
            short neighborID = avatar.GetPersonData(VMPersonDataVariable.NeighborId);
            // Native stores Stack Object and signed Stack Object ID separately;
            // `$Object` reads the entity while `$Neighbor` reads the NBRS id.
            frame._StackObjectID = neighborID;

            var operand = new VMDialogOperand
            {
                YesStringID = 1,
                NoStringID = 2,
                CancelStringID = 3,
                TitleStringID = 4,
                MessageStringID = 5,
                Flags = (VMDialogFlags)0
            };
            var built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (built.Icon != avatar || built.IconNeighborID != -1)
            { ok = false; info += " selectorParseOrderObject;"; }

            // Message is parsed last; making only it a Neighbor selector must
            // replace the prior Object selection. `$Me` above must not replace
            // the title's Object selection.
            source.LanguageSets[0].Strings[4].Value = "$Neighbor";
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (built.Icon != null || built.IconNeighborID != neighborID)
            { ok = false; info += " selectorParseOrderNeighbor;"; }

            // With no selector tokens, automatic mode falls back to Stack
            // Object. Explicit none/neighbor remain independent choices.
            foreach (var item in source.LanguageSets[0].Strings) item.Value = "$Me";
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (built.Icon != avatar || built.IconNeighborID != -1)
            { ok = false; info += " selectorParseFallback;"; }

            operand.Flags = (VMDialogFlags)(1 << 1);
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (built.Icon != null || built.IconNeighborID != -1)
            { ok = false; info += " selectorParseNone;"; }

            operand.Flags = (VMDialogFlags)(2 << 1);
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (built.Icon != null || built.IconNeighborID != neighborID)
            { ok = false; info += " selectorParseNeighbor;"; }

            // Byte 1 is an STR index only in named mode. A missing named entry
            // is empty; indexed mode must not parse the same byte as text.
            operand.IconNameStringID = 250;
            operand.Flags = (VMDialogFlags)(4 << 1);
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (!string.IsNullOrEmpty(built.IconName))
            { ok = false; info += " selectorParseNamedMissing;"; }
            operand.Flags = (VMDialogFlags)(3 << 1);
            built = VMDialogHandler.BuildDialogInfo(frame, operand, source);
            if (!string.IsNullOrEmpty(built.IconName)
                || !object.ReferenceEquals(built.IconResource, frame.ScopeResource))
            { ok = false; info += " selectorParseIndexed;"; }
        }

        private static void CheckOriginalDialogIconRouting(GraphicsDevice gd,
            ref bool ok, ref string info)
        {
            var lot = _screen?.LotControl;
            var avatar = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>().FirstOrDefault();
            if (lot == null || avatar == null)
            {
                ok = false;
                info += " iconRouterNoLotOrAvatar;";
                return;
            }

            var operand = new VMDialogOperand();
            var dialog = new VMDialogInfo { Operand = operand, DialogID = 1, IconNeighborID = -1 };
            Simitone.Client.UI.Panels.UIMobileAlert probe = null;
            var originalActive = lot.ActiveEntity;
            if (lot.ActiveEntity == null)
            {
                // The focused harness reaches the lot before the normal
                // selected-Sim update has necessarily run. Native `rel`
                // explicitly reads the selected character, so give the router
                // that real UI precondition and restore it after the probe.
                lot.ActiveEntity = avatar;
            }
            try
            {
                // Mode 1 is a positive blank choice: no fallback to a sentinel
                // entity is permitted even though one is supplied.
                operand.Flags = (VMDialogFlags)(1 << 1);
                dialog.Icon = avatar;
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (probe.OriginalIconForProbe.Visible || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNoneHasImage;"; }
                probe.Removed(); probe = null;

                // Automatic person selector uses a 45x45 PersonFinder result
                // centered on SimStub.
                operand.Flags = (VMDialogFlags)0;
                dialog.Icon = avatar;
                dialog.IconNeighborID = -1;
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || !probe.OriginalIconStubForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 45
                    || (int)probe.OriginalIconForProbe.Height != 45)
                { ok = false; info += " routeAutoPerson;"; }
                probe.Removed(); probe = null;

                // Automatic products go through World::GetObjectThumb and are
                // composed to Product::DrawIcon's exact 120x120 destination.
                // A restored lot can contain controller/out-of-world products
                // whose ObjectComponent exists but intentionally emits no
                // thumbnail. Probe production routing with the first product
                // that actually yields Product::DrawIcon output, rather than
                // binding the assertion to entity-list order.
                bool autoProduct = false;
                int productAttempts = 0;
                int productExceptions = 0;
                int routedProductID = 0;
                var products = _vm.Entities.OfType<VMGameObject>()
                    .Where(x => x.MultitileGroup != null
                        && x.MultitileGroup.Objects.Count > 0
                        && x.MultitileGroup.Objects.All(part =>
                            part.WorldUI is FSO.LotView.Components.ObjectComponent))
                    .OrderBy(x => x.ObjectID).Take(64).ToList();
                foreach (var product in products)
                {
                    productAttempts++;
                    dialog.Icon = product;
                    probe = NewDialogIconProbeAlert();
                    try
                    {
                        lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                        autoProduct = probe.OriginalIconForProbe.Visible
                            && !probe.OriginalIconStubForProbe.Visible
                            && (int)probe.OriginalIconForProbe.Width == 120
                            && (int)probe.OriginalIconForProbe.Height == 120;
                        if (autoProduct) routedProductID = product.ObjectID;
                    }
                    catch { productExceptions++; }
                    finally { probe.Removed(); probe = null; }
                    if (autoProduct) break;
                }
                if (!autoProduct)
                {
                    ok = false;
                    info += " routeAutoProduct(attempts=" + productAttempts
                        + ",exceptions=" + productExceptions + ");";
                }
                else info += " productRoute=" + routedProductID + "/" + productAttempts + ";";

                // Explicit neighbor mode must ignore the sentinel Icon and use
                // signed Stack Object ID/NBRS identity.
                operand.Flags = (VMDialogFlags)(2 << 1);
                dialog.Icon = null;
                dialog.IconNeighborID = avatar.GetPersonData(VMPersonDataVariable.NeighborId);
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || !probe.OriginalIconStubForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 45)
                { ok = false; info += " routeNeighbor;"; }
                probe.Removed(); probe = null;

                // Indexed mode loads private BMP_(5000+operand[1]) at full,
                // native bounds. HDHelpSystem is an owned shipped fixture with
                // BMP_5000 and avoids fabricated checker textures.
                var helpIff = FindMountedTS1Iff("HDHelpSystem.iff");
                var helpResource = new DialogProbeResource(helpIff);
                var expectedIndexed = helpResource.Get<BMP>(5000)?.GetTexture(gd);
                int indexedW = expectedIndexed?.Width ?? 0;
                int indexedH = expectedIndexed?.Height ?? 0;
                expectedIndexed?.Dispose();
                operand.Flags = (VMDialogFlags)(3 << 1);
                operand.IconNameStringID = 0;
                dialog.IconResource = helpResource;
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (indexedW <= 0 || indexedH <= 0 || !probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != indexedW
                    || (int)probe.OriginalIconForProbe.Height != indexedH
                    || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeIndexed=" + indexedW + "x" + indexedH + ";"; }
                probe.Removed(); probe = null;

                // Named private and named global paths use their actual source
                // files, preserving 1:1 native dimensions.
                var tutorialIff = FindMountedTS1Iff("Tutorial.iff");
                var tutorialResource = new DialogProbeResource(tutorialIff);
                var expectedMy = tutorialResource.Get<BMP>(300)?.GetTexture(gd);
                int myW = expectedMy?.Width ?? 0;
                int myH = expectedMy?.Height ?? 0;
                expectedMy?.Dispose();
                operand.Flags = (VMDialogFlags)(4 << 1);
                dialog.IconResource = tutorialResource;
                dialog.IconName = "my 300";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (myW <= 0 || myH <= 0 || !probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != myW
                    || (int)probe.OriginalIconForProbe.Height != myH)
                { ok = false; info += " routeNamedMy=" + myW + "x" + myH + ";"; }
                probe.Removed(); probe = null;

                dialog.IconName = "gzi 9005";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 133
                    || (int)probe.OriginalIconForProbe.Height != 103
                    || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNamedGzi;"; }
                probe.Removed(); probe = null;

                // The two global commands are intentionally not synonyms:
                // gz takes the first horizontal quarter while gzi preserves
                // the complete source image.
                dialog.IconName = "gz 9005";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 33
                    || (int)probe.OriginalIconForProbe.Height != 103
                    || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNamedGz;"; }
                probe.Removed(); probe = null;

                // JobIconMultiPopup is a 22-row 84x63 sheet. Job -1 is the
                // original special case for row 11, not an invalid selector.
                dialog.IconName = "job -1";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 84
                    || (int)probe.OriginalIconForProbe.Height != 63
                    || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNamedJob;"; }
                probe.Removed(); probe = null;

                // The shipped relationship command selects the center fifth
                // of the active Sim's authored 200x40 BMP_2003 strip.
                dialog.IconName = "rel";
                var relAvatar = lot.ActiveEntity as VMAvatar;
                var relSource = relAvatar?.Object?.Resource?.Get<BMP>(2003)?.GetTexture(gd);
                int relSourceW = relSource?.Width ?? 0;
                int relSourceH = relSource?.Height ?? 0;
                relSource?.Dispose();
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 40
                    || (int)probe.OriginalIconForProbe.Height != 40
                    || probe.OriginalIconStubForProbe.Visible)
                {
                    ok = false;
                    info += " routeNamedRel(active=" + (relAvatar != null)
                        + ",source=" + relSourceW + "x" + relSourceH
                        + ",shown=" + (probe.OriginalIconForProbe.Visible
                            ? (int)probe.OriginalIconForProbe.Width + "x"
                                + (int)probe.OriginalIconForProbe.Height
                            : "blank") + ");";
                }
                probe.Removed(); probe = null;

                // Pin the one GUID selector authored by the shipped corpus.
                // ComposeBtnImage always hands the dialog a 45x45 product
                // image, which in turn selects the native SimStub branch.
                dialog.IconName = "guid -2032092235";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (!probe.OriginalIconForProbe.Visible
                    || (int)probe.OriginalIconForProbe.Width != 45
                    || (int)probe.OriginalIconForProbe.Height != 45
                    || !probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNamedGuid;"; }
                probe.Removed(); probe = null;

                // Unknown/missing named commands and the unimplemented 5..7
                // dispatch values are positive blank choices, never automatic
                // fallbacks to a supplied entity.
                dialog.Icon = avatar;
                dialog.IconName = "gzi 999999";
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (probe.OriginalIconForProbe.Visible || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeNamedMissingFallback;"; }
                probe.Removed(); probe = null;

                operand.Flags = (VMDialogFlags)(5 << 1);
                probe = NewDialogIconProbeAlert();
                lot.ApplyOriginalDialogIconForProbe(probe, dialog);
                if (probe.OriginalIconForProbe.Visible || probe.OriginalIconStubForProbe.Visible)
                { ok = false; info += " routeReservedFallback;"; }
            }
            catch (Exception e)
            {
                ok = false;
                info += " iconRouterEXC=" + e.GetType().Name + ";";
            }
            finally
            {
                probe?.Removed();
                lot.ActiveEntity = originalActive;
            }
        }

        private static void CheckUIDialogChrome()
        {
            try
            {
                var ok = true; var info = "";
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (gd == null) { Skip("uidlgchrome", "no device"); return; }
                // CheckUISurvey may have hidden the save's live ObjectDialog.
                // Also cover focused uidlgchrome runs where uisurvey is disabled.
                // Synthetic probe dialogs are created only after this snapshot.
                SuppressPreexistingDialogsForVisualArtifacts("uidlgchrome");

                // 1. the chrome art itself resolves at canon dims
                var genDlg = Simitone.Client.UI.Controls.UIOriginalDialogChrome.GetGenDlg();
                var pictureTiles = Simitone.Client.UI.Controls.UIOriginalDialogChrome.GetPictureTiles();
                var winBtn = Simitone.Client.UI.Controls.UIOriginalDialogChrome.GetWinBtn();
                if (genDlg == null || genDlg.Width != 30 || genDlg.Height != 30)
                { ok = false; info += " gendlg=" + (genDlg != null ? genDlg.Width + "x" + genDlg.Height : "null") + "!=30x30;"; }
                if (winBtn == null || winBtn.Width != 260 || winBtn.Height != 33)
                { ok = false; info += " winbtn=" + (winBtn != null ? winBtn.Width + "x" + winBtn.Height : "null") + "!=260x33;"; }
                if (pictureTiles == null || pictureTiles.Width != 36 || pictureTiles.Height != 36)
                { ok = false; info += " pictureTiles=" + (pictureTiles != null ? pictureTiles.Width + "x" + pictureTiles.Height : "null") + "!=36x36;"; }
                if (Simitone.Client.UI.Controls.UIOriginalDialogChrome.PictureBorder != 12
                    || Simitone.Client.UI.Controls.UIOriginalDialogChrome.TiledSegmentCount(25, 12) != 3
                    || Simitone.Client.UI.Controls.UIOriginalDialogChrome.TiledFinalSegmentLength(25, 12) != 1)
                { ok = false; info += " pictureTileLaw;"; }
                if (Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(1.95)
                    || Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(2.05)
                    || Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(1.97)
                    || Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(2.03)
                    || !Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(1.94)
                    || !Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureOutsideAspectTolerance(2.06))
                { ok = false; info += " pictureAspectTolerance;"; }
                if (Simitone.Client.UI.Controls.UIOriginalDialogChrome.FillColor.R != 0 ||
                    Simitone.Client.UI.Controls.UIOriginalDialogChrome.FillColor.G != 0 ||
                    Simitone.Client.UI.Controls.UIOriginalDialogChrome.FillColor.B != 82)
                { ok = false; info += " fillColor!=RGB(0,0,82);"; }
                // DrawLocalTexture consumes a scale multiplier. A 10px source
                // edge stretched across 438px must therefore use 43.8x, not 438x.
                var edgeScale = Simitone.Client.UI.Controls.UIOriginalDialogChrome.EdgeScaleForLength(438);
                if (Math.Abs(edgeScale * Simitone.Client.UI.Controls.UIOriginalDialogChrome.Border - 438f) > 0.01f)
                { ok = false; info += " edgeScale=" + edgeScale + ";"; }

                // 2. a REAL alert through the same construction path every dialog uses —
                //    the engine laws must hold on the live object.
                int titlesBefore = Simitone.Client.UI.Controls.UIMobileDialog.TitlesTwinned;
                var alert = new Simitone.Client.UI.Panels.UIMobileAlert(new FSO.Client.UI.Controls.UIAlertOptions
                {
                    Title = "uidlgchrome",
                    Message = "Round 142 original dialog chrome gate.",
                    Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null),
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.Cancel, null)
                    }
                });
                try
                {
                    if (!alert.OriginalChrome) { ok = false; info += " originalChrome=false;"; }
                    if (alert.BoxWidth < 200) { ok = false; info += " boxWidth=" + alert.BoxWidth + "<200;"; }
                    // both buttons carry the WinBtn sheet and uniform maxW >= 65
                    var btns = alert.ButtonMap;
                    int maxW = 65;
                    foreach (var b in btns.Values)
                    {
                        if (b.Texture == null || b.Texture.Width != 260 || b.Texture.Height != 33)
                        { ok = false; info += " btnTex=" + (b.Texture != null ? b.Texture.Width + "x" + b.Texture.Height : "null") + ";"; }
                        maxW = Math.Max(maxW, (int)b.Width);
                    }
                    if (btns.Count == 2)
                    {
                        var expected = Simitone.Client.UI.Controls.UIOriginalDialogChrome.ButtonLefts(alert.BoxWidth, 2, maxW);
                        int top = Simitone.Client.UI.Controls.UIOriginalDialogChrome.ButtonTop(alert.Height, 33);
                        int i = 0;
                        foreach (var b in btns.Values)
                        {
                            if (Math.Abs((int)b.X - expected[i]) > 1) { ok = false; info += " btn" + i + "X=" + (int)b.X + " want=" + expected[i] + ";"; }
                            if (Math.Abs((int)b.Y - top) > 1) { ok = false; info += " btn" + i + "Y=" + (int)b.Y + " want=" + top + ";"; }
                            i++;
                        }
                    }
                    if (Simitone.Client.UI.Controls.UIMobileDialog.TitlesTwinned <= titlesBefore)
                    { ok = false; info += " titleTwin not mounted;"; }
                    var genericFont11 = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(11, gd);
                    var genericTitlePos = alert.OriginalTitlePositionForProbe;
                    var genericTitleColor = alert.OriginalTitleColorForProbe;
                    if (genericFont11 == null || genericFont11.LineHeight != 21
                        || !object.ReferenceEquals(alert.OriginalTitleFontForProbe, genericFont11)
                        || genericTitleColor != Simitone.Client.UI.Controls.UIMobileDialog.OriginalSystemTextColor
                        || (int)genericTitlePos.X != 16 || (int)genericTitlePos.Y != 16)
                    { ok = false; info += " genericTitleFontColorPos;"; }
                    var genericLines = alert.OriginalBodyLinesForProbe;
                    if (alert.OriginalPictureLayoutForProbe
                        || alert.OriginalBodyTopForProbe != 45
                        || genericLines == null || genericLines.Count == 0
                        || (int)genericLines[0].X != 16 || (int)genericLines[0].Y != 45
                        || genericLines.Any(line => !object.ReferenceEquals(line.Font, genericFont11)
                            || line.Color != Simitone.Client.UI.Controls.UIMobileDialog.OriginalSystemTextColor))
                    { ok = false; info += " genericBodyFontColorPos;"; }
                }
                finally
                {
                    alert.Close();
                }

                // ObjectDialog is cWinPictureDialog by class identity, not by
                // whether SetImage happened to be called. Pin its legitimate
                // no-image member so it cannot regress to the generic tiny/black
                // title merely because VMDialogInfo.Icon is null.
                var noImagePictureAlert = new Simitone.Client.UI.Panels.UIMobileAlert(
                    new FSO.Client.UI.Controls.UIAlertOptions
                    {
                        Title = "Congratulations!",
                        Message = "What vision, what talent! Bella received one Creativity Skill Point.",
                        Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                            new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null)
                        }
                    }, true);
                try
                {
                    var noImageTitleFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(14, gd);
                    var noImageBodyFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(12, gd);
                    var noImageTitlePos = noImagePictureAlert.OriginalTitlePositionForProbe;
                    float noImageTitleX = noImageTitleFont != null
                        ? (noImagePictureAlert.BoxWidth - noImageTitleFont.Measure("Congratulations!")) / 2f
                        : float.NaN;
                    var noImageLines = noImagePictureAlert.OriginalBodyLinesForProbe;
                    if (!noImagePictureAlert.OriginalPictureLayoutForProbe
                        || !object.ReferenceEquals(noImagePictureAlert.OriginalTitleFontForProbe, noImageTitleFont)
                        || noImagePictureAlert.OriginalTitleColorForProbe != Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureTitleColor
                        || float.IsNaN(noImageTitleX) || Math.Abs(noImageTitlePos.X - noImageTitleX) > 0.51f
                        || (int)noImageTitlePos.Y != 21
                        || noImagePictureAlert.OriginalBodyTopForProbe != 66
                        || noImageLines == null || noImageLines.Count == 0
                        || noImageLines.Any(line => !object.ReferenceEquals(line.Font, noImageBodyFont)
                            || line.Color != Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureBodyColor))
                    { ok = false; info += " noImagePictureDialog;"; }

                    // Keep an eyes-on artifact for the no-image member too. This
                    // catches readable-but-wrong typography and centering that
                    // structural probes alone cannot communicate clearly.
                    noImagePictureAlert.InterpolatedAnimation = 1f;
                    try
                    {
                        var sc = FSO.Client.GameFacade.Screens.CurrentUIScreen;
                        sc.Add(noImagePictureAlert);
                        var tree = new System.Collections.Generic.List<string>
                        {
                            "== no-image ObjectDialog headline =="
                        };
                        SurveyDump("dialog-no-image", tree);
                        sc.Remove(noImagePictureAlert);
                    }
                    catch (Exception ve) { ok = false; info += " noImagePictureSurvey " + ve.GetType().Name + ";"; }
                }
                finally
                {
                    FSO.Client.GameFacade.Screens.CurrentUIScreen?.Remove(noImagePictureAlert);
                    noImagePictureAlert.Close();
                }

                // Empty-body picture dialogs must remain draw-safe: this path
                // has no original body twins and intentionally has no modern
                // TextRenderer result. SurveyDump executes the production Draw.
                var emptyPictureAlert = new Simitone.Client.UI.Panels.UIMobileAlert(
                    new FSO.Client.UI.Controls.UIAlertOptions
                    {
                        Title = "Congratulations!",
                        Message = "",
                        Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                            new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null)
                        }
                    }, true);
                try
                {
                    emptyPictureAlert.InterpolatedAnimation = 1f;
                    var sc = FSO.Client.GameFacade.Screens.CurrentUIScreen;
                    sc.Add(emptyPictureAlert);
                    SurveyDump("dialog-empty", new System.Collections.Generic.List<string>
                    {
                        "== empty-body ObjectDialog draw safety =="
                    });
                    sc.Remove(emptyPictureAlert);
                }
                catch (Exception ve)
                {
                    Log("AUTOTEST empty-picture draw EXC " + ve);
                    ok = false; info += " emptyPictureDraw " + ve.GetType().Name + ";";
                }
                finally
                {
                    FSO.Client.GameFacade.Screens.CurrentUIScreen?.Remove(emptyPictureAlert);
                    emptyPictureAlert.Close();
                }

                var iconModeProbe = new FSO.SimAntics.Primitives.VMDialogOperand();
                for (int mode = 0; mode <= 7; mode++)
                {
                    iconModeProbe.Flags = (FSO.SimAntics.Primitives.VMDialogFlags)(mode << 1);
                    if (Simitone.Client.UI.Panels.UILotControl.OriginalDialogIconMode(iconModeProbe) != mode)
                    { ok = false; info += " iconMode" + mode + ";"; }
                }
                if (Simitone.Client.UI.Panels.UILotControl.OriginalDialogIconMode(null) != -1)
                { ok = false; info += " genericIconMode;"; }

                CheckOriginalDialogSelectorParsing(ref ok, ref info);

                var objectInfoProbe = new FSO.SimAntics.Model.VMDialogInfo
                {
                    Operand = iconModeProbe,
                    DialogID = 1
                };
                iconModeProbe.Flags = (FSO.SimAntics.Primitives.VMDialogFlags)0;
                if (!Simitone.Client.UI.Panels.UILotControl.IsOriginalObjectDialog(objectInfoProbe)
                    || !Simitone.Client.UI.Panels.UILotControl.UsesAutomaticObjectDialogIcon(objectInfoProbe))
                { ok = false; info += " objectDialogProvenance;"; }
                objectInfoProbe.DialogID = 0;
                if (Simitone.Client.UI.Panels.UILotControl.IsOriginalObjectDialog(objectInfoProbe)
                    || Simitone.Client.UI.Panels.UILotControl.UsesAutomaticObjectDialogIcon(objectInfoProbe))
                { ok = false; info += " genericDialogProvenance;"; }

                string namedCommand;
                int namedArgument;
                if (!Simitone.Client.UI.Panels.UILotControl.TryParseOriginalNamedIcon(
                        "GZI 9005", out namedCommand, out namedArgument)
                    || namedCommand != "gzi" || namedArgument != 9005
                    || !Simitone.Client.UI.Panels.UILotControl.TryParseOriginalNamedIcon(
                        "guid -2032092235", out namedCommand, out namedArgument)
                    || namedCommand != "guid" || namedArgument != -2032092235
                    || !Simitone.Client.UI.Panels.UILotControl.TryParseOriginalNamedIcon(
                        "rel", out namedCommand, out namedArgument)
                    || namedCommand != "rel"
                    || Simitone.Client.UI.Panels.UILotControl.TryParseOriginalNamedIcon(
                        "gzi", out namedCommand, out namedArgument))
                { ok = false; info += " namedIconGrammar;"; }

                var tragedyMember = Simitone.Client.UI.Model.UIOriginal.ResourceNameForIDForProbe(9005);
                var tragedy = Simitone.Client.UI.Model.UIOriginal.EnsureResolvedByID(9005)?.Get(gd);
                if (!string.Equals(tragedyMember, "Other\\TragedyMask.bmp",
                        StringComparison.OrdinalIgnoreCase)
                    || tragedy == null || tragedy.Width != 133 || tragedy.Height != 103)
                { ok = false; info += " globalIcon9005=" + (tragedyMember ?? "null") + ";"; }

                // Exercise the production selector-mode router against shipped
                // resources. This catches a blank/wrong image even when the
                // parser and the picture-dialog chrome pass independently.
                CheckOriginalDialogIconRouting(gd, ref ok, ref info);

                // A mode-0 operand is not sufficient provenance on its own:
                // synthetic exception/debug messages also carry a default
                // operand but DialogID=0 and must remain generic message boxes.
                var syntheticGeneric = new Simitone.Client.UI.Panels.UIMobileAlert(
                    new FSO.Client.UI.Controls.UIAlertOptions
                    {
                        Title = "SimAntics Exception!",
                        Message = "Synthetic diagnostic",
                        Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                            new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null)
                        }
                    }, false);
                try
                {
                    if (syntheticGeneric.OriginalPictureLayoutForProbe)
                    { ok = false; info += " syntheticGenericPicture;"; }
                    var accidentalIcon = new Microsoft.Xna.Framework.Graphics.Texture2D(gd, 8, 8);
                    accidentalIcon.SetData(Enumerable.Repeat(Microsoft.Xna.Framework.Color.White, 64).ToArray());
                    try
                    {
                        syntheticGeneric.SetIcon(accidentalIcon, 8, 8);
                        if (syntheticGeneric.OriginalPictureLayoutForProbe
                            || syntheticGeneric.OriginalIconForProbe.Visible)
                        { ok = false; info += " genericIconPromotion;"; }
                    }
                    finally { accidentalIcon.Dispose(); }
                }
                finally { syntheticGeneric.Removed(); syntheticGeneric.Close(); }

                // 3. Pin the image-bearing cWinPictureDialog's distinct tiled frame,
                //    exact fonts/colors, adaptive geometry and render this
                //    representative composition for eyes-on validation.
                var pictureTexture = new Microsoft.Xna.Framework.Graphics.Texture2D(gd, 120, 120);
                var picturePixels = new Microsoft.Xna.Framework.Color[120 * 120];
                for (int py = 0; py < 120; py++)
                    for (int px = 0; px < 120; px++)
                        picturePixels[py * 120 + px] = ((px / 12 + py / 12) & 1) == 0
                            ? new Microsoft.Xna.Framework.Color(231, 185, 67)
                            : new Microsoft.Xna.Framework.Color(126, 82, 28);
                pictureTexture.SetData(picturePixels);
                var pictureMessage = string.Join(" ", Enumerable.Repeat(
                    "This picture dialog wraps beside the object and then uses the full line width below it.", 8));
                var pictureAlert = new Simitone.Client.UI.Panels.UIMobileAlert(new FSO.Client.UI.Controls.UIAlertOptions
                {
                    Title = "Picture Dialog",
                    Message = pictureMessage,
                    Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null)
                    }
                }, true);
                try
                {
                    pictureAlert.SetIcon(pictureTexture, 120, 120);
                    if (!pictureAlert.OriginalPictureLayoutForProbe)
                    { ok = false; info += " pictureLayout=false;"; }
                    if (pictureAlert.BoxWidth != pictureAlert.OriginalTextWidthForProbe + 42)
                    { ok = false; info += " pictureBox=" + pictureAlert.BoxWidth + " body=" + pictureAlert.OriginalTextWidthForProbe + ";"; }
                    double pictureRatio = pictureAlert.BoxWidth / (double)Math.Max(1, pictureAlert.Height);
                    if (Math.Abs(pictureRatio - 2.0) > 0.08)
                    { ok = false; info += " pictureRatio=" + pictureRatio.ToString("0.000") + ";"; }
                    var icon = pictureAlert.OriginalIconForProbe;
                    if (icon == null || !icon.Visible || (int)icon.X != 21 || (int)icon.Y != 21
                        || (int)icon.Size.X != 120 || (int)icon.Size.Y != 120)
                    { ok = false; info += " picture=" + (icon != null ? (int)icon.X + "," + (int)icon.Y + " " + (int)icon.Size.X + "x" + (int)icon.Size.Y : "null") + ";"; }
                    var bodyFont12 = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(12, gd);
                    var titleFont14 = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(14, gd);
                    if (bodyFont12 == null || bodyFont12.LineHeight != 23)
                    { ok = false; info += " bodyFont12Height=" + (bodyFont12 != null ? bodyFont12.LineHeight.ToString() : "null") + ";"; }
                    if (titleFont14 == null || titleFont14.LineHeight != 27)
                    { ok = false; info += " titleFont14Height=" + (titleFont14 != null ? titleFont14.LineHeight.ToString() : "null") + ";"; }
                    var lines = pictureAlert.OriginalBodyLinesForProbe;
                    if (lines == null || lines.Count < 5)
                    { ok = false; info += " pictureLines=" + (lines != null ? lines.Count.ToString() : "null") + ";"; }
                    else
                    {
                        if ((int)lines[0].X != 159 || (int)lines[0].Y != 66)
                        { ok = false; info += " firstLine=" + (int)lines[0].X + "," + (int)lines[0].Y + "!=159,66;"; }
                        if (!lines.Any(line => (int)line.X == 21))
                        { ok = false; info += " no-full-width-line;"; }
                        if (lines.Any(line => !object.ReferenceEquals(line.Font, bodyFont12)
                            || line.Color != Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureBodyColor))
                        { ok = false; info += " pictureBodyFontOrColor;"; }
                    }
                    var titlePos = pictureAlert.OriginalTitlePositionForProbe;
                    int titleWidth = titleFont14 != null ? titleFont14.Measure("Picture Dialog") : 0;
                    float expectedTitleX = 12 + 120 + 18
                        + (pictureAlert.OriginalTextWidthForProbe - 138 - titleWidth) / 2f;
                    if (float.IsNaN(titlePos.X) || Math.Abs(titlePos.X - expectedTitleX) > 0.51f || (int)titlePos.Y != 21)
                    { ok = false; info += " pictureTitle=" + titlePos.X + "," + titlePos.Y + " want=" + expectedTitleX + ",21;"; }
                    var titleColor = pictureAlert.OriginalTitleColorForProbe;
                    if (pictureAlert.OriginalTitleFontForProbe == null
                        || !object.ReferenceEquals(pictureAlert.OriginalTitleFontForProbe, titleFont14))
                    { ok = false; info += " pictureTitleFont!=slot14;"; }
                    if (titleColor != Simitone.Client.UI.Panels.UIMobileAlert.OriginalPictureTitleColor)
                    { ok = false; info += " pictureTitleColor=" + titleColor.R + "," + titleColor.G + "," + titleColor.B + ";"; }
                    if (pictureAlert.OriginalBodyTopForProbe != 66
                        || pictureAlert.OriginalBodyHeightForProbe < 92
                        || pictureAlert.OriginalBodyHeightForProbe % 23 != 0)
                    { ok = false; info += " pictureBody=" + pictureAlert.OriginalBodyTopForProbe + "+" + pictureAlert.OriginalBodyHeightForProbe + ";"; }
                    var pictureButton = pictureAlert.ButtonMap.Values.FirstOrDefault();
                    int expectedButtonTop = pictureAlert.OriginalBodyTopForProbe
                        + pictureAlert.OriginalBodyHeightForProbe + 18;
                    if (pictureButton == null || (int)pictureButton.Width != 100
                        || pictureButton.X < 21 || pictureButton.X + pictureButton.Width > pictureAlert.BoxWidth - 21
                        || (int)pictureButton.Y != expectedButtonTop
                        || (int)pictureButton.Y + 33 != pictureAlert.Height - 21)
                    { ok = false; info += " pictureButton=" + (pictureButton != null ? pictureButton.X + "," + pictureButton.Y + " " + pictureButton.Width : "null") + ";"; }

                    pictureAlert.InterpolatedAnimation = 1f;
                    int screenW = FSO.Client.GameFacade.Screens.CurrentUIScreen.ScreenWidth;
                    int screenH = FSO.Client.GameFacade.Screens.CurrentUIScreen.ScreenHeight;
                    if (pictureAlert.X < 0 || pictureAlert.Y < 0
                        || pictureAlert.X + pictureAlert.BoxWidth > screenW
                        || pictureAlert.Y + pictureAlert.Height > screenH)
                    { ok = false; info += " pictureOffscreen=" + pictureAlert.X + "," + pictureAlert.Y + " " + pictureAlert.BoxWidth + "x" + pictureAlert.Height + ";"; }

                    try
                    {
                        var sc = FSO.Client.GameFacade.Screens.CurrentUIScreen;
                        sc.Add(pictureAlert);
                        var tree2 = new System.Collections.Generic.List<string> { "== picture dialog chrome ==" };
                        SurveyDump("dialog", tree2);
                        sc.Remove(pictureAlert);
                    }
                    catch (Exception ve) { ok = false; info += " pictureSurvey " + ve.GetType().Name + ";"; }
                }
                finally
                {
                    pictureAlert.Removed();
                    pictureAlert.Close();
                    pictureTexture.Dispose();
                }

                // 4. Exercise the exact R175 automatic-person composition. The
                // original mounts SimStub at (21,21), centers the native 45px
                // image inside its 133x103 field, and uses the decoded geometry
                // for this exact Easel.iff message.
                // UIIconCache's live avatar head source is 74x74; SetIcon's
                // requested 45x45 native dimensions must select and compose the
                // SimStub branch even though that source is larger.
                var stubTexture = new Microsoft.Xna.Framework.Graphics.Texture2D(gd, 74, 74);
                var stubPixels = Enumerable.Repeat(new Microsoft.Xna.Framework.Color(85, 138, 198),
                    74 * 74).ToArray();
                stubTexture.SetData(stubPixels);
                var stubAlert = new Simitone.Client.UI.Panels.UIMobileAlert(new FSO.Client.UI.Controls.UIAlertOptions
                {
                    Title = "Congratulations!",
                    Message = "What vision, what talent! Bella received one Creativity Skill Point.",
                    Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                        new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null, "OK")
                    }
                }, true);
                try
                {
                    stubAlert.SetIcon(stubTexture, 45, 45);
                    var stub = stubAlert.OriginalIconStubForProbe;
                    var portrait = stubAlert.OriginalIconForProbe;
                    if (stub == null || !stub.Visible || stub.Texture == null
                        || stub.Texture.Width != 133 || stub.Texture.Height != 103
                        || (int)stub.X != 21 || (int)stub.Y != 21)
                    { ok = false; info += " simStub=" + (stub != null && stub.Texture != null ? stub.Texture.Width + "x" + stub.Texture.Height + "@" + (int)stub.X + "," + (int)stub.Y : "null") + ";"; }
                    if (portrait == null || (int)portrait.X != 65 || (int)portrait.Y != 50
                        || (int)portrait.Width != 45 || (int)portrait.Height != 45)
                    { ok = false; info += " portrait=" + (portrait != null ? (int)portrait.X + "," + (int)portrait.Y + " " + (int)portrait.Width + "x" + (int)portrait.Height : "null") + ";"; }

                    var titleFont = Simitone.Client.UI.Controls.OriginalGlyphFont.LoadByIndex(14, gd);
                    var titlePos = stubAlert.OriginalTitlePositionForProbe;
                    var bodyLines = stubAlert.OriginalBodyLinesForProbe;
                    var okButton = stubAlert.ButtonMap.Values.FirstOrDefault();
                    if (stubAlert.BoxWidth != 407 || (int)stubAlert.Height != 207
                        || titleFont == null || titleFont.Measure("Congratulations!") != 157
                        || (int)titlePos.X != 191 || (int)titlePos.Y != 21
                        || stubAlert.OriginalBodyTopForProbe != 66
                        || bodyLines == null || bodyLines.Count == 0
                        // body control starts at x=21; its first line advances
                        // past the 151px SimStub+gap exclusion to x=172.
                        || (int)bodyLines[0].X != 172 || (int)bodyLines[0].Y != 66
                        || okButton == null || (int)okButton.Width != 100
                        || (int)okButton.X != 153 || (int)okButton.Y != 153)
                    { ok = false; info += " congratulationsPortraitLaw;"; }

                    stubAlert.InterpolatedAnimation = 1f;
                    try
                    {
                        var sc = FSO.Client.GameFacade.Screens.CurrentUIScreen;
                        sc.Add(stubAlert);
                        var tree = new System.Collections.Generic.List<string>
                        {
                            "== Congratulations ObjectDialog portrait law =="
                        };
                        SurveyDump("dialog-congratulations", tree);
                        sc.Remove(stubAlert);
                    }
                    catch (Exception ve) { ok = false; info += " congratulationsSurvey " + ve.GetType().Name + ";"; }
                }
                finally
                {
                    FSO.Client.GameFacade.Screens.CurrentUIScreen?.Remove(stubAlert);
                    stubAlert.Removed();
                    stubAlert.Close();
                    stubTexture.Dispose();
                }

                // Preserve the independent-width multi-button law alongside the
                // exact one-button Congratulations composition above.
                var multiStubTexture = new Microsoft.Xna.Framework.Graphics.Texture2D(gd, 45, 45);
                multiStubTexture.SetData(Enumerable.Repeat(
                    new Microsoft.Xna.Framework.Color(85, 138, 198), 45 * 45).ToArray());
                const string wideCaption = "A deliberately wider choice";
                var multiStubAlert = new Simitone.Client.UI.Panels.UIMobileAlert(
                    new FSO.Client.UI.Controls.UIAlertOptions
                    {
                        Title = "Sim Portrait",
                        Message = "The native portrait is centered on the original stub.",
                        Buttons = new FSO.Client.UI.Controls.UIAlertButton[] {
                            new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.OK, null, "OK"),
                            new FSO.Client.UI.Controls.UIAlertButton(FSO.Client.UI.Controls.UIAlertButtonType.Cancel, null, wideCaption)
                        }
                    }, true);
                try
                {
                    multiStubAlert.SetIcon(multiStubTexture, 45, 45);
                    FSO.Client.UI.Controls.UIButton shortButton;
                    FSO.Client.UI.Controls.UIButton wideButton;
                    if (!multiStubAlert.ButtonMap.TryGetValue(FSO.Client.UI.Controls.UIAlertButtonType.OK, out shortButton)
                        || !multiStubAlert.ButtonMap.TryGetValue(FSO.Client.UI.Controls.UIAlertButtonType.Cancel, out wideButton))
                    { ok = false; info += " pictureButtonsMissing;"; }
                    else
                    {
                        int spacing = (multiStubAlert.OriginalTextWidthForProbe
                            - (int)shortButton.Width - (int)wideButton.Width) / 3;
                        if (spacing < 0) spacing = 9;
                        if ((int)shortButton.Width != 100 || wideButton.Width <= shortButton.Width
                            || multiStubAlert.OriginalTextWidthForProbe < shortButton.Width + wideButton.Width + 60
                            || (int)shortButton.X != 21 + spacing
                            || (int)wideButton.X != 21 + spacing * 2 + (int)shortButton.Width)
                        { ok = false; info += " independentButtons=" + shortButton.Width + "," + wideButton.Width + " spacing=" + spacing + ";"; }
                    }
                }
                finally
                {
                    multiStubAlert.Removed();
                    multiStubAlert.Close();
                    multiStubTexture.Dispose();
                }

                // 5. pie canon: art resolves + the slice band law exact, on
                // the decoded label frame law (UI-11;
                // tools/iff-dump/pie-label-paint-law.md): every bubble is the
                // measured label rect + 3px per side (cTSPieMenu::Layout
                // 0x5290c0, DrawLabelFrame 0x528d10), height growing with the
                // text. Supersedes the R142-era 8px inset / fixed 17px
                // height model.
                Microsoft.Xna.Framework.Graphics.Texture2D pieButtonArt = null;
                try
                {
                    var pb = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("shared\\sys\\PieButt.bmp")?.Get(gd);
                    pieButtonArt = pb;
                    var vm = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("cpanel\\ViewMenuBackground.bmp")?.Get(gd);
                    if (pb == null || pb.Width != 17 || pb.Height != 17) { ok = false; info += " piebutt=" + (pb != null ? pb.Width + "x" + pb.Height : "null") + ";"; }
                    if (vm == null || vm.Width != 17 || vm.Height != 17) { ok = false; info += " viewmenu=" + (vm != null ? vm.Width + "x" + vm.Height : "null") + ";"; }
                }
                catch (Exception pe) { ok = false; info += " pieArt EXC " + pe.GetType().Name + ";"; }
                int[] input = { 0, 1, 2, 3, 4, 5, 8, 12 };
                int[] law =   { 1, 3, 4, 7, 8, 13, 16, 20 };
                for (int i = 0; i < input.Length; i++)
                {
                    var got = Simitone.Client.UI.Panels.UIPieMenu.SliceCount(input[i]);
                    if (got != law[i]) { ok = false; info += " slices(" + input[i] + ")=" + got + " want " + law[i] + ";"; }
                }
                if (Simitone.Client.UI.Panels.UIPieMenu.OriginalButtonMargin != 3)
                { ok = false; info += " pieMargin=" + Simitone.Client.UI.Panels.UIPieMenu.OriginalButtonMargin + "!=3;"; }
                if (pieButtonArt != null)
                {
                    const string caption = "Go Here";
                    var style = new FSO.Client.UI.Framework.TextStyle
                    {
                        Font = GameFacade.MainFont,
                        VFont = GameFacade.VectorFont,
                        Size = 12,
                        Color = Color.White
                    };
                    var pieProbe = new Simitone.Client.UI.Panels.UIPieBubble
                    {
                        Caption = caption,
                        CaptionStyle = style,
                        ImageStates = 1,
                        Texture = pieButtonArt
                    };
                    pieProbe.AutoMargins = Simitone.Client.UI.Panels.UIPieMenu.OriginalButtonMargin;
                    pieProbe.FitToCaption();
                    int textAdvance = (int)style.MeasureString(caption).X;
                    int textHeight = (int)style.MeasureString(caption).Y;
                    int wantedWidth = textAdvance + 2 * Simitone.Client.UI.Panels.UIPieMenu.OriginalButtonMargin;
                    int wantedHeight = textHeight + 2 * Simitone.Client.UI.Panels.UIPieMenu.OriginalButtonMargin;
                    if ((int)pieProbe.Width != wantedWidth || pieProbe.GetBounds().Width != wantedWidth
                        || pieProbe.GetBounds().Height != wantedHeight)
                    { ok = false; info += " goHere=" + (int)pieProbe.Width + "x" + pieProbe.GetBounds().Height
                        + " want " + wantedWidth + "x" + wantedHeight + ";"; }
                }

                Log("AUTOTEST uidlgchrome original-dialog+pie canon" + (ok ? ": OK " : ": FAIL ") + info);
                if (ok) Pass("uidlgchrome"); else Fail("uidlgchrome");
            }
            catch (Exception ce) { Log("AUTOTEST uidlgchrome EXC " + ce.GetType().Name + " " + ce.Message); Fail("uidlgchrome"); }
        }

        // ROUND-142 'uibargeom' — the original bottom-bar composition on the live
        // screen: MainPanel flush at (220, SH-100) with PanelBack at its natural
        // 804x100 (220+804 = 1024 = the original resolution's exact fit; the shared
        // band still reaches the right edge); R185 refines the subpanel law to the
        // native People host matrix — Mood/Personality 280x100, the other five
        // families 504x100 at the 1024 logical width (280 otherwise); the compact
        // motive rows sit inside the bar; the plate must not contain the fabricated
        // floor ordinal.
        private static void CheckUIBarGeometry()
        {
            try
            {
                var screen = FSO.Client.GameFacade.Screens?.CurrentUIScreen as Simitone.Client.UI.Screens.TS1GameScreen;
                var fe = screen?.Frontend;
                var mp = fe?.MainPanel;
                if (mp == null || fe.DesktopUCP == null)
                { Log("AUTOTEST uibargeom: no frontend (screen=" + (FSO.Client.GameFacade.Screens?.CurrentUIScreen?.GetType().Name ?? "null") + ")"); Fail("uibargeom"); return; }
                var ok = true; var info = "";
                int SW = screen.ScreenWidth, SH = screen.ScreenHeight;

                if ((int)mp.X != 220 || (int)mp.Y != SH - 100)
                { ok = false; info += " panel=" + (int)mp.X + "," + (int)mp.Y + " want 220," + (SH - 100) + ";"; }
                var pb = mp.OriginalPanelBack;
                int pbW = 804; // natural-size buffer; the viewport clips on narrow windows
                if (pb == null || (int)pb.Size.X != pbW || (int)pb.Size.Y != 100)
                { ok = false; info += " panelBack=" + (pb != null ? (int)pb.Size.X + "x" + (int)pb.Size.Y : "null") + " want " + pbW + "x100;"; }

                // R171/R172 seam audit: kBackPatch 2036 is the real 52x100
                // bridge at cpanel (168,50), ending exactly where the x=220
                // PanelBack child begins. cWinCPanel paints that parent surface
                // before its cWinViewControl/UCP child. Pin both local art order
                // and frontend sibling depth: the UCP's authored alpha curve
                // must composite over the opaque bridge, not be guillotined by it.
                var backPatch = mp.BackPatch;
                var panelChildren = mp.GetChildren().ToList();
                bool backPatchOrder = pb != null && backPatch != null
                    && panelChildren.IndexOf(pb) >= 0
                    && panelChildren.IndexOf(backPatch) > panelChildren.IndexOf(pb);
                var frontendChildren = fe.GetChildren().ToList();
                bool seamDepth = frontendChildren.Count(c => object.ReferenceEquals(c, mp)) == 1
                    && frontendChildren.Count(c => object.ReferenceEquals(c, fe.DesktopUCP)) == 1
                    && frontendChildren.IndexOf(mp) >= 0
                    && frontendChildren.IndexOf(fe.DesktopUCP) > frontendChildren.IndexOf(mp);
                if (backPatch == null || backPatch.Texture == null
                    || backPatch.Texture.Width != 52 || backPatch.Texture.Height != 100
                    || (int)backPatch.X != -52 || (int)backPatch.Y != 0
                    || (int)(mp.X + backPatch.X) != 168
                    || (int)(mp.X + backPatch.X + backPatch.Texture.Width) != 220
                    || !backPatchOrder || !seamDepth)
                {
                    ok = false;
                    info += " backPatch=" + (backPatch?.Texture != null
                        ? backPatch.Texture.Width + "x" + backPatch.Texture.Height + "@"
                            + (int)backPatch.X + "," + (int)backPatch.Y
                        : "null") + "/localOrder=" + backPatchOrder
                        + "/frontendDepth=" + seamDepth + ";";
                }

                var sub = mp.SubPanel;
                if (sub != null)
                {
                    // R185 native People host matrix (r185-bottom-right-regression.md):
                    // Mood/Personality keep a 280x100 content host even at 1024 (the
                    // shared 804x100 band behind them still reaches the screen edge),
                    // while Relationship/Job/House/Interest/Gift expand to 504 exactly
                    // at the 1024 logical width. Non-People panels keep the R142
                    // full-band law: right edge == SW.
                    bool moodOrPersonality = sub is Simitone.Client.UI.Panels.LiveSubpanels.UIMotiveSubpanel
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIPersonalitySubpanel;
                    bool peopleHost = moodOrPersonality
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIRelationshipSubpanel
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIJobSubpanel
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIHouseSubpanel
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalInterestSubpanel
                        || sub is Simitone.Client.UI.Panels.LiveSubpanels.UIOriginalGiftSubpanel;
                    int wantW = !peopleHost ? (int)(SW - mp.X - sub.Position.X)
                        : moodOrPersonality ? 280
                        : (SW == 1024 ? 504 : 280);
                    if ((int)sub.Size.X != wantW) { ok = false; info += " subW=" + (int)sub.Size.X + " want " + wantW + ";"; }
                    if ((int)sub.Size.Y != 100) { ok = false; info += " subH=" + (int)sub.Size.Y + " want 100;"; }
                }

                if (fe.DesktopUCP.FloorOriginal != null || fe.DesktopUCP.FloorLabel != null || fe.DesktopUCP.FloorLabelShadow != null)
                { ok = false; info += " floor-ordinal-present;"; }

                // The original people chrome uses custom-drawn UIButton subclasses.
                // UIButton.Size normally ignores Y, so pin both their public geometry
                // and their actual mouse bounds to the decoded art cells.
                var people = mp.PeopleChrome;
                if (people == null || people.Webcams == null || people.Webcams.Length != 8)
                { ok = false; info += " webcams=" + (people?.Webcams != null ? people.Webcams.Length.ToString() : "null") + ";"; }
                else for (int i = 0; i < people.Webcams.Length; i++)
                    {
                        var webcam = people.Webcams[i];
                        var hit = webcam?.GetBounds() ?? Rectangle.Empty;
                        if (webcam == null || webcam.Index != i || (int)webcam.Size.X != 45 || (int)webcam.Size.Y != 45
                            || hit.Width != 45 || hit.Height != 45
                            || webcam.Tooltip != webcam.Avatar?.Name)
                        { ok = false; info += " webcam" + i + "=" + (webcam != null ? (int)webcam.Size.X + "x" + (int)webcam.Size.Y + "/hit" + hit.Width + "x" + hit.Height + "/idx" + webcam.Index : "null") + ";"; }
                    }

                // An unoccupied family slot uses the blank normal cell from
                // PeopleTemplate.bmp. UnknownFace.bmp is an anonymous-person
                // portrait sheet and produced the repeated/upside-down heads.
                var emptyWebcam = new Simitone.Client.UI.Panels.UIOriginalWebcamButton(99);
                emptyWebcam.SetAvatar(null);
                var emptyBase = emptyWebcam.CurrentBaseTextureForProbe;
                if (emptyBase == null || emptyBase.Width != 45 || emptyBase.Height != 45
                    || !object.ReferenceEquals(emptyBase, emptyWebcam.NormalFrameForProbe)
                    || emptyWebcam.Tooltip != null)
                { ok = false; info += " emptyWebcam=" + (emptyBase != null ? emptyBase.Width + "x" + emptyBase.Height : "null") + "/not-template;"; }

                int[] tabW = { 32, 27, 27, 27, 27, 27, 27 };
                int[] tabH = { 39, 30, 30, 30, 30, 30, 30 };
                if (people == null || people.Tabs == null || people.Tabs.Length != 7)
                { ok = false; info += " peopleTabs=" + (people?.Tabs != null ? people.Tabs.Length.ToString() : "null") + ";"; }
                else for (int i = 0; i < people.Tabs.Length; i++)
                    {
                        var tab = people.Tabs[i];
                        var hit = tab?.GetBounds() ?? Rectangle.Empty;
                        if (tab == null || tab.CellWidth != tabW[i] || tab.CellHeight != tabH[i]
                            || (int)tab.Size.X != tabW[i] || (int)tab.Size.Y != tabH[i]
                            || hit.Width != tabW[i] || hit.Height != tabH[i])
                        { ok = false; info += " tab" + i + "=" + (tab != null ? (int)tab.Size.X + "x" + (int)tab.Size.Y + "/hit" + hit.Width + "x" + hit.Height : "null") + ";"; }
                    }

                Log("AUTOTEST uibargeom original-bar-composition" + (ok ? ": OK" : ": FAIL") +
                    " panel=" + (int)mp.X + "," + (int)mp.Y + " back=" + (pb != null ? (int)pb.Size.X + "x" + (int)pb.Size.Y : "null") +
                    " bridge=" + (backPatch?.Texture != null ? backPatch.Texture.Width + "x" + backPatch.Texture.Height + "@168..220" : "null") +
                    " sub=" + (sub != null ? (int)sub.Size.X + "x" + (int)sub.Size.Y + "@r" + (int)(mp.X + sub.Position.X + sub.Size.X) : "none") +
                    " peopleHit=8x45x45+32x39+6x27x30" +
                    (info.Length > 0 ? " " + info.Trim() : ""));
                if (ok) Pass("uibargeom"); else Fail("uibargeom");
            }
            catch (Exception ce) { Log("AUTOTEST uibargeom EXC " + ce.GetType().Name + " " + ce.Message); Fail("uibargeom"); }
        }

        // UIQUEUEGEOM (Round 169): cActionIcon/UpdateActionIcons canon decoded from
        // the original executable. Queue cells are 45x45, target top-lefts are
        // (32+50*i,32), StartAnimating uses 500ms, and a pie-menu source begins at
        // (clickX-16,clickY-16). IconFrame is a 90x45 two-cell overlay; QueueCancel
        // is a 45x45 overlay painted afterward. Canon sheets select column zero and
        // the middle row when the source is 135px high.
        private static void CheckUIQueueGeometry()
        {
            try
            {
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (gd == null) { Log("AUTOTEST uiqueuegeom: no graphics device"); Fail("uiqueuegeom"); return; }
                var ok = true; var info = "";

                if (!Simitone.Client.UI.Controls.UIInteraction.OriginalStyle)
                { ok = false; info += " originalStyle=false;"; }

                var frame = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("cpanel\\Buttons\\IconFrame.bmp")?.Get(gd);
                var cancel = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("other\\QueueCancel.bmp")?.Get(gd);
                if (frame == null || frame.Width != 90 || frame.Height != 45)
                { ok = false; info += " frame=" + (frame != null ? frame.Width + "x" + frame.Height : "null") + "!=90x45;"; }
                if (cancel == null || cancel.Width != 45 || cancel.Height != 45)
                { ok = false; info += " cancel=" + (cancel != null ? cancel.Width + "x" + cancel.Height : "null") + "!=45x45;"; }

                var p0 = Simitone.Client.UI.Panels.UIInteractionQueue.GetOriginalQueuePosition(0);
                var p3 = Simitone.Client.UI.Panels.UIInteractionQueue.GetOriginalQueuePosition(3);
                if (p0 != new Microsoft.Xna.Framework.Vector2(32, 32) || p3 != new Microsoft.Xna.Framework.Vector2(182, 32))
                { ok = false; info += " targets=" + p0.X + "," + p0.Y + "/" + p3.X + "," + p3.Y + ";"; }
                if (Math.Abs(Simitone.Client.UI.Panels.UIInteractionQueue.OriginalQueuePitch - 50f) > 0.001f
                    || Math.Abs(Simitone.Client.UI.Panels.UIInteractionQueue.OriginalRepositionSeconds - 0.5f) > 0.001f
                    || Math.Abs(Simitone.Client.UI.Panels.UIInteractionQueue.OriginalPieSourceInset - 16f) > 0.001f)
                { ok = false; info += " pitch/time/inset;"; }

                var s45 = Simitone.Client.UI.Controls.UIInteraction.OriginalSourceRectangle(45, 45);
                var s180 = Simitone.Client.UI.Controls.UIInteraction.OriginalSourceRectangle(180, 45);
                var s270 = Simitone.Client.UI.Controls.UIInteraction.OriginalSourceRectangle(270, 135);
                if (s45 != new Microsoft.Xna.Framework.Rectangle(0, 0, 45, 45)
                    || s180 != new Microsoft.Xna.Framework.Rectangle(0, 0, 45, 45)
                    || s270 != new Microsoft.Xna.Framework.Rectangle(0, 45, 45, 45))
                { ok = false; info += " sourceRects=" + s45 + "/" + s180 + "/" + s270 + ";"; }

                var probe = new Simitone.Client.UI.Controls.UIInteraction(false);
                var click = probe.InteractionClickRegion;
                if (click != new Microsoft.Xna.Framework.Rectangle(0, 0, 45, 45)
                    || probe.GetBounds() != new Microsoft.Xna.Framework.Rectangle(0, 0, 45, 45))
                { ok = false; info += " click=" + click + " bounds=" + probe.GetBounds() + ";"; }
                if (probe.OriginalFrameTexture == null || probe.OriginalFrameTexture.Width != 90 || probe.OriginalFrameTexture.Height != 45)
                { ok = false; info += " mountedFrame;"; }

                // Paint-order gate: IconFrame.bmp is fully opaque. A solid
                // sentinel action bitmap must therefore remain visible at the
                // center only when the production draw path paints frame first
                // and action icon second.
                var sentinel = new Microsoft.Xna.Framework.Graphics.Texture2D(gd, 45, 45);
                try
                {
                    var sentinelColor = new Color(237, 31, 47, 255);
                    sentinel.SetData(Enumerable.Repeat(sentinelColor, 45 * 45).ToArray());
                    probe.Icon = sentinel;
                    var sampled = RenderElementPixel(probe, 22, 22);
                    if (Math.Abs(sampled.R - sentinelColor.R) > 2
                        || Math.Abs(sampled.G - sentinelColor.G) > 2
                        || Math.Abs(sampled.B - sentinelColor.B) > 2
                        || sampled.A < 250)
                    { ok = false; info += " frameOrderPixel=" + sampled.R + "," + sampled.G + "," + sampled.B + "," + sampled.A + ";"; }
                }
                finally { sentinel.Dispose(); }
                probe.SetActive(true);
                if (probe.InteractionClickRegion != new Microsoft.Xna.Framework.Rectangle(0, 0, 45, 45)
                    || Math.Abs(probe.ScaleX - 1f) > 0.001f || Math.Abs(probe.ScaleY - 1f) > 0.001f)
                { ok = false; info += " activeGeometry;"; }
                probe.SetCancelled();
                if (probe.OriginalCancelTexture == null || probe.OriginalCancelTexture.Width != 45 || probe.OriginalCancelTexture.Height != 45
                    || Math.Abs(probe.OverlayScale - 1f) > 0.001f)
                { ok = false; info += " mountedCancel;"; }

                Log("AUTOTEST uiqueuegeom original-action-queue" + (ok ? ": OK" : ": FAIL ") + info);
                if (ok) Pass("uiqueuegeom"); else Fail("uiqueuegeom");
            }
            catch (Exception ce) { Log("AUTOTEST uiqueuegeom EXC " + ce.GetType().Name + " " + ce.Message); Fail("uiqueuegeom"); }
        }

        // UICASORIG (Round 143): the ORIGINAL 800x600 create-a-family flow on
        // decoded engine law (r143/cas-layout-law.md + nbhd-layout-law.md):
        // the BI_RLE8 far family resolves with the magic-pink transparency law
        // (idx0 opaque), every DesignChar/DesignFamily/PickAFamily anchor is a
        // decoded immediate, the personality LED law (draw value*6 / click
        // value*5, pool 25 down-counter, deny at 0), the points bar law, and
        // the engine zodiac table (data 0x4c144, Pisces zero-row fallback).
        private static void CheckUICASOrig()
        {
            try
            {
                var gd = FSO.Client.GameFacade.GraphicsDevice;
                if (gd == null) { Log("AUTOTEST uicasorig: no graphics device"); Fail("uicasorig"); return; }
                var ok = true; var info = "";

                // 1. RLE8 art resolves at full dims through the far resolver
                var art = new (string, int, int)[] {
                    ("nbhd\\CreateACharBack.BMP", 800, 600),
                    ("nbhd\\DsgnFamBkg.bmp", 800, 600),
                    ("nbhd\\PickBkg.bmp", 800, 600),
                    ("nbhd\\DesignCharPersLED.bmp", 59, 25),
                    ("nbhd\\CACPointRemainingBars.bmp", 149, 25),
                    ("nbhd\\FamilyPickItemBkg.bmp", 690, 204),
                    ("nbhd\\PAFMoveIn.bmp", 656, 62),
                    ("nbhd\\NbhdTileBtn.BMP", 364, 62),
                };
                foreach (var a in art)
                {
                    var tx = Simitone.Client.UI.Model.UIOriginal.EnsureResolved(a.Item1)?.Get(gd);
                    if (tx == null || tx.Width != a.Item2 || tx.Height != a.Item3)
                    { ok = false; info += " art[" + a.Item1 + "]=" + (tx != null ? tx.Width + "x" + tx.Height : "null") + " want " + a.Item2 + "x" + a.Item3 + ";"; }
                }

                // 2. transparency law: idx0 OPAQUE (PickBkg corner), magic-pink
                //    entries transparent (AddPersonBtn corner outside its shape)
                try
                {
                    var pick = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("nbhd\\PickBkg.bmp")?.Get(gd);
                    var add = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("nbhd\\AddPersonBtn.bmp")?.Get(gd);
                    if (pick != null)
                    {
                        var d = new Microsoft.Xna.Framework.Color[1];
                        pick.GetData(0, new Microsoft.Xna.Framework.Rectangle(0, 0, 1, 1), d, 0, 1);
                        if (d[0].A != 255) { ok = false; info += " pickBkg(0,0).A=" + d[0].A + " want 255 (idx0 opaque);"; }
                    }
                    if (add != null)
                    {
                        var d = new Microsoft.Xna.Framework.Color[1];
                        add.GetData(0, new Microsoft.Xna.Framework.Rectangle(0, 0, 1, 1), d, 0, 1);
                        if (d[0].A != 0) { ok = false; info += " addBtn(0,0).A=" + d[0].A + " want 0 (magic-pink key);"; }
                    }
                }
                catch (Exception tex) { ok = false; info += " alphaEXC " + tex.GetType().Name + ";"; }

                // 3. DesignChar: every anchor + sheet state width (decoded table §3.1)
                var cas = new Simitone.Client.UI.Panels.CAS.UIOriginalDesignChar();
                var casPins = new (FSO.Client.UI.Framework.UIElement, int, int, string)[] {
                    (cas.AdultBtn, 497, 101, "adult"), (cas.ChildBtn, 406, 111, "child"),
                    (cas.FemaleBtn, 499, 274, "female"), (cas.MaleBtn, 400, 274, "male"),
                    (cas.DarkBtn, 499, 202, "dark"), (cas.MediumBtn, 452, 202, "medium"), (cas.LightBtn, 396, 202, "light"),
                    (cas.BodyPrevBtn, 580, 291, "bodyPrev"), (cas.BodyNextBtn, 729, 291, "bodyNext"),
                    (cas.HeadPrevBtn, 597, 160, "headPrev"), (cas.HeadNextBtn, 714, 160, "headNext"),
                };
                foreach (var pin in casPins)
                {
                    if ((int)pin.Item1.X != pin.Item2 || (int)pin.Item1.Y != pin.Item3)
                    { ok = false; info += " " + pin.Item4 + "=" + (int)pin.Item1.X + "," + (int)pin.Item1.Y + " want " + pin.Item2 + "," + pin.Item3 + ";"; }
                }
                var casSheets = new (Simitone.Client.UI.Panels.CAS.UIOriginalSheetButton, int, string)[] {
                    (cas.AdultBtn, 57, "adultW"), (cas.ChildBtn, 92, "childW"), (cas.FemaleBtn, 57, "femaleW"),
                    (cas.MaleBtn, 98, "maleW"), (cas.DarkBtn, 57, "darkW"), (cas.MediumBtn, 46, "mediumW"),
                    (cas.LightBtn, 55, "lightW"), (cas.BodyPrevBtn, 18, "arrowW"),
                };
                foreach (var pin in casSheets)
                {
                    if (pin.Item1.StateWidth != pin.Item2) { ok = false; info += " " + pin.Item3 + "=" + pin.Item1.StateWidth + " want " + pin.Item2 + ";"; }
                }
                if ((int)cas.NameBox.X != 275 || (int)cas.NameBox.Y != 52 || cas.NameBox.MaxChars != 25)
                { ok = false; info += " nameBox=" + (int)cas.NameBox.X + "," + (int)cas.NameBox.Y + " cap=" + cas.NameBox.MaxChars + " want 275,52 cap25;"; }
                if ((int)cas.BioEdit.X != 22 || (int)cas.BioEdit.Y != 425 || cas.BioEdit.Capacity != 2048)
                { ok = false; info += " bioBox cap=" + cas.BioEdit.Capacity + " want 2048 @22,425;"; }
                // R183 system-button law: the provisional 200px SetArea is
                // narrowed and recentered by SetCaption to textWidth+70.
                // English font[12] measures Done=39 and Cancel=51.
                if ((int)cas.DoneBtn.X != 56 || (int)cas.CancelBtn.X != 339 || (int)cas.DoneBtn.Y != 529
                    || cas.DoneBtn.ControlWidth != 109 || cas.CancelBtn.ControlWidth != 121
                    || cas.DoneBtn.StateWidth != 91 || cas.CancelBtn.StateWidth != 91
                    || cas.DoneBtn.FontIndex != 12 || cas.CancelBtn.FontIndex != 12
                    || (int)cas.DoneBtn.Caption.X != 35 || (int)cas.DoneBtn.Caption.Y != 19
                    || cas.DoneBtn.Caption.Font == null || cas.DoneBtn.Caption.Font.LineHeight != 23)
                {
                    ok = false;
                    info += " sysBtns=" + (int)cas.DoneBtn.X + "/" + (int)cas.CancelBtn.X
                        + " widths=" + cas.DoneBtn.ControlWidth + "/" + cas.CancelBtn.ControlWidth
                        + " state=" + cas.DoneBtn.StateWidth + " font=" + cas.DoneBtn.FontIndex
                        + " cap=" + (int)cas.DoneBtn.Caption.X + "," + (int)cas.DoneBtn.Caption.Y
                        + " want x56/339 widths109/121 state91 font12 cap35,19;";
                }

                // Native command dispatch is release-inside, with capture
                // disarmed on leave and rearmed on re-entry. The caption uses
                // the same four-state colors and the pressed +2,+2 offset.
                int systemClicks = 0;
                cas.DoneBtn.OnButtonClick += (b) => systemClicks++;
                var mouseState = new FSO.Common.Rendering.Framework.Model.UpdateState();
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, mouseState);
                bool systemHover = cas.DoneBtn.CurrentArtFrame == 2 && cas.DoneBtn.Caption.Color == Color.White;
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, mouseState);
                bool systemDown = cas.DoneBtn.CurrentArtFrame == 1
                    && cas.DoneBtn.Caption.Color == new Color(0x00, 0xFF, 0xFF)
                    && (int)cas.DoneBtn.Caption.X == 37 && (int)cas.DoneBtn.Caption.Y == 21;
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut, mouseState);
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, mouseState);
                bool systemDragOut = systemClicks == 0 && !cas.DoneBtn.Captured && !cas.DoneBtn.Pressed;
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, mouseState);
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, mouseState);
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOut, mouseState);
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, mouseState);
                cas.DoneBtn.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, mouseState);
                bool systemDragBack = systemClicks == 1 && cas.DoneBtn.CurrentArtFrame == 2;
                cas.DoneBtn.Disabled = true;
                bool systemDisabled = cas.DoneBtn.CurrentArtFrame == 3
                    && cas.DoneBtn.Caption.Color == new Color(0x40, 0x5D, 0x5F);
                cas.DoneBtn.Disabled = false;
                if (!systemHover || !systemDown || !systemDragOut || !systemDragBack || !systemDisabled
                    || cas.DoneBtn.CurrentArtTexture == null || cas.DoneBtn.CurrentArtTexture.Width != 91
                    || cas.DoneBtn.CurrentArtTexture.Height != 62
                    || cas.DoneBtn.GetBounds() != new Rectangle(0, 0, 109, 62))
                {
                    ok = false;
                    info += " sysState=" + systemHover + "/" + systemDown + "/" + systemDragOut
                        + "/" + systemDragBack + "/" + systemDisabled + " clicks=" + systemClicks + ";";
                }

                // Every cropped state must be the corresponding 91px source
                // cell from the 364px sheet. (The native hover/disabled art
                // cells happen to be pixel-identical to normal, so object or
                // digest distinctness would be the wrong invariant.)
                var systemSheet = Simitone.Client.UI.Model.UIOriginal.EnsureResolved("nbhd\\NbhdTileBtn.BMP")?.Get(gd);
                bool systemCrops = systemSheet != null;
                if (systemSheet != null)
                {
                    var sheetPixels = new Color[systemSheet.Width * systemSheet.Height];
                    systemSheet.GetData(sheetPixels);
                    for (int frame = 0; frame < 4 && systemCrops; frame++)
                    {
                        var stateTex = cas.DoneBtn.GetArtState(frame);
                        if (stateTex == null || stateTex.Width != 91 || stateTex.Height != 62)
                        {
                            systemCrops = false;
                            break;
                        }
                        var statePixels = new Color[91 * 62];
                        stateTex.GetData(statePixels);
                        for (int y = 0; y < 62 && systemCrops; y++)
                            for (int x = 0; x < 91; x++)
                                if (statePixels[y * 91 + x] != sheetPixels[y * 364 + frame * 91 + x])
                                {
                                    systemCrops = false;
                                    break;
                                }
                    }
                }

                // Paint-path gate for the nonuniform 45/1/45 ImageBlt law.
                // Row 1 is caption-free and has distinct pixels at the two
                // cap seams; uniform 91->109 scaling cannot satisfy all three.
                bool systemSlices = false;
                var sliceProbe = new Simitone.Client.UI.Panels.CAS.UIOriginalSystemButton("Done",
                    Simitone.Client.UI.Controls.OriginalGlyphFont.LoadCaption(gd));
                var normalState = sliceProbe.GetArtState(0);
                if (normalState != null)
                {
                    var src = new Color[91 * 62];
                    normalState.GetData(src);
                    CalculateElementMatrixChain(sliceProbe);
                    var leftSeam = RenderElementPixel(sliceProbe, 44, 1);
                    var stretchedCenter = RenderElementPixel(sliceProbe, 50, 1);
                    var rightSeam = RenderElementPixel(sliceProbe, 64, 1);
                    Func<Color, Color, bool> close = (a, b) => Math.Abs(a.R - b.R) <= 2
                        && Math.Abs(a.G - b.G) <= 2 && Math.Abs(a.B - b.B) <= 2
                        && Math.Abs(a.A - b.A) <= 2;
                    systemSlices = close(leftSeam, src[1 * 91 + 44])
                        && close(stretchedCenter, src[1 * 91 + 45])
                        && close(rightSeam, src[1 * 91 + 46]);
                }
                if (!systemCrops || !systemSlices)
                { ok = false; info += " sysArt=crops:" + systemCrops + "/slices:" + systemSlices + ";"; }

                // 4. personality LED law: rows at (228, 131+32i); pool down-counter;
                //    draw pitch 6 / click pitch 5; deny at pool 0; lit = value*6
                for (int i = 0; i < 5; i++)
                {
                    int wantY = 131 + i * 32;
                    if ((int)cas.LedStrips[i].X != 228 || (int)cas.LedStrips[i].Y != wantY)
                    { ok = false; info += " led" + i + "=" + (int)cas.LedStrips[i].X + "," + (int)cas.LedStrips[i].Y + " want 228," + wantY + ";"; }
                }
                if (Simitone.Client.UI.Panels.CAS.UIOriginalDesignChar.LED_DRAW_PITCH != 6 ||
                    Simitone.Client.UI.Panels.CAS.UIOriginalDesignChar.LED_CLICK_PITCH != 5)
                { ok = false; info += " pitchConsts;"; }
                cas.AdjustTrait(0, 1); cas.AdjustTrait(0, 1); cas.AdjustTrait(0, 1);
                if (cas.Values[0] != 3 || cas.Pool != 22) { ok = false; info += " plus=" + cas.Values[0] + "/p" + cas.Pool + " want 3/22;"; }
                if (cas.LedStrips[0].Texture == null || cas.LedStrips[0].Texture.Width != 18)
                { ok = false; info += " lit0=" + (cas.LedStrips[0].Texture != null ? cas.LedStrips[0].Texture.Width.ToString() : "null") + " want 18 (3*6);"; }
                if (cas.PointsBar.Texture == null || cas.PointsBar.Texture.Width != 132)
                { ok = false; info += " ptsBar=" + (cas.PointsBar.Texture != null ? cas.PointsBar.Texture.Width.ToString() : "null") + " want 132 (22*6);"; }
                cas.AdjustTrait(0, -1);
                if (cas.Values[0] != 2 || cas.Pool != 23) { ok = false; info += " minus=" + cas.Values[0] + "/p" + cas.Pool + " want 2/23;"; }
                cas.Values[0] = 10; cas.Pool = 0; cas.UpdateLeds();
                int denyBefore = cas.Values[1];
                cas.AdjustTrait(1, 1);
                if (cas.Values[1] != denyBefore) { ok = false; info += " denyFailed;"; }
                if (cas.LedStrips[0].Texture == null || cas.LedStrips[0].Texture.Width != 59)
                { ok = false; info += " litClamp=" + (cas.LedStrips[0].Texture != null ? cas.LedStrips[0].Texture.Width.ToString() : "null") + " want 59;"; }

                // 5. zodiac table: nearest archetype; Pisces zero-row = unassigned
                cas.Values = new int[] { 5, 4, 8, 5, 3 }; if (cas.ComputeZodiac() != 0) { ok = false; info += " zodiacAries=" + cas.ComputeZodiac() + ";"; }
                cas.Values = new int[] { 7, 3, 3, 4, 8 }; if (cas.ComputeZodiac() != 1) { ok = false; info += " zodiacTaurus=" + cas.ComputeZodiac() + ";"; }
                cas.Values = new int[] { 0, 0, 0, 0, 0 }; if (cas.ComputeZodiac() != 11) { ok = false; info += " zodiacPisces=" + cas.ComputeZodiac() + ";"; }

                // 6. DesignFamily anchors + slot grid (§4)
                var fam = new Simitone.Client.UI.Panels.CAS.UIOriginalDesignFamily();
                if ((int)fam.AddBtn.X != 593 || (int)fam.AddBtn.Y != 103 || fam.AddBtn.StateWidth != 139)
                { ok = false; info += " famAdd;"; }
                if ((int)fam.DeleteBtn.X != 594 || (int)fam.DeleteBtn.Y != 208 || fam.DeleteBtn.StateWidth != 149)
                { ok = false; info += " famDel;"; }
                if ((int)fam.EditBtn.X != 594 || (int)fam.EditBtn.Y != 311 || fam.EditBtn.StateWidth != 137)
                { ok = false; info += " famEdit;"; }
                if ((int)fam.DoneBtn.X != 145 || (int)fam.CancelBtn.X != 539 || (int)fam.DoneBtn.Y != 529
                    || fam.DoneBtn.ControlWidth != 109 || fam.CancelBtn.ControlWidth != 121)
                { ok = false; info += " famSys=" + (int)fam.DoneBtn.X + "/" + (int)fam.CancelBtn.X + ";"; }
                if ((int)fam.FamilyNameBox.X != 274 || (int)fam.FamilyNameBox.Y != 50 || fam.FamilyNameBox.MaxChars != 24)
                { ok = false; info += " famName;"; }
                for (int i = 0; i < 8; i++)
                {
                    // Native cWinDesignFamily::Init 0x2d1850-0x2d1a5c: the flow flag at
                    // stack+0x108 is zeroed (0x2d1880), so the HORIZONTAL branch runs —
                    // four columns x two rows. CAS-01 corrected R143's vertical-first
                    // misread (tools/iff-dump/r143/cas-layout-law.md §4.3); the slots in
                    // UIOriginalCAS.cs follow this law.
                    int wx = 111 + (i % 4) * 120, wy = 121 + (i / 4) * 140;
                    if ((int)fam.Slots[i].X != wx || (int)fam.Slots[i].Y != wy)
                    { ok = false; info += " slot" + i + "=" + (int)fam.Slots[i].X + "," + (int)fam.Slots[i].Y + " want " + wx + "," + wy + ";"; }
                }

                // 7. PickFamily anchors (nbhd-layout-law.md §2)
                var pickPanel = new Simitone.Client.UI.Panels.CAS.UIOriginalPickFamily();
                if ((int)pickPanel.AddButton.X != 322 || (int)pickPanel.AddButton.Y != 530 || pickPanel.AddButton.StateWidth != 92)
                { ok = false; info += " pafAdd;"; }
                if ((int)pickPanel.DeleteButton.X != 414 || (int)pickPanel.DeleteButton.Y != 530 || pickPanel.DeleteButton.StateWidth != 92)
                { ok = false; info += " pafDel;"; }
                if ((int)pickPanel.MoveInButton.X != 506 || (int)pickPanel.MoveInButton.Y != 530 || pickPanel.MoveInButton.StateWidth != 164)
                { ok = false; info += " pafMoveIn;"; }
                if (pickPanel.CancelButton == null || (int)pickPanel.CancelButton.X != 139
                    || (int)pickPanel.CancelButton.Y != 529 || pickPanel.CancelButton.ControlWidth != 121
                    || pickPanel.CancelButton.Caption.Text != GameFacade.Strings.GetString("128", "5")
                    || pickPanel.CancelButton.Tooltip != GameFacade.Strings.GetString("128", "15")
                    || pickPanel.CancelButton.GetBounds() != new Rectangle(0, 0, 121, 62))
                { ok = false; info += " pafCancel;"; }
                int pafCancelCommands = 0;
                pickPanel.OnCancel += () => pafCancelCommands++;
                pickPanel.CancelButton.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseOver, mouseState);
                pickPanel.CancelButton.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseDown, mouseState);
                pickPanel.CancelButton.HandleMouseEvent(FSO.Common.Rendering.Framework.IO.UIMouseEventType.MouseUp, mouseState);
                if (pafCancelCommands != 1) { ok = false; info += " pafCancelCommand=" + pafCancelCommands + ";"; }

                // 8. evidence dumps: each constructed screen attached to the
                //    current screen, drawn, walked, detached (r142 dialog pattern)
                try
                {
                    var sc = FSO.Client.GameFacade.Screens.CurrentUIScreen;
                    if (sc != null)
                    {
                        var dumpSet = new (FSO.Client.UI.Framework.UIElement, string)[] {
                            (cas, "casorig-cac"), (fam, "casorig-fam"), (pickPanel, "casorig-paf") };
                        foreach (var dsv in dumpSet)
                        {
                            var vis = dsv.Item1.Visible;
                            dsv.Item1.Visible = true;
                            sc.Add(dsv.Item1);
                            var tree = new System.Collections.Generic.List<string>();
                            SurveyDump(dsv.Item2, tree);
                            sc.Remove(dsv.Item1);
                            dsv.Item1.Visible = vis;
                        }
                    }
                }
                catch (Exception de) { info += " dumpEXC " + de.GetType().Name + ";"; ok = false; }

                bool cas239 = AutotestCAS239.Check(out string cas239Info);
                Log("AUTOTEST uicasorig workflow239="+cas239+" "+cas239Info);
                ok &= cas239;
                bool cas240 = AutotestCAS240.Check(out string cas240Info);
                Log("AUTOTEST uicasorig workflow240="+cas240+" "+cas240Info);
                ok &= cas240;
                bool cas242 = AutotestCAS242.Check(cas, out string cas242Info);
                Log("AUTOTEST uicasorig composite242=" + cas242 + " " + cas242Info);
                ok &= cas242;

                // 9. CAS-02 (additive): the native Vita preview framing law and
                //    the single-line person name-editor law.
                //    Framing (cWinVitaBtn decode): UpdateTransform 0x2dbef0
                //    anchors the skeleton root at (window center, bottom-20);
                //    the VitaBoy render scale is the engine's standard Near
                //    scale on the raw mesh (PreciseZoom 1 = 30.17 px/WU, the
                //    refuted 64 px/WU chain replaced per the run
                //    reconciliation); look tile height 1.1482 puts the root
                //    on surface (50,200) through the cos-30 pitch factor.
                //    Resolution-free surface.
                var surface = cas.VitaSurface;
                if (surface == null) { ok = false; info += " vitaSurface=null;"; }
                else
                {
                    surface.EnsureCameraForProbe();
                    var cam = surface.CameraForProbe;
                    if (cam == null || cam.Zoom != FSO.LotView.WorldZoom.Near
                        || System.Math.Abs(cam.PreciseZoom - Simitone.Client.UI.Panels.CAS.UIOriginalVitaPreview.NativePreciseZoom) > 0.0001f
                        || cam.CenterTile != new Vector3(0, 0, Simitone.Client.UI.Panels.CAS.UIOriginalVitaPreview.NativeLookTileZ)
                        || cam.ViewDimensions != new Vector2(100, 220))
                    { ok = false; info += " vitaCam=" + (cam != null ? cam.Zoom + "/" + cam.PreciseZoom + "/" + cam.CenterTile + "/" + cam.ViewDimensions : "null") + ";"; }
                }
                //    Name (cTSWinTextEdit2): SetLinesAllowed(1) at 0x2cf4a4;
                //    TSOnCharacter 0x5336e8 normalizes CR to LF and never lets
                //    a line break enter the buffer; Return routes as the dialog
                //    default command (0x533728 -> 0x2cdffc cTSWinGenDlg) = Done.
                int enterDone = 0;
                cas.OnDone += () => enterDone++;
                var nameInput = new FSO.Common.Rendering.Framework.Model.UpdateState { Time = new Microsoft.Xna.Framework.GameTime(), WindowFocused = true,
                    InputManager = new FSO.Common.Rendering.Framework.IO.InputManager(), FrameTextInput = new List<char>() };
                nameInput.InputManager.SetFocus(cas.NameBox);
                cas.NameBox.CurrentText = "";
                nameInput.FrameTextInput = new List<char> { 'a', '\n', 'b', '\r', 'c' };
                cas.NameBox.Update(nameInput);
                nameInput.FrameTextInput = null;
                nameInput.NewKeys = new List<Microsoft.Xna.Framework.Input.Keys> { Microsoft.Xna.Framework.Input.Keys.Enter };
                cas.NameBox.Update(nameInput);
                nameInput.NewKeys = new List<Microsoft.Xna.Framework.Input.Keys>();
                if (cas.NameBox.CurrentText != "abc" || enterDone != 1)
                { ok = false; info += " nameSingleLine=" + cas.NameBox.CurrentText.Replace("\n", "\\n") + " enterDone=" + enterDone + " want abc/1;"; }

                Log("AUTOTEST uicasorig original-cas-screens" + (ok ? ": OK" : ": FAIL") + (info.Length > 0 ? " " + info.Trim() : ""));
                if (ok) Pass("uicasorig"); else Fail("uicasorig");
            }
            catch (Exception ce) { Log("AUTOTEST uicasorig EXC " + ce.GetType().Name + " " + ce.Message + " AT " + (ce.StackTrace ?? "").Replace("\n", " | ")); Fail("uicasorig"); }
        }

        // AUDIO runtime check: verify the engine's audio infra (HITVM) initializes and that a
        // PlaySoundEvent executes without exception on this macOS build (headless + OpenAL/CoreAudio
        // path). The created HITSound is ticked by the real game loop and re-checked at Finish.
        private static void CheckAudio()
        {
            try
            {
                var hit = FSO.HIT.HITVM.Get();
                if (hit == null) { Log("AUTOTEST audio: HITVM.Get() null (Init not called?)"); Fail("audio"); return; }
                var evts = FSO.Content.Content.Get().Audio?.Events;
                int evtCount = evts == null ? -1 : evts.Count;
                bool hasLotEnter = evts != null && evts.ContainsKey("lot_enter");
                int sndEnts = _vm == null ? -1 : _vm.SoundEntities.Count;
                var sampleKeys = evts == null ? new System.Collections.Generic.List<string>()
                    : evts.Keys.OrderBy(x => x).Take(10).ToList();
                var probeKey = hasLotEnter ? "lot_enter" : (evts == null ? null : evts.Keys.FirstOrDefault());
                Log("AUTOTEST audio hitvm=ok disableSound=" + FSO.HIT.HITVM.DISABLE_SOUND +
                    " events=" + evtCount + " lot_enter=" + hasLotEnter +
                    " soundEntities=" + sndEnts + " sample=[" + string.Join(",", sampleKeys) + "]");
                try
                {
                    AudioCheckThread = probeKey == null ? null : hit.PlaySoundEvent(probeKey);
                    Log("AUTOTEST audio PlaySoundEvent(" + (probeKey ?? "<none>") + ")=" + (AudioCheckThread == null
                        ? "null" : (AudioCheckThread.GetType().Name + ":" + AudioCheckThread.Name +
                        " dead=" + AudioCheckThread.Dead)));
                }
                catch (Exception pe) { Log("AUTOTEST audio PlaySoundEvent EXC " + pe.GetType().Name + " " + pe.Message); Fail("audio"); return; }
                if (evtCount < 0) { Log("AUTOTEST audio: no audio event corpus (Events null)"); Fail("audio"); return; }
                Pass("audio");
            }
            catch (Exception ae) { Log("AUTOTEST audio EXC " + ae.GetType().Name + " " + ae.Message); Fail("audio"); }
        }

        // AUD-01 audit probe (private-checkout tooling, evidence-only; classification is manual in
        // coordination/evidence/AUD-01/). D1: for probe events, read the .hot ground truth
        // (event -> track control group / volume / ducking priority via TS1Audio.Events+GetTrack),
        // fire PlaySoundEvent, tick the returned HITSound until its VolGroup is adopted (NoteOn
        // content sniff, or HITVM forcing for kTurnOnTV/kSetMusicMode) and log both sides.
        // D2: directly construct the HITTVOn(5) that bkground_load=kSetMusicMode,5 produces; the
        // id==5 branch resolves TSO stub Patch(0x4f85) with null Filename, GetSFX prints " was
        // null" on stdout, Instance stays unset, first Tick must report Dead.
        private static void CheckAudioD1D2()
        {
            try
            {
                var hit = FSO.HIT.HITVM.Get();
                var audio = FSO.Content.Content.Get().Audio;
                var evts = audio?.Events;
                if (hit == null || evts == null) { Log("AUTOTEST d1d2: hitvm=" + (hit != null) + " events=" + (evts != null)); Fail("audiod1d2"); return; }

                var wanted = new List<string>();
                foreach (var k in new[] { "stereo_country", "stereo_zydeco" }) if (evts.ContainsKey(k)) wanted.Add(k);
                wanted.AddRange(evts.Keys.Where(x => x.StartsWith("vox_")).OrderBy(x => x).Take(4));
                if (evts.Count > 0) wanted.Add(evts.Keys.OrderBy(x => x).First());

                int rows = 0, voxMismatch = 0;
                foreach (var name in wanted.Distinct())
                {
                    try
                    {
                        if (!evts.TryGetValue(name, out var reg) || reg == null) continue;
                        var track = audio.GetTrack(reg.TrackID, reg.TrackID, reg.ResGroup);
                        var snd = hit.PlaySoundEvent(name);
                        if (snd == null) { Log("AUTOTEST d1 event=" + name + " thread=null"); continue; }
                        int ticks = 0;
                        while (!snd.Dead && ticks < 100) { if (!snd.Tick()) break; ticks++; }
                        var thread = snd as FSO.HIT.HITThread;
                        Log("AUTOTEST d1 event=" + name + " type=" + reg.EventType + " track=" + reg.TrackID +
                            " hotControlGroup=" + (track == null ? "<missing>" : track.ControlGroup.ToString()) +
                            " hotVolume=" + (track == null ? -1 : (int)track.Volume) +
                            " threadKind=" + snd.GetType().Name + " threadVolGroup=" + snd.VolGroup +
                            " dead=" + snd.Dead + " ticks=" + ticks);
                        rows++;
                        // AUD-03 regression gate: runtime VolGroup must equal the
                        // declared track control group for every defined group.
                        FSO.HIT.Model.HITVolumeGroup? expect = null;
                        if (track != null)
                        {
                            switch (track.ControlGroup)
                            {
                                case FSO.Files.HIT.HITControlGroups.kGroupVox: expect = FSO.HIT.Model.HITVolumeGroup.VOX; break;
                                case FSO.Files.HIT.HITControlGroups.kGroupMusic: expect = FSO.HIT.Model.HITVolumeGroup.MUSIC; break;
                                case FSO.Files.HIT.HITControlGroups.kGroupSFX: expect = FSO.HIT.Model.HITVolumeGroup.FX; break;
                            }
                        }
                        bool rowOK = (expect == null) || (snd.VolGroup == expect.Value);
                        Log("AUTOTEST d1 rowOK=" + rowOK);
                        if (!rowOK) { voxMismatch++; Fail("audiod1d2"); }
                        // no Dispose: probe threads stay live like CheckAudio's AudioCheckThread;
                        // disposing here races HITVM.Tick's queued note instances (ObjectDisposedException).
                    }
                    catch (Exception pe) { Log("AUTOTEST d1 event=" + name + " EXC " + pe.GetType().Name + " " + pe.Message); }
                }
                Log("AUTOTEST d1 rows=" + rows + " voxGroupMismatches=" + voxMismatch);

                bool hasLoadLoop = evts.ContainsKey("bkground_load");
                var load = new FSO.HIT.Events.HITTVOn(5, hit, true);
                bool tickResult = load.Tick();
                Log("AUTOTEST d2 bkgroundLoadInCorpus=" + hasLoadLoop + " directHITTVOn(5) firstTick=" + tickResult + " dead=" + load.Dead);
                // AUD-03 regression gate: the TS1 load loop must resolve KLOD ->
                // Music/Modes/Load/ and stay alive (first tick true, not dead).
                if (!hasLoadLoop || load.Dead) { Log("AUTOTEST d2 FAIL: load-music thread dead"); Fail("audiod1d2"); }

                // UI-09 leg: exact artboard positions of the mode-0 neighborhood house buttons,
                // read from the real LotLocations STR the panel consumes.
                try
                {
                    var panel = new Simitone.Client.UI.Panels.UINeighborhoodSelectionPanel(1);
                    var pos = panel.HousePositions.OrderBy(k => k.Key)
                        .Select(kv => kv.Key + ":(" + (int)kv.Value.X + "," + (int)kv.Value.Y + ")");
                    Log("AUTOTEST d3 housePositions " + string.Join(" ", pos));
                }
                catch (Exception ue) { Log("AUTOTEST d3 housePositions EXC " + ue.GetType().Name + " " + ue.Message); }

                Pass("audiod1d2");
            }
            catch (Exception ae) { Log("AUTOTEST d1d2 EXC " + ae.GetType().Name + " " + ae.Message); Fail("audiod1d2"); }
        }


        // SIM-09 audit probe (opt-in "budgettxn"): the household budget ledger —
        // category attribution from committed transactions, day rollover into the
        // 3-day history, DaysRunning, and a serialize/deserialize + SIMI
        // BudgetDays mirror round-trip. Self-contained (no IFF or UI dependency).
        private static void CheckBudgetTxn()
        {
                var state = new FSO.SimAntics.Model.TS1Platform.VMTS1LotState(FSO.SimAntics.Marshals.VMMarshal.LATEST_VERSION);
                try
                {
                    state.RecordTransaction(500, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.IncomeJob);
                    state.RecordTransaction(-40, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.ExpenseNPC);
                    state.RecordTransaction(-10, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.ExpenseFridgeRefill);
                    state.RecordTransaction(-1200, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.ExpenseFromObjects);
                    state.RecordTransaction(250, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.IncomeMisc);
                    state.RecordTransaction(-15, FSO.SimAntics.Primitives.VMTransferFundsExpenseType.NONE);
                    var T = state.TodayReport;
                    Log("AUTOTEST budgettxn today=[MInc=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.MiscIncome]
                        + " JInc=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.JobIncome]
                        + " Svc=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.ServiceExpense]
                        + " Food=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.FoodExpense]
                        + " Bills=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.BillsExpense]
                        + " MExp=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.MiscExpense]
                        + " HH=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.HouseholdExpense]
                        + " Arch=" + T[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.ArchitectureExpense] + "]");

                state.RollDay();
                int todayAllZero = state.TodayReport.All(x => x == 0) ? 1 : 0;
                int histJob = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.JobIncome];
                int histSvc = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.ServiceExpense];
                int histFood = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.FoodExpense];
                int histHH = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.HouseholdExpense];
                int histMInc = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.MiscIncome];
                int histMExp = state.HistoryReport[(int)FSO.SimAntics.Model.TS1Platform.VMTS1LotState.BudgetCat.MiscExpense];
                Log("AUTOTEST budgettxn rolled todayAllZero=" + todayAllZero + " daysRunning=" + state.DaysRunning
                    + " hist=[MInc=" + histMInc + " JInc=" + histJob + " Svc=" + histSvc + " Food=" + histFood
                    + " MExp=" + histMExp + " HH=" + histHH + "]");

                // persistence round-trip incl. the SIMI BudgetDays mirror
                state.SimulationInfo = new FSO.Files.Formats.IFF.Chunks.SIMI() { ChunkID = 1, ChunkType = "SIMI" };
                using (var ms = new MemoryStream())
                {
                    state.SerializeInto(new BinaryWriter(ms));
                    ms.Position = 0;
                    var loaded = new FSO.SimAntics.Model.TS1Platform.VMTS1LotState(FSO.SimAntics.Marshals.VMMarshal.LATEST_VERSION);
                    loaded.Deserialize(new BinaryReader(ms));
                    // SIMI slot 0 = the (post-rollover, empty) today; slot 1 = the
                    // day that just completed, which carries the JobIncome 500.
                    var simiDay = loaded.SimulationInfo?.BudgetDays?[1];
                    var simiJob = simiDay != null && simiDay.Valid != 0 ? simiDay.JobIncome : -1;
                    var ok = loaded.TodayReport.SequenceEqual(state.TodayReport)
                        && loaded.HistoryReport.SequenceEqual(state.HistoryReport)
                        && loaded.DaysRunning == state.DaysRunning
                        && simiJob == histJob;
                    Log("AUTOTEST budgettxn roundtrip todayOk=" + loaded.TodayReport.SequenceEqual(state.TodayReport)
                        + " histOk=" + loaded.HistoryReport.SequenceEqual(state.HistoryReport)
                        + " daysOk=" + (loaded.DaysRunning == state.DaysRunning)
                        + " simiMirrorJob=" + simiJob);
                    if (ok) Pass("budgettxn"); else Fail("budgettxn");
                }
            }
            catch (Exception be)
            {
                Log("AUTOTEST budgettxn EXC " + be.GetType().Name + " " + be.Message + " AT " + (be.StackTrace ?? "").Replace("\n", " | "));
                Fail("budgettxn");
            }
        }

        // TRV-02 audit probe (opt-in "travelstate"): the travel state contract —
        // time-token read+consume (native generic call 23), vacation-lot booking
        // counting (native call 27), and transit persistence across a lot-state
        // serialize/deserialize round-trip (save away → quit → reload recovery).
        private static void CheckTravelState()
        {
            try
            {
                var inv = new List<FSO.Files.Formats.IFF.Chunks.InventoryItem>
                {
                    new FSO.Files.Formats.IFF.Chunks.InventoryItem { Type = 2, GUID = 7, Count = 9 },
                    new FSO.Files.Formats.IFF.Chunks.InventoryItem { Type = 2, GUID = 8, Count = 30 },
                    new FSO.Files.Formats.IFF.Chunks.InventoryItem { Type = 2, GUID = 9, Count = 77 },
                    new FSO.Files.Formats.IFF.Chunks.InventoryItem { Type = 1, GUID = 7, Count = 5 },
                };
                var hours = FSO.SimAntics.Primitives.VMGenericTS1Call.TakeIData(inv, 7);
                var minutes = FSO.SimAntics.Primitives.VMGenericTS1Call.TakeIData(inv, 8);
                var decoyAlive = inv.Any(x => x.Type == 2 && x.GUID == 9 && x.Count == 77);
                var wrongTypeAlive = inv.Any(x => x.Type == 1 && x.GUID == 7);
                var tokensGone = !inv.Any(x => x.Type == 2 && (x.GUID == 7 || x.GUID == 8));
                Log("AUTOTEST travelstate mode23 hours=" + hours + " minutes=" + minutes
                    + " tokensGone=" + tokensGone + " decoyAlive=" + decoyAlive + " wrongTypeAlive=" + wrongTypeAlive);

                var fams = new List<FAMI>
                {
                    new FAMI { HouseNumber = 41 }, new FAMI { HouseNumber = 42 },
                    new FAMI { HouseNumber = 7 }, new FAMI { HouseNumber = 60 },
                };
                var occupied = FSO.SimAntics.Primitives.VMGenericTS1Call.CountOccupiedVacationLots(fams);
                var none = FSO.SimAntics.Primitives.VMGenericTS1Call.CountOccupiedVacationLots(new List<FAMI>());
                Log("AUTOTEST travelstate mode27 occupied=" + occupied + " noneNeighborhood=" + none);

                var state = new FSO.SimAntics.Model.TS1Platform.VMTS1LotState(FSO.SimAntics.Marshals.VMMarshal.LATEST_VERSION);
                state.LotTransitInfo = 2;
                state.DowntownSimGUID = 0xDEADBEEF;
                using (var ms = new MemoryStream())
                {
                    state.SerializeInto(new BinaryWriter(ms));
                    ms.Position = 0;
                    var loaded = new FSO.SimAntics.Model.TS1Platform.VMTS1LotState(FSO.SimAntics.Marshals.VMMarshal.LATEST_VERSION);
                    loaded.Deserialize(new BinaryReader(ms));
                    var transitOk = loaded.LotTransitInfo == 2 && loaded.DowntownSimGUID == 0xDEADBEEF;
                    Log("AUTOTEST travelstate roundtrip transitOk=" + transitOk
                        + " lotTransit=" + loaded.LotTransitInfo + " simGuid=0x" + loaded.DowntownSimGUID.ToString("X"));
                }

                var ok = hours == 9 && minutes == 30 && tokensGone && decoyAlive && wrongTypeAlive
                    && occupied == 2 && none == 0;
                if (ok) Pass("travelstate"); else Fail("travelstate");
            }
            catch (Exception te)
            {
                Log("AUTOTEST travelstate EXC " + te.GetType().Name + " " + te.Message);
                Fail("travelstate");
            }
        }

        // SAV-03 audit probe (opt-in "sav03appearance"): (1) generator record
        // encodings across skin/age/gender (pd60 lgt=1/med=3/drk=2, age 9/27,
        // gender 0/1); (2) on-lot avatars: disk-legal pd60 and render SkinTone
        // consistent with the native activation mapper; (3) avatar marshal
        // round-trip preserves pd60 + SkinTone; (4) the disclosed
        // VMNetAvatarPersistState.Apply clobber (raw AppearanceType into pd60)
        // characterized and reverted in-memory.
        private static void CheckSav03Appearance()
        {
            var info = new System.Text.StringBuilder();
            var ok = true;
            try
            {
                // (1) generator record encodings
                var codes = new[]
                {
                    new[] { "mmaaf", "lgt", "1", "27", "0" },
                    new[] { "fmaaf", "med", "3", "27", "1" },
                    new[] { "mmaaf", "drk", "2", "27", "0" },
                    new[] { "mcchd", "lgt", "1", "9",  "0" },
                };
                foreach (var c in codes)
                {
                    var pd = new SimTemplateCreateInfo(c[0], c[1]).MakePersonData();
                    var rowOk = pd[60] == short.Parse(c[2]) && pd[58] == short.Parse(c[3]) && pd[65] == short.Parse(c[4]);
                    info.Append(c[0] + "/" + c[1] + ":pd60=" + pd[60] + ",age=" + pd[58] + ",gen=" + pd[65] + ";");
                    if (!rowOk) ok = false;
                }

                // (2) on-lot avatars: pd60 disk-legal + render tone matches the
                // native activation mapper
                var avatars = _vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>().ToList();
                if (avatars == null || avatars.Count == 0) { Log("AUTOTEST sav03appearance: no avatars on lot"); Fail("sav03appearance"); return; }
                foreach (var av in avatars)
                {
                    var pd60 = av.GetPersonData(VMPersonDataVariable.SkinColor);
                    var legal = pd60 >= 1 && pd60 <= 3;
                    var mapped = VMTS1ActivatorNew.DiskSkinToAppearance(pd60, 0x4);
                    var toneOk = !legal || (int)av.SkinTone == (int)mapped;
                    info.Append("av" + av.ObjectID + ":pd60=" + pd60 + ",tone=" + (int)av.SkinTone + ",toneOk=" + toneOk + ";");
                    if (!legal || !toneOk) ok = false;
                }

                // (3) avatar marshal round-trip preserves pd60 + SkinTone
                foreach (var av in avatars.Take(3))
                {
                    var pd60Before = av.GetPersonData(VMPersonDataVariable.SkinColor);
                    var toneBefore = (int)av.SkinTone;
                    var m = av.Save();
                    var ms = new MemoryStream();
                    using (var w = new BinaryWriter(ms, System.Text.Encoding.UTF8, true)) m.SerializeInto(w);
                    ms.Position = 0;
                    var back = new FSO.SimAntics.Marshals.VMAvatarMarshal(FSO.SimAntics.Marshals.VMMarshal.LATEST_VERSION, true);
                    using (var r = new BinaryReader(ms, System.Text.Encoding.UTF8, true)) back.Deserialize(r);
                    var rtOk = back.PersonData != null && back.PersonData.Length > 60
                        && back.PersonData[60] == pd60Before && (int)back.SkinTone == toneBefore;
                    info.Append("rt" + av.ObjectID + "=" + rtOk + ";");
                    if (!rtOk) ok = false;
                }

                // (4) clobber characterization: VMNetAvatarPersistState.Apply
                // (CustomGUID == 0 path) writes the RAW AppearanceType byte into
                // pd60 — the 0/1/2 sandbox encoding, not the disk 1/2/3 law.
                var victim = avatars[0];
                var pd60BeforeClobber = victim.GetPersonData(VMPersonDataVariable.SkinColor);
                var beforeClobber = pd60BeforeClobber;
                string clobber;
                try
                {
                    var ps = new FSO.SimAntics.NetPlay.Model.VMNetAvatarPersistState();
                    ps.Save(victim);
                    ps.Apply(victim);
                    var after = victim.GetPersonData(VMPersonDataVariable.SkinColor);
                    clobber = "applied pd60 " + beforeClobber + "->" + after + (after != beforeClobber ? " CLOBBERED" : " unchanged");
                    victim.SetPersonData(VMPersonDataVariable.SkinColor, beforeClobber); // restore disk law
                    if (victim.GetPersonData(VMPersonDataVariable.SkinColor) != beforeClobber) clobber += " RESTORE-FAILED";
                }
                catch (Exception ce)
                {
                    clobber = "persist-state path threw " + ce.GetType().Name
                        + " on a TS1 avatar (TSO state absent) — clobber not reachable in the Simitone TS1 flow";
                }
                info.Append(clobber);
                Log("AUTOTEST sav03appearance " + (ok ? "ok " : "ISSUES ") + info);
                if (ok) Pass("sav03appearance"); else Fail("sav03appearance");
            }
            catch (Exception se)
            {
                Log("AUTOTEST sav03appearance EXC " + se.GetType().Name + " " + se.Message + " " + info);
                Fail("sav03appearance");
            }
        }

        // NBR-04 audit probe (opt-in "nbrcommerce"): on community/downtown lots
        // the visiting family pays even though CurrentFamily is not activated —
        // GetBudgetForFamily/TransactBudgetForFamily fall back to the travel
        // context's active family instead of "maxis has infinite money".
        private static void CheckNbrCommerce()
        {
            try
            {
                var vm = _vm;
                var av = vm?.Context?.ObjectQueries?.Avatars?.OfType<VMAvatar>().FirstOrDefault();
                var fam = vm?.TS1State?.CurrentFamily;
                if (vm == null || av == null || fam == null) { Log("AUTOTEST nbrcommerce: missing vm/avatar/family"); Fail("nbrcommerce"); return; }
                var gl = vm.GlobalLink as FSO.SimAntics.Engine.TSOTransaction.VMTS1GlobalLinkStub;
                if (gl == null) { Log("AUTOTEST nbrcommerce: GlobalLink is not the TS1 stub"); Fail("nbrcommerce"); return; }
                var gameState = FSO.Content.Content.Get().Neighborhood.GameState;
                var priorActive = gameState.ActiveFamily;
                var budgetBefore = fam.Budget;

                // visitor scenario: family not activated on this lot
                vm.TS1State.CurrentFamily = null;
                gameState.ActiveFamily = fam;

                var readOk = gl.GetBudgetForFamily(vm, av) == (uint)budgetBefore;
                var transactOk = gl.TransactBudgetForFamily(vm, av, -100) && fam.Budget == budgetBefore - 100;
                var denyOk = !gl.CanTransactBudgetForFamily(vm, av, int.MaxValue);
                var readAfter = gl.GetBudgetForFamily(vm, av) == (uint)(budgetBefore - 100);

                // restore: budget, activated family, travel context
                fam.Budget = budgetBefore;
                vm.TS1State.CurrentFamily = fam;
                gameState.ActiveFamily = priorActive;
                var restored = fam.Budget == budgetBefore && vm.TS1State.CurrentFamily == fam;

                Log("AUTOTEST nbrcommerce visitorRead=" + readOk + " visitorTransact=" + transactOk
                    + " denyOverBudget=" + denyOk + " readAfter=" + readAfter + " restored=" + restored);
                if (readOk && transactOk && denyOk && readAfter && restored) Pass("nbrcommerce"); else Fail("nbrcommerce");
            }
            catch (Exception ne)
            {
                Log("AUTOTEST nbrcommerce EXC " + ne.GetType().Name + " " + ne.Message);
                Fail("nbrcommerce");
            }
        }

        // NPC-INFO runtime check (PARITY Round 23-24): the ORIGINAL IFF new-sim init chain
        // (PersonGlobals 'init NPC' 8298 -> 'Init person' 8192, engine-driven in the original,
        // 0 IFF callers corpus-wide) writes my PersonData canon: personality 2..7=1000 (R22),
        // Priority 33=25, AutonomyLevel 36=50, JobType 56=-1 (IFF Equals(56,0) true-branch),
        // JobPromotionLevel 57=Tuning[17412] (=4 at runtime), JobPerformance 63=0 (R23),
        // opcode-8 skill spread 9..12,15,17,18=NextRandom(1000) [0,1000) each (R24), and
        // pd[29]=1 Cheats, pd[32]=Tuning[16898] PersonType->2 (R24).
        // Engine-created new sims (make_new_character via VMTS1MakeNewCharacter + generated
        // families) build their Neighbour.PersonData from SimitoneNeighbourGenerator.MakePersonData;
        // the runtime VMAvatar then inherits that PersonData wholesale (VMAvatar.InheritNeighbor:
        // PersonData = neigh.PersonData.ToArray()). This check runs the ACTUAL engine new-sim data
        // builder and asserts it now carries the IFF write-set 1:1.
        private static void CheckNpcinfo()
        {
            try
            {
                var info = new SimTemplateCreateInfo("mmaaf", "lgt"); // adult-male-normal; constructor reads code.Substring(2,3) so code needs 5 chars
                var pd = info.MakePersonData(); // the exact engine builder under parity scrutiny
                int pr = (pd.Length > 33) ? pd[33] : int.MinValue;
                int au = (pd.Length > 36) ? pd[36] : int.MinValue;
                int jt = (pd.Length > 56) ? pd[56] : int.MinValue;
                int jl = (pd.Length > 57) ? pd[57] : int.MinValue;
                int jp = (pd.Length > 63) ? pd[63] : int.MinValue;
                int ch = (pd.Length > 29) ? pd[29] : int.MinValue;
                int pt = (pd.Length > 32) ? pd[32] : int.MinValue;
                int[] sk = new int[] { 9, 10, 11, 12, 15, 17, 18 }.Select(i => (pd.Length > i) ? pd[i] : int.MinValue).ToArray();
                bool skRange = sk.All(s => s >= 0 && s < 1000);
                Log("AUTOTEST npcinfo pd[2..7]=" + string.Join(",", pd.Skip(2).Take(6)) +
                    " pd[33](Priority)=" + pr + " pd[36](Autonomy)=" + au + " pd[56](JobType)=" + jt +
                    " pd[57](JobLevel)=" + jl + " pd[63](JobPerf)=" + jp +
                    " pd[29](Cheats)=" + ch + " pd[32](PersonType)=" + pt +
                    " skills[9..12,15,17,18]={" + string.Join(",", sk) + "}" +
                    " (IFF 8298/8192 canon 25/50/-1,4,0 + 1,2 + skills [0,1000); " +
                    "InheritNeighbor ships record PersonData to runtime avatar)");
                if (pr == 25 && au == 50 && jt == -1 && jl == 4 && jp == 0 && ch == 1 && pt == 2 && skRange)
                { Pass("npcinfo"); return; }
                Log("AUTOTEST npcinfo: engine MakePersonData must carry IFF init-NPC canon " +
                    "Priority 25 / Autonomy 50 / JobType -1 / JobLevel 4 / JobPerf 0 / Cheats 1 / " +
                    "PersonType 2 / skills [0,1000)");
                Fail("npcinfo");
            }
            catch (Exception ne) { Log("AUTOTEST npcinfo EXC " + ne.GetType().Name + " " + ne.Message); Fail("npcinfo"); }
        }

        // PERSONDATA WIDTH (R163): shipped TS1 OBJM residents carry 80 words and NBRS carries
        // an 88-word prefix, while original expansion BHAVs demonstrably address words 80..84.
        // The live VM's canonical address space is 0..100; absent persisted words zero-extend.
        // Pin the original consumers, live BHAV execution, and every avatar's normalized boundary.
        private static void CheckPersonDataWidth()
        {
            try
            {
                bool ReadsWord(BHAV bhav, int instruction, int word, byte owner)
                {
                    if (bhav?.Instructions == null || instruction < 0 || instruction >= bhav.Instructions.Length)
                        return false;
                    var ins = bhav.Instructions[instruction];
                    var op = ins.Operand;
                    if (ins.Opcode != 2 || op == null || op.Length < 8) return false;
                    var lhs = op[0] | (op[1] << 8);
                    var rhs = op[2] | (op[3] << 8);
                    return (op[6] == owner && lhs == word) || (op[7] == owner && rhs == word);
                }

                var globals = _vm?.Context?.Globals?.Resource?.Iff;
                var peer = globals?.Get<BHAV>(488);
                bool peerAnchor = peer != null
                    && (peer.ChunkLabel ?? "").Trim() == "Is Stack Object My Peer( Fame )?"
                    && peer.Instructions != null && peer.Instructions.Length == 77
                    && ReadsWord(peer, 0, 80, 18) && ReadsWord(peer, 1, 80, 19)
                    && ReadsWord(peer, 20, 81, 18) && ReadsWord(peer, 21, 81, 19);

                IffFile personGlobals = Content.Get().TS1Global.Get("PersonGlobals.iff") as IffFile;
                if (personGlobals == null && _avatars != null && _avatars.Count > 0)
                    personGlobals = _avatars[0].Object?.Resource?.SemiGlobal?.Iff;
                var ghostSocial = personGlobals?.Get<BHAV>(8645);
                bool ghostAnchor = ghostSocial != null
                    && (ghostSocial.ChunkLabel ?? "").Trim() == "MAGIC - Ghost Social Test"
                    && ghostSocial.Instructions != null && ghostSocial.Instructions.Length == 3
                    && ReadsWord(ghostSocial, 0, 84, 18);

                bool live = _avatars != null && _avatars.Count > 0;
                var lengths = new List<string>();
                if (live)
                {
                    foreach (var avatar in _avatars)
                    {
                        var data = avatar.GetPersonDataClone();
                        lengths.Add(avatar.ObjectID + ":" + data.Length);
                        if (data.Length < 101) { live = false; continue; }
                        // Exercise the same public boundary VMMemory uses for the anchored BHAV
                        // reads. Writing each value back unchanged catches both undersized reads
                        // and writes without changing gameplay state.
                        foreach (var word in new int[] { 80, 81, 84, 100 })
                        {
                            var value = avatar.GetPersonData((VMPersonDataVariable)word);
                            if (!avatar.SetPersonData((VMPersonDataVariable)word, value)) live = false;
                        }
                        // ClownPortal 4107 saves/restores raw outfit state through word 21;
                        // the TSO IsHousemate projection must not replace that TS1 value.
                        var outfitBefore = data[21];
                        var outfitProbe = (short)(outfitBefore == -1 ? 0 : -1);
                        if (!avatar.SetPersonData((VMPersonDataVariable)21, outfitProbe)
                            || avatar.GetPersonData((VMPersonDataVariable)21) != outfitProbe)
                            live = false;
                        avatar.SetPersonData((VMPersonDataVariable)21, outfitBefore);
                        // Word 70 is Zodiac in TS1 but SkillLock in TSO. Exercise a real
                        // value change so a TSO-only synthesized getter/no-op setter cannot
                        // silently mask the original TS1 word. Restore it immediately.
                        var zodiacBefore = data[70];
                        var zodiacProbe = (short)(zodiacBefore == 1234 ? 1235 : 1234);
                        if (!avatar.SetPersonData(VMPersonDataVariable.TS1Zodiac, zodiacProbe)
                            || avatar.GetPersonData(VMPersonDataVariable.TS1Zodiac) != zodiacProbe
                            || avatar.GetPersonDataClone()[70] != zodiacProbe)
                            live = false;
                        avatar.SetPersonData(VMPersonDataVariable.TS1Zodiac, zodiacBefore);
                        // RenderDisplayFlags is both a renderer side effect and an original
                        // BHAV-visible bitfield. Toggle one bit and prove the backing word is
                        // stored, then restore the exact prior flags immediately.
                        var displayBefore = data[74];
                        var displayProbe = (short)(displayBefore ^ 1);
                        if (!avatar.SetPersonData(VMPersonDataVariable.RenderDisplayFlags, displayProbe)
                            || avatar.GetPersonData(VMPersonDataVariable.RenderDisplayFlags) != displayProbe)
                            live = false;
                        avatar.SetPersonData(VMPersonDataVariable.RenderDisplayFlags, displayBefore);
                        // No original TS1 writer targets the TSO online-job status word.
                        // Once a short record is extended, the TSO tick initializer must not
                        // mutate that new tail behind the original game's back.
                        if (data[98] != 0) live = false;
                    }
                }

                // Execute both anchored originals as check trees. Unlike RunInMyStack,
                // EvaluateCheck turns a SimAntics exception into GOTO_FALSE instead of
                // swallowing it, so an undersized PersonData access cannot false-pass.
                bool bhavLive = false;
                string bhavNote = "unavailable";
                var probeAvatar = (_avatars == null) ? null : _avatars.OrderBy(x => x.ObjectID).FirstOrDefault();
                if (probeAvatar?.Thread != null)
                {
                    var pd80Before = probeAvatar.GetPersonData((VMPersonDataVariable)80);
                    var pd81Before = probeAvatar.GetPersonData((VMPersonDataVariable)81);
                    var pd84Before = probeAvatar.GetPersonData((VMPersonDataVariable)84);
                    var ghostBefore = probeAvatar.GetPersonData(VMPersonDataVariable.IsGhost);
                    var ageBefore = probeAvatar.GetPersonData(VMPersonDataVariable.PersonsAge);
                    var tempsBefore = (short[])probeAvatar.Thread.TempRegisters.Clone();
                    try
                    {
                        var peerRoutine = _vm.Context.Globals.Resource.GetRoutine(488) as VMRoutine;
                        var ghostRoutine = probeAvatar.Object?.Resource?.SemiGlobal?.GetRoutine(8645) as VMRoutine;
                        if (peerRoutine != null && ghostRoutine != null)
                        {
                            probeAvatar.SetPersonData((VMPersonDataVariable)80, 0);
                            probeAvatar.SetPersonData((VMPersonDataVariable)81, 0);
                            var peerResult = FSO.SimAntics.Engine.VMThread.EvaluateCheck(
                                _vm.Context, probeAvatar, new FSO.SimAntics.Engine.VMStackFrame
                                {
                                    Caller = probeAvatar,
                                    Callee = probeAvatar,
                                    StackObject = probeAvatar,
                                    CodeOwner = probeAvatar.Object,
                                    Routine = peerRoutine,
                                    Args = new short[4]
                                });

                            probeAvatar.SetPersonData((VMPersonDataVariable)84, 1); // TS1LivingGhost
                            probeAvatar.SetPersonData(VMPersonDataVariable.IsGhost, 1);
                            probeAvatar.SetPersonData(VMPersonDataVariable.PersonsAge, 19);
                            var ghostResult = FSO.SimAntics.Engine.VMThread.EvaluateCheck(
                                _vm.Context, probeAvatar, new FSO.SimAntics.Engine.VMStackFrame
                                {
                                    Caller = probeAvatar,
                                    Callee = probeAvatar,
                                    StackObject = probeAvatar,
                                    CodeOwner = probeAvatar.Object,
                                    Routine = ghostRoutine,
                                    Args = new short[4]
                                });
                            bhavLive = peerResult == FSO.SimAntics.Engine.VMPrimitiveExitCode.RETURN_TRUE
                                && ghostResult == FSO.SimAntics.Engine.VMPrimitiveExitCode.RETURN_TRUE;
                            bhavNote = "488=" + peerResult + ",8645=" + ghostResult;
                        }
                    }
                    finally
                    {
                        // The two anchored checks are read-only. Restore only the five probe
                        // inputs we changed: replaying every PersonData setter would trigger
                        // unrelated outfit/render/queue side effects and reject future tail words.
                        probeAvatar.SetPersonData((VMPersonDataVariable)80, pd80Before);
                        probeAvatar.SetPersonData((VMPersonDataVariable)81, pd81Before);
                        probeAvatar.SetPersonData((VMPersonDataVariable)84, pd84Before);
                        probeAvatar.SetPersonData(VMPersonDataVariable.IsGhost, ghostBefore);
                        probeAvatar.SetPersonData(VMPersonDataVariable.PersonsAge, ageBefore);
                        Array.Copy(tempsBefore, probeAvatar.Thread.TempRegisters,
                            Math.Min(tempsBefore.Length, probeAvatar.Thread.TempRegisters.Length));
                    }
                }

                // Cover the second live replacement sink too: create one temporary OOW
                // person from a mounted NBRS record, which exercises VMContext ->
                // VMAvatar.InheritNeighbor (the persisted NBRS array is only 88 words).
                bool inheritLive = false;
                string inheritNote = "unavailable";
                VMMultitileGroup inheritGroup = null;
                try
                {
                    var inheritNeighbor = Content.Get().Neighborhood?.Neighbors?.Entries
                        .FirstOrDefault(x => x != null && x.Unknown1 > 0 && x.GUID != 0
                            && x.PersonData != null && x.PersonData.Length < 101
                            && Content.Get().WorldObjects.Get(x.GUID)?.OBJ?.ObjectType == OBJDType.Person);
                    if (inheritNeighbor != null)
                    {
                        inheritGroup = _vm.Context.CreateObjectInstance(inheritNeighbor.GUID,
                            FSO.LotView.Model.LotTilePos.OUT_OF_WORLD,
                            FSO.LotView.Model.Direction.NORTH, false);
                        var inherited = inheritGroup?.Objects?.OfType<VMAvatar>().FirstOrDefault();
                        if (inherited != null)
                        {
                            var inheritedData = inherited.GetPersonDataClone();
                            var word100 = inherited.GetPersonData((VMPersonDataVariable)100);
                            inheritLive = inheritedData.Length >= 101;
                            inheritNote = "nid=" + inheritNeighbor.NeighbourID + ",len=" + inheritedData.Length
                                + ",pd100=" + word100;
                        }
                    }
                }
                finally
                {
                    inheritGroup?.Delete(_vm.Context);
                }

                Log("AUTOTEST persondata widths=[" + string.Join(",", lengths) + "]" +
                    " global488-pd80/81=" + peerAnchor + " person8645-pd84=" + ghostAnchor +
                    " live-rw[21,70,74,80,81,84,100]+pd98zero=" + live + " live-bhavs=" + bhavLive + "(" + bhavNote + ")" +
                    " inherit-neighbor=" + inheritLive + "(" + inheritNote + ")" +
                    " (short original OBJM/NBRS prefixes must zero-extend to PersonData[0..100])");
                if (peerAnchor && ghostAnchor && live && bhavLive && inheritLive) Pass("persondata"); else Fail("persondata");
            }
            catch (Exception pe)
            {
                Log("AUTOTEST persondata EXC " + pe.GetType().Name + " " + pe.Message +
                    " AT " + (pe.StackTrace ?? "").Replace("\n", " | "));
                Fail("persondata");
            }
        }

        // TRAVEL INVENTORY (R163): ORIGINAL PhoneGlobals mode-5 operands store Temp0's
        // neighbor as the auto-follow pointer. Mode 6 is the paired follow-home operation.
        // Their consumers read type=2/GUID=10 or 11 and treat Count as the neighbor ID, so a
        // second write must replace the prior Count instead of appending a stale duplicate.
        private static void CheckTravelInventory()
        {
            var avatar = (_avatars == null || _avatars.Count == 0) ? null : _avatars[0];
            var neighborhood = Content.Get().Neighborhood;
            short ownerNid = 0;
            List<InventoryItem> prior = null;
            short priorTemp0 = 0;
            bool swapped = false;
            bool tempSaved = false;
            bool priorHadKey = false;
            try
            {
                if (avatar?.Thread != null)
                {
                    priorTemp0 = avatar.Thread.TempRegisters[0];
                    tempSaved = true;
                }
                var phone = Content.Get().TS1Global.Get("PhoneGlobals.iff") as IffFile;
                var newCall = phone?.Get<BHAV>(8325);
                var call = phone?.Get<BHAV>(8313);
                bool Mode5At(BHAV bhav, int index)
                {
                    if (bhav?.Instructions == null || index < 0 || index >= bhav.Instructions.Length)
                        return false;
                    var ins = bhav.Instructions[index];
                    var op = ins.Operand;
                    return ins.Opcode == 51 && op != null && op.Length >= 8
                        && op[0] == 5 && op[1] == 0 && op[2] == 0 && op[3] == 9
                        && op[4] == 0x47 && op[5] == 0x77 && op[6] == 0x64 && op[7] == 0xab;
                }
                bool iffAnchor = newCall != null && newCall.Instructions?.Length == 65
                    && Mode5At(newCall, 14) && Mode5At(newCall, 38) && Mode5At(newCall, 53)
                    && call != null && call.Instructions?.Length == 63
                    && Mode5At(call, 12) && Mode5At(call, 37) && Mode5At(call, 53);

                if (avatar == null || avatar.Thread == null || neighborhood == null)
                    throw new InvalidOperationException("live avatar/thread/neighborhood unavailable");
                var neighborIds = neighborhood.Neighbors?.Entries
                    .Where(x => x != null && x.Unknown1 > 0)
                    .Select(x => x.NeighbourID).Distinct().Take(2).ToArray() ?? new short[0];
                if (neighborIds.Length < 2) throw new InvalidOperationException("fewer than two mounted neighbors");

                ownerNid = avatar.GetPersonData(VMPersonDataVariable.NeighborId);
                priorHadKey = neighborhood.Neighborhood.InventoryByID.ContainsKey(ownerNid);
                prior = neighborhood.GetInventoryByNID(ownerNid);
                var scratch = new List<InventoryItem>();
                neighborhood.SetInventoryForNID(ownerNid, scratch);
                swapped = true;

                var frame = new FSO.SimAntics.Engine.VMStackFrame
                {
                    Thread = avatar.Thread,
                    Caller = avatar,
                    Callee = avatar,
                    StackObject = avatar
                };
                var handler = new FSO.SimAntics.Primitives.VMTS1InventoryOperations();
                var auto = new FSO.SimAntics.Primitives.VMTS1InventoryOperationsOperand
                {
                    Mode = FSO.SimAntics.Primitives.VMTS1InventoryMode.Temp0NeighborAsAutofollow,
                    Flags = 0,
                    Flags2 = 9
                };
                var home = new FSO.SimAntics.Primitives.VMTS1InventoryOperationsOperand
                {
                    Mode = FSO.SimAntics.Primitives.VMTS1InventoryMode.Temp0NeighborAsFollowHome,
                    Flags = 0,
                    Flags2 = 9
                };

                avatar.Thread.TempRegisters[0] = neighborIds[0];
                handler.Execute(frame, auto);
                avatar.Thread.TempRegisters[0] = neighborIds[1];
                handler.Execute(frame, auto);
                avatar.Thread.TempRegisters[0] = neighborIds[0];
                handler.Execute(frame, home);
                avatar.Thread.TempRegisters[0] = neighborIds[1];
                handler.Execute(frame, home);

                var autos = scratch.Where(x => x.Type == 2 && x.GUID == 10).ToList();
                var homes = scratch.Where(x => x.Type == 2 && x.GUID == 11).ToList();
                bool replacement = scratch.Count == 2 && autos.Count == 1 && homes.Count == 1
                    && autos[0].Count == (ushort)neighborIds[1]
                    && homes[0].Count == (ushort)neighborIds[1];
                Log("AUTOTEST travelinv PhoneGlobals-mode5-sites=" + iffAnchor +
                    " sequence=" + neighborIds[0] + "->" + neighborIds[1] +
                    " scratch=[" + string.Join(",", scratch.Select(x => x.Type + ":" + x.GUID + ":" + x.Count)) + "]" +
                    " replace-guid10/11=" + replacement +
                    " (Count is latest Temp0 neighbor; consumers spawn GUID 10/11 then remove)");
                if (iffAnchor && replacement) Pass("travelinv"); else Fail("travelinv");
            }
            catch (Exception te)
            {
                Log("AUTOTEST travelinv EXC " + te.GetType().Name + " " + te.Message);
                Fail("travelinv");
            }
            finally
            {
                if (swapped)
                {
                    if (priorHadKey) neighborhood.SetInventoryForNID(ownerNid, prior);
                    else neighborhood.Neighborhood.InventoryByID.Remove(ownerNid);
                }
                if (tempSaved) avatar.Thread.TempRegisters[0] = priorTemp0;
            }
        }

        // EXP-06 V1 ('ss-mount', opt-in): Superstar pack mount census against EXA-06's
        // accepted census (coordination/evidence/EXA-06/ss-census.json + status.md).
        // Superstar's acceptance minimum is the fame/Studio Town behavioral loop; this
        // leg pins the static surface the loop rides before any live drive:
        //   1. the 11 SimType controllers of the Studio Town controller bank mount
        //      through the generic FAR object provider (TS1ObjectProvider.Entries),
        //      GUID-exact: 6 ControllerStudioLot OBJDs (Studio Traffic / Build+Buy /
        //      Celebrity Spawn / Studio NPC / Home Fame Decay / Insanity) + NPCControllerSS
        //      + PhonePluginStudioLots + StereoSpeakersSuperstar + the Obsessed-Fan
        //      generator + ControllerSpa;
        //   2. the full 56-person Studio Town cast mounts Person-typed
        //      (TS1ObjectProvider.PersonGUIDs) — clerks, dancers, masseurs, the fame
        //      production cast (fashion/movie/TV directors, photographers, producers,
        //      scene partners), vendors, celebrities, obsessed fan, paparazzi, butler;
        //   3. sep6snds.hot merged into TS1Audio with the fame/station registrations
        //      exact: station_superstar (kSetMusicMode, track 13), the superstar
        //      transition (kSetMusicMode, 14 = KSST), the fame award/promotion/demotion
        //      stings (kSoundobPlay 103744/103741/103742), the SS TV station (kTurnOnTV
        //      103000) — plus the MusicModes routing entries 13/14.
        //   4. the Studio Town template lots exist on the TS1 data root
        //      (TemplateStudiotown/House81..89.iff + LotLocations.iff — the travel
        //      destination range; houseID 80-89 reads STDesc per GetHouseNameDesc).
        private static void RunSSMount()
        {
            bool ok = true;
            try
            {
                var ts1p = Content.Get().WorldObjects as FSO.Content.TS1.TS1ObjectProvider;
                if (ts1p == null)
                {
                    Log("AUTOTEST ss-mount WorldObjects is " + Content.Get().WorldObjects.GetType().Name);
                    ok = false;
                }
                else
                {
                    Log("AUTOTEST ss-mount mounted object entries=" + ts1p.Entries.Count
                        + " persons=" + ts1p.PersonGUIDs.Count);

                    // (1) Studio Town controller bank — census-exact GUIDs (EXA-06
                    // simtype_controllers), with the mounted OBJD name logged so a
                    // divergence names itself.
                    var controllers = new Dictionary<uint, string>
                    {
                        { 0xDE1FD99Au, "NPC Controller - Superstar (NPCControllerSS)" },
                        { 0xC61F8102u, "Phone - Go Studio Plugin (PhonePluginStudioLots)" },
                        { 0x3B5A39F9u, "Stereo Speakers - Superstar - Music Controller" },
                        { 0x94400258u, "NPC Obsessed Fan - Generator" },
                        { 0xDF820338u, "Controller - Spa" },
                        { 0x91D0C8CDu, "Controller - Studio Traffic (ControllerStudioLot)" },
                        { 0x8EFA9A92u, "Controller - Studio Build/Buy (ControllerStudioLot)" },
                        { 0x6A75FC81u, "Controller - Celebrity Spawn (ControllerStudioLot)" },
                        { 0x925C17A2u, "Controller - Studio NPC (ControllerStudioLot)" },
                        { 0x20E32C3Cu, "Controller - Home Fame Decay (ControllerStudioLot)" },
                        { 0xC2AF7E1Cu, "Controller - Insanity (ControllerStudioLot)" }
                    };
                    int cfound = 0;
                    foreach (var kv in controllers)
                    {
                        FSO.Files.Formats.IFF.Chunks.OBJD objd;
                        if (ts1p.Entries.ContainsKey(kv.Key) && FSO.Content.TS1.TS1ObjectProvider.ObjdByGUID.TryGetValue(kv.Key, out objd))
                        {
                            cfound++;
                            Log("AUTOTEST ss-mount controller 0x" + kv.Key.ToString("x8") + " name=\""
                                + objd.ChunkLabel + "\" want=" + kv.Value);
                        }
                        else { Log("AUTOTEST ss-mount controller 0x" + kv.Key.ToString("x8") + " MISSING (" + kv.Value + ")"); ok = false; }
                    }
                    Log("AUTOTEST ss-mount controllers=" + cfound + "/" + controllers.Count);

                    // (2) the 56-person Studio Town cast, Person-typed (EXA-06 persons).
                    uint[] cast = {
                        0xD932FC29u, 0xA295FB82u, 0x74EFFBFEu, 0xD9B0FB54u, 0x55FCFB32u, 0x68A8FAFDu, 0x02F9DC42u,
                        0xC6D85D3Fu, 0xE7CF69F3u, 0x15B45D0Au, 0xCC5469C8u, 0x0D882E43u, 0xAA8B692Du, 0xC1144BC9u,
                        0xCD5E7AE2u, 0x29736784u, 0xABA3CEA9u, 0xD098519Fu, 0xA2B64A17u, 0x79184C1Du, 0x00FB4BD8u,
                        0x25604C00u, 0x51294D14u, 0x9E0B4D63u, 0x36434D0Au, 0x2367B7B1u, 0x4656FCF8u, 0x7A104D1Au,
                        0xA3644D21u, 0xD33558DBu, 0x7178EB1Bu, 0x5D6F3537u, 0x9669EB2Eu, 0x386BCE33u, 0x8092506Fu,
                        0x4CDC448Bu, 0x5183F3D5u, 0x18D2F3C0u, 0x6EC4F3DDu, 0x3C9085B8u, 0xC4881C24u, 0x17DF16D5u,
                        0x3396AA53u, 0x22EAE6B4u, 0xA20FFB6Au, 0xE1D61496u, 0x36F5D5CAu, 0x22B5A78Cu, 0xCA29D5F7u,
                        0xAEF74DA1u, 0x1E4060D8u, 0x4E777166u, 0x7F446268u, 0x55984D57u, 0x66D2626Eu, 0x8C1BEA25u
                    };
                    int pfound = cast.Count(g => ts1p.PersonGUIDs.Contains(g));
                    foreach (var g in cast.Where(g => !ts1p.PersonGUIDs.Contains(g)))
                        Log("AUTOTEST ss-mount person 0x" + g.ToString("x8") + " NOT-PERSON-TYPED");
                    Log("AUTOTEST ss-mount cast persons=" + pfound + "/" + cast.Length);
                    if (pfound != cast.Length) ok = false;
                }

                var tAudio = Content.Get().Audio as FSO.Content.TS1.TS1Audio;
                if (tAudio == null)
                {
                    Log("AUTOTEST ss-mount audio provider is not TS1Audio");
                    ok = false;
                }
                else
                {
                    var evts = tAudio.Events;
                    Log("AUTOTEST ss-mount events total=" + evts.Count);
                    // (3) fame + station registrations from sep6snds.hot (parsed from the
                    // pack's own HOT file; the fame stings are the award/agent/promo/dem
                    // reward sounds of the fame system).
                    var wantEvents = new (string Name, FSO.Files.HIT.HITEvents Type, uint Track)[]
                    {
                        ("station_superstar", FSO.Files.HIT.HITEvents.kSetMusicMode, 13u),
                        ("music_superstar_transition", FSO.Files.HIT.HITEvents.kSetMusicMode, 14u),
                        ("sting_fame_award", FSO.Files.HIT.HITEvents.kSoundobPlay, 103744u),
                        ("sting_fame_pro", FSO.Files.HIT.HITEvents.kSoundobPlay, 103741u),
                        ("sting_fame_dem", FSO.Files.HIT.HITEvents.kSoundobPlay, 103742u),
                        ("tv_superstar_animal", FSO.Files.HIT.HITEvents.kTurnOnTV, 103000u)
                    };
                    foreach (var want in wantEvents)
                    {
                        FSO.Content.Model.HITEventRegistration reg;
                        if (evts.TryGetValue(want.Name, out reg))
                        {
                            Log("AUTOTEST ss-mount event " + want.Name + " type=" + reg.EventType + " track=" + reg.TrackID);
                            if (reg.EventType != want.Type || reg.TrackID != want.Track) { Log("AUTOTEST ss-mount event " + want.Name + " MISMATCH"); ok = false; }
                        }
                        else { Log("AUTOTEST ss-mount event " + want.Name + " MISSING"); ok = false; }
                    }
                    // MusicModes routing: 13 = the superstar station, 14 = the SS
                    // transition mode ("KSST" -> Music/Modes/Superstar/). Mode 13's
                    // value is the raw IIS(100100) encoding (length-prefixed bytes,
                    // NUL-terminated) — assert non-empty but do NOT log it raw: a
                    // NUL in the log makes BSD grep classify it binary and the
                    // launcher's SUMMARY parse prints "Binary file matches".
                    string mm13, mm14;
                    bool m13 = tAudio.MusicModes.TryGetValue(13, out mm13);
                    bool m14 = tAudio.MusicModes.TryGetValue(14, out mm14);
                    bool m13Clean = m13 && mm13.Length > 0 && mm13.IndexOf('\0') < 0;
                    Log("AUTOTEST ss-mount musicmodes 13=" + (m13 ? ("len" + mm13.Length + (m13Clean ? " text-ok" : " raw-iis")) : "MISSING")
                        + " 14=" + (m14 ? mm14 : "MISSING"));
                    if (!m13 || string.IsNullOrEmpty(mm13) || !m14 || mm14 != "KSST") ok = false;
                }

                // (4) Studio Town template lots on the TS1 data root.
                var ts1Root = GlobalSettings.Default.TS1HybridPath;
                if (string.IsNullOrEmpty(ts1Root))
                {
                    Log("AUTOTEST ss-mount TS1HybridPath empty");
                    ok = false;
                }
                else
                {
                    int lotsFound = 0;
                    for (int house = 81; house <= 89; house++)
                    {
                        var p = Path.Combine(ts1Root, "TemplateStudiotown", "House" + house + ".iff");
                        if (File.Exists(p)) lotsFound++;
                        else { Log("AUTOTEST ss-mount lot MISSING " + p); ok = false; }
                    }
                    bool lotLoc = File.Exists(Path.Combine(ts1Root, "TemplateStudiotown", "LotLocations.iff"));
                    Log("AUTOTEST ss-mount template lots=" + lotsFound + "/9 lotLocations=" + lotLoc);
                    if (!lotLoc) ok = false;
                }
            }
            catch (Exception ex)
            {
                Log("AUTOTEST ss-mount EXC " + ex.GetType().Name + " " + ex.Message);
                ok = false;
            }
            if (ok) Pass("ss-mount"); else Fail("ss-mount");
        }

        // EXP-06 V2 leg 1 ('ss-plugin', opt-in): the Studio Town phone plugin ON the
        // played lot. The phone plugin object (PhonePluginStudioLots, 0xC61F8102) is
        // how a live household reaches Studio Town: its TTAB 129 rows are the phone's
        // studio interactions and its trees drive the Generate Cab -> Wait For Cab ->
        // Send Downtown chain (the same 4108/4117 BHAV ids EXP-04 decoded on the
        // Vacation plugin). This leg pins the departure point before any push:
        //   1. the plugin object EXISTS as a live entity on house 5 (the original
        //      bootstrap law — EXP-04 run 72 found its Vacation twin at obj267);
        //   2. every TTAB row resolves through the engine's GetAction (a row with a
        //      missing action or check tree is unofferable — the GetAction law);
        //   3. each row's TTAs label + action/check tree ids are logged (the next
        //      legs' push targets).
        private static void RunSSPlugin()
        {
            const uint PluginGuid = 0xC61F8102u;
            bool ok = true;
            try
            {
                var plugins = _vm.Entities.Where(e => e.Object?.OBJ != null && e.Object.OBJ.GUID == PluginGuid).ToList();
                Log("AUTOTEST ss-plugin instances=" + plugins.Count
                    + (plugins.Count > 0 ? " ids=[" + string.Join(",", plugins.Select(p => p.ObjectID)) + "]" : ""));
                if (plugins.Count == 0) { Log("AUTOTEST ss-plugin: plugin NOT PRESENT on the lot"); Fail("ss-plugin"); return; }

                var av = _avatars.Count > 0 ? _avatars[0] : null;
                foreach (var plugin in plugins)
                {
                    var ttab = plugin.TreeTable;
                    int rows = ttab?.Interactions?.Length ?? 0;
                    Log("AUTOTEST ss-plugin obj=" + plugin.ObjectID + " ttabRows=" + rows);
                    if (rows == 0) { Log("AUTOTEST ss-plugin obj=" + plugin.ObjectID + " NO TTAB ROWS"); ok = false; continue; }
                    for (uint row = 0; row < rows; row++)
                    {
                        VMQueuedAction a = null;
                        try { a = av != null ? plugin.GetAction((int)row, av, _vm.Context, false) : null; }
                        catch (Exception re) { Log("AUTOTEST ss-plugin row " + row + " resolve EXC " + re.GetType().Name + " " + re.Message); }
                        if (a == null)
                        {
                            Log("AUTOTEST ss-plugin row " + row + " UNRESOLVABLE (missing action/check tree)");
                            ok = false;
                            continue;
                        }
                        Log("AUTOTEST ss-plugin row " + row + " name=\"" + a.Name + "\" action=BHAV "
                            + (a.ActionRoutine?.ID ?? 0) + " check=BHAV " + (a.CheckRoutine?.ID.ToString() ?? "none"));
                    }
                }
            }
            catch (Exception ex)
            {
                Log("AUTOTEST ss-plugin EXC " + ex.GetType().Name + " " + ex.Message);
                ok = false;
            }
            if (ok) Pass("ss-plugin"); else Fail("ss-plugin");
        }

        // EXP-06 V2 leg 2+3 ('ss-book', opt-in): the Go Studio push leg + the
        // queue-path dialog responder. EXP-04's vacation law set, applied to the
        // Studio plugin (0xC61F8102):
        //   - 4100 ins25 gates on StackObject attr[1] == 0 -> the direct push never
        //     activates until the booking-armed attribute is set (run-76 law); the
        //     native dialogs arm it — this leg arms attr[1]=1 probe-side (disclosed)
        //     and reads whether the push then walks the chain;
        //   - 'Ask for Lot' (4103) raises a TS1Vacation-class dialog and the tree
        //     parks until answered (leg-2 law: gbd obj307 parked the window);
        //   - leg 3: respond through the PRODUCTION path's semantics
        //     (VMNetDialogResponseCmd.TS1 branch): set the VMDialogResult BlockingState
        //     Responded/ResponseCode/ResponseText on the blocking dialog's thread
        //     (or any queue-path entity's unresponded dialog — the HPAnswerDialogs
        //     scan law), clear GlobalBlockingDialog, restore speed from
        //     LastSpeedMultiplier. The dialog answer text becomes temp0 (EXP-04
        //     V2.7 law: answered "1" -> temp0=1), so the responder answers "81" to
        //     route the mode-17 switch at Studio Town lot 81 (GetHousePath(81)
        //     exists — TemplateUserData ships House00-99).
        // Watch (~60 sim-min window, sample every 60f): avatar ActiveAction, plugin
        // attrs, cab 0x6477AB64 spawn (the EXP-04 V2.0 departure-machinery GUID),
        // GlobalBlockingDialog, TS1State.LotTransitInfo, InLot, entity count.
        // Verdict: PASS on terminal=depTokens (the EXP-04 VACBOOK booking proof —
        // banked departure tokens; the pickup machine keeps polling and transit
        // needs the leg-4 clock lever) or cab seen AND (transit OR lot switch);
        // otherwise FAIL naming the terminal state. The review note (2026-09-22):
        // VMDialogResult codes are 0=yes/ok, 1=no, 2=cancel and YesNo maps 0->TRUE —
        // the booking continuation here rides the FALSE branch of the obj307 YesNo,
        // and the TS1StudioTown picker ignores the code byte entirely (its answer
        // rides ResponseText). Blanket code=1 on Message/YesNo dialogs is not what a
        // native click sends (empty text) — empirical chain identical runs 4-6.
        private static bool _ssBookDone;
        private static int _ssBookFrame;
        private static VMEntity _ssBookPlugin;
        private static VMAvatar _ssBookAv;
        private static string _ssBookTerminal;
        private static bool _ssBookCabSeen;
        private static bool _ssBookTokensSeen;
        private static bool _ssBookClockArmed;
        private static int _ssBookTokH = -1;
        private static int _ssBookTokM = -1;
        private static int _ssBookAnswered;
        private static readonly List<string> _ssBookTrace = new List<string>();
        private static readonly Dictionary<string, int> _ssBookTraceAgg = new Dictionary<string, int>();
        private static bool _ssBookTraceArmed;
        private static bool _ssBookTraceDone;
        private static bool _ssBookSelectorDone;
        private static bool _ssBookArrived;
        private static int _ssBookArrivedFrame = -1;
        private static readonly Dictionary<int, short[]> _ssBookPD0 = new Dictionary<int, short[]>();
        private static readonly HashSet<string> _ssBookStings = new HashSet<string>();
        private static bool _ssBookPerfPushed;
        private static bool _ssBookFameSting;
        private static readonly Dictionary<string, int> _ssBookPDDiffs = new Dictionary<string, int>();
        private static int _ssBookLastUpdates = -1, _ssBookLastTicks = -1;
        private static int _ssBookTraceOther;
        private static bool _ssBookNotifyArmed;
        private static int _ssBookNotifyFrame = -1;
        private static void SSBookTick()
        {
            _ssBookFrame++;
            try
            {
                if (_ssBookFrame == 1)
                {
                    _ssBookPlugin = _vm.Entities.FirstOrDefault(e => e.Object?.OBJ != null && e.Object.OBJ.GUID == 0xC61F8102);
                    _ssBookAv = _avatars.Count > 0 ? _avatars[0] : null;
                    if (_ssBookPlugin == null || _ssBookAv == null)
                    {
                        Log("AUTOTEST ss-book arm FAIL plugin=" + (_ssBookPlugin != null) + " av=" + (_ssBookAv != null));
                        Fail("ss-book"); _ssBookDone = true; Finish(); return;
                    }
                    var attrs = new short[8];
                    for (short i = 0; i < 8; i++) attrs[i] = _ssBookPlugin.GetAttribute(i);
                    Log("AUTOTEST ss-book obj=" + _ssBookPlugin.ObjectID + " attrs[0..7]=[" + string.Join(",", attrs) + "]");
                    _ssBookPlugin.SetAttribute(1, 1);
                    Log("AUTOTEST ss-book attr[1] armed (probe-side; native arm is the phone dialog) -> "
                        + _ssBookPlugin.GetAttribute(1));
                    var action = _ssBookPlugin.GetAction(2, _ssBookAv, _vm.Context, false);
                    if (action == null) { Log("AUTOTEST ss-book: row 2 GetAction null"); Fail("ss-book"); _ssBookDone = true; Finish(); return; }
                    action.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                    _ssBookAv.Thread.EnqueueAction(action);
                    Log("AUTOTEST ss-book pushed row 2 'Go to Studio Town' uid=" + action.UID);
                    return;
                }
                // R157 unpause replication: my short-circuit bypasses StateSample's
                // own unpause, so a mid-watch dialog park (speed=-2) would stall the
                // WHOLE VM and read as "thread never executes" (the run-11 artifact).
                // The engine's pause is legitimate blocking-dialog UX; the probe
                // unpauses exactly as the runner does elsewhere. Review note (P3):
                // clearing GlobalBlockingDialog here does NOT set BlockingState.
                //Responded — the same-tick entity-scan responder answers any
                // unresponded VMDialogResult; a parked BlockingState that is not a
                // VMDialogResult would be masked as "running" (identical to the
                // runner's own r157 semantics).
                if (_vm.SpeedMultiplier <= 0)
                {
                    var staleLatch = _vm.GlobalBlockingDialog;
                    _vm.SpeedMultiplier = _vm.LastSpeedMultiplier > 0 ? _vm.LastSpeedMultiplier : 1;
                    _vm.LastSpeedMultiplier = 0;
                    _vm.GlobalBlockingDialog = null;
                    Log("AUTOTEST ss-book unpaused vm (speed was <=0; stale-latch "
                        + (staleLatch == null ? "none" : "obj" + staleLatch.ObjectID) + " released) at f=" + _ssBookFrame);
                }

                // One-shot manual entity-tick bracket (the EXP-04 V3.4 bisect): if a
                // manual avatar.Tick() executes instructions while the scheduler's own
                // pump executes none, the entity is stranded outside TickSchedule; if
                // the manual tick also executes nothing, the thread exits early.
                if (_ssBookFrame == 400)
                {
                    // review P2: deliberately NOT gated on _ssBookTraceDone — booking
                    // success disarms the trace by f~138 (budget exhausted), which
                    // would otherwise starve this bracket in exactly the headline
                    // scenario it was built to bisect.
                    var avObjId = _ssBookAv.ObjectID;
                    _ssBookTrace.Clear();
                    _ssBookTraceAgg.Clear();
                    _ssBookTraceOther = 0;
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = s =>
                    {
                        if (s.Contains("ent=" + avObjId + " ")) { if (_ssBookTrace.Count < 200) _ssBookTrace.Add(s); }
                        else _ssBookTraceOther++;
                    };
                    FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget = 400;
                    Log("AUTOTEST ss-book manual-tick bracket: schedIdleEnd=" + _ssBookAv.Thread?.ScheduleIdleEnd
                        + " curTick=" + _vm.Scheduler.CurrentTickID + " dead=" + _ssBookAv.Dead
                        + " spd=" + _vm.SpeedMultiplier);
                    try { _ssBookAv.Tick(); }
                    catch (Exception te) { Log("AUTOTEST ss-book manual tick EXC " + te.GetType().Name + " " + te.Message); }
                    Log("AUTOTEST ss-book manual-tick result: avatarLines=" + _ssBookTrace.Count
                        + " otherLines=" + _ssBookTraceOther
                        + " first=" + (_ssBookTrace.Count > 0 ? _ssBookTrace[0] : "none"));
                    foreach (var l in _ssBookTrace.Take(10)) Log("AUTOTEST ss-book MT " + l);
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = null;
                    FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget = 0;
                }

                // Leg-4 law (runs 10-14): after the picker answer the screen's pump
                // (vm.Update) stops entirely — cur frozen, async=False, ready=True,
                // spd=1 — while the frame loop runs. The production picker answer
                // (UILotControl.HouseSelected) does what the VM-level answer cannot:
                // it REMOVES the composed UINeighborhoodSelectionPanel (the UI state
                // whose presence gates the pump) and then answers through
                // VMNetDialogResponseCmd. Invoke the production handler reflectively.
                if (_ssBookFrame == 300 && !_ssBookSelectorDone)
                {
                    _ssBookSelectorDone = true;
                    try
                    {
                        var lotCtrl = _screen?.LotControl;
                        if (lotCtrl != null)
                        {
                            var t = lotCtrl.GetType();
                            var selField = t.GetField("TS1NeighSelector",
                                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                            var sel = selField?.GetValue(lotCtrl);
                            Log("AUTOTEST ss-book selector present=" + (sel != null) + " at f=300");
                            if (sel != null)
                            {
                                var hs = t.GetMethod("HouseSelected",
                                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                                if (hs != null) hs.Invoke(lotCtrl, new object[] { 81 });
                                Log("AUTOTEST ss-book HouseSelected(81) invoked=" + (hs != null)
                                    + " (production picker answer; HouseSelected itself early-returns "
                                    + "if ActiveEntity is null — the selector-removal still runs client-side)");
                            }
                        }
                    }
                    catch (Exception se) { Log("AUTOTEST ss-book selector EXC " + se.GetType().Name + " " + se.Message); }
                }

                // THE leg-4 freeze (run 16 pump counters): VM.Tick runs 30x/s but
                // VMServerDriver.Tick's `if (vm.SpeedMultiplier > 0) tick.TickID++`
                // never advances TickID — a per-frame park lands after the probe's
                // speed restore and before the pump. The park is the UIMainPanel
                // non-LIVE law (UIMainPanel.cs:1280, `if (Mode != LIVE)
                // SpeedMultiplier = -1`): the booking flips the panel out of LIVE.
                // The EXP-04 V4.2 lever: flip the panel Mode to LIVE — what a
                // player's LIVE click does. Re-applied each tick in case the panel
                // re-asserts non-LIVE.
                if (_ssBookClockArmed)
                {
                    var mainPanel = _screen?.Frontend?.MainPanel;
                    if (mainPanel != null && mainPanel.Mode != Simitone.Client.UI.Panels.UIMainPanelMode.LIVE)
                    {
                        var was = mainPanel.Mode;
                        mainPanel.SetMode(Simitone.Client.UI.Panels.UIMainPanelMode.LIVE);
                        Log("AUTOTEST ss-book livelift: panel Mode " + was + " -> LIVE at f=" + _ssBookFrame);
                    }
                }

                // Driver-state dump (runs 18+): at f=300 and f=1000 reflect the
                // VMServerDriver privates — the silent doTick=false latch (a recurring
                // VMStateSyncCmd(Run) in the command queue) and the TickID/LastTick
                // truth are both directly visible here.
                if ((_ssBookFrame == 300 || _ssBookFrame == 1000) && _ssBookLastUpdates >= 0)
                {
                    try
                    {
                        var BF = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
                        var drv = typeof(FSO.SimAntics.VM).GetField("Driver", BF)?.GetValue(_vm);
                        if (drv == null) { Log("AUTOTEST ss-book drvstate Driver null"); }
                        else
                        {
                            var tt = drv.GetType();
                            string Describe(string fieldName)
                            {
                                var list = tt.GetField(fieldName, BF)?.GetValue(drv) as System.Collections.IEnumerable;
                                if (list == null) return "null";
                                int c = 0; var names = new List<string>();
                                foreach (var item in list) { c++; if (names.Count < 4) names.Add(item?.GetType().Name ?? "null"); }
                                return "count=" + c + (names.Count > 0 ? "[" + string.Join(",", names) + "]" : "");
                            }
                            Log("AUTOTEST ss-book drvstate f=" + _ssBookFrame
                                + " driverType=" + tt.Name
                                + " TickID=" + tt.GetField("TickID", BF)?.GetValue(drv)
                                + " LastTick=" + tt.GetField("LastTick", BF)?.GetValue(drv)
                                + " CurrentTick=" + tt.GetField("CurrentTick", BF)?.GetValue(drv)
                                + " QueuedCmds{" + Describe("QueuedCmds") + "}"
                                + " DeferredCmds{" + Describe("DeferredCmds") + "}"
                                + " SyncSerializing=" + tt.GetField("SyncSerializing", BF)?.GetValue(drv)
                                + " TicksSinceSync=" + (tt.GetField("TicksSinceSync", BF)?.GetValue(drv) as System.Collections.ICollection)?.Count);
                        }
                    }
                    catch (Exception de) { Log("AUTOTEST ss-book drvstate EXC " + de.GetType().Name + " " + de.Message); }
                }

                // Arrival detector (the run-19/20 orphaning law): when the departure's
                // SignalLotSwitch(81) lands, TS1GameScreen REPLACES its vm (VMLotSwitch
                // -> InitializeLot) — the probe's stale _vm reference then reads the
                // orphaned corpse (frozen clock/tick) while the LIVE VM runs Studio
                // Town. Switch sampling to the screen's live VM and census the
                // arrival-side controllers.
                var screenVm = _screen?.vm;
                if (screenVm != null && !ReferenceEquals(screenVm, _vm))
                {
                    var oldEnts = _vm.Entities.Count;
                    _vm = screenVm;
                    var ctrls = _vm.Entities.Where(e => e.Object?.OBJ != null
                        && (e.Object.OBJ.GUID == 0x91D0C8CDu || e.Object.OBJ.GUID == 0x6A75FC81u
                            || e.Object.OBJ.GUID == 0x925C17A2u || e.Object.OBJ.GUID == 0x8EFA9A92u))
                        .Select(e => "0x" + e.Object.OBJ.GUID.ToString("x8") + "@obj" + e.ObjectID).ToList();
                    Log("AUTOTEST ss-book VM REPLACED (lot switch landed) at f=" + _ssBookFrame
                        + " oldEnts=" + oldEnts + " newEnts=" + _vm.Entities.Count
                        + " arrivalControllers=[" + string.Join(",", ctrls) + "]");
                    // arrival PROVEN — the departure's ins 12 fired and the Studio Town
                    // lot (controllers live) is the screen's current VM. Take the
                    // one-shot arrival census (avatars + positions + performance
                    // objects), then sample the LIVE VM for a bounded window.
                    _ssBookArrived = true;
                    _ssBookArrivedFrame = _ssBookFrame;
                    Log("AUTOTEST ss-book ARRIVAL CENSUS (lot 81) at f=" + _ssBookFrame);
                    var arrAvs = _vm.Entities.OfType<VMAvatar>().ToList();
                    Log("AUTOTEST ss-book arrival avatars=" + arrAvs.Count);
                    foreach (var a in arrAvs)
                        Log("AUTOTEST ss-book arrival sim obj=" + a.ObjectID
                            + " pos=(" + a.Position.TileX + "," + a.Position.TileY + ",L" + a.Position.Level + ")"
                            + " action=" + (a.Thread?.ActiveAction?.Name ?? "-"));
                    var perfKeys = new[] { "studio", "fame", "dance", "massage", "photo", "record", "stage", "dressing", "spa", "oxygen" };
                    var perf = _vm.Entities.Where(e => e.Object?.OBJ != null)
                        .GroupBy(e => perfKeys.FirstOrDefault(k => (e.Object.OBJ.ChunkLabel ?? "").ToLowerInvariant().Contains(k)))
                        .Where(g => g.Key != null)
                        .Select(g => g.Key + "=" + g.Count())
                        .OrderBy(x => x).ToList();
                    Log("AUTOTEST ss-book arrival perfObjects " + string.Join(" ", perf));
                    // label the actual drive targets: distinct labels + positions
                    var labels = _vm.Entities.Where(e => e.Object?.OBJ != null
                        && perfKeys.Any(k => (e.Object.OBJ.ChunkLabel ?? "").ToLowerInvariant().Contains(k)))
                        .GroupBy(e => e.Object.OBJ.ChunkLabel)
                        .Select(g => g.Key + " x" + g.Count() + " @obj" + string.Join("/obj", g.Take(3).Select(x => x.ObjectID)))
                        .OrderBy(x => x).ToList();
                    foreach (var l in labels) Log("AUTOTEST ss-book arrival perfLabel " + l);
                }

                // Leg 3: the queue-path dialog responder (production VMNetDialogResponseCmd
                // semantics; runs BEFORE sampling so the same-tick release is visible).
                FSO.SimAntics.Primitives.VMDialogResult target = null;
                VMEntity targetOwner = null;
                var gbd = _vm.GlobalBlockingDialog;
                if (gbd != null)
                {
                    var bs = gbd.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                    if (bs != null && !bs.Responded) { target = bs; targetOwner = gbd; }
                }
                if (target == null)
                {
                    foreach (var ent in _vm.Entities)
                    {
                        var qbs = ent?.Thread?.BlockingState as FSO.SimAntics.Primitives.VMDialogResult;
                        if (qbs != null && !qbs.Responded) { target = qbs; targetOwner = ent; break; }
                    }
                }
                if (target != null)
                {
                    target.Responded = true;
                    // 0=yes/ok, 1=no, 2=cancel; YesNo maps 0->TRUE. The booking
                    // continuation rides the YesNo FALSE branch, and the TS1StudioTown
                    // picker parses only ResponseText ("81" -> temp0) — see the header note.
                    target.ResponseCode = 1;
                    target.ResponseText = "81"; // -> temp0=81 -> mode-17 SignalLotSwitch(81)
                    if (ReferenceEquals(_vm.GlobalBlockingDialog, targetOwner) || targetOwner == gbd)
                        _vm.GlobalBlockingDialog = null;
                    if (_vm.LastSpeedMultiplier > 0) { _vm.SpeedMultiplier = _vm.LastSpeedMultiplier; _vm.LastSpeedMultiplier = 0; }
                    else if (_vm.SpeedMultiplier < 0) _vm.SpeedMultiplier = 1;
                    _ssBookAnswered++;
                    Log("AUTOTEST ss-book dialog answered #" + _ssBookAnswered + " owner=obj" + (targetOwner?.ObjectID ?? 0)
                        + " type=" + target.Type + " code=1 text=\"81\" gbdCleared=" + (_vm.GlobalBlockingDialog == null)
                        + " at f=" + _ssBookFrame);
                }

                // Wait-For-Notify release (the EXP-04 V1.3 law): the booking trees park
                // in global 281 'Wait For Notify' whose innermost idle_for_input counts
                // 20000 ticks — far beyond this window. The native release is
                // ActiveAction.NotifyIdle re-evaluated on the next idle execution, so
                // arm the flag AND schedule a 1-tick scheduler wake to re-enter the idle.
                if (_ssBookFrame > 120 && !_ssBookNotifyArmed)
                {
                    var aaNi = _ssBookAv.Thread.ActiveAction;
                    if (aaNi != null && !aaNi.NotifyIdle)
                    {
                        aaNi.NotifyIdle = true;
                        _vm.Scheduler.ScheduleTickIn(_ssBookAv, 1);
                        _ssBookNotifyArmed = true;
                        _ssBookNotifyFrame = _ssBookFrame;
                        Log("AUTOTEST ss-book armed NotifyIdle + 1-tick wake (Wait-For-Notify park) at f=" + _ssBookFrame);
                    }
                }
                // dense post-arm trace (the EXP-04 V1.3 run-75 pattern): name the exit
                // branch frame by frame for 40 frames after the wake.
                if (_ssBookNotifyFrame > 0 && _ssBookFrame >= _ssBookNotifyFrame && _ssBookFrame < _ssBookNotifyFrame + 40)
                {
                    var tst = _ssBookAv.Thread.Stack;
                    var ta = _ssBookAv.Thread.ActiveAction;
                    Log("AUTOTEST ss-book POST f=" + _ssBookFrame
                        + " active=" + (ta == null ? "none" : "'" + ta.Name + "'uid" + ta.UID + " ni=" + ta.NotifyIdle)
                        + " bs=" + (_ssBookAv.Thread.BlockingState == null ? "-" : _ssBookAv.Thread.BlockingState.GetType().Name)
                        + " transit=" + _vm.TS1State.LotTransitInfo
                        + " stack=[" + (tst == null ? "" : string.Join(",", tst.Select(f => (f.Routine?.ID ?? 0) + "@" + ((int)f.InstructionPointer)))) + "]");
                }

                // Leg-4 continuation: arm the engine-side instruction-trace sink for a
                // bounded window once the machine is booked and the clock armed; the
                // executed-cycle map names the branch the 4100 loop cycles on.
                if (_ssBookClockArmed && !_ssBookTraceArmed && !_ssBookTraceDone)
                {
                    _ssBookTraceArmed = true;
                    _ssBookTrace.Clear();
                    _ssBookTraceAgg.Clear();
                    _ssBookTraceOther = 0;
                    var avObj = _ssBookAv.ObjectID;
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = s =>
                    {
                        _ssBookTraceOther++;
                        if (!s.Contains("ent=" + avObj + " ")) return;
                        _ssBookTraceOther--;
                        if (_ssBookTrace.Count < 500) _ssBookTrace.Add(s);
                        if (_ssBookTraceAgg.ContainsKey(s.Substring(s.IndexOf(' ') + 1))) _ssBookTraceAgg[s.Substring(s.IndexOf(' ') + 1)]++;
                        else _ssBookTraceAgg[s.Substring(s.IndexOf(' ') + 1)] = 1;
                    };
                    FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget = 800;
                    Log("AUTOTEST ss-book ITRACE armed (budget 800) at f=" + _ssBookFrame);
                }
                if (_ssBookTraceArmed && (FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget <= 0
                    || _ssBookFrame > 300))
                {
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = null;
                    FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget = 0;
                    _ssBookTraceArmed = false;
                    _ssBookTraceDone = true;
                    Log("AUTOTEST ss-book ITRACE disarmed at f=" + _ssBookFrame + " avatarLines=" + _ssBookTrace.Count
                        + " otherLines=" + _ssBookTraceOther + " distinct=" + _ssBookTraceAgg.Count);
                    foreach (var kv in _ssBookTraceAgg.OrderByDescending(x => x.Value).Take(20))
                        Log("AUTOTEST ss-book ITRACE cycle " + kv.Value + "x " + kv.Key);
                    foreach (var l in _ssBookTrace.Take(15)) Log("AUTOTEST ss-book ITRACE first " + l);
                    foreach (var l in _ssBookTrace.Skip(Math.Max(0, _ssBookTrace.Count - 15))) Log("AUTOTEST ss-book ITRACE last " + l);
                }

                if (_ssBookArrived)
                {
                    // post-arrival sampling of the LIVE VM: sim routing + the
                    // performance/ambient machinery on lot 81.
                    // V3: fame-sting audible detection — poll HITVM.ActiveEvents
                    // (reflection on the private dict; the rail pattern without an
                    // engine edit) for any fame/sting event name, and diff each
                    // sim's PD against the pre-departure snapshot.
                    try
                    {
                        var hit = FSO.HIT.HITVM.Get();
                        var aeF = hit.GetType().GetField("ActiveEvents",
                            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                        var ae = aeF?.GetValue(hit) as System.Collections.IDictionary;
                        if (ae != null)
                        {
                            foreach (var key in ae.Keys)
                            {
                                var name = key?.ToString() ?? "";
                                if ((name.Contains("fame") || name.Contains("sting")) && _ssBookStings.Add(name))
                                    Log("AUTOTEST ss-book HIT EVENT active: " + name + " at f=" + _ssBookFrame);
                                if (name.Contains("sting_fame")) _ssBookFameSting = true;
                            }
                        }
                    }
                    catch { }
                    var liveAvs = _vm.Entities.OfType<VMAvatar>().ToList();
                    foreach (var a in liveAvs)
                    {
                        if (!_ssBookPD0.TryGetValue(a.ObjectID, out var pd0)) continue;
                        var diffs = new List<string>();
                        for (short i = 0; i < 80; i++)
                        {
                            var now = a.GetPersonData((VMPersonDataVariable)i);
                            if (now != pd0[i]) diffs.Add("PD[" + i + "] " + pd0[i] + "->" + now);
                        }
                        if (diffs.Count > 0)
                        {
                            Log("AUTOTEST ss-book PD diff obj=" + a.ObjectID + ": " + string.Join(", ", diffs) + " at f=" + _ssBookFrame);
                            _ssBookPDDiffs["obj" + a.ObjectID] = diffs.Count;
                        }
                    }
                    if (_ssBookFrame % 100 == 0)
                    {
                        var avatars2 = _vm.Entities.OfType<VMAvatar>().ToList();
                        foreach (var a in avatars2)
                            Log("AUTOTEST ss-book live sim obj=" + a.ObjectID
                                + " pos=(" + a.Position.TileX + "," + a.Position.TileY + ",L" + a.Position.Level + ")"
                                + " action=" + (a.Thread?.ActiveAction?.Name ?? "-")
                                + " at f=" + _ssBookFrame);
                        var cars2 = _vm.Entities.Count(e => e.Object?.OBJ != null
                            && (e.Object.OBJ.GUID == 0x105BCC90u || e.Object.OBJ.GUID == 0xF408F4DBu
                                || e.Object.OBJ.GUID == 0x5326FC22u || e.Object.OBJ.GUID == 0xD5A8B9A6u));
                        Log("AUTOTEST ss-book live cars=" + cars2 + " at f=" + _ssBookFrame);
                    }
                    // V3 increment 4: the dressing-room-first drive. Enumerate the
                    // dressing mirrors' FULL TTAB rows (the engine-parsed chunk —
                    // includes rows GetAction would refuse) + names from TTAs; push
                    // any costume-ish row onto a sim before the rug scene.
                    if (_ssBookFrame == _ssBookArrivedFrame + 100)
                    {
                        var mirrors = _vm.Entities.Where(e =>
                            (e.Object?.OBJ?.ChunkLabel ?? "").ToLowerInvariant().Contains("dressing room")).ToList();
                        var BF = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
                        foreach (var m in mirrors)
                        {
                            var tt = m.TreeTable;
                            if (tt?.Interactions == null) { Log("AUTOTEST ss-book mirror obj=" + m.ObjectID + " no TTAB"); continue; }
                            var ttas = m.TreeTableStrings;
                            for (uint row = 0; row < tt.Interactions.Length; row++)
                            {
                                var inter = tt.Interactions[row];
                                var nm = "";
                                try { nm = ttas?.GetString((int)inter.TTAIndex) ?? ""; } catch { }
                                Log("AUTOTEST ss-book mirror obj=" + m.ObjectID + " row " + row
                                    + " actionFn=" + inter.ActionFunction + " testFn=" + inter.TestFunction
                                    + " name=\"" + nm + "\"");
                                var lower = nm.ToLowerInvariant();
                                if (lower.Contains("costume") || lower.Contains("change") || lower.Contains("dress"))
                                {
                                    var av = _vm.Entities.OfType<VMAvatar>().FirstOrDefault();
                                    if (av != null)
                                    {
                                        var act = m.GetAction((int)row, av, _vm.Context, false);
                                        if (act != null)
                                        {
                                            act.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                                            av.Thread.EnqueueAction(act);
                                            Log("AUTOTEST ss-book COSTUME push: '" + act.Name + "' -> sim obj"
                                                + av.ObjectID + " uid=" + act.UID);
                                        }
                                        else Log("AUTOTEST ss-book costume row GetAction null (gated)");
                                    }
                                }
                            }
                        }
                    }
                    // V3 increment 6: the seat inventory + seating choreography.
                    // Enumerate every soap-set piece (labels 'Set - Soap Opera*'),
                    // log TTAB row names, and push sit/direct rows: the Director
                    // Seat piece (16815) onto sim0, actor pieces onto sims 1/2.
                    if (_ssBookFrame == _ssBookArrivedFrame + 140)
                    {
                        var pieces = _vm.Entities.Where(e =>
                            (e.Object?.OBJ?.ChunkLabel ?? "").Contains("Soap Opera")).ToList();
                        Log("AUTOTEST ss-book soap pieces=" + pieces.Count);
                        var BF2 = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
                        var sims2 = _vm.Entities.OfType<VMAvatar>().ToList();
                        foreach (var p in pieces)
                        {
                            var tt = p.TreeTable;
                            if (tt?.Interactions == null) continue;
                            var lbl = p.Object.OBJ.ChunkLabel;
                            var isDirector = lbl.Contains("Director Seat");
                            for (uint row = 0; row < tt.Interactions.Length; row++)
                            {
                                var inter = tt.Interactions[row];
                                string nm = null;
                                try { nm = p.TreeTableStrings?.GetString((int)inter.TTAIndex) ?? ""; } catch { }
                                Log("AUTOTEST ss-book piece obj=" + p.ObjectID + " '" + lbl + "' row " + row
                                    + " fn=" + inter.ActionFunction + "/" + inter.TestFunction + " name='" + nm + "'");
                                var lower = (nm ?? "").ToLowerInvariant();
                                var wantSim = isDirector ? sims2.FirstOrDefault() : sims2.Skip(1).FirstOrDefault();
                                if (wantSim == null) continue;
                                // run-34 law: every piece carries the same 5-row pie.
                                // The correct choreography: the DIRECTOR SEAT piece's
                                // row 3 ('Direct') -> sim0; two OTHER pieces' row 4
                                // ('Act Autonomous') -> sims 1/2.
                                var wantRow = isDirector ? (row == 3 && lower.Contains("direct"))
                                                         : (row == 4 && lower.Contains("autonomous"));
                                if (!wantRow) continue;
                                VMQueuedAction a = null;
                                try { a = p.GetAction((int)row, wantSim, _vm.Context, false); } catch { }
                                if (a != null)
                                {
                                    a.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                                    wantSim.Thread.EnqueueAction(a);
                                    Log("AUTOTEST ss-book SEAT push '" + nm + "' (piece obj" + p.ObjectID
                                        + " row " + row + ") -> sim obj" + wantSim.ObjectID + " uid=" + a.UID);
                                    break; // one push per piece
                                }
                            }
                        }
                    }
                    // V3 increment 5: the soap-set session drive. The set's pie has
                    // 'Direct' (director seat) and 'Act Autonomous' (actor seats) —
                    // the session machine (Make Random Director -> Scene: Play Role
                    // -> Do I Win? -> fame write) runs when a director + actors are
                    // in the seats. Push Direct on sim0, Act Autonomous on sim1/2.
                    if (_ssBookFrame == _ssBookArrivedFrame + 120)
                    {
                        var soap = _vm.Entities.Where(e => e.TreeTable != null)
                            .FirstOrDefault(e =>
                            {
                                try
                                {
                                    var ttas = e.TreeTableStrings;
                                    for (uint r = 0; r < e.TreeTable.Interactions.Length; r++)
                                        if ((ttas?.GetString((int)e.TreeTable.Interactions[r].TTAIndex) ?? "").Contains("Act Autonomous"))
                                            return true;
                                }
                                catch { }
                                return false;
                            });
                        if (soap == null) { Log("AUTOTEST ss-book soap set NOT FOUND in the live VM"); }
                        else
                        {
                            Log("AUTOTEST ss-book soap set found obj=" + soap.ObjectID
                                + " rows=" + soap.TreeTable.Interactions.Length);
                            var sims = _vm.Entities.OfType<VMAvatar>().ToList();
                            var plans = new[] { ("Direct", 0), ("Act Autonomous", 1), ("Act Autonomous", 2) };
                            foreach (var (want, si) in plans)
                            {
                                if (sims.Count <= si) break;
                                var sim = sims[si];
                                for (uint row = 0; row < soap.TreeTable.Interactions.Length; row++)
                                {
                                    var inter = soap.TreeTable.Interactions[row];
                                    string nm = null;
                                    try { nm = soap.TreeTableStrings?.GetString((int)inter.TTAIndex) ?? ""; } catch { }
                                    if (string.IsNullOrEmpty(nm) || !nm.Contains(want)) continue;
                                    VMQueuedAction a = null;
                                    try { a = soap.GetAction((int)row, sim, _vm.Context, false); } catch { }
                                    if (a == null) { Log("AUTOTEST ss-book session row " + row + " '" + nm + "' unresolved for obj" + sim.ObjectID); continue; }
                                    a.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                                    sim.Thread.EnqueueAction(a);
                                    Log("AUTOTEST ss-book session push '" + nm + "' (row " + row + ") -> sim obj"
                                        + sim.ObjectID + " uid=" + a.UID);
                                    break;
                                }
                            }
                        }
                    }
                    // V3 increment 3: drive the PHOTO SHOOT set (the decoded fame
                    // venue) — push all three TTAB 131 interactions across the
                    // arrival sims with the sting poll + PD diff armed.
                    if (_ssBookFrame == _ssBookArrivedFrame + 100)
                    {
                        var setObj = _vm.Entities.FirstOrDefault(e =>
                            (e.Object?.OBJ?.ChunkLabel ?? "") == "Set - Photo Shoot" && e.TreeTable != null)
                            ?? _vm.Entities.FirstOrDefault(e =>
                            (e.Object?.OBJ?.ChunkLabel ?? "").Contains("Photo Shoot") && e.TreeTable != null);
                        if (setObj == null)
                        {
                            Log("AUTOTEST ss-book photo shoot: set object NOT FOUND in the live VM");
                        }
                        else
                        {
                            var rows = setObj.TreeTable?.Interactions?.Length ?? 0;
                            Log("AUTOTEST ss-book photo shoot set obj=" + setObj.ObjectID + " rows=" + rows);
                            var sims = _vm.Entities.OfType<VMAvatar>().ToList();
                            for (uint row = 0; row < rows; row++)
                            {
                                var sim = sims.Count > 0 ? sims[(int)(row % sims.Count)] : null;
                                if (sim == null) break;
                                VMQueuedAction a = null;
                                try { a = setObj.GetAction((int)row, sim, _vm.Context, false); } catch { }
                                if (a == null) { Log("AUTOTEST ss-book photo push row " + row + " unresolved"); continue; }
                                a.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                                sim.Thread.EnqueueAction(a);
                                Log("AUTOTEST ss-book photo push row " + row + " '" + a.Name + "' -> sim obj"
                                    + sim.ObjectID + " uid=" + a.UID);
                            }
                        }
                    }
                    // V3 increment 2: drive a performance — scan lot 81's TTAB-bearing
                    // objects for a performance-ish interaction and push the best
                    // candidate onto the first arrival sim (priority verbs below).
                    if (_ssBookFrame == _ssBookArrivedFrame + 150)
                    {
                        var verbs = new[] { "perform", "sing", "play ", "pose", "model", "practice", "dance", "act" };
                        var actor = _vm.Entities.OfType<VMAvatar>().FirstOrDefault();
                        if (actor == null) { Log("AUTOTEST ss-book perf scan: no avatar in the live VM"); }
                        else
                        {
                            var cands = new List<string>();
                            foreach (var e in _vm.Entities)
                            {
                                var tt = e.TreeTable;
                                if (tt?.Interactions == null) continue;
                                for (uint row = 0; row < tt.Interactions.Length; row++)
                                {
                                    VMQueuedAction a = null;
                                    try { a = e.GetAction((int)row, actor, _vm.Context, false); } catch { }
                                    if (a == null || string.IsNullOrEmpty(a.Name)) continue;
                                    var nm = a.Name.ToLowerInvariant();
                                    var hitV = verbs.FirstOrDefault(v => nm.Contains(v));
                                    if (hitV != null)
                                        cands.Add("obj" + e.ObjectID + " row" + row + " '" + a.Name + "' verb=" + hitV.Trim());
                                }
                            }
                            Log("AUTOTEST ss-book perf candidates (" + cands.Count + "): " + string.Join(" | ", cands.Take(20)));
                            // pick: prefer the ACT scenes (the Studio Town fame
                            // performances) on non-avatar objects; run 25 law:
                            // 'Perform Trick' matched first but lives on another SIM
                            // (a social, not a solo performance).
                            var avatarIds = new HashSet<int>(_vm.Entities.OfType<VMAvatar>().Select(a => (int)a.ObjectID));
                            var nonSim = cands.Where(c =>
                            {
                                var p = c.Split(' ')[0];
                                return int.TryParse(p.Replace("obj", ""), out var oid) && !avatarIds.Contains(oid);
                            }).ToList();
                            // precise scene match: the fame performances are named
                            // 'Act.../Emergency Scene', 'Act.../Inheritance Scene',
                            // 'Act.../Commercial' — match the 'act.../' prefix, not
                            // the bare verb (run 27 law: 'act' substring-matches
                            // 'Interaction').
                            string pick = nonSim.FirstOrDefault(c => c.ToLowerInvariant().Contains("act.../"))
                                ?? nonSim.FirstOrDefault(c => c.Contains("verb=perform"))
                                ?? nonSim.FirstOrDefault(c => c.Contains("verb=sing"))
                                ?? nonSim.FirstOrDefault(c => c.Contains("verb=practice"))
                                ?? nonSim.FirstOrDefault(c => c.Contains("verb=dance"))
                                ?? cands.FirstOrDefault();
                            if (pick != null)
                            {
                                var objPart = pick.Split(' ')[0]; // objNNN
                                var targetObj = _vm.Entities.FirstOrDefault(e => "obj" + e.ObjectID == objPart
                                    || ("obj" + e.ObjectID) == objPart);
                                var row = int.Parse(pick.Split(' ')[1].Replace("row", ""));
                                var act = targetObj.GetAction(row, actor, _vm.Context, false);
                                if (act != null)
                                {
                                    act.Flags |= FSO.Files.Formats.IFF.Chunks.TTABFlags.FSOSkipPermissions;
                                    actor.Thread.EnqueueAction(act);
                                    _ssBookPerfPushed = true;
                                    Log("AUTOTEST ss-book pushed performance push obj=" + targetObj.ObjectID
                                        + " row=" + row + " name=\"" + act.Name + "\" uid=" + act.UID);
                                }
                                else Log("AUTOTEST ss-book push failed: GetAction null for " + pick);
                            }
                            else Log("AUTOTEST ss-book no performance-ish interaction found on lot 81");
                        }
                    }
                    if (_ssBookFrame >= _ssBookArrivedFrame + 10800)
                    {
                        Log("AUTOTEST ss-book arrival window complete (~3 sim-hours) at f=" + _ssBookFrame
                            + " fameSting=" + _ssBookFameSting + " perfPushed=" + _ssBookPerfPushed
                            + " pdDiffSims=" + _ssBookPDDiffs.Count);
                        if (_ssBookFameSting || _ssBookPDDiffs.Count > 0) Pass("ss-book"); else Fail("ss-book");
                        _ssBookDone = true;
                        Finish();
                        return;
                    }
                    return;
                }
                if (_ssBookFrame % 60 == 0 || _ssBookFrame < 5)
                {
                    // run 17 law: the fame flow spawns CarLimoWhite (0x105BCC90, via
                    // ControllerStudioLot 4134 'Make Car based on Fame') and
                    // CarStudio (0xF408F4DB, via PedMarkersStudio) — the plain cab
                    // GUID (0x6477AB64) is the non-fame path.
                    var cabs = _vm.Entities.Count(e => e.Object?.OBJ != null
                        && (e.Object.OBJ.GUID == 0x6477AB64u || e.Object.OBJ.GUID == 0x105BCC90u
                            || e.Object.OBJ.GUID == 0xF408F4DBu));
                    if (cabs > 0) _ssBookCabSeen = true;
                    var aa = _ssBookAv.Thread.ActiveAction;
                    var stack = aa?.ActionRoutine;
                    // leg-4 diagnostics: the innermost stack frames' temp registers (the
                    // EXP-04 V2.2 machine law read temps [1,13,2] steady at 4100@2) and
                    // the rest of the household's queue/active state (the pickup may
                    // gate on house-member pickup participation — 4116 'Invite House
                    // Member' exists in this plugin).
                    var tr = _ssBookAv.Thread.TempRegisters;
                    var temps = new System.Text.StringBuilder(" thread=[" + string.Join(",", tr.Take(8)) + "]");
                    var others = string.Join(",", _avatars.Where(a => a != _ssBookAv).Take(3)
                        .Select(a => "obj" + a.ObjectID + ":" + (a.Thread?.ActiveAction?.Name ?? "-")
                            + "/q" + (a.Thread?.Queue?.Count ?? 0)));
                    Log("AUTOTEST ss-book f=" + _ssBookFrame
                        + " active=" + (aa == null ? "-" : (aa.Name ?? "?") + "@" + (stack?.ID ?? 0) + ":" + (aa.Callee?.ObjectID ?? 0))
                        + " cabs=" + cabs
                        + " transit=" + _vm.TS1State.LotTransitInfo
                        + " gbd=" + (_vm.GlobalBlockingDialog == null ? "-" : "obj" + _vm.GlobalBlockingDialog.ObjectID)
                        + " inLot=" + (_screen != null && _screen.InLot)
                        + " clock=" + _vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00")
                        + " ents=" + _vm.Entities.Count
                        + " temps" + temps
                        + " spd=" + _vm.SpeedMultiplier + "/last" + _vm.LastSpeedMultiplier
                        + " avDead=" + _ssBookAv.Dead
                        + " avQ=" + (_ssBookAv.Thread?.Queue?.Count ?? -1)
                        + " avStack=" + (_ssBookAv.Thread?.Stack?.Count ?? -1)
                        + " schedIdle=" + _ssBookAv.Thread?.ScheduleIdleEnd + "/cur=" + _vm.Scheduler.CurrentTickID
                        + " async=" + _vm.FSOVAsyncLoading
                        + " ready=" + _vm.Context.Ready
                        + " mode=" + (_screen?.Frontend?.MainPanel?.Mode.ToString() ?? "?")
                        + " drvSpd=" + FSO.SimAntics.NetPlay.Drivers.VMServerDriver.AutotestDriverLastSpeed
                        + " pump[upd+" + (FSO.SimAntics.VM.AutotestPumpUpdates - (_ssBookLastUpdates < 0 ? FSO.SimAntics.VM.AutotestPumpUpdates : _ssBookLastUpdates))
                        + " tick+" + (FSO.SimAntics.VM.AutotestPumpTicks - (_ssBookLastTicks < 0 ? FSO.SimAntics.VM.AutotestPumpTicks : _ssBookLastTicks))
                        + " pumpSpd=" + FSO.SimAntics.VM.AutotestPumpLastSpeed + "]"
                        + " others=[" + others + "]");
                    _ssBookLastUpdates = FSO.SimAntics.VM.AutotestPumpUpdates;
                    _ssBookLastTicks = FSO.SimAntics.VM.AutotestPumpTicks;
                }
                var transit = _vm.TS1State.LotTransitInfo;
                bool lotSwitch = _screen != null && !_screen.InLot;
                if (transit > 0)
                {
                    Log("AUTOTEST ss-book transit=" + transit + " at f=" + _ssBookFrame);
                    _ssBookTerminal = "transit";
                }
                else if (lotSwitch)
                {
                    Log("AUTOTEST ss-book lot switch at f=" + _ssBookFrame);
                    _ssBookTerminal = "lot-switch";
                }
                // Departure-token read (the EXP-04 VACBOOK booking observable): the
                // booking chain banks Type-2 GUID-7/8 inventory tokens (departure
                // hours:minutes) on the actor's NID inventory while the pickup machine
                // keeps polling; their presence proves the booking ran end-to-end
                // headless even before any cab/departure.
                string tokens = null;
                try
                {
                    var nid = _ssBookAv.GetPersonData(VMPersonDataVariable.NeighborId);
                    var inv = FSO.Content.Content.Get().Neighborhood.GetInventoryByNID(nid);
                    if (inv != null)
                    {
                        var t7 = inv.FirstOrDefault(x => x.Type == 2 && x.GUID == 7);
                        var t8 = inv.FirstOrDefault(x => x.Type == 2 && x.GUID == 8);
                        if (t7 != null && t7.Count > 0)
                        {
                            tokens = t7.Count + ":" + (t8?.Count ?? -1);
                            _ssBookTokensSeen = true;
                            _ssBookTokH = t7.Count;
                            _ssBookTokM = t8?.Count ?? -1;
                        }
                    }
                }
                catch (Exception te) { Log("AUTOTEST ss-book token read EXC " + te.GetType().Name + " " + te.Message); }
                if (_ssBookFrame % 600 == 0 && tokens != null)
                    Log("AUTOTEST ss-book depTokens=" + tokens + " at f=" + _ssBookFrame);
                // The VACBOOK law: banked departure tokens ARE the headless booking
                // proof. The pickup machine then polls the sim clock against the
                // departure time (EXP-04 V2.1) with an equality that a live clock
                // misses once the booking minute has passed — the EXP-04 V2.2 lever
                // is to drive the clock from the autotest: arm it exactly onto the
                // banked departure minute and let the machine's next poll fire
                // ins 12 (mode-17 SignalLotSwitch(81)).
                if (_ssBookTokensSeen && !_ssBookClockArmed && _ssBookTokH >= 0 && _ssBookTokM >= 0)
                {
                    _ssBookClockArmed = true;
                    Log("AUTOTEST ss-book booking proven via departure tokens " + tokens + " at f=" + _ssBookFrame
                        + "; arming clock " + _ssBookTokH + ":" + _ssBookTokM.ToString("00")
                        + " (was " + _vm.Context.Clock.Hours + ":" + _vm.Context.Clock.Minutes.ToString("00") + ")"
                        + " — EXP-04 V2.2 lever");
                    _vm.Context.Clock.Hours = _ssBookTokH;
                    _vm.Context.Clock.Minutes = _ssBookTokM;
                    // V3: snapshot each household sim's person data (PD[0..79])
                    // pre-departure — the post-arrival diff names the fame storage.
                    foreach (var a in _avatars)
                    {
                        var pd = new short[80];
                        for (short i = 0; i < 80; i++) pd[i] = a.GetPersonData((VMPersonDataVariable)i);
                        _ssBookPD0[a.ObjectID] = pd;
                    }
                    Log("AUTOTEST ss-book PD snapshots taken for " + _avatars.Count + " sims");
                }
                // Leg-4 law (run 10 ITRACE): after booking, the pickup machine sleeps
                // at 4100 ins 3 (local 4121, operand 10000) — its thread executes
                // NOTHING for the whole watch (500 trace lines, all other entities).
                // The loop's own wake is notify_out_of_idle (op 49): RescheduleInterrupt
                // + Thread.Interrupt. The probe repeats that native wake each tick so
                // the machine's sleep boundary releases as soon as it is reachable.
                if (_ssBookClockArmed)
                {
                    _vm.Scheduler.RescheduleInterrupt(_ssBookAv);
                    _ssBookAv.Thread.Interrupt = true;
                    if (_ssBookFrame % 600 == 0)
                        Log("AUTOTEST ss-book wake armed (RescheduleInterrupt + Interrupt) at f=" + _ssBookFrame);
                }
                if (_ssBookTerminal != null)
                {
                    Log("AUTOTEST ss-book verdict terminal=" + _ssBookTerminal + " cabSeen=" + _ssBookCabSeen
                        + " answered=" + _ssBookAnswered + " depTokens=" + (tokens ?? "none")
                        + " clockArmed=" + _ssBookClockArmed);
                    // the departure proof is the mode-17 firing itself (transit or the
                    // lot switch); cabSeen is informational (the pickup may reuse the
                    // fame car instead of the plain cab).
                    // review P3: disarm the sink here too — a terminal at f<=300 must
                    // not leave residual budget emitting past Finish.
                    FSO.SimAntics.Engine.VMThread.AutotestTraceSink = null;
                    FSO.SimAntics.Engine.VMThread.AutotestInstrTraceBudget = 0;
                    _ssBookTraceArmed = false;
                    Pass("ss-book");
                    _ssBookDone = true;
                    Finish();
                    return;
                }
                if (_ssBookFrame >= 3600)
                {
                    var gbdEnd = _vm.GlobalBlockingDialog;
                    var aa2 = _ssBookAv.Thread.ActiveAction;
                    Log("AUTOTEST ss-book window closed: active=" + (aa2 == null ? "-" : aa2.Name ?? "?")
                        + " gbd=" + (gbdEnd == null ? "-" : "obj" + gbdEnd.ObjectID)
                        + " transit=" + transit + " cabSeen=" + _ssBookCabSeen + " answered=" + _ssBookAnswered
                        + " depTokens=" + (tokens ?? "none"));
                    Log("AUTOTEST ss-book verdict terminal=none (named state: "
                        + (_ssBookAnswered == 0 ? "no dialog ever raised; chain stalled at "
                            + (aa2 == null ? "queue-head" : aa2.Name)
                        : _ssBookCabSeen ? "cab spawned but never departed"
                        : _ssBookTokensSeen ? "booked (tokens " + _ssBookTokH + ":" + _ssBookTokM.ToString("00")
                            + ", clock armed=" + _ssBookClockArmed + ") but the pickup machine never fired ins 12; still polling at "
                            + (aa2 == null ? "queue-head" : aa2.Name)
                        : "answered but chain stalled at " + (aa2 == null ? "queue-head" : aa2.Name)) + ")");
                    Fail("ss-book"); _ssBookDone = true;
                    Finish();
                    return;
                }
            }
            catch (Exception ex)
            {
                Log("AUTOTEST ss-book EXC " + ex.GetType().Name + " " + ex.Message);
                Fail("ss-book"); _ssBookDone = true;
                Finish();
            }
        }

        private static void Pass(string check)
        {
            _passed++;
            Log("AUTOTEST " + check + ": PASS");
        }

        private static void Fail(string check)
        {
            _failed++;
            Log("AUTOTEST " + check + ": FAIL");
        }

        // REL-11: a skip is not a pass. Skipped checks are counted and reported in the
        // RESULT line; a run whose checks all skipped no longer prints RESULT PASS.
        private static void Skip(string check, string reason)
        {
            _skipped++;
            Log("AUTOTEST " + check + ": SKIPPED (" + reason + ")");
        }

        private static bool _nbrmgmtVerdicted;

        private static void Finish()
        {
            AutotestCamera239.CancelCaptureCheck();
            if (_pip240 != null) { _screen?.Remove(_pip240); _pip240.Dispose(); _pip240=null; }
            if (_cutaway244 != null) { _screen?.Remove(_cutaway244); _cutaway244.Dispose(); _cutaway244=null; }
            if (_finished) return;
            _finished = true;
            RestoreVisualArtifactDialogs();
            StopCareerBudgetObservation();
            StopCareerCreateObservation();
            // (R249) freewillwin safety: restore pinned state and settle the verdict on any
            // early exit (timeout / lot abort) that beats the window's own evaluation.
            if (CheckEnabled("freewillwin"))
            {
                AutotestFreeWillWin249.FinishShim("finish");
                if (!_freewillwinVerdicted)
                {
                    _freewillwinVerdicted = true;
                    if (AutotestFreeWillWin249.VerdictReady && AutotestFreeWillWin249.AllPassed) Pass("freewillwin");
                    else Fail("freewillwin");
                }
            }
            try { FSO.SimAntics.Primitives.UseNeighborLog.Summary(); } catch (Exception usl) { Log("AUTOTEST relprobe-summary EXC " + usl.GetType().Name); }
            if (AudioCheckThread != null)
                Log("AUTOTEST audio end thread=" + AudioCheckThread.GetType().Name + ":" +
                    AudioCheckThread.Name + " dead=" + AudioCheckThread.Dead);
            // NBR-02: neighborhood create/select + move-out law pin. Runs on a
            // scratch provider so the live lot VM is never unmounted; verdict is
            // settled before the summary line, like the freewillwin shim above.
            if (CheckEnabled("nbrmgmt") && !_nbrmgmtVerdicted)
            {
                _nbrmgmtVerdicted = true;
                try { if (AutotestNBRMgmt.Run()) Pass("nbrmgmt"); else Fail("nbrmgmt"); }
                catch (Exception nbrE) { Log("AUTOTEST nbrmgmt EXC " + nbrE.GetType().Name + ": " + nbrE.Message); Fail("nbrmgmt"); }
            }
            Log("AUTOTEST SUMMARY passed=" + _passed + " failed=" + _failed + " skipped=" + _skipped);
            // REL-11: PASS requires at least one verdicted check — a focused opts string
            // that names nothing (typo) or whose checks all skipped must not print PASS.
            var pass = _failed == 0 && _passed > 0;
            Log("AUTOTEST RESULT " + (pass ? "PASS" : "FAIL") + " passed=" + _passed + " failed=" + _failed + " skipped=" + _skipped + (_passed == 0 && _failed == 0 ? " (no check verdicted)" : ""));
            Console.WriteLine("AUTOTEST RESULT " + (pass ? "PASS" : "FAIL") + " passed=" + _passed + " failed=" + _failed + " skipped=" + _skipped);
            if (Config.ExitOnDone && GameFacade.Game != null)
                GameThread.NextUpdate(x => GameFacade.Game.Exit());
        }
    }
}
